# -*- coding: utf-8 -*-
"""P10 素材第 1 期 — ダンジョンと地表の基本セットを手続き生成する。

定義の置き場: （プレハブ形式）・§9（世界の構築）
段取り: P10（素材）

`tools/voxel_probe/`（捨て試作）とは別物である。試作は記録なので触らず、
書き出しの関数だけ `export_vox.py` から借りる（.vox と .jsonc の形は 1 か所で守る）。

## 作りの規律（設計書 §6）
- **無作為な表面ノイズは入れない**（±1 の凹凸で三角形が 180 倍・見た目は「腐食」）。
  質を上げるのは**構造的な凹凸**: 目地・石割り・段・帯。彫りは 1 ボクセルの深さで、
  底に暗い色を敷く（焼き込み AO と合わさって溝が影になる）
- 色は**塊ごとに 1 色**（石 1 個・板 1 枚）。ボクセルごとに散らすと greedy が効かず
  三角形が膨れる。ばらつきは塊単位で出す
- **接地層（z=0）の平面方向は縮めない**（罠 5。隣との間から背景が抜ける）。
  岩の荒々しさは上半分だけを平面で削って出す

## 向きの約束（デザイン15・2026-08-20 に痛い目を見た）
- **+y は南＝カメラ側**、+x は東、+z は上。`house_wall` の「窓は南面だけ」が
  `y1-2:y1`（y の大きいほう）へ彫っているのがその証拠である
- **戸口・門・坑口は「手前が y 大」で書く。**逆に書くと、奥の闇が幕の手前に立って
  **入口の絵が丸ごと黒い板になる**（§5.19 の穴 3 番。合成フレームでは
  「赤い帯のついた黒い戸口」に見え、`--prefab=` で 1 枚だけ描かせるまで気づかなかった）

## 大きさの約束
- 1 マス = 32 ボクセル（§5）
- 地面タイルは 32×32×2 を z=-2 に置く（天面がちょうど z=0。既存 `make_box_prefab` と同じ）
- 水・溶岩は天面を床より下げる（§9.1「床より僅かに低く」）
- 壁は高さ 32（= 1.0 マス。「揃っていることが作られた感になる」terrain_view.cpp）
- 岩盤は変種ごとに違う高さを焼く（置く側はもう sz で伸ばさない）

## 実行
```
python tools\voxel\gen_prefabs.py          # assets/voxel/ へ全部書き出す
python tools\voxel\gen_prefabs.py 名前 …  # 名前を絞って書き出す
```
"""
import importlib.util
import math
import os
import sys
import zlib

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, '..', '..'))
OUT_DIR = os.path.join(ROOT, 'assets', 'voxel')

# .vox / .jsonc の書き出しは export_vox.py のものを使う（形を決める場所を 2 つにしない）。
_spec = importlib.util.spec_from_file_location('export_vox', os.path.join(HERE, 'export_vox.py'))
_ev = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_ev)
write_vox = _ev.write_vox
write_prefab = _ev.write_prefab

# 色の名前 → 材質は palette_materials.py に 1 か所だけ置く（宣言と予備表で判断を割らない）。
_spec_pm = importlib.util.spec_from_file_location('palette_materials', os.path.join(HERE, 'palette_materials.py'))
pm = importlib.util.module_from_spec(_spec_pm)
_spec_pm.loader.exec_module(pm)

V = 32  # 1 マスのボクセル数


# ------------------------------------------------------------------- パレット
# vox_art.py と同じ流儀（名前 → 索引）。値の分離（明・中・暗）を最初から持たせる。
C = {}
PAL = {}


def reg(name, rgb):
    """**共通のパレット**へ 1 色。索引 1..254 で、ここは 2026-08-18 に埋まっている。

    ここへ足してはならない（`np.uint8` の配列に 256 以上は入らない）。新しい色は
    下の `reg_local` を使うこと。
    """
    C[name] = len(C) + 1
    PAL[C[name]] = rgb


LOCAL_BASE = 1000  #!< 意匠ごとの色の索引。書き出しで 1..255 へ詰め直される


def reg_local(name, rgb):
    """**その意匠だけの色**（2026-08-20。こう決めた——「256色のパレットは個別に分ける
    話もあるので、足らずに無理がでる場合は言って。方針を変えよう」）。

    ## なぜ足せるようになったか
    `.vox` の索引は 1〜255 だが、**パレットはファイルごと**である——`.vox` は自分の
    RGBA チャンクを持ち、描く側も**プレハブごとに 256×1 のテクスチャ**を上げている
    （`hd2d/render/voxel_renderer.cpp`）。「全プレハブ合わせて 254 色」は
    **生成器が 1 つの表を共有していただけ**の縛りで、形式にもエンジンにも根拠が無かった。
    書き出し（`export_vox._compact`）が**その 1 個で使った色だけを 1..255 へ詰め直す**ので、
    ここでは 1000 番台の索引を配ってよい。**1 個あたり 255 色**までが本当の上限である。

    ## 使うときの約束
    - **配列は `np.int16` で作る**（`np.uint8` には 1000 が入らない。NumPy が例外を出す）
    - 別名（`C[x] = C[y]`）で足りるならそちらが先。**同じ材が別の色になると町が散る**
      ——共通の表は「世界が 1 枚の絵に見える」ための資産なので、崩すのは理由があるときだけ
    """
    C[name] = LOCAL_BASE + len(LOCAL_PAL)
    LOCAL_PAL[C[name]] = rgb
    PAL[C[name]] = rgb


LOCAL_PAL = {}


reg('wall',    (118, 112, 100)); reg('wall_l',  (156, 148, 132)); reg('wall_d', (84, 78, 68))
reg('mortar',  (56, 52, 46))
reg('rock',    (126, 122, 114)); reg('rock_l',  (152, 148, 138)); reg('rock_d', (100, 96, 90))
reg('rock_dd', (74, 71, 66));    reg('band',    (110, 100, 86))
reg('mag',     (98, 58, 46));    reg('mag_d',   (66, 40, 34));    reg('mag_h',  (172, 84, 40))
reg('qz',      (204, 200, 190)); reg('qz_l',    (238, 236, 228))
reg('obs',     (40, 38, 46));    reg('obs_l',   (58, 56, 68));    reg('obs_h',  (92, 90, 112))
# 地面は**茶系**（2026-08-09 に決めた。壁の灰色と同調して見分けが付かなかった）。
reg('pav',     (138, 116, 90));  reg('pav_l',   (162, 140, 112)); reg('pav_d',  (114, 94, 72))
reg('pav_dd',  (92, 76, 58))
# 彫った底。**暗くしすぎない。**(70,58,44) にしたら亀裂が黒い虫のように見えた
# （溝は AO と影でどうせ暗くなる。素材の側で暗くすると二重に効く）。
reg('crack',   (104, 88, 68))
# 石の目（微細なむら）。**基調から離さない**（離すと「汚れ」に見える。石の斑に留める）。
reg('pav_g1',  (146, 124, 96));  reg('pav_g2',  (130, 108, 84));  reg('pav_g3', (152, 130, 102))
reg('dirt',    (124, 102, 74));  reg('dirt_l',  (142, 120, 88));  reg('dirt_d', (102, 82, 58))
reg('pebble',  (132, 128, 120))
reg('grass',   (92, 130, 60));   reg('grass_l', (114, 152, 72));  reg('grass_d', (72, 108, 50))
reg('soil',    (110, 90, 62))
reg('fl_w',    (232, 228, 214)); reg('fl_y',    (226, 198, 86));  reg('fl_r',   (200, 86, 70))
reg('wa',      (56, 96, 124));   reg('wa_l',    (86, 132, 152));  reg('wa_d',   (38, 70, 96))
reg('wa_dd',   (26, 52, 76))
reg('crust',   (46, 38, 36));    reg('crust_l', (66, 53, 47))
reg('lava_o',  (226, 122, 38));  reg('lava_y',  (250, 198, 74))
reg('timber',  (78, 54, 38));    reg('timber_l', (104, 76, 52));  reg('timber_d', (56, 39, 28))
reg('oak',     (128, 96, 62));   reg('oak_l',   (150, 116, 78))
reg('iron',    (56, 54, 58));    reg('iron_l',  (86, 84, 90))
reg('bone',    (216, 206, 184)); reg('bone_d',  (176, 164, 138))
reg('mgl',     (140, 214, 188)); reg('mgl_d',   (86, 150, 128));  reg('stem',   (198, 198, 178))
reg('mbr',     (152, 106, 64));  reg('mbr_d',   (112, 78, 50))
reg('fl_core', (252, 216, 100)); reg('fl_mid',  (240, 142, 50));  reg('fl_edge', (212, 88, 32))
reg('moss',    (88, 112, 58));   reg('moss_d',  (66, 88, 46))
# 木（P10 レビュー 2）。葉は**塊ごとに 1 色**なので 4 段あれば足りる。
reg('bark',    (74, 54, 38));    reg('bark_l',  (100, 76, 54))
reg('leaf_d',  (42, 70, 42));    reg('leaf_m',  (62, 98, 50))
reg('leaf_l',  (88, 128, 60));   reg('leaf_h',  (118, 156, 78))
reg('dark',    (16, 15, 17))
# 町（P10 第 2 期。設計書 §10）。**壁と屋根は別のプレハブ**にしてあるので、
# 敷地ごとの色替えを漆喰と瓦で独立に掛けられる（インスタンス色はプレハブ単位）。
reg('plas',    (206, 196, 176)); reg('plas_l',  (226, 218, 200)); reg('plas_d', (176, 166, 146))
#! 屋根は**板張り**（2026-08-09 に決めた「板張りでムラがあり、ところどころから
#! 草が生えているような風合いに」）。瓦（tile_*）から差し替えた。
reg('shin',    (128, 100, 70));  reg('shin_l',  (152, 122, 88));  reg('shin_d', (100, 76, 52))
reg('shin_g',  (118, 108, 92))   # 日に灼けて灰がかった板
reg('ridge',   (84, 62, 42))
reg('glass',   (48, 56, 70));    reg('glass_l', (72, 84, 102))
reg('lit',     (252, 216, 140))  # 窓の灯り。自発光は置く側がインスタンスで足す
# 前庭の地面。**街路（茶の敷石）より暗く**する。明るいと空き地のほうへ目が行き、
# 「柵で囲った空き地の町」に見えた（実機の絵で気づいた）。主役は建物である。
reg('gravel',  (118, 110, 96));  reg('gravel_l', (138, 130, 114)); reg('gravel_d', (96, 89, 78))
reg('hay',     (214, 186, 106)); reg('hay_d',   (172, 146, 74))
reg('mrl',     (96, 92, 84))     # 城壁の狭間（本体より暗い石）
# 丸太（辺境の塀とやぐら）。**木口（切り口）は樹皮より明るい**ので別に持つ。
reg('log',     (108, 82, 54));   reg('log_l',   (132, 104, 72));  reg('log_d',  (84, 62, 40))
reg('log_end', (146, 116, 78));  reg('lash',    (70, 58, 44))     # 木口 / 縄
# 短い草と踏み固めた土（辺境の町の地面。2026-08-09 に決めた）。
reg('turf',    (96, 116, 62));   reg('turf_l',  (116, 138, 74));  reg('turf_d', (76, 94, 50))
reg('pack',    (128, 108, 82));  reg('pack_l',  (148, 128, 100)); reg('pack_d', (106, 88, 66))
reg('grit',    (140, 132, 118))
# 看板の絵（アイコン）。**塊ごとに 1 色**（罠 38）。
reg('steel',   (196, 202, 212)); reg('steel_d', (150, 156, 168))
reg('gold',    (222, 178, 62));  reg('gold_d',  (176, 132, 40))
reg('cloth',   (206, 198, 182)); reg('cloth_d', (156, 146, 128))
reg('sky',     (110, 158, 196)); reg('crimson', (168, 56, 52))
reg('board',   (104, 76, 48));   reg('board_l', (132, 100, 66));  reg('board_d', (80, 58, 36))
reg('ink',     (48, 36, 28))     # 板に塗った濃い塗料。**板の色と紛れないこと**が要件
# ---- 町ごとの意匠（P10 第 2 期レビュー 3。2026-08-09 に決めた「街ごとの雰囲気の変化」）----
# **辺境の地の色は 1 つも触らない。**上の一式がそれで、実機で見て閉じている。
#
# テルモラ = 木骨漆喰＋藁葺き（人間の領主が治める、運河と畑つきの城塞街）。
reg('straw',   (196, 166, 96));  reg('straw_l', (222, 196, 130)); reg('straw_d', (158, 130, 70))
reg('straw_g', (168, 154, 106))  # 灰がかって古びた藁
reg('beam',    (68, 48, 32));    reg('beam_l',  (96, 70, 48))     # 木骨。**漆喰との明度差で読ませる**（罠 74）
reg('rub',     (124, 118, 106)); reg('rub_l',   (148, 142, 128)); reg('rub_d',   (98, 93, 84))
reg('cream',   (216, 204, 178)); reg('cream_l', (234, 226, 204)); reg('cream_d', (184, 172, 148))
# モリバント = 切石＋漆喰＋瓦（多種族の都。中央に噴水のある大きな城塞街）。
reg('ash',     (152, 148, 138)); reg('ash_l',   (178, 174, 162)); reg('ash_d',  (122, 119, 110))
reg('joint',   (94, 91, 84))     # 目地。**彫りの底の色**（溝は幾何が暗くする＝罠 44）
reg('tile',    (140, 96, 74));   reg('tile_l',  (168, 120, 92));  reg('tile_d',  (108, 74, 56))
reg('tile_b',  (98, 102, 118))   # 葺き替えの新しい列（青みがかった瓦）
reg('flag',    (148, 144, 134)); reg('flag_l',  (170, 166, 154)); reg('flag_d',  (122, 118, 110))
reg('cob',     (126, 120, 110)); reg('cob_l',   (148, 142, 130)); reg('cob_d',   (102, 97, 90))
# 噴水の水（レビュー 4）。**空の色ではなく白い泡で読ませる**——見下ろすカメラでは
# 水そのものは背景と紛れるが、砕けた白い飛沫は石の上でも読める。
reg('foam',    (236, 244, 250)); reg('spray',   (198, 222, 240)); reg('jetwa',  (140, 190, 218))
# ススキ（テルモラの平地）。**穂は葉より明るく、灰がかっている**のが読みの決め手。
reg('plume',   (218, 210, 184)); reg('plume_d', (188, 178, 152)); reg('stalk',  (128, 142, 78))
reg('stalk_d', (104, 118, 62))
# ---- 岩山と高山植物（P10 第 3 期。2026-08-10 に決めた。ズル＝山の中の町）----
# **岩盤（`rock_*`）とは別に持つ。**岩盤は地下の壁で、こちらは空の下の山なので、
# 同じ灰色でも鉄気の褐色を混ぜて日に灼けた岩にする（並べたときに地下と混ざらない）。
reg('crag',    (134, 126, 114)); reg('crag_l',  (164, 156, 142)); reg('crag_d',  (106, 100, 90))
reg('crag_dd', (80, 75, 68));    reg('crag_b',  (124, 108, 88))   # 層理の帯（鉄気の褐色）
reg('lichen',  (144, 150, 116))  # 地衣。**苔より灰がかっている**のが岩の上の読み
reg('alp',     (76, 106, 64));   reg('alp_d',   (54, 80, 48));    reg('alp_l',   (102, 132, 78))
reg('alp_fw',  (238, 238, 228)); reg('alp_fy',  (232, 202, 92));  reg('alp_fr',  (188, 72, 62))
# ---- 溶岩の泡とガス（2026-08-10 に決めた）----
# 泡は**溶岩そのものが膨らんだもの**なので、皮（`crust`）ではなく熔けた色で作る。
# ガスは硫黄がかった灰色。置く側が地形の自発光を乗せるので、**素の色は明るくしない**
# （明るい灰に自発光を足すと白く飛んで湯気に見える）。
reg('bub',     (236, 132, 44));  reg('bub_l',   (252, 206, 96));  reg('bub_d',   (190, 82, 28))
# ガスは**青みの灰**にしてある。置く側が乗せる自発光は赤が強い（2.10, 0.72, 0.22）ので、
# 素で暖色の灰にすると桜色の綿になった（実機の絵で見つけた）。青みで打ち消して煙に戻す。
reg('gas',     (104, 110, 118)); reg('gas_d',   (78, 84, 92));     reg('gas_y',   (128, 132, 136))
# ---- 巣とゴミ（P10 第 4 期。2026-08-10 に決めた。イークの洞穴とオークの洞窟）----
# 藁（`straw_*`）・骨（`bone_*`）・布（`cloth_*`）・鉄（`iron_*`）は**既にあるものを使う**。
# 足すのは「汚れ」の側だけ——町の素材は洗ってあるので、そのままだと巣が小綺麗に見える。
reg('char',    (38, 34, 32));    reg('char_l',  (58, 52, 48))      # 消し炭。**灰ではなく炭**（火は消えている）
reg('fur',     (108, 84, 60));   reg('fur_d',   (80, 62, 44));     reg('fur_l',   (136, 110, 82))
reg('rust',    (128, 74, 44));   reg('rust_d',  (96, 54, 32))      # 錆。**鉄（`iron`）と並べて初めて「傷んだ」に見える**
reg('rag',     (118, 106, 88))   # 汚れた布。`cloth`（206,198,182）は洗った布なのでゴミに使えない
reg('rot',     (96, 100, 62))    # 腐った食べかす。黄緑がかった灰
# ---- 大理石（城。2026-08-10 に決めた「城は大理石をイメージした白系の壁と床に」）----
# **白い石に黒い目地は強すぎる。**切石（`ash`＋`joint`）の流儀のまま色だけ白くすると、
# 目地が黒い格子になって石より目立つ。目地も明るい灰にして、主役を面に戻す。
reg('marb',    (230, 228, 222)); reg('marb_l',  (244, 243, 238)); reg('marb_d', (204, 202, 196))
#! 脈。**青みの灰**（暖色にすると汚れに見える）。**白との差を詰める**のが要件で、
#! (158,158,164) で 1 マスに 2〜4 本引いた版は貫入ではなく**ひび割れ**に見えた。
reg('marb_v',  (192, 192, 199))
reg('marb_j',  (176, 174, 168))  # 目地
reg('marb_g',  (150, 148, 144)); reg('marb_gd', (118, 116, 114))  # 灰大理石（腰石と躯体）
# ---- ダンジョンごとの小物（P10 第 4 期の後半。残り 18 本）----
# **既にある色で足りるものは足さない。**骨・鉄・錆・金・石英・布・木・葉は上の一式を使う。
reg('web',     (222, 226, 230))  # 蜘蛛の巣。**白い糸**（灰にすると埃に見える）
reg('snow',    (238, 242, 248)); reg('snow_d',  (206, 214, 226))
reg('sulf',    (214, 196, 72));  reg('sulf_d',  (168, 150, 48))   # 硫黄
reg('tent',    (86, 104, 72));   reg('tent_d',  (62, 76, 54))     # 触手の彫刻・粘液
reg('cloud',   (238, 240, 246)); reg('cloud_d', (212, 216, 228))
reg('verd',    (96, 142, 118))   # 緑青。沈んだ金属と古い銅の飾り
reg('coin',    (206, 168, 60))   # 溶けかけた金貨（`gold` より鈍い）
# ---- 第 5 期の意匠（P10。2026-08-11。A 系統に残っていた 4 本）----
# 擬態（カメレオン洞 18）。**石を足しすぎない**——擬態は「まわりの材を真似る」ことなので、
# 岩・土・苔は既にあるものを混ぜる。足すのは「真似そこねた」側の 3 色と瞳だけ。
reg('mim',     (112, 122, 96));  reg('mim_d',   (86, 96, 74))     # 色相のずれた岩（緑へ寄る）
reg('mim_s',   (146, 134, 104))  # 砂へ寄った岩
reg('iris',    (198, 156, 54))   # 瞳の虹彩。**`gold` より鈍く**（金属に見せない）
# 暗闇の洞窟（19）。**黒にはしない。**光を吸うのは「彩度と明度が低い」ことで言う
# ——真っ黒にすると `DARKNESS`（コアが部屋の `GLOW` を潰す）と掛け算になって形が消える。
reg('murk',    (78, 76, 84));    reg('murk_l',  (106, 104, 114)); reg('murk_d',  (58, 57, 64))
reg('murk_dd', (42, 41, 47))
reg('soot',    (62, 60, 62));    reg('soot_l',  (86, 84, 86))     # 積もった煤
# 封じ（反魔法 16 ／ 反攻撃 17 で**共有**）。**磨いた一枚岩**（切石の石割りを持たない）。
# 印は彫るだけで光らせない（案「反魔法は光らないことで語る」）。
reg('ward',    (108, 106, 112)); reg('ward_l',  (132, 130, 136)); reg('ward_d',  (86, 84, 90))
reg('ward_j',  (66, 65, 70))     # 彫った印の底
# ---- 第 6 期（P10。2026-08-11。B〜G 系統の材と、案に残っていた小物）----
# **足すのは 6 家族だけ**にしてある。骨・鉄・錆・金・硝子・布・木・藁・炭・溶岩は
# 上の一式で足りる（罠 113 の裏返しで、**色を足す前に既にある色を数える**）。
#
# 竜の住みか（5）。**熱で焼けた岩**。既定の花崗岩（`rock_*`）との差は「褐色に灼けている」
# ことで、岩山（`crag_*`）の日灼けとは別物——あちらは日光、こちらは炎である。
reg('lair',    (112, 92, 76));   reg('lair_l',  (140, 118, 96)); reg('lair_d',  (86, 70, 58))
reg('lair_dd', (64, 52, 44))
# 墓地（6）。**苔と水染みの石灰岩**。切石（`ash`）より黄ばみ、目地は苔で埋まっている。
reg('tomb',    (150, 146, 132)); reg('tomb_l',  (174, 170, 156)); reg('tomb_d', (122, 118, 106))
reg('tomb_j',  (92, 89, 82));    reg('damp',    (104, 112, 104))  # 水が伝った筋
# 火山（8）。**気泡だらけの黒い岩**（スコリア）。黒曜石（`obs`）は磨いた面、こちらは粗い面。
reg('sco',     (74, 64, 60));    reg('sco_l',   (100, 88, 82));  reg('sco_d',   (54, 47, 44))
# 地獄（9）。**熱を持ったままの岩**。割れ目から下の火が透ける（`mag_h` を底に敷く）。
reg('emb',     (88, 58, 48));    reg('emb_l',   (120, 78, 60));  reg('emb_d',   (62, 40, 34))
# 天界（10）。**真珠層**。大理石（`marb`）より青く冷たい——同じ白でも石と貝で分かれる。
reg('nacr',    (222, 226, 240)); reg('nacr_l',  (240, 242, 250)); reg('nacr_d', (196, 202, 222))
# 水没した遺跡（11）。**積もった泥**。水そのものは表が敷くので、こちらは底に溜まったもの。
reg('silt',    (104, 110, 98));  reg('silt_l',  (126, 132, 116)); reg('silt_d', (84, 90, 80))
# ルルイエ（13）。**玄武岩の巨石**。灰に青緑を差す（水の底で長く沈んでいた石）。
reg('cyc',     (88, 94, 96));    reg('cyc_l',   (112, 118, 120)); reg('cyc_d',  (68, 73, 76))
reg('cyc_j',   (50, 54, 57))
# 小物で要る 4 色。**それ以外は既存で足りる。**
reg('wilt',    (122, 110, 84));  reg('wilt_d',  (96, 86, 66))     # 枯れた茎（明・暗）
reg('wilt_p',  (152, 126, 118))  # 色の抜けた花びら
reg('cor',     (188, 116, 110)); reg('cor_l',   (214, 148, 140)); reg('cor_d',  (150, 88, 84))
reg('clay',    (166, 116, 82));  reg('clay_d',  (132, 90, 62))    # 素焼きの壺
reg('slime',   (116, 148, 84));  reg('slime_l', (146, 178, 104))  # 緑の粘液（`tent` は彫刻の色）
# ---- ガラスの扉とカーテン（2026-08-11。「ガラス扉も東西では 90° 回す」と決めた）----
#! **色は必ず末尾へ足すこと。**`reg()` は登録順に番号を振るので、途中へ挿すと以降の
#! 索引が全部ずれる。.vox はパレットを丸ごと抱えているので既存の絵は壊れないが、
#! **次にその素材を作り直したときだけ中身が変わる**＝差分が「触っていない素材」に出る。
#
# 硝子の板。**`glass`（48,56,70）を使わない**——あれは城の暗い硝子で、暗い壁の前では
# 影と見分けが付かない（`glass_sconce` の注記と同じ話）。扉は「向こうが見えるほど薄い」
# ことを**明度**で言うしかないので、冷たい明るい青にして桟（`steel_d`）で割る。
reg('pane',    (150, 178, 196)); reg('pane_l',  (206, 226, 236)); reg('pane_d', (110, 136, 156))
# 帳（カーテン）。**扉と同じ赤系にしない**——樫（`oak`）と並ぶので、布は彩度で分ける。
reg('drape',   (132, 62, 70));   reg('drape_l', (170, 90, 98));   reg('drape_d', (94, 42, 50))
# 全体マップの町の屋根。**町の瓦（`tile` = 140,96,74）では茶色すぎる**——広域マップの
# 地色は草・岩・水で、暖色が 1 つも無い。この縮尺で「町だ」と言うのは形ではなく色なので、
# 目印用にもう一段赤い瓦を持つ（町の中の建物には使わない。あちらは決着している）。
reg('roof_r',  (170, 76, 56));   reg('roof_rl', (202, 108, 82));  reg('roof_rd', (128, 52, 38))
# ---- 永久壁の割れ（2026-08-13。「色合いはこのままに凹凸クラックを入れて」と決めた）----
# 黒曜石の**割れの底**。既存の 3 色（`obs` / `obs_l` / `obs_h`）はどれも面の色なので、
# 彫った溝を暗く沈める段が無かった。`dark` を使わないのは、あれが暗闇の洞窟の材で、
# 黒曜石より青みが無いため——同じ黒でも材が違うと**割れが「汚れ」に見える**。
reg('obs_d',   (26, 25, 32))
# ---- 和風の門（2026-08-17。幻想蛮怒の町。「変愚の話なので幻想では変えていく」と決めた）----
# **末尾に足すこと。**`reg` は `len(C)+1` で採番するので、途中に挿すと既存の板の色が全部ずれる。
# 藍は暖簾の地。**黒に寄せない**——遠目で「暗い穴」に見えて口が塞がったように読める。
reg('ai',      (44, 68, 108));   reg('ai_l',    (66, 96, 140));   reg('ai_d',   (28, 44, 74))
reg('nuki',    (234, 230, 220))  # 白抜き（屋号の抜き。この縮尺では字にならないので帯で出す）
reg('sugi',    (72, 58, 46));    reg('sugi_l',  (98, 82, 64))     # 杉皮の庇
# ---- 人里の意匠（2026-08-18。決めたこと Q3/Q4「意匠は 3 町だけ・人里から」）----
#
# **色はもう 1 つも足せない。** `.vox` の索引は 1〜255 で、ここまでで 254 使い切っている
# （和風の門で 254 に達した）。10 色足したら索引が 256〜265 になり、`np.uint8` へ入れた瞬間に
# **巻き戻って別の色になる**（NumPy が「cast overflows」と警告する。実際に踏んだ）。
#
# だから人里の材は**既にある色を組み替えて**作る。下は**別名だけ**で、指す先は既存の索引
# ——`reg` を呼ばないので 1 枠も消費しない。**テルモラの藁より鈍く褐色**に寄せてあるので、
# 並べれば別の材に読める（藁は葺きたての黄、茅は枯れた褐色）。
for _alias, _base in (
    ('kaya', 'straw_d'), ('kaya_l', 'hay_d'), ('kaya_d', 'mbr_d'), ('kaya_g', 'shin_g'),
    ('mune', 'bark'),  # 棟押さえの竹と丸太（**芝棟にしない**——あれはテルモラの癖）
    ('yaki', 'timber_d'), ('yaki_l', 'timber'),  # 焼杉の腰板
    ('tsuchi', 'plas_l'), ('tsuchi_d', 'plas_d'),  # 土壁
    ('shoji', 'qz_l'),  # 障子。壁より明るい（夜の灯は置く側がインスタンスで足す）
):
    C[_alias] = C[_base]

# ---- 天狗の里の意匠（2026-08-18。Q3 の 2 つめ）----
# 同じく**別名だけ**（パレットは満杯。`reg` を呼ばないので 1 枠も消費しない）。
# 白漆喰は城の大理石の白を借りる——あちらは磨いた石、こちらは塗った漆喰だが、
# 城は変愚の目印なので幻想蛮怒の町と同じ画面に並ぶことは無い。
# 杉皮は和風の門の庇（`sugi`）と同じ材——天狗の里の屋根は §4.4 の「檜皮・杉皮の墨灰茶」。
for _alias, _base in (
    ('shira', 'marb'), ('shira_l', 'marb_l'), ('shira_d', 'marb_d'),  # 白漆喰
    ('hiwada', 'sugi'), ('hiwada_l', 'sugi_l'), ('hiwada_d', 'char_l'),  # 杉皮葺き
    ('hiwada_g', 'shin_g'),  # 灰がかって古びた杉皮
    #! 檜皮の赤み（デザイン8。永遠亭の大屋根。`hiwada_l` と交互に葺くと層が読める）。
    ('hiwada_r', 'mbr_d'),
):
    C[_alias] = C[_base]

# ---- 旧地獄街道の意匠（2026-08-18。Q3 の 3 つめ＝意匠はこれで打ち止め）----
# 同じく**別名だけ**（パレットは満杯）。§4.4「黒い町屋＋橙の提灯の列・背景は岩」。
# 下見板は人里の焼杉（timber_d）と同じ焦茶を地にして、**白漆喰を 1 面も使わない**
# ——天狗の里との一番効く差はここにある（§4.4 ②）。瓦の黒は黒曜石の藍黒を借りる
# （char の炭色より青みがあり、いぶした瓦の照りに読める）。提灯は溶岩の泡の橙
# ——地底の絵どうしなので、灼熱地獄跡の照り返し（§4.4 ⑥）と色が喧嘩しない。
for _alias, _base in (
    ('shitami', 'timber_d'), ('shitami_l', 'board_d'), ('shitami_d', 'char'),  # 下見板
    ('kawara', 'obs'), ('kawara_l', 'obs_l'), ('kawara_d', 'obs_d'),  # 黒瓦
    ('kawara_g', 'murk_l'),  # 棟のいぶし銀
    ('chochin', 'bub'), ('chochin_l', 'bub_l'),  # 提灯の紙（昼から橙。灯は別体で足す）
    ('koshi', 'rust'),  # 格子（紅殻。歓楽街の窓の暖かさ）
):
    C[_alias] = C[_base]

# ---- 博麗神社の意匠（2026-08-19 デザイン6）----
# 同じく**別名だけ**（パレットは満杯）。朱は広域マップの赤瓦（roof_r）を借りる——
# あちらの「町の建物には使わない」は変愚の閉じた絵を動かさないための約束で、
# 幻想蛮怒の鳥居は新しい板である。Q2 の決定「朱にするのは鳥居だけで、社殿は素木のまま」。
# 桜は珊瑚の桃色（cor）＋大理石の白。屋根は人里の茅（kaya）をそのまま使う。
for _alias, _base in (
    ('shu', 'roof_r'), ('shu_l', 'roof_rl'), ('shu_d', 'roof_rd'),  # 朱（古びた朱 §4.2 ②）
    ('hana', 'cor_l'), ('hana_d', 'cor'), ('hana_w', 'marb_l'),     # 桜の花
):
    C[_alias] = C[_base]

# ---- 河童のバザーの意匠（2026-08-19 デザイン7）----
# 同じく**別名だけ**（パレットは満杯。`reg` を呼ばないので 1 枠も消費しない）。
# §4.4「外せない 1 点 ＝ **錆びた波トタンの片流れ＋崖の六角柱の縦縞**。背景に水と横断する配管」。
#
# 玄武岩はルルイエの巨石（`cyc_*`。「灰に青緑を差す」）をそのまま借りる——**玄武の沢は
# 溶岩が冷え固まった六角柱**（儚月抄）で、材としてはあれがいちばん近い。ダンジョン 13 番と
# 同じ画面に並ぶことは無い。トタンは看板の鋼（`steel_*`）と切石の灰（`ash_*`）、錆は巣の
# `rust_*`、配管の緑青は `verd`（既にそのものの名前で在る）、幕の藍は暖簾の `ai_*`、
# 胡瓜と発光苔は粘液（`slime_*`）と光る茸（`mgl_*`）。
for _alias, _base in (
    ('genbu', 'cyc'), ('genbu_l', 'cyc_l'), ('genbu_d', 'cyc_d'), ('genbu_j', 'cyc_j'),  # 玄武岩
    ('tin', 'steel_d'), ('tin_l', 'steel'), ('tin_d', 'ash_d'), ('tin_g', 'ash'),  # 生トタン
    ('pipe', 'verd'), ('pipe_d', 'tent_d'),  # 緑青の配管
    ('kyuri', 'slime'), ('kyuri_l', 'slime_l'),  # 胡瓜
    ('koke', 'mgl'), ('koke_d', 'mgl_d'),  # 発光苔（沢の岩肌。日当たりが悪い）
    ('bulb', 'lit'),  # 裸電球（灯は置く側がインスタンスで足す）
):
    C[_alias] = C[_base]

# ---- 香霖堂の意匠（2026-08-19 デザイン9）----
# 同じく**別名だけ**（パレットは満杯。`reg` を呼ばないので 1 枠も消費しない）。
# §4.1「外せない 1 点 ＝ **入母屋の店舗＋白い土蔵が渡り廊下でつながった 2 棟**」。
#
# 瓦は**いぶし銀の桟瓦**（§4.1 ②）。旧地獄街道の黒瓦（`kawara`＝黒曜石の藍黒）とは
# 別の段を借りて、灰褐色に寄せる——同じ「瓦の町」を 2 つ作らないための差である。
# 白漆喰は天狗の里と同じ大理石の白（`shira` と同じ指し先）だが、こちらは**壁いっぱい**に
# 塗る材なので、名前を土蔵のものとして持つ。なまこ壁の黒は消し炭（`char`）。
# 洋風の扉の濃茶は焼杉より明るい `timber_l`、真鍮は看板の金（`gold`）。
for _alias, _base in (
    # 桟瓦。**明るい側の灰**を地にする——大屋根は見下ろすと自分の影に入りやすく、
    # 暗い灰（murk 78,76,84）を地にしたら合成フレームで**黒い板**になった（実測）。
    ('sanga', 'ash_d'), ('sanga_l', 'ash'), ('sanga_d', 'murk'), ('sanga_g', 'cyc_d'),
    ('kura_w', 'marb'), ('kura_wl', 'marb_l'), ('kura_wd', 'marb_g'),  # 土蔵の白漆喰
    ('namako', 'char'), ('namako_l', 'char_l'),  # なまこ壁の黒瓦
    ('door_w', 'timber_l'), ('door_wd', 'timber_d'),  # 洋風の開き戸（濃茶）
    ('brass', 'gold'), ('brass_d', 'gold_d'),  # 真鍮のノブと蝶番
):
    C[_alias] = C[_base]

# ---- 命蓮寺の意匠（2026-08-19 デザイン10）----
# 同じく**別名だけ**（パレットは満杯）。§4.2「外せない 1 点 ＝ **灰の瓦屋根と赤い幟の列、
# そして鳥居を置かないこと**」。瓦は香霖堂で作った灰（`sanga`）をそのまま——神社 2 件を
# 茅・檜皮の暖色にしてあるので、**瓦の冷たい灰だけで「寺」と読める**（§4.2 ①）。
# 白壁は土蔵と同じ大理石の白（3 件で最も明るい建物にする）。赤い幟は看板の緋
# （`crimson`）で、朱（`shu`＝博麗の鳥居）とは**別の赤**にしてある——幟は布、朱は塗り。
for _alias, _base in (
    ('myo_w', 'marb'), ('myo_wl', 'marb_l'), ('myo_wd', 'marb_g'),  # 白壁と築地塀
    ('nobori', 'crimson'), ('nobori_d', 'cor_d'),  # 赤い幟（布）
    ('kane', 'cyc_j'), ('kane_l', 'murk_l'),  # 梵鐘
    ('ishi', 'flag'), ('ishi_l', 'flag_l'), ('ishi_d', 'flag_d'),  # 石畳・石仏・石段
):
    C[_alias] = C[_base]

# ---- 霧雨魔法店の意匠（2026-08-19 デザイン11）----
# 同じく**別名だけ**（パレットは満杯）。§4.1「外せない 1 点 ＝ **急勾配の尖った洋風屋根**。
# 瓦や入母屋を持ち込むと香霖堂と、低い寄棟にすると里の民家と即座に混ざる」。
# 屋根は**赤錆の板葺き**（§4.1 ②「暗色（深い青灰か赤錆）。**瓦のいぶし銀は使わない**」）
# ——3 つめの灰の瓦を作らないための選択である。壁は褪せた板張りで、蔓は苔の緑を借りる。
for _alias, _base in (
    ('kir_b', 'board_l'), ('kir_bl', 'cream_d'), ('kir_bd', 'board_d'),  # 褪せた横板張り
    ('kir_r', 'rust'), ('kir_rl', 'mbr'), ('kir_rd', 'rust_d'),  # 赤錆の板葺き
    ('vine', 'moss'), ('vine_d', 'moss_d'),  # 壁に絡む蔓
):
    C[_alias] = C[_base]

# ---- 魔法の森の 2 軒（デザイン11 その2・2026-08-20）----
# アリスの家（`_ari`）と森の幽霊洋館（`_yur`）。**同じ洋館で、違うのは手入れの有無**
# なので、色だけを 2 組にして型は共有する。魔法店（褪せた板張り＋赤錆）とは
# **白い下見板＋青灰のスレート**で分かれ、朽ちた側は**彩度を落として緑を差す**
# ——明度だけで振ると「日陰の同じ家」に見える（罠 74 の逆）。
#
# **ここが `reg_local` の 1 例目**（2026-08-20 に決めた）。初版は別名で組んだが、
# 借り物では**アリスの青が水の青（56,96,124）で暗く鈍く**、塗り直しの白が大理石の白に
# なっていた。意匠ごとのパレットに切り替えて、欲しい色をそのまま置いた。
for _name, _rgb in (
    # 白い下見板。塗った板の白（大理石の白より暖かく、生成りより白い）
    ('ari_b', (238, 236, 230)), ('ari_bl', (250, 250, 246)), ('ari_bd', (206, 204, 196)),
    # 青い鎧戸・窓枠。**矢車菊寄りの青**——人形師の家の青で、水の青ではない
    ('ari_s', (72, 108, 176)), ('ari_sl', (112, 152, 214)), ('ari_sd', (44, 70, 124)),
    # 青灰のスレート（石板葺き）
    ('ari_r', (104, 116, 138)), ('ari_rl', (136, 150, 174)), ('ari_rd', (68, 78, 96)),
    # 灰に褪せた下見板（同じ板が塗料を失った姿。**色相はアリスと同じ**で彩度だけ落とす）
    ('yur_b', (128, 124, 114)), ('yur_bl', (152, 148, 138)), ('yur_bd', (96, 92, 84)),
    # 苔むした暗いスレート
    ('yur_r', (86, 94, 96)), ('yur_rl', (110, 118, 118)), ('yur_rd', (54, 60, 62)),
):
    reg_local(_name, _rgb)


# ---- 廃洋館の意匠（デザイン12・2026-08-20）----
# §4.3 の「ボクセル」欄がそのまま指定になっている数少ない町である——
# ②壁＝退色した灰白 `#A8A49B` ／屋根＝色の抜けた青灰 `#5A6470`（**紅魔館の赤の真逆**）、
# ③窓は黒く抜く `#1C1E22`・**灯を入れない**、④蔓 `#4A6B3C`。
# **借り物では出せない**（灰白は大理石の白より暗く土壁より冷たい・青灰は蒸気の灰より青い）
# ので、意匠ごとのパレット（`reg_local`）で指定の値をそのまま置く。
for _name, _rgb in (
    # 退色した灰白の切石（§4.3 ② の指定値）
    ('hai_w', (168, 164, 155)), ('hai_wl', (196, 192, 182)), ('hai_wd', (124, 120, 112)),
    # **黒く抜けた窓**（同 ③）。灯りの色は 1 つも作らない
    ('hai_k', (28, 30, 34)),
    # 色の抜けた青灰のスレート（同 ②）
    ('hai_r', (90, 100, 112)), ('hai_rl', (118, 128, 140)), ('hai_rd', (60, 68, 78)),
    # 蔓（同 ④）。魔法の森の苔（`vine`）より濃く青い——ここは常緑の蔦である
    ('hai_v', (74, 107, 60)), ('hai_vd', (52, 78, 44)),
    # 陸屋根の鉛板（マンサールの頂）
    ('hai_l', (122, 124, 128)), ('hai_ll', (150, 152, 156)), ('hai_ld', (92, 94, 100)),
    # 錆びた鉄（門扉・柵・棟飾り）
    ('hai_ru', (120, 74, 48)), ('hai_rud', (84, 50, 34)),
    # 吹き溜まった落ち葉
    ('hai_lf', (112, 86, 52)),
):
    reg_local(_name, _rgb)


def rng_for(name):
    """プレハブ名から決める乱数器。**同じ名前なら毎回同じ形**（差分が読める）。

    種は `zlib.crc32` から採る。**`hash()` を使ってはならない。**Python 3 の str の
    ハッシュはプロセスごとに撹拌されるので（PYTHONHASHSEED）、同じ名前でも実行のたびに
    別の形が出る。初版はこれで、再生成のたびにボクセル数が変わっていた（§3 罠 43）。
    変種（`wall_stone_07` など）の作り分けも名前の違いだけで足りる。
    """
    return np.random.default_rng(zlib.crc32(name.encode('utf-8')) + 7)


# --------------------------------------------------------------- 地面のタイル
def _tile(h=2):
    """32×32×h の板。z=0 が底（origin_z=-h で天面がちょうど地面になる）。"""
    return np.zeros((V, V, h), np.uint8)


def _mottle(rng, layer, shades, weights):
    """塊単位のむら。2×2 の塊で塗る（1 ボクセル単位だと greedy が効かない）。"""
    hx = (V + 1) // 2
    pick = rng.choice(shades, size=(hx, hx), p=weights)
    big = np.repeat(np.repeat(pick, 2, axis=0), 2, axis=1)
    layer[:, :] = big[:V, :V]


def _grain(rng, layer, mask, shades, weights, block=2):
    """**微細なむら**（2026-08-09 に決めた「もっと微細なムラでリアリティのある石タイル感」）。

    `mask` が真の所だけを `block`×`block` の塊で塗り替える。既にある明暗の上へ重ねるので、
    敷石ごとの色差（大きな単位）と石の目（細かい単位）の 2 段になる。
    **1 ボクセル単位にはしない**（greedy が効かなくなり、四角形が塊数ぶんそのまま増える）。
    """
    n = (V + block - 1) // block
    pick = rng.choice(shades + [0], size=(n, n), p=weights + [1.0 - sum(weights)])
    big = np.repeat(np.repeat(pick, block, axis=0), block, axis=1)[:V, :V]
    hit = mask & (big > 0)
    layer[hit] = big[hit]


FLOOR_H = 4  #!< 床タイルの厚み（ボクセル）。**亀裂を彫る深さのぶん厚くしてある**


def _lump_face(rng, layer, shades, weights, span=(3, 10), count=80):
    """天面を**大きさも位置もばらばらの矩形**で塗る（P10 第 4 期）。

    `_mottle` / `_grain` は 2×2 の格子で塗るので、寄ると**砂粒の斑**に見える
    （「砂地の点描」＝罠 38）。かといって塊を大きなマス目に揃えると
    今度は**格子**に見える（罠 99。岩肌の壁で 1 度踏んだ）。

    **重ねた矩形なら、塊でありながら揃わない。**縁が互いを切るので、
    出来上がるのは市松ではなく岩の割れ目になる。
    """
    layer[:, :] = shades[0]
    for _ in range(count):
        w = int(rng.integers(*span))
        d = int(rng.integers(*span))
        x = int(rng.integers(-3, V - 1))
        y = int(rng.integers(-3, V - 1))
        layer[max(0, x):x + w, max(0, y):y + d] = rng.choice(shades, p=weights)


def floor_room(name):
    """部屋の床 — 大判の敷石。

    | 段 | 何 |
    |---|---|
    | 目地 | 天面から **1 段**彫る（底は暗い色。AO が溝の影を作る） |
    | 亀裂 | 天面から **2 段**彫る（2026-08-09 に決めた「亀裂は色ではなくボクセルのへこみで」） |
    | 欠け | 敷石の角を 1〜2 段落とす |

    彫りの深さを持たせるために厚みは `FLOOR_H`。**接地面（z=0 の層）は彫らない**（罠 5 の習慣。
    ここが抜けると隣のタイルとの間から下が見える）。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['pav_dd'] if z < top - 1 else C['crack']  # 彫った底ほど暗い
    v[:, :, 0] = C['pav_dd']

    face = np.zeros((V, V), np.uint8)
    step = 16
    for by in range(0, V, step):
        off = (by // step) % 2 * (step // 2)  # 半枚ずらす（芋目地を避ける）
        for bx in range(-step, V + step, step):
            x0 = bx + off
            shade = rng.choice([C['pav'], C['pav_l'], C['pav_d']], p=[0.5, 0.25, 0.25])
            x1, y1 = x0 + step - 1, by + step - 1  # 1 列は目地として残す
            xa, xb = max(x0, 0), min(x1, V)
            ya, yb = max(by, 0), min(y1, V)
            if xa < xb and ya < yb:
                face[xa:xb, ya:yb] = shade
    stone = face > 0
    # 石の目（微細なむら）。敷石の中だけ、2×2 の塊で 3 色を薄く散らす。
    _grain(rng, face, stone, [C['pav_g1'], C['pav_g2'], C['pav_g3']], [0.16, 0.13, 0.10])

    v[:, :, top] = face  # 0 の所は 1 段彫れて目地の底が見える

    # 亀裂: 折れ線で 1 段彫る（**深いのは一部だけ**）。
    # **数も太さも控えめに。**1〜3 本・幅 2 を 35% で入れた版は、床が黒い虫だらけに見えた。
    for _ in range(int(rng.integers(0, 3))):
        x, y = int(rng.integers(3, V - 3)), int(rng.integers(3, V - 3))
        dx, dy = (1, 1) if rng.random() < 0.5 else (1, -1)
        deep = rng.random() < 0.4
        for _ in range(int(rng.integers(7, 14))):
            if 0 <= x < V and 0 <= y < V:
                v[x, y, top] = 0
                if deep:
                    v[x, y, top - 1] = 0
            x += dx if rng.random() < 0.8 else 0
            y += dy if rng.random() < 0.6 else 0
    # 敷石の欠け（角を 1 段落とす）。
    for _ in range(int(rng.integers(1, 4))):
        x, y = int(rng.integers(0, V - 3)), int(rng.integers(0, V - 3))
        w, d = int(rng.integers(2, 5)), int(rng.integers(2, 5))
        v[x:x + w, y:y + d, top] = 0
        if rng.random() < 0.25:
            v[x:x + w, y:y + d, top - 1] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_rough(name, rocky):
    """通路の床 — 踏み固めた土／岩肌。**節理と轍はへこみで**（部屋の床の亀裂と同じ考え）。"""
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['dirt_d'] if z < top - 1 else C['crack']
    layer = np.zeros((V, V), np.uint8)
    if rocky:
        _mottle(rng, layer, [C['rock_d'], C['rock'], C['rock_dd']], [0.45, 0.3, 0.25])
        _grain(rng, layer, layer > 0, [C['rock'], C['rock_dd'], C['band']], [0.14, 0.12, 0.09])
        v[:, :, top] = layer
        # 節理（岩の割れ目）。**1〜2 段彫る**（色の線ではなく溝）。数は控えめに（罠 45）。
        for _ in range(int(rng.integers(1, 4))):
            x, y = int(rng.integers(0, V)), int(rng.integers(0, V))
            deep = rng.random() < 0.35
            for _ in range(int(rng.integers(8, 16))):
                if 0 <= x < V and 0 <= y < V:
                    v[x, y, top] = 0
                    if deep:
                        v[x, y, top - 1] = 0
                x += int(rng.integers(-1, 2))
                y += 1 if rng.random() < 0.7 else 0
    else:
        _mottle(rng, layer, [C['dirt'], C['dirt_l'], C['dirt_d']], [0.5, 0.25, 0.25])
        _grain(rng, layer, layer > 0, [C['dirt'], C['dirt_l'], C['soil']], [0.15, 0.12, 0.08])
        for _ in range(7):  # 埋まった小石（1 段持ち上げず、色だけ）
            x, y = int(rng.integers(1, V - 2)), int(rng.integers(1, V - 2))
            layer[x:x + 2, y:y + 2] = C['pebble']
        v[:, :, top] = layer
        # 踏み荒らした窪み（浅い皿）。
        for _ in range(int(rng.integers(2, 5))):
            x, y = int(rng.integers(1, V - 6)), int(rng.integers(1, V - 6))
            w, d = int(rng.integers(3, 7)), int(rng.integers(3, 7))
            v[x:x + w, y:y + d, top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_cave(name):
    """**掘り広げた洞窟の床**（P10 第 4 期。イークの洞穴の部屋）。

    2026-08-10 に決めたことの続き——壁を岩肌にしたら、**手掘りの穴に切石の床**が
    敷いてあることが目に付いた。

    部屋の床の既定（`floor_room`）は大判の敷石で、**16 マスごとの目地**が引いてある。
    そこが「人が造った」の読みなので、洞窟では**線を 1 本も引かない**のが要件になる。
    代わりに岩と土が斑に覗き、掘った窪みが散る。

    **色は重ねた矩形で置く**（`_lump_face`）。格子にも砂粒にもしないため。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['rock_dd'] if z < top - 1 else C['crack']
    face = np.zeros((V, V), np.uint8)
    #! 岩が主・土が従。**部屋のほうが岩が多い**（掘り広げた面がそのまま出ている）。
    _lump_face(rng, face, [C['rock_d'], C['rock'], C['band'], C['dirt_d'], C['rock_dd']],
               [0.30, 0.26, 0.16, 0.16, 0.12])
    v[:, :, top] = face
    #! 掘った窪み。**浅く広く**（深いと穴に見えて通れないマスと紛れる）。
    for _ in range(int(rng.integers(3, 7))):
        x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        w, d = int(rng.integers(4, 10)), int(rng.integers(4, 10))
        v[x:x + w, y:y + d, top] = 0
    #! 節理（岩の割れ目）。折れ線で 1〜2 段。**数は控えめに**（罠 45）。
    for _ in range(int(rng.integers(1, 4))):
        x, y = int(rng.integers(2, V - 2)), int(rng.integers(2, V - 2))
        deep = rng.random() < 0.3
        for _ in range(int(rng.integers(8, 17))):
            if 0 <= x < V and 0 <= y < V:
                v[x, y, top] = 0
                if deep:
                    v[x, y, top - 1] = 0
            x += int(rng.integers(-1, 2))
            y += 1 if rng.random() < 0.7 else 0
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_dug(name):
    """**手掘りの通路の床**（P10 第 4 期。イークの洞穴の通路）。

    部屋（`floor_cave`）との差は**踏み固め**である。通路は歩かれるので土が締まって
    岩が隠れる。逆に部屋は掘り広げた岩の面がそのまま出ている。
    **向きを持つものは置けない**（プレハブは通路の走る向きを知らない）ので、
    轍ではなく「均された土」と「つるはしの筋」で言う。

    つるはしの筋は**変種ごとに 1 つの向きへ揃える**。ばらばらに刻むと
    ただの傷になるが、平行に並ぶと道具の跡に読める。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['rock_dd'] if z < top - 1 else C['crack']
    face = np.zeros((V, V), np.uint8)
    #! 土が主・岩が従（部屋と逆）。`pack` は町の踏み固めた土と同じ色。
    _lump_face(rng, face, [C['pack'], C['dirt_d'], C['dirt'], C['rock_d'], C['pack_d']],
               [0.30, 0.24, 0.18, 0.16, 0.12])
    #! 埋まった小石。**1 段持ち上げず色だけ**（`floor_rough` と同じ流儀）。
    for _ in range(9):
        x, y = int(rng.integers(1, V - 3)), int(rng.integers(1, V - 3))
        face[x:x + 2, y:y + 2] = C['pebble']
    v[:, :, top] = face
    #! つるはしの筋。**変種ごとに向きを揃える**（1 段だけ彫る）。
    along_x = (int(name[-2:]) % 2) == 0
    for _ in range(int(rng.integers(5, 10))):
        x, y = int(rng.integers(1, V - 7)), int(rng.integers(1, V - 7))
        ln = int(rng.integers(3, 7))
        if along_x:
            v[x:x + ln, y, top] = 0
        else:
            v[x, y:y + ln, top] = 0
    #! 踏み荒らした浅い皿。
    for _ in range(int(rng.integers(2, 5))):
        x, y = int(rng.integers(1, V - 6)), int(rng.integers(1, V - 6))
        w, d = int(rng.integers(3, 8)), int(rng.integers(3, 8))
        v[x:x + w, y:y + d, top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def bedrock_raw(name):
    """**地山**（P10 第 4 期。まだ掘っていない岩の塊）。

    岩肌の壁（`wall_rock`）と並べて置くので、**同じ石でありながら「掘った／掘っていない」
    が読める**ことが要件になる。分けたのは 2 つ。

    ============  ==================================================
    彫りの深さ     壁は 1〜3（抉った）。**地山は 0〜1**（手が入っていない）
    層理           地山のほうが**帯が強く・多い**。堆積したまま切り立っている
    ============  ==================================================

    既定の `bedrock` との差は色の粒である。あちらは 1 ボクセルの染みを 14 枚重ねるので
    寄ると点描に見える（2026-08-10 に気づいた）。こちらは塊で置く。
    **直方体・高さ 1.0 マス・天面平ら**は既定と同じく崩さない。
    """
    rng = rng_for(name)
    h = WALL_H
    #! 層理は 8 帯（`bedrock` の 5 帯より細かい）。厚みも 1 帯ずつ揺らす。
    bands = [C['rock_dd'], C['rock_d'], C['band'], C['rock'], C['rock_d'],
             C['band'], C['rock_l'], C['rock']]
    edges = np.sort(rng.choice(np.arange(2, h - 1), size=len(bands) - 1, replace=False))
    v = np.zeros((V, V, h), np.uint8)
    for z in range(h):
        v[:, :, z] = bands[int(np.searchsorted(edges, z))]

    #! 帯の中の塊むら（4×4×4）。**帯を消さない程度に薄く**（0.30）。
    grow = (lambda a: np.repeat(np.repeat(np.repeat(a, 4, 0), 4, 1), 4, 2)[:V, :V, :h])
    shape = ((V + 3) // 4, (V + 3) // 4, (h + 3) // 4)
    lump = rng.choice([C['rock_d'], C['rock'], C['rock_dd'], C['band']],
                      size=shape, p=[0.34, 0.28, 0.22, 0.16]).astype(np.uint8)
    v = np.where(grow(rng.random(shape) < 0.30), grow(lump), v).astype(np.uint8)

    #! 剥離。**深さ 1 だけ**（掘った跡ではないので抉らない）。帯に沿って横長に。
    for face in range(4):
        for _ in range(9):
            du = int(rng.integers(6, 16))
            dw = int(rng.integers(2, 5))
            u0 = int(rng.integers(-4, V - 2))
            w0 = int(rng.integers(1, max(2, h - 3)))
            _carve_relief(v, face, u0, u0 + du, w0, w0 + dw, 1)
            _paint_face(v, face, u0, u0 + du, max(w0, 1), min(w0 + dw, h - 1), 1, C['rock_dd'])
    #! 天面は平ら・明るくしない（`bedrock` と同じ理由）。
    face_top = rng.choice([C['rock_d'], C['rock_dd']], size=((V + 3) // 4, (V + 3) // 4),
                          p=[0.58, 0.42]).astype(np.uint8)
    v[:, :, h - 1] = np.repeat(np.repeat(face_top, 4, 0), 4, 1)[:V, :V]
    return [('main', v, (0, 0, 0))]


def _paved_face(rng, face, step, stagger, shades, weights):
    """敷石の天面。`step` マスの正方形で、段ごとに `stagger` だけ横へずらす。

    **目地は「貼り残し」で作る**（右端と上端の 1 列を空ける）。彫るのではなく
    置かないので、1 段下の暗い色がそのまま溝の底になる（`floor_room` と同じ流儀）。
    `stagger` を 0 にすると**芋目地**——縦の目地が一直線に通り、格子が強く出る。
    """
    for by in range(0, V, step):
        off = ((by // step) % 2) * stagger
        for bx in range(-step, V + step, step):
            x0 = bx + off
            shade = rng.choice(shades, p=weights)
            xa, xb = max(x0, 0), min(x0 + step - 1, V)
            ya, yb = max(by, 0), min(by + step - 1, V)
            if (xa < xb) and (ya < yb):
                face[xa:xb, ya:yb] = shade


def _block_wall(name, course_h, block_w, stagger, shades, weights, joint_colour,
                recess_choice, recess_p, cap_shade, plaster=None):
    """石ブロックの壁（`masonry` の親戚。**目地の周期を呼ぶ側が決める**）。

    `masonry`（切石積み）は 8 マスの段・11 マスの石・半枚ずらしに焼き付けてあり、
    実機で見て決着させた見た目である。**そこは 1 ボクセルも触らない**ので、
    周期と材を替えたいときはこちらを使う。

    面いっぱいを目地の色で満たしてから外皮に石を貼り、貼り残した目地を彫る、
    という手順は `masonry` と同じ（＝ AO が溝の影を作る）。

    :param stagger: 段ごとの横ずらし。**0 なら芋目地**（縦の目地が一直線に通る）
    :param recess_choice: 石ごとの引っ込み量の候補。`(0,)` なら平ら
    :param plaster: `(下端の z, 色, 重み)`。腰から上を漆喰にするとき
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.full((V, V, h), joint_colour, np.uint8)
    for face in range(4):
        for cz in range(0, h, course_h):
            off = ((cz // course_h) % 2) * stagger
            w0, w1 = cz, min(cz + course_h - 1, h)  # 上端 1 列は目地
            use_shades, use_p = shades, weights
            if (plaster is not None) and (cz >= plaster[0]):
                use_shades, use_p = plaster[1], plaster[2]
            u = -off
            while u < V:
                shade = rng.choice(use_shades, p=use_p)
                recess = int(rng.choice(recess_choice, p=recess_p))
                ua, ub = max(u, 0), min(u + block_w - 1, V)  # 右 1 列は目地
                if ua < ub:
                    if recess > 0:
                        _carve_relief(v, face, ua, ub, w0, w1, recess)
                    _paint_face(v, face, ua, ub, max(w0, 1), min(w1, h - 1), recess, shade)
                u += block_w
    # 貼り残した目地を彫る（外皮だけ。接地層と天面は残す＝罠 5 と高さの揃い）。
    shell = np.zeros((V, V, h), bool)
    shell[:, 0, :] = shell[:, V - 1, :] = shell[0, :, :] = shell[V - 1, :, :] = True
    carve = shell & (v == joint_colour)
    carve[:, :, 0] = False
    carve[:, :, h - 1] = False
    v[carve] = 0
    # 天面は笠石。**平らに保つ**（高さの揃いが地形の判別を作る）。
    top = np.zeros((V, V), np.uint8)
    for bx in range(0, V, 16):
        for by in range(0, V, 16):
            top[bx:bx + 16, by:by + 16] = rng.choice(cap_shade)
    v[:, :, h - 1] = top
    return [('main', v, (0, 0, 0))]


# ------------------------------------- 迷宮の意匠（P10 第 4 期。2026-08-10 に決めた）
#
# > 迷宮のイメージはミノタウロスの迷宮や Wizardry の四角い迷宮のイメージ。
# > 小物とはずれるが**壁や床を石ブロックの壁、石壁で他と差別化する**
#
# **「四角い」は乱れの無さで作る。**ほかのダンジョンは変種 10 枚でばらけさせているが、
# ここは逆で、どれを引いても見分けが付かないくらい揃える——反復が読めることが四角さになる。
# 亀裂も欠けも苔も乱れ積みも入れない。`FORGET`（地図が消える）と噛み合う。


def floor_lab(name):
    """迷宮の床 — **正確に並ぶ正方形の石畳**（部屋も通路も同じものを敷く）。

    既定の部屋の床（`floor_room`）との差は 3 つ。**半枚ずらさない**（芋目地）、
    **亀裂と欠けを入れない**、**石の目（微細なむら）を入れない**。
    「部屋と通路で床を分けない」と決めたので、`dungeon_style.cpp` は
    部屋にも通路にもこれを指す。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['joint']  # 目地の底。**彫った所ほど暗い、をやらない**（均一に保つ）
    face = np.zeros((V, V), np.uint8)
    #! 16 マスの正方形が 2×2。**ずらさない**ので縦の目地が一直線に通る。
    #! 色は**冷たく暗い灰**。城（`floor_cas`）が淡い暖色の石灰岩なので、
    #! ここを明るい灰にすると 2 つが見分けられなくなった（実機の絵で気づいた）。
    _paved_face(rng, face, step=16, stagger=0,
                shades=[C['cob'], C['cob_d'], C['flag_d']], weights=[0.62, 0.22, 0.16])
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def wall_lab(name):
    """迷宮の壁 — **1 マスに大きな石ブロックが 2 段**。目地は水平と垂直だけ。"""
    return _block_wall(name, course_h=16, block_w=16, stagger=0,
                       shades=[C['flag'], C['flag_l'], C['flag_d']], weights=[0.66, 0.17, 0.17],
                       joint_colour=C['joint'],
                       #! **ほぼ平ら。**引っ込みを混ぜると乱れ積みに見えて四角さが消える。
                       recess_choice=[0, 1], recess_p=[0.82, 0.18],
                       cap_shade=[C['flag_d'], C['flag']])


def bedrock_lab(name):
    """迷宮の岩盤 — **えぐれを持たない垂直の面**（そう決めた）。

    彫らないので側面は真っ平ら。縦の筋（色だけ・4 マスの塊）で石の目を示す。
    **壁より暗くする**——同じ灰色だと迷路の壁と地山が地続きに見えて、
    通れる所の輪郭が読めなくなる。
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.full((V, V, h), C['cob_d'], np.uint8)
    #! **縦の筋**（列ごとに 1 色。上下には変えない）。切り立った面が縦に走って見える。
    #! 4 マスの塊で色を置く（1 ボクセルずつ振ると点描＝罠 38）。
    cols = rng.choice([C['cob_d'], C['joint'], C['flag_d']],
                      size=((V + 3) // 4,), p=[0.50, 0.30, 0.20]).astype(np.uint8)
    band = np.repeat(cols, 4)[:V]
    for face in range(4):
        at = _face_setter(v, face)
        for u in range(V):
            for w in range(1, h - 1):
                v[at(u, w, 0)] = band[u]
    v[:, :, h - 1] = C['joint']  # 天面は平ら・暗い（見下ろすカメラで浮かせない）
    return [('main', v, (0, 0, 0))]


# ------------------------------------- 城の意匠（P10 第 4 期。ダンジョン 12 番「城」）
#
# > 城は**大理石をイメージした白系の壁と床**にしてみよう
# （2026-08-10 に決めた）
#
# : 深さ 20–65・`NO_CAVE`（洞窟が 1 つも湧かない）・`CURTAIN`（帳）・
# `ARENA`・主は皇帝『レイザーク』。**人が造った建物**であることが名前であり中身でもある。
# 洞窟の系統（イーク）と正面から対にする——あちらは掘った穴、こちらは積んだ建物。
#
# **大理石の読みを作るのは 3 つ。**白いだけでは漆喰と見分けが付かない。
#
# ==========  ====================================================================
# 脈          青みの灰の 1 ボクセルの線。**続いた線であること**が要件で、
#             散らすと汚れになる（罠 38 の点描はここでは「線」なので別物）
# 明るい目地  白い石に黒い目地を切ると、目地が格子になって石より目立つ
# 磨き        亀裂も欠けも入れない。傷んだ石は大理石に見えない
# ==========  ====================================================================


def _marble_vein(rng, face, colour, count, length=(10, 26)):
    """大理石の脈 — **1 ボクセル幅の続いた線**をふらつかせて引く。

    亀裂（`floor_room`）と作りは同じだが、**彫らずに色だけ**置く。彫ると溝の影が
    落ちて「割れた石」になる。大理石の脈は面の中の模様であって、へこみではない。
    """
    for _ in range(count):
        x, y = int(rng.integers(0, V)), int(rng.integers(0, V))
        dx, dy = (1, 1) if rng.random() < 0.5 else (1, -1)
        for _ in range(int(rng.integers(*length))):
            if (0 <= x < V) and (0 <= y < V) and (face[x, y] != 0):
                face[x, y] = colour
            x += dx if rng.random() < 0.75 else 0
            y += dy if rng.random() < 0.55 else 0


def floor_cas(name):
    """城の広間の床 — **白大理石の大判**。

    既定の部屋の床（`floor_room`）との差は「傷んでいない」こと。亀裂も欠けも入れず、
    代わりに脈を通す。**半枚ずらす**のは正式な石張りだから——迷宮の芋目地とはここで分かれる。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['marb_j']
    face = np.zeros((V, V), np.uint8)
    _paved_face(rng, face, step=16, stagger=8,
                shades=[C['marb'], C['marb_l'], C['marb_d']], weights=[0.58, 0.26, 0.16])
    #! **1 マスに 1〜2 本**。多いと貫入ではなくひび割れに見える（実機の絵で気づいた）。
    _marble_vein(rng, face, C['marb_v'], count=int(rng.integers(1, 3)))
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_hall(name):
    """城の廊下の床 — **細長い大理石を一方向へ並べる**。

    広間（`floor_cas`）が正方形の大判なのに対し、廊下は 32×8 の板を 4 枚。
    **板目が一方向に走る**ことが「通り道」の読みになる。向きは変種ごとに替える
    ——プレハブは廊下の走る向きを知らないので、揃えるより散らすほうが破綻しない。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['marb_j']
    face = np.zeros((V, V), np.uint8)
    along_x = (int(name[-2:]) % 2) == 0
    shades, weights = [C['marb'], C['marb_d'], C['marb_l']], [0.52, 0.28, 0.20]
    for k in range(0, V, 8):
        #! 継ぎ目は板ごとに位置を替える（1 本の線が端から端まで通らないように）
        seam = int(rng.integers(6, V - 6))
        a, b = rng.choice(shades, p=weights), rng.choice(shades, p=weights)
        if along_x:
            face[0:seam - 1, k:k + 7] = a
            face[seam:V, k:k + 7] = b
        else:
            face[k:k + 7, 0:seam - 1] = a
            face[k:k + 7, seam:V] = b
    _marble_vein(rng, face, C['marb_v'], count=int(rng.integers(1, 3)))
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def _face_vein(v, rng, colour, stone, count, length=(10, 24)):
    """側面（外皮）に大理石の脈を引く。床の `_marble_vein` の壁版。

    **石の上にだけ乗せる**（`stone` に無い色＝目地や抉った底は避ける）。
    目地の中を脈が横切ると、石と目地の区別が壊れて面が濁る。
    """
    for face in range(4):
        at = _face_setter(v, face)
        for _ in range(count):
            u, w = int(rng.integers(0, V)), int(rng.integers(2, WALL_H - 2))
            step = 1 if rng.random() < 0.5 else -1
            for _ in range(int(rng.integers(*length))):
                if (0 <= u < V) and (1 <= w < WALL_H - 1):
                    pos = at(u, w, 0)
                    if v[pos] in stone:
                        v[pos] = colour
                u += 1 if rng.random() < 0.75 else 0
                w += step if rng.random() < 0.5 else 0


def wall_cas(name):
    """城の壁 — **白大理石の切石。腰石だけ灰大理石**。

    白一色だと床と壁が地続きに見えて、部屋の輪郭が読めなくなる（見下ろすカメラでは
    壁の天面が絵の大半を占める）。**下 1 段を灰大理石**にして足元を締める。
    """
    parts = _block_wall(name, course_h=8, block_w=12, stagger=6,
                        shades=[C['marb'], C['marb_l'], C['marb_d']], weights=[0.54, 0.26, 0.20],
                        joint_colour=C['marb_j'],
                        #! **ほぼ平ら**（磨いた石なので出入りは付けない）。
                        recess_choice=[0, 1], recess_p=[0.80, 0.20],
                        cap_shade=[C['marb_d'], C['marb']],
                        #! 「腰から上」ではなく**下 1 段だけ灰**にしたいので、
                        #! `plaster`（＝ある高さから上を別の材へ）は使わない。
                        plaster=None)
    v = parts[0][1]
    rng = rng_for(name + '_vein')
    #! 腰石。下 1 段（z=0〜7）を灰大理石へ置き換える（**塊で。にじませない**）。
    stone = (C['marb'], C['marb_l'], C['marb_d'])
    for face in range(4):
        at = _face_setter(v, face)
        for u in range(V):
            for w in range(0, 8):
                pos = at(u, w, 0)
                if v[pos] in stone:
                    v[pos] = C['marb_g'] if rng.random() < 0.72 else C['marb_gd']
    _face_vein(v, rng, C['marb_v'], stone, count=3)
    return parts


def bedrock_cas(name):
    """城の躯体 — **灰大理石の厚い石**。白い壁より暗く、石も大きい。

    城には「地山」が無い（`NO_CAVE`）ので、岩盤の役割に来るのは**分厚い壁の中身**である。
    磨いていない灰大理石で、脈も粗い。**白い壁とここで明度が分かれる**ことが、
    通れる所（部屋）と通れない塊の見分けになる。
    """
    parts = _block_wall(name, course_h=11, block_w=16, stagger=8,
                        shades=[C['marb_g'], C['marb_gd'], C['marb_d']], weights=[0.48, 0.34, 0.18],
                        joint_colour=C['joint'],
                        recess_choice=[0, 1, 2], recess_p=[0.52, 0.32, 0.16],
                        cap_shade=[C['marb_gd'], C['marb_g']])
    rng = rng_for(name + '_vein')
    _face_vein(parts[0][1], rng, C['marb_j'], (C['marb_g'], C['marb_gd'], C['marb_d']), count=4)
    return parts


# ----------------------------------- 金鉱の意匠（P10 第 4 期。ダンジョン 15 番「金鉱」）
#
# : 深さ 75–80・`SMALLEST`・通路率 0・**壁の 40% が財宝の鉱脈**・
# 出るのは `$` だけ・湧きが 2 倍。壁がもう鉱脈なので、意匠は「人が掘った跡」を足す側に回る。


def _ore_specks(rng, face, count=14):
    """こぼれた鉱石の粒。**2×2 の塊**で置く（1 ボクセルだと砂粒＝罠 38）。"""
    for _ in range(count):
        x, y = int(rng.integers(0, V - 2)), int(rng.integers(0, V - 2))
        face[x:x + 2, y:y + 2] = C['gold_d'] if rng.random() < 0.55 else C['qz']


def floor_mine(name):
    """坑道の切羽の床 — 掘り屑（ずり）と土。こぼれた鉱石が混じる。"""
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['rock_dd'] if z < top - 1 else C['crack']
    face = np.zeros((V, V), np.uint8)
    #! ずり（砕いた岩）が主。**イークの洞窟より灰色寄り**にして、土の穴と分ける。
    _lump_face(rng, face, [C['rock_d'], C['rock'], C['rock_dd'], C['dirt_d'], C['band']],
               [0.30, 0.24, 0.20, 0.14, 0.12])
    _ore_specks(rng, face, count=12)
    v[:, :, top] = face
    #! 掘り下げた窪み。
    for _ in range(int(rng.integers(2, 6))):
        x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        v[x:x + int(rng.integers(3, 9)), y:y + int(rng.integers(3, 9)), top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_drift(name):
    """坑道（ドリフト）の床 — 運び出す道。**ずりが均され、粒が落ちている**。

    切羽（`floor_mine`）との差は「均してある」こと。窪みを入れず、
    鉱石の粒を増やす——鉱車で運ぶ道なので、こぼれるのはこちら側である。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['rock_dd'] if z < top - 1 else C['crack']
    face = np.zeros((V, V), np.uint8)
    _lump_face(rng, face, [C['pack'], C['rock_d'], C['dirt_d'], C['grit'], C['pack_d']],
               [0.28, 0.24, 0.20, 0.16, 0.12])
    _ore_specks(rng, face, count=20)
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def wall_mine(name):
    """金鉱の壁 — **掘り出した岩に鉱脈の帯が走る**。

    形は岩肌の壁（`wall_rock`）と同じ作りにして、`_vein` で金と石英の帯を貼る。
    掘っている当人がいる場所なので、抉りは洞窟と同じく深い。
    """
    parts = wall_rock(name)
    v = parts[0][1]
    rng = rng_for(name + '_vein')  # **形の種と分ける**（帯だけ替えた変種を作れるように）
    _vein(v, rng, WALL_H, [C['gold'], C['gold_d'], C['qz'], C['qz_l']], [0.30, 0.34, 0.22, 0.14])
    return parts


def bedrock_mine(name):
    """金鉱の地山 — **まだ掘っていない鉱床**。層理に沿って帯が濃い。"""
    parts = bedrock_raw(name)
    v = parts[0][1]
    rng = rng_for(name + '_vein')
    _vein(v, rng, WALL_H, [C['gold_d'], C['qz'], C['mag'], C['gold']], [0.34, 0.26, 0.22, 0.18])
    return parts


# =============================== 第 5 期の意匠（P10。2026-08-11。A 系統に残っていた 4 本）
#
# が「床 100・花崗岩 100・石英 4／溶岩 6・通路率 50」の**既定そのまま**と
# 数えた 5 本のうち、鉄獄（1）は**基準に据える**（表の 1 行を消せば元の絵に戻せる）ので、
# 残っていたのは反魔法（16）・反攻撃（17）・カメレオン洞（18）・暗闇の洞窟（19）の 4 本である。
#
# | 本 | 材 | 何で語るか |
# |---|---|---|
# | 18 カメレオン洞 | `floor_mimic` / `floor_scute` / `wall_mimic` / `bedrock_scute` | **周りを真似る**。10 枚のうち 1 枚だけ真似そこねる |
# | 19 暗闇の洞窟 | `floor_murk` / `floor_soot` / `wall_murk` / `bedrock_murk` | **光を吸う**。ただし黒にはしない |
# | 16 反魔法 ／ 17 反攻撃 | `wall_ward` / `bedrock_ward` を **2 本で共有** | **封じてある**。磨いた一枚岩に印を彫る |
#
# **16 と 17 は同じ材を引く。**案が「対にするので材が同じ
# ほうが小物の差が立つ」として材を替えないと書いていたのは、**2 本の間の差**の話である。
# 1 組の材を 2 本で共有すれば、対であることは崩れないまま鉄獄（＝既定）とは分かれる。


def _recolour(v, mapping):
    """色の索引を入れ替える（**形はそのまま**）。同じ形で別の材を作るときの手。

    暗闇の洞窟は「掘り抜いた穴」であることがイークの洞穴と変わらないので、
    形（`wall_rock` / `bedrock_raw`）を作り直す理由が無い。**替えるのは色だけ**である。
    """
    out = v.copy()
    for src, dst in mapping.items():
        out[v == C[src]] = C[dst]
    return out


def _glyph_dot(v, face, u, w, colour):
    """側面を 1 段だけ彫って底に色を置く（印の 1 画素）。

    **接地層と天面は彫らない**（`_carve_relief` と同じ約束）。
    """
    at = _face_setter(v, face)
    if (0 <= u < V) and (1 <= w < v.shape[2] - 1):
        v[at(u, w, 0)] = 0
        v[at(u, w, 1)] = colour


def _glyph_ring(v, face, cu, cw, r, colour):
    """印の輪。"""
    steps = max(16, int(2.0 * math.pi * r))
    for i in range(steps):
        a = 2.0 * math.pi * i / steps
        _glyph_dot(v, face, int(round(cu + r * math.cos(a))), int(round(cw + r * math.sin(a))), colour)


def _glyph_bar(v, face, u0, w0, u1, w1, colour):
    """印の線（縦・横・斜め）。"""
    n = max(abs(u1 - u0), abs(w1 - w0)) + 1
    for i in range(n):
        t = i / max(n - 1, 1)
        _glyph_dot(v, face, int(round(u0 + (u1 - u0) * t)), int(round(w0 + (w1 - w0) * t)), colour)


def _skin_lumps(v, rng, shades, weights, p_cover, keep_top=True):
    """外皮の色を**塊（4×4×4）**で塗り替える。形には触らない。

    天面は既定で守る——見下ろすカメラでは天面が絵の大半を占めるので、
    ここを明るい色で塗ると「壁が手前にある」が読めなくなる（`wall_rock` と同じ理由）。
    """
    h = v.shape[2]
    top_layer = v[:, :, h - 1].copy()
    grow = (lambda a: np.repeat(np.repeat(np.repeat(a, 4, 0), 4, 1), 4, 2)[:V, :V, :h])
    shape = ((V + 3) // 4, (V + 3) // 4, (h + 3) // 4)
    lump = rng.choice(shades, size=shape, p=weights).astype(np.uint8)
    mask = grow(rng.random(shape) < p_cover) & (v > 0)
    v[mask] = grow(lump)[mask]
    if keep_top:
        v[:, :, h - 1] = top_layer


# ---- 18 カメレオン洞（30–45・カメレオンのみ・最低 30 体。主はカメレオンの王）----


def floor_mimic(name):
    """カメレオン洞の部屋の床 — **周りの材を真似た岩**。

    擬態を材で言うのに要るのは 2 つ。

    - **1 マスの中に岩・苔・砂が混じる。**どれでもない面は「真似ている途中」に見える
    - **変種はきっちり揃える。**ばらつきで語ると擬態ではなくただの汚れになる
      （迷宮で「四角い」を乱れの無さで作ったのと同じ理屈＝§27.11）

    そのうえで**真似そこねた 1 枚**（`_10`）だけ色相をずらす。1/10 のマスなので
    部屋にひとつふたつ混じる——「同じものが 1 つだけ違う」が擬態の読みである。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['rock_dd'] if z < top - 1 else C['crack']
    face = np.zeros((V, V), np.uint8)
    off = (int(name[-2:]) % 10) == 0  # 真似そこねた 1 枚
    shades = ([C['mim'], C['mim_d'], C['moss_d'], C['mim_s'], C['rock_d']] if off
              else [C['rock_d'], C['rock'], C['moss_d'], C['mim_s'], C['band']])
    _lump_face(rng, face, shades, [0.28, 0.24, 0.18, 0.16, 0.14])
    v[:, :, top] = face
    #! 窪み。**線は 1 本も引かない**（洞窟なので目地は無い＝`floor_cave` と同じ要件）。
    for _ in range(int(rng.integers(2, 6))):
        x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        v[x:x + int(rng.integers(4, 9)), y:y + int(rng.integers(4, 9)), top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_scute(name):
    """カメレオン洞の通路の床 — **鱗板**。

    部屋（`floor_mimic`）が「真似ている面」なのに対して、通路は**皮そのもの**にする。
    種点のいちばん近い所どうしを 1 枚の板にまとめ、**板の境目だけ 1 段彫る**
    ——多角形が敷き詰まると亀甲になり、鱗に読める。**板ごとに 1 色**（罠 38）。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['rock_dd'] if z < top - 1 else C['crack']
    seeds = rng.integers(0, V, size=(14, 2))
    tone = rng.choice(np.array([C['rock_d'], C['band'], C['moss_d'], C['mim_s'], C['rock']], np.uint8),
                      size=len(seeds), p=[0.28, 0.22, 0.20, 0.16, 0.14]).astype(np.uint8)
    xs, ys = np.meshgrid(np.arange(V), np.arange(V), indexing='ij')
    d2 = (xs[..., None] - seeds[:, 0]) ** 2 + (ys[..., None] - seeds[:, 1]) ** 2
    owner = np.argmin(d2, axis=2)
    v[:, :, top] = tone[owner]
    edge = np.zeros((V, V), bool)
    edge[:-1, :] |= owner[:-1, :] != owner[1:, :]
    edge[:, :-1] |= owner[:, :-1] != owner[:, 1:]
    layer = v[:, :, top]
    layer[edge] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def _eye_on_face(v, face, cu, cw, rx=6, rw=4):
    """**瞳**。楕円に 1 段彫って虹彩を敷き、縦の瞳孔を落とす。

    彫ってから色を置くのは罠 104 の対（塊の上に描いた線は見えないが、
    **窪みの底の色は影と一緒に読める**）。瞳孔を縦にするのは爬虫類の目の記号。
    """
    at = _face_setter(v, face)
    h = v.shape[2]
    for du in range(-rx, rx + 1):
        for dw in range(-rw, rw + 1):
            if ((du / rx) ** 2 + (dw / rw) ** 2) > 1.0:
                continue
            u, w = cu + du, cw + dw
            if not ((0 <= u < V) and (1 <= w < h - 1)):
                continue
            v[at(u, w, 0)] = 0
            slit = (abs(du) <= 1) and (abs(dw) <= rw - 1)
            v[at(u, w, 1)] = C['dark'] if slit else C['iris']


def wall_mimic(name):
    """カメレオン洞の壁 — 岩肌だが**色が周りを真似ている**。10 枚のうち 1 枚に**瞳**がある。

    形は洞窟の壁（`wall_rock`）のままでよい——ここも掘り抜いた穴である。替えるのは
    色の側で、苔と砂の塊を岩の上へ重ねて「石なのに石の色をしていない」面にする。

    **瞳は `_07` の 1 枚だけ**（種は名前で決まるので、同じマスは何度見ても同じ壁）。
    前後の両面へ彫ってある——**プレハブの向きは置く側が決める**ので片面に賭けない（罠 105）。
    """
    _, v, org = wall_rock(name)[0]
    rng = rng_for(name + '_skin')
    _skin_lumps(v, rng, [C['moss_d'], C['mim_s'], C['mim'], C['lichen']],
                [0.34, 0.30, 0.20, 0.16], p_cover=0.34)
    if (int(name[-2:]) % 10) == 7:
        for face in (0, 1):
            _eye_on_face(v, face, V // 2, WALL_H // 2 + 4)
    return [('main', v, org)]


def bedrock_scute(name):
    """カメレオン洞の地山 — **鱗が重なった面**。

    壁（掘った）と地山（掘っていない）を作り分けるのはイークの洞穴と同じ約束
    （§27.10）。ここでは剥離の形を**半円**にして、重ねると鱗に見えるようにした。
    地山のほうが擬態が進んでいる——手が入っていない岩ほど周りに紛れる。
    """
    _, v, org = bedrock_raw(name)[0]
    rng = rng_for(name + '_skin')
    _skin_lumps(v, rng, [C['moss_d'], C['mim_s'], C['mim_d'], C['lichen']],
                [0.32, 0.30, 0.22, 0.16], p_cover=0.40)
    for face in range(4):
        for _ in range(8):
            cu = int(rng.integers(0, V))
            w0 = int(rng.integers(1, max(2, WALL_H - 8)))
            r = int(rng.integers(4, 8))
            for dw in range(r):
                half = int(round(r * math.sqrt(max(0.0, 1.0 - (dw / r) ** 2))))
                _carve_relief(v, face, cu - half, cu + half + 1, w0 + dw, w0 + dw + 1, 1)
                _paint_face(v, face, cu - half, cu + half + 1, w0 + dw, w0 + dw + 1, 1, C['rock_dd'])
    return [('main', v, org)]


# ---- 19 暗闇の洞窟（55–72・`DARKNESS`・小。主はヌル）----
#
# **置くものより置かないもので語る**のは小物でやった（§27.12）。材のほうは
# 「光を吸う」を色で言う。**黒にはしない**——コアが部屋の `GLOW` を潰しているので
# （`grid.cpp:74`）、材まで黒くすると暗さが二重に掛かって形が消える。

_MURK_MAP = {'rock_dd': 'murk_dd', 'rock_d': 'murk_d', 'band': 'soot',
             'rock': 'murk', 'rock_l': 'murk_l'}


def floor_murk(name):
    """暗闇の洞窟の部屋の床 — 光を吸う岩。**黒曜のかけらだけが稜を返す**。"""
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['murk_dd'] if z < top - 1 else C['murk_d']
    face = np.zeros((V, V), np.uint8)
    _lump_face(rng, face, [C['murk'], C['murk_d'], C['soot'], C['murk_l'], C['murk_dd']],
               [0.30, 0.26, 0.18, 0.14, 0.12])
    #! 黒曜のかけら。**2×2 の塊で数枚だけ**——暗い面では、明るい点が形の手掛かりになる。
    #! 撒きすぎると星空になるので 2〜4 枚に留める。
    for _ in range(int(rng.integers(2, 5))):
        x, y = int(rng.integers(0, V - 2)), int(rng.integers(0, V - 2))
        face[x:x + 2, y:y + 2] = C['obs_h']
    v[:, :, top] = face
    for _ in range(int(rng.integers(2, 5))):
        x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        v[x:x + int(rng.integers(4, 9)), y:y + int(rng.integers(4, 9)), top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_soot(name):
    """暗闇の洞窟の通路の床 — **煤が積もっている**。

    部屋（`floor_murk`）との差は「積もっているか」である。通路は歩かれるので
    炭の粒が踏まれて均され、岩が煤に隠れる（部屋と通路をイークで踏み固めで分けたのと同じ手）。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['murk_dd'] if z < top - 1 else C['murk_d']
    face = np.zeros((V, V), np.uint8)
    _lump_face(rng, face, [C['soot'], C['soot_l'], C['char'], C['murk_d'], C['murk']],
               [0.32, 0.24, 0.18, 0.14, 0.12])
    #! 踏み割れた炭。**1 段持ち上げず色だけ**（`floor_dug` の小石と同じ流儀）。
    for _ in range(7):
        x, y = int(rng.integers(1, V - 3)), int(rng.integers(1, V - 3))
        face[x:x + 2, y:y + 2] = C['char_l']
    v[:, :, top] = face
    for _ in range(int(rng.integers(1, 4))):
        x, y = int(rng.integers(1, V - 6)), int(rng.integers(1, V - 6))
        v[x:x + int(rng.integers(3, 8)), y:y + int(rng.integers(3, 8)), top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


# **マスの縁を明るくして輪郭を出す手は捨てた**（2026-08-11。実機の絵で見つけた）。
# 暗い材では面の明暗が潰れるので、天面の縁を 1 列だけ返させてみたところ、
# 岩盤が一面に広がる所で**明るい線の格子**になった——方眼紙であって岩ではない。
# 罠 38（砂粒）・罠 99（市松）と同じ話で、**マスの単位で規則的に置いたものは必ず模様になる**。
# 読みやすさは色の明度で確保する（`murk` は既定の岩の 6 割ほどの明るさに留めてある）。


def wall_murk(name):
    """暗闇の洞窟の壁 — 掘り抜いた穴の形のまま、**材だけ光を吸う岩**へ替える。

    形を作り直さないのは理屈の話でもある。ここも洞窟であって、イークの洞穴と
    「掘った」ことは変わらない。違うのは**光が返ってこない**ことだけである。
    """
    _, v, org = wall_rock(name)[0]
    v = _recolour(v, _MURK_MAP)
    rng = rng_for(name + '_murk')
    #! 深い抉り。底は `dark`（洞窟の穴が「奥がある」に見える）。
    for face in range(4):
        for _ in range(4):
            du = int(rng.integers(4, 10))
            dw = int(rng.integers(3, 8))
            u0 = int(rng.integers(-2, V - 2))
            w0 = int(rng.integers(1, max(2, WALL_H - 6)))
            _carve_relief(v, face, u0, u0 + du, w0, w0 + dw, 3)
            _paint_face(v, face, u0, u0 + du, max(w0, 1), min(w0 + dw, WALL_H - 1), 3, C['dark'])
    return [('main', v, org)]


def bedrock_murk(name):
    """暗闇の洞窟の地山。壁と同じ色の一族で、**手の入っていない**面。"""
    _, v, org = bedrock_raw(name)[0]
    v = _recolour(v, _MURK_MAP)
    return [('main', v, org)]


# ---- 16 反魔法 ／ 17 反攻撃（どちらも 40–50・素材も同じ。**材を共有する**）----


def _monolith(name, body, light, dark_, cap):
    """磨いた一枚岩。**石割りも目地も持たない**面を作る。

    切石（`masonry`）は 11 マスの石を貼って目地を彫るが、封じた壁は継ぎ目を持たない。
    **継ぎ目が無いこと自体が「人が塞いだ」の読み**である。平らな面を先に作るのは
    印を彫るためでもある（罠 104。塊の上に彫った溝はどこにも見えない）。
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.full((V, V, h), body, np.uint8)
    #! 面の振り。**帯にしない**（層理は自然の岩の読みで、切り出した石には出ない）。
    _skin_lumps(v, rng, [body, light, dark_], [0.46, 0.28, 0.26], p_cover=0.22, keep_top=False)
    #! 面取り。上端の 2 段を 1 ボクセル引っ込めて、底に明るい色を敷く
    #! ——**磨いた石の稜に当たる光**である。平らなだけの箱は「素材が無い」に見えるので、
    #! 凹凸はここ 1 か所だけ入れる（岩肌のように抉ると一枚岩でなくなる）。
    for face in range(4):
        _carve_relief(v, face, 0, V, h - 3, h - 1, 1)
        _paint_face(v, face, 0, V, h - 3, h - 1, 1, light)
    #! 腰の線。**マスをまたいで 1 本に繋がる**ので、並べると幅木のある壁になる。
    #! 印を持たない 8 枚が「素材の無い箱」に見えないための最低限の線でもある。
    for face in range(4):
        _carve_relief(v, face, 0, V, 5, 7, 1)
        _paint_face(v, face, 0, V, 5, 7, 1, dark_)
    #! 天面は平ら・単色寄り（高さの揃いが地形の判別を作る）。
    v[:, :, h - 1] = cap
    return v


def wall_ward(name):
    """封じの壁（反魔法 16 ／ 反攻撃 17 で**共有**）— 磨いた一枚岩に印を彫る。

    | 要件 | なぜ |
    |---|---|
    | **石割りを持たない** | 継ぎ目の無い 1 枚の面が「塞いだ」の読み。切石とも岩肌とも分かれる |
    | **印は 10 枚のうち 4 枚だけ** | 全部の壁に刻むと模様の部屋になる。要所に在るから封印に見える |
    | **光らせない** | 案の「反魔法は光らないことで語る」。自発光を乗せると意味が反転する |

    印は 4 面すべてへ彫ってある（罠 105。**向きは置く側が決める**）。
    """
    v = _monolith(name, C['ward'], C['ward_l'], C['ward_d'], C['ward_d'])
    idx = int(name[-2:]) % 10
    #! **10 枚のうち 2 枚だけ**。初版は 4 枚にしていて、実機の絵で
    #! **同じ印が 3 マス続けて並んだ**（40% は多すぎる）。要所に在るから封印に見える。
    if idx in (5, 8):
        cu, cw = V // 2, WALL_H // 2 + 2
        for face in range(4):
            _glyph_ring(v, face, cu, cw, 9, C['ward_j'])
            if idx == 5:  # 二重の輪
                _glyph_ring(v, face, cu, cw, 5, C['ward_j'])
            else:  # 輪に斜めの交叉
                _glyph_bar(v, face, cu - 5, cw - 5, cu + 5, cw + 5, C['ward_j'])
                _glyph_bar(v, face, cu - 5, cw + 5, cu + 5, cw - 5, C['ward_j'])
    return [('main', v, (0, 0, 0))]


def bedrock_ward(name):
    """封じの地山 — **印を持たない**一枚岩。

    印を彫るのは「人が塞いだ面」だけである。岩盤に来るのは分厚い壁の中身なので
    （城の `bedrock_cas` と同じ理屈）、ここに印は無い。縦の筋だけ入れて壁と分ける。
    """
    v = _monolith(name, C['ward_d'], C['ward'], C['ward_j'], C['ward_j'])
    rng = rng_for(name + '_grain')
    for face in range(4):
        for _ in range(6):
            u = int(rng.integers(1, V - 1))
            w0 = int(rng.integers(1, WALL_H // 2))
            w1 = int(rng.integers(WALL_H // 2, WALL_H - 1))
            _glyph_bar(v, face, u, w0, u, w1, C['ward_j'])
    return [('main', v, (0, 0, 0))]


def ground_grass(name, patchy, flowers=False):
    """草地。土のパッチと花は変種で。"""
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['soil']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['grass'], C['grass_l'], C['grass_d']], [0.5, 0.25, 0.25])
    if patchy:
        for _ in range(3):  # 土が覗くパッチ
            x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
            w, h = int(rng.integers(3, 6)), int(rng.integers(3, 6))
            layer[x:x + w, y:y + h] = C['soil']
    if flowers:
        for _ in range(6):
            x, y = int(rng.integers(1, V - 1)), int(rng.integers(1, V - 1))
            layer[x, y] = rng.choice([C['fl_w'], C['fl_y'], C['fl_r']], p=[0.4, 0.35, 0.25])
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def ground_dirt(name):
    """乾いた土（DIRT）。轍のような薄い帯を 1 本。"""
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['dirt_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['dirt_l'], C['dirt'], C['pebble']], [0.55, 0.35, 0.1])
    x = int(rng.integers(8, 24))
    for y in range(V):  # 帯（うっすら暗い）
        layer[max(0, min(V - 1, x)), y] = C['dirt']
        layer[max(0, min(V - 1, x + 1)), y] = C['dirt']
        x += int(rng.integers(-1, 2))
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def water(name, deep):
    """水面。**天面を床より下げる**（浅 -1・深 -2）。さざ波は明るい帯で。"""
    rng = rng_for(name)
    v = _tile(3)
    base, lite, dk = (C['wa_d'], C['wa'], C['wa_dd']) if deep else (C['wa'], C['wa_l'], C['wa_d'])
    v[:, :, 0] = dk
    v[:, :, 1] = base
    xs = np.arange(V)[:, None]
    ys = np.arange(V)[None, :]
    phase = float(rng.uniform(0, 6.28))
    wavep = np.sin(xs * 0.55 + ys * 0.35 + phase)
    top = np.full((V, V), base, np.uint8)
    top[wavep > (1.1 if deep else 0.82)] = lite
    top[wavep < -1.15] = dk
    v[:, :, 2] = top
    oz = -5 if deep else -4
    return [('main', v, (0, 0, oz))]


def lava_crust(name):
    """溶岩 — 黒い皮に明るい亀裂の網。**自発光は置く側がインスタンスで足す**
    （面そのものの色は皮の暗さと亀裂の明るさで作っておく）。"""
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['lava_o']
    v[:, :, 1] = C['crust']
    top = np.zeros((V, V), np.uint8)
    _mottle(rng, top, [C['crust'], C['crust_l']], [0.7, 0.3])
    for _ in range(5):  # 亀裂の網。1 段彫って下の橙を見せる
        x, y = int(rng.integers(0, V)), int(rng.integers(0, V))
        dx = 1 if rng.random() < 0.5 else -1
        for _ in range(int(rng.integers(10, 22))):
            if 0 <= x < V and 0 <= y < V:
                top[x, y] = 0
                if rng.random() < 0.3 and 0 <= x + 1 < V:
                    top[x + 1, y] = C['lava_y'] if rng.random() < 0.3 else 0
            x += dx if rng.random() < 0.6 else 0
            y += 1 if rng.random() < 0.75 else -1 if rng.random() < 0.15 else 0
    v[:, :, 2] = top
    return [('main', v, (0, 0, -4))]


# --------------------------------------------------------------------- 壁と岩
WALL_H = V  #!< **壁ブロックの高さは全種で 1.0 マスに統一**（2026-08-09 に決めた）


def _face_setter(v, face):
    """4 つの側面を同じ書き方で扱う口。`(u, w, depth) → ボクセル` を返す。

    `depth` は**面から内側へ何ボクセル入るか**。0 = 外皮。凹凸はこれで作る。
    """
    if face == 0:
        return lambda u, w, d: (u, d, w)
    if face == 1:
        return lambda u, w, d: (u, V - 1 - d, w)
    if face == 2:
        return lambda u, w, d: (d, u, w)
    return lambda u, w, d: (V - 1 - d, u, w)


def _carve_relief(v, face, u0, u1, w0, w1, depth):
    """側面の矩形を `depth` ボクセル分えぐる（凹凸の実体）。

    **接地層（w=0）と天面（w=最上段）はえぐらない。**接地層は隣との継ぎ目から下が
    見えるのを防ぐため（罠 5 の習慣）、天面は「壁の高さが揃って見える」ことを守るため
    （「高さを統一」と決めた。天面まで凸凹にすると高さが揃って見えなくなる）。
    """
    at = _face_setter(v, face)
    top = v.shape[2] - 1
    for w in range(max(w0, 1), min(w1, top)):
        for u in range(max(u0, 0), min(u1, V)):
            for d in range(depth):
                v[at(u, w, d)] = 0


def _paint_face(v, face, u0, u1, w0, w1, depth, colour):
    """えぐった底（`depth` の層）に色を置く。"""
    at = _face_setter(v, face)
    for w in range(max(w0, 0), min(w1, v.shape[2])):
        for u in range(max(u0, 0), min(u1, V)):
            v[at(u, w, depth)] = colour


def masonry(name, moss=False, rubblework=False):
    """切石積みの壁（高さ 1.0 マスちょうど）。

    面いっぱいをモルタルで満たし、外皮に「石」を貼る。目地は貼り残す（＝ 1 ボクセル彫れた
    溝になり、底のモルタルが覗く。AO で影が落ちる）。

    **石ごとに 0〜2 ボクセル引っ込める**（2026-08-09 に決めた「壁表面に 1〜2 ボクセルの
    凹凸があるほうが岩肌感があってよい」）。設計書 §6(c) が禁じているのは**ボクセル単位の
    無作為ノイズ**（±1 で三角形 180 倍）であって、**塊単位の段差は「構造的な凹凸」の側**で
    ある（§6 は「石の目地・乱れた石割り」を質を上げるものとして挙げている）。

    """
    rng = rng_for(name)
    h = WALL_H
    v = np.full((V, V, h), C['mortar'], np.uint8)
    course_h = 8
    shades = [C['wall'], C['wall_l'], C['wall_d']]

    for face in range(4):
        for cz in range(0, h, course_h):
            off = (cz // course_h) % 2 * 6 + (int(rng.integers(0, 4)) if rubblework else 0)
            w0, w1 = cz, min(cz + course_h - 1, h)  # 上端 1 列は目地
            u = -off
            while u < V:
                bw = int(rng.integers(8, 15)) if rubblework else 11
                shade = rng.choice(shades, p=[0.55, 0.2, 0.25])
                # 石ごとの出入り。引っ込んだ石ほど暗く見える（AO が効く）ので明暗と揃える。
                recess = int(rng.choice([0, 1, 2], p=[0.45, 0.35, 0.20]))
                ua, ub = max(u, 0), min(u + bw - 1, V)  # 右 1 列は目地
                if ua < ub:
                    if recess > 0:
                        _carve_relief(v, face, ua, ub, w0, w1, recess)
                    _paint_face(v, face, ua, ub, max(w0, 1), min(w1, h - 1), recess, shade)
                u += bw

    # 目地を彫る（外皮に残ったモルタルを消す。1 段下のモルタルが底になる）。
    shell = np.zeros((V, V, h), bool)
    shell[:, 0, :] = shell[:, V - 1, :] = shell[0, :, :] = shell[V - 1, :, :] = True
    carve = shell & (v == C['mortar'])
    carve[:, :, 0] = False  # **接地層は彫らない**（罠 5。隣との間から背景が抜ける）
    carve[:, :, h - 1] = False  # 天面も残す（高さを揃えて見せる）
    v[carve] = 0
    # 天面は笠石（2 枚割りの平石）。**平らに保つ**（高さの揃いが地形の判別を作る）。
    top = np.zeros((V, V), np.uint8)
    for bx in range(0, V, 16):
        for by in range(0, V, 11):
            shade = rng.choice(shades, p=[0.6, 0.25, 0.15])
            top[bx:bx + 15, by:by + 10] = shade
    v[:, :, h - 1] = np.where(top > 0, top, v[:, :, h - 1])
    if moss:
        # 下の 2 段の石を苔の色に置き換える（塊単位。にじませない）。
        low = v[:, :, 0:course_h * 2]
        stone_mask = np.isin(low, shades)
        blocks = rng.random((V, V, 1)) < 0.28
        low[stone_mask & np.broadcast_to(blocks, low.shape)] = C['moss']
    return [('main', v, (0, 0, 0))]


def bedrock(name, vein=None):
    """岩盤。**直方体を崩さない**（2026-08-09 に決めた:「削れた状態は行動不能の壁として
    判別がつきにくいのでブロック状を維持」。P10 初版の平面削りは廃止）。

    **高さは壁と同じ 1.0 マス**（同じ指示の後半:「壁ブロックの高さが異なるのも地形判別が
    つきづらくなるので統一しよう」）。荒々しさは**側面のえぐれ（1〜2 ボクセル）と色**で出す。
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.zeros((V, V, h), np.uint8)
    # 層理: z 帯で基調を変える。
    bands = [C['rock_d'], C['rock'], C['band'], C['rock'], C['rock_l']]
    for z in range(h):
        v[:, :, z] = bands[min(len(bands) - 1, z * len(bands) // h)]

    # --- 側面の岩肌（えぐれ＋色の染み）。**明るい石は少なめ**（1/6）。
    # 等確率にしたら岩盤が白くまだらになった（レビュー第 1 回）。
    shades = [C['rock_d'], C['rock_dd'], C['rock'], C['rock_d'], C['rock_dd'], C['rock_l']]
    for face in range(4):
        # (a) 塊のえぐれ（1〜2 ボクセル）。**これが岩肌感を作る**（決めたこと）。
        for _ in range(10):
            u0 = int(rng.integers(0, V - 5))
            w0 = int(rng.integers(1, h - 5))
            du = int(rng.integers(4, 10))
            dw = int(rng.integers(3, 8))
            depth = 1 if rng.random() < 0.62 else 2
            _carve_relief(v, face, u0, u0 + du, w0, w0 + dw, depth)
            # えぐった底は暗い岩（穴として読める）。
            _paint_face(v, face, u0, u0 + du, max(w0, 1), min(w0 + dw, h - 1), depth,
                        C['rock_dd'] if depth == 2 else C['rock_d'])
        # (b) 色の染み（形は変えない。えぐりと合わさって層が割れて見える）。
        at = _face_setter(v, face)
        for _ in range(14):
            u0 = int(rng.integers(0, V - 4))
            w0 = int(rng.integers(0, h - 4))
            shade = shades[int(rng.integers(0, len(shades)))]
            for u in range(u0, min(u0 + int(rng.integers(3, 8)), V)):
                for w in range(w0, min(w0 + int(rng.integers(3, 8)), h)):
                    for d in range(3):  # えぐられた底にも同じ色が乗るように 3 層ぶん
                        pos = at(u, w, d)
                        if v[pos] != 0:
                            v[pos] = shade
                            break
    # 天面: **平ら・明るくしない。**見下ろすカメラでは天面が絵の大半を占めるので、
    # 明るい石にすると塊ごと白く浮き、床より明るくなって「壁が手前にある」と読めなくなる。
    # 高さを揃えるためにも凹凸は付けない（「高さを統一」と決めた）。
    v[:, :, h - 1] = C['rock_d']
    for _ in range(7):
        x0, y0 = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        v[x0:x0 + int(rng.integers(3, 6)), y0:y0 + int(rng.integers(3, 6)), h - 1] = C['rock_dd']
    if vein == 'magma':
        _vein(v, rng, h, [C['mag'], C['mag_d'], C['mag_h']], [0.45, 0.35, 0.2])
    elif vein == 'quartz':
        _vein(v, rng, h, [C['qz'], C['qz_l']], [0.6, 0.4])
    return [('main', v, (0, 0, 0))]


def _vein(v, rng, h, shades, p):
    """鉱脈 — 側面（外皮）を横切る斜めの帯として貼る。帯の中は塊単位（2×2×2）で色を選ぶ。

    露出面ぜんぶに書くと粒に散って**雪をかぶったよう**に見える（初版で踏んだ）。
    ブロックが直方体になったので、4 つの側面だけに貼れば足りる。
    """
    xs, ys, zs = np.meshgrid(np.arange(V), np.arange(V), np.arange(h), indexing='ij')
    shell = np.zeros((V, V, h), bool)
    shell[0, :, :] = shell[V - 1, :, :] = True
    shell[:, 0, :] = shell[:, V - 1, :] = True
    shell[:, :, 0] = False  # 接地層は触らない（罠 5 の習慣）
    pick = rng.choice(shades, size=((V + 1) // 2, (V + 1) // 2, (h + 1) // 2), p=p)
    pickv = np.repeat(np.repeat(np.repeat(pick, 2, axis=0), 2, axis=1), 2, axis=2)[:V, :V, :h]
    for width in (3.0, 2.2, 1.6):
        nx, ny = rng.uniform(-1, 1), rng.uniform(-1, 1)
        nz = rng.uniform(-0.35, 0.35)
        d = xs * nx + ys * ny + zs * nz
        c = float(rng.uniform(d.min() + 2, d.max() - 2))
        band = np.abs(d - c) < width
        m = band & shell & (v > 0)
        v[m] = pickv[m]


def wall_rock(name):
    """岩肌の壁 — **掘り抜いた洞窟の壁**（P10 第 4 期。イークの洞穴とオークの洞窟）。

    2026-08-10 に決めた:「イークもオークも壁は**岩肌**（ゴツゴツしたかんじ、
    **砂地の点描とは違う**）で」。部屋の壁の既定は切石積み（`masonry`）だが、
    手掘りの穴と獣の巣に切石は積まれていない。

    **「ゴツゴツ」は塊で作る。**`crag`（岩山）で通した道と同じで、

    ==========================  ==============================================
    えぐりを **4 ボクセルの塊**  1 ボクセルずつ凹ませると三角形が跳ね上がるうえ、
    単位で 0〜3 ボクセル          寄ると**毛羽立ち**にしか見えない
    色も **4×4×4 の塊**単位      1 ボクセルずつ振ると**砂粒の斑**になる（罠 38）。
                                 これが「砂地の点描」である
    ==========================  ==============================================

    **直方体・高さ 1.0 マス・天面は平ら**は崩さない（2026-08-09 に決めた:
    「削れた状態は行動不能の壁として判別がつきにくいのでブロック状を維持」
    「壁ブロックの高さが異なるのも地形判別がつきづらくなるので統一しよう」）。
    ゴツゴツは**側面だけ**に出す。接地層と天面を彫らないのは `_carve_relief` の仕事。

    岩盤（`bedrock`）との差は**えぐりの深さと粒**である。岩盤は 1〜2 ボクセルの
    浅いえぐれ＋ 1 ボクセルの色の染みで「切り立った地層」、こちらは 3 ボクセルまで
    塊で抉れた「人と獣が広げた穴」。色は同じ `rock_*` を使うので、同じ洞窟の中で
    材が食い違わない。
    """
    rng = rng_for(name)
    h = WALL_H
    #! 層理（下ほど暗い）。`bedrock` と同じ帯だが、塊の明暗を上から掛けて崩す。
    bands = [C['rock_dd'], C['rock_d'], C['band'], C['rock'], C['rock_l']]
    palette = np.array(bands, np.uint8)
    band_at = np.minimum((np.arange(h) * len(bands)) // h, len(bands) - 1)
    v = np.broadcast_to(palette[band_at], (V, V, h)).copy()

    #! 塊ごとの明暗（4×4×4）。**明るい石は少なめ**（岩盤と同じ理由。等確率にすると白くまだらになる）。
    grow = (lambda a: np.repeat(np.repeat(np.repeat(a, 4, 0), 4, 1), 4, 2)[:V, :V, :h])
    shape = ((V + 3) // 4, (V + 3) // 4, (h + 3) // 4)
    lump = rng.choice(bands, size=shape, p=[0.20, 0.30, 0.12, 0.28, 0.10]).astype(np.uint8)
    v = np.where(grow(rng.random(shape) < 0.52), grow(lump), v).astype(np.uint8)

    #! 側面のえぐり。**格子に乗せない**（初版は 4×4 のマス目ごとに深さを引いていて、
    #! 「四角い穴の並び」＝窓の壁に見えた）。大きさも位置もばらばらの矩形で抉り、
    #! **重ねる**ことで縁が折れる。岩盤（`bedrock`）との差は深さ（1〜2 → 1〜3）と、
    #! 色を 1 ボクセルの染みではなく塊で置いていること。
    for face in range(4):
        for _ in range(16):
            du = int(rng.integers(3, 12))
            dw = int(rng.integers(3, 11))
            u0 = int(rng.integers(-3, V - 2))
            w0 = int(rng.integers(1, max(2, h - 4)))
            depth = int(rng.choice([1, 2, 3], p=[0.40, 0.37, 0.23]))
            _carve_relief(v, face, u0, u0 + du, w0, w0 + dw, depth)
            #! 抉った底は暗い岩（穴として読める）。深いほど暗く。
            _paint_face(v, face, u0, u0 + du, max(w0, 1), min(w0 + dw, h - 1), depth,
                        C['rock_dd'] if depth >= 2 else C['rock_d'])

    #! 天面。**明るくしない**（見下ろすカメラでは天面が絵の大半を占める。明るいと
    #! 床より明るくなって「壁が手前にある」と読めなくなる＝岩盤と同じ）。塊で 2 色。
    face_top = rng.choice([C['rock_d'], C['rock_dd']], size=((V + 3) // 4, (V + 3) // 4),
                          p=[0.62, 0.38]).astype(np.uint8)
    v[:, :, h - 1] = np.repeat(np.repeat(face_top, 4, 0), 4, 1)[:V, :V]
    return [('main', v, (0, 0, 0))]


def _spall(v, face, rng, u0, u1, w0, w1, steps=2):
    """貝殻状の剥離を 1 枚（黒曜石が割れた跡）。**矩形の段**で彫る。

    丸く彫ってはならない。曲線の縁は階段状の面になって岩肌（`wall_rock`）に寄り、
    「磨いてある」の読みが消える（そのうえ三角形も跳ね上がる。設計書 §6 の実測で、
    岩肌は 866・切石は 404 三角形）。**平らな面が段で重なる**のが貝殻状断口の形で、
    これなら greedy がまとまる。

    段は**片側へ寄せる**。同心に重ねると的の模様になり、割れではなく彫刻に見える。

    **底は塗らない**（初版は `obs_l` を敷いて明るくしていた）。窪みの底を地の色より
    明るくすると、窪みではなく**貼った板**に見える——実際そう出た（2026-08-13 の 1 回目。
    金属の箱のようになり、作り直した）。暗い磨き石で深さを言うのは AO と陰であって
    色ではない。色を足すのは**縁に当たる光**だけ、それも短く刻む。
    """
    top = v.shape[2] - 1
    for d in range(1, steps + 1):
        if ((u1 - u0) < 4) or ((w1 - w0) < 4):
            return
        _carve_relief(v, face, u0, u1, w0, w1, d)
        #! 縁の光。**面の幅いっぱいに引かない**（長い 1 本は棒に見える。1 回目の失敗）。
        if rng.random() < 0.55:
            lit = int(rng.integers(3, 7))
            lu = int(rng.integers(u0, max(u0 + 1, u1 - lit)))
            _paint_face(v, face, lu, lu + lit, max(w0, 1), max(w0, 1) + 1, d - 1, C['obs_l'])
        if rng.random() < 0.5:
            u0 += int(rng.integers(2, 5))
            u1 -= 1
        else:
            u0 += 1
            u1 -= int(rng.integers(2, 5))
        w0 += 1
        w1 -= int(rng.integers(1, 4))


def _fissure(v, face, rng, u, w0, w1, depth):
    """割れ。**折れ線**で彫る（1 ボクセルずつ振ってはならない）。

    ボクセル単位で蛇行させると設計書 §6(c) の禁じる無作為ノイズそのものになる
    （実測 180 倍）。**真っ直ぐな段を数本、折れ目でずらす**——黒曜石の割れは
    そもそも角ばっているので、形の側からもこちらが正しい。
    """
    top = v.shape[2] - 1
    w = w0
    cur = u
    while w < w1:
        w_end = min(w + int(rng.integers(5, 12)), w1)
        _carve_relief(v, face, cur, cur + 1, w, w_end, depth)
        _paint_face(v, face, cur, cur + 1, max(w, 1), min(w_end, top), depth, C['obs_d'])
        w = w_end
        cur = max(1, min(V - 2, cur + int(rng.integers(-2, 3))))


def _top_fissure(v, rng):
    """天面の割れ。**天面は手で掘る**（`_carve_relief` は天面を守るので側面の口では届かない）。

    見下ろすカメラでは天面が絵の大半を占めるので、ここが単色だと側面に何を彫っても
    「無地のブロック」に見える（この改修の発端がそれである）。深さは 1 段だけに留める
    ——高さが揃って見えることは地形の判別そのものなので崩さない。
    """
    top = v.shape[2] - 1
    along_x = bool(rng.random() < 0.5)
    a = int(rng.integers(3, V - 3))
    b = 0
    while b < V:
        b_end = min(b + int(rng.integers(5, 12)), V)
        if along_x:
            v[a, b:b_end, top] = 0
            v[a, b:b_end, top - 1] = C['obs_d']
        else:
            v[b:b_end, a, top] = 0
            v[b:b_end, a, top - 1] = C['obs_d']
        b = b_end
        a = max(1, min(V - 2, a + int(rng.integers(-2, 3))))


def wall_perm(name):
    """永久壁 — 磨かれた黒曜石。貝殻状の剥離と角ばった割れの入った面。

    **色は変えない**（`obs` 系の 3 色のまま。2026-08-13 に決めた:「色合いはこの
    ままに凹凸クラックを入れて 10 種類の変種をつくろう」）。替えるのは形だけである。

    初版は**凹凸をまったく持たない 1 枚の箱**だった——「磨かれていることが『壊せない
    壁』の記号なので、岩肌にすると岩盤と区別が付かなくなる」という理屈で、これ自体は
    今も正しい。誤っていたのは**変種を 1 枚も持たせなかった**ことである。永久壁は
    クエスト階の壁のほとんどを占める（固定マップ 24 本で永久壁 12,685 マス／花崗岩
    3,013 マス。盗賊の隠れ家・オーク野営地・産卵場などは 100%）ので、無地の面 1 枚が
    視界を丸ごと埋めていた。

    そこで**磨きの読みは色と縦の筋に預け**、凹凸は「磨いた面が割れた」形だけにする。

    | 何を入れるか | なぜその形か |
    |---|---|
    | 貝殻状の剥離（`_spall`） | 黒曜石の割れ方そのもの。段で作るので岩肌に寄らない |
    | 角ばった割れ（`_fissure`） | 硝子質の割れは折れ線。曲がりくねらせると溶岩の亀裂になる |
    | 天面の割れ（`_top_fissure`） | 見下ろすカメラでは天面がいちばん広い。ここが無地だと全部無地に見える |
    | 稜の光（`obs_h`） | 段の下辺だけ。磨いた面が割れたことは**光の乗り方**でしか言えない |

    **10 枚のうち 2 枚（`_03` / `_07`）だけ大きく剥離している。**全部に大きな剥離を
    入れると割れた壁の部屋になる（罠 114 と同じ話で、マスの単位で必ず在るものは模様に
    なる）。要所で 1 枚だけ大きく欠けているから「硬い石が割れた」に見える。
    """
    rng = rng_for(name)
    h = WALL_H
    idx = int(name[-2:]) if name[-2:].isdigit() else 0
    v = np.full((V, V, h), C['obs'], np.uint8)
    for face in range(4):
        #! 磨いた面の縦の筋（初版から在る「黒曜石らしさ」。彫る前に置く）。
        for _ in range(int(rng.integers(2, 5))):
            u = int(rng.integers(1, V - 2))
            w0 = int(rng.integers(0, h // 2))
            w1 = int(rng.integers(h // 2, h - 1))
            _paint_face(v, face, u, u + 1, w0, w1, 0, C['obs_l'])
        #! **面取りは付けない。**上端を通しで引っ込めると、天面が別の板に見える
        #! （1 回目に入れて「蓋の載った箱」になった）。永久壁は 1 枚の石である。
        #! **割れが先・剥離が後。**逆にすると、剥離で空いた所へ割れの底を描いて
        #! 宙に 1 ボクセル浮く（`_paint_face` は深さを指定して塗るだけで、そこが
        #! 空かどうかを見ない）。剥がれた片が割れごと落ちた、と読めば形の側も合う。
        for _ in range(int(rng.integers(1, 3))):
            #! 深さは 1 段だけ。2 段彫ると溝の側面まで見えて**継ぎ目の線**に見える。
            _fissure(v, face, rng, int(rng.integers(3, V - 3)), int(rng.integers(1, 6)),
                     int(rng.integers(h - 8, h - 3)), 1)
        if idx in (3, 7):
            #! 大きな剥離。面の半分ほどを 3 段で持っていく。
            _spall(v, face, rng, 5, 27, 3, h - 8, steps=3)
        #! **1〜2 枚まで。**初版は 2〜4 枚彫っていて、面が窪みで埋まり
        #! 「板を貼った箱」になった。磨いた面が残っていないと磨きは読めない。
        for _ in range(int(rng.integers(1, 3))):
            u0 = int(rng.integers(1, V - 8))
            w0 = int(rng.integers(1, h - 12))
            _spall(v, face, rng, u0, u0 + int(rng.integers(6, 14)),
                   w0, w0 + int(rng.integers(6, 15)), steps=2)
    #! 天面。**明るくしない**（`wall_rock` と同じ理由。見下ろすカメラでは天面が絵の
    #! 大半を占めるので、床より明るいと「壁が手前にある」が読めなくなる）。
    #!
    #! 地は初版と同じ `obs_l` 一色にして、**斜めに切った半面**を 1〜2 枚暗く落とす。
    #!
    #! 書き方を 2 度替えている。4×4 の塊で 2 色に振る（`wall_rock` の天面）と
    #! **市松模様**になり、矩形の斑を置くと**貼った紙**に見えた。どちらも境がマスの目に
    #! 揃うのが理由である。斜めの境ならマスの目から外れるので、「割れた面がわずかに
    #! 向きを変えている」——黒曜石の天面に在ってよい唯一の情報——として読める。
    #! 天面は平らなままなので、この 3 つはどれも三角形を 1 枚も増やさない（色だけ）。
    v[:, :, h - 1] = C['obs_l']
    _xs = np.arange(V)[:, None]
    _ys = np.arange(V)[None, :]
    for _ in range(int(rng.integers(1, 3))):
        na = float(rng.uniform(-1.0, 1.0))
        nb = float(rng.uniform(-1.0, 1.0))
        nc = (na + nb) * (V / 2.0) + float(rng.uniform(-9.0, 9.0))
        layer = v[:, :, h - 1]
        layer[(_xs * na + _ys * nb) > nc] = C['obs']
    #! 稜の光。**四辺を通しで塗らない**——マスごとに同じ枠を描くと、並べたとき天面が
    #! 格子模様になる（罠 114「マスの単位で規則的に置いたものは必ず模様になる」）。
    #! 短く刻んで、隣とつながる所とつながらない所を作る。
    for edge in range(4):
        u = 0
        while u < V:
            u_end = min(u + int(rng.integers(3, 8)), V)
            if rng.random() < 0.42:
                if edge == 0:
                    v[u:u_end, 0, h - 1] = C['obs_h']
                elif edge == 1:
                    v[u:u_end, V - 1, h - 1] = C['obs_h']
                elif edge == 2:
                    v[0, u:u_end, h - 1] = C['obs_h']
                else:
                    v[V - 1, u:u_end, h - 1] = C['obs_h']
            u = u_end
    for _ in range(int(rng.integers(1, 4))):
        _top_fissure(v, rng)
    return [('main', v, (0, 0, 0))]


def pillar(name):
    """柱 — 台座・柱身（エンタシス）・柱頭。部屋の縁に置く。"""
    h = 54
    v = np.zeros((V, V, h), np.uint8)
    cx = cy = V // 2

    def disc(z0, z1, r, c):
        for z in range(z0, z1):
            for x in range(V):
                for y in range(V):
                    if (x - cx + 0.5) ** 2 + (y - cy + 0.5) ** 2 <= r * r:
                        v[x, y, z] = c

    disc(0, 2, 8.4, C['wall_d'])
    disc(2, 4, 7.2, C['wall'])
    for z in range(4, 45):
        r = 5.6 - (z - 4) * 0.022  # わずかにすぼめる
        disc(z, z + 1, r, C['wall'] if (z % 9) else C['wall_l'])
    disc(45, 48, 6.6, C['wall_l'])
    disc(48, 50, 7.4, C['wall'])
    v[cx - 7:cx + 7, cy - 7:cy + 7, 50:53] = C['wall_d']
    return [('main', v, (0, 0, 0))]


# ------------------------------------------------------------------ 扉と階段
def _door_frame(v):
    """扉の枠 — **木の太枠**（方立て 2 本＋前へ出た楣）。

    2026-08-09 に決めた「扉と判別しづらい。もっと扉の意匠に近づけて」。
    初版の石の枠は壁と同じ灰色で、壁の続きにしか見えなかった。石の壁の中に
    **素材の違う木**が立っていることが「扉」の第一の記号になる。
    """
    v[0:5, 12:20, 0:30] = C['timber_d']  # 方立て（壁より 1 ボクセル前へ）
    v[27:32, 12:20, 0:30] = C['timber_d']
    v[1:4, 12, 2:28] = C['timber']  # 南面の面取りの筋
    v[28:31, 12, 2:28] = C['timber']
    v[1:4, 19, 2:28] = C['timber']  # 北面も同じ（扉は両側から見える）
    v[28:31, 19, 2:28] = C['timber']
    v[0:32, 11:21, 26:30] = C['timber']  # 楣（さらに 1 ボクセル前へ張り出す）
    v[0:32, 11:21, 29] = C['timber_l']
    v[0:32, 13:19, 30:36] = C['wall_d']  # 楣の上の石の詰め（壁と繋がる）


def _door_panel_face(panel, y_face, y_stud):
    """板面 1 つぶんの金物（鉄帯 2 本・鋲・蝶番）。両面に同じものを付ける。"""
    panel[5:27, y_face, 5:8] = C['iron']  # 鉄帯
    panel[5:27, y_face, 18:21] = C['iron']
    for x in range(7, 27, 4):  # 鋲（帯の上に 1 ボクセル浮き出る）
        panel[x, y_stud, 6] = C['iron_l']
        panel[x, y_stud, 19] = C['iron_l']
    panel[5:8, y_stud, 3:7] = C['iron_l']  # 蝶番（左の方立て側に 2 枚）
    panel[5:8, y_stud, 20:24] = C['iron_l']


def door_closed(name):
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.uint8)
    _door_frame(v)
    panel = np.zeros((V, V, 36), np.uint8)
    for x in range(5, 27, 4):  # 縦の樫板（明るい 2 色。暗い扉は壁に沈む）
        shade = rng.choice([C['oak'], C['oak_l'], C['timber_l']], p=[0.45, 0.35, 0.2])
        panel[x:x + 4, 14:18, 0:26] = shade
    _door_panel_face(panel, 14, 13)  # 南面（既定のカメラが見る側）
    _door_panel_face(panel, 17, 18)  # 北面
    # 鉄輪の取っ手（右手側・南面に 1 ボクセル浮き出る環）。
    panel[20:25, 13, 10:15] = C['iron_l']
    panel[21:24, 13, 11:14] = 0
    panel[22, 14, 14] = C['iron']  # 環の吊り金具
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def door_open(name):
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.uint8)
    _door_frame(v)
    panel = np.zeros((V, V, 36), np.uint8)
    for y in range(18, 30, 4):  # 開いた板は左の方立てから奥（+y）へ 90° 畳む
        shade = rng.choice([C['oak'], C['oak_l'], C['timber_l']], p=[0.45, 0.35, 0.2])
        panel[5:9, y:y + 4, 0:26] = shade
    panel[5, 18:30, 5:8] = C['iron']  # 鉄帯（開いた面にも見える）
    panel[5, 18:30, 18:21] = C['iron']
    for y in range(19, 30, 4):
        panel[4, y, 6] = C['iron_l']  # 鋲
        panel[4, y, 19] = C['iron_l']
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def door_broken(name):
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.uint8)
    _door_frame(v)
    panel = np.zeros((V, V, 36), np.uint8)
    for x in range(5, 27, 4):  # 下だけ残った板。上端はぎざぎざ
        shade = rng.choice([C['oak'], C['timber_l'], C['timber']], p=[0.4, 0.35, 0.25])
        panel[x:x + 4, 14:18, 0:int(rng.integers(4, 13))] = shade
    panel[5:27, 14, 5:8] = C['iron']  # 折れ残った鉄帯
    panel[8:16, 20:23, 0:2] = C['timber_d']  # 床に倒れた板
    panel[18:27, 24:27, 0:2] = C['oak']
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def _glass_frame(v):
    """ガラスの扉の枠 — **磨いた鋼の細枠**。

    樫の扉（`_door_frame`）と同じ「方立て 2 本＋前へ出た楣」の骨組みだが、材を鋼に替え、
    **枠を細くする**（樫は 5 ボクセル幅、こちらは 3）。硝子の扉は「枠が細くて中が明るい」
    ことで読ませるもので、太い枠にすると板の面積が減って樫の扉の色違いにしか見えない。

    鋼（`steel` = 196,202,212）を使うのは、暗い壁の前で枠が沈まないようにするため
    （`iron` = 56,54,58 は影と同じ明度になる。`glass_sconce` の注記と同じ話）。
    """
    v[0:3, 13:19, 0:30] = C['steel_d']  # 方立て
    v[29:32, 13:19, 0:30] = C['steel_d']
    v[0:3, 13, 2:28] = C['steel']  # 南面の稜（光が乗る辺）
    v[29:32, 13, 2:28] = C['steel']
    v[0:3, 18, 2:28] = C['steel']  # 北面も同じ（扉は両側から見える）
    v[29:32, 18, 2:28] = C['steel']
    v[0:32, 12:20, 26:30] = C['steel_d']  # 楣（1 ボクセル前へ張り出す）
    v[0:32, 12:20, 29] = C['steel']
    v[0:32, 13:19, 30:36] = C['wall_d']  # 楣の上の石の詰め（壁と繋がる）


def _glass_pane(panel, x0, x1, z0, z1, y0=15, y1=17):
    """硝子 1 枚。**斜めの照りを 1 本だけ入れる。**

    面を 1 色で塗ると板ガラスではなく水色の板に見える。斜めの帯を 1 本走らせると、
    見る角度で光る面＝硝子の記号になる（塊ごとに 1 色＝罠 38 は守る。帯は 2 ボクセル幅）。
    """
    panel[x0:x1, y0:y1, z0:z1] = C['pane']
    panel[x0:x1, y0:y1, z0:z0 + 2] = C['pane_d']  # 下端は濁る（埃と傷）
    span = (x1 - x0) + (z1 - z0)
    for k in range(span):
        x = x0 + int(k * (x1 - x0) / max(1, span - 1))
        z = z1 - 1 - int(k * (z1 - z0) / max(1, span - 1))
        if (x0 <= x < x1) and (z0 <= z < z1):
            panel[x:min(x + 2, x1), y0:y1, z:min(z + 2, z1)] = C['pane_l']


def _glass_muntins(panel):
    """桟（縦 1 本・横 2 本）。**硝子より暗い鋼**で、板を 6 枚に割る。"""
    for x in (3, 15, 27):
        panel[x:x + 2, 14:18, 0:26] = C['steel_d']
    for z in (0, 12, 24):
        panel[3:29, 14:18, z:z + 2] = C['steel_d']


def door_glass_closed(name):
    """閉じたガラスの扉（`CLOSED_GLASS_DOOR` ほか 16 種）。細い鋼の枠に 4 枚の硝子。"""
    del name  # 硝子は磨いてあるので散らさない（樫の扉と違って変種の種を持たない）
    v = np.zeros((V, V, 36), np.uint8)
    _glass_frame(v)
    panel = np.zeros((V, V, 36), np.uint8)
    for x0, x1 in ((5, 15), (17, 27)):
        for z0, z1 in ((2, 12), (14, 24)):
            _glass_pane(panel, x0, x1, z0, z1)
    _glass_muntins(panel)
    # 引き手（右手側・南面に浮き出る縦の握り。樫の扉の鉄輪に当たるもの）。
    panel[24:27, 12, 9:17] = C['steel']
    panel[24:27, 13, 9:10] = C['steel_d']
    panel[24:27, 13, 16:17] = C['steel_d']
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def door_glass_open(name):
    """開いたガラスの扉。板は樫の扉と**同じ側**（左の方立てから奥へ 90°）へ畳む。"""
    del name
    v = np.zeros((V, V, 36), np.uint8)
    _glass_frame(v)
    panel = np.zeros((V, V, 36), np.uint8)
    # 畳んだ板は **xz ではなく yz に立つ**ので、`_glass_pane`（x で走る）は使えない。
    # 照りの帯だけ y 方向へ引き直す（意匠は閉じた扉と同じ「斜めに 1 本」）。
    for y0, y1 in ((20, 29),):
        for z0, z1 in ((2, 12), (14, 24)):
            panel[3:7, y0:y1, z0:z1] = C['pane']
            panel[3:7, y0:y1, z0:z0 + 2] = C['pane_d']
            for k in range(min(y1 - y0, z1 - z0)):
                panel[3:7, y0 + k, z1 - 1 - k] = C['pane_l']
    for y in (18, 29):  # 桟（畳んだ板の端）
        panel[3:7, y:y + 2, 0:26] = C['steel_d']
    for z in (0, 12, 24):
        panel[3:7, 18:31, z:z + 2] = C['steel_d']
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def door_glass_broken(name):
    """割れたガラスの扉。桟は残り、硝子は縁だけ。**床に破片が散る**。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.uint8)
    _glass_frame(v)
    panel = np.zeros((V, V, 36), np.uint8)
    _glass_muntins(panel)
    #! **破片は 1 ボクセルの薄板にする。**初版は無傷の板と同じ 2 ボクセル厚で、しかも
    #! 桟の**下**から生やしたので、白い塊が棚に並んでいるように見えた（絵で見つけた）。
    #! 割れた硝子は枠に噛んだまま残るものなので、**上の桟からぶら下げ、下の桟から生やす**。
    #! 厚みを半分にすると光が当たる面が減り、同じ色でも塊ではなく板に戻る。
    for x0, x1 in ((5, 15), (17, 27)):
        for z0, z1 in ((2, 12), (14, 24)):
            for x in range(x0, x1):
                hang = int(rng.integers(0, 5))  # 上の桟からぶら下がる牙
                if hang:
                    panel[x, 16, z1 - hang:z1] = C['pane']
                    if (x % 5) == 0:
                        panel[x, 16, z1 - hang] = C['pane_l']  # 割れ口の稜は 5 本に 1 本
                stand = int(rng.integers(0, 3))  # 下の桟に残った縁
                if stand:
                    panel[x, 16, z0:z0 + stand] = C['pane_d']
            for z in range(z0, z1):  # 縦の桟に沿って残る細い帯
                if int(rng.integers(0, 3)) == 0:
                    panel[x0, 16, z] = C['pane_d']
                if int(rng.integers(0, 3)) == 0:
                    panel[x1 - 1, 16, z] = C['pane_d']
    for _ in range(10):  # 床の破片（**寝かせて**散らす。立てると氷柱に見える）
        x = int(rng.integers(3, 28))
        y = int(rng.integers(10, 23))
        panel[x:x + 2, y:y + 2, 0:1] = C['pane_d']
        panel[x:x + 1, y:y + 1, 1:2] = C['pane']  # 反った角だけ 1 段浮かす
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def _curtain_rod(v):
    """帳の吊り棒（枠は無い）。**扉と違って枠を持たない**のが帳の読みなので、
    上に鋼の棒が 1 本渡っているだけにする。両端の受け金具で壁に留める。"""
    v[0:32, 15:18, 27:30] = C['steel_d']
    v[0:32, 15, 28] = C['steel']
    v[0:3, 14:19, 25:31] = C['steel_d']  # 受け金具
    v[29:32, 14:19, 25:31] = C['steel_d']
    v[0:32, 13:19, 31:36] = C['wall_d']  # 棒の上の石の詰め（壁と繋がる）


def curtain_closed(name):
    """閉じた帳（`CLOSED_CURTAIN`）。棒から床まで垂れた布。**襞は縦の色の列**で出す。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.uint8)
    _curtain_rod(v)
    panel = np.zeros((V, V, 36), np.uint8)
    for x in range(1, 31, 3):  # 襞（3 ボクセルごとに明暗を替え、前後にも 1 ボクセル振る）
        shade = rng.choice([C['drape'], C['drape_l'], C['drape_d']], p=[0.4, 0.3, 0.3])
        bulge = int(rng.integers(0, 2))
        hem = int(rng.integers(0, 3))  # 裾の乱れ
        panel[x:x + 3, 15 - bulge:18 + bulge, hem:28] = shade
        panel[x:x + 3, 15 - bulge, hem:28] = C['drape_l'] if (shade != C['drape_l']) else C['drape']
    panel[1:31, 14:19, 26:28] = C['drape_d']  # 棒に通した上端（きゅっと寄る）
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def curtain_open(name):
    """開いた帳（`OPEN_CURTAIN`）。左右の柱際へ**寄せて束ねた**布。真ん中は抜ける。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.uint8)
    _curtain_rod(v)
    panel = np.zeros((V, V, 36), np.uint8)
    for x0 in (1, 24):
        for x in range(x0, x0 + 7, 2):
            shade = rng.choice([C['drape'], C['drape_l'], C['drape_d']], p=[0.4, 0.3, 0.3])
            bulge = int(rng.integers(1, 3))
            hem = int(rng.integers(0, 4))
            panel[x:x + 2, 15 - bulge:18 + bulge, hem:28] = shade
            panel[x:x + 2, 15 - bulge, hem:28] = C['drape_l'] if (shade != C['drape_l']) else C['drape']
        panel[x0:x0 + 7, 13:20, 10:14] = C['gold_d']  # 括り紐（束ねている所）
        panel[x0:x0 + 7, 13, 11:13] = C['gold']
    panel[1:8, 14:19, 26:28] = C['drape_d']  # 上端は棒に通したまま
    panel[24:31, 14:19, 26:28] = C['drape_d']
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


def rotate_parts_90(parts):
    """xy 平面で 90° 回した写しを返す（**1 マス＝32x32 の素材専用**）。

    設計書 §7.1-2 は「向きはデータを 1 方向で持ち、姿勢のほうを用意する」と言っている。
    ボクセルの 90° 回転は**再サンプリング無しで厳密**なので、形は 1 ボクセルも崩れない。
    ここで作るのは「同じ意匠の別姿勢」であって、別デザインではない。
    """
    out = []
    for part_name, v, origin in parts:
        if (v.shape[0] != V) or (v.shape[1] != V):
            raise ValueError('回せるのは 1 マス（32x32）の素材だけです: %s' % part_name)
        if (origin[0] != 0) or (origin[1] != 0):
            raise ValueError('原点がマスの隅にない素材は回せません: %s' % part_name)
        out.append((part_name, np.ascontiguousarray(np.rot90(v, k=1, axes=(0, 1))), origin))
    return out


def rotated(builder):
    """`_ew` の付いた名前で呼ばれたら、**同じ種で**基の形を作って 90° 回す。

    種を基の名前から引くので、板の色の散らし方まで基と同一になる（＝意匠は 1 つ）。
    """
    return lambda n: rotate_parts_90(builder(n[:-3] if n.endswith('_ew') else n))


def arch_stone(name):
    """自立した門（§10.3）。扉の無い口・店の入口。楣の下面を弧に彫る。"""
    v = np.zeros((V, V, 40), np.uint8)
    v[0:6, 13:19, 0:40] = C['wall']
    v[26:32, 13:19, 0:40] = C['wall']
    v[0:32, 13:19, 30:40] = C['wall']
    for x in range(6, 26):  # 弧（中央ほど高く抜く）
        t = (x - 15.5) / 9.5
        rise = int(round(4.5 * (1.0 - t * t)))
        v[x, 13:19, 30:30 + rise] = 0
    v[13:19, 13:19, 36:40] = C['wall_l']  # 要石
    v[0:6, 13:19, 28:30] = C['wall_l']  # 台輪
    v[26:32, 13:19, 28:30] = C['wall_l']
    return [('main', v, (0, 0, 0))]


def arch_noren(name):
    """**暖簾の口**（和風の門・案 A。2026-08-17）。素木の柱に竿を渡し、藍の暖簾を垂らす。

    `arch_stone` の置き換えなので**寸法と姿勢はあちらに合わせる**——1 マス・厚みは y 13..19、
    「南北にくぐる」形が基で、東西は `rotated()` が作る。カメラは **+y の面**を見る
    （`signboard()` の註記）ので、**布は y の大きい側へ 1 ボクセル出す**。出さないと柱と同じ
    平面に沈んで、遠目で「柱の間の影」に見える。

    暖簾は**3 枚に割れている**のが読みの要（切れ目が無いと壁に見えて「通れない」と読まれる）。
    上端だけ繋げ、下は抜く。
    """
    v = np.zeros((V, V, 40), np.uint8)

    # 柱（素木）。根元に礎石を噛ませる——土に直に立てると「棒を刺した」ように見える。
    for x0, x1 in ((0, 5), (27, 32)):
        v[x0:x1, 13:19, 0:32] = C['oak']
        v[x0:x1, 18, 2:32] = C['oak_l']  # カメラ側の面を明るく（丸みの代わり）
        v[x0:x1, 13:19, 0:3] = C['wall']  # 礎石
        v[x0:x1, 18, 0:3] = C['wall_l']

    # 竿（暖簾を掛ける横木）。柱より前後に張り出す。
    v[0:32, 12:20, 32:37] = C['oak']
    v[0:32, 12:20, 36] = C['oak_l']  # 天面
    v[0:32, 19, 32:36] = C['oak_l']

    # 暖簾（藍地）。カメラ側へ 1 ボクセル出す。
    rng = rng_for(name)
    for x in range(5, 27):
        hem = 14 + int(rng.integers(0, 3))  # 裾のばらつき（風でめくれた感じ）
        v[x, 18:20, hem:32] = C['ai']
        v[x, 19, hem:32] = C['ai_l'] if (x % 7 < 4) else C['ai']  # 布の縦じわ
        v[x, 18:20, 30:32] = C['ai_d']  # 竿に巻き込む上端は影

    # 白抜きの帯 2 本（屋号の代わり。32px では字にならない——研究報告の代替案）。
    v[7:25, 19, 24:26] = C['nuki']
    v[7:25, 19, 21:22] = C['nuki']

    # 切れ目 2 本（3 枚に割る）。**上端は残す**（竿から垂れているので）。
    for x0, x1 in ((11, 13), (19, 21)):
        v[x0:x1, 18:20, 14:30] = 0

    return [('main', v, (0, 0, 0))]


def arch_kido(name):
    """**木戸**（和風の門・案 B。2026-08-17）。冠木門に杉皮の庇と縦格子を載せた形。

    暖簾（案 A）との差は **屋根があること**。遠目では「布の面」か「屋根の線」かで分かれる。
    寸法と姿勢は `arch_stone` に合わせる（§ `arch_noren` の註記と同じ）。
    """
    v = np.zeros((V, V, 46), np.uint8)

    # 柱（角材。面取りの筋を入れて丸太と区別する）。
    for x0, x1 in ((0, 6), (26, 32)):
        v[x0:x1, 13:19, 0:34] = C['timber']
        v[x0 + 1:x1 - 1, 18, 3:34] = C['timber_l']  # 面取り
        v[x0:x1, 13:19, 0:3] = C['wall']  # 根巻きの石
        v[x0:x1, 18, 0:3] = C['wall_l']

    # 冠木（上の横木）。柱より前後に張り出す。
    v[0:32, 11:21, 34:40] = C['oak']
    v[0:32, 20, 34:40] = C['oak_l']

    # 縦格子（冠木の下だけ。**下は通れるよう空ける**）。
    for x in range(8, 25, 3):
        v[x:x + 2, 15:18, 26:34] = C['timber_d']
        v[x:x + 2, 17, 26:34] = C['timber']

    # 杉皮の庇。**前（＝カメラ側の +y）へ深く出して下へ落とす**——軒が深いことが和風の読み
    # そのものである。奥（y 小）が棟、手前（y 大）が軒先。段ごとに **z の位置を下げる**
    # （厚みを削るのではない。削ると手前の列が消える——一度そう書いて気づいた）。
    # 勾配は **1 段で 2 落とす**。1 ずつだと寝すぎて「横縞のひさし」に見えた（試作で気づいた）。
    # 明部は**段の手前 1 列だけ**に置く——段の天面を丸ごと明るくすると鎧戸の羽根に見える。
    for i in range(5):
        y0 = 13 + i * 3
        zb = 40 - i * 2
        v[0:32, y0:y0 + 3, zb:zb + 3] = C['sugi']
        v[0:32, y0 + 2, zb + 2] = C['sugi_l']  # 葺きの段の頭（軒と平行な線になる）

    return [('main', v, (0, 0, 0))]


def stairs_down(name):
    """降り階段。天面から +y へ段を彫り、いちばん奥は暗がりへ落とす。
    地面ごと置き換えるタイルである（origin_z=-8。footprint は空 = 歩ける）。"""
    v = np.zeros((V, V, 8), np.uint8)
    v[:, :, :] = C['pav_d']
    v[:, :, 0] = C['dark']
    steps = ((0, 8, 8), (8, 14, 6), (14, 20, 4), (20, 26, 2), (26, 32, 1))
    for y0, y1, top in steps:
        v[3:29, y0:y1, top:8] = 0  # 段の上を抜く
        if top > 1:
            v[3:29, y0:y1, top - 1] = C['pav_l']  # 踏み面
    v[3:29, 26:32, 1] = C['dark']  # 最奥は闇
    v[3:29, 25, 1:2] = C['dark']
    v[0:3, :, 7] = C['pav']  # 左右の親柱（天面の縁）
    v[29:32, :, 7] = C['pav']
    return [('main', v, (0, 0, -8))]


def stairs_up(name):
    """上り階段。+y の奥へ向かって上がる直階段。床の上に置く。"""
    v = np.zeros((V, V, 30), np.uint8)
    steps = ((26, 32, 4), (20, 26, 10), (14, 20, 16), (8, 14, 22), (0, 8, 28))
    for y0, y1, top in steps:
        v[4:28, y0:y1, 0:top] = C['pav_d']
        v[4:28, y0:y1, top - 1] = C['pav_l']  # 踏み面
    v[0:4, 0:32, 0:6] = C['pav']  # 左右の袖壁（低い）
    v[28:32, 0:32, 0:6] = C['pav']
    v[0:4, 0:8, 0:29] = C['pav']  # 奥の袖は高く
    v[28:32, 0:8, 0:29] = C['pav']
    return [('main', v, (0, 0, 0))]


# ------------------------------------------------------- 全体マップの目印（P10）
#! 2026-08-11 に気づいた「**全体マップで町のオブジェクトが無く見つけられない**」。
#!
#! 広域マップ（`<` で入る画面）は **1 マスが町ひとつ・山ひとつ**という縮尺で、町の作り込み
#! （設計書 §10.3。敷地を分解して家を建てる）はそのままでは載らない。かといってマスの色を
#! 変えるだけでは、草地と山の間に埋もれて探せない——**マスの上に立体を 1 つ置く**のが要る。
#!
#! 2 つに共通する決め事:
#! - **高さは 1.4〜1.5 マス**（45〜48 ボクセル）。山（`bedrock_*` = 1 マス）より高くしないと
#!   隣のマスに隠れる。逆に 2 マスを超えると南隣のマスを隠して地図が読めなくなる
#! - **輪郭で読ませる。**この縮尺では面の模様は 1 画素も見えないので、明暗の塊で
#!   「屋根が集まっている」「岩に穴が開いている」を言う
#! - **マスいっぱいには広げない**（縁 2 ボクセルを空ける）。隣のマスの目印と地続きに見えると
#!   町が 2 つ並んでいるのか 1 つ大きいのか分からなくなる
#!
#! **向きの決め事（ここで 1 度間違えた）**: 世界は **x = 東・y = 南**（`signboard()` の
#! §「裏面は左右を反転」に書いてある）で、カメラは注視点の **+y から**見下ろす
#! （`render/camera.cpp` の `eye()`）。つまり**カメラが見るのは y の大きい面**である。
#! 初版は口も門も y の小さい側へ向けたので、実機では裏側しか見えない箱になった。
#! `--prefab=` の既定の向き（azimuth 0.9rad）は**世界と同じ側**を見る。裏を見たいときは
#! `HD2D_PREFAB_AZIMUTH=270`。
def _gable_roof(v, x0, x1, y0, y1, z0, shade, shade_l):
    """切妻の屋根 — 棟は x 方向。**軒を 1 ボクセル出す**（出さないと箱の蓋に見える）。

    勾配は **1 段すぼめるごとに 2 段上げる**（＝約 63°）。1 対 1 で組んだ初版は
    8 マス幅の家に高さ 4 の屋根が乗り、真上から見ると**茶色い板が寝ている**ようにしか
    見えなかった（絵で見つけた）。広域マップの目印は輪郭で読ませるものなので、
    勾配は実物より立てる。

    **各段は下まで塗りつぶす**（1 層だけ置くと段どうしの間が抜けて、屋根ではなく
    棚板が 4 枚重なっているように見えた——これも絵で見つけた）。

    **明暗は段ごとに替えない。**k の偶奇で明暗を振った版は、屋根の斜面に横縞が入って
    「C の字の飾り」に見えた。明るいのは**棟の 1 本だけ**でよい。
    """
    #! 勾配は **2 行で 3 段**。1 行 2 段（63°）は段の踏み面が 1 ボクセルしか無く、
    #! 蹴上げが影に落ちて**棚板が積んである**ように見えた（絵で見つけた）。
    #! 1 行 1 段（45°）だと今度は屋根が低くて平たい。あいだを採る。
    depth = (y1 - y0 + 1) // 2
    top = z0
    for k in range(depth):
        z = min(v.shape[2], z0 + int(1.5 * (k + 1)) + 1)
        v[max(0, x0 - 1):x1 + 1, y0 + k, z0:z] = shade
        v[max(0, x0 - 1):x1 + 1, y1 - 1 - k, z0:z] = shade
        top = z
    v[max(0, x0 - 1):x1 + 1, y0 + depth - 1:y1 - depth + 1, z0:top] = shade  # 棟まわりを埋める
    v[max(0, x0 - 1):x1 + 1, y0 + depth - 1:y1 - depth + 1, top - 1:top] = shade_l  # 棟
    return top


def town_marker(name):
    """全体マップの町（`TOWN`）。**1 マスに町を 1 つ畳んだ模型**。

    残したのは遠目で「町だ」と分かる 4 つだけ——**塀で囲った輪郭**・**赤い切妻屋根が
    3 つ**・**南に開いた門**・**旗を掲げた櫓**。屋根を赤にするのは、広域マップの地色が
    草（緑）と岩（灰）と水（青）で埋まっていて、**暖色がひとつも無い**からである。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 46), np.uint8)
    # (1) 土壇。町は周りの野より一段高い所に建つ（塀の足元を地面から切り離す）。
    v[2:30, 2:30, 0:3] = C['pack']
    v[2:30, 2:30, 2] = C['pack_l']

    # (2) 塀（4 辺。**南 = y の大きい側**の中央だけ門のぶん空ける）。
    for x0, x1, y0, y1 in ((3, 29, 3, 5), (3, 29, 27, 29), (3, 5, 3, 29), (27, 29, 3, 29)):
        v[x0:x1, y0:y1, 3:11] = C['cob']
        v[x0:x1, y0:y1, 10] = C['cob_l']  # 天端（日の当たる辺）
    v[13:19, 27:29, 3:11] = 0  # 門の口

    # (3) 門。**脇柱を塀より高くする**（口が空いているだけでは門に見えない）。
    for x0 in (11, 18):
        v[x0:x0 + 3, 26:30, 3:16] = C['cob_d']
        v[x0:x0 + 3, 29, 4:15] = C['cob_l']
    v[11:21, 26:30, 14:17] = C['cob_d']  # 楣
    v[11:21, 29, 15:16] = C['cob_l']

    # (4) 家 3 軒。**大きさと向きを揃えない**（揃えると倉庫の列に見える）。
    #! **門の筋（x 13〜19）には建てない。**塞ぐと門が見えず、ただの囲いになる。
    houses = ((5, 13, 16, 26, 11), (19, 27, 17, 26, 10), (5, 12, 5, 14, 10))
    for x0, x1, y0, y1, wall_top in houses:
        v[x0:x1, y0:y1, 3:wall_top] = C['plas']
        v[x0:x1, y1 - 1, 3:wall_top] = C['plas_d']  # 南面はわずかに沈める（面の向き）
        shade, shade_l = ((C['roof_r'], C['roof_rl']) if rng.random() < 0.7
                          else (C['roof_rd'], C['roof_r']))
        _gable_roof(v, x0, x1, y0, y1, wall_top, shade, shade_l)

    # (5) 櫓と旗。**この町でいちばん高い所**（広域マップで最初に目に入る点）。
    #! 塔は**北**（y の小さい側）へ寄せる。マスの真ん中に立てると、南から見下ろすカメラでは
    #! 家 3 軒がまるごと塔の陰に入って「柵の中に塔が 1 本」にしか見えない。
    v[18:24, 5:11, 3:26] = C['cob']
    v[18:24, 10, 3:26] = C['cob_d']
    for x in range(18, 24, 2):  # 狭間
        v[x:x + 1, 5:11, 26:29] = C['cob_l']
    v[20:22, 7:9, 26:33] = C['timber_d']  # 旗竿
    v[20:22, 7:9, 33:40] = C['timber']
    v[22:27, 7:8, 34:39] = C['crimson']  # 旗（東へなびく）
    v[22:27, 7:8, 38] = C['fl_w']
    return [('main', v, (0, 0, 0))]


def dungeon_entrance(name):
    """全体マップのダンジョンの口（`ENTRANCE`）。**降り階段ではなく「入り口」**。

    2026-08-11 に決めた「**ダンジョンは下り階段ではなく立体的な入り口風の意匠**」。
    広域マップの 1 マスは山ひとつぶんなので、床に彫った段（`stairs_down`）は真上から見ると
    **ただの穴**にしか見えない。ここは岩に穿った門——**南を向いた崖**・**両脇の
    切り出した柱**・**楣**・**奥の闇**——を立体で組む。

    闇（`dark`）は**奥の壁にしか置かない**。口の内側を全部黒くすると、この縮尺では
    ただの黒い四角になって「穴」ではなく「影」に見える（岩の側面の明暗が消える）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 46), np.uint8)
    #! **岩は丘ではなく「南を向いた崖」である。**初版は南面の高さを 10 ボクセルしか
    #! 取らなかったので、そこへ彫った口は真上から見ると**ただの切り欠き**に見えた。
    #! 穴に見せるには、**口より高い垂直な面**が口の周りに要る。
    #! 南 = y の大きい側なので、**face（崖の面）が back（奥）より大きい**ことに注意。
    face, back = 24, 2  # 崖の南面と、いちばん奥（北）
    #! **稜を 1 行ずつ明るくしない。**初版は y ごとに天端を `crag_l` で塗ったので、
    #! 奥へ 1 行ごとに 1 段上がる斜面に**白い横縞**が並び、岩ではなく波板の屋根に見えた
    #! （絵で見つけた）。明かりは**塊で散らす**（罠 38 と同じ話）。
    #! 頂は **6 マス角の塊ごと**に高さを決める（`_lump_face` と同じ考え方）。
    #! 直した経緯を 2 つ残す——どちらも「規則的な模様」に化けた失敗である:
    #! - **奥へ一定の勾配で上げない。**22 行で 11 段上げた版は、2 行ごとに同じ段差の
    #!   ledge が 11 本並んで**波板の屋根**に見えた
    #! - **x ごとに 1 ボクセル散らさない。**上の勾配と掛け算になって**格子状のいぼ**に
    #!   なった（罠 99 の再演。「揃えると格子・散らすと点描」の谷）
    #! 岩の頂は**でこぼこの平坦**でよい。崖の読みを作っているのは天ではなく南の垂直面である。
    tops = np.zeros((V, V), np.int32)
    block = 6
    for bx in range(0, V, block):
        for by in range(back, face + 1, block):
            t = (face - by) / float(face - back)  # 0 = 崖の面 / 1 = 奥
            h = min(44, int(rng.integers(29, 39) + (t * 5)))  # 奥ほど少しだけ高い
            tops[bx:bx + block, by:by + block] = h
    for y in range(back, face + 1):
        for x in range(1, 31):
            v[x, y, 0:int(tops[x, y])] = C['crag']
        for _ in range(3):  # 層理と剥離
            x = int(rng.integers(1, 28))
            z = int(rng.integers(0, 26))
            v[x:x + int(rng.integers(2, 6)), y, z:z + 2] = C['crag_d']
    #! 塊の高さは **4 本の柱の低いほう**に合わせる。(x,y) の天端で塗った初版は、
    #! 低い隣の上に 1 段だけボクセルが**浮いて**、岩の頭がいぼだらけになった（絵で見つけた）。
    for _ in range(50):  # 陽の当たる稜（塊で散らす）
        x = int(rng.integers(1, 29))
        y = int(rng.integers(back, face))
        top = int(tops[x:x + 2, y:y + 2].min())
        if top > 0:
            v[x:x + 2, y:y + 2, top - 1:top] = C['crag_l']
    v[1:31, back:face + 1, 0:2] = C['crag_dd']  # 岩の足元
    for _ in range(10):  # 南面を平らにしない（崖に凹凸を彫る）
        x = int(rng.integers(1, 28))
        z = int(rng.integers(2, 28))
        if (x + 4 <= 9) or (x >= 23):  # 口には掛けない
            v[x:x + 4, face - int(rng.integers(1, 3)):face + 1, z:z + 4] = 0

    # (2) 口を彫る。**天井は弧**（四角い穴は扉に見える。ここは岩の裂け目である）。
    for x in range(10, 22):
        s = (x - 15.5) / 6.0
        arch = int(round(22 - (5.0 * s * s)))
        v[x, back + 3:face + 1, 0:arch] = 0
    v[10:22, back + 3:face + 1, 0:2] = C['crag_dd']  # 洞床（少し暗い）
    v[10:22, back + 1:back + 3, 0:22] = C['dark']  # **闇は奥の面だけ**（全部黒くすると影に見える）
    v[10, back + 3:face + 1, 0:22] = C['crag_d']  # 口の内壁（左右）
    v[21, back + 3:face + 1, 0:22] = C['crag_d']

    # (3) 切り出した柱と楣。**岩より明るい石**で、人の手が入っていることを言う。
    #! 帯は**柱の幅の中で**打つ。`x0-1:x0+5` まで広げた初版は、右の柱の帯が口の内壁
    #! （x=21）へ食い込んで、開口に梯子が渡っているように見えた（絵で見つけた）。
    #! 前へ張り出させたいなら x ではなく y（`face-1`）で出す。
    for x0 in (6, 22):
        v[x0:x0 + 4, face:face + 5, 0:26] = C['ash']
        v[x0:x0 + 4, face + 4, 0:26] = C['ash_l']
        for z in range(4, 26, 7):  # 帯（3 本）
            v[x0:x0 + 4, face - 1:face + 5, z:z + 2] = C['ash_d']
    v[5:27, face:face + 5, 25:30] = C['ash']
    v[5:27, face + 4, 26:29] = C['ash_l']
    v[5:27, face:face + 5, 29] = C['ash_d']  # 楣の天端

    # (4) 敷居とこぼれた石（門の前＝さらに南。**低いものだけ**——高いと口を隠す）。
    v[10:22, 29:31, 0:2] = C['ash_d']
    v[10:22, 29:31, 1] = C['ash']
    for _ in range(9):
        x = int(rng.integers(1, 29))
        y = int(rng.integers(29, 31))
        v[x:x + 2, y:y + 2, 0:int(rng.integers(1, 3))] = C['crag_d']
    return [('main', v, (0, 0, 0))]


# ---------------------------------------------------------------------- 小物
def torch_stand(name):
    """立ち松明の柱。**炎は別のプレハブ**（`torch_flame`）である。

    自発光はインスタンス単位でしか渡せない（`InstanceData::er`）。柱と炎が
    1 つのプレハブだと、炎を光らせる自発光が鉄柱まで一様に持ち上げてしまう。
    2 つに分け、置く側が同じマスへ重ねて置く（`terrain_view.cpp`）。
    """
    pole = np.zeros((V, V, 34), np.uint8)
    pole[13:19, 13:19, 0:2] = C['wall_d']  # 石の台座
    pole[15:17, 15:17, 2:28] = C['iron']
    pole[14:18, 14:18, 27:29] = C['iron']  # 受け皿
    pole[13:19, 13:19, 29:31] = C['iron_l']  # かごの縁
    return [('pole', pole, (0, 0, 0))]


def torch_flame(name):
    """松明の炎。2 枚を別々の振り子で揺らす（地下は無風なので、風には頼らない）。
    座標は `torch_stand` と同じ原点で作る（同じマスへ置くだけで柱の上に載る）。"""
    fa = np.zeros((6, 6, 10), np.uint8)  # 炎の外側
    fa[1:5, 1:5, 0:6] = C['fl_edge']
    fa[1:5, 1:5, 2:7] = C['fl_mid']
    fa[2:4, 2:4, 6:8] = C['fl_mid']
    fb = np.zeros((4, 4, 9), np.uint8)  # 炎の芯（少し高い）
    fb[1:3, 1:3, 0:6] = C['fl_core']
    fb[1:3, 1:3, 6:8] = C['fl_mid']
    return [('flame_a', fa, (13, 13, 30)), ('flame_b', fb, (14, 14, 31))]


def barrel(name):
    rng = rng_for(name)
    v = np.zeros((V, V, 16), np.uint8)
    cx = cy = V // 2
    for z in range(16):
        bulge = 1.0 - ((z - 7.5) / 7.5) ** 2 * 0.18
        r = 6.6 * bulge
        for x in range(V):
            for y in range(V):
                d2 = (x - cx + 0.5) ** 2 + (y - cy + 0.5) ** 2
                if d2 <= r * r:
                    ang = int((np.arctan2(y - cy + 0.5, x - cx + 0.5) + 3.15) / 0.9)
                    v[x, y, z] = C['timber_l'] if ang % 2 else C['timber']
    for z in (2, 3, 12, 13):  # 鉄の箍
        for x in range(V):
            for y in range(V):
                if v[x, y, z] and (z in (2, 13) or True):
                    d2 = (x - cx + 0.5) ** 2 + (y - cy + 0.5) ** 2
                    if d2 >= (6.6 * (1.0 - ((z - 7.5) / 7.5) ** 2 * 0.18) - 1.6) ** 2:
                        v[x, y, z] = C['iron']
    v[cx - 5:cx + 5, cy - 5:cy + 5, 15] = C['timber_d']  # 蓋
    v[cx - 2:cx + 2, cy - 2:cy + 2, 15] = C['timber']
    return [('main', v, (0, 0, 0))]


def crate(name):
    v = np.zeros((V, V, 14), np.uint8)
    v[9:23, 9:23, 0:13] = C['timber']
    for a in (9, 22):  # 枠
        v[a, 9:23, 0:13] = C['timber_d']
        v[9:23, a, 0:13] = C['timber_d']
    for k in range(12):  # 斜めの帯（面ごと）
        x = 10 + k
        if x < 22:
            v[x, 9, k] = C['timber_l']
            v[x, 22, 12 - k] = C['timber_l']
    v[9:23, 9:23, 13] = C['timber_l']
    v[10:22, 10:22, 13] = C['timber']
    return [('main', v, (0, 0, 0))]


def bones(name):
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    sx, sy = 9, 14
    # 頭蓋骨。眼窩は -y 面（既定のカメラが見る側）。
    v[sx:sx + 8, sy:sy + 7, 2:7] = C['bone']
    v[sx + 1:sx + 7, sy + 1:sy + 6, 7] = C['bone']  # 丸めた頭頂
    v[sx:sx + 8, sy:sy + 3, 0:2] = C['bone_d']  # 顎（前へ出す）
    v[sx + 1:sx + 3, sy, 4:6] = C['dark']  # 眼窩
    v[sx + 5:sx + 7, sy, 4:6] = C['dark']
    v[sx + 3:sx + 5, sy, 2:4] = C['bone_d']  # 鼻腔のくぼみ
    for _ in range(4):  # 散った骨（両端に節）
        x, y = int(rng.integers(3, 22)), int(rng.integers(3, 22))
        ln = int(rng.integers(6, 10))
        if rng.random() < 0.5:
            v[x:x + ln, y:y + 1, 0] = C['bone_d']
            v[x - 1:x + 1, y - 1:y + 1, 0:2] = C['bone']
            v[x + ln - 1:x + ln + 1, y - 1:y + 1, 0:2] = C['bone']
        else:
            v[x:x + 1, y:y + ln, 0] = C['bone_d']
            v[x - 1:x + 1, y - 1:y + 1, 0:2] = C['bone']
            v[x - 1:x + 1, y + ln - 1:y + ln + 1, 0:2] = C['bone']
    return [('main', v, (0, 0, 0))]


def mushrooms(name, glow):
    """茸の群れ。**傘の下に柄が見える高さ**にする（低いと地面の染みに見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 13), np.uint8)
    cap, cap_d = (C['mgl'], C['mgl_d']) if glow else (C['mbr'], C['mbr_d'])
    spots = [(9, 10), (20, 14), (13, 20), (23, 23), (8, 22)]
    for i in range(int(rng.integers(4, 6))):
        x, y = spots[i]
        x += int(rng.integers(-1, 2))
        y += int(rng.integers(-1, 2))
        h = int(rng.integers(4, 8))
        r = int(rng.integers(2, 4))
        v[x:x + 2, y:y + 2, 0:h] = C['stem']
        v[max(0, x - r):x + r + 2, max(0, y - r):y + r + 2, h:h + 2] = cap_d  # 傘の縁
        v[max(0, x - r + 1):x + r + 1, max(0, y - r + 1):y + r + 1, h + 1:h + 3] = cap  # 傘の頂
    return [('main', v, (0, 0, 0))]


def rubble_pile(name):
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    for _ in range(11):  # 岩塊を重ねて山にする
        cx, cy = int(rng.integers(8, 24)), int(rng.integers(8, 24))
        w, d, h = (int(rng.integers(3, 8)) for _ in range(3))
        z0 = int(rng.integers(0, 3)) if max(abs(cx - 16), abs(cy - 16)) > 5 else int(rng.integers(2, 6))
        shade = rng.choice([C['rock'], C['rock_l'], C['rock_d']], p=[0.45, 0.25, 0.3])
        v[cx - w // 2:cx + (w + 1) // 2, cy - d // 2:cy + (d + 1) // 2, max(0, z0 - h):z0 + h] = shade
    v[:, :, 8:] = 0  # 高さを抑える（装飾は低く）
    return [('main', v, (0, 0, 0))]


def tree(name):
    """立ち木。**高さは変種ごとに違う**（2026-08-09 に決めた:「木の高さはランダムにして
    最大今の倍くらいまで。最低は今の 1/2 の低木も」）。

    もとの `vox_art.tree()` は 76×76×112（3.5 マス）で **31,730 三角形**あった。葉を
    粒単位で塗り分けていたためで、8,409 本の Outpost では LOD 無しに成立しない
    （設計書 §6.1）。ここでは**葉の塊ごとに 1 色**にして greedy を効かせる（罠 38 の一般形）。

    名前の末尾 2 桁が高さを決める（01 = 1.75 マス の低木 〜 10 = 7 マスの大木）。
    """
    rng = rng_for(name)
    step = int(name[-2:]) if name[-2:].isdigit() else 5
    # 56（現行 112 の 1/2）〜 224（現行の 2 倍）を 10 段。1 マス = 32 ボクセル。
    h = int(round(56 + (224 - 56) * (step - 1) / 9.0))
    span = 64 if h < 96 else (96 if h < 160 else 128)  # 幅はマス単位で 2 / 3 / 4
    v = np.zeros((span, span, h), np.uint8)
    # 幹は**マスの中心**へ。`span // 2` はマスの境界に当たるので、そこに立てると
    # 幹が 2 マスにまたがって footprint が 4 マスになる（実際にそうなった）。
    cx = cy = (((span // V) // 2) * V) + (V // 2)
    trunk_h = int(h * rng.uniform(0.36, 0.48))
    r_base = max(2.2, h * 0.045)

    def limb(p0, p1, r0, r1, colour):
        n = int(max(abs(np.array(p1) - np.array(p0)).max() * 2, 8))
        for i in range(n + 1):
            t = i / n
            px, py, pz = [p0[k] + (p1[k] - p0[k]) * t for k in range(3)]
            r = r0 + (r1 - r0) * t
            xs = np.arange(span)[:, None] - px
            ys = np.arange(span)[None, :] - py
            m = (xs ** 2) + (ys ** 2) < (r * r)
            zi = int(round(pz))
            for dz in range(-int(r), int(r) + 1):
                if 0 <= zi + dz < h and abs(dz) < r:
                    v[:, :, zi + dz][m] = colour

    limb((cx, cy, 0), (cx + 1, cy - 1, trunk_h), r_base, r_base * 0.55, C['bark'])
    tips = [(cx + 1, cy - 1, trunk_h + h * 0.06)]
    branches = 3 if h < 96 else (4 if h < 160 else 5)
    for k in range(branches):
        ang = (k * 6.283 / branches) + rng.uniform(-0.3, 0.3)
        ln = span * rng.uniform(0.16, 0.26)
        up = h * rng.uniform(0.12, 0.22)
        ex = cx + 1 + (np.cos(ang) * ln)
        ey = cy - 1 + (np.sin(ang) * ln)
        limb((cx + 1, cy - 1, trunk_h * 0.85), (ex, ey, trunk_h + up), r_base * 0.5, r_base * 0.28,
             C['bark_l'])
        tips.append((ex, ey, trunk_h + up))

    # 葉。**塊ごとに 1 色の直方体**にする（設計書 R8「ボクセルアート寄り。立方体が見えてよい」）。
    # 球で置くと表面が階段状になり、1 本 65,000 三角形まで膨れた（実測）。角を落とした
    # 直方体なら greedy が面ごとにまとめるので、同じ見た目の密度で 1 桁安くなる。
    leaf_shades = [C['leaf_d'], C['leaf_m'], C['leaf_l'], C['leaf_h']]
    crown_r = span * 0.34  # 樹冠のおおよその半径。塊はこの中に散らす
    for (tx, ty, tz) in tips:
        for _ in range(10 if h < 96 else 16):
            bx = tx + rng.normal(0, crown_r * 0.55)
            by = ty + rng.normal(0, crown_r * 0.55)
            bz = tz + rng.normal(h * 0.10, h * 0.075)
            # **小さめの塊を多く。**大きな直方体を数個置くと積み木に見えた（1 度そうなった）。
            bw = span * rng.uniform(0.055, 0.105)
            bd = span * rng.uniform(0.055, 0.105)
            bh = h * rng.uniform(0.035, 0.065)
            # 上ほど明るい塊を選ぶ（光は上から来る）。
            up_ratio = min(1.0, max(0.0, (bz - trunk_h) / max(1.0, h - trunk_h)))
            idx = int(min(3, max(0, rng.normal(0.7 + (up_ratio * 2.0), 0.8))))
            x0, x1 = int(bx - bw), int(bx + bw)
            y0, y1 = int(by - bd), int(by + bd)
            z0, z1 = int(bz - bh), int(bz + bh)
            block = v[max(x0, 0):x1, max(y0, 0):y1, max(z0, 0):z1]
            if block.size == 0:
                continue
            block[block == 0] = leaf_shades[idx]
    # 樹冠の下面を削って椀形にする（真下から生えた四角い塊のままだと影も四角くなる）。
    leaf_mask = np.isin(v, leaf_shades)
    xs = np.arange(span)[:, None, None]
    ys = np.arange(span)[None, :, None]
    zs = np.arange(h)[None, None, :]
    crown_z = trunk_h + (h * 0.18)
    under = (((xs - cx) ** 2) + ((ys - cy) ** 2)) > ((crown_r * 1.15) ** 2)
    v[leaf_mask & under] = 0  # 樹冠から離れすぎた葉を落とす
    bowl = (zs < crown_z) & ((((xs - cx) ** 2) + ((ys - cy) ** 2)) > ((crown_r * 0.62) ** 2))
    v[np.isin(v, leaf_shades) & bowl] = 0
    limb((cx, cy, 0), (cx + 1, cy - 1, trunk_h), r_base, r_base * 0.55, C['bark'])  # 幹を葉より前に
    return [('main', v, (0, 0, 0))]


def stalagmite(name):
    rng = rng_for(name)
    v = np.zeros((V, V, 22), np.uint8)
    for cx, cy, h, r0 in ((12, 12, 20, 4.4), (21, 18, 13, 3.4), (14, 22, 8, 2.6)):
        for z in range(h):
            r = r0 * (1.0 - z / float(h)) + 0.4
            for x in range(V):
                for y in range(V):
                    if (x - cx) ** 2 + (y - cy) ** 2 <= r * r:
                        c = C['rock_l'] if z > h - 3 else (C['rock'] if (z // 4) % 2 else C['rock_d'])
                        v[x, y, z] = c
    return [('main', v, (0, 0, 0))]


# ------------------------------------- 巣とゴミ（P10 第 4 期。ダンジョンごとの小物）
#
# 2026-08-10 に決めた:「**同質なダンジョンは名前の意味で小物に差を付けよう。**
# イークの洞窟はベッドの藁束や食料としている小動物の骨、生えているキノコ。
# オークの洞窟はイークの洞窟より大きなベッド、壊れた道具、ゴミの山等」。
#
# **イークとオークの差は「大きさ」で付ける。**同じ「ベッド」を 2 つ作って、
# オークをイークの倍以上にする。並べて見ることは無いが、先にイークを見てから
# オークへ来る順路（深さ 1–13 → 10–23）なので、記憶と比べられる。
#
# どれも**装飾層に乗る**ので、マスの四隅に置かれ、通路では半分の大きさになる
# （`terrain_view.cpp` の `prop_scale`）。**背は低く**保つこと——高い装飾は
# 視線を遮る扱いになる（`note_cover`）。


def _scatter_lumps(v, rng, count, box, span, height, shades, weights):
    """塊を撒いて山にする（`rubble_pile` と同じ流儀）。**塊単位で色を引く**（罠 38）。

    `box` は撒く範囲 (lo, hi)、`span` は 1 塊の幅の範囲、`height` は同じく高さの範囲。
    """
    lo, hi = box
    for _ in range(count):
        cx, cy = int(rng.integers(lo, hi)), int(rng.integers(lo, hi))
        w, d = int(rng.integers(*span)), int(rng.integers(*span))
        t = int(rng.integers(*height))
        shade = rng.choice(shades, p=weights)
        v[max(0, cx - w // 2):cx + (w + 1) // 2, max(0, cy - d // 2):cy + (d + 1) // 2, 0:t] = shade


def _nest_ring(v, rng, radius, wall, rim, shades, weights):
    """巣の輪 — 外は積んだ縁、中は凹んだベッド。**中を凹ませるのが「ベッド」の読み**である。

    ただの塚にすると「ゴミの山」と見分けが付かない（オークは両方持つので、
    ここが混ざると 2 つの小物が 1 つに見える）。
    """
    cx = cy = V // 2
    for x in range(V):
        for y in range(V):
            dist = math.hypot(x - cx + 0.5, y - cy + 0.5)
            if dist > radius:
                continue
            #! 縁は高く、中は薄く。境目は塊で崩す（真円だと編んだ籠に見える）。
            edge = dist > (radius - rim)
            top = wall if edge else max(1, wall // 3)
            top -= int(rng.integers(0, 2))
            shade = rng.choice(shades, p=weights)
            v[x, y, 0:max(1, top)] = shade


def nest_straw(name):
    """藁束のベッド（イーク）。**1 匹ぶんの小ささ**（径 0.47 マス・高さ 0.19 マス）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 7), np.uint8)
    _nest_ring(v, rng, radius=7.5, wall=6, rim=3.0,
               shades=[C['straw'], C['straw_d'], C['straw_g'], C['straw_l']],
               weights=[0.34, 0.28, 0.26, 0.12])
    #! 抜けた藁が数本、外へこぼれている（輪だけだと「置いた物」に見える）。
    for _ in range(5):
        x, y = int(rng.integers(4, V - 10)), int(rng.integers(4, V - 10))
        ln = int(rng.integers(4, 8))
        if rng.random() < 0.5:
            v[x:x + ln, y, 0] = C['straw_g']
        else:
            v[x, y:y + ln, 0] = C['straw_g']
    return [('main', v, (0, 0, 0))]


def bones_small(name):
    """小動物の骨（イークの食べかす）。**`bones` の頭蓋を持たない**のが差である。

    既存の `bones` は人骨で、頭蓋だけで 8×7×5 ある。ここは「食べ終えた小動物」なので、
    親指ほどの骨と小さな頭が散っているだけにする。**同じマスに置いても別物に読める**。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 4), np.uint8)
    #! 小さな頭（4×4×3・鼻づら付き）。眼窩は -y 面（既定のカメラが見る側＝`bones` と同じ約束）。
    #! **初版は 3×3 の立方体で、白い箱にしか見えなかった**——鼻づらが付いて初めて頭に読める。
    hx, hy = int(rng.integers(12, 17)), int(rng.integers(14, 19))
    v[hx:hx + 4, hy:hy + 4, 0:3] = C['bone']
    v[hx + 1:hx + 3, hy - 2:hy, 0:2] = C['bone_d']  # 鼻づら（前へ出す）
    v[hx, hy, 1] = C['dark']
    v[hx + 3, hy, 1] = C['dark']
    #! 散った小骨。**幅 2 で寝かせる**（幅 1 だと 1 画素の線になって消える）。
    #! 両端の節を 1 段持ち上げると棒ではなく骨に読める。
    for _ in range(6):
        x, y = int(rng.integers(5, V - 12)), int(rng.integers(5, V - 12))
        ln = int(rng.integers(6, 10))
        shade = C['bone'] if rng.random() < 0.6 else C['bone_d']
        if rng.random() < 0.5:
            v[x:x + ln, y:y + 2, 0] = shade
            v[x:x + 2, y - 1:y + 3, 0:2] = C['bone']
            v[x + ln - 2:x + ln, y - 1:y + 3, 0:2] = C['bone']
        else:
            v[x:x + 2, y:y + ln, 0] = shade
            v[x - 1:x + 3, y:y + 2, 0:2] = C['bone']
            v[x - 1:x + 3, y + ln - 2:y + ln, 0:2] = C['bone']
    return [('main', v, (0, 0, 0))]


def ash_pit(name):
    """消し炭の焚き火跡（イーク）。**火は消えている**——自発光は乗せない。

    立ち松明（`torch_stand` ＋ `torch_flame`）の代わりに置く。イークが鉄の燭台を
    据えるのは不自然だし、松明は「明るいと確定した部屋」にしか出ないので、
    浅い階では出っぱなしになる（`terrain_view.cpp` の `lit_room`）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 5), np.uint8)
    cx = cy = V // 2
    #! 炭の床を**先に敷いて 2 段持ち上げる**。初版は 1 段だったので、見下ろすカメラでは
    #! 石の影に隠れて「石が数個転がっているだけ」に見えた。**炉は黒い面で読ませる。**
    for x in range(V):
        for y in range(V):
            if math.hypot(x - cx + 0.5, y - cy + 0.5) <= 6.4:
                v[x, y, 0:2] = C['char'] if rng.random() < 0.72 else C['char_l']
    #! 燃え残りの枝（炭の上に置く。黒一色だと炭が「穴」に見える）。
    for _ in range(5):
        x, y = int(rng.integers(cx - 4, cx + 3)), int(rng.integers(cy - 4, cy + 3))
        ln = int(rng.integers(3, 7))
        if rng.random() < 0.5:
            v[x:x + ln, y, 2] = C['char_l']
        else:
            v[x, y:y + ln, 2] = C['char_l']
    #! 囲いの石。**小さく多く**（10 個・2〜3 マス）。初版は 6 個 × 最大 4 マスで、
    #! 1 つ 1 つが大きすぎて「積んだ石」に見えず、輪も閉じなかった。
    for k in range(10):
        ang = (k / 10.0 * 2.0 * math.pi) + float(rng.uniform(-0.22, 0.22))
        r = float(rng.uniform(7.0, 8.4))
        x = int(cx + math.cos(ang) * r)
        y = int(cy + math.sin(ang) * r)
        w = int(rng.integers(2, 4))
        shade = rng.choice([C['rock_d'], C['rock'], C['rock_dd']], p=[0.4, 0.3, 0.3])
        v[max(0, x - w // 2):x + w // 2 + 1, max(0, y - w // 2):y + w // 2 + 1,
          0:int(rng.integers(3, 5))] = shade
    return [('main', v, (0, 0, 0))]


def refuse_heap(name):
    """ゴミの山（オーク）。**瓦礫（`rubble_pile`）との差は「石でない物が混ざる」こと**。

    骨・汚れた布・折れた木・腐った食べかすを石と同じ塚に積む。色が 5 種類あるのが
    「捨て場」の読みで、石だけだと落石にしか見えない。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 13), np.uint8)
    #! **塊を小さく多く**（初版は 13 個 × 最大 8 マスで、大きな箱を数個積んだように見えた。
    #! とくに腐った食べかす（`rot`）の緑が面で出て「緑の箱」になった）。
    #! 18 個 × 最大 6 マスにして、`rot` は差し色の量まで落とす。
    _scatter_lumps(v, rng, count=18, box=(8, 24), span=(2, 6), height=(2, 10),
                   shades=[C['rag'], C['bone_d'], C['timber_d'], C['rock_d'], C['rot']],
                   weights=[0.28, 0.24, 0.22, 0.19, 0.07])
    #! 山から突き出た骨と棒。**輪郭を崩す**のが「積んだ」ではなく「捨てた」の読み。
    for _ in range(5):
        x, y = int(rng.integers(8, 24)), int(rng.integers(8, 24))
        z0 = int(rng.integers(3, 8))
        ln = int(rng.integers(3, 6))
        shade = C['bone'] if rng.random() < 0.5 else C['timber_d']
        if rng.random() < 0.5:
            v[x:x + ln, y, z0:z0 + 2] = shade
        else:
            v[x, y:y + ln, z0:z0 + 2] = shade
    v[:, :, 11:] = 0  # 背は抑える（装飾は低く）
    return [('main', v, (0, 0, 0))]


def broken_tools(name):
    """壊れた道具（オーク）。折れた斧・潰れた兜・割れた盾を**地面に転がす**。

    立てて置くと武器庫に見える。オークの洞窟にあるのは**捨てた物**なので、
    どれも寝かせて、欠けた形にする。錆（`rust`）を鉄（`iron`）と混ぜて傷ませる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 6), np.uint8)
    #! (1) 折れた斧。柄は途中で切れていて、刃は地面に伏せている。
    hx, hy = 7, 9
    ln = int(rng.integers(7, 11))
    v[hx:hx + ln, hy, 0:2] = C['timber_d']
    v[hx + ln - 1, hy, 0:3] = C['timber']  # 折れ口（明るい木口）
    v[hx - 4:hx, hy - 2:hy + 3, 0:2] = C['iron']
    v[hx - 4:hx - 2, hy - 2:hy + 3, 0:2] = C['rust']  # 刃先が錆びている
    #! (2) 潰れた兜。半球を**片側だけ凹ませる**（丸いままだと椀に見える）。
    cx, cy = 22, 12
    for x in range(V):
        for y in range(V):
            d = math.hypot(x - cx + 0.5, y - cy + 0.5)
            if d <= 5.0:
                t = 4 - int(d * 0.6)
                if x > cx + 1:  # 潰れた側
                    t = max(1, t - 2)
                v[x, y, 0:max(1, t)] = C['iron_l'] if d < 2.5 else C['iron']
    v[cx + 3:cx + 6, cy - 2:cy + 2, 0:2] = C['rust_d']
    #! (3) 割れた盾。円板の**一部を欠く**（欠けが無いと蓋に見える）。
    sx, sy = 13, 23
    for x in range(V):
        for y in range(V):
            d = math.hypot(x - sx + 0.5, y - sy + 0.5)
            if (d <= 6.2) and not ((x > sx + 1) and (y > sy + 1) and (d > 3.0)):
                v[x, y, 0:2] = C['oak'] if d > 2.2 else C['iron']
    for k in range(-6, 7):  # 割れ目
        if 0 <= sx + k < V:
            v[sx + k, sy + (k // 3), 0:2] = 0
    v[sx - 6:sx + 7, sy - 6:sy - 5, 0:2] = np.where(
        v[sx - 6:sx + 7, sy - 6:sy - 5, 0:2] > 0, C['rust'], 0)  # 縁金の錆
    return [('main', v, (0, 0, 0))]


def nest_hide(name):
    """毛皮と藁のベッド（オーク）。**イークの倍以上**（径 0.81 マス・高さ 0.31 マス）。

    2026-08-10 に決めた「イークの洞窟より大きなベッド」。大きさだけでなく
    **材も足す**——藁の輪の中に毛皮を敷く。藁だけを大きくすると
    「イークの巣が大きいだけ」に見えて、別の生き物の巣にならない。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 11), np.uint8)
    _nest_ring(v, rng, radius=13.0, wall=9, rim=4.5,
               shades=[C['straw_d'], C['straw_g'], C['straw'], C['fur_d']],
               weights=[0.32, 0.28, 0.22, 0.18])
    #! 中に敷いた毛皮。**塊で置く**（1 ボクセルずつ振ると毛羽ではなく砂になる＝罠 38）。
    cx = cy = V // 2
    for bx in range(cx - 9, cx + 9, 3):
        for by in range(cy - 9, cy + 9, 3):
            if math.hypot(bx - cx + 1.5, by - cy + 1.5) > 8.5:
                continue
            shade = rng.choice([C['fur'], C['fur_d'], C['fur_l']], p=[0.46, 0.34, 0.20])
            v[bx:bx + 3, by:by + 3, 0:int(rng.integers(2, 5))] = shade
    #! 引き込んだ大きな骨（食べ残しをベッドへ持ち込んでいる）。**イークの巣には置かない**。
    bx, by = int(rng.integers(cx - 5, cx + 3)), int(rng.integers(cy - 5, cy + 3))
    v[bx:bx + 8, by, 3:5] = C['bone_d']
    v[bx, by - 1:by + 2, 3:6] = C['bone']
    v[bx + 7, by - 1:by + 2, 3:6] = C['bone']
    return [('main', v, (0, 0, 0))]


# ------------------- ダンジョンごとの小物・後半（P10 第 4 期。残り 18 本。2026-08-10）
#
# 案は の §3・§4。**名前の意味で差を付ける**（決めたこと）。
# どれも装飾層に乗るので、マスの四隅に置かれ、通路では半分の大きさになる。**背は低く保つ**
# （高い装飾は視線を遮る扱いになる＝`note_cover`）。
#
# 作りの共通の約束（先陣で踏んだ罠から）:
#   - 色は**塊**で置く（1 ボクセルずつ振ると砂粒＝罠 38）
#   - 面で読ませたいものは周りより低くしない（罠 100。焚き火跡で踏んだ）
#   - 棒は**幅 2**（幅 1 は 1 画素の線になって消える）


def _sticks(v, rng, count, z, shades, length=(5, 10), thick=2):
    """散らばった棒（骨・枝・刃・杖の折れ）。**幅 2 で寝かせる**のが読みの下限。"""
    for _ in range(count):
        x, y = int(rng.integers(2, V - 12)), int(rng.integers(2, V - 12))
        ln = int(rng.integers(*length))
        shade = rng.choice(shades)
        if rng.random() < 0.5:
            v[x:x + ln, y:y + thick, z:z + thick] = shade
        else:
            v[x:x + thick, y:y + ln, z:z + thick] = shade


def _slab(v, x0, y0, w, d, h, shade, z0=0):
    v[max(0, x0):x0 + w, max(0, y0):y0 + d, z0:z0 + h] = shade


# ---- 鉄獄（1）: 鉄の牢獄。**基準に据えるなら表の 1 行を消すだけで戻せる** ----


def chain_rusted(name):
    """錆びた鎖と枷 — 壁際に落ちている。鉄（`iron`）と錆（`rust`）を**節ごとに**替える。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 4), np.uint8)
    x, y = 6, int(rng.integers(8, 18))
    for k in range(9):  # 鎖。1 節 2 マスで蛇行させる
        shade = C['rust'] if rng.random() < 0.45 else C['iron']
        v[x:x + 2, y:y + 2, 0:2] = shade
        x += 2
        y += int(rng.integers(-1, 2))
        y = max(2, min(V - 4, y))
    v[x:x + 6, y - 2:y + 4, 0:2] = C['iron']  # 枷（輪）
    v[x + 1:x + 5, y - 1:y + 3, 0:2] = 0
    v[x + 2:x + 4, y - 2:y, 0:3] = C['rust_d']  # 留め金
    return [('main', v, (0, 0, 0))]


def weapon_broken(name):
    """折れた武器 — 前に来た者の残り。**刃だけ・柄だけ**にして「折れた」を出す。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 4), np.uint8)
    _sticks(v, rng, 3, 0, [C['timber_d'], C['oak']], length=(5, 9))
    _sticks(v, rng, 3, 0, [C['iron'], C['steel_d'], C['rust']], length=(6, 11))
    #! 折れ口は明るく（木口と欠けた鋼）。
    for _ in range(4):
        x, y = int(rng.integers(3, V - 4)), int(rng.integers(3, V - 4))
        if v[x, y, 0]:
            v[x:x + 2, y:y + 2, 0:3] = C['steel'] if rng.random() < 0.5 else C['timber_l']
    return [('main', v, (0, 0, 0))]


# ---- 迷宮（4）: ミノタウロスの迷宮 ----


def torch_stub(name):
    """燃え尽きた松明の燃え殻 — 引き返した跡。暗闇の洞窟（19）と共用。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 5), np.uint8)
    for k in range(int(rng.integers(3, 6))):
        x, y = int(rng.integers(4, V - 12)), int(rng.integers(4, V - 12))
        ln = int(rng.integers(6, 11))
        if rng.random() < 0.5:
            v[x:x + ln, y:y + 2, 0:2] = C['timber_d']
            v[x + ln - 3:x + ln, y:y + 2, 0:3] = C['char']  # 焼けた先
        else:
            v[x:x + 2, y:y + ln, 0:2] = C['timber_d']
            v[x:x + 2, y + ln - 3:y + ln, 0:3] = C['char']
    return [('main', v, (0, 0, 0))]


def pillar_bull(name):
    """牛頭の柱頭 — 主が『迷宮のミノタウロス』。既存の柱の**上だけ**を差し替えた形。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 46), np.uint8)
    #! 柱身（角柱。迷宮の材＝冷たい灰）。
    v[11:21, 11:21, 0:36] = C['cob']
    v[10:22, 10:22, 0:3] = C['cob_d']  # 礎石
    v[10:22, 10:22, 34:37] = C['cob_d']  # 頂板
    #! 牛頭。**角が横へ張り出す**のが読みの決め手（正面の面だけでは牛にならない）。
    v[12:20, 12:18, 37:44] = C['flag']
    v[13:19, 10:13, 37:41] = C['flag_d']  # 鼻づら（南＝カメラ側へ出す）
    v[13:15, 11, 41:43] = C['dark']
    v[17:19, 11, 41:43] = C['dark']
    for side, x0 in ((0, 7), (1, 20)):
        v[x0:x0 + 5, 13:16, 42:45] = C['bone_d']  # 角
        v[x0 + (0 if side == 0 else 3):x0 + (2 if side == 0 else 5), 13:16, 44:46] = C['bone']
    return [('main', v, (0, 0, 0))]


def pack_lost(name):
    """先人の荷物 — 放り出された背嚢と白骨。**中身がこぼれている**のが「放り出した」の読み。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    _slab(v, 9, 12, 11, 9, 6, C['rag'])
    _slab(v, 10, 13, 9, 7, 7, C['timber_d'])  # 蓋の革
    for _ in range(4):  # こぼれた中身
        x, y = int(rng.integers(3, V - 4)), int(rng.integers(3, V - 4))
        v[x:x + 3, y:y + 3, 0:2] = rng.choice([C['gold_d'], C['qz'], C['cloth_d'], C['oak']])
    _sticks(v, rng, 3, 0, [C['bone'], C['bone_d']], length=(5, 9))
    return [('main', v, (0, 0, 0))]


# ---- 城（12）: 白大理石の宮殿 ----


def armour_stand(name):
    """空の鎧 — 壁際に立っている。**肩を張り、首を空ける**のが鎧の読み。

    初版は胴が細くて肩も無く、白い人形に見えた。肩を胴より左右へ 3 マスずつ張り出させ、
    兜と胴の間を 2 段空ける（**中身が無い**ことは隙間で言う）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 35), np.uint8)
    v[10:22, 12:20, 0:2] = C['marb_g']  # 台
    v[15:17, 15:17, 2:12] = C['iron']  # 支柱
    v[11:21, 12:20, 12:24] = C['steel_d']  # 胴
    v[12:20, 12:14, 12:24] = C['steel']  # 胸当て（カメラ側を明るく）
    v[8:24, 13:19, 22:26] = C['steel']  # **肩**
    v[7:10, 14:18, 12:23] = C['steel_d']  # 籠手（左）
    v[22:25, 14:18, 12:23] = C['steel_d']  # 同（右）
    v[13:19, 14:18, 28:33] = C['steel']  # 兜（**首を 2 段空ける**）
    v[14:18, 13:15, 29:31] = C['dark']  # 面の隙間
    v[12:20, 14:18, 33:34] = C['steel_d']  # 庇
    if rng.random() < 0.5:
        v[15:17, 15:17, 34:35] = C['crimson']
    return [('main', v, (0, 0, 0))]


def tapestry(name):
    """織物の垂れ幕 — `CURTAIN` を持つダンジョンなので理屈が合う。**壁に貼る薄板**。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    base = rng.choice([C['crimson'], C['sky'], C['tent']])
    v[6:26, 1:3, 6:28] = base
    v[5:27, 0:2, 27:30] = C['gold_d']  # 吊り棒
    #! 紋。**塊で置く**（細かい絵は 1 マス幅では潰れる）。
    v[12:20, 1:3, 14:22] = C['cloth']
    v[14:18, 1:3, 16:20] = C['gold']
    for k in range(6, 26, 4):  # 裾の房
        v[k:k + 2, 1:3, 4:7] = C['gold_d']
    return [('main', v, (0, 0, 0))]


def sconce(name):
    """壁の燭台 — 柱に立てる松明の代わり。炎は `torch_flame` を同じマスへ重ねる。

    **蝋燭はマスの中央へ立てる。**炎のプレハブは `torch_stand` に合わせて
    `(13,13,30)` から作ってあり（マスの中央・柱の頭）、置く側は本体と炎へ同じ位置を渡す。
    初版は受け皿を壁ぎわ（y=7〜13）に置いていたので、**炎だけが宙に浮く**形になっていた
    ——世界に置いていない素材は検査されていない（罠 86）の実例で、
    2026-08-11 に城の火として初めて置いたときに分かった。腕をその分だけ伸ばしてある。
    """
    v = np.zeros((V, V, 32), np.uint8)
    v[13:19, 1:4, 18:22] = C['gold_d']  # 壁付けの台座
    v[15:17, 3:14, 20:22] = C['gold_d']  # 腕（マスの中央まで伸ばす）
    v[13:19, 13:19, 21:26] = C['gold']  # 受け皿
    v[14:18, 14:18, 23:26] = 0
    v[15:17, 15:17, 24:30] = C['fl_edge']  # 蝋燭。**天面が炎の底（z=30）に合う**
    return [('main', v, (0, 0, 0))]


def table_long(name):
    """長机 — 城の広間。**脚の間を抜く**（抜かないと箱に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 14), np.uint8)
    v[4:28, 10:22, 10:13] = C['oak']  # 天板
    v[4:28, 10:22, 13] = C['oak_l']
    for x0 in (5, 24):  # 脚
        v[x0:x0 + 3, 11:13, 0:10] = C['timber_d']
        v[x0:x0 + 3, 19:21, 0:10] = C['timber_d']
    if rng.random() < 0.6:  # 燭台と杯
        v[13:16, 14:17, 13:14] = C['gold_d']
        v[14:15, 15:16, 13:18] = C['gold']
    return [('main', v, (0, 0, 0))]


def carpet(name):
    """絨毯 — **1 段だけ**。厚くすると段差に見えて通れないマスと紛れる。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 1), np.uint8)
    base = rng.choice([C['crimson'], C['sky'], C['tent_d']])
    v[2:30, 5:27, 0] = base
    v[3:29, 6:26, 0] = base
    v[2:30, 5:7, 0] = C['gold_d']  # 縁取り
    v[2:30, 25:27, 0] = C['gold_d']
    v[12:20, 12:20, 0] = C['gold_d']  # 中央の紋
    v[14:18, 14:18, 0] = base
    return [('main', v, (0, 0, 0))]


# ---- 金鉱（15）: 坑道 ----


def pick_stuck(name):
    """掘りかけの切羽 — つるはしが岩に刺さったまま。

    初版は塊を撒いた上に細い柄を斜めに置いたので、道具に見えなかった。
    **岩を 1 枚の面**にして、**頭を大きく**（7 マス）して刺さり口を作る。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 24), np.uint8)
    v[8:28, 8:24, 0:12] = C['rock_d']
    v[9:27, 9:23, 11:14] = C['rock']
    for _ in range(5):  # 掘り取った跡
        x, y = int(rng.integers(9, 24)), int(rng.integers(9, 20))
        v[x:x + int(rng.integers(3, 7)), y:y + int(rng.integers(3, 6)), 11:14] = 0
    for _ in range(4):  # 覗いた鉱脈
        x, y = int(rng.integers(9, 25)), int(rng.integers(9, 22))
        v[x:x + 3, y:y + 2, 10:13] = C['gold_d'] if rng.random() < 0.6 else C['qz']
    v[10:17, 12:15, 12:15] = C['iron']  # 頭（岩に食い込んでいる）
    v[9:12, 12:15, 12:15] = C['rust']
    x, z = 16, 13
    for _ in range(9):  # 柄（手前へ倒れている）
        v[x:x + 3, 13:15, z:z + 2] = C['timber']
        x += 1
        z += 1
    v[min(x, V - 4):min(x, V - 4) + 3, 12:16, min(z, 21):min(z, 21) + 3] = C['timber_l']
    return [('main', v, (0, 0, 0))]


def pit_prop(name):
    """坑木の支保工 — **2 本の柱と梁**。通路にこの枠が並ぶだけで坑道になる。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    for x0 in (3, 25):
        v[x0:x0 + 4, 14:18, 0:26] = C['timber']
        v[x0:x0 + 4, 14:18, 0:2] = C['timber_d']
    v[2:30, 14:18, 26:30] = C['timber_l']  # 梁
    v[2:30, 14:18, 25:26] = C['timber_d']
    for x0 in (7, 22):  # 方杖（斜めの支え）
        for k in range(4):
            v[x0 + (k if x0 == 7 else -k), 15:17, 22 - k:24 - k] = C['timber_d']
    if rng.random() < 0.5:  # 落ちた坑木
        v[10:20, 20:22, 0:2] = C['timber_d']
    return [('main', v, (0, 0, 0))]


def miner_lamp(name):
    """カンテラ — 坑道の灯り。松明の代わりに置く。炎は別体（`torch_flame`）。

    **籠は炎（z=30〜40）を囲む高さに置く。**初版は籠が z=14〜25 だったので、
    火として置くと**炎が籠の 5 ボクセル上に浮いた**（`sconce` と同じ穴。罠 86）。
    籠の中で火が揺れているのがカンテラの読みなので、竿を伸ばして籠を炎の高さへ上げた。
    **四方は塞がない**（塞ぐと中の炎が 1 画素も見えない）。
    """
    v = np.zeros((V, V, 45), np.uint8)
    v[13:19, 13:19, 0:2] = C['iron']  # 台
    v[15:17, 15:17, 2:28] = C['iron']  # 竿
    v[13:19, 13:19, 27:29] = C['iron']  # 籠の底
    for x, y in ((13, 13), (13, 18), (18, 13), (18, 18)):  # 籠の四隅の柱
        v[x:x + 1, y:y + 1, 28:41] = C['iron_l']
    v[13:19, 13:19, 40:42] = C['iron']  # 籠の天板
    v[15:17, 15:17, 42:45] = C['iron_l']  # 吊り手
    return [('main', v, (0, 0, 0))]


def ore_heap(name):
    """鉱石の山 — 選り分けて積んだもの。**円錐に積む**（散らすと落石に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    for x in range(V):  # まず円錐（山であることは輪郭で読む）
        for y in range(V):
            d = math.hypot(x - 16 + 0.5, y - 16 + 0.5)
            if d <= 11.0:
                v[x, y, 0:max(1, int(9.0 * (1.0 - d / 11.0)))] = C['rock_d']
    for _ in range(18):  # 上へ塊を散らして粒を出す。**きらめきは塊で**
        cx, cy = int(rng.integers(8, 24)), int(rng.integers(8, 24))
        d = math.hypot(cx - 16, cy - 16)
        if d > 10.0:
            continue
        top = max(1, int(9.0 * (1.0 - d / 11.0)))
        w = int(rng.integers(2, 5))
        v[cx:cx + w, cy:cy + w, max(0, top - 2):top + 1] = rng.choice(
            [C['rock'], C['gold_d'], C['qz'], C['gold']], p=[0.34, 0.28, 0.22, 0.16])
    return [('main', v, (0, 0, 0))]


def staff_snapped(name):
    """折れた杖と巻物の灰 — 反魔法の洞窟。

    初版は灰と棒を撒いただけで、何が起きたか読めなかった。**1 本の杖が 2 つに折れて
    同じ向きに並ぶ**（間に隙間・折れ口が明るい）形にすると「折られた」に読める。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 6), np.uint8)
    for x in range(V):  # 灰の輪（巻物が燃えた跡）。**面で**
        for y in range(V):
            if math.hypot(x - 20 + 0.5, y - 20 + 0.5) <= 7.0 and rng.random() < 0.72:
                v[x, y, 0] = C['ash_d'] if rng.random() < 0.6 else C['char_l']
    y0 = int(rng.integers(9, 14))
    v[3:14, y0:y0 + 3, 0:3] = C['oak']
    v[17:27, y0:y0 + 3, 0:3] = C['oak']
    v[12:14, y0:y0 + 3, 0:4] = C['timber_l']  # 折れ口（ささくれ）
    v[17:19, y0:y0 + 3, 0:4] = C['timber_l']
    v[2:6, y0 - 1:y0 + 4, 0:5] = C['qz']  # 杖頭の宝珠
    v[3:5, y0:y0 + 3, 3:5] = 0  # **割れている**
    return [('main', v, (0, 0, 0))]


def ward_stone(name):
    """封じの石柱 — 印が刻んであるが**光らない**。ここが反魔法の読みで、
    うっかり自発光を乗せると意味が反転する。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    v[11:21, 12:20, 0:26] = C['cob']
    v[10:22, 11:21, 0:3] = C['cob_d']
    v[11:21, 12:20, 26:28] = C['cob_d']
    #! 印。**彫る**（色で描くと落書きに見える）。南面（カメラ側）に 3 段。
    for k, z in enumerate((8, 14, 20)):
        w = 3 + ((k + int(rng.integers(0, 2))) % 3)
        v[15 - w // 2:15 + (w + 1) // 2, 12, z:z + 2] = 0
        v[15, 12, z - 2:z + 4] = 0
    return [('main', v, (0, 0, 0))]


def ward_ring(name):
    """鎖でつないだ石の輪（結界） — 反魔法。**輪が閉じている**ことが結界の読み。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    for k in range(8):
        ang = k / 8.0 * 2.0 * math.pi
        x = int(16 + math.cos(ang) * 10)
        y = int(16 + math.sin(ang) * 10)
        v[x - 2:x + 2, y - 2:y + 2, 0:int(rng.integers(4, 7))] = C['cob_d']
        nx = int(16 + math.cos(ang + math.pi / 8) * 10)
        ny = int(16 + math.sin(ang + math.pi / 8) * 10)
        v[min(x, nx):max(x, nx) + 1, min(y, ny):max(y, ny) + 1, 0:2] = C['iron']  # 鎖
    return [('main', v, (0, 0, 0))]


def blades_heap(name):
    """砕けた刃の山 — 反攻撃の洞窟。**刃だけが積まれている**（柄が無い）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 11), np.uint8)
    for _ in range(14):
        x, y = int(rng.integers(9, 23)), int(rng.integers(9, 23))
        ln = int(rng.integers(4, 9))
        z0 = int(rng.integers(0, 6))
        shade = rng.choice([C['steel_d'], C['iron'], C['steel'], C['rust']], p=[0.36, 0.28, 0.2, 0.16])
        if rng.random() < 0.5:
            v[x:x + ln, y:y + 2, z0:z0 + 2] = shade
        else:
            v[x:x + 2, y:y + ln, z0:z0 + 2] = shade
    return [('main', v, (0, 0, 0))]


def blade_embedded(name):
    """壁に食い込んだ武器 — 反攻撃。**抜けない**ので根元が壁に埋まっている。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 28), np.uint8)
    for k in range(int(rng.integers(2, 4))):
        y = 1
        z = int(rng.integers(8, 20))
        x = int(rng.integers(8, 22))
        ln = int(rng.integers(7, 12))
        v[x:x + 2, y:y + ln, z:z + 2] = C['steel_d']  # 刀身（壁から生えて手前へ）
        v[x - 1:x + 3, y + ln - 2:y + ln + 1, z - 1:z + 3] = C['iron']  # 鍔
        v[x:x + 2, y + ln:y + ln + 4, z:z + 2] = C['timber_d']  # 柄
    return [('main', v, (0, 0, 0))]


def pillar_glass(name):
    """硝子の柱 — 反攻撃とガラスの城で共用。**稜だけ明るく**して透けを匂わせる。

    ボクセルは不透明前提なので**本当には透けない**（既存の宿題）。
    稜線を明るく・中を暗くすると、面が見えているのに向こうがある感じになる。
    """
    v = np.zeros((V, V, 50), np.uint8)
    v[12:20, 12:20, 0:46] = C['glass']
    for x, y in ((12, 12), (12, 19), (19, 12), (19, 19)):
        v[x:x + 1, y:y + 1, 0:46] = C['glass_l']
    v[11:21, 11:21, 0:3] = C['glass_l']
    v[11:21, 11:21, 45:48] = C['glass_l']
    v[13:19, 13:19, 47:50] = C['glass']
    return [('main', v, (0, 0, 0))]


def stone_floating(name):
    """宙に浮いた石 — 反攻撃の洞窟。**回る**（`MotionKind` にある動きで斥力を出す）。

    台座と石を**別の部品**にしてある。台座は接地して静止、石は接地せず回る
    ——台座が無いと「落ちてくる石」に見えるし、石が接地扱いだと影が地面に貼り付く。

    石は**横へ離す**。初版は中心付近へ 3 つ積んだので 1 つの塊に見え、回っても
    ほとんど動かなかった。**回る半径があって初めて「回っている」が読める。**
    """
    rng = rng_for(name)
    base = np.zeros((V, V, 4), np.uint8)
    base[12:20, 12:20, 0:3] = C['cob_d']
    base[13:19, 13:19, 3:4] = C['cob']
    stones = np.zeros((V, V, 26), np.uint8)
    for k in range(3):
        a = (k / 3.0 * 2.0 * math.pi) + float(rng.uniform(-0.3, 0.3))
        rad = 8.0 + float(rng.uniform(-1.5, 1.5))
        cx = int(16 + math.cos(a) * rad)
        cy = int(16 + math.sin(a) * rad)
        _blob(stones, cx, cy, 10 + k * 5, 3.4 - k * 0.5, C['cob'] if k % 2 else C['cob_d'])
    return [('base', base, (0, 0, 0)), ('stones', stones, (0, 0, 0))]


def stone_floating_parts():
    """台座は静止・石は**縦軸で回る**。支点は台座の真上（配列の中）＝罠 73。"""
    return [
        {'name': 'base', 'voxels': 'base', 'grounded': True,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
        {'name': 'stones', 'voxels': 'stones', 'grounded': False,
         'pivot': [16.0, 16.0, 16.0],
         'motion': {'kind': 'rotate', 'axis': 'z', 'speed': 0.08, 'phase': 0.0},
         'wind_k': 0.0},
    ]


# ---- カメレオン洞（18）: 擬態 ----


def slough(name):
    """抜け殻 — **薄く広く**（塊にすると死体に見える）。皮が捲れた縁だけ持ち上げる。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 5), np.uint8)
    for x in range(4, 28):
        for y in range(6, 26):
            if math.hypot((x - 16) * 0.7, y - 16) <= 9 and rng.random() < 0.85:
                v[x, y, 0] = C['cloth_d'] if rng.random() < 0.6 else C['cloth']
    for _ in range(3):  # 捲れた縁
        x, y = int(rng.integers(6, 24)), int(rng.integers(8, 22))
        v[x:x + 4, y:y + 3, 0:3] = C['cloth']
    return [('main', v, (0, 0, 0))]


def egg_cluster(name):
    """卵の塊 — カメレオンの巣。**大きさを揃えない**（揃えると人工物に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    for _ in range(7):
        cx, cy = int(rng.integers(10, 22)), int(rng.integers(10, 22))
        r = float(rng.uniform(2.2, 3.6))
        _blob(v, cx, cy, int(r) + 1, r, C['cloth'] if rng.random() < 0.6 else C['mgl_d'])
    v[:, :, 10:] = 0
    return [('main', v, (0, 0, 0))]


# ---- 暗闇の洞窟（19）: 置くものより**置かないもの**で語る ----


def crystal_black(name):
    """黒い結晶 — 光を吸う。**稜だけわずかに明るい**（真っ黒だと穴に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 20), np.uint8)
    for cx, cy, h, r0 in ((13, 14, 18, 3.6), (20, 17, 12, 2.8), (16, 21, 8, 2.2)):
        cx += int(rng.integers(-1, 2))
        for z in range(h):
            r = r0 * (1.0 - z / float(h)) + 0.6
            for x in range(V):
                for y in range(V):
                    if ((x - cx) ** 2 + (y - cy) ** 2) <= r * r:
                        v[x, y, z] = C['obs_l'] if z > h - 3 else C['obs']
    return [('main', v, (0, 0, 0))]


# ---- 竜の住みか（5）: 巣と宝と骸 ----


def eggshell_dragon(name):
    """割れた卵殻 — **下半分は残し、上半分を大きく欠く**。

    初版は縁を 1 ボクセルずつ確率で欠いたので全周がぎざぎざになり、**うにか珊瑚**に
    見えた。欠くのは**塊**（3〜5 マス）で、しかも**片側へ寄せる**——割れ口が 1 箇所に
    あることが「孵った」の読みになる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 20), np.uint8)
    cx = cy = 16
    open_a = float(rng.uniform(0.0, 2.0 * math.pi))  #!< 割れ口の向き
    for z in range(18):
        r = 9.5 * math.sin(math.pi * (z + 2) / 26.0)
        for x in range(V):
            for y in range(V):
                d = math.hypot(x - cx + 0.5, y - cy + 0.5)
                if not ((r - 2.0) <= d <= r):
                    continue
                a = math.atan2(y - cy + 0.5, x - cx + 0.5)
                if z > (15.0 - (math.cos(a - open_a) * 7.0)):
                    continue
                v[x, y, z] = C['bone'] if ((x // 3 + y // 3) % 4) else C['bone_d']
    for _ in range(4):  # 縁の欠け。**塊で**（1 ボクセルずつだと毛羽立つ）
        a = open_a + float(rng.uniform(-1.1, 1.1))
        ex = int(cx + math.cos(a) * 8)
        ey = int(cy + math.sin(a) * 8)
        w = int(rng.integers(3, 6))
        v[max(0, ex - w // 2):ex + w // 2, max(0, ey - w // 2):ey + w // 2, 8:18] = 0
    for _ in range(4):  # 落ちた殻の破片
        x, y = int(rng.integers(2, V - 5)), int(rng.integers(2, V - 5))
        v[x:x + 4, y:y + 3, 0:2] = C['bone_d']
    return [('main', v, (0, 0, 0))]


def claw_rock(name):
    """爪痕のついた岩 — **平らな面に 3 本の深い溝**。

    初版は瓦礫のような塊の上に 1 段の溝を引いたので、**溝がどこにも見えなかった**。
    岩を 1 枚の平たい塊にして面を作り、そこを幅 2・深さ 3 で抉る。**面がないと傷は付かない。**
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 14), np.uint8)
    v[3:29, 6:26, 0:9] = C['rock_d']
    v[4:28, 7:25, 8:11] = C['rock']
    for _ in range(4):  # 縁を崩す（直方体のままだと台に見える）
        x, y = int(rng.integers(2, V - 6)), int(rng.integers(4, V - 8))
        v[x:x + int(rng.integers(3, 7)), y:y + int(rng.integers(3, 6)), 8:11] = 0
    y0 = int(rng.integers(9, 15))
    slant = int(rng.integers(0, 2))
    for k in range(3):  # **3 本平行**。1 本だと傷、3 本だと爪
        for x in range(5, 27):
            yy = y0 + k * 4 + ((x - 5) * slant) // 9
            if 0 <= yy < V - 1:
                v[x, yy:yy + 2, 8:11] = 0
                v[x, yy:yy + 2, 7:8] = C['rock_dd']
    return [('main', v, (0, 0, 0))]


def coin_hoard(name):
    """溶けかけた金貨の山 — 竜の宝床。**平たく広げる**（尖らせると賽銭に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    for _ in range(16):
        cx, cy = int(rng.integers(7, 25)), int(rng.integers(7, 25))
        r = int(rng.integers(2, 5))
        h = max(1, 5 - int(math.hypot(cx - 16, cy - 16) / 4))
        v[cx - r:cx + r, cy - r:cy + r, 0:h] = rng.choice(
            [C['coin'], C['gold'], C['gold_d']], p=[0.44, 0.3, 0.26])
    for _ in range(3):  # 混ざった杯と宝石
        x, y = int(rng.integers(8, 22)), int(rng.integers(8, 22))
        v[x:x + 3, y:y + 3, 0:4] = rng.choice([C['qz_l'], C['crimson'], C['sky']])
    return [('main', v, (0, 0, 0))]


def scale_shed(name):
    """落ちた鱗 — **1 枚が大きく、厚みがある**。竜の大きさは鱗 1 枚で言う。

    初版は 4 枚を薄く重ねたので赤い染みにしか見えなかった。**2 枚**に減らし、
    厚みを 4 段まで上げて縁を明るくする（板であることは縁で読む）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 6), np.uint8)
    for k in range(2):
        cx = 11 + k * 10 + int(rng.integers(-1, 2))
        cy = 13 + k * 6 + int(rng.integers(-1, 2))
        shade = (C['crimson'], C['rust'])[k]
        for x in range(cx - 9, cx + 10):
            for y in range(cy - 6, cy + 7):
                if not ((0 <= x < V) and (0 <= y < V)):
                    continue
                d = ((x - cx) / 9.0) ** 2 + ((y - cy) / 6.0) ** 2
                if d <= 1.0:
                    v[x, y, 0:max(1, 4 - int(d * 3))] = shade  # 中央が厚い（伏せた皿）
                elif d <= 1.25:
                    v[x, y, 0:1] = C['fl_edge']
        v[max(0, cx - 6):cx + 7, cy:cy + 1, 3:5] = C['fl_edge']  # 稜のつや
    return [('main', v, (0, 0, 0))]


def bones_huge(name):
    """巨大な骨 — 竜の住みかと地獄で共用。**1 本がマスをまたぐ**大きさ。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    #! 肋骨（弧を描いて立ち上がる）。**3 本**並べる。
    for k in range(3):
        y = 8 + k * 7
        for x in range(2, 28):
            z = int(7 * math.sin(math.pi * (x - 2) / 26.0))
            v[x:x + 2, y:y + 3, max(0, z - 1):z + 2] = C['bone'] if k % 2 else C['bone_d']
    #! 背骨（節をつける）。
    for x in range(1, 30, 4):
        v[x:x + 3, 20:24, 0:3] = C['bone_d']
    _sticks(v, rng, 2, 0, [C['bone']], length=(8, 13))
    return [('main', v, (0, 0, 0))]


# ---- 森（7）: 主はシェロブ（闇の蜘蛛） ----


def spider_web(name):
    """蜘蛛の巣 — `floor_meaning.h:51` が最初から予定していたもの（作っていなかった）。

    **放射と同心の 2 種類の糸**が要る。片方だけだと網に見えない。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 24), np.uint8)
    cx = cy = 16
    spokes = 8
    for k in range(spokes):  # 放射
        ang = k / float(spokes) * 2.0 * math.pi
        for t in range(3, 15):
            x = int(cx + math.cos(ang) * t)
            y = int(cy + math.sin(ang) * t)
            v[x, y, 14 + (t // 4)] = C['web']
    for r in (5, 9, 13):  # 同心（多角形で結ぶ）
        pts = []
        for k in range(spokes):
            ang = k / float(spokes) * 2.0 * math.pi
            pts.append((int(cx + math.cos(ang) * r), int(cy + math.sin(ang) * r)))
        for k in range(spokes):
            x0, y0 = pts[k]
            x1, y1 = pts[(k + 1) % spokes]
            for t in range(9):
                x = int(x0 + (x1 - x0) * t / 8.0)
                y = int(y0 + (y1 - y0) * t / 8.0)
                if (0 <= x < V) and (0 <= y < V):
                    v[x, y, 14 + (r // 5)] = C['web']
    #! 掛かった獲物。**1 つだけ**（多いと巣ではなく物置に見える）。
    if rng.random() < 0.6:
        v[13:17, 13:17, 10:15] = C['cloth_d']
    return [('main', v, (0, 0, 0))]


def log_fallen(name):
    """倒木と切り株 — 森の部屋の縁。**木口（切り口）を明るく**するのが木の読み。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    y0 = int(rng.integers(8, 18))
    r = 4
    for x in range(1, 30):
        for dy in range(-r, r + 1):
            for dz in range(0, r * 2):
                if (dy * dy + (dz - r) ** 2) <= r * r:
                    v[x, y0 + dy, dz] = C['bark'] if rng.random() < 0.8 else C['bark_l']
    v[0:2, y0 - r:y0 + r + 1, 0:r * 2] = C['log_end']  # 木口
    for _ in range(3):  # 苔
        x = int(rng.integers(4, 26))
        v[x:x + 4, y0 - 2:y0 + 2, r * 2 - 2:r * 2] = C['moss']
    return [('main', v, (0, 0, 0))]


def cocoon(name):
    """繭 — シェロブの森。**紡いだ筋**を縦に入れる（無地だと石に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 22), np.uint8)
    for z in range(20):
        r = 6.0 * math.sin(math.pi * (z + 1) / 22.0) + 1.0
        for x in range(V):
            for y in range(V):
                if math.hypot(x - 16 + 0.5, y - 16 + 0.5) <= r:
                    v[x, y, z] = C['web'] if ((x + z) % 5) else C['cloth_d']
    v[15:17, 15:17, 20:22] = C['web']  # 吊り糸
    return [('main', v, (0, 0, 0))]


def fern(name):
    """背の高い羊歯 — 森。**風で揺れる**（森は地上に近いので揺れてよい）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 24), np.uint8)
    for _ in range(int(rng.integers(4, 7))):
        cx, cy = int(rng.integers(8, 24)), int(rng.integers(8, 24))
        h = int(rng.integers(12, 22))
        v[cx:cx + 2, cy:cy + 2, 0:h] = C['stalk_d']
        #! 羽状の葉。**左右へ張り出す**のが羊歯の読み。
        for z in range(4, h, 3):
            w = 1 + (h - z) // 5
            shade = C['leaf_m'] if (z // 3) % 2 else C['leaf_l']
            v[max(0, cx - w):cx + w + 2, cy:cy + 2, z:z + 1] = shade
            v[cx:cx + 2, max(0, cy - w):cy + w + 2, z:z + 1] = shade
    return [('main', v, (0, 0, 0))]


def fairy_ring(name):
    """茸の輪 — 森の部屋。**輪であること**が読みで、散らすとただの茸になる。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 11), np.uint8)
    for k in range(9):
        ang = (k / 9.0 * 2.0 * math.pi) + float(rng.uniform(-0.12, 0.12))
        cx = int(16 + math.cos(ang) * 11)
        cy = int(16 + math.sin(ang) * 11)
        h = int(rng.integers(4, 8))
        r = int(rng.integers(2, 4))
        v[cx:cx + 2, cy:cy + 2, 0:h] = C['stem']
        v[max(0, cx - r):cx + r + 2, max(0, cy - r):cy + r + 2, h:h + 2] = C['mbr_d']
        v[max(0, cx - r + 1):cx + r + 1, max(0, cy - r + 1):cy + r + 1, h + 1:h + 3] = C['mbr']
    return [('main', v, (0, 0, 0))]


# ---- 山（14）: 主は大鷲王『ソロンドール』。**既存の `alpine` と `crag` が使える** ----


def cairn(name):
    """ケルン（積み石） — 道しるべ。**上へ行くほど小さく**、わずかにずらして積む。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 26), np.uint8)
    cx = cy = 16
    z = 0
    for k in range(6):
        w = 9 - k
        ox, oy = int(rng.integers(-1, 2)), int(rng.integers(-1, 2))
        h = int(rng.integers(3, 5))
        shade = rng.choice([C['crag'], C['crag_d'], C['crag_dd']], p=[0.4, 0.34, 0.26])
        v[cx - w // 2 + ox:cx + (w + 1) // 2 + ox,
          cy - w // 2 + oy:cy + (w + 1) // 2 + oy, z:z + h] = shade
        z += h
    return [('main', v, (0, 0, 0))]


def nest_eagle(name):
    """大鷲の巣 — **大枝を組む**（藁の巣を大きくしただけでは鷲にならない）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 14), np.uint8)
    #! 外周を大枝で組む。1 本ずつ向きを替えて交差させる。
    for k in range(18):
        ang = k / 18.0 * 2.0 * math.pi
        cx = int(16 + math.cos(ang) * 12)
        cy = int(16 + math.sin(ang) * 12)
        ln = int(rng.integers(6, 12))
        z = int(rng.integers(0, 8))
        shade = C['bark'] if rng.random() < 0.6 else C['bark_l']
        if abs(math.cos(ang)) > abs(math.sin(ang)):
            v[max(0, cx - 1):cx + 2, max(0, cy - ln // 2):cy + ln // 2, z:z + 2] = shade
        else:
            v[max(0, cx - ln // 2):cx + ln // 2, max(0, cy - 1):cy + 2, z:z + 2] = shade
    v[10:22, 10:22, 0:2] = C['bark_l']  # 敷いた小枝
    for _ in range(4):  # 羽根
        x, y = int(rng.integers(11, 21)), int(rng.integers(11, 21))
        v[x:x + 5, y:y + 2, 2:3] = C['cloth_d']
    return [('main', v, (0, 0, 0))]


def snow_drift(name):
    """雪だまり — 山の高い所。**丸く盛る**（直方体だと白い木箱に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    for _ in range(3):  # 先に岩（雪は岩の陰に溜まる）
        x, y = int(rng.integers(6, 24)), int(rng.integers(6, 24))
        v[x:x + 5, y:y + 4, 0:5] = C['crag_d']
    for _ in range(10):
        cx, cy = int(rng.integers(6, 26)), int(rng.integers(6, 26))
        _blob(v, cx, cy, 0, float(rng.uniform(3.0, 6.0)),
              C['snow'] if rng.random() < 0.7 else C['snow_d'])
    v[:, :, 6:] = 0  # 背は抑える
    return [('main', v, (0, 0, 0))]


def volcanic_bomb(name):
    """火山弾 — 丸い黒石。**表面が割れている**（紡錘状の割れ目）のが火山弾の読み。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 14), np.uint8)
    for cx, cy, r in ((14, 15, 6.2), (22, 20, 4.0), (10, 23, 3.2)):
        cx += int(rng.integers(-1, 2))
        _blob(v, cx, cy, int(r) - 1, r, C['crust'])
        _blob(v, cx, cy, int(r) - 1, r - 1.2, C['crust_l'])
        for k in range(3):  # 割れ目
            a = rng.uniform(0, math.pi)
            for t in range(-int(r), int(r) + 1):
                x = int(cx + math.cos(a) * t)
                y = int(cy + math.sin(a) * t)
                if (0 <= x < V) and (0 <= y < V):
                    v[x, y, int(r) - 1] = C['lava_o'] if rng.random() < 0.3 else C['crust']
    return [('main', v, (0, 0, 0))]


def fumarole(name):
    """噴気孔 — ガスが立つ。**孔（暗い口）と気（風で揺れる塊）を別の部品**にする。"""
    rng = rng_for(name)
    vent = np.zeros((V, V, 6), np.uint8)
    for x in range(V):
        for y in range(V):
            d = math.hypot(x - 16 + 0.5, y - 16 + 0.5)
            if 4.0 <= d <= 8.0:
                vent[x, y, 0:int(rng.integers(2, 5))] = (
                    C['sulf_d'] if rng.random() < 0.4 else C['crust'])
            elif d < 4.0:
                vent[x, y, 0] = C['dark']
    gas = np.zeros((V, V, 26), np.uint8)
    for z in range(6, 26):
        r = 1.5 + (z - 6) * 0.22
        for x in range(V):
            for y in range(V):
                if math.hypot(x - 16 + 0.5, y - 16 + 0.5) <= r and rng.random() < 0.5:
                    gas[x, y, z] = C['gas'] if rng.random() < 0.7 else C['gas_y']
    return [('vent', vent, (0, 0, 0)), ('gas', gas, (0, 0, 0))]


def fumarole_parts():
    """孔は静止、気は**風**（`lava_bubble` のガスと同じ係数の考え方）。"""
    return [
        {'name': 'vent', 'voxels': 'vent', 'grounded': True,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
        {'name': 'gas', 'voxels': 'gas', 'grounded': False,
         'motion': {'kind': 'wind'}, 'wind_k': 0.6},
    ]


def sulphur_crust(name):
    """硫黄の結晶 — 火山。**黄色は狭く**（面で出すと毒々しい）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    _scatter_lumps(v, rng, 9, (8, 24), (2, 6), (2, 6),
                   [C['crust'], C['sulf_d'], C['crust_l']], [0.46, 0.3, 0.24])
    for _ in range(5):  # 結晶の粒
        x, y = int(rng.integers(8, 23)), int(rng.integers(8, 23))
        v[x:x + 2, y:y + 2, 0:int(rng.integers(3, 7))] = C['sulf']
    return [('main', v, (0, 0, 0))]


def charred_wood(name):
    """炭化した木 — 火山。**燃え落ちて横たわった幹**。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 9), np.uint8)
    y0 = int(rng.integers(10, 20))
    for x in range(2, 28):
        r = 3 - (x // 12)
        v[x, max(0, y0 - r):y0 + r + 1, 0:r * 2] = C['char'] if rng.random() < 0.75 else C['char_l']
    for _ in range(4):  # 折れた枝
        x = int(rng.integers(4, 24))
        ln = int(rng.integers(4, 8))
        v[x:x + 2, y0 + 3:y0 + 3 + ln, 0:2] = C['char']
    v[26:29, y0 - 2:y0 + 3, 0:4] = C['lava_o']  # まだ熾がある切り口
    return [('main', v, (0, 0, 0))]


def iron_stake(name):
    """赤熱した鉄杭と鎖 — 地獄。**人が作った責め具**であることが火山との差。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    v[12:20, 12:20, 0:3] = C['crust']  # 座
    v[14:18, 14:18, 3:26] = C['iron']
    v[14:18, 14:18, 20:26] = C['rust']  # 上ほど焼けている
    v[13:19, 13:19, 26:28] = C['lava_o']
    x, y = 18, 16
    for k in range(7):  # 垂れた鎖
        v[x:x + 2, y:y + 2, max(0, 22 - k * 3):24 - k * 3] = C['iron_l'] if k % 2 else C['iron']
        x += int(rng.integers(0, 3))
        x = min(x, V - 3)
    return [('main', v, (0, 0, 0))]


def skull_pillar(name):
    """角のある頭蓋の柱 — 地獄の部屋の縁。柱の**頂に頭蓋**を載せる。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 44), np.uint8)
    v[12:20, 12:20, 0:32] = C['crust']
    v[11:21, 11:21, 0:3] = C['crust_l']
    v[11:21, 11:21, 30:33] = C['crust_l']
    v[12:20, 12:19, 33:40] = C['bone_d']  # 頭蓋
    v[13:19, 12:15, 33:36] = C['bone']  # 顎
    v[13:15, 12, 36:38] = C['dark']
    v[17:19, 12, 36:38] = C['dark']
    for x0, dx in ((9, -1), (20, 1)):  # 角（**上へ反る**）
        for k in range(4):
            v[x0 + dx * k:x0 + dx * k + 2, 14:17, 38 + k:40 + k] = C['bone_d']
    if rng.random() < 0.5:
        v[15:17, 15:17, 40:42] = C['lava_y']  # 眼窩の火
    return [('main', v, (0, 0, 0))]


def bones_hung(name):
    """鎖で吊られた骨 — 地獄の行き止まり。**吊るされた籠に骨が詰まっている**。

    初版は鎖の先に小さな塊を付けただけで、何が下がっているか読めなかった。
    籠を大きくし、**肋と頭蓋を外へはみ出させる**（籠の中だけだと箱に見える）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 40), np.uint8)
    x = 16
    for z in range(38, 22, -2):  # 鎖
        v[x:x + 2, 15:17, z:z + 2] = C['iron'] if (z // 2) % 2 else C['iron_l']
        x = max(8, min(V - 10, x + int(rng.integers(-1, 2))))
    for z in (10, 16, 22):  # 籠の輪。**中が見える**ことが檻の読み
        for a in range(16):
            ang = a / 16.0 * 2.0 * math.pi
            bx = int(x + 1 + math.cos(ang) * 7)
            by = int(16 + math.sin(ang) * 7)
            v[bx:bx + 2, by:by + 2, z:z + 2] = C['iron']
    for a in range(4):  # 縦棒
        ang = a / 4.0 * 2.0 * math.pi + 0.4
        bx = int(x + 1 + math.cos(ang) * 7)
        by = int(16 + math.sin(ang) * 7)
        v[bx:bx + 2, by:by + 2, 10:24] = C['iron_l']
    v[max(0, x - 2):x + 5, 13:19, 12:18] = C['bone_d']  # 中身
    v[max(0, x - 1):x + 4, 12:14, 12:15] = C['bone']  # 頭蓋
    v[x:x + 2, 12, 15:17] = C['dark']
    v[x + 2:x + 4, 12, 15:17] = C['dark']
    for _ in range(3):  # はみ出した骨
        z = int(rng.integers(10, 22))
        v[max(0, x - 6):x + 8, 15:17, z:z + 2] = C['bone']
    return [('main', v, (0, 0, 0))]


def gravestone(name):
    """墓石 — 上が丸い板。**わずかに傾ける**（真っ直ぐだと新しい墓に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 26), np.uint8)
    lean = int(rng.integers(0, 3))
    for z in range(22):
        off = (z * lean) // 12
        w = 10 if z < 16 else 10 - (z - 16)
        v[16 - w // 2 + off:16 + (w + 1) // 2 + off, 14:17, z] = (
            C['rock'] if rng.random() < 0.7 else C['rock_l'])
    v[10:22, 12:19, 0:3] = C['rock_d']  # 台
    for k in range(3):  # 碑文（**彫る**）
        v[13:19, 14, 8 + k * 3:9 + k * 3] = 0
    if rng.random() < 0.5:
        v[12:20, 12:14, 0:2] = C['moss']  # 枯れた花の跡と苔
    return [('main', v, (0, 0, 0))]


def grave_broken(name):
    """崩れた墓標 — 行き止まり。**折れて倒れている**。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    v[10:16, 13:20, 0:5] = C['rock_d']  # 折れた根元（立っている）
    v[16:28, 12:19, 0:3] = C['rock']  # 倒れた板
    v[16:18, 12:19, 0:4] = C['rock_l']  # 折れ口
    _scatter_lumps(v, rng, 4, (4, 26), (2, 5), (1, 4),
                   [C['rock_d'], C['rock_dd']], [0.6, 0.4])
    return [('main', v, (0, 0, 0))]


def sarcophagus(name):
    """石棺 — 部屋の縁。**蓋がずれている**のが墓地の読み（閉じていると台に見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 16), np.uint8)
    v[4:28, 9:23, 0:11] = C['rock_d']
    v[6:26, 11:21, 8:11] = C['dark']  # 中（空）
    off = int(rng.integers(3, 9))
    v[4 + off:26, 9:23, 11:14] = C['rock']  # ずれた蓋
    v[6 + off:24, 11:21, 14:15] = C['rock_l']  # 蓋の彫り
    return [('main', v, (0, 0, 0))]


def grave_open(name):
    """掘り返された墓 — 部屋の中。**土の山と穴の縁**で「掘り返した」を言う。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 9), np.uint8)
    for x in range(V):  # 縁（盛り土）
        for y in range(V):
            d = max(abs(x - 16) / 11.0, abs(y - 16) / 7.0)
            if 0.85 <= d <= 1.25:
                v[x, y, 0:int(rng.integers(2, 6))] = C['soil'] if rng.random() < 0.7 else C['dirt_d']
    v[7:25, 11:21, 0] = C['dark']  # 穴
    v[9:15, 13:19, 0:3] = C['timber_d']  # 割れた棺の板
    _sticks(v, rng, 2, 0, [C['bone'], C['bone_d']], length=(5, 9))
    return [('main', v, (0, 0, 0))]


# ---- 水没した遺跡（11）とルルイエ（13）: **水は揺れるもので言う** ----


def column_fallen(name):
    """崩れた円柱 — 横たわって節ごとに割れている。水没した遺跡とルルイエで共用。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    y0 = 16
    x = 1
    while x < 30:
        seg = int(rng.integers(5, 9))
        gap = int(rng.integers(0, 3))
        r = 4
        for xx in range(x, min(x + seg, 30)):
            for dy in range(-r, r + 1):
                for dz in range(0, r * 2):
                    if (dy * dy + (dz - r) ** 2) <= r * r:
                        v[xx, y0 + dy, dz] = C['flag'] if rng.random() < 0.75 else C['flag_d']
        v[x, y0 - r:y0 + r + 1, 0:r * 2] = C['marb_g']  # 割れ口
        x += seg + gap
    for _ in range(3):  # 溝彫り（円柱の縦筋）
        xx = int(rng.integers(3, 27))
        v[xx, y0 - 3:y0 + 4, 6:8] = C['joint']
    return [('main', v, (0, 0, 0))]


def kelp(name):
    """海藻 — **風で揺らすと水中の揺らぎに読める**。水そのものではなく揺れるもので言う。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    for _ in range(int(rng.integers(4, 7))):
        cx, cy = int(rng.integers(7, 25)), int(rng.integers(7, 25))
        h = int(rng.integers(16, 29))
        shade = rng.choice([C['tent'], C['tent_d'], C['moss_d']], p=[0.44, 0.32, 0.24])
        for z in range(h):
            #! **ゆるく蛇行させる**（真っ直ぐだと棒に見える）。
            ox = int(2.0 * math.sin(z * 0.35))
            v[max(0, cx + ox):cx + ox + 2, cy:cy + 3, z] = shade
        v[max(0, cx - 1):cx + 3, cy:cy + 3, h - 3:h] = C['verd']  # 気胞
    return [('main', v, (0, 0, 0))]


def statue_worn(name):
    """顔の溶けかけた石像 — ヌメノールの遺跡。**顔が読めない**ことが「沈んで久しい」。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 40), np.uint8)
    v[9:23, 10:22, 0:4] = C['flag_d']  # 台
    v[12:20, 13:19, 4:26] = C['flag']  # 胴
    v[10:22, 13:19, 20:24] = C['flag_d']  # 肩
    v[13:19, 13:19, 26:34] = C['flag']  # 頭
    #! 侵食。**上ほど欠く**（水面に近いほど削られた、という読み）。
    for _ in range(14):
        x, y = int(rng.integers(10, 22)), int(rng.integers(12, 20))
        z = int(rng.integers(18, 34))
        v[x:x + int(rng.integers(2, 5)), y:y + 2, z:z + int(rng.integers(2, 4))] = 0
    for _ in range(6):  # 付着した緑青と貝
        x, y = int(rng.integers(11, 21)), int(rng.integers(12, 20))
        v[x:x + 2, y:y + 2, int(rng.integers(4, 20)):][:, :, 0:2] = C['verd']
    return [('main', v, (0, 0, 0))]


def wreck_rib(name):
    """難破船の肋材 — 水没した遺跡。**曲がった梁が並ぶ**のが船体の読み。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 22), np.uint8)
    for k in range(4):
        y = 5 + k * 7
        for z in range(20):
            off = int(6.0 * math.sin(math.pi * z / 30.0))
            x = 4 + off
            v[x:x + 3, y:y + 2, z] = C['timber_d'] if k % 2 else C['timber']
    v[2:30, 3:5, 0:3] = C['timber_d']  # 竜骨
    for _ in range(4):  # 板の残り
        y = int(rng.integers(5, 24))
        z = int(rng.integers(2, 14))
        v[4:14, y:y + 2, z:z + 2] = C['oak']
    return [('main', v, (0, 0, 0))]


def stone_tilted(name):
    """傾いた石 — ルルイエ。**角度が合わない**ことが非ユークリッドの読み。

    初版は段ごとに横へずらしたので**階段状の積み石**になった。傾きは
    「上下で同じ断面が平行にずれる」ことで出る（斜めに立った 1 枚の石板）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    h = int(rng.integers(20, 29))
    w = int(rng.integers(9, 13))
    d = int(rng.integers(5, 8))
    ang = float(rng.uniform(0.0, 2.0 * math.pi))
    lean = float(rng.uniform(6.0, 10.0))  #!< 上端で 6〜10 マスずれる＝はっきり傾く
    for z in range(h):
        t = z / float(h - 1)
        x0 = 16 - w // 2 + int(math.cos(ang) * lean * t)
        y0 = 16 - d // 2 + int(math.sin(ang) * lean * t)
        #! **色は 1 つ**。段ごとに変えると（初版がそうだった）ボクセルの段差が縞で
        #! 強調されて「皿を積んだ塔」に見える。傾いた 1 枚の石板に読ませたい。
        v[max(0, x0):x0 + w, max(0, y0):y0 + d, z] = C['flag_d']
    for _ in range(6):  # 苔と欠け（塊で。段差の縞を作らない向きに散らす）
        t = float(rng.uniform(0.1, 0.9))
        x0 = 16 - w // 2 + int(math.cos(ang) * lean * t)
        y0 = 16 - d // 2 + int(math.sin(ang) * lean * t)
        z = int(t * (h - 3))
        bx = max(0, x0 + int(rng.integers(0, max(1, w - 3))))
        by = max(0, y0 + int(rng.integers(0, max(1, d - 2))))
        v[bx:bx + 3, by:by + 2, z:z + 3] = C['tent_d'] if rng.random() < 0.6 else C['cob_d']
    #! 根元の土（傾いた石が地面から生えていることを言う）。
    v[16 - w // 2 - 2:16 + w // 2 + 2, 16 - d // 2 - 2:16 + d // 2 + 2, 0:2] = C['rock_dd']
    return [('main', v, (0, 0, 0))]


def tentacle_carve(name):
    """触手の彫刻 — ルルイエの壁際。**うねる帯**を壁から生やす。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 24), np.uint8)
    for k in range(int(rng.integers(2, 4))):
        x = int(rng.integers(6, 24))
        z = int(rng.integers(2, 10))
        r = 3
        for t in range(16):
            x += int(1.6 * math.cos(t * 0.5))
            z += 1
            x = max(2, min(V - 5, x))
            if z >= 22:
                break
            v[x:x + r, 1:1 + r, z:z + 2] = C['tent'] if t % 3 else C['tent_d']
            if t % 4 == 0:  # 吸盤
                v[x:x + 2, 1 + r:2 + r, z:z + 1] = C['cloth_d']
    return [('main', v, (0, 0, 0))]


def glyph_slab(name):
    """刻印のある巨石 — ルルイエ。印は**彫る**（色で描くと落書きに見える）。

    初版は幅 3・深さ 1 の窪みだったので、真横から見ないと 1 画素も見えなかった。
    **南面（カメラ側）に幅 5・深さ 3** で彫り、底へ緑を差す。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 20), np.uint8)
    v[3:29, 11:22, 0:16] = C['flag_d']
    v[4:28, 12:21, 16:17] = C['joint']
    #! **前後の両面に彫る**。初版は南面だけだったので、置く向きしだいで
    #! 1 画素も見えなかった（プレハブの向きは置く側が決めるので、片面に賭けない）。
    for k in range(int(rng.integers(3, 5))):
        x = 5 + k * 6
        z = int(rng.integers(3, 9))
        for y0, y1 in ((11, 14), (19, 22)):
            v[x:x + 5, y0:y1, z:z + 5] = 0
            v[x:x + 5, y0:y1, z + 2:z + 3] = C['tent_d']  # 横棒（底に緑）
            v[x + 2:x + 3, y0:y1, max(0, z - 2):z + 8] = 0
    for _ in range(4):  # 垂れた粘液
        x = int(rng.integers(5, 26))
        v[x:x + 3, 11:13, 0:int(rng.integers(3, 8))] = C['tent']
    return [('main', v, (0, 0, 0))]


def glass_shards(name):
    """砕けたガラスの破片 — **立てて刺す**（寝かせると水たまりに見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 14), np.uint8)
    for _ in range(9):
        x, y = int(rng.integers(6, 26)), int(rng.integers(6, 26))
        h = int(rng.integers(3, 12))
        w = int(rng.integers(1, 3)) + 1
        v[x:x + w, y:y + w, 0:h] = C['glass']
        v[x:x + w, y:y + w, h - 1:h] = C['glass_l']  # 割れ口の稜
    return [('main', v, (0, 0, 0))]


def glass_table(name):
    """ガラスの机と椅子 — ガラスの城。**脚を細く**して重さを消す。"""
    v = np.zeros((V, V, 16), np.uint8)
    v[6:26, 11:21, 12:14] = C['glass']
    v[6:26, 11:21, 14:15] = C['glass_l']
    for x0 in (7, 23):
        for y0 in (12, 18):
            v[x0:x0 + 2, y0:y0 + 2, 0:12] = C['glass_l']
    v[9:15, 23:29, 6:8] = C['glass']  # 椅子（座面）
    v[9:15, 27:29, 8:16] = C['glass_l']  # 背
    for x0 in (9, 13):
        for y0 in (23, 27):
            v[x0:x0 + 1, y0:y0 + 1, 0:6] = C['glass_l']
    return [('main', v, (0, 0, 0))]


def cloud_puff(name):
    """雲だまり — 天界の行き止まり。**地面に接する**（浮かせると床が抜けて見える）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    for _ in range(8):
        cx, cy = int(rng.integers(8, 24)), int(rng.integers(8, 24))
        r = float(rng.uniform(3.0, 5.5))
        cz = int(rng.integers(2, 5))
        _blob(v, cx, cy, cz, r, C['cloud'] if rng.random() < 0.7 else C['cloud_d'])
    v[:, :, 10:] = 0
    return [('main', v, (0, 0, 0))]


def column_white(name):
    """白い柱と蔦 — 天界。**溝彫り（フルート）**が古典の柱の読み。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 52), np.uint8)
    cx = cy = 16
    for z in range(48):
        r = 5.2 if z > 3 else 6.4
        for x in range(V):
            for y in range(V):
                d = math.hypot(x - cx + 0.5, y - cy + 0.5)
                if d <= r:
                    ang = math.atan2(y - cy + 0.5, x - cx + 0.5)
                    flute = (int((ang + math.pi) / (math.pi / 6)) % 2) == 0
                    v[x, y, z] = C['marb_d'] if (flute and d > r - 1.2) else C['marb_l']
    v[9:23, 9:23, 48:52] = C['marb']  # 柱頭
    for _ in range(int(rng.integers(2, 4))):  # 蔦
        ang = rng.uniform(0, 2 * math.pi)
        for z in range(4, 44):
            a = ang + z * 0.22
            x = int(cx + math.cos(a) * 5.6)
            y = int(cy + math.sin(a) * 5.6)
            if (0 <= x < V) and (0 <= y < V):
                v[x, y, z] = C['leaf_m'] if (z % 3) else C['leaf_l']
    return [('main', v, (0, 0, 0))]


def statue_winged(name):
    """翼の生えた像 — 天界。**翼が横へ張る**のが読みで、背中に貼ると塊に見える。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 44), np.uint8)
    v[10:22, 11:21, 0:4] = C['marb_g']
    v[13:19, 14:18, 4:24] = C['marb_l']  # 胴
    v[14:18, 14:18, 24:31] = C['marb']  # 頭
    for x0, dx in ((12, -1), (19, 1)):  # 翼
        for k in range(6):
            h = 14 - k * 2
            v[x0 + dx * k:x0 + dx * k + 1, 17:20, 16 + k:16 + k + h] = (
                C['marb_l'] if k % 2 else C['marb'])
    if rng.random() < 0.5:
        v[15:17, 12:14, 12:20] = C['gold_d']  # 手に持つ笏
    return [('main', v, (0, 0, 0))]


def light_font(name):
    """光の泉 — 天界の部屋の中。**受け皿と水面**。自発光は置く側が乗せる。"""
    v = np.zeros((V, V, 18), np.uint8)
    for z in range(10):
        r = 4.0 + z * 0.55
        for x in range(V):
            for y in range(V):
                d = math.hypot(x - 16 + 0.5, y - 16 + 0.5)
                if d <= r:
                    v[x, y, z] = C['marb_l'] if d > r - 1.4 else C['marb_g']
    for x in range(V):  # 水面
        for y in range(V):
            if math.hypot(x - 16 + 0.5, y - 16 + 0.5) <= 8.0:
                v[x, y, 10:12] = C['lit']
    v[14:18, 14:18, 12:17] = C['lit']  # 立ち上る光
    return [('main', v, (0, 0, 0))]


# ================================ 第 6 期（2026-08-11）: B〜G 系統の材 =================
#
# 第 5 期で A 系統（素材から差が出ない 9 本）が埋まった。残るのは B〜G の 11 本だが、
# **11 本ぜんぶに材を入れるのは間違いである**（罠 113）。役割の既定の材が出るのは
# 「地形の細別を持たないマス」だけで、細別を持つマスは表（`terrain_prefabs.jsonc`）が正だから、
# コアが砂地や水や溶岩や木を敷いている所へ材を作っても**絵にほとんど出ない**。
#
# そこで の内訳（床／壁／外壁・内壁）を役割ごとに読み直して、
# **既定へ落ちる割合が高い役割にだけ**材を入れた。作ったものと、作らなかったものは次のとおり。
#
# ====  ==============  ==========================================  ==========
# ID    ダンジョン      入れた役割                                    個
# ====  ==============  ==========================================  ==========
# 5     竜の住みか      壁（花崗岩 90）・岩盤                          20
# 6     墓地            部屋の床（85）・通路の床・壁（75）・岩盤       40
# 8     火山            壁（花崗岩 90）・岩盤                          20
# 9     地獄            岩盤のみ（壁は深い溶岩 80 ＝ 細別）            10
# 10    天界            床のみ（壁は永久壁 100 ＝ 細別）               20
# 11    水没した遺跡    床のみ（壁は深い水 80 ＝ 細別）                20
# 13    ルルイエ        部屋の床（50）・通路の床・壁（100）・岩盤      40
# ====  ==============  ==========================================  ==========
#
# **入れなかった 4 本**とその理由:
#
# - **3 オークの洞窟** … 床は砂地 70／草 30、壁は既に `wall_rock` を共有している。
#   岩盤 10 個だけが残るが、イークと「掘り抜いた穴」であることが同じなので分ける理由が無い
#   （§30.1 で床を落としたときと同じ判断）
# - **7 森** … 床は草 85／花 5／水 10、壁は木 90。**役割の既定へ落ちるマスがほとんど無い**
# - **14 山** … 床は草 100、壁は山脈壁 100。同上
# - **20 ガラスの城** … 床も壁もガラス 100。同上（透過は別の宿題）


# ---- 5 竜の住みか（60–72・砂地の床・溶岩の川・`d D`。壁の 90% が花崗岩）----
#
# **炎で灼けた岩**。既定の花崗岩との差は色だけで足りる——ここも掘り抜いた穴であって、
# 形を作り直す理由は無い（暗闇の洞窟で通したのと同じ手＝§30.3）。岩山（`crag_*`）の
# 日灼けと混ざらないよう、**褐色ではなく煤の混じった褐色**にしてある。

_LAIR_MAP = {'rock_dd': 'lair_dd', 'rock_d': 'lair_d', 'band': 'char',
             'rock': 'lair', 'rock_l': 'lair_l'}


def wall_lair(name):
    """竜の住みかの壁 — 灼けた岩に**爪痕**。

    爪痕は**3 本を平行に**引く（1 本では亀裂と見分けが付かない）。彫ってから底に
    暗い色を敷くのは罠 104 の対で、塊の上に線を描いても 1 画素も見えない。
    """
    _, v, org = wall_rock(name)[0]
    v = _recolour(v, _LAIR_MAP)
    rng = rng_for(name + '_claw')
    #! 爪痕。**10 枚のうち 6 枚**（全部に付けると壁紙になる。罠 114 と同じ話）。
    if int(name[-2:]) % 10 not in (3, 7, 0, 4):
        for face in range(4):
            u0 = int(rng.integers(4, V - 12))
            w0 = int(rng.integers(4, max(5, WALL_H - 16)))
            ln = int(rng.integers(9, 15))
            for k in range(3):
                u = u0 + k * 4
                for d in range(ln):
                    _carve_relief(v, face, u, u + 2, w0 + d, w0 + d + 1, 2)
                    _paint_face(v, face, u, u + 2, w0 + d, w0 + d + 1, 2, C['lair_dd'])
    #! 煤の染み（火を吐いた跡）。**塊で置く**（1 ボクセルずつ振ると点描＝罠 38）。
    _skin_lumps(v, rng, [C['char'], C['lair_dd'], C['char_l']], [0.44, 0.34, 0.22], p_cover=0.16)
    return [('main', v, org)]


def bedrock_lair(name):
    """竜の住みかの地山 — 灼けた岩の一族。**爪痕は持たない**（掘られていない面）。"""
    _, v, org = bedrock_raw(name)[0]
    v = _recolour(v, _LAIR_MAP)
    rng = rng_for(name + '_sear')
    _skin_lumps(v, rng, [C['lair_d'], C['char'], C['lair_dd']], [0.42, 0.30, 0.28], p_cover=0.20)
    return [('main', v, org)]


# ---- 6 墓地（40–70・床 85 が既定・壁 75 が花崗岩・水の床 15。主はヴェクナ）----
#
# **納骨堂**。A 系統の城（人が造った建物）と洞窟（掘り抜いた穴）のどちらでもない
# 第 3 の作りで、**人が造ったが手入れされていない**——切石は積んであるが、目地は苔で
# 埋まり、水が伝った筋が残っている。城（白大理石・磨いてある）と正面から分かれる。


def floor_tomb(name):
    """墓地の部屋の床 — **墓碑を転用した板石**。

    大きさがまちまちなのが読みで、正方形に揃えると城か迷宮になる。彫られた文字は
    **薄く 1 段**（読めなくてよい。読めると看板になる）。目地には苔を差す。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['tomb_j']
    face = np.zeros((V, V), np.uint8)
    #! 板石。**幅も高さもばらばら**に切る（帯を横に割ってから、帯ごとに縦へ割る）。
    y = 0
    while y < V:
        dh = int(rng.integers(9, 15))
        x = -int(rng.integers(0, 8))
        while x < V:
            dw = int(rng.integers(10, 18))
            xa, xb = max(x, 0), min(x + dw - 1, V)
            ya, yb = max(y, 0), min(y + dh - 1, V)
            if (xa < xb) and (ya < yb):
                face[xa:xb, ya:yb] = rng.choice([C['tomb'], C['tomb_d'], C['tomb_l']],
                                                p=[0.54, 0.30, 0.16])
                #! 薄れた刻字。板 1 枚につき 2〜3 行、**幅 1 の横線**だけ。
                if rng.random() < 0.45:
                    for row in range(ya + 3, min(yb - 2, ya + 10), 3):
                        face[xa + 2:max(xa + 3, xb - int(rng.integers(2, 7))), row] = C['tomb_j']
            x += dw
        y += dh
    #! 苔。**目地の上にだけ**（板の上に生やすと床が緑の絨毯になる）。
    moss_hit = (face == 0) & (rng.random((V, V)) < 0.42)
    face[moss_hit] = C['moss_d']
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_crypt(name):
    """墓地の通路の床 — **狭い納骨堂の通路**。細長い板石が一方向へ走る。

    部屋（`floor_tomb`）との差は「歩かれている」こと。板は細く、刻字は無く、
    苔は端へ寄る（真ん中は踏まれて禿げている）。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['tomb_j']
    face = np.zeros((V, V), np.uint8)
    along_x = (int(name[-2:]) % 2) == 0
    for k in range(0, V, 7):
        seam = int(rng.integers(8, V - 8))
        a = rng.choice([C['tomb_d'], C['tomb'], C['tomb_l']], p=[0.50, 0.34, 0.16])
        b = rng.choice([C['tomb_d'], C['tomb'], C['tomb_l']], p=[0.50, 0.34, 0.16])
        if along_x:
            face[0:seam - 1, k:k + 6] = a
            face[seam:V, k:k + 6] = b
        else:
            face[k:k + 6, 0:seam - 1] = a
            face[k:k + 6, seam:V] = b
    #! 苔は**端の 6 列だけ**。踏まれる真ん中には出ない。
    edge = np.zeros((V, V), bool)
    edge[:6, :] = edge[V - 6:, :] = edge[:, :6] = edge[:, V - 6:] = True
    hit = edge & (face == 0) & (rng.random((V, V)) < 0.55)
    face[hit] = C['moss_d']
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def wall_tomb(name):
    """墓地の壁 — **苔の目地の切石**。10 枚のうち 2 枚に**壁龕**（骨を納める窪み）。

    城（`wall_cas`）と同じ「人が積んだ壁」だが、**手入れされていない**ことで分かれる:
    目地は暗くて広く、水が伝った筋が縦に走り、石は黄ばんでいる。
    """
    parts = _block_wall(name, course_h=8, block_w=11, stagger=5,
                        shades=[C['tomb'], C['tomb_d'], C['tomb_l'], C['damp']],
                        weights=[0.44, 0.30, 0.14, 0.12],
                        joint_colour=C['tomb_j'],
                        recess_choice=[0, 1, 2], recess_p=[0.58, 0.30, 0.12],
                        cap_shade=[C['tomb_d'], C['tomb_j']])
    _, v, org = parts[0]
    rng = rng_for(name + '_niche')
    #! 水が伝った筋。**縦に 1 ボクセル幅**（横に引くと段の目地と混ざる）。
    for face in range(4):
        for _ in range(3):
            u = int(rng.integers(2, V - 2))
            w1 = int(rng.integers(WALL_H // 2, WALL_H - 2))
            for w in range(2, w1):
                _glyph_dot(v, face, u, w, C['damp'])
    #! 壁龕。**2 枚だけ**（§30.6 で印を 4 枚→2 枚へ落としたのと同じ勘定。
    #! 続けて並ぶと納骨堂ではなく「窓のある壁」になる）。骨を 1 本だけ覗かせる。
    if int(name[-2:]) % 10 in (2, 6):
        for face in range(4):
            _carve_relief(v, face, 11, 21, 9, 21, 5)
            _paint_face(v, face, 11, 21, 9, 21, 5, C['tomb_j'])
            _paint_face(v, face, 12, 20, 10, 12, 4, C['bone_d'])
    return [('main', v, org)]


def bedrock_tomb(name):
    """墓地の地山 — 壁と同じ石の一族で、**積んでいない**塊。苔は下端だけ。"""
    _, v, org = bedrock(name)[0]
    v = _recolour(v, {'rock_dd': 'tomb_j', 'rock_d': 'tomb_d', 'band': 'damp',
                      'rock': 'tomb', 'rock_l': 'tomb_l'})
    rng = rng_for(name + '_moss')
    for face in range(4):
        for _ in range(5):
            u0 = int(rng.integers(0, V - 6))
            _paint_face(v, face, u0, u0 + int(rng.integers(4, 9)), 1, int(rng.integers(3, 7)),
                        0, C['moss_d'])
    return [('main', v, org)]


# ---- 8 火山（50–60・溶岩の床・壁の 90% が花崗岩。炎免疫と飛行のみ）----
#
# **スコリア**（気泡だらけの噴出岩）。黒曜石（`obs`・永久壁）は磨いた面だが、こちらは
# 粗い面である。**赤い割れ目**は彫った溝の底にだけ置く——面に赤を塗ると溶岩の壁になり、
# 地獄（9・壁まで溶岩）と見分けが付かなくなる。

_SCORIA_MAP = {'rock_dd': 'sco_d', 'rock_d': 'sco', 'band': 'sco_d',
               'rock': 'sco', 'rock_l': 'sco_l'}


def wall_scoria(name):
    """火山の壁 — 気泡だらけの黒い岩。割れ目の底にだけ火の色が残る。"""
    _, v, org = wall_rock(name)[0]
    v = _recolour(v, _SCORIA_MAP)
    rng = rng_for(name + '_vesicle')
    #! 気泡。**2×2 の穴を彫って底を暗く**（1 ボクセルだと寄っても見えない）。
    for face in range(4):
        for _ in range(22):
            u = int(rng.integers(0, V - 2))
            w = int(rng.integers(2, WALL_H - 3))
            _carve_relief(v, face, u, u + 2, w, w + 2, 2)
            _paint_face(v, face, u, u + 2, w, w + 2, 2, C['dark'])
    #! 赤い割れ目。**10 枚のうち 4 枚**、1 面に 1 本だけ。**自発光は乗せない**
    #! （乗せるのは地形の溶岩の側で、壁が光ると溶岩の川との差が消える）。
    if int(name[-2:]) % 10 in (1, 4, 6, 9):
        for face in range(4):
            u = int(rng.integers(6, V - 6))
            w = int(rng.integers(3, 10))
            while w < WALL_H - 3:
                u = max(1, min(V - 2, u + int(rng.integers(-1, 2))))
                _glyph_dot(v, face, u, w, C['mag_h'])
                w += 1
    return [('main', v, org)]


def bedrock_scoria(name):
    """火山の地山 — 同じ気泡の岩。**割れ目は持たない**（掘っていない塊の中身）。"""
    _, v, org = bedrock_raw(name)[0]
    v = _recolour(v, _SCORIA_MAP)
    rng = rng_for(name + '_vesicle')
    for face in range(4):
        for _ in range(14):
            u = int(rng.integers(0, V - 2))
            w = int(rng.integers(2, WALL_H - 3))
            _carve_relief(v, face, u, u + 2, w, w + 2, 1)
            _paint_face(v, face, u, u + 2, w, w + 2, 1, C['dark'])
    return [('main', v, org)]


# ---- 9 地獄（666–696・壁まで溶岩・要勝利）----
#
# **岩盤だけ**。壁は深い溶岩 80／暗い穴 20 で、床も溶岩なので、既定へ落ちるのは
# 岩盤（＝まだ掘っていない厚い壁の中身）しか無い。ただし通路率 0・最大の広さなので、
# **画面のかなりを岩盤が占める**——1 役割 10 個で効きの大きい所である。


def bedrock_ember(name):
    """地獄の地山 — **熱を持ったままの岩**。割れ目の底から下の火が透ける。

    火山（`bedrock_scoria`・冷えた噴出岩）と対にしてある。あちらは黒い気泡、
    こちらは**赤黒く、割れている**。自発光は乗せない（岩は光らない。光るのは溶岩）。
    """
    _, v, org = bedrock_raw(name)[0]
    v = _recolour(v, {'rock_dd': 'emb_d', 'rock_d': 'emb', 'band': 'emb_d',
                      'rock': 'emb', 'rock_l': 'emb_l'})
    rng = rng_for(name + '_crack')
    #! 割れ目。**枝分かれさせる**（1 本の縦線だと彫った溝に見える）。
    for face in range(4):
        for _ in range(2):
            u = int(rng.integers(5, V - 5))
            w = 2
            while w < WALL_H - 2:
                u = max(1, min(V - 2, u + int(rng.integers(-1, 2))))
                _glyph_dot(v, face, u, w, C['mag_h'])
                if rng.random() < 0.18:  # 枝
                    bu = u
                    for bw in range(w, min(w + 6, WALL_H - 2)):
                        bu = max(1, min(V - 2, bu + int(rng.choice([-1, 1]))))
                        _glyph_dot(v, face, bu, bw, C['mag'])
                w += 1
    return [('main', v, org)]


# ---- 10 天界（555–585・永久壁 100・床 100 が既定・善のみ・要勝利）----
#
# **床だけ**。壁は永久壁（`wall_perm` ＝ 磨かれた黒曜石）なので触らない
# ——というより、**黒い壁と白い床の対比がそのまま天界の絵**になっている。
# 白は大理石（城）と分けたい。城が石なら、ここは**真珠層**（`nacr_*`。青く冷たい白）である。


def floor_halo(name):
    """天界の部屋の床 — 真珠層の大判。**10 枚のうち 3 枚だけ金の象嵌**。

    象嵌を全部のマスに入れると、床が一面の格子模様になる（罠 114。マスの単位で規則的に
    置いたものは必ず模様になる）。3 枚に留め、しかも**マスの中央から外す**。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['nacr_d']
    face = np.zeros((V, V), np.uint8)
    _paved_face(rng, face, step=16, stagger=8,
                shades=[C['nacr'], C['nacr_l'], C['nacr_d']], weights=[0.56, 0.30, 0.14])
    #! 真珠の虹。**大理石の脈と同じ「続いた線」**だが、色を 2 つ交互に置いて薄い虹にする。
    _marble_vein(rng, face, C['nacr_l'], count=2, length=(14, 30))
    _marble_vein(rng, face, C['sky'], count=1, length=(8, 18))
    #! **10 枚のうち 1 枚だけ。**初版は 3 枚（30%）で、実機の絵では 1 部屋に輪が 6 つ並んで
    #! **床が金の水玉模様**になった。§30.6 で封じの印を 40%→20% へ落としたのと同じ話で、
    #! ここは床（マスが全部見える）なので、壁よりさらに薄くしないと模様になる。
    if int(name[-2:]) % 10 == 5:
        cx = int(rng.integers(9, 23))
        cy = int(rng.integers(9, 23))
        for i in range(48):  # 金の輪（象嵌。1 ボクセル幅）
            a = 2.0 * math.pi * i / 48.0
            x = int(round(cx + 7.0 * math.cos(a)))
            y = int(round(cy + 7.0 * math.sin(a)))
            if (0 <= x < V) and (0 <= y < V):
                face[x, y] = C['gold_d']
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_nacre(name):
    """天界の通路の床 — **回廊**。通路率 1000 なので、ここがいちばん長く目に入る。

    部屋（`floor_halo`）との差は板の形。**32×6 の細長い板が一方向**に走り、
    継ぎ目に細い金の筋が 1 本通る——歩く先が読めることが回廊の役目である。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['nacr_d']
    face = np.zeros((V, V), np.uint8)
    along_x = (int(name[-2:]) % 2) == 0
    for k in range(0, V, 6):
        shade = rng.choice([C['nacr'], C['nacr_l'], C['nacr_d']], p=[0.56, 0.28, 0.16])
        if along_x:
            face[0:V, k:k + 5] = shade
        else:
            face[k:k + 5, 0:V] = shade
    mid = 12 + int(rng.integers(0, 3)) * 6
    if along_x:
        face[0:V, mid:mid + 1] = C['gold_d']
    else:
        face[mid:mid + 1, 0:V] = C['gold_d']
    _marble_vein(rng, face, C['nacr_l'], count=1, length=(12, 26))
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


# ---- 11 水没した遺跡（55–75・壁の 80% が深い水・床の 80% が既定）----
#
# **床だけ**。「水の中」は水そのものではなく**底に溜まったもの**で言う（小物で海藻を
# 揺らしたのと同じ手＝§27.12「水は揺れるもので言う」）。泥に半分埋まった敷石が、
# 水に沈んで長い時間が経ったことを言う。


def floor_silt(name):
    """水没した遺跡の部屋の床 — **泥に半分埋まった敷石**。

    敷石を先に敷いてから、泥で**上から潰す**。潰し残った石だけが顔を出すので、
    「元は舗装されていた」と「いまは埋まっている」が 1 枚で言える。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['silt_d']
    face = np.zeros((V, V), np.uint8)
    _paved_face(rng, face, step=11, stagger=5,
                shades=[C['flag'], C['flag_d'], C['verd']], weights=[0.48, 0.36, 0.16])
    #! 泥。**大きな塊で被せる**（点で撒くと砂粒＝罠 38）。6 割ほどを埋める。
    for _ in range(14):
        cx, cy = int(rng.integers(-4, V)), int(rng.integers(-4, V))
        w, d = int(rng.integers(6, 15)), int(rng.integers(6, 15))
        face[max(cx, 0):cx + w, max(cy, 0):cy + d] = rng.choice(
            [C['silt'], C['silt_d'], C['silt_l']], p=[0.50, 0.32, 0.18])
    #! 泥の上の藻。**塊の縁へ**（真ん中に置くと苔の絨毯になる）。
    for _ in range(6):
        x, y = int(rng.integers(0, V - 3)), int(rng.integers(0, V - 3))
        if face[x, y] in (C['silt'], C['silt_d'], C['silt_l']):
            face[x:x + 3, y:y + 2] = C['moss_d']
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_shell(name):
    """水没した遺跡の通路の床 — **貝殻の混じった砂**。舗装がもう残っていない。

    部屋との差は「石が 1 枚も無い」こと。通路は歩かれないまま埋まりきっている。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['silt_d']
    face = np.zeros((V, V), np.uint8)
    _lump_face(rng, face, [C['silt'], C['silt_d'], C['silt_l'], C['dirt_d'], C['moss_d']],
               [0.32, 0.26, 0.18, 0.14, 0.10])
    #! 貝殻。**扇形に 1 枚ずつ**（散らすと骨の粉に見える）。3〜4 枚だけ。
    #! 初版は半径 3〜4 で、泥のむらに紛れて 1 枚も読めなかった。**大きく（5〜7）して、
    #! 放射の筋を彫る**——扇に筋が入って初めて貝に見える（罠 103 の「数を減らして大きく」）。
    for _ in range(int(rng.integers(3, 5))):
        cx, cy = int(rng.integers(6, V - 7)), int(rng.integers(6, V - 7))
        r = int(rng.integers(5, 8))
        shade = C['bone'] if rng.random() < 0.6 else C['bone_d']
        for x in range(cx - r, cx + r + 1):
            for y in range(cy - r, cy + r + 1):
                if (0 <= x < V) and (0 <= y < V) and (math.hypot(x - cx, y - cy) <= r) and (y >= cy):
                    face[x, y] = shade
        for i in range(5):  # 放射の筋（**扇の要から**）
            a = math.pi * (0.12 + 0.19 * i)
            for t in range(1, r):
                px, py = int(cx + math.cos(a) * t), int(cy + math.sin(a) * t)
                if (0 <= px < V) and (0 <= py < V):
                    face[px, py] = C['silt_d']
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


# ---- 13 ルルイエ（80–96・壁の 100% が花崗岩・床 50 が既定。主は偉大なるクトゥルフ）----
#
# **「傾いている」が唯一にして最大の読み**（小物でそう決めた＝§27.12）。材のほうでも
# 同じことを言う。ただし**プレハブそのものを傾けてはいけない**——マスは直方体であることが
# 通れる／通れないの判別なので（2026-08-09 に決めた）、傾けるのは**目地の側**である。
# 継ぎ目が水平でも垂直でもない巨石積みは、箱を保ったまま「角度が合わない」を言える。


def floor_cyclo(name):
    """ルルイエの部屋の床 — **巨石を 1〜2 枚**。継ぎ目が斜めに走る。

    ほかの床が「何枚も敷いてある」のに対して、ここはマスが石より小さい。
    **マスの境と石の境が合わない**ことが、人の寸法で造られていないことの読みになる。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['cyc_j']
    face = np.full((V, V), C['cyc'], np.uint8)
    #! 斜めの継ぎ目を 1〜2 本。**必ずマスを横切らせる**——初版は通る位置を
    #! `-10〜V+10` から引いていたので、**変種の半分で線がマスの外に落ちて無地の板**になった
    #! （`_03` は 1 本も入っていなかった）。マスの真ん中を通る点を先に決めて、そこから引く。
    for k in range(int(rng.integers(1, 3))):
        through = float(rng.integers(6, V - 6))   # y=16 で通る x
        slope = float(rng.uniform(-1.2, 1.2)) + (0.0 if k == 0 else 0.6)
        side = rng.choice([C['cyc_d'], C['cyc_l']], p=[0.6, 0.4])
        for y in range(V):
            cut = int(round(through + slope * (y - V / 2.0)))
            if cut < V:
                face[max(cut, 0):V, y] = side
            if 0 <= cut < V:
                face[cut, y] = C['cyc_j']
            if 0 <= cut + 1 < V:
                face[cut + 1, y] = C['cyc_j']
    #! 石の目。**塊で・はっきりと**（面が広いので、弱いと塗り潰しに見える）。
    _grain(rng, face, face > 0, [C['cyc_l'], C['cyc_d'], C['cyc_j']], [0.16, 0.18, 0.06], block=4)
    #! 欠けと窪み。**大きく 2〜3 か所**（巨石は細かく傷まない。大きく欠ける）。
    for _ in range(int(rng.integers(2, 4))):
        x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        w, d = int(rng.integers(4, 9)), int(rng.integers(4, 9))
        face[x:x + w, y:y + d] = C['cyc_d']
        face[x + 1:x + w - 1, y + 1:y + d - 1] = C['cyc_j']
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def floor_basalt(name):
    """ルルイエの通路の床 — **柱状節理を輪切りにした面**（六角がびっしり）。

    部屋（巨石 1〜2 枚）と正反対に、こちらは小さな多角形が敷き詰まる。
    通路率 100 のダンジョンなので、**同じ床を部屋と通路で分けない手は取らない**
    ——迷宮（`floor_lab`）は「どこも同じ」が読みだったが、ここは逆に「石の寸法が狂う」
    ことを言いたいので、部屋と通路で寸法を大きく違える。
    """
    rng = rng_for(name)
    v = _tile(FLOOR_H)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['cyc_j']
    face = np.zeros((V, V), np.uint8)
    #! 種点から最寄りを引く（`floor_scute` の亀甲と同じ作り。あちらは鱗、こちらは節理）。
    pts = [(float(rng.uniform(-3, V + 3)), float(rng.uniform(-3, V + 3))) for _ in range(11)]
    tone = [rng.choice([C['cyc'], C['cyc_d'], C['cyc_l']], p=[0.52, 0.32, 0.16]) for _ in pts]
    for x in range(V):
        for y in range(V):
            best = best2 = 1e9
            bi = 0
            for i, (px, py) in enumerate(pts):
                d = (x - px) ** 2 + (y - py) ** 2
                if d < best:
                    best2, best, bi = best, d, i
                elif d < best2:
                    best2 = d
            #! 境目だけ 1 段彫る（多角形の縁が溝になって節理に読める）。
            face[x, y] = C['cyc_j'] if (math.sqrt(best2) - math.sqrt(best)) < 1.1 else tone[bi]
    v[:, :, top] = face
    return [('main', v, (0, 0, -FLOOR_H))]


def wall_cyclo(name):
    """ルルイエの壁 — **巨石積み。目地が傾いている**。

    `_block_wall` は水平の段しか積めないので、ここは自前で組む。段の境を
    **マスごとに違う角度**で引き、石の中を無地に保つ（無地の面が巨石の大きさを言う）。
    箱そのものは崩さない（マスは直方体＝通れない所の判別）。
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.full((V, V, h), C['cyc'], np.uint8)
    _skin_lumps(v, rng, [C['cyc'], C['cyc_d'], C['cyc_l']], [0.50, 0.30, 0.20],
                p_cover=0.24, keep_top=False)
    for face in range(4):
        #! 段の境を 2 本。**傾ける**のがこの壁の全部である。
        for k in range(2):
            w0 = 8 + k * 11 + int(rng.integers(-2, 3))
            slope = float(rng.uniform(-0.28, 0.28))
            for u in range(V):
                w = int(round(w0 + slope * (u - V / 2.0)))
                for dw in (0, 1):
                    _carve_relief(v, face, u, u + 1, w + dw, w + dw + 1, 1)
                    _paint_face(v, face, u, u + 1, w + dw, w + dw + 1, 1, C['cyc_j'])
        #! 縦の継ぎ目は**段ごとに 1 本だけ**（多いと切石になる。巨石は継ぎ目が少ない）。
        for w0, w1 in ((1, 9), (10, 20), (21, h - 1)):
            u = int(rng.integers(4, V - 4))
            for w in range(w0, w1):
                _carve_relief(v, face, u, u + 1, w, w + 1, 1)
                _paint_face(v, face, u, u + 1, w, w + 1, 1, C['cyc_j'])
    v[:, :, h - 1] = C['cyc_d']
    return [('main', v, (0, 0, 0))]


def bedrock_cyclo(name):
    """ルルイエの地山 — **柱状節理**。縦の柱が束になって切り立つ。

    壁（積んだ巨石）と地山（自然の岩）を作り分ける。通路の床（`floor_basalt`）が
    その輪切りなので、**床と地山が同じ岩であることが分かる**のが狙いである。
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.full((V, V, h), C['cyc_d'], np.uint8)
    #! 縦の柱。**幅 3〜5 の帯で色を変え、境を 1 段彫る**（帯だけだと縞の壁になる）。
    for face in range(4):
        u = 0
        while u < V:
            w = int(rng.integers(3, 6))
            shade = rng.choice([C['cyc'], C['cyc_d'], C['cyc_l']], p=[0.46, 0.34, 0.20])
            _paint_face(v, face, u, u + w, 1, h - 1, 0, shade)
            _carve_relief(v, face, u + w - 1, u + w, 1, h - 1, 1)
            _paint_face(v, face, u + w - 1, u + w, 1, h - 1, 1, C['cyc_j'])
            u += w
    #! 柱の折れ口（節理は途中で折れる）。**面の 1/3 ほどの高さで 1 段だけ**。
    for face in range(4):
        w = int(rng.integers(9, h - 9))
        _carve_relief(v, face, 0, V, w, w + 1, 1)
        _paint_face(v, face, 0, V, w, w + 1, 1, C['cyc_j'])
    v[:, :, h - 1] = C['cyc_j']
    return [('main', v, (0, 0, 0))]


# ========================= 第 6 期: 案に書いてあって作っていなかった小物 ================
#
# ・§4 の表と `dungeon_style.cpp` を突き合わせると、
# **案に名前があるのに 1 個も作っていないもの**が残っていた。第 4 期は 20 本すべてを
# 「表に載せる」ことを優先したので、枠が埋まった時点で止まっていた形である。
#
# あわせて、**別のダンジョンの小物を借りていた 3 か所**を自前の材へ置き換える。
# 借り物は「表に載っている」ので検査は通るが、絵の意味が混ざる（罠 86 の親戚）:
#
#   - 火山（8）の部屋の縁が**暗闇の洞窟の黒い結晶**だった → `pillar_obsidian`
#   - ガラスの城（20）の壁際が**城の鉄の燭台**だった → `glass_sconce`
#   - 森（7）の部屋の中が**人骨**だった → `bones_deer`
#
# **火は「明るい部屋」の枠**（`fire_body` ＋ `fire_flame`）で、ここだけが自発光を
# 受け取れる（`terrain_view.cpp` は ④ の枠へ 0 を渡す＝罠 106）。地獄の溶けた鉄が
# 光るのはこの枠に載せたからで、④ に置くと「光らない毒々しい塊」になる（§27.14）。


# ---- 3 オークの洞窟: 縄張りの印と、焚き火 ----


def war_stake(name):
    """粗い杭と旗（オーク）— **縄張りの印**。部屋の縁に、切石の柱の代わりに立てる。

    イークの洞穴が「掘り残しの岩」（自然物）なのに対して、こちらは**置いた物**である。
    オークは巣を主張する側なので、そこで 2 本が分かれる。旗は風で揺らさない
    （地下は無風＝`hd2d_app.cpp` の「洞窟の草が揺れると嘘くさい」）。
    """
    v = np.zeros((V, V, 40), np.uint8)
    #! 杭。**割った丸太**なので断面が四角く、先が尖っている。
    v[13:19, 14:20, 0:32] = C['log']
    v[13:19, 14:16, 0:32] = C['log_d']
    v[14:18, 15:19, 32:36] = C['log_l']
    v[15:17, 16:18, 36:38] = C['log_end']
    #! 横木（旗を吊る腕）。**旗は横木から下がる**——竿に直に貼ると板に見える。
    v[6:26, 16:18, 28:30] = C['log_d']
    v[6:8, 15:19, 27:31] = C['log_end']
    v[24:26, 15:19, 27:31] = C['log_end']
    #! ぼろ布の旗。**大きく 1 枚**（初版は幅 2 の帯で、遠目に杭の影と見分けが付かなかった。
    #! 罠 105 の「数を減らして 1 つを大きく」と同じ話）。裾はぎざぎざに破れている。
    for k in range(16):
        wid = 18 - (k // 5)
        x0 = 7 + (18 - wid) // 2
        if k >= 12 and ((k + x0) % 2) == 0:  # 破れた裾
            wid -= 4
        v[x0:x0 + wid, 16:18, 27 - k:28 - k] = C['rag'] if (k % 4) else C['rust']
    #! 括り付けた頭蓋（獲物の印）。**竿の前へ出す**（竿と同じ太さだと節に見える）。
    v[11:21, 10:17, 18:26] = C['bone_d']
    v[12:20, 9:11, 19:25] = C['bone']
    v[13:16, 8:11, 21:24] = C['dark']  # 眼窩
    v[17:20, 8:11, 21:24] = C['dark']
    v[14:18, 8:10, 18:20] = C['bone']  # 鼻づら
    v[11:21, 15:18, 17:19] = C['lash']  # 縄
    return [('main', v, (0, 0, 0))]


def cook_fire(name):
    """焚き火と鉄鍋（オーク）— **松明の代わりに火の本体として置く**。

    イークの `ash_pit`（消し炭＝**火は消えている**）と対にしてある。オークは火を焚く。
    炎は別体（`cook_flame`）で、**既定の `torch_flame` は使えない**——あちらは
    松明の受け皿に合わせて z=30 から作ってあるので、地面の焚き火に載せると
    炎が 1 マス上に浮く（`sconce` と `miner_lamp` で 2 度踏んだ穴＝罠 86）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 34), np.uint8)
    cx = cy = V // 2
    #! 炉。囲いの石と炭の床は `ash_pit` と同じ作り（同じ洞窟の系統なので揃える）。
    for x in range(V):
        for y in range(V):
            if math.hypot(x - cx + 0.5, y - cy + 0.5) <= 6.0:
                v[x, y, 0:2] = C['char'] if rng.random() < 0.7 else C['char_l']
    for k in range(10):
        ang = (k / 10.0 * 2.0 * math.pi) + float(rng.uniform(-0.2, 0.2))
        x = int(cx + math.cos(ang) * 7.6)
        y = int(cy + math.sin(ang) * 7.6)
        w = int(rng.integers(2, 4))
        v[max(0, x - w // 2):x + w // 2 + 1, max(0, y - w // 2):y + w // 2 + 1,
          0:int(rng.integers(3, 5))] = rng.choice([C['rock_d'], C['rock'], C['rock_dd']],
                                                  p=[0.4, 0.3, 0.3])
    #! 薪（**炎の下**に組む。炎は z=2〜14 に来る）。
    for k in range(4):
        ang = k / 4.0 * math.pi
        dx, dy = int(math.cos(ang) * 5), int(math.sin(ang) * 5)
        v[cx - dx:cx + dx + 2, cy - dy:cy + dy + 2, 2:4] = C['timber_d']
    #! 三脚。**炎を避けて外側へ**（真上から吊ると炎に脚が刺さる）。
    for k in range(3):
        ang = k / 3.0 * 2.0 * math.pi
        x = int(cx + math.cos(ang) * 9)
        y = int(cy + math.sin(ang) * 9)
        for z in range(0, 26):
            t = z / 26.0
            px = int(x + (cx - x) * t)
            py = int(y + (cy - y) * t)
            v[px:px + 2, py:py + 2, z:z + 1] = C['timber']
    #! 鉄鍋。**炎の上**（z=16〜25）に吊る。
    #! 初版は鍋も三脚も `iron`（56,54,58）で組んだので、**炭の上の黒い塊**にしかならなかった。
    #! 鍋は `iron_l` を基調にして三脚（木）と明度で割る——鉄鍋が主役である。
    for z in range(16, 26):
        r = 6.8 - abs(z - 20.5) * 0.30
        for x in range(V):
            for y in range(V):
                d = math.hypot(x - cx + 0.5, y - cy + 0.5)
                if d <= r:
                    #! 手前（-y）を明るく、奥を暗く。**面で分ける**と球ではなく器に読める。
                    v[x, y, z] = C['iron_l'] if (y < cy) else C['iron']
    for x in range(V):  # 口の縁（**明るく 2 段**。無いと黒い球に見える）
        for y in range(V):
            d = math.hypot(x - cx + 0.5, y - cy + 0.5)
            if 5.0 <= d <= 6.8:
                v[x, y, 25:27] = C['steel_d']
    v[cx - 1:cx + 1, cy - 1:cy + 1, 27:29] = C['iron']  # 吊り手
    v[cx - 6:cx + 6, cy - 1:cy + 1, 28:29] = C['iron']
    return [('main', v, (0, 0, 0))]


def cook_flame(name):
    """焚き火の炎（オーク）— **地面の高さで燃える**。`torch_flame` の低い版。

    松明の炎（z=30）と作りは同じ 2 枚の振り子だが、**太く低い**。
    自発光は置く側が枠で乗せる（1.35 / 0.85 / 0.30）ので、素の色は明るくしない。
    """
    fa = np.zeros((10, 10, 12), np.uint8)  # 外側（広い）
    fa[1:9, 1:9, 0:6] = C['fl_edge']
    fa[2:8, 2:8, 2:9] = C['fl_mid']
    fa[3:7, 3:7, 8:11] = C['fl_mid']
    fb = np.zeros((6, 6, 12), np.uint8)  # 芯（高い）
    fb[1:5, 1:5, 0:8] = C['fl_core']
    fb[2:4, 2:4, 8:11] = C['fl_mid']
    return [('flame_a', fa, (11, 11, 2)), ('flame_b', fb, (13, 13, 3))]


def cook_flame_parts():
    """支点は**炎の根元**（z=2）。松明（z=30）と同じ揺れ幅では地面の火に見えない
    ので、振れを小さく・周期を長くしてある（大きな火はゆっくり揺れる）。"""
    return [
        {'name': 'flame_a', 'voxels': 'flame_a', 'grounded': False,
         'pivot': [16.0, 16.0, 2.0],
         'motion': {'kind': 'pendulum', 'axis': 'x', 'amplitude': 4.0,
                    'period': 1.30, 'phase': 0.0, 'damping': 0.0},
         'wind_k': 0.0},
        {'name': 'flame_b', 'voxels': 'flame_b', 'grounded': False,
         'pivot': [16.0, 16.0, 3.0],
         'motion': {'kind': 'pendulum', 'axis': 'y', 'amplitude': 6.0,
                    'period': 0.88, 'phase': 1.7, 'damping': 0.0},
         'wind_k': 0.0},
    ]


# ---- 12 城: 長机の相手 ----


def chair(name):
    """椅子（城）— 長机（`table_long`）と対。**背もたれを高く**するのが椅子の読み。

    机がマスをまたぐ大きさなので、椅子は小さくてよい。**1 脚だけ・斜めに引いてある**
    （揃えて 2 脚並べると食堂の絵になり、装飾ではなく主役に見える）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    x0 = int(rng.integers(10, 15))
    y0 = int(rng.integers(11, 16))
    v[x0:x0 + 10, y0:y0 + 10, 12:14] = C['oak']  # 座面
    v[x0:x0 + 10, y0:y0 + 10, 14] = C['oak_l']
    for dx, dy in ((0, 0), (8, 0), (0, 8), (8, 8)):  # 脚
        v[x0 + dx:x0 + dx + 2, y0 + dy:y0 + dy + 2, 0:12] = C['timber_d']
    v[x0:x0 + 10, y0 + 8:y0 + 10, 14:28] = C['oak']  # 背もたれ
    v[x0 + 1:x0 + 9, y0 + 8:y0 + 10, 18:24] = 0  # 抜き（**板 1 枚だと扉に見える**）
    v[x0:x0 + 10, y0 + 8:y0 + 10, 27:29] = C['oak_l']
    if rng.random() < 0.4:  # 座面の布
        v[x0 + 1:x0 + 9, y0 + 1:y0 + 9, 14:15] = C['crimson']
    return [('main', v, (0, 0, 0))]


# ---- 16 反魔法: 部屋の縁（案の「逆さに埋めた剣の輪」）----


def sword_inverted(name):
    """逆さに埋めた剣の輪（反魔法）— **柄を下に、刃を上に**して地に刺す。

    武器として置いてあるのではなく**封じの杭**として使われている、が読みである。
    輪（`ward_ring`）が水平の結界なら、こちらは垂直に立つ結界で、部屋の縁に並ぶ。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.uint8)
    v[9:23, 9:23, 0:3] = C['cob_d']  # 埋めた台
    v[10:22, 10:22, 3:4] = C['cob']
    #! **2 本だけ**。初版は幅 2 の刀身を 3 本立てたので、細い棒の束にしか見えなかった
    #! （罠 103 の「数を減らして 1 つを大きく」）。刃は幅 4・厚み 2 の板にする。
    for k, (x, y) in enumerate(((11, 14), (19, 17))):
        top = 30 + k * 3
        v[x:x + 4, y:y + 2, 4:top] = C['steel_d']  # 刀身（平たい板）
        v[x + 1:x + 3, y:y + 2, 4:top] = C['steel']  # 鎬（**面の真ん中を明るく**）
        v[x + 1:x + 3, y:y + 2, top:top + 3] = C['steel']  # 切先
        #! 鍔。**下のほう＝逆さの証**。刀身の 2 倍以上に張り出させないと読めない。
        v[x - 3:x + 7, y - 2:y + 4, 8:11] = C['iron']
        v[x - 3:x + 7, y - 2:y + 4, 10:11] = C['iron_l']
        v[x + 1:x + 3, y:y + 2, 4:8] = C['timber_d']  # 柄が地に埋まっている
    #! 刻んだ輪。**光らせない**（反魔法の読みが反転する＝案の指示）。台の上に彫る。
    for i in range(40):
        a = 2.0 * math.pi * i / 40.0
        px = int(round(16 + 9.5 * math.cos(a)))
        py = int(round(16 + 9.5 * math.sin(a)))
        if (0 <= px < V) and (0 <= py < V):
            v[px, py, 2:4] = C['ward_j']
    #! 割れた刃のかけら（2 本だけだと「置いた物」に見える）。
    for _ in range(3):
        x, y = int(rng.integers(3, V - 5)), int(rng.integers(3, V - 5))
        if math.hypot(x - 16, y - 16) > 10:
            v[x:x + 4, y:y + 2, 0:2] = C['steel_d']
    return [('main', v, (0, 0, 0))]


# ---- 19 暗闇の洞窟: 部屋の縁（案の「柱に刺さったまま消えた松明」）----


def pillar_snuffed(name):
    """柱に刺さったまま消えた松明（暗闇の洞窟）— **消えていることが主題**。

    立ち松明はこのダンジョンでは 1 本も立たない（`DARKNESS` がコアの側で部屋の
    `GLOW` を潰すので、「明るい部屋」の条件が成立しない＝§27.12）。**燃えていない
    松明を柱として置く**ことで、「昔は灯っていた」を絵にする。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 44), np.uint8)
    #! 柱身。**暗闇の材（`murk`）で**——同じ洞窟の壁と石を揃える。
    v[12:20, 12:20, 0:3] = C['murk_d']
    v[13:19, 13:19, 3:36] = C['murk']
    v[13:19, 13:19, 36:38] = C['murk_l']
    for z in range(6, 34, 7):  # 段の線（無地の角柱は「箱」に見える）
        v[13:19, 12:13, z:z + 1] = C['murk_dd']
        v[13:19, 19:20, z:z + 1] = C['murk_dd']
        v[12:13, 13:19, z:z + 1] = C['murk_dd']
        v[19:20, 13:19, z:z + 1] = C['murk_dd']
    #! 受け金と、突き刺さったままの燃え殻。
    #! **前後の 2 面へ付ける**（罠 105。プレハブの向きは置く側が決めるので、片面に賭けると
    #! 向きしだいで 1 本も見えない。初版は -y 面だけに付けて、実際に見えなかった）。
    #! 腕は柱から 5 マス出す——柱に貼り付けると「柱の節」に読める。
    for y0, sign in ((11, -1), (20, 1)):
        v[13:19, min(y0, y0 + sign * 4):max(y0, y0 + sign * 4) + 1, 24:27] = C['iron']
        ay = y0 + sign * 5
        v[14:18, min(ay, ay + sign * 2):max(ay, ay + sign * 2) + 1, 24:29] = C['iron_l']
        #! 燃え殻。**炭を斜め上へ長く出す**（受けの中に納めると金具にしか見えない）。
        tz = 28
        ty = ay + sign
        for k in range(6):
            v[15:17, min(ty, ty + sign):max(ty, ty + sign) + 1, tz:tz + 2] = \
                C['timber_d'] if k < 3 else C['char']
            ty += sign
            tz += 1
        v[14:18, min(ty, ty + sign * 2):max(ty, ty + sign * 2) + 1, tz:tz + 3] = C['char']
        v[15:17, min(ty, ty + sign * 2):max(ty, ty + sign * 2) + 1, tz + 2:tz + 4] = C['char_l']
    if rng.random() < 0.5:  # 落ちた燃え殻
        v[int(rng.integers(4, 10)):int(rng.integers(11, 14)), 6:8, 0:2] = C['char']
    return [('main', v, (0, 0, 0))]


# ---- 8 火山: 部屋の縁（暗闇の黒い結晶を借りていた所を、自前の柱へ）----


def pillar_obsidian(name):
    """黒曜石の柱（火山）— **溶岩が固まって立った柱**。人が立てたのではない。

    暗闇の洞窟の `crystal_black`（結晶＝尖った塊が 3 つ）を借りていたのをやめる。
    あちらは「光を吸う」ための小さな結晶で、こちらは**部屋の縁に立つ高さ**が要る。
    黒曜石なので**割れ口が貝殻状に光る**——そこだけ明るくすると硝子質に読める。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 46), np.uint8)
    #! 六角の柱（柱状節理）。**上へ細らせない**（細らせると石筍と同じ形になる）。
    for z in range(42):
        r = 6.6 - z * 0.03
        for x in range(V):
            for y in range(V):
                dx, dy = x - 16 + 0.5, y - 16 + 0.5
                #! 六角は「3 方向の帯の重なり」で作る（真円は溶けた飴に見える）。
                if (abs(dy) <= r) and (abs(dy * 0.5 + dx * 0.866) <= r) \
                        and (abs(dy * 0.5 - dx * 0.866) <= r):
                    v[x, y, z] = C['obs'] if (z % 11) else C['obs_l']
    #! 割れ口。**面を彫ってから明るい色**（塊の上の線は消える＝罠 104）。
    for _ in range(5):
        z0 = int(rng.integers(6, 34))
        x0 = int(rng.integers(10, 20))
        v[x0:x0 + int(rng.integers(3, 6)), 9:11, z0:z0 + int(rng.integers(4, 9))] = C['obs_h']
    #! 折れた頭（柱は途中で折れる）。**斜めに削ぐ**。
    for k in range(4):
        v[:, :, 42 + k] = 0
        v[10 + k * 2:22, 10:22, 41 - k] = C['obs_h']
    #! 根元に散った破片（柱だけだと「置いた棒」に見える）。
    for _ in range(5):
        x, y = int(rng.integers(3, V - 5)), int(rng.integers(3, V - 5))
        if math.hypot(x - 16, y - 16) > 8:
            v[x:x + 3, y:y + 3, 0:2] = C['obs_l']
    return [('main', v, (0, 0, 0))]


# ---- 9 地獄: 火の枠（案の「溶けた鉄の池」）----
#
# **④ 部屋の中の枠には置けない。**あちらは自発光を 0 で渡すので、溶けた鉄を入れると
# 「光らない橙色の塊」になる（光茸で 1 度踏んだ穴＝§27.14・罠 106）。
# 火の枠（`fire_body` ＋ `fire_flame`）に載せると自発光が乗る。**「明るい部屋」の縛りは
# 外す**（`fire_needs_lit = false`）——溶けた鉄は部屋の明るさと関係なく在るものである。


def iron_pool(name):
    """溶けた鉄の池（地獄）— **枠の側**。冷えて固まった縁と、鋳型の石。

    光る面は別体（`iron_pool_glow`）。自発光はインスタンス単位でしか渡せないので、
    1 つにすると縁の石まで光る（松明を 2 体に割ったのと同じ理由）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    #! 縁。**内側へ向かって下がる皿**にする（平らだと「橙色の敷物」に見える）。
    for x in range(V):
        for y in range(V):
            d = math.hypot(x - 16 + 0.5, y - 16 + 0.5)
            if d <= 13.5:
                top = 1 if d < 9.0 else int(2 + (d - 9.0) * 0.9)
                v[x, y, 0:max(1, top)] = C['emb_d'] if d < 11.0 else C['emb']
    #! 冷えて固まった皮が浮いている（`lava_crust` と同じ読み。全面が液だと湖になる）。
    for _ in range(int(rng.integers(3, 6))):
        cx, cy = int(rng.integers(9, 23)), int(rng.integers(9, 23))
        if math.hypot(cx - 16, cy - 16) > 8.0:
            continue
        w = int(rng.integers(3, 6))
        v[cx:cx + w, cy:cy + w, 1:3] = C['crust']
    #! 縁に立てかけた鋳型の石（人の手が入っていることを 1 つだけ言う）。
    v[4:8, 13:19, 0:6] = C['iron']
    v[5:7, 14:18, 5:7] = C['rust']
    return [('main', v, (0, 0, 0))]


def iron_pool_glow(name):
    """溶けた鉄の湯面（地獄）— **火の枠の炎の側**。自発光は置く側が乗せる。

    炎ではないので**揺らさない**（振り子で回すと液面が傾く）。素の色は明るくしない
    ——自発光（1.35 / 0.85 / 0.30）が乗ると白く飛ぶ（噴気孔のガスで踏んだ話と同じ）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.uint8)
    for x in range(V):
        for y in range(V):
            if math.hypot(x - 16 + 0.5, y - 16 + 0.5) <= 9.4:
                v[x, y, 0:2] = C['bub'] if rng.random() < 0.72 else C['bub_d']
    #! 湯の花（明るい筋）。**塊で 3 本**（点で撒くと火の粉に見える）。
    for _ in range(3):
        x, y = int(rng.integers(9, 20)), int(rng.integers(9, 20))
        v[x:x + int(rng.integers(4, 9)), y:y + 2, 1:2] = C['bub_l']
    return [('main', v, (0, 0, 1))]


# ---- 6 墓地 / 7 森 / 14 山: 案に名前だけ在ったもの ----


def flowers_dead(name):
    """枯れた花（墓地）— 墓石に供えたものが枯れている。**束ねてあること**が読み。

    野に生えた枯れ草と分けるために、**根本を縄で括る**。括ってあれば人が置いたものになる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 6), np.uint8)
    #! **寝かせる。**立てる版を 2 度作って 2 度とも失敗した——扇に開いても、幅 2 の茎を
    #! 6 本立てると隣どうしがくっついて 1 個の塊になる（マスは 32 ボクセルしかないので、
    #! 縦に立てた細いものを何本も並べる余地が無い）。**供えた花は寝ている**ほうが
    #! 理屈にも合う。寝かせれば長さ 20 マスまで取れて、束・茎・花の 3 つが並んで読める。
    #! 平たいものが読めるのは `slough`（抜け殻）と `bones_small` で確かめてある。
    ax, ay = 6, 22          # 根本（束ねてある側）
    bx, by = 26, 9          # 花の側
    for k in range(6):
        off = k - 2.5
        #! 茎。**幅 2 で寝かせる**（幅 1 は 1 画素の線になって消える＝`bones_small` の約束）。
        for step in range(21):
            t = step / 20.0
            x = int(round(ax + (bx - ax) * t + off * t * 1.6))
            y = int(round(ay + (by - ay) * t + off * (1.0 - t) * 0.4))
            if (0 <= x < V - 1) and (0 <= y < V - 1):
                v[x:x + 2, y:y + 2, 0:1] = C['wilt_d'] if (step % 3) else C['wilt']
        #! 花。**花の側の端に固めて置く**（散らすと落ち葉になる）。1 段持ち上げる。
        hx = int(round(bx + off * 1.6))
        hy = int(round(by))
        if (1 <= hx < V - 4) and (1 <= hy < V - 4):
            v[hx - 1:hx + 3, hy - 1:hy + 3, 0:2] = C['wilt_p']
            v[hx:hx + 2, hy:hy + 2, 2:3] = C['wilt_p']
    #! 括った縄。**根本を 3 段持ち上げる**——束ねてあるから供物に読める（野の枯れ草ではない）。
    v[ax - 1:ax + 5, ay - 2:ay + 4, 0:3] = C['wilt_d']
    v[ax + 1:ax + 4, ay - 1:ay + 3, 2:4] = C['lash']
    #! 落ちた花びら（供えてから時間が経っている）。
    for _ in range(4):
        x, y = int(rng.integers(4, V - 5)), int(rng.integers(4, V - 5))
        if v[x, y, 0] == 0:
            v[x:x + 2, y:y + 2, 0:1] = C['wilt_p']
    return [('main', v, (0, 0, 0))]


def bones_deer(name):
    """鹿の骨（森）— **角があること**だけが人骨（`bones`）との差である。

    森の部屋の中に人骨が転がっているのは物語が違う（ここは獣の森で、墓地ではない）。
    頭は横倒しにして、**角を左右へ広げる**——角は上へ伸ばすと木の枝に見える。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 18), np.uint8)
    hx, hy = 14, 14
    #! 頭。**立てて置く**（横倒しにすると角が地面に埋まって、白い棒の散らばりになった）。
    v[hx:hx + 7, hy:hy + 6, 0:7] = C['bone']
    v[hx + 1:hx + 6, hy - 4:hy + 1, 0:5] = C['bone_d']  # 鼻づら（手前へ）
    v[hx + 1, hy - 3, 3] = C['dark']
    v[hx + 5, hy - 3, 3] = C['dark']
    #! 角。**上へ大きく開く**のが鹿の読み。幅 2 で 3 又、先を外へ跳ねさせる
    #! （初版は z=3〜8 に寝かせていたので、頭の上の瘤にしか見えなかった）。
    for side in (-1, 1):
        bx = hx + (0 if side < 0 else 5)
        x, z = bx, 7
        for k in range(6):  # 主枝（外へ反りながら上へ）
            x = max(1, min(V - 3, x + side))
            z += 1
            v[x:x + 2, hy + 1:hy + 3, z:z + 2] = C['bone']
        for k, (ox, oz) in enumerate(((-2, -5), (-1, -2))):  # 枝を 2 本
            tx = max(1, min(V - 3, x + side * ox))
            for j in range(3):
                v[tx:tx + 2, hy + 1:hy + 3, z + oz + j:z + oz + j + 2] = C['bone_d']
                tx = max(1, min(V - 3, tx + side))
        v[x:x + 2, hy + 1:hy + 3, z + 2:z + 4] = C['bone_d']  # 先
    #! 肋と脚（**幅 2 で寝かせる**＝`bones_small` と同じ約束）。
    for _ in range(4):
        x, y = int(rng.integers(3, 11)), int(rng.integers(6, 22))
        ln = int(rng.integers(6, 11))
        v[x:x + 2, y:min(y + ln, V), 0] = C['bone_d'] if rng.random() < 0.5 else C['bone']
    return [('main', v, (0, 0, 0))]


def rockfall(name):
    """落石（山）— 行き止まりに置く。**上から落ちてきた**ことが読み。

    瓦礫（`rubble_pile`）との差は「角が立っていて、大きさに開きがある」こと。
    崩した石は丸くならないし、1 個だけ大きいと落ちてきた感じになる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 17), np.uint8)
    #! 主役の 1 個。**マスの 4 割ほど**（これが無いと砂利の山になる）。
    bx, by = int(rng.integers(9, 14)), int(rng.integers(9, 14))
    v[bx:bx + 13, by:by + 12, 0:11] = C['crag_d']
    v[bx + 1:bx + 12, by + 1:by + 11, 9:13] = C['crag']
    v[bx + 3:bx + 10, by + 2:by + 9, 12:14] = C['crag_l']
    for _ in range(4):  # 角を落とす（**塊で削る**＝直方体のままにしない）
        x = int(rng.integers(bx, bx + 10))
        y = int(rng.integers(by, by + 9))
        v[x:x + int(rng.integers(3, 6)), y:y + int(rng.integers(3, 6)),
          int(rng.integers(8, 13)):14] = 0
    #! 砕けた小石。**主役の周りへ**（遠くへ撒くと別の物に見える）。
    _scatter_lumps(v, rng, count=9, box=(3, V - 6), span=(2, 6), height=(1, 5),
                   shades=[C['crag_d'], C['crag'], C['crag_dd'], C['lichen']],
                   weights=[0.38, 0.28, 0.24, 0.10])
    return [('main', v, (0, 0, 0))]


# ---- 11 水没した遺跡: 珊瑚と、貝と壺 ----


def coral(name):
    """珊瑚（水没した遺跡）— **枝分かれ**が水の中の読み。壁際に生える。

    海藻（`kelp`）が揺れで水を言うのに対して、こちらは**形**で言う。
    枝は 3 回まで分かれ、**先端だけ明るい**（生きている先）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 26), np.uint8)
    v[12:20, 12:20, 0:3] = C['cor_d']  # 根

    def branch(x, y, z, dx, dy, depth):
        for _ in range(int(rng.integers(4, 8))):
            x += dx
            y += dy
            z += 1
            if not ((1 <= x < V - 2) and (1 <= y < V - 2) and (z < 24)):
                return
            v[x:x + 2, y:y + 2, z:z + 2] = C['cor'] if depth < 2 else C['cor_l']
        if depth >= 3:
            v[x:x + 3, y:y + 3, z:z + 3] = C['cor_l']  # 先端
            return
        for ndx, ndy in ((dx + 1, dy), (dx - 1, dy), (dx, dy + 1)):
            if rng.random() < 0.7:
                branch(x, y, z, max(-1, min(1, ndx)), max(-1, min(1, ndy)), depth + 1)

    for k in range(3):
        ang = k / 3.0 * 2.0 * math.pi
        branch(16, 16, 3, int(round(math.cos(ang))), int(round(math.sin(ang))), 0)
    return [('main', v, (0, 0, 0))]


def amphora(name):
    """貝と壺（水没した遺跡）— 沈んだ積荷。**壺は倒れている**（立っていると店になる）。

    難破船の肋材（`wreck_rib`）と同じ「積荷が散った」系統だが、あちらは船の骨格で、
    こちらは中身である。壺の口から砂がこぼれ、周りに貝が付いている。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 14), np.uint8)
    #! 横倒しの壺。**輪郭で言う**（罠 103 の 3 つ目）。初版は胴を正弦で膨らませただけの
    #! 塊で、寄ると「編んだ球」にしか見えなかった。**胴・肩・首・口を段で分ける**と、
    #! 側面の影が段のところで折れて壺の形が出る。
    cy, cz = 16, 6
    prof = []  # (x の範囲, 半径)
    prof += [(4, 7, 3.4)]                     # 底（すぼまっている）
    prof += [(7, 10, 5.0)]                    # 腰
    prof += [(10, 18, 6.4)]                   # 胴（いちばん太い）
    prof += [(18, 21, 5.0)]                   # 肩
    prof += [(21, 25, 2.8)]                   # 首（**細くする**のが壺の決め手）
    prof += [(25, 28, 4.2)]                   # 口の縁（首より広げる）
    for x0, x1, r in prof:
        for x in range(x0, min(x1, V)):
            for y in range(V):
                for z in range(14):
                    if math.hypot(y - cy + 0.5, z - cz + 0.5) <= r:
                        #! 手前（-y）を明るく。無地の筒は面が読めない。
                        v[x, y, z] = C['clay'] if (y < cy) else C['clay_d']
    #! 取っ手。**輪郭の外へ張り出す**（胴に沿わせると見えない）。肩と胴を繋ぐ 2 本。
    for side in (-1, 1):
        ya = cy + side * 7
        v[13:20, min(ya, ya + 2):max(ya, ya + 2) + 1, cz + 3:cz + 6] = C['clay_d']
        v[13:15, min(cy + side * 5, ya):max(cy + side * 5, ya) + 1, cz + 3:cz + 6] = C['clay_d']
        v[18:20, min(cy + side * 5, ya):max(cy + side * 5, ya) + 1, cz + 3:cz + 6] = C['clay_d']
    #! こぼれた砂。**口の側だけ**（両側に散らすと割れた壺になる）。
    for _ in range(5):
        x, y = int(rng.integers(27, V - 2)), int(rng.integers(10, 22))
        v[x:x + 2, y:y + 3, 0:2] = C['silt_l']
    #! 貝。壺から離して置く（付いていると模様に見える）。
    for _ in range(4):
        x, y = int(rng.integers(4, V - 4)), int(rng.integers(3, V - 4))
        if abs(y - cy) > 8:
            v[x:x + 3, y:y + 2, 0:2] = C['bone'] if rng.random() < 0.6 else C['verd']
    return [('main', v, (0, 0, 0))]


# ---- 13 ルルイエ: 粘液と、傾いた柱 ----


def slime_green(name):
    """緑の粘液（ルルイエ）— **垂れている**ことが読み。壁際に置く。

    苔（面に貼る）とも茸（立つ）とも分ける。**上が厚く、下へ細く垂れる**筋を数本、
    壁の側（-y）へ寄せて置くと「壁から垂れている」に見える。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.uint8)
    #! **壁から垂らすのをやめた。**筋 4 本＝緑の柱、庇つき＝緑の椅子、1 枚の幕＝緑の板。
    #! 3 度とも「壁に付いた縦のもの」が別の物に読めていて、直し方が見えない。
    #! **床の溜まりに替える**——粘液は下に溜まるものでもあるので、案の「緑の粘液」から
    #! 外れない。玉を寄せて溶かし合わせる形は `egg_cluster` で読めることが確かめてある
    #! （形を発明しないこと＝`prism` で学んだのと同じ）。
    #!
    #! 苔（面に貼る）との差は**厚みと艶**で付ける。溜まりに 3 段の高さを持たせ、
    #! 頂だけ明るくすると濡れて見える。
    for x in range(V):  # 溜まり（縁を崩した薄い面）
        for y in range(V):
            d = math.hypot((x - 15) * 0.85, (y - 16) * 1.0)
            if d <= 11.5 - rng.random() * 2.2:
                v[x, y, 0:2] = C['tent_d'] if d > 8.0 else C['slime']
    #! 盛り上がった玉。**大きさを揃えない**（揃えると卵の塊になる）。
    for cx, cy, r in ((13, 14, 5.2), (20, 18, 4.0), (15, 22, 3.2), (22, 12, 2.6)):
        _blob(v, cx, cy, 1, r, C['slime'])
        _blob(v, cx, cy - 1, int(r) - 1, r * 0.55, C['slime_l'])  # 頂の艶
    v[:, :, 10:] = 0
    #! 糸を引いている（粘る、を言う唯一の手）。**細い縦の筋を 2 本だけ。**
    for cx, cy in ((13, 14), (20, 18)):
        h = int(rng.integers(6, 10))
        v[cx:cx + 2, cy:cy + 2, 4:4 + h] = C['slime_l']
        v[cx:cx + 1, cy:cy + 1, 4 + h:4 + h + 2] = C['slime']
    return [('main', v, (0, 0, 0))]


def pillar_tilted(name):
    """わずかに傾いた柱（ルルイエ）— **角度が狂った街**。部屋の縁に立てる。

    傾けるのは**柱身だけ**で、マスそのものは直方体を保つ（マスの形は通れる／通れないの
    判別なので崩さない＝2026-08-09 に決めた）。段ごとに 1 ボクセルずらして積むと、
    箱の中で柱だけが倒れかけて見える。**倒し方は変種ごとに向きを替える**。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 46), np.uint8)
    #! 倒れる向きは**種から引く**。`name[-2:]` で変種番号を読む書き方にしていたが、
    #! これは 1 個もの（`pillar_tilted` に `_01` は付かない）なので、**その枝は死んでいた**
    #! ——同じ穴が `prism` にも在った。1 個ものでは名前から変種を読まないこと。
    ang = float(rng.uniform(0.0, 2.0 * math.pi))
    dx, dy = math.cos(ang), math.sin(ang)
    cx = cy = 16
    v[cx - 7:cx + 7, cy - 7:cy + 7, 0:3] = C['cyc_d']  # 台座（**傾けない**）
    v[cx - 6:cx + 6, cy - 6:cy + 6, 3:4] = C['cyc']
    #! 柱身。**倒れ幅 8 マス**（初版は 4 マスで、「わずかに傾いた」が「まっすぐ」に見えた。
    #! 高さ 40 に対して 4 マスは 6°——実機の見下ろす角では読めない。8 マス＝ 11° にした）。
    for z in range(4, 42):
        t = (z - 4) / 38.0
        ox = dx * t * 8.0
        oy = dy * t * 8.0
        r = 5.2 - t * 0.5
        for x in range(V):
            for y in range(V):
                if math.hypot(x - cx - ox + 0.5, y - cy - oy + 0.5) <= r:
                    v[x, y, z] = C['cyc'] if (z % 8) else C['cyc_l']
    #! 柱頭。**傾いた先へ付ける**（真上に付けると柱が折れて見える）。
    tx = int(round(cx + dx * 8.0))
    ty = int(round(cy + dy * 8.0))
    v[max(0, tx - 6):min(V, tx + 6), max(0, ty - 6):min(V, ty + 6), 41:44] = C['cyc_d']
    v[max(0, tx - 5):min(V, tx + 5), max(0, ty - 5):min(V, ty + 5), 44:45] = C['cyc_l']
    #! 根元の割れ（傾いたなら台座が割れている）。**倒れた側を欠く**。
    for _ in range(4):
        x = int(cx + dx * 6 + rng.integers(-3, 4))
        y = int(cy + dy * 6 + rng.integers(-3, 4))
        v[max(0, x):x + 3, max(0, y):y + 3, 2:4] = C['cyc_j']
    return [('main', v, (0, 0, 0))]


# ---- 20 ガラスの城 / 10 天界 ----


def glass_sconce(name):
    """ガラスの燭台（ガラスの城）— 城の鉄の燭台（`sconce`）を借りていた所を替える。

    **受け皿の高さは `sconce` と同じ**（炎＝`torch_flame` は z=30 に来る）。
    鉄を硝子へ替え、腕を**曲げずに 1 本の棒**にする——硝子は鍛えられないので、
    鉄の燭台の曲がった腕をそのまま硝子にすると嘘になる。
    """
    v = np.zeros((V, V, 34), np.uint8)
    #! 壁の座。**`sconce`（金の燭台）と同じ寸法**にしてある——同じ枠に入る物なので、
    #! 大きさが違うと城とガラスの城で「別の種類の物」に見える。
    #! 初版は幅 6・厚み 3 の小さな座と幅 2 の腕で、**遠目に灰色の点**にしかならなかった。
    #! **暗い硝子（`glass` = 48,56,70）を基調にしない。**初版はそれで組んで、暗い壁の前で
    #! 影と見分けが付かなかった——`pillar_glass`（柱）は 46 マスの高さがあるので輪郭で読めるが、
    #! 燭台のような小さいものは**明度そのもの**で読ませるしかない。`glass_l` を基調にして、
    #! 稜と蝋燭を `qz_l`（白）で抜く。暗い `glass` は影の側だけに使う。
    v[11:21, 1:5, 14:24] = C['glass_l']
    v[12:20, 1:2, 16:22] = C['qz_l']
    v[12:20, 4:5, 14:24] = C['glass']  # 壁と接する側だけ暗く（面の向きを出す）
    v[11:12, 1:5, 14:24] = C['qz_l']  # 座の稜
    v[20:21, 1:5, 14:24] = C['qz_l']
    for y in range(4, 15):  # 腕（まっすぐ前へ。硝子は鍛えられないので曲げない）
        v[14:18, y:y + 1, 21:24] = C['qz_l'] if (y % 3) else C['glass_l']
    v[12:20, 12:20, 22:26] = C['glass_l']  # 受け皿
    v[13:19, 13:19, 24:26] = 0  # 皿の窪み
    for x, y in ((12, 12), (12, 19), (19, 12), (19, 19)):
        v[x:x + 1, y:y + 1, 22:28] = C['qz_l']
    v[15:17, 15:17, 24:30] = C['qz_l']  # 蝋燭。**天面が炎の底（z=30）に合う**
    return [('main', v, (0, 0, 0))]


def prism(name):
    """プリズム（ガラスの城）— **光を割るもの**。部屋の中に置く。

    ボクセルは不透明前提なので透過はできないが、**面ごとに色を変える**ことで
    「向こうが色付きで見えている」を匂わせられる。柱（`pillar_glass`）が稜の明るさで
    透けを言うのに対して、こちらは**色**で言う。台座に載せて「置かれた物」にする。
    """
    v = np.zeros((V, V, 30), np.uint8)
    #! **形を発明しない。**三角柱で 2 度・切子で 1 度失敗した（板／縞の板／白い貝殻）。
    #! 3 度目からは**実機で読めることが確かめてある形**を使う——尖った結晶を 3 本立てる
    #! `crystal_black`（暗闇の洞窟）がそれで、最初の一覧で 1 度も引っ掛からなかった。
    #! **同じ形に別の色を入れる**のは第 5 期で材にやったのと同じ手である。
    #! 光を割るのは**色の側**の仕事にした——3 本を別の色にして、割れて出た光を言う。
    v[10:22, 10:22, 0:2] = C['marb_g']  # 台座（**石**。硝子の上に硝子を載せると 1 体に見える）
    v[11:21, 11:21, 2:3] = C['marb_l']
    spikes = ((13, 14, 24, 4.0, C['sky']), (21, 17, 17, 3.0, C['fl_y']),
              (16, 22, 12, 2.6, C['verd']))
    for cx, cy, h, r0, colour in spikes:
        for z in range(3, 3 + h):
            r = r0 * (1.0 - (z - 3) / float(h)) + 0.7
            for x in range(V):
                for y in range(V):
                    if ((x - cx) ** 2 + (y - cy) ** 2) <= r * r:
                        #! 先の 3 段だけ白く抜く（**光が出ていく口**。全体を明るくすると
                        #! 3 本の色が飛んで、白い結晶が 3 本になる）。
                        v[x, y, z] = C['qz_l'] if z > 3 + h - 4 else colour
    return [('main', v, (0, 0, 0))]


def harp(name):
    """竪琴（天界）— 部屋の中。**弦が見えること**が竪琴の読み。

    弦は 1 ボクセル幅だと消えるので**幅 2・間を 2 空ける**。枠を金、弦を白にして
    明度で分ける。翼の像（`statue_winged`）と同じ「置かれた物」の系統である。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.uint8)
    v[10:22, 14:18, 0:3] = C['marb_g']  # 台
    #! 枠。**前柱・湾曲した頸・響胴**の 3 つが揃うと竪琴に見える。
    v[10:13, 14:18, 3:26] = C['gold_d']  # 前柱
    v[19:23, 14:18, 3:14] = C['gold_d']  # 響胴
    for k in range(9):  # 頸（前柱の頭から響胴へ弧を描く）
        x = 13 + k
        z = 26 - int((k / 8.0) ** 1.7 * 13)
        v[x:x + 2, 14:18, z:z + 3] = C['gold']
    #! 弦。**幅 2・2 空け**（幅 1 では 1 画素の線になって消える＝`bones_small` と同じ話）。
    for k in range(4):
        x = 13 + k * 2
        z_top = 25 - int((k / 4.0) ** 1.6 * 11)
        v[x:x + 1, 15:17, 6:z_top] = C['qz_l']
    if rng.random() < 0.5:
        v[11:13, 13:15, 24:27] = C['gold']  # 前柱の飾り
    return [('main', v, (0, 0, 0))]


def candle_white(name):
    """白い蝋燭立て（天界）— 立ち松明（鉄の柱）の代わりに置く火の本体。

    天界の材は永久壁（磨いた黒曜石）と真珠層の床で、そこへ**錆びうる鉄**を立てるのは
    ちぐはぐである（森とイークの洞穴で切石の柱を降ろしたのと同じ理屈＝案の §7）。
    **受け皿は z=27〜31**——既定の炎（`torch_flame`・z=30）がそのまま載る。
    """
    v = np.zeros((V, V, 34), np.uint8)
    for z in range(0, 4):  # 台座（段になった大理石）
        r = 8.4 - z * 0.7
        for x in range(V):
            for y in range(V):
                if math.hypot(x - 16 + 0.5, y - 16 + 0.5) <= r:
                    v[x, y, z] = C['marb_g'] if z < 2 else C['marb_d']
    for z in range(4, 24):  # 柱身（真珠層）
        r = 3.4 + math.sin(z / 24.0 * math.pi) * 0.9
        for x in range(V):
            for y in range(V):
                if math.hypot(x - 16 + 0.5, y - 16 + 0.5) <= r:
                    v[x, y, z] = C['nacr'] if (z % 7) else C['nacr_l']
    v[12:20, 12:20, 24:27] = C['gold_d']  # 金の受け
    v[13:19, 13:19, 27:29] = C['marb_l']  # 蝋
    v[14:18, 14:18, 29:31] = C['marb_l']
    return [('main', v, (0, 0, 0))]


# ------------------------------------------------------- 町（P10 第 2 期・§10）
#
# 建物は**壁と屋根を別のプレハブ**にしてある。理由は 2 つ。
#   1. インスタンス色はプレハブ単位なので、1 つにまとめると漆喰と瓦が一緒に転ぶ
#   2. 階数を「壁を積む枚数」で決められる（2 階建ての屋根を作り直さなくてよい）
# 形は**寄棟屋根の 9 スライス**（`town_plan.h` の `HouseSlice`）。四方へ落ちる屋根は
# 向きを持たないので、任意の矩形の建物がこの 9 枚だけで組める。
HOUSE_WALL_H = 34   # 壁 1 層の高さ（ボクセル）= 1.0625 マス
HOUSE_ROOF_H = 30   # 屋根の高さ = 0.9375 マス
HOUSE_EAVE = 4      # 軒先の厚み（ボクセル）
HOUSE_INSET = 2     # 外に面した壁を引っ込める量（＝軒の出）
HOUSE_PLINTH = 5    # 土台。**ここだけはマスいっぱい**（罠 5。隙間から下が見える）

#: スライス → 外に面している辺 (北, 南, 西, 東)
SLICE_OUT = {
    'nw': (1, 0, 1, 0), 'n': (1, 0, 0, 0), 'ne': (1, 0, 0, 1),
    'w': (0, 0, 1, 0), 'mid': (0, 0, 0, 0), 'e': (0, 0, 0, 1),
    'sw': (0, 1, 1, 0), 's': (0, 1, 0, 0), 'se': (0, 1, 0, 1),
}
HOUSE_SLICES = ('nw', 'n', 'ne', 'w', 'mid', 'e', 'sw', 's', 'se')

# ---- 町ごとの意匠（2026-08-09 に決めた「街ごとの雰囲気の変化」）----
#
# 同じ枠（壁 9 スライス・屋根 9 スライス・地面・柵・城壁・やぐら）に**別の材**を入れる。
# 名前は「基の名前へ意匠を差し込む」だけで、置く側（`terrain_view.cpp`）は
# 接尾辞を付けて引き、無ければ基の名前へ落ちる。
#
# | 意匠 | 町 | 地面 | 壁 | 屋根 | 塀 |
# |---|---|---|---|---|---|
# | （無し） | 辺境の地 | 土と短い草 | 板と丸太 | 板張り | 丸太＋木のやぐら |
# | `tel` | テルモラ | 半舗装の土＋麦わらの草 | 木骨漆喰 | 藁葺き | 乱石積み＋石と木のやぐら |
# | `mor` | モリバント | 大判の敷石＋玉石 | 切石＋漆喰 | 瓦 | 切石の城壁＋円塔 |
#
# **辺境の地の素材は 1 ボクセルも触らない**（実機で見て閉じている）。
# 分岐は必ず「意匠が空なら従来の本体へ」の形で書くこと。
TOWN_STYLES = ('tel', 'mor', 'jin', 'ten', 'kyu', 'koma', 'hak', 'kap', 'ein', 'kor',
               'myo', 'kir', 'hai', 'moy', 'hig', 'git')


def _split_style(name):
    """名前から意匠を切り出す。`('tel', 'house_wall_nw')` のように (意匠, 基の名前) を返す。

    意匠は**茎（stem）のすぐ後ろ**に入る（`ground_path_tel_01`）か、**末尾**に付く
    （`house_wall_nw_tel`）。どちらでも拾えるよう、区切りで割って探す。
    """
    parts = name.split('_')
    for i, part in enumerate(parts):
        if part in TOWN_STYLES:
            return part, '_'.join(parts[:i] + parts[i + 1:])
    return '', name


def _slice_of(name):
    return _split_style(name)[1].rsplit('_', 1)[-1]


def house_wall(name):
    """建物の壁 1 層。外に面した辺だけを作り込む（内側は隣のマスに隠れる）。

    土台 → 漆喰 → 隅柱と胴差し（木組み）→ 窓、の順に置く。**窓は南面だけ**に彫る
    （見下ろすカメラの正面。北面は建物自身に隠れて 1 画素も見えない）。

    意匠つきの名前（`house_wall_nw_tel` など）は別の材へ振り分ける。
    """
    style = _split_style(name)[0]
    if style == 'tel':
        return _house_wall_timber(name)
    #! koma（紅魔館）の敷地の家は**モリバントと同じ絵**（2026-08-18 に決めた
    #! 「敷地内の三つの永久岩は洋風たてものて置き換え。モリバンドの建物だけを配置」）。
    #! suffix を _mor にすると塀と地面まで引きずられるので、名前だけ分けて絵を転送する。
    #! hai（廃洋館）の地図に**敷地は 1 件も無い**（塀の輪と館だけ）。ただし実機の読みは
    #! **既知のマスから立つ**ので、塀を部分的にしか見ていない段では敷地に読まれうる——
    #! そこで丸太の家が生えないよう、切石の家（モリバントの絵）へ流しておく。
    if style in ('mor', 'koma', 'hai'):
        return _house_wall_stone(name)
    if style == 'kap':
        return _house_wall_kap(name)
    #! ein（永遠亭）の地図に**敷地は 1 件も無い**（壁の塊は 1 つで、屋敷として立つ）。
    #! ここへ来ることは無いが、来たときに西洋の板壁が出ないよう人里の造りへ流す。
    #! myo（命蓮寺）の宿坊も同じ（造りは和風のまま、色は表の tint で寺へ振る）。
    #! moy（守矢神社）の脇の小屋も同じ（造りは和風のまま、色は表の tint で山の社へ振る）。
    #! hig（彼岸）の雑貨屋（9×4）も和風の造り。色は表の tint で白漆喰へ振る。
    if style in ('jin', 'ein', 'myo', 'moy', 'hig'):
        return _house_wall_tsuchi(name)
    #! git（偽天棚）は**石場建ての縦板張り**（高原の小屋。デザイン15）。
    if style == 'git':
        return _house_wall_git(name)
    if style == 'ten':
        #! 2026-08-18 その3 に決めた「天狗の里の設定は洋風建築より和風建築のがよく
        #! ないか？人里の建物の色違いにしよう」——白漆喰＋黒柱の真壁は木骨（西洋）に
        #! 読めた。造りは人里と同じ（焼杉の腰板＋土壁＋障子）にし、色は表の tint で
        #! 山の里へ振る。真壁の生成器（_house_wall_shinkabe）は記録として残す。
        return _house_wall_tsuchi(name)
    #! hak（博麗神社）の脇の小屋（ライブラリなど敷地 2 つ）も人里の造りの色違い（天狗の里と同じ手。
    #! Q3「意匠は 3 町だけ」は新しい家並みを設計しない話で、生成器の共用は工数ゼロ）。
    if style == 'hak':
        return _house_wall_tsuchi(name)
    if style == 'kyu':
        return _house_wall_shitami(name)
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    v = np.zeros((V, V, HOUSE_WALL_H), np.uint8)

    # 土台（マスいっぱい）。上に載る躯体だけを引っ込める。
    v[:, :, 0:HOUSE_PLINTH] = C['wall_d']
    v[:, :, HOUSE_PLINTH - 1] = C['wall']

    x0 = HOUSE_INSET if west else 0
    x1 = V - HOUSE_INSET if east else V
    y0 = HOUSE_INSET if north else 0
    y1 = V - HOUSE_INSET if south else V
    v[x0:x1, y0:y1, HOUSE_PLINTH:] = C['plas']

    # 漆喰のむら（塊単位。ボクセル単位に散らすと砂嵐になる＝罠 38）。
    for _ in range(6):
        bx = int(rng.integers(x0, max(x0 + 1, x1 - 6)))
        bz = int(rng.integers(HOUSE_PLINTH, HOUSE_WALL_H - 5))
        shade = C['plas_l'] if rng.random() < 0.5 else C['plas_d']
        v[bx:bx + 6, y0:y1, bz:bz + 5][v[bx:bx + 6, y0:y1, bz:bz + 5] == C['plas']] = shade

    def face(side):
        """その辺の外側 1 ボクセルの面（木組みと窓を彫る所）を (x スライス, y スライス) で返す。"""
        if side == 'n':
            return (slice(x0, x1), slice(y0, y0 + 1))
        if side == 's':
            return (slice(x0, x1), slice(y1 - 1, y1))
        if side == 'w':
            return (slice(x0, x0 + 1), slice(y0, y1))
        return (slice(x1 - 1, x1), slice(y0, y1))

    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        fx, fy = face(side)
        # 胴差し（軒下の帯）と足元の水切り。
        v[fx, fy, HOUSE_WALL_H - 4:HOUSE_WALL_H] = C['timber']
        v[fx, fy, HOUSE_PLINTH:HOUSE_PLINTH + 2] = C['timber_d']
        # 柱（等間隔の縦の木）。**面の中だけ**なので三角形は増えない。
        span = fx if side in ('n', 's') else fy
        lo, hi = span.start, span.stop
        for p in range(lo + 3, hi - 3, 9):
            if side in ('n', 's'):
                v[p:p + 2, fy, HOUSE_PLINTH:HOUSE_WALL_H - 4] = C['timber']
            else:
                v[fx, p:p + 2, HOUSE_PLINTH:HOUSE_WALL_H - 4] = C['timber']

    # 窓（南面だけ）。枠を彫り込み、奥にガラスを置く。
    if south:
        wx = (x0 + x1) // 2 - 5
        wz = HOUSE_PLINTH + 8
        v[wx - 1:wx + 11, y1 - 2:y1, wz - 1:wz + 13] = C['timber_l']  # 枠
        v[wx:wx + 10, y1 - 2:y1, wz:wz + 12] = C['glass']
        v[wx:wx + 10, y1 - 2:y1, wz + 5:wz + 7] = C['glass_l']  # 中桟の照り返し
    return [('main', v, (0, 0, 0))]


def _house_face(x0, x1, y0, y1, side):
    """その辺の外側 1 ボクセルの面を (x スライス, y スライス) で返す（意匠つきの壁で共用）。"""
    if side == 'n':
        return (slice(x0, x1), slice(y0, y0 + 1))
    if side == 's':
        return (slice(x0, x1), slice(y1 - 1, y1))
    if side == 'w':
        return (slice(x0, x0 + 1), slice(y0, y1))
    return (slice(x1 - 1, x1), slice(y0, y1))


def _house_wall_timber(name):
    """**テルモラの壁** — 石の土台に木骨（ハーフティンバー）、間を生成りの漆喰で埋める。

    辺境の板壁との違いは 3 つ。**土台が石**（乱石積みを 9 ボクセル）・**筋交いが入る**
    （斜めの木。これが「木骨」の読みを作る唯一の要素で、縦の柱だけでは辺境と見分けが
    付かなかった）・**漆喰が生成りで明るい**。木は漆喰より 3 段暗くとる——絵は面積では
    なく明度差で読める（罠 74）。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    plinth = 9  #!< 辺境（5）より高い石の土台。雨仕舞いの厚みがそのまま町の格になる
    v = np.zeros((V, V, HOUSE_WALL_H), np.uint8)

    #! 乱石積みの土台（マスいっぱい＝罠 5）。**石は横に並べる**——2 次元のむらをそのまま
    #! 上へ伸ばすと、側面が縦縞になって板壁に見える（見えるのは側面だけである）。
    v[:, :, 0:plinth] = C['rub_d']
    for z in range(1, plinth - 1):
        row = np.zeros(V, np.uint8)
        p = 0
        while p < V:
            w = int(rng.integers(5, 10))
            row[p:p + w] = rng.choice([C['rub'], C['rub_l'], C['rub_d']], p=[0.5, 0.26, 0.24])
            p += w
        v[:, 0, z] = row
        v[:, V - 1, z] = row[::-1]
        v[0, :, z] = row[::-1]
        v[V - 1, :, z] = row
    v[:, :, plinth - 1] = C['rub_l']  # 水切りの天端

    x0 = HOUSE_INSET if west else 0
    x1 = V - HOUSE_INSET if east else V
    y0 = HOUSE_INSET if north else 0
    y1 = V - HOUSE_INSET if south else V
    v[x0:x1, y0:y1, plinth:] = C['cream']
    # 漆喰のむら（塊単位＝罠 38）。
    for _ in range(6):
        bx = int(rng.integers(x0, max(x0 + 1, x1 - 6)))
        bz = int(rng.integers(plinth, HOUSE_WALL_H - 5))
        shade = C['cream_l'] if rng.random() < 0.5 else C['cream_d']
        block = v[bx:bx + 6, y0:y1, bz:bz + 5]
        block[block == C['cream']] = shade

    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        fx, fy = _house_face(x0, x1, y0, y1, side)
        v[fx, fy, HOUSE_WALL_H - 4:HOUSE_WALL_H] = C['beam']       # 軒桁
        v[fx, fy, plinth:plinth + 3] = C['beam']                   # 土台際の土台差し
        span = fx if side in ('n', 's') else fy
        lo, hi = span.start, span.stop
        #! 柱（等間隔の縦の木）。面の中だけなので三角形は増えない。
        posts = list(range(lo + 2, hi - 2, 11))
        for p in posts:
            if side in ('n', 's'):
                v[p:p + 3, fy, plinth:HOUSE_WALL_H - 4] = C['beam']
            else:
                v[fx, p:p + 3, plinth:HOUSE_WALL_H - 4] = C['beam']
        #! **筋交い**（斜めの木）。柱と柱の間へ 1 本ずつ。これが木骨の読みを作る。
        top = HOUSE_WALL_H - 4
        for a, b in zip(posts, posts[1:]):
            rise = top - (plinth + 3)
            run = max(1, b - a)
            up = rng.random() < 0.5   # 右上がり／左上がりを混ぜる（全部同じだと縞に見える）
            for t in range(run):
                z = plinth + 3 + int(round(rise * (t / run if up else 1.0 - (t / run))))
                pos = a + t
                zz0, zz1 = max(plinth, z - 1), min(top, z + 2)
                if zz0 >= zz1:
                    continue
                if side in ('n', 's'):
                    v[pos:pos + 2, fy, zz0:zz1] = C['beam_l']
                else:
                    v[fx, pos:pos + 2, zz0:zz1] = C['beam_l']

    # 窓（南面だけ）。木の格子（縦桟 1 本）を入れる。
    if south:
        wx = (x0 + x1) // 2 - 5
        wz = plinth + 7
        v[wx - 1:wx + 11, y1 - 2:y1, wz - 1:wz + 13] = C['beam_l']
        v[wx:wx + 10, y1 - 2:y1, wz:wz + 12] = C['glass']
        v[wx + 4:wx + 6, y1 - 2:y1, wz:wz + 12] = C['beam']   # 縦桟
        v[wx:wx + 10, y1 - 2:y1, wz + 5:wz + 7] = C['glass_l']
    return [('main', v, (0, 0, 0))]


def _house_wall_stone(name):
    """**モリバントの壁** — 切石積みの下半分と漆喰の上半分。角には隅石。

    段（course）は**高さで切る**ので、どのスライスでも水平に通る。継ぎ目は段ごとに
    半枚ずらす（芋目地を避ける＝`floor_room` と同じ流儀）。目地は色ではなく**1 ボクセル
    彫る**——溝は AO と影が勝手に暗くするので、素材の側で暗くすると二重に効く（罠 44）。

    2 階建ては同じ壁を積むので、石と漆喰の帯が階ごとにくり返す。都市の石造家屋として
    辻褄が合ううえ、**階の境が読める**ので高さが伝わる。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    plinth = 6
    course = 6      #!< 石 1 段の高さ
    stone_top = 21  #!< ここから上は漆喰
    v = np.zeros((V, V, HOUSE_WALL_H), np.uint8)

    v[:, :, 0:plinth] = C['ash_d']
    v[:, :, plinth - 1] = C['ash']

    x0 = HOUSE_INSET if west else 0
    x1 = V - HOUSE_INSET if east else V
    y0 = HOUSE_INSET if north else 0
    y1 = V - HOUSE_INSET if south else V
    v[x0:x1, y0:y1, plinth:stone_top] = C['ash']
    v[x0:x1, y0:y1, stone_top:] = C['plas']
    for _ in range(5):  # 漆喰のむら（塊単位＝罠 38）
        bx = int(rng.integers(x0, max(x0 + 1, x1 - 6)))
        bz = int(rng.integers(stone_top, HOUSE_WALL_H - 3))
        shade = C['plas_l'] if rng.random() < 0.5 else C['plas_d']
        block = v[bx:bx + 6, y0:y1, bz:bz + 3]
        block[block == C['plas']] = shade

    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        fx, fy = _house_face(x0, x1, y0, y1, side)
        #! 面の 1 つ内側（彫った目地の底になる所）。
        bx, by = fx, fy
        if side == 'n':
            by = slice(y0 + 1, y0 + 2)
        elif side == 's':
            by = slice(y1 - 2, y1 - 1)
        elif side == 'w':
            bx = slice(x0 + 1, x0 + 2)
        else:
            bx = slice(x1 - 2, x1 - 1)
        span = fx if side in ('n', 's') else fy
        lo, hi = span.start, span.stop
        #! 石の段と縦の継ぎ目は**彫る**（面を 0 にし、底を目地の色にする）。
        #! 色だけで線を引くと、AO と影の暗さと重なって黒い線になる（罠 44）。
        for z in range(plinth + course - 1, stone_top, course):
            v[fx, fy, z] = 0
            v[bx, by, z] = C['joint']
            #! 継ぎ目は段ごとに半枚ずらす（芋目地を避ける）。
            off = ((z - plinth) // course) % 2 * 5
            z0 = max(plinth, z - course + 1)
            for p in range(lo + off, hi, 10):
                if side in ('n', 's'):
                    v[p:p + 1, fy, z0:z] = 0
                    v[p:p + 1, by, z0:z] = C['joint']
                else:
                    v[fx, p:p + 1, z0:z] = 0
                    v[bx, p:p + 1, z0:z] = C['joint']
        # 漆喰と石の境の水切り（1 段の帯）。
        v[fx, fy, stone_top:stone_top + 2] = C['ash_l']

    #! 隅石（quoin）。**外に面した辺が 2 つある角のスライスだけ**に立てる。
    if (north or south) and (west or east):
        cx = x0 if west else x1 - 3
        cy = y0 if north else y1 - 3
        for z in range(plinth, HOUSE_WALL_H - 1, course):
            v[cx:cx + 3, y0:y1, z:z + course - 1] = C['ash_l'] if ((z // course) % 2) else C['ash']
            v[x0:x1, cy:cy + 3, z:z + course - 1] = C['ash_l'] if ((z // course) % 2) else C['ash']

    # 窓（南面だけ）。石のまぐさとアーチ。
    if south:
        wx = (x0 + x1) // 2 - 5
        wz = plinth + 8
        v[wx - 2:wx + 12, y1 - 2:y1, wz - 2:wz + 15] = C['ash_l']   # 石枠
        v[wx:wx + 10, y1 - 2:y1, wz:wz + 11] = C['glass']
        for k in range(4):                                          # アーチ（上を丸く）
            v[wx + k:wx + 10 - k, y1 - 2:y1, wz + 11 + k] = C['glass']
        v[wx:wx + 10, y1 - 2:y1, wz + 4:wz + 6] = C['glass_l']
    return [('main', v, (0, 0, 0))]


def house_roof(name):
    """寄棟屋根の 1 スライス。**外に面した辺へ向かって落ちる**（無ければ棟の平ら）。

    高さは「外に面した各辺までの距離」の最小値で決める。角のスライスでは 2 つの斜面が
    交わって隅棟（対角の稜線）になる。1 マスで軒から棟まで上がるので、2 マスの奥行きでも
    ちゃんと棟ができる。

    **葺きは板張り**（2026-08-09 に決めた:「屋根は板張りでムラがあり、ところどころ
    から草が生えているような風合いに」）。段は高さで切るので、どの斜面でも自然に
    **軒と平行な板の列**になる（斜面ごとに別の型を用意しなくてよい）。

    意匠つきの名前は別の葺き材へ振り分ける（テルモラ＝藁 / モリバント＝瓦）。
    """
    style = _split_style(name)[0]
    if style == 'tel':
        return _house_roof_thatch(name)
    if style in ('mor', 'koma'):  # koma はモリバントの絵の転送（house_wall の註記）
        return _house_roof_tile(name)
    if style == 'hai':
        #! 廃洋館の敷地の家も切石＋瓦（house_wall の註記と同じ判断）。
        return _house_roof_tile(name)
    if style in ('jin', 'ein'):
        return _house_roof_kaya(name)
    if style == 'ten':
        #! 人里と同じ茅葺きの色違い（上の壁の註記と同じ判断。杉皮の生成器は記録として残す）。
        return _house_roof_kaya(name)
    if style == 'hak':
        return _house_roof_kaya(name)  # 博麗神社の脇の小屋も同じ茅（壁の註記と同じ判断）
    #! moy（守矢神社）は**檜皮**（§4.2 の屋根材。天狗の里で作って記録に回してあった
    #! 杉皮の生成器を、ここで初めて使う——博麗の茅と守矢の檜皮が色と輪郭で分かれる）。
    if style == 'moy':
        return _house_roof_hiwada(name)
    #! hig（彼岸）の雑貨屋も**黒瓦**（§4.5 ⑤⑥ の黒瓦を町ぜんぶで通す）。
    if style in ('kyu', 'hig'):
        return _house_roof_kawara(name)
    #! git（偽天棚）は**石置き板葺き**（高山の風に飛ばないよう屋根石を並べる）。
    if style == 'git':
        return _house_roof_git(name)
    if style == 'myo':
        return _house_roof_myo(name)
    if style == 'kap':
        return _house_roof_tin(name)
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    top = HOUSE_ROOF_H
    v = np.zeros((V, V, top), np.uint8)

    #! 板 1 枚ぶんの色。**塊ごとに 1 色**（ボクセル単位に散らすと砂嵐＝罠 38）。
    plank = rng.choice([C['shin'], C['shin_l'], C['shin_d'], C['shin_g']],
                       size=(V // 4 + 1, V // 4 + 1, top // 3 + 1), p=[0.40, 0.24, 0.22, 0.14])
    height = np.zeros((V, V), np.int32)
    for x in range(V):
        for y in range(V):
            reach = []
            if north:
                reach.append((y + 0.5) / V)
            if south:
                reach.append((V - 0.5 - y) / V)
            if west:
                reach.append((x + 0.5) / V)
            if east:
                reach.append((V - 0.5 - x) / V)
            t = min(reach) if reach else 1.0
            h = int(round(HOUSE_EAVE + ((top - HOUSE_EAVE) * min(1.0, t))))
            h = max(1, min(top, h))
            height[x, y] = h
            for z in range(h):
                v[x, y, z] = C['shin_d'] if z < HOUSE_EAVE else plank[x // 4, y // 4, z // 3]
            #! 板の重なり（段の頭 1 列を暗くする）。軒と平行な線になり「葺いた」ように見える。
            if (h % 3) == 0:
                v[x, y, h - 1] = C['shin_d']
            if h >= top:
                v[x, y, h - 1] = C['ridge']  # 棟包み

    # 苔の染み。**天面にだけ**、塊で置く（見下ろすカメラでは天面が絵の大半＝罠 41）。
    for _ in range(int(rng.integers(3, 7))):
        cx, cy = int(rng.integers(0, V - 4)), int(rng.integers(0, V - 4))
        w, d = int(rng.integers(3, 8)), int(rng.integers(3, 8))
        shade = C['moss_d'] if rng.random() < 0.5 else C['moss']
        for x in range(cx, min(cx + w, V)):
            for y in range(cy, min(cy + d, V)):
                v[x, y, height[x, y] - 1] = shade
    # 板の隙間から生えた草。屋根の上へ 2 ボクセルだけ立てる（伸ばすと屋根が毛羽立つ）。
    for _ in range(int(rng.integers(3, 7))):
        cx, cy = int(rng.integers(1, V - 3)), int(rng.integers(1, V - 3))
        blade = C['turf'] if rng.random() < 0.5 else C['turf_d']
        for x in range(cx, cx + 2):
            for y in range(cy, cy + 2):
                base = height[x, y]
                for k in range(2):
                    if (base + k) < top:
                        v[x, y, base + k] = blade
    return [('main', v, (0, 0, 0))]


def _roof_field(north, south, west, east, eave, top, curve):
    """屋根の高さ場と「稜線か」の印を作る（意匠つきの屋根で共用）。

    `curve` が 1.0 なら平らな斜面（板張りと同じ）、0.5 なら軒で急に立ち上がって棟の
    近くで寝る**丸い**屋根（藁葺き）。稜線は「いちばん近い 2 辺までの距離がほぼ同じ」
    所——角のスライスに現れる**隅棟**である。棟（頂上）は高さで判る。
    """
    height = np.zeros((V, V), np.int32)
    hip = np.zeros((V, V), bool)
    for x in range(V):
        for y in range(V):
            reach = []
            if north:
                reach.append((y + 0.5) / V)
            if south:
                reach.append((V - 0.5 - y) / V)
            if west:
                reach.append((x + 0.5) / V)
            if east:
                reach.append((V - 0.5 - x) / V)
            if reach:
                near = sorted(reach)
                t = near[0]
                hip[x, y] = (len(near) >= 2) and ((near[1] - near[0]) < (1.4 / V))
            else:
                t = 1.0
            t = min(1.0, t) ** curve
            h = int(round(eave + ((top - eave) * t)))
            height[x, y] = max(1, min(top, h))
    return height, hip


SHOJI_X0, SHOJI_X1 = 3, 29   # 障子 1 面の左右（壁のマスの中）
SHOJI_PITCH = 4              # 桟の間隔（ボクセル）


def _shoji_paper(rows):
    """障子の割り付け。**戻りは (x, z) の 2 値** — True = 紙、False = 桟か框。

    参考にした実物（2026-08-18）は「**細かい格子に紙**」で、白い面が 3 枚並ぶ形ではない。
    中ほどに 1 本太い桟（腰の切り替え）が通り、上下で格子が分かれる。

    **壁（`_house_wall_tsuchi`）と灯り（`_house_light_shoji`）が同じ割り付けを使う。**
    ずれると格子が二重に見える——灯りは壁の面より手前に置かれるので、
    こちらが桟を持っていないと壁の格子を塗り潰してしまう。
    """
    paper = np.zeros((V, rows), bool)
    paper[SHOJI_X0 + 1:SHOJI_X1 - 1, 1:rows - 1] = True
    for x in range(SHOJI_X0 + SHOJI_PITCH, SHOJI_X1 - 1, SHOJI_PITCH):
        paper[x, :] = False
    for k in range(SHOJI_PITCH, rows - 1, SHOJI_PITCH):
        paper[:, k] = False
    paper[:, rows // 2] = False  # 中桟（腰の切り替え。実物は上下で格子が分かれる）
    return paper


def _house_wall_tsuchi(name):
    """**人里の壁**（2026-08-18） — 下は焼杉の腰板、上は土壁、柱と貫は黒。南面に障子。

    §4.1 の意匠手がかりに沿う——「壁は焼杉の焦茶＋土壁の生成りの 2 トーン、柱を黒く立てると
    64px でも和風に読める」「障子の白を必ず 1 面入れる」。

    **テルモラ（木骨漆喰）との差は線の向きである。** あちらは筋交いの斜め材が目立つが、
    和風の真壁は**貫（ぬき）の水平線と柱の縦線**でできている。**斜めを 1 本も入れない**のが要点で、
    ここを混ぜると「木骨漆喰の色を変えただけ」に見える。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    v = np.zeros((V, V, HOUSE_WALL_H), np.uint8)

    # 土台（マスいっぱい。石場建ての石）。上に載る躯体だけを引っ込める。
    v[:, :, 0:HOUSE_PLINTH] = C['wall_d']
    v[:, :, HOUSE_PLINTH - 1] = C['wall']

    #! 腰板（焼杉）と土壁の境。**低めに取る**——腰板を高くするとライブラリに見える。
    koshi = HOUSE_PLINTH + 9
    v[:, :, HOUSE_PLINTH:koshi] = C['yaki']
    v[:, :, koshi:HOUSE_WALL_H] = C['tsuchi']
    #! 土壁のむら。**塊で置く**（ボクセル単位に散らすと砂嵐＝罠 38）。
    for _ in range(int(rng.integers(3, 6))):
        cx = int(rng.integers(0, V - 6))
        cz = int(rng.integers(koshi, HOUSE_WALL_H - 4))
        v[cx:cx + int(rng.integers(4, 9)), :, cz:cz + int(rng.integers(2, 5))] = C['tsuchi_d']

    #! **外に面した辺は躯体を 2 ボクセル引っ込める**（基の壁の「上に載る躯体だけを引っ込める」と
    #! 同じ理由）。マスいっぱいに詰めると、**壁の前に置く別体が壁の中に埋まって 1 画素も見えない**
    #! ——灯り（`house_light`）と玄関（`house_entrance`）がそれで消えた（2026-08-18 に実際に踏んだ）。
    inset = 2
    if north:
        v[:, 0:inset, HOUSE_PLINTH:] = 0
    if south:
        v[:, V - inset:V, HOUSE_PLINTH:] = 0
    if west:
        v[0:inset, :, HOUSE_PLINTH:] = 0
    if east:
        v[V - inset:V, :, HOUSE_PLINTH:] = 0

    #! 引っ込めたぶん、飾りを描く面もずれる（南なら y = V-1-inset）。
    for dirn, on in (('n', north), ('s', south), ('w', west), ('e', east)):
        if not on:
            continue
        ns = dirn in ('n', 's')
        at_face = inset if dirn in ('n', 'w') else V - 1 - inset
        #! 柱（隅と中ほど）。**縦の黒い線**が和風の第一印。
        for at in (0, 1, V // 2 - 1, V // 2, V - 2, V - 1):
            if ns:
                v[at, at_face, HOUSE_PLINTH:HOUSE_WALL_H] = C['yaki']
            else:
                v[at_face, at, HOUSE_PLINTH:HOUSE_WALL_H] = C['yaki']
        #! 貫（水平材）。腰板の頭と軒下の 2 本だけ。**3 本以上入れると格子に見える**（罠 71 の形）。
        for z in (koshi - 1, HOUSE_WALL_H - 3):
            if ns:
                v[:, at_face, z:z + 2] = C['yaki_l']
            else:
                v[at_face, :, z:z + 2] = C['yaki_l']

    #! **障子は南面だけ**（見下ろすカメラの正面。北面は建物自身に隠れて 1 画素も見えない）。
    #! **深い軒に食われないよう腰板のすぐ上へ下げる**（2026-08-18 に気づいた:「障子が見えない」）。
    if south:
        z0 = koshi
        z1 = z0 + 13
        paper = _shoji_paper(z1 - z0)
        yface = V - 1 - inset
        for x in range(SHOJI_X0, SHOJI_X1):
            for k in range(z1 - z0):
                v[x, yface, z0 + k] = C['shoji'] if paper[x, k] else C['yaki']
    return [('main', v, (0, 0, 0))]


def _house_wall_shinkabe(name):
    """**天狗の里の壁**（2026-08-18） — 白漆喰の真壁に濃い柱。南面は連子窓。

    §4.4 の意匠手がかり「壁は白漆喰＋濃い柱の真壁——3 者の中で唯一の**白い建物**に
    すると識別が立つ」。人里（生成りの土壁＋焼杉の腰板）との差は**白さと腰板の無さ**。
    骨組みは同じ和風の文法（柱の縦線＋貫の水平線。**斜めを 1 本も入れない**）に載せる。

    南面の窓は**障子ではなく連子（縦格子）**——役所と新聞社の並び（求聞史紀の
    職能の縦社会）なので、紙の白ではなく木の格子で言う。障子は人里の印に取ってある。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    v = np.zeros((V, V, HOUSE_WALL_H), np.uint8)

    # 土台（切石。山上なので石場より整った石积み）。上に載る躯体だけを引っ込める。
    v[:, :, 0:HOUSE_PLINTH] = C['wall_d']
    v[:, :, HOUSE_PLINTH - 1] = C['wall']

    #! 白漆喰。むらは**わずかに**（塗り直しの行き届いた官庁街。人里より綺麗に保つ）。
    v[:, :, HOUSE_PLINTH:HOUSE_WALL_H] = C['shira']
    for _ in range(int(rng.integers(2, 4))):
        cx = int(rng.integers(0, V - 6))
        cz = int(rng.integers(HOUSE_PLINTH + 2, HOUSE_WALL_H - 4))
        v[cx:cx + int(rng.integers(4, 8)), :, cz:cz + int(rng.integers(1, 3))] = C['shira_d']

    #! 外に面した辺は躯体を 2 ボクセル引っ込める（人里と同じ罠——詰めると別体が埋まる）。
    inset = 2
    if north:
        v[:, 0:inset, HOUSE_PLINTH:] = 0
    if south:
        v[:, V - inset:V, HOUSE_PLINTH:] = 0
    if west:
        v[0:inset, :, HOUSE_PLINTH:] = 0
    if east:
        v[V - inset:V, :, HOUSE_PLINTH:] = 0

    for dirn, on in (('n', north), ('s', south), ('w', west), ('e', east)):
        if not on:
            continue
        ns = dirn in ('n', 's')
        at_face = inset if dirn in ('n', 'w') else V - 1 - inset
        #! 柱。**白地に黒に近い焦茶の縦線**（真壁の第一印。白との明度差が最大の武器）。
        for at in (0, 1, V // 2 - 1, V // 2, V - 2, V - 1):
            if ns:
                v[at, at_face, HOUSE_PLINTH:HOUSE_WALL_H] = C['timber_d']
            else:
                v[at_face, at, HOUSE_PLINTH:HOUSE_WALL_H] = C['timber_d']
        #! 貫（水平材）2 本。人里より 1 段低い位置に足元の雨押えも入れて「役所」の硬さを出す。
        for z in (HOUSE_PLINTH + 1, HOUSE_PLINTH + 8, HOUSE_WALL_H - 3):
            if ns:
                v[:, at_face, z:z + 2] = C['timber_d']
            else:
                v[at_face, :, z:z + 2] = C['timber_d']

    #! **連子窓は南面だけ**（見下ろすカメラの正面）。窓の奥を陰にして縦の桟を刻む。
    if south:
        z0 = HOUSE_PLINTH + 12
        z1 = z0 + 11
        yface = V - 1 - inset
        v[7:25, yface, z0:z1] = C['dark']
        for x in range(7, 25, 3):
            v[x, yface, z0:z1] = C['timber']
        v[6:26, yface, z0 - 1:z0] = C['timber_d']   # 窓台
        v[6:26, yface, z1:z1 + 1] = C['timber_d']   # まぐさ
    return [('main', v, (0, 0, 0))]


# ---- 旧地獄街道の提灯と格子の割り付け（壁と灯りで共有する。障子の SHOJI_* と同じ理由）----
KYU_LANT_XS = (7, 20)   # 提灯の左端 x（幅 5 の 2 張り。南向きスライスが並ぶと横一列が続く）
KYU_LANT_W = 5
KYU_LANT_Z0, KYU_LANT_Z1 = 22, 30   # 紙の胴（壁の z）。下に口輪・上に蓋が 1 段ずつ付く
KYU_KOSHI_X0, KYU_KOSHI_X1 = 5, 27  # 格子窓の左右
KYU_KOSHI_Z0, KYU_KOSHI_Z1 = 8, 18  # 格子窓の上下（壁の z）
KYU_KOSHI_PITCH = 3                 # 桟の間隔（1 本置き＝2 ボクセル空き）


def _house_wall_shitami(name):
    """**旧地獄街道の壁**（2026-08-18） — 黒〜焦茶の下見板。南面は紅殻格子と提灯の列。

    §4.4 ②「壁は黒〜焦茶の下見板——**白漆喰は使わない**（天狗の里との一番効く差）」。
    下見板は横板の重ね張りなので、外に面した面に **4 段ごとの横の影線**を刻む
    （人里の焼杉は縦張りの腰板・天狗は白面に黒柱——3 町は板の向きと明度で分かれる）。

    §4.4 ③「提灯の列が最重要の印」は**壁に焼き込む**——南向きのスライスが横に並べば
    軒下の横一列がひとりでに続く（町屋の連続はスライスの連続そのもの）。夜の灯は
    別体（`_house_light_chochin`）が同じ割り付けで 1 ボクセル手前に重なる。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    v = np.zeros((V, V, HOUSE_WALL_H), np.uint8)

    # 土台（マスいっぱい＝罠 5）。上に載る躯体だけを引っ込める。
    v[:, :, 0:HOUSE_PLINTH] = C['wall_d']
    v[:, :, HOUSE_PLINTH - 1] = C['wall']

    v[:, :, HOUSE_PLINTH:HOUSE_WALL_H] = C['shitami']

    #! 外に面した辺は躯体を 2 ボクセル引っ込める（人里で踏んだ罠——詰めると別体が埋まる）。
    inset = 2
    if north:
        v[:, 0:inset, HOUSE_PLINTH:] = 0
    if south:
        v[:, V - inset:V, HOUSE_PLINTH:] = 0
    if west:
        v[0:inset, :, HOUSE_PLINTH:] = 0
    if east:
        v[V - inset:V, :, HOUSE_PLINTH:] = 0

    #! 下見板の帯の色。**帯ごとに 1 色**（罠 38 を帯単位で守る）。面どうしで揃える
    #! ——板は建物を一周するので、面ごとに引き直すと角で色が割れる。
    shades = [C['shitami'] if rng.random() < 0.72 else C['shitami_l']
              for _ in range((HOUSE_WALL_H // 4) + 1)]
    for dirn, on in (('n', north), ('s', south), ('w', west), ('e', east)):
        if not on:
            continue
        ns = dirn in ('n', 's')
        at_face = inset if dirn in ('n', 'w') else V - 1 - inset
        for z in range(HOUSE_PLINTH, HOUSE_WALL_H):
            row = (z - HOUSE_PLINTH) % 4
            shade = C['shitami_d'] if row == 3 else shades[(z - HOUSE_PLINTH) // 4]
            if ns:
                v[:, at_face, z] = shade
            else:
                v[at_face, :, z] = shade
        #! 隅の押縁と軒下の胴差し。黒い面の輪郭をさらに暗い炭色で締める。
        for at in (0, 1, V - 2, V - 1):
            if ns:
                v[at, at_face, HOUSE_PLINTH:HOUSE_WALL_H] = C['char']
            else:
                v[at_face, at, HOUSE_PLINTH:HOUSE_WALL_H] = C['char']
        if ns:
            v[:, at_face, HOUSE_WALL_H - 2:HOUSE_WALL_H] = C['char']
        else:
            v[at_face, :, HOUSE_WALL_H - 2:HOUSE_WALL_H] = C['char']

    #! **紅殻の格子窓は南面だけ**（カメラの正面）。奥を陰にして縦の桟を刻む。
    #! 天狗の連子（素木）との差は桟の色——歓楽街の窓は紅殻の赤茶で温める。
    if south:
        yface = V - 1 - inset
        v[KYU_KOSHI_X0:KYU_KOSHI_X1, yface, KYU_KOSHI_Z0:KYU_KOSHI_Z1] = C['dark']
        for x in range(KYU_KOSHI_X0 + 1, KYU_KOSHI_X1, KYU_KOSHI_PITCH):
            v[x, yface, KYU_KOSHI_Z0:KYU_KOSHI_Z1] = C['koshi']
        v[KYU_KOSHI_X0 - 1:KYU_KOSHI_X1 + 1, yface, KYU_KOSHI_Z0 - 1:KYU_KOSHI_Z0] = C['char']
        v[KYU_KOSHI_X0 - 1:KYU_KOSHI_X1 + 1, yface, KYU_KOSHI_Z1:KYU_KOSHI_Z1 + 1] = C['char']

        #! 提灯の列（§4.4 ③）。躯体の手前の余白（y 30）に紙、蓋と口輪は炭色。
        #! 紙は昼から橙（赤提灯は昼も赤い）。夜の灯は別体が y 31 へ重なる。
        for lx in KYU_LANT_XS:
            v[lx:lx + KYU_LANT_W, 30:31, KYU_LANT_Z0:KYU_LANT_Z1] = C['chochin']
            v[lx + 1:lx + KYU_LANT_W - 1, 30:31, KYU_LANT_Z0 + 2:KYU_LANT_Z1 - 2] = C['chochin_l']
            v[lx:lx + KYU_LANT_W, 30:31, KYU_LANT_Z0 - 1:KYU_LANT_Z0] = C['char']
            v[lx:lx + KYU_LANT_W, 30:31, KYU_LANT_Z1:KYU_LANT_Z1 + 1] = C['char']
            v[lx + 2, 30:31, KYU_LANT_Z1 + 1:KYU_LANT_Z1 + 3] = C['char']
    return [('main', v, (0, 0, 0))]


def _house_roof_kaya(name):
    """**人里の屋根**（2026-08-18） — 分厚い茅葺き。軒を深く、棟は竹で押さえる。

    テルモラの藁葺きとの差は 3 つ:
    1. 色が**枯れて灰がかる**（`kaya` 系。あちらは葺きたての黄）
    2. **軒先がさらに厚い**（9 ボクセル。§4.1「軒が深い」）
    3. **棟に草を載せない**——芝棟はテルモラの癖で、人里は竹と丸太で押さえた**暗い筋**にする
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    eave, top = 9, 38
    v = np.zeros((V, V, top), np.uint8)
    height, hip = _roof_field(north, south, west, east, eave, top, curve=0.62)
    #! 稜線と棟の飾りは**斜面のあるスライスだけ**（`mid` は平らなので天面が丸ごと染まる）。
    ridged = bool(north or south or west or east)

    #! 茅束。**塊ごとに 1 色**（罠 38）。2×2 にして「束ねた」粒を出す。
    bundle = rng.choice([C['kaya'], C['kaya_l'], C['kaya_d'], C['kaya_g']],
                        size=(V // 2 + 1, V // 2 + 1), p=[0.44, 0.22, 0.22, 0.12])
    for x in range(V):
        for y in range(V):
            h = height[x, y]
            shade = bundle[x // 2, y // 2]
            v[x, y, 0:h] = C['kaya_d']  # 軒の断面（切り口は影になって暗い）
            if h > eave:
                v[x, y, eave:h] = shade
            v[x, y, h - 1] = shade
            if ridged and (hip[x, y] or (h >= top)):
                v[x, y, h - 1] = C['kaya_l']  # 隅棟は茅を寄せて留めるので明るい筋になる
    #! 煤と苔（天面にだけ、塊で＝罠 41）。囲炉裏の煙で棟の近くが黒ずむ。
    for _ in range(int(rng.integers(3, 7))):
        cx, cy = int(rng.integers(0, V - 4)), int(rng.integers(0, V - 4))
        w, d = int(rng.integers(3, 8)), int(rng.integers(3, 8))
        shade = C['kaya_g'] if rng.random() < 0.55 else C['moss_d']
        for x in range(cx, min(cx + w, V)):
            for y in range(cy, min(cy + d, V)):
                v[x, y, height[x, y] - 1] = shade
    #! 棟押さえ（竹）。**斜面のあるスライスだけ**——平らな所に載せると屋根一面が筋になる。
    if ridged:
        for x in range(V):
            for y in range(V):
                if height[x, y] >= top:
                    v[x, y, top - 1] = C['mune']
    return [('main', v, (0, 0, 0))]


def _house_roof_hiwada(name):
    """**天狗の里の屋根**（2026-08-18） — 杉皮葺き。**反りの無い深い軒**の墨灰茶。

    §4.4「屋根は反りの無い深い軒の入母屋／寄棟、檜皮・杉皮の墨灰茶。3 軒並べると
    **役所の列**に読める」。9 スライスは寄棟しか組めないので、**反りの無さ**は
    `curve=1.0`（直線勾配）で、**深い軒**は軒先の厚み 7 で、材は暗い色で言う。
    茅（人里。丸い輪郭）とも瓦（モリバント。明るい棟）とも輪郭と明度で分かれる。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    eave, top = 7, 30
    v = np.zeros((V, V, top), np.uint8)
    height, hip = _roof_field(north, south, west, east, eave, top, curve=1.0)
    ridged = bool(north or south or west or east)   # 棟の飾りは斜面のあるスライスだけ（罠は茅と同じ）

    #! 杉皮の帯。塊ごとに 1 色（罠 38）。**軒と平行な暗い筋**を 3 段ごとに入れると
    #! 「重ねて葺いた」向きが遠目でも読める（瓦の段と同じ理屈で、色だけ暗い）。
    slab = rng.choice([C['hiwada'], C['hiwada_l'], C['hiwada_g']],
                      size=(V // 4 + 1, V // 4 + 1), p=[0.55, 0.25, 0.20])
    for x in range(V):
        for y in range(V):
            h = height[x, y]
            shade = slab[x // 4, y // 4]
            v[x, y, 0:h] = C['hiwada_d']   # 軒の断面（深い軒の厚みがここで読める）
            if h > eave:
                v[x, y, eave:h] = shade
            v[x, y, h - 1] = shade
            if (h % 3) == 0:
                v[x, y, h - 1] = C['hiwada_d']
            if ridged and (hip[x, y] or (h >= top)):
                v[x, y, h - 1] = C['iron']   # 箱棟。黒い鉄気の色で締める（白い壁との対比）
    return [('main', v, (0, 0, 0))]


def _house_roof_kawara(name, shades=None):
    """**旧地獄街道の屋根**（2026-08-18） — 黒瓦。低く葺いて軒と平行な段を刻む。

    §4.4 ①「屋根は町屋の切妻・平入りが横に連続（**低く長い**。瓦は黒）」。9 スライスは
    寄棟しか組めない（§3.5）ので、**低さ**（top 26。茅 38・杉皮 30 より低い）と
    **軒と平行な瓦の段**で町屋の横長を言う。モリバントの赤瓦と同じ文法で色だけ
    藍黒に振り、棟と隅棟を**いぶし銀**に光らせる——黒い面は頂の照りで初めて瓦に読める。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    eave, top = 6, 26
    v = np.zeros((V, V, top), np.uint8)
    height, hip = _roof_field(north, south, west, east, eave, top, curve=1.0)
    ridged = bool(north or south or west or east)   # 棟の飾りは斜面のあるスライスだけ（罠は茅と同じ）

    #! 瓦の塊。塊ごとに 1 色（罠 38）。
    #! 色は差し替えられる（デザイン10。命蓮寺の宿坊は**灰の瓦**）。
    #! **既定は旧地獄街道の黒瓦のまま**なので、あちらの絵は 1 ボクセルも動かない。
    base, light, dark, glow = shades or (C['kawara'], C['kawara_l'], C['kawara_d'], C['kawara_g'])
    slab = rng.choice([base, light, dark],
                      size=(V // 4 + 1, V // 4 + 1, top // 3 + 1), p=[0.56, 0.20, 0.24])
    for x in range(V):
        for y in range(V):
            h = height[x, y]
            for z in range(h):
                v[x, y, z] = dark if z < eave else slab[x // 4, y // 4, z // 3]
            #! 段の頭を 1 段暗く。軒と平行な線が「瓦を重ねた」向きに読める。
            if (h % 3) == 0:
                v[x, y, h - 1] = dark
            if ridged and (hip[x, y] or (h >= top)):
                v[x, y, h - 1] = glow   # 棟と隅棟のいぶし銀
    return [('main', v, (0, 0, 0))]


def _house_roof_thatch(name):
    """**テルモラの屋根** — 厚い藁葺き。棟には草を載せる。

    板張りとの違いは**輪郭**である。軒で急に立ち上がって棟の近くで寝る（`curve=0.55`）
    ので、同じ 1 マスでも「分厚くて丸い」影が出る。軒先も厚くとる（7 ボクセル＝板張りの
    ほぼ倍）——見下ろすカメラでは軒の断面が屋根の縁として読めるので、ここが薄いと
    葺き材が何であっても板に見える。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    eave, top = 7, 36
    v = np.zeros((V, V, top), np.uint8)
    height, hip = _roof_field(north, south, west, east, eave, top, curve=0.55)
    #! 稜線の飾りは**斜面のあるスライスだけ**（`mid` は屋根の平らな所で、頂上が面いっぱいに
    #! 広がる＝天面が丸ごと棟の色になる。瓦のほうはこれで**白い平屋根**が出た）。
    ridged = bool(north or south or west or east)

    #! 藁束。**塊ごとに 1 色**（罠 38）。板より細かい 2×2 にして「束ねた」粒を出す。
    bundle = rng.choice([C['straw'], C['straw_l'], C['straw_d'], C['straw_g']],
                        size=(V // 2 + 1, V // 2 + 1), p=[0.42, 0.24, 0.22, 0.12])
    for x in range(V):
        for y in range(V):
            h = height[x, y]
            shade = bundle[x // 2, y // 2]
            v[x, y, 0:h] = C['straw_d']          # 軒の断面（切り口は影になって暗い）
            if h > eave:
                v[x, y, eave:h] = shade
            v[x, y, h - 1] = shade
            if ridged and (hip[x, y] or (h >= top)):
                v[x, y, h - 1] = C['straw_l']    # 稜線は藁を寄せて留めるので明るい筋になる
    # 苔と古びた染み（天面にだけ、塊で＝罠 41）。
    for _ in range(int(rng.integers(3, 7))):
        cx, cy = int(rng.integers(0, V - 4)), int(rng.integers(0, V - 4))
        w, d = int(rng.integers(3, 8)), int(rng.integers(3, 8))
        shade = C['moss_d'] if rng.random() < 0.45 else C['straw_g']
        for x in range(cx, min(cx + w, V)):
            for y in range(cy, min(cy + d, V)):
                v[x, y, height[x, y] - 1] = shade
    #! 棟に載せた草（芝棟）。**斜面のあるスライスだけ**に載せる。
    #! `mid`（外に面した辺が無い＝屋根の平らな部分）にも載せた版は、広い建物の屋根が
    #! **一面の芝生**になった（実機の絵で気づいた）。斜面があるスライスでは「頂上」は
    #! 稜線の 1 列にしかならないので、そこだけが草の筋になる。
    if north or south or west or east:
        for x in range(V):
            for y in range(V):
                if height[x, y] >= top:
                    v[x, y, top - 1] = C['turf'] if ((x + y) % 5) else C['turf_d']
    return [('main', v, (0, 0, 0))]


def _house_roof_tile(name):
    """**モリバントの屋根** — 瓦。段は軒と平行、棟と隅棟は漆喰で塗り固める。

    見下ろすカメラで瓦を瓦として読ませているのは**段の線**と**明るい棟**の 2 つで、
    1 枚 1 枚の丸みではない（32 ボクセルのマスでは丸瓦 1 本が 2 ボクセルにしかならず、
    刻んでも砂嵐にしかならない＝罠 38）。段は高さで切るのでどの斜面でも水平に通る。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    eave, top = 3, 28
    v = np.zeros((V, V, top), np.uint8)
    height, hip = _roof_field(north, south, west, east, eave, top, curve=1.0)
    ridged = bool(north or south or west or east)   # 藁葺きと同じ理由（棟は稜線だけ）

    #! 瓦の色は塊ごと。ときどき**青みの列**（葺き替えた所）を混ぜる。
    slab = rng.choice([C['tile'], C['tile_l'], C['tile_d'], C['tile_b']],
                      size=(V // 4 + 1, V // 4 + 1, top // 3 + 1), p=[0.44, 0.24, 0.22, 0.10])
    for x in range(V):
        for y in range(V):
            h = height[x, y]
            for z in range(h):
                v[x, y, z] = C['tile_d'] if z < eave else slab[x // 4, y // 4, z // 3]
            #! 段の頭を 1 列暗くする。**軒と平行な線**になり「葺いた」ように見える。
            if (h % 3) == 0:
                v[x, y, h - 1] = C['tile_d']
            if ridged and (hip[x, y] or (h >= top)):
                v[x, y, h - 1] = C['ash_l']   # 棟・隅棟は漆喰で塗り固めた白い筋
    return [('main', v, (0, 0, 0))]


def house_light(name):
    """窓の灯り（P7 の宿題「地上でブルームが 1 画素も効かない」への答え）。

    **自発光はインスタンス単位**なので、壁と一体にすると漆喰まで光る（罠 39）。
    別体にして、置く側が夜の度合いで `emissive` を上げる。接地しない（footprint は空）。
    """
    if _split_style(name)[0] in ('jin', 'ten', 'hak'):
        return _house_light_shoji(name)  # ten も障子（壁を人里の造りに揃えた＝割り付け共有の罠）
    if _split_style(name)[0] == 'kyu':
        return _house_light_chochin(name)
    v = np.zeros((V, V, 13), np.uint8)
    v[11:21, 29:32, 1:13] = C['lit']
    return [('main', v, (0, 0, 0))]


def gate_great_jin(name):
    """**人里の大門**（2026-08-18 に決めた）。南側の土塀に組み込む**閉じた**棟門。

    §4.1 の「町の入口に囲壁＋大門を必ず立てる」に応える。当初は塀の切れ目に立てて
    くぐらせる案だったが、**「開いて通過させる必要はないので、閉じた大門としてつくり、
    南側の壁の一部に組み込んで」**（2026-08-18 に決めた）に従い、二枚の板戸を
    閉めた姿で焼く。実際の出入りは塀の切れ目（街道）が受け持つ。
    置く側は `TownStyle::great_gate` が塀のマス 1 つをこれに差し替える。

    三月精の版に寄せて**朱は使わない**——里の門は素木と瓦で、朱塗りは神社の記号にしてある
    （§4.2 の描き分け）。高さは塀（1.9 マス）より頭ひとつ高い 2.6 マス。
    隣に土塀（マスいっぱいの塊）が続くので、**柱はマスの端まで広げて**継ぎ目に隙間を作らない。
    """
    height = 84
    v = np.zeros((V, V, height), np.uint8)
    #! 敷石（たたき）。塀のマスを差し替えるので、地面はこの板が自分で持つ。
    v[:, :, 0:3] = C['wall_d']
    v[:, :, 2] = C['wall']
    #! 太い柱 2 本（礎石つき）。塀より太くしないと「塀の一部」に見える。
    for x0, x1 in ((0, 8), (24, 32)):
        v[x0:x1, 11:21, 0:66] = C['timber']
        v[x0:x1, 20, 3:66] = C['timber_l']
        v[x0:x1, 10:22, 0:4] = C['wall']
    #! **閉じた二枚戸**。縦板の目地・合わせ目・貫 2 段に鋲。柱の面（y 20）より奥に収める
    #! （門は閉まっていて、実際の通行は塀の切れ目が受け持つ）。
    v[8:24, 13:19, 3:66] = C['oak']
    for x in range(8, 24, 4):
        v[x, 18, 3:62] = C['timber_d']  # 縦板の目地
    v[15:17, 18, 3:66] = C['timber_d']  # 二枚戸の合わせ目
    for z0 in (22, 46):
        v[8:24, 18:20, z0:z0 + 4] = C['timber']  # 貫（横帯）
        for x in (10, 13, 18, 21):
            v[x, 19, z0 + 1:z0 + 3] = C['iron']  # 鋲
    #! 冠木（上の横木）。柱より前後に張り出す。
    v[0:32, 9:23, 66:73] = C['oak']
    v[0:32, 22, 66:73] = C['oak_l']
    #! 切妻の瓦屋根。**棟は塀の並びと同じ東西に通す**（南のカメラには軒の面が正面になる）。
    for i in range(6):
        y0 = 7 + i * 2
        v[0:32, y0:y0 + 2, 73 + i:76 + i] = C['wall_d']
        v[0:32, y0 + 1, 75 + i] = C['wall']
    for i in range(6):
        y1 = 25 - i * 2
        v[0:32, y1:y1 + 2, 73 + i:76 + i] = C['wall_d']
        v[0:32, y1, 75 + i] = C['wall']
    v[0:32, 15:17, 79:82] = C['mrl']  # 大棟
    return [('main', v, (0, 0, 0))]


def gate_great_koma(name):
    """**紅魔館の大門**（2026-08-18 に決めた「bの横と、左側の塀の終端には人里の
    大門を洋風にした門を」）。

    人里の大門（棟門）の構図——柱 2 本・閉じた扉・上部の渡し——で、材を洋風にする:
    レンガの門柱・鉄の格子扉・柱間を渡す鉄の弧。瓦屋根は載せない（洋門の記号は
    屋根ではなく鉄のアーチと槍先）。鉄柵の塀（3 マス）より頭ひとつ高い 3.4 マス。
    人里と同じく**閉じた門**で、実際の出入りは塀の切れ目（参道の開口）が受け持つ。
    """
    rng = rng_for(name)
    height = 108
    v = np.zeros((V, V, height), np.uint8)
    #! 敷石。塀のマスを差し替えるので、地面はこの板が自分で持つ。
    v[:, :, 0:3] = C['wall_d']
    v[:, :, 2] = C['wall']
    #! レンガの門柱 2 本。4 ボクセルの段で積み、笠石と鉄の飾りを頂に載せる。
    for x0, x1 in ((0, 9), (23, 32)):
        for z in range(3, 86):
            shade = C['tile'] if ((z // 4) % 2) else rng.choice(
                [C['roof_r'], C['tile'], C['drape']], p=[0.34, 0.44, 0.22])
            v[x0:x1, 10:22, z] = shade
        v[x0 - 0:x1, 9:23, 86:90] = C['wall_l']            # 笠石
        cx = (x0 + x1) // 2
        v[cx - 2:cx + 2, 14:18, 90:97] = C['iron']         # 頂の飾り（尖り）
        v[cx - 1:cx + 1, 15:17, 97:100] = C['iron_l']
    #! 鉄の格子扉（閉）。縦棒ピッチ 3・**太さ 2**（1 だと遠景で透けて枠だけに見えた）。
    #! 上端は中央ほど高い弧＋穂先。
    for x in range(9, 23):
        arch = int(round(6.0 * math.sin(math.pi * (x - 9) / 13.0)))
        top = 58 + arch
        if (x % 3) == 0:
            v[x:x + 2, 15:17, 3:top] = C['iron_l']
            v[x:x + 2, 15, top:top + 3] = C['steel_d']
    for z0 in (16, 40):
        v[9:23, 15:17, z0:z0 + 2] = C['iron']              # 横貫
    v[15:17, 14:18, 3:64] = C['iron']                      # 中央の合わせ（太い）
    v[15:17, 15:17, 64:68] = C['iron_l']
    #! 柱間の鉄の弧（上部の飾り）。梁 1 本＋中央の盛り上がり。
    v[6:26, 15:17, 82:85] = C['iron']
    for x in range(9, 23):
        rise = int(round(7.0 * math.sin(math.pi * (x - 9) / 13.0)))
        if rise > 0:
            v[x, 15:17, 84:84 + rise] = C['iron']
    return [('main', v, (0, 0, 0))]


# ---- 紅魔館の本館（デザイン4・2026-08-18「本館はベースは巨大な三階建ての赤レンガ作りの
#      洋館。窓は少なめ。三階の屋根はひさしが出ている」）----
#
# 屋敷（Manor）は敷地の家と同じ 9 スライスの枠で建てるが、**壁は 3 階を一体で焼く**
# （高さ 102 = 34×3。積む仕掛けを増やさず、窓と見切り帯を階をまたいで設計できる）。
# 屋根はひさしがマスの外へ 4 ボクセル張り出す（型を 40×40 にして origin で中央へ寄せる）。

#! 3 階で **6 ブロック**（2026-08-18 に気づいた デザイン4:「紅魔館の３階建ては
#! ３ブロックの高さではなく、６ブロックで」——初版の 34×3=102 は低かった）。1 階 2 マス。
MANOR_WALL_H = 192


def _manor_brick_face(v, rng, fx, fy, span_lo, span_hi, z0, z1, vertical):
    """レンガの外面（4 ボクセル段・目地は貼り残し彫り）。`vertical`=面が y に走るか。"""
    for z in range(z0 + 3, z1, 4):
        off = ((z // 4) % 2) * 4
        for p in range(span_lo + off, span_hi, 8):
            a0, a1 = p, min(p + 7, span_hi)
            if a0 >= a1:
                continue
            shade = rng.choice([C['tile'], C['roof_r'], C['drape']], p=[0.5, 0.28, 0.22])
            if vertical:
                v[fx, a0:a1, max(z0, z - 3):z] = shade
                v[fx, a0:a1, z] = C['joint']
            else:
                v[a0:a1, fy, max(z0, z - 3):z] = shade
                v[a0:a1, fy, z] = C['joint']


def manor_wall_koma(name):
    """紅魔館の本館の壁 1 マス（3 階一体・赤レンガ・窓は少なめ）。

    1 階は石の基部（窓なし＝「窓が少ない」の担保）、2〜3 階はレンガ。**変種で窓の数を
    振る**（_01/_02 = 窓なし・_03 = 2 階に 1 つ・_04 = 2〜3 階に 2 つ。南面のみ）——
    スライスの種は名前で固定なので、変種にしないと「全マスに同じ窓」か「ゼロ」の二択に
    なる（実測で窓ゼロに固定された）。置く側がマスの種で 1 枚選ぶ。
    """
    base = _split_style(name)[1]  # manor_wall_<slice>_<nn>
    parts = base.split('_')
    key = parts[2]
    variant = int(parts[3]) if ((len(parts) > 3) and parts[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    v = np.zeros((V, V, MANOR_WALL_H), np.uint8)
    v[:, :, :] = C['tile']
    v[:, :, 0:8] = C['wall_d']  # 土台（マスいっぱい。罠 5）
    #! 1 階の腰までは石（0..58）——洋館の基部。窓を置かないことが「窓少なめ」を作る。
    v[:, :, 8:58] = C['wall']
    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        if side == 'n':
            fx, fy, vert = slice(0, V), 0, False
        elif side == 's':
            fx, fy, vert = slice(0, V), V - 1, False
        elif side == 'w':
            fx, fy, vert = 0, slice(0, V), True
        else:
            fx, fy, vert = V - 1, slice(0, V), True
        #! 石の基部の段（外面だけ目地の彫り色）。
        for z in range(14, 58, 8):
            v[fx, fy, z] = C['joint']
        #! レンガの外面（2〜3 階）。
        if vert:
            _manor_brick_face(v, rng, fx, None, 0, V, 64, MANOR_WALL_H, True)
        else:
            _manor_brick_face(v, rng, None, fy, 0, V, 64, MANOR_WALL_H, False)
        #! 階の見切り帯（白石）。1F|2F = 58..64、2F|3F = 122..128。
        v[fx, fy, 58:64] = C['wall_l']
        v[fx, fy, 122:128] = C['wall_l']
        v[fx, fy, MANOR_WALL_H - 4:MANOR_WALL_H] = C['wall_l']  # 軒下の蛇腹
    #! 隅石（角のスライスだけ）。
    if (north or south) and (west or east):
        cx = 0 if west else V - 3
        cy = 0 if north else V - 3
        for z in range(8, MANOR_WALL_H - 4, 10):
            shade = C['wall_l'] if ((z // 10) % 2) else C['wall']
            v[cx:cx + 3, :, z:z + 9][v[cx:cx + 3, :, z:z + 9] != 0] = shade
            v[:, cy:cy + 3, z:z + 9][v[:, cy:cy + 3, z:z + 9] != 0] = shade
    #! 縦長窓（南面・2〜3 階・**変種で数を振る**＝「窓は少なめ」）。黒い窓に白石の枠。
    #! 1 階 2 マスに合わせて窓も大きく（幅 8・高さ 32）。灯りの暖色を下に敷く（画像の
    #! リファレンスは窓が暖かく灯る）——自発光は無し、色だけ。
    if south and (variant >= 3):
        floors = (76,) if (variant == 3) else (76, 140)
        for z0 in floors:
            wx = int(rng.integers(7, 17))
            v[wx - 1:wx + 9, V - 1:V, z0 - 2:z0 + 36] = C['marb_d']  # 枠
            v[wx:wx + 8, V - 1:V, z0:z0 + 32] = C['obs']            # 窓（黒く沈む）
            v[wx:wx + 8, V - 1:V, z0:z0 + 10] = C['fl_y']           # 下段の灯り（暖色）
            v[wx + 3:wx + 5, V - 1:V, z0:z0 + 32] = C['marb_d']     # 中桟
    return [('main', v, (0, 0, 0))]


def manor_roof_koma(name):
    """紅魔館の本館の屋根 1 マス（**黒い斜めの大屋根**・ひさしが外へ 8 ボクセル出る）。

    2026-08-18 デザイン4 に気づいた:「屋敷の屋根は斜めに設置されるべき。
    1ブロックあたり2枚くらいの瓦でもっとおきな屋根を構成しよう」＋リファレンス画像の
    屋根は黒——初版の「縁 16 vox の立ち上がり＋臙脂の平頂」はほぼ陸屋根に見えた。
    外に面した辺は**40 vox（1.25 マス）かけて 64 vox（2 マス）上がる急勾配**、
    瓦は 16 vox の大きな段（1 マス 2 枚）。内側は黒い平頂。型は 48×48・origin (-8,-8)。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    W = V + 16
    H = 72
    ridge = 64  # 棟の高さ（2 マス）
    v = np.zeros((W, W, H), np.uint8)
    xs = np.arange(W)[:, None]
    ys = np.arange(W)[None, :]
    #! 各点の「外縁からの深さ」（外に面した辺だけ数える）。ひさし分 8 を含む。
    depth = np.full((W, W), 255, np.int32)
    if north:
        depth = np.minimum(depth, ys)
    if south:
        depth = np.minimum(depth, W - 1 - ys)
    if west:
        depth = np.minimum(depth, xs)
    if east:
        depth = np.minimum(depth, W - 1 - xs)
    #! 立ち上がり: ひさしの先 z=10 から 40 vox かけて棟 z=64 へ（勾配 1.35）。
    rise = np.clip(depth * (ridge - 10) // 40, 0, ridge - 10)
    for x in range(W):
        for y in range(W):
            d = depth[x, y]
            if d == 255:
                #! 外に面していないスライス（mid など）は張り出し無し——枠の 8 は空に。
                if (x < 8) or (x >= W - 8) or (y < 8) or (y >= W - 8):
                    continue
                v[x, y, ridge - 6:ridge] = C['obs'] if (((x // 8) + (y // 8)) % 2) else C['obs_l']
                continue
            z_top = 10 + int(rise[x, y])
            #! 斜面の厚み 6（急勾配なので薄いと隣の段と欠けが出る）。
            z_lo = max(0, z_top - 6)
            #! 瓦は **16 vox の大きな段**（1 マス 2 枚）。段の下端に影の線＝軒の水平線が通る。
            band = C['obs_l'] if ((z_top // 16) % 2) else C['obs']
            v[x, y, z_lo:z_top] = band
            if (z_top % 16) < 2:
                v[x, y, z_lo:z_lo + 2] = C['obs_h']  # 段の口（照り）
            if d < 8:
                v[x, y, z_lo:z_top] = C['obs']  # ひさしの裏は影の色
    return [('main', v, (-8, -8, 0))]


def manor_innerwall_koma(name):
    """紅魔館の内壁 1 辺（こう決めた——「屋敷の内壁高さ2ブロック。下部が赤く塗られた
    板張り、上部が白の壁紙」。**柱の意匠は無し**——デザイン5・2026-08-19
    「屋内の壁紙は柱の意匠は無くそう」で、初版の 8 vox おきの柱を取り下げた）。

    fence と同じ「1 枚 1 辺」——**屋内床のマス**の、館の壁に面した辺に貼る
    （館の壁パネルと同じマスに置くと箱の中へ埋まる）。高さ 64 = 2 マス・厚み 3。
    """
    side = _slice_of(name)
    rng = rng_for(name)
    th, height = 3, 64
    v = np.zeros((V, V, height), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    #! 下部 = 赤く塗られた板張り（縦板の目地）。
    put(0, V, 0, 30, C['crimson'])
    for p in range(0, V, 5):
        put(p, p + 1, 2, 30, C['drape'])
    #! 腰の見切り。
    put(0, V, 30, 33, C['marb_d'])
    #! 上部 = 白の壁紙（むらは塊で）。
    put(0, V, 33, height, C['marb_l'])
    for _ in range(4):
        a = int(rng.integers(0, V - 5))
        z = int(rng.integers(36, height - 6))
        put(a, a + 5, z, z + 5, C['marb'])
    return [('main', v, (0, 0, 0))]


def manor_floor_koma(name):
    """紅魔館の屋内の床——板張り（2026-08-19 デザイン5 に決めた:「建物内の床は
    草ではおかしいので板張りの床に」）。

    ground 系と同じ 32×32×3・origin (0,0,-3)。東西に走る長板のりゃんこ張り
    （板幅 4・継ぎ目と行間の 1 vox が暗い目地）。屋内（彫り込み）のマスの地面を
    これで差し替える（`terrain_view.cpp` の manor_inside）。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['timber_d']
    v[:, :, 1] = C['timber']
    layer = np.full((V, V), C['timber_d'], np.uint8)
    row = 4
    for by in range(0, V, row):
        x = -int(rng.integers(0, 12))
        while x < V:
            ln = int(rng.integers(10, 18))
            shade = rng.choice([C['oak'], C['oak_l'], C['timber']], p=[0.5, 0.3, 0.2])
            x0, x1 = max(0, x), min(V, x + ln - 1)
            if x1 > x0:
                layer[x0:x1, by:by + row - 1] = shade
            x += ln
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _brick_round_tower(rng, W, height, body, r, merlon=10):
    """レンガの円塔の胴（監視塔と同じ文法の大型版）。返り値は volume。"""
    cx = cy = (W - 1) / 2.0
    v = np.zeros((W, W, height), np.uint8)
    for x in range(W):
        for y in range(W):
            if (((x - cx) ** 2) + ((y - cy) ** 2)) > (r * r):
                continue
            for z in range(body):
                v[x, y, z] = C['wall'] if z < 22 else C['tile']
    for z in range(25, body, 4):
        for x in range(W):
            for y in range(W):
                if v[x, y, z] == 0:
                    continue
                d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
                if d2 > ((r - 1.2) ** 2):
                    v[x, y, z] = C['joint']
                    v[x, y, max(22, z - 3):z] = rng.choice(
                        [C['tile'], C['roof_r'], C['drape']], p=[0.5, 0.28, 0.22])
    for x in range(W):
        for y in range(W):
            d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
            if (d2 > (r * r)) or (d2 < ((r - 4.5) ** 2)):
                continue
            ang = math.atan2(y - cy, x - cx)
            if int((ang + math.pi) / (math.pi / 4)) % 2 == 0:
                v[x, y, body:body + merlon] = C['tile']
                v[x, y, body + merlon - 1] = C['roof_r']
    return v, cx, cy


def tower_clock_koma(name):
    """**紅魔館の時計塔**（「中に入れるスペースの上に巨大な時計塔」）。

    4 マス幅・8 マス高の 1 枚型。レンガの角柱の胴・四面に白い文字盤（黒針は 10:08）・
    臙脂の尖り屋根・鉄の頂華。**屋根の上に置く**ので接地の形は持たない
    （origin を置く側が屋根の高さへ載せる。footprint は使われない）。
    """
    rng = rng_for(name)
    W = 128
    height = 256
    v = np.zeros((W, W, height), np.uint8)
    x0, x1 = 20, W - 20  # 胴 88（2.75 マス）
    body = 168
    v[x0:x1, x0:x1, 0:body] = C['tile']
    #! レンガの段（外面）。四面まとめて帯で塗る（塊の明暗は面ごと）。
    for z in range(3, body, 4):
        shade = rng.choice([C['tile'], C['roof_r'], C['drape']], p=[0.5, 0.28, 0.22])
        v[x0:x1, x0, z - 3:z] = shade
        v[x0:x1, x1 - 1, z - 3:z] = shade
        v[x0, x0:x1, z - 3:z] = shade
        v[x1 - 1, x0:x1, z - 3:z] = shade
        for f in (x0, x1 - 1):
            v[x0:x1, f, z] = C['joint']
            v[f, x0:x1, z] = C['joint']
    #! 隅の控え（白石）。
    for cx_, cy_ in ((x0, x0), (x0, x1 - 4), (x1 - 4, x0), (x1 - 4, x1 - 4)):
        for z in range(0, body, 8):
            shade = C['wall_l'] if ((z // 8) % 2) else C['wall']
            v[cx_:cx_ + 4, cy_:cy_ + 4, z:z + 7] = shade
    #! 文字盤の階（body..body+56）。少し張り出した白い箱に丸い文字盤を四面。
    cz0 = body
    cz1 = body + 56
    v[x0 - 4:x1 + 4, x0 - 4:x1 + 4, cz0:cz0 + 6] = C['wall_l']  # 張り出しの帯
    v[x0 - 2:x1 + 2, x0 - 2:x1 + 2, cz0 + 6:cz1] = C['wall']    # 文字盤の階の胴（白石。画像準拠）
    ctr = W // 2
    fr = 22  # 文字盤の半径
    fz = cz0 + 28
    for x in range(W):
        for z in range(height):
            d2 = ((x - ctr) ** 2) + ((z - fz) ** 2)
            if d2 <= fr * fr:
                for f, o in ((x0 - 3, x0 - 2), (x1 + 2, x1 + 1)):
                    v[x, f, z] = C['marb_l'] if d2 > ((fr - 2) ** 2) * 0 else v[x, f, z]
                v[x, x0 - 3, z] = C['marb_l']
                v[x, x1 + 2, z] = C['marb_l']
                v[x0 - 3, x, z] = C['marb_l']
                v[x1 + 2, x, z] = C['marb_l']
            if (d2 <= fr * fr) and (d2 > ((fr - 2) ** 2)):
                v[x, x0 - 3, z] = C['obs']
                v[x, x1 + 2, z] = C['obs']
                v[x0 - 3, x, z] = C['obs']
                v[x1 + 2, x, z] = C['obs']
    #! 針（10:08 ふう。上向きの長針と斜めの短針を黒で）。
    for k in range(fr - 4):
        v[ctr, x0 - 3, fz + k] = C['obs']
        v[ctr, x1 + 2, fz + k] = C['obs']
        v[x0 - 3, ctr, fz + k] = C['obs']
        v[x1 + 2, ctr, fz + k] = C['obs']
    for k in range(fr - 9):
        v[ctr - k, x0 - 3, fz + (k // 2)] = C['obs']
        v[ctr - k, x1 + 2, fz + (k // 2)] = C['obs']
        v[x0 - 3, ctr - k, fz + (k // 2)] = C['obs']
        v[x1 + 2, ctr - k, fz + (k // 2)] = C['obs']
    #! 尖り屋根（臙脂の四角錐）と鉄の頂華。
    for z in range(cz1, height - 8):
        t = (z - cz1) / float(height - 8 - cz1)
        half = int(round((1.0 - t) * ((x1 - x0) // 2 + 6)))
        if half < 2:
            half = 2
        band = C['obs'] if ((z // 3) % 2) else C['obs_l']
        v[ctr - half:ctr + half, ctr - half:ctr + half, z] = band
    v[ctr - 1:ctr + 1, ctr - 1:ctr + 1, height - 8:height - 2] = C['iron']
    v[ctr - 2:ctr + 2, ctr - 2:ctr + 2, height - 5:height - 3] = C['iron_l']
    #! 接地は**中央の 1 マスだけ**（龍神像と同じ「張り出し」の扱い）。負の world 座標の
    #! footprint は Python の floor 除算と C++ の 0 方向丸めが食い違う（実測で照合落ち）。
    #! 屋根に 0.35 マス埋めて置くので、z=0 の縁の 1 層の凹みは見えない。
    _ground_center_only(v, W)
    return [('main', v, (-48, -48, 0))]


def _ground_center_only(v, W):
    """z=0 の接地を中央 1 マス（32×32）に絞る（footprint を (0,0) の 1 マスにする）。"""
    c0 = (W // 2) - 16
    keep = v[c0:c0 + 32, c0:c0 + 32, 0].copy()
    v[:, :, 0] = 0
    v[c0:c0 + 32, c0:c0 + 32, 0] = keep


def tower_minor_koma(name):
    """時計塔の左右の小塔（「その左右に少し小ぶりな塔」）。2 マス幅・5.5 マス高。"""
    rng = rng_for(name)
    W = 64
    height = 176
    v, cx, cy = _brick_round_tower(rng, W, height, body=120, r=26.0, merlon=8)[0], (W - 1) / 2.0, (W - 1) / 2.0
    cone0 = 128
    for z in range(cone0, height):
        t = (z - cone0) / float(height - cone0)
        rr = (26.0 * (1.0 - t)) + 0.8
        for x in range(W):
            for y in range(W):
                if (((x - cx) ** 2) + ((y - cy) ** 2)) <= (rr * rr):
                    v[x, y, z] = C['obs'] if ((z // 3) % 2) else C['obs_l']
    _ground_center_only(v, W)  # 接地は中央 1 マス（時計塔の註記と同じ）
    return [('main', v, (-16, -16, 0))]


def tower_wing_koma(name):
    """屋敷の両翼の大塔（「屋敷のりょうよくにも大きな塔を」）。3 マス幅・7 マス高。"""
    rng = rng_for(name)
    W = 96
    height = 224
    v, cx, cy = _brick_round_tower(rng, W, height, body=150, r=40.0, merlon=12)[0], (W - 1) / 2.0, (W - 1) / 2.0
    cone0 = 162
    for z in range(cone0, height):
        t = (z - cone0) / float(height - cone0)
        rr = (42.0 * (1.0 - t)) + 0.8
        for x in range(W):
            for y in range(W):
                if (((x - cx) ** 2) + ((y - cy) ** 2)) <= (rr * rr):
                    v[x, y, z] = C['obs'] if ((z // 3) % 2) else C['obs_l']
    _ground_center_only(v, W)  # 接地は中央 1 マス（時計塔の註記と同じ）
    return [('main', v, (-32, -32, 0))]


def spiral_stair_koma(name):
    """**迷宮（ダンジョン「紅魔館」）入口の螺旋階段**（「迷宮入り口は螺旋階段の
    オブジェクトを配置」）。中心柱のまわりを石段が 2 回転半のぼる。1 マス・2.5 マス。"""
    height = 80
    v = np.zeros((V, V, height), np.uint8)
    ctr = 15.5
    #! 土台の円盤と中心柱。
    for x in range(V):
        for y in range(V):
            d2 = ((x - ctr) ** 2) + ((y - ctr) ** 2)
            if d2 <= 14.0 ** 2:
                v[x, y, 0:2] = C['wall_d']
            if d2 <= 3.2 ** 2:
                v[x, y, 0:height - 6] = C['wall']
    #! 螺旋の段（12 段 × 高さ 6。30° ずつ回る）。
    for i in range(13):
        ang = i * (math.pi / 6.0)
        z0 = 2 + i * 6
        for rr in range(4, 14):
            px = ctr + rr * math.cos(ang)
            py = ctr + rr * math.sin(ang)
            x, y = int(round(px)), int(round(py))
            if 0 <= x < V and 0 <= y < V:
                v[max(0, x - 1):min(V, x + 2), max(0, y - 1):min(V, y + 2), z0:z0 + 3] = (
                    C['wall_l'] if (i % 2) else C['wall'])
    #! 手すりの縁（外周の細い螺旋）。
    for i in range(26):
        ang = i * (math.pi / 12.0)
        z0 = 2 + i * 3
        x = int(round(ctr + 13.5 * math.cos(ang)))
        y = int(round(ctr + 13.5 * math.sin(ang)))
        if 0 <= x < V and 0 <= y < V and z0 + 10 < height:
            v[x, y, z0 + 3:z0 + 10] = C['iron']
    return [('main', v, (0, 0, 0))]


def bookdesk_koma(name):
    """**図書館と書店の印**（「本が並んだ机を下段横に２ブロック上段に看板を貼り付けて
    おく」）。横 2 マスの机に本がぎっしり、頭上に**字の看板**（2026-08-19 に決めた
    デザイン5:「本屋と図書館の看板には本と図の字を入れて」——`bookdesk_koma` = 本・
    `bookdesk_lib_koma` = 図。初版の開いた本の絵はやめた）。入口のマスの南（屋内床）に
    置く——**見た目だけ**で footprint は空（接地層に何も置かない…ではなく机は接地する。
    通行はコアの当たり判定が決める＝絵が塞いでも歩ける）。"""
    icon_key = 'library_gb' if name.startswith('bookdesk_lib') else 'book_gb'
    rng = rng_for(name)
    W = 64
    height = 56
    v = np.zeros((W, V, height), np.uint8)
    #! 机（幅 60・奥行 12・北寄せ＝館の壁際）。
    v[2:62, 2:14, 10:14] = C['oak']
    v[3:61, 3:13, 13] = C['oak_l']
    for lx in (4, 30, 56):
        v[lx:lx + 4, 4:12, 0:10] = C['timber']  # 脚
    #! 並んだ本（背表紙の縦縞。色は塊ごと）。
    spines = [C['crimson'], C['drape_l'], C['sky'], C['moss'], C['fl_y'], C['mgl_d'], C['cor_d']]
    x = 4
    while x < 60:
        wdt = int(rng.integers(2, 4))
        hgt = int(rng.integers(10, 16))
        v[x:x + wdt, 4:12, 14:14 + hgt] = rng.choice(spines)
        x += wdt
    #! 上段の看板（字）。壁際に木の板、白地に黒の字——店の吊り看板と同じ
    #! 「漢字 1 文字」の流儀（§5.5）。**字はカメラの側（南面）に描く**
    #! （初版の開いた本は北面＝壁側に貼ってしまい、単体レンダで真っ黒な板だけが見えた。
    #! 北面は館の壁に密着するので描かない）。
    #! **板は西マス（x 0..32）の中央**——型は印のマスから東へ 2 マスに広がるので、型の中央
    #! （x 32）に置くと**扉から半マス右**にずれる（2026-08-19 に気づいた）。
    v[0:32, 0:4, 34:52] = C['timber_d']
    v[2:30, 3:4, 35:51] = C['marb_l']
    colours, rows = ICONS[icon_key]
    ox = (32 - len(rows[0])) // 2
    oz = 35 + ((16 - len(rows)) // 2)
    for r, line in enumerate(rows):
        for cidx, ch in enumerate(line):
            if ch == '.':
                continue
            v[ox + cidx, 3:4, oz + (len(rows) - 1 - r)] = C[colours[ch]]
    return [('main', v, (0, 0, 0))]


def statue_dragon_jin(name):
    """**龍神の石像**（2026-08-18 に決めた）。人里の `BUILDING_4`。

    原作（東方求聞史紀）では**河童が作った石像**で、里人が日々拝む。天気予報の機能が
    付いていて、ゲーム内でも「龍神像の目は青く光っている。今日はいい天気らしい」という
    台詞が出る——**目を青く光らせる**のはその台詞をそのまま形にしたものである。

    **2 代目（2026-08-18 に決めた:「もっと迫力が欲しい。土台はこのままに像の部分を
    今の 1.5 倍のサイズ感で龍のリアルな造形に」）**、続けて**3 代目（同日:「もう一声。
    ドラゴンボールの神龍のような横に広がるうねり方を。土台が 1 マスなので像は横に
    はみ出て構わない」）。** 縦の螺旋をやめ、**左右へ大きく張り出す S 字のうねり**を
    重ねて昇る——尾は台座に据わり、東へ・西へ・また東へと蛇行しながら太い胸へ膨らみ、
    首が南（カメラ）へ乗り出して**開いた口・牙・V 字の角・たてがみ・髭**の頭で終わる。
    低いうねりの下には**石の雲**（龍は雲に乗る——浮いた石の言い訳でもある）。
    顎の下に**宝珠**（目と同じ青の石）。総高 120（3.75 マス）・幅はおよそ 2.3 マス。

    像は 1 マスから大きくはみ出すので **96×96 の型を origin (-32,-32,0) でマスの中央へ
    寄せる**。接地しているのは台座だけなので footprint は 1 マスのまま
    （木の枝葉と同じ「張り出し」の扱い。画面の縁でマスが外れると像ごと消えるのも同じ）。
    石なので**意匠の色を受けない**（`kPlain` で置く）。
    """
    import math
    rng = rng_for(name)
    W = 96
    height = 120
    v = np.zeros((W, W, height), np.uint8)
    ctr = W / 2.0

    # ---- 台座（初代のまま。二段の切石。中心へ寄せただけ）----
    v[36:60, 36:60, 0:8] = C['wall_d']
    v[38:58, 38:58, 8:16] = C['wall']
    v[39:57, 39:57, 15] = C['wall_l']

    def put_ball(px, py, pz, r, colour):
        x0, x1 = max(0, int(px - r)), min(W, int(px + r) + 2)
        y0, y1 = max(0, int(py - r)), min(W, int(py + r) + 2)
        z0, z1 = max(0, int(pz - r)), min(height, int(pz + r) + 2)
        if (x0 >= x1) or (y0 >= y1) or (z0 >= z1):
            return
        gx, gy, gz = np.ogrid[x0:x1, y0:y1, z0:z1]
        mask = (((gx + 0.5) - px) ** 2 + ((gy + 0.5) - py) ** 2 + ((gz + 0.5) - pz) ** 2) <= (r * r)
        region = v[x0:x1, y0:y1, z0:z1]
        region[mask] = colour

    # ---- 胴（神龍の横うねり。制御点を Catmull-Rom で繋いだ一本の流れ）----
    #! 尾（台座の上）→ 東へ大きく → 西へ大きく → もう一度東へ → 中央へ戻って首、と
    #! **左右の張り出しを段違いに重ねる**。太さは尾 3 → 胸 7.6 → 首 3.8 の紡錘。
    knots = [
        (54.0, 42.0, 17.0, 3.0),   # 尾の先（台座の上に据わる）
        (62.0, 52.0, 20.0, 4.6),
        (76.0, 46.0, 28.0, 6.2),   # 東への張り出し（+28）
        (58.0, 40.0, 38.0, 7.4),
        (22.0, 50.0, 48.0, 7.6),   # 西への張り出し（-26）。胸のいちばん太い所
        (42.0, 42.0, 60.0, 7.0),
        (70.0, 48.0, 68.0, 6.2),   # もう一度東へ（+22）
        (52.0, 52.0, 80.0, 5.2),
        (36.0, 46.0, 88.0, 4.6),   # 小さく西へ切り返す
        (46.0, 44.0, 96.0, 4.2),
        (48.0, 52.0, 100.0, 3.8),  # 首。南（カメラ）へ乗り出して頭に繋がる
    ]

    def catmull(pts, t):
        n = len(pts) - 1
        f = min(max(t * n, 0.0), float(n) - 1e-6)
        i = int(f)
        u = f - i
        p0 = pts[max(0, i - 1)]
        p1 = pts[i]
        p2 = pts[min(n, i + 1)]
        p3 = pts[min(n, i + 2)]
        out = []
        for c in range(4):
            a0, a1, a2, a3 = p0[c], p1[c], p2[c], p3[c]
            out.append(0.5 * ((2 * a1) + (-a0 + a2) * u + (2 * a0 - 5 * a1 + 4 * a2 - a3) * u * u
                + (-a0 + 3 * a1 - 3 * a2 + a3) * u * u * u))
        return out

    spine_pts = []
    for i in range(701):
        t = i / 700.0
        px, py, pz, r = catmull(knots, t)
        seg = int(t * 44)
        put_ball(px, py, pz, r, C['rock_d'] if (seg % 6 == 5) else C['rock'])
        if (i % 34 == 17) and (0.04 < t < 0.95):
            spine_pts.append((px, py, pz, r))

    # ---- 石の雲（低いうねりの下。龍は雲に乗る＝浮いた石の言い訳）----
    #! **初版の倍のサイズ**（2026-08-18 に決めた「雲を今の倍のサイズにしてみよう」）。
    #! 球を 3 → 4 個に増やして幅もおよそ倍（〜50 ボクセル）。東の雲は裾が z16 で切られて
    #! 地面から湧く座布団になり、西の雲は宙に浮く一枚。**上面が胴の腹へ 3〜4 ボクセル
    #! 食い込む**よう z を取る（触れていないと「乗って」見えない）。
    for (mx, my, balls) in (
        (74.0, 47.0, ((-19.0, 1.5, 16.0, 7.4), (-7.0, -0.5, 15.0, 9.8),
                      (6.0, 1.0, 15.5, 10.2), (16.0, 0.5, 16.0, 7.2))),
        (26.0, 50.0, ((-15.0, 1.0, 36.0, 7.2), (-4.0, -1.0, 34.0, 9.6),
                      (8.0, 0.5, 34.0, 9.8), (18.0, 0.0, 36.5, 7.0))),
    ):
        for (ox, oy, oz, orr) in balls:
            put_ball(mx + ox, my + oy, oz, orr, C['rock'])

    #! 台座の外へ落ちた裾や雲の底は台座の上面（z 16）で切りそろえる。
    hang = np.ones((W, W), bool)
    hang[36:60, 36:60] = False
    v[:, :, 0:16][hang] = 0

    # ---- 背の棘（うねりの天辺に沿う列。彫りの「龍」をいちばん安く言う線）----
    for (px, py, pz, r) in spine_pts:
        x0 = int(px)
        y0 = int(py)
        z0 = int(pz + r - 1.0)
        v[max(0, x0 - 1):min(W, x0 + 2), max(0, y0 - 1):min(W, y0 + 2), z0:min(height, z0 + 3)] = C['rock_d']
        v[x0, y0, z0:min(height, z0 + 6)] = C['rock_d']

    # ---- 明暗（リアルさの要）。天面は日を受けて明るく、腹は影で暗い ----
    #! 節の縞（rock_d）と棘には触れない——**rock だけ**を塗り替える。
    zz = np.arange(height)[None, None, :]
    rock = v == C['rock']
    lit = np.zeros_like(rock)
    lit[:, :, :-1] = v[:, :, 1:] == 0
    dim = np.zeros_like(rock)
    dim[:, :, 1:] = v[:, :, :-1] == 0
    v[rock & lit & (zz >= 16)] = C['rock_l']
    v[rock & dim & (zz > 20)] = C['rock_dd']

    # ---- 頭（南向き。開いた口・牙・角・たてがみ・髭）----
    v[41:55, 49:61, 94:106] = C['rock']       # 頭蓋
    v[42:54, 50:60, 105] = C['rock_l']
    v[43:53, 59:68, 97:102] = C['rock']       # 上顎（鼻先。南へ突き出す）
    v[44:52, 60:67, 101] = C['rock_l']
    v[44:52, 59:67, 92:95] = C['rock']        # 下顎
    v[44:52, 60:68, 95:97] = C['dark']        # **開いた口の中**（上下の顎の間の陰）
    for x in (45, 48, 51):                    # 牙（開いた口だから見える）
        v[x, 65:67, 96:98] = C['bone']
        v[x - 1 if x > 45 else 46, 65:67, 94:96] = C['bone']
    v[44:46, 66:68, 100] = C['rock_d']        # 鼻孔
    v[50:52, 66:68, 100] = C['rock_d']
    v[43:53, 58:60, 102:104] = C['rock_d']    # 眉の峰（目の上の影）
    #! **目は青く光る**（求聞史紀の天気予報）。頭蓋から 1 ボクセル飛び出させて
    #! 64px でも必ず画素が残るようにする。
    v[40:43, 57:61, 98:102] = C['mgl']
    v[53:56, 57:61, 98:102] = C['mgl']
    for k in range(11):                       # 角（外へ開きながら後ろへ反る 2 本。正面で V の形）
        zk = 103 + k
        yk = 53 - (k * 2) // 3
        splay = k // 3
        v[41 - splay:44 - splay, yk:yk + 2, zk:zk + 2] = C['rock_d']
        v[52 + splay:55 + splay, yk:yk + 2, zk:zk + 2] = C['rock_d']
    for x in (43, 47, 51):                    # たてがみ（頭の後ろの炎形の房）
        v[x:x + 2, 48:52, 101:107] = C['rock_d']
    v[41, 64:66, 92:97] = C['rock_l']         # 髭（口の脇から垂れる 2 筋）
    v[54, 64:66, 92:97] = C['rock_l']
    v[46:50, 63:67, 88:92] = C['rock_d']      # 顎髭の房
    # ---- 宝珠（顎髭の下に抱く。目と同じ青の石）----
    put_ball(48.0, 65.0, 85.0, 3.4, C['mgl_d'])
    v[47:50, 64:67, 87] = C['mgl']

    #! 苔（石像は里の中で長く立っている。台座と裾だけ——頭まで苔むすと廃墟に見える）。
    for _ in range(int(rng.integers(5, 10))):
        mx, my = int(rng.integers(36, 57)), int(rng.integers(36, 57))
        mz = int(rng.integers(0, 24))
        if v[mx, my, mz]:
            v[mx:mx + 3, my:my + 3, mz:mz + 2] = C['moss_d']
    return [('main', v, (-32, -32, 0))]


def house_entrance(name):
    """**見た目だけの玄関**（2026-08-18 に決めた:「機能のない建物にも見た目としてだけ
    玄関をつけたい」）。

    町のデータに入口を持たない敷地は、いまのところ**窓と屋根だけの閉じた箱**である。
    人が住んでいる家に見えないので、南面（＝カメラの正面）に引き戸を 1 つ立てる。

    **`house_light` と同じ「壁の前に置く別体」**である（壁そのものを彫らない）。壁は 9 スライスの
    共用材で、玄関のあるマスだけ別に焼くと意匠が 2 倍になるため。y 27..31 に収めてあるので
    マスからはみ出さない。

    **基（変愚）は作らない。** 引く側は `styled("house_entrance")` なので、意匠を持たない町では
    名前が見つからず**何も置かれない**——変愚の絵は 1 ボクセルも動かない。
    """
    v = np.zeros((V, V, 32), np.uint8)
    y0, y1 = 29, 31  # 壁の面（引っ込めた躯体の外側）より手前
    #! 踏み石（土間へ上がる沓脱ぎ）。**二枚戸ぶんに広げる。**
    v[7:25, 26:31, 0:3] = C['wall']
    v[7:25, 26:31, 2] = C['wall_l']
    #! 外枠（左右の柱と敷居・鴨居）。実物は**太い枠が戸を囲む**。
    v[5:27, y0:y1 + 1, 3:30] = C['yaki']
    #! **戸は 2 枚**（2026-08-18 に決めた:「真ん中に一枚ではなく、これを左右に二枚並べて」）。
    #! 中央に**召し合わせの框**（2 枚の縦框が突き合う所）が立つのが引き違いの読みである。
    for lx0 in (7, 17):
        lx1 = lx0 + 9
        v[lx0:lx1, y1, 4:29] = C['board']  # 戸の地
        v[lx0:lx1, y1, 5:13] = C['board_d']  # 下は無地の板（実物の下半分）
        for x in range(lx0 + 2, lx1 - 1, 2):  # 上は縦格子（1 本置きで縞に読める）
            v[x, y1, 13:25] = C['board_l']
        for z in (17, 21):  # 格子を区切る横桟 2 本
            v[lx0 + 1:lx1 - 1, y1, z] = C['yaki']
        v[lx0, y1, 4:29] = C['yaki']  # 縦框（左右）
        v[lx1 - 1, y1, 4:29] = C['yaki']
    #! 欄間（戸の上の明かり取り。ここも縦格子）。
    for x in range(6, 26, 2):
        v[x, y1, 26:29] = C['board_l']
    #! 小さな庇。杉皮を 2 段。軒があるだけで「入口」に読める。
    v[4:28, 25:31, 30:32] = C['sugi']
    v[4:28, 25:27, 31] = C['sugi_l']
    return [('main', v, (0, 0, 0))]


def _house_light_shoji(name):
    """**人里の灯り** — 障子の白い面そのものを光らせる（2026-08-18 に気づいた）。

    > 障子の中に光る枠（変愚の窓）が違和感。障子自体の白い部分を光らせることはできるか？

    できる。**自発光はインスタンス単位**（罠 39）なので、光るものは壁と別体でなければならない
    ——そこは変えずに、**別体の形を障子に合わせる**のが答えである。基のものは窓 1 つぶんの
    四角（`v[11:21, 29:32]`）で、障子 3 枚の真ん中あたりに**別の枠**として浮いて見えていた。

    位置は `_house_wall_tsuchi` の障子と揃える:
    - 横 … x 4..9 / 13..18 / 22..27（同じ 3 枚）
    - 高さ … 壁の中では z 16..27（＝0.50〜0.84 マス）。灯りは 0.40 マスに置かれるので
      局所では **z 3..15**。ここを外すと「障子の上下だけ光る帯」になる
    - **桟（縦の 1 列）は光らせない。**白い面が 1 枚の板に見えてしまい、障子に読めない
    """
    rows = 13
    paper = _shoji_paper(rows)
    v = np.zeros((V, V, 16), np.uint8)
    #! 壁の障子は z 14..27（＝0.4375〜0.84 マス）。灯りは 0.40 マスに置かれるので局所は 1 から。
    for x in range(SHOJI_X0, SHOJI_X1):
        for k in range(rows):
            if paper[x, k]:
                v[x, 29:32, 1 + k] = C['lit']
    return [('main', v, (0, 0, 0))]


def _house_light_chochin(name):
    """**旧地獄街道の灯り** — 軒下の提灯と格子窓を光らせる（障子の灯と同じ流儀）。

    自発光はインスタンス単位（罠 39）なので光る物は壁と別体。**割り付けは壁と共有**
    （`KYU_*`。片方だけ動かすと灯が提灯から抜け出す——障子で踏んだ罠と同じ形）。
    置かれる高さは壁より 0.40 マス（≒13 ボクセル）上なので、**origin_z を −13 にして
    壁と同じ z で書く**（接地層 z=0 に何も無いので footprint は空のまま）。

    - 提灯 … 紙（壁の y 30）の 1 ボクセル手前 y 31 に光る面（石灯籠の灯と同じ）
    - 格子 … 桟を抜いて**隙間だけ**光らせる。面ごと光らせると格子が塗り潰される
      （障子で踏んだ罠。桟の位置は壁と同じ式で出す）
    """
    v = np.zeros((V, V, HOUSE_WALL_H), np.uint8)
    for lx in KYU_LANT_XS:
        v[lx:lx + KYU_LANT_W, 31:32, KYU_LANT_Z0:KYU_LANT_Z1] = C['chochin_l']
    for x in range(KYU_KOSHI_X0, KYU_KOSHI_X1):
        bar = ((x - KYU_KOSHI_X0 - 1) % KYU_KOSHI_PITCH) == 0
        if not bar:
            v[x, 30:31, KYU_KOSHI_Z0:KYU_KOSHI_Z1] = C['lit']
    return [('main', v, (0, 0, -13))]


# ---------------------------------------- 人里の意匠の残り（2026-08-18。§4.1 の意匠手がかり）
#
# 壁と屋根（`_house_wall_tsuchi` / `_house_roof_kaya`）に続く 19 個。
# **色は 1 つも足していない**（パレットは 254/255 で満杯。上の別名の表を参照）。


def _fence_ita(name):
    """**人里の柵** — 縦板を並べた板塀。

    高さ（14）と厚み（4）は**基のものと必ず揃える**——柵の高さは「視線を遮らない」という
    約束そのもので、町ごとに変えると遮蔽の判定に効いてしまう（基の註記）。
    """
    side = _slice_of(name)
    rng = rng_for(name)
    th, height = 4, 14
    v = np.zeros((V, V, height), np.uint8)
    lo = 0 if side in ('n', 'w') else V - th
    ns = side in ('n', 's')

    #! 縦板。**塊ごとに 1 色**（罠 38）。3 幅＋1 空きで並べると隙間から向こうが透ける。
    for a in range(0, V, 4):
        shade = rng.choice([C['board'], C['board_l'], C['board_d']], p=[0.45, 0.30, 0.25])
        if ns:
            v[a:a + 3, lo:lo + th, 0:height] = shade
        else:
            v[lo:lo + th, a:a + 3, 0:height] = shade
    #! 笠木（頭を通す横木）。**縦板だけだと櫛に見える。**
    if ns:
        v[:, lo:lo + th, height - 2:height] = C['yaki_l']
        v[:, lo:lo + th, 0:2] = C['yaki']
    else:
        v[lo:lo + th, :, height - 2:height] = C['yaki_l']
        v[lo:lo + th, :, 0:2] = C['yaki']
    return [('main', v, (0, 0, 0))]


def _rampart_dobei(name):
    """**人里の塀** — 土塀（土を突き固めた壁）に瓦の笠木。

    §4.1 の「町の入口に囲壁＋大門を必ず立てる」に応える材。**丸太の塀と遠目で分かれる**
    ことが要件で、そこは「縦の木口が並ぶ」か「横に長い土の面」かの差で出る。
    高さは基と同じ 62（＝1.9 マス）。
    """
    rng = rng_for(name)
    height = 62
    v = np.zeros((V, V, height), np.uint8)
    v[:, :, 0:6] = C['wall_d']  # 石の基壇（土が雨で流れないよう腰を石で組む）
    v[:, :, 5] = C['wall']
    v[:, :, 6:height - 6] = C['tsuchi']
    #! 土のむら。**塊で置く**（罠 38）。版築の横の縞に見えるよう、横長に取る。
    for _ in range(int(rng.integers(4, 8))):
        cx = int(rng.integers(0, V - 6))
        cz = int(rng.integers(8, height - 12))
        v[cx:cx + int(rng.integers(5, 11)), :, cz:cz + int(rng.integers(2, 4))] = C['tsuchi_d']
    v[:, :, height - 6:height - 2] = C['mune']  # 笠木の下地（木）
    v[:, :, height - 2:height] = C['wall']  # 瓦の笠木（天面。見下ろすカメラではここが主役）
    return [('main', v, (0, 0, 0))]


def _rampart_neribei(name):
    """**天狗の里の塀** — 白漆喰の練塀に黒い瓦の笠木。

    人里の土塀（生成り）との差は**白さ**、モリバントの城壁（切石の目地）との差は
    **面の無地**。§4.4「3 者の中で唯一の白い建物」を塀にも通す。
    高さは基と同じ 62（＝1.9 マス）。
    """
    rng = rng_for(name)
    height = 62
    v = np.zeros((V, V, height), np.uint8)
    v[:, :, 0:8] = C['wall_d']   # 石垣の腰。山上なので高めに組む
    v[:, :, 7] = C['wall']
    v[:, :, 8:height - 7] = C['shira']
    #! 漆喰の古び。**塊で**（罠 38）。腰の近くに寄せる（雨垂れの跡）。
    for _ in range(int(rng.integers(3, 6))):
        cx = int(rng.integers(0, V - 5))
        cz = int(rng.integers(9, 24))
        v[cx:cx + int(rng.integers(3, 8)), :, cz:cz + int(rng.integers(2, 4))] = C['shira_d']
    v[:, :, height - 7:height - 4] = C['timber_d']   # 笠木の下地
    v[:, :, height - 4:height] = C['iron']           # 黒い瓦（見下ろすカメラの主役）
    v[:, :, height - 1] = C['iron_l']
    return [('main', v, (0, 0, 0))]


def _rock_face_kyu(name):
    """**旧地獄街道の岩肌**（2026-08-18 その3 に決めた）——刳り抜いた山の内壁 6 マス。

    > 街の奥側の壁の表現は高い岩の内側の岩肌として表現して、高さは 6 ブロック分ほどになってよい

    塀（`palisade_kyu`）と岩山の全段（`crag_*_kyu`）を**同じ材**で置く——どちらも同じ山の
    身である（初版の黒板塀はこの指示で置き換えた。柵の横板塀は前庭の囲いとして残る）。
    天面は岩天井（`cave_roof_kyu`・z=6 マス）に接するので、頭は作り込まない。
    **塀（62）の高さの約束はここでは受けない**——これは塀ではなく山であり、
    櫓も覆いの町では立たない（terrain_view が抑える）。

    彫りは構造だけ（§6——無作為な表面ノイズは入れない）: 地層の横帯（帯ごとに 1 色・
    **灼熱地獄跡の名残の赤褐**を 2 割ほど挟む＝§4.4 ⑥）＋帯の境の影線＋煤の塊＋
    まれな縦の裂け目。
    """
    rng = rng_for(name)
    height = 192  # 6 マス
    v = np.zeros((V, V, height), np.uint8)
    #! 地層。8〜14 ボクセルの帯ごとに 1 色。灰にせず黒と赤褐で「地底の岩」にする。
    #! 帯の座標は後の彫り（棚）と共有するので、先に列を作る。
    bands = []
    z = 0
    while z < height:
        step = int(rng.integers(8, 15))
        bands.append((z, min(z + step, height)))
        z += step
    for (z0, z1) in bands:
        shade = rng.choice([C['char_l'], C['char'], C['sco_d'], C['emb_d'], C['sco']],
                           p=[0.34, 0.24, 0.18, 0.14, 0.10])
        v[:, :, z0:z1] = shade
        if z1 < height:
            v[:, :, z1 - 1] = C['obs_d']  # 帯の境の影線
    #! 煤と焦げの塊（塊で置く＝罠 38。面だけ塗ると縦縞に見える）。
    for _ in range(60):
        bx, by = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        bz = int(rng.integers(0, height - 10))
        w, d, h = int(rng.integers(3, 7)), int(rng.integers(3, 7)), int(rng.integers(4, 10))
        v[bx:bx + w, by:by + d, bz:bz + h] = C['char'] if rng.random() < 0.6 else C['obs_d']

    # ---- 面の彫り（気づいたこと その3「建物の奥の岩肌がまったいらなのも気になる」）----
    #
    # 色の縞だけでは面が完全な平面で、崖に読めなかった。彫りは**構造で**出す（§6
    # ——ボクセル単位の砂嵐にしない）。**足元 8 ボクセルはマスいっぱいのまま**（罠 5
    # ——削ると隣との継ぎ目から背景が抜ける）。両側から最大 5 ボクセルずつ彫っても
    # 芯 22 が残るので、殻を撃ち抜いて中の空洞が覗くことは無い。
    # 隣のマスと彫りが揃わないのは crag と同じ狙い——継ぎ目が格子でなく岩の割れに見える。
    carve_from = 8
    #! (a) 地層の棚。帯ごとに 0〜2 ボクセル引っ込める——横に走る段差が崖の第一印。
    for (z0, z1) in bands:
        if z0 < carve_from:
            continue
        inset = int(rng.integers(0, 3))
        if inset:
            v[0:inset, :, z0:z1] = 0
            v[V - inset:V, :, z0:z1] = 0
            v[:, 0:inset, z0:z1] = 0
            v[:, V - inset:V, z0:z1] = 0
    #! (b) 塊の抉り。各面に幅 4〜9・高さ 6〜15・深さ 1〜3 の欠けを散らす。
    for _ in range(int(rng.integers(26, 40))):
        side = int(rng.integers(0, 4))
        p = int(rng.integers(0, V - 9))
        z0 = int(rng.integers(carve_from, height - 16))
        w = int(rng.integers(4, 10))
        hh = int(rng.integers(6, 16))
        d = int(rng.integers(1, 4))
        if side == 0:
            v[0:d, p:p + w, z0:z0 + hh] = 0
        elif side == 1:
            v[V - d:V, p:p + w, z0:z0 + hh] = 0
        elif side == 2:
            v[p:p + w, 0:d, z0:z0 + hh] = 0
        else:
            v[p:p + w, V - d:V, z0:z0 + hh] = 0
    #! (c) 縦の裂け目。塗り（dark）に加えて**実彫り**を数本——影線でなく本物の溝にする。
    for _ in range(int(rng.integers(3, 6))):
        p = int(rng.integers(2, V - 3))
        z0 = int(rng.integers(carve_from, height - 70))
        z1 = z0 + int(rng.integers(40, 100))
        side = int(rng.integers(0, 4))
        if side == 0:
            v[0:2, p:p + 2, z0:z1] = 0
        elif side == 1:
            v[V - 2:V, p:p + 2, z0:z1] = 0
        elif side == 2:
            v[p:p + 2, 0:2, z0:z1] = 0
        else:
            v[p:p + 2, V - 2:V, z0:z1] = 0
    v[:, :, height - 2:height] = C['obs_d']  # 天井に接する頭は影に沈める
    return [('main', v, (0, 0, 0))]


def cave_roof_kyu(name):
    """**旧地獄街道の岩天井**（2026-08-18 その3 に決めた）。

    > 街全体を巨大な黒い岩山で覆い、屋根としてしまいたい。（中略）二重透過の仕組みで
    > 岩山の中の街をキャラに合わせて透過しながら描画する

    町の**全マス**の z=6 マスに 1 枚ずつ敷く蓋。見えるのは天面（屋根外しの穴の外＝
    黒い山の背）だけ——下面は見下ろしのカメラに映らず、穴の中は層 2 が刳り抜く。

    **天面は変種ごとに平ら。**初版はマスの中で 4 ボクセル起伏させたら、マスごとに独立の
    種なので全面が市松の砂利になった（実写で確認）。巨大な一枚岩は「平らな面＋
    大きな段」で読ませる——置く側が **4×4 マスのまとまり**で変種を選ぶので、変種の高さの
    差（1 ボクセル）が数マスおきの緩い段丘になる。色のむらも 8×8 の大きな塊で薄く。
    """
    rng = rng_for(name)
    idx = int(name.rsplit('_', 1)[-1])
    top_h = 19 + (idx % 3)   # 変種ごとの平らな高さ（段丘の 1 段）
    v = np.zeros((V, V, top_h + 1), np.uint8)
    v[:, :, 0:top_h] = C['obs_d']            # 下面と胴（洞窟の天井裏）
    shades = rng.choice([C['char'], C['char_l'], C['sco_d']],
                        size=(V // 8 + 1, V // 8 + 1), p=[0.55, 0.25, 0.20])
    for x in range(V):
        for y in range(V):
            v[x, y, top_h - 1] = int(shades[x // 8, y // 8])
    #! 灼熱の名残の赤褐をまれに 1 塊（黒い山の背に差す地の色。多いと錆びた鉄板に見える）。
    if rng.random() < 0.5:
        bx, by = int(rng.integers(0, V - 8)), int(rng.integers(0, V - 8))
        v[bx:bx + int(rng.integers(4, 8)), by:by + int(rng.integers(4, 8)), top_h - 1] = C['emb_d']
    return [('main', v, (0, 0, 0))]


def _tower_hinomi(name):
    """**人里のやぐら** — 火の見櫓。細い 4 本柱に半鐘と小さな板葺きの切妻。

    **塀より頭ひとつ高い**という約束（基の註記）は変えない。丸太のやぐらとの差は
    「太い箱」か「細い櫓」かで、里の自警の道具らしさはそこに出る。
    """
    height = 100
    v = np.zeros((V, V, height), np.uint8)
    posts = ((4, 9), (23, 28))
    for (x0, x1) in posts:
        for (y0, y1) in posts:
            v[x0:x1, y0:y1, 0:78] = C['timber']
    #! 貫（水平材）を 3 段。**斜めの筋交いは入れない**（和風の櫓は貫で組む）。
    for z in (22, 44, 64):
        v[4:28, 4:9, z:z + 2] = C['timber_d']
        v[4:28, 23:28, z:z + 2] = C['timber_d']
        v[4:9, 4:28, z:z + 2] = C['timber_d']
        v[23:28, 4:28, z:z + 2] = C['timber_d']
    v[3:29, 3:29, 78:81] = C['board']  # 床
    for (a0, a1) in ((3, 5), (27, 29)):  # 手すり
        v[a0:a1, 3:29, 81:86] = C['timber']
        v[3:29, a0:a1, 81:86] = C['timber']
    v[14:18, 14:18, 82:88] = C['iron']  # 半鐘
    #! 小さな切妻。**茅ではなく板**（火の見櫓に茅を葺くと家に見える）。
    for i in range(6):
        v[2 + i:30 - i, 2 + i:30 - i, 88 + i:89 + i] = C['shin'] if (i % 2) else C['shin_d']
    return [('main', v, (0, 0, 0))]


def _tower_takadono(name):
    """**天狗の里のやぐら** — 白漆喰の袴腰の望楼。棟に鴉が一羽。

    火の見櫓（人里。吹き抜けの細い柱）との差は**足元が詰まっている**こと——山上の
    望楼は風が強いので袴腰（裾広がりの白漆喰）で組む。**塀より頭ひとつ高い**約束は
    変えない。§4.4 ⑤ の鴉（棟の黒い小板）はここに 1 羽だけ載せる——天狗の里の署名。
    """
    height = 100
    v = np.zeros((V, V, height), np.uint8)
    #! 袴腰（裾広がり）。裾 2 → 頭 7 の絞りを白漆喰で積む。
    for z in range(0, 62):
        m = 2 + (z * 5) // 62
        v[m:V - m, m:V - m, z] = C['shira']
    v[2:30, 2:30, 0:3] = C['wall_d']   # 石の基壇
    #! 四隅の隅木の線（濃い焦茶）。白い面の縁を締める。
    for z in range(3, 62):
        m = 2 + (z * 5) // 62
        for cx, cy in ((m, m), (V - 1 - m, m), (m, V - 1 - m), (V - 1 - m, V - 1 - m)):
            v[cx, cy, z] = C['timber_d']
    v[6:26, 6:26, 62:65] = C['board']   # 見張り台の床
    for a0, a1 in ((6, 8), (24, 26)):   # 手すり
        v[a0:a1, 6:26, 65:70] = C['timber']
        v[6:26, a0:a1, 65:70] = C['timber']
    for x0, x1 in ((7, 9), (23, 25)):   # 屋根を受ける柱
        for y0, y1 in ((7, 9), (23, 25)):
            v[x0:x1, y0:y1, 65:88] = C['timber']
    #! 反りの無い方形屋根（杉皮。家並みの屋根と同じ材）。
    for i in range(7):
        v[4 + i:28 - i, 4 + i:28 - i, 88 + i:89 + i] = C['hiwada'] if (i % 2) else C['hiwada_d']
    #! 鴉。**棟の黒い小板 1 羽**（§4.4。求聞史紀の鴉天狗＝報道部隊の連想）。
    v[14:18, 15:17, 95:98] = C['dark']   # 胴
    v[17:19, 15:17, 96:99] = C['dark']   # 頭とくちばし
    return [('main', v, (0, 0, 0))]


def _tower_yagura(name):
    """**旧地獄街道のやぐら** — 黒木の櫓。床下に提灯を 1 張り提げる。

    骨は火の見櫓（人里）と同じ吹き抜けの 4 本柱だが、木が黒く、屋根は板でなく
    **黒瓦の方形**——家並みと同じ材で締める。提灯は昼の目印（夜の自発光は無し。
    やぐらは滅多に建たないので配線を増やさない）。**塀より頭ひとつ高い**約束は変えない。
    """
    height = 100
    v = np.zeros((V, V, height), np.uint8)
    posts = ((4, 9), (23, 28))
    for (x0, x1) in posts:
        for (y0, y1) in posts:
            v[x0:x1, y0:y1, 0:78] = C['shitami']
    for z in (22, 44, 64):   # 貫。**斜めの筋交いは入れない**（和風の櫓は貫で組む）
        v[4:28, 4:9, z:z + 2] = C['char']
        v[4:28, 23:28, z:z + 2] = C['char']
        v[4:9, 4:28, z:z + 2] = C['char']
        v[23:28, 4:28, z:z + 2] = C['char']
    v[3:29, 3:29, 78:81] = C['shitami_l']   # 床
    for (a0, a1) in ((3, 5), (27, 29)):     # 手すり
        v[a0:a1, 3:29, 81:86] = C['shitami']
        v[3:29, a0:a1, 81:86] = C['shitami']
    #! 方形の黒瓦屋根。頂をいぶし銀で光らせる（家並みの棟と同じ記号）。
    for i in range(6):
        v[2 + i:30 - i, 2 + i:30 - i, 88 + i:89 + i] = C['kawara'] if (i % 2) else C['kawara_d']
    v[13:19, 13:19, 94:96] = C['kawara_g']
    #! 提灯（南面＝カメラ側の床下）。紙は昼から橙（赤提灯は昼も赤い）。
    v[15:17, 27:30, 76:79] = C['char_l']    # 吊り
    v[13:19, 26:30, 74:76] = C['char']      # 蓋
    v[12:20, 25:30, 64:74] = C['chochin']   # 紙の胴
    v[13:19, 29:30, 66:72] = C['chochin_l']
    v[13:19, 26:30, 62:64] = C['char']      # 口輪（下）
    return [('main', v, (0, 0, 0))]


def stone_lantern(name):
    """**石灯籠**（2026-08-18 に決めた「L 字の角は高さ 2 ブロックの石灯籠に」）。

    春日形——基礎・竿・中台・火袋・笠・宝珠。高さ 64（＝2 マス）。
    人里の祠では **L 字の柱の欠片の角のマス**に立つ（`terrain_view.cpp` の `lone_props`。
    腕の先の 2 マスは花壇）。細い立ち姿にして**龍神像を隠さない**のが要件である。
    石なので意匠の色は受けない（`kPlain`）。火袋の窓は暖色に塗るだけで自発光は
    まだ配線していない（夜に灯すなら `lamp_flame` と同じ別体に割ることになる）。
    """
    height = 64
    v = np.zeros((V, V, height), np.uint8)
    v[8:24, 8:24, 0:4] = C['wall_d']         # 基礎（切石）
    v[9:23, 9:23, 3] = C['wall']
    v[13:19, 13:19, 4:28] = C['rock']        # 竿。**細く**（像を隠さない）
    v[13, 13:19, 4:28] = C['rock_d']
    v[18, 13:19, 4:28] = C['rock_d']
    v[11:21, 11:21, 28:32] = C['rock']       # 中台（受け）
    v[12:20, 12:20, 28:30] = C['rock_l']
    v[12:20, 12:20, 32:46] = C['rock']       # 火袋
    #! 窓は十字に貫く——四面どれから見ても暖色の窓が出る。
    v[14:18, 12:20, 35:43] = C['lit']
    v[12:20, 14:18, 35:43] = C['lit']
    v[9:23, 9:23, 46:49] = C['rock_d']       # 笠（下端が最も広い）
    v[10:22, 10:22, 49:51] = C['rock_d']
    v[12:20, 12:20, 51:53] = C['rock']
    v[13:19, 13:19, 53:55] = C['rock']       # 請花
    v[14:18, 14:18, 55:62] = C['rock_l']     # 宝珠
    return [('main', v, (0, 0, 0))]


def torii(name):
    """**素木の鳥居**（2026-08-18 に決めた。人里の龍神の祠の入口）。

    それまで祠の入口（`BUILDING_4` のマス）には対応表の既定＝**変愚の石のアーチ**が
    立っていた（和風化から漏れていた）。差し替え先は素木の鳥居と決めた。
    **朱は使わない**——Q2 の描き分けで朱は博麗の鳥居だけの記号にしてある。
    素木なので形も飾りの無い**神明鳥居**（まっすぐな笠木・貫・額束なし）。
    姿勢は石のアーチと同じ「南北にくぐる」が基。高さ 1.8 マス——くぐった先の
    像（3.75 マス）の顔を隠さない。守矢の素木の鳥居（§4.2）にも使い回せる。
    """
    height = 58
    v = np.zeros((V, V, height), np.uint8)
    for x0, x1 in ((3, 8), (24, 29)):
        v[x0:x1, 14:18, 0:52] = C['oak']              # 柱
        v[x0:x1, 17, 2:52] = C['oak_l']               # 南の面（カメラ側）は日を受けて明るい
        v[x0 - 1:x1 + 1, 13:19, 0:3] = C['wall_d']    # 根元の石（亀腹）
    v[0:32, 13:19, 52:58] = C['oak']                  # 笠木（まっすぐ＝神明鳥居）
    v[0:32, 13:19, 57] = C['oak_l']
    v[0:32, 14:18, 38:42] = C['oak']                  # 貫
    v[0:32, 17, 38:42] = C['oak_l']
    return [('main', v, (0, 0, 0))]


def stone_lantern_flame(name):
    """**石灯籠の灯**（2026-08-18 に決めた「石灯籠は夜光らせる事は可能？」）。

    火袋の窓の**1 ボクセル外**に貼る発光板 4 枚。街灯の `lamp_flame` と同じ流儀で、
    自発光はインスタンス単位（罠 39）なので光る物を別体に割る——本体の窓（`lit` の塗り）と
    同じ位置に重ねると z-fight するので、面の外へ 1 ボクセル出して貼る。
    夜だけ置かれ、自発光は置く側が乗せる。接地しない（footprint は空）。
    位置は `stone_lantern` の火袋（12:20 / z 32:46・窓 35:43）に合わせてある。
    """
    v = np.zeros((V, V, 64), np.uint8)
    v[14:18, 20:21, 35:43] = C['lit']   # 南（カメラ側）
    v[14:18, 11:12, 35:43] = C['lit']   # 北
    v[20:21, 14:18, 35:43] = C['lit']   # 東
    v[11:12, 14:18, 35:43] = C['lit']   # 西
    return [('main', v, (0, 0, 0))]


def nobori_ten(name):
    """**天狗の里の幟**（§4.4 ③「幟を屋根より高く 1 枚——遠目の第一印」）。

    白地に赤の帯と黒の一字。この縮尺で字は潰れるので**帯と塊**で言う（店の暖簾の
    白抜きと同じ判断）。屋根（壁 34 ＋ 屋根 30 ＝ 64）より高い 96（3 マス）。
    置くのは街路樹の口（`TownStyle::street_tree`）——道沿いのマスに 3 割で立つ。
    """
    height = 96
    v = np.zeros((V, V, height), np.uint8)
    v[13:18, 13:18, 0:3] = C['wall_d']              # 根元の石
    v[14:17, 14:17, 0:height - 2] = C['timber']     # 竿
    v[14:17, 14:17, height - 3] = C['timber_l']
    top = height - 4
    v[14:29, 15:17, top:top + 2] = C['timber_l']    # 横手（布を吊る腕木）
    #! 布。竿の東へ張り出し、面を南（カメラ）へ向ける。風はモーションを持たないので
    #! **下端を 1 段だけ振る**（棒のように真っ直ぐだと看板に見える）。
    v[17:29, 15:17, top - 58:top] = C['nuki']
    v[17:29, 15:17, top - 6:top] = C['crimson']     # 上端の赤帯
    v[17:29, 15:17, top - 58:top - 55] = C['crimson']  # 下端の赤帯
    v[19:27, 16, top - 30:top - 12] = C['ink']      # 黒の一字（潰れるので塊で）
    v[26:29, 15:17, top - 58:top - 50] = 0          # 下端の翻り（欠き取りで風を言う）
    return [('main', v, (0, 0, 0))]


# ---- 博麗神社（デザイン6・2026-08-19）--------------------------------------
#
# 町 5 の地図は「北端からの一本の参道 → 277 マス 25×12 の社殿の塊」。塊は敷地の条件
# （span ≤ 26・充填 0.92）に収まるので、これまでは**巨大な寄棟の民家**が建っていた。
# デザイン6 で屋敷（Manor）に読み替え、屋根を**切妻**で組む（§3.5「9 スライスの枠内では
# 切妻が作れない」への答え。棟が東西へ通り、妻が東西端に立つ＝平入りの拝殿）。
# 社殿は素木＋生成り（Q2「朱にするのは鳥居だけで、社殿は素木のまま」）、
# **朱は参道の大鳥居 1 対だけ**が持つ。

HAK_WALL_H = 72   # 拝殿の壁 1 層（2.25 マス。低く見せる——§4.2「大きくすると命蓮寺に食われる」）
HAK_RISE = 14     # 切妻の斜面が 1 マスで上がる高さ（12 マス奥行き × 6 段 ＝ 棟まで 84 vox）


def _ground_path_hak(name):
    """**博麗神社の参道** — 自然石の敷石に玉砂利と苔。「参道はきちんと整備され」（§4.2）。"""
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['gravel_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['gravel'], C['gravel_l'], C['pack'], C['gravel_d']], [0.34, 0.24, 0.22, 0.20])
    #! 大きめの自然石。角の丸い矩形を**重ねて**置く（_lump_face の理屈。格子に揃えない）。
    _lump_face(rng, layer, [C['rub_l'], C['flag'], C['flag_l']], [0.45, 0.30, 0.25],
               span=(5, 12), count=26)
    #! 目地の苔（古びた参道の読み。塊で置く＝罠 38）。
    _grain(rng, layer, layer > 0, [C['moss_d'], C['moss']], [0.05, 0.03], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def manor_wall_hak(name):
    """博麗神社の拝殿の壁 1 マス（素木の柱＋生成りの土壁・**縁側の濡縁つき**・高さ 2.25 マス）。

    紅魔館（3 階 192 vox）との対比で**低く**作る——博麗は「小さく低く、朱を使わない」が
    見分けの要（§4.2）。変種で開口を振る（_01 = 壁だけ・_02 = 連子窓・_03 = 障子）。
    縁側は外に面した辺の**外へ 8 vox 張り出す**（型 48×48・origin (-8,-8)。
    張り出しは z≥8 だけ——接地がマスの外に出ると footprint 照合で落ちる罠を避ける）。
    """
    base = _split_style(name)[1]  # manor_wall_<slice>_<nn>
    parts = base.split('_')
    key = parts[2]
    variant = int(parts[3]) if ((len(parts) > 3) and parts[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    W = V + 16
    v = np.zeros((W, W, HAK_WALL_H), np.uint8)
    c0, c1 = 8, 8 + V  # マスの中身（local 8..40）
    #! 基壇（切石。マスいっぱい＝罠 5）。
    v[c0:c1, c0:c1, 0:8] = C['wall_d']
    v[c0:c1, c0:c1, 7] = C['wall']
    #! 躯体（生成りの土壁。むらは塊で）。
    v[c0:c1, c0:c1, 8:HAK_WALL_H] = C['cream']
    for _ in range(5):
        bx = int(rng.integers(c0, c1 - 6))
        bz = int(rng.integers(12, HAK_WALL_H - 8))
        shade = C['cream_l'] if rng.random() < 0.5 else C['cream_d']
        region = v[bx:bx + 6, c0:c1, bz:bz + 5]
        region[region == C['cream']] = shade

    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        if side == 'n':
            fx, fy, vert = slice(c0, c1), c0, False
        elif side == 's':
            fx, fy, vert = slice(c0, c1), c1 - 1, False
        elif side == 'w':
            fx, fy, vert = c0, slice(c0, c1), True
        else:
            fx, fy, vert = c1 - 1, slice(c0, c1), True
        #! 面の割り——**腰の羽目板（横板）＋長押＋上の帯＋軒下**。初版の「柱 3 本＋
        #! 横帯 4 本」は一人称（FPS モード）で正面から見ると**面じゅうが格子**になり、
        #! 「障子で埋め尽くされた」と読まれた（気づいたこと・デザイン6 その3）。
        #! 柱は**マスの境に 1 本**だけ（隣と合わせて 6 vox 角に見える）。
        v[fx, fy, 8:12] = C['timber_d']                  # 水切り
        #! 腰の羽目板（4 vox の横板・目地は濃い線）。参考画像の「腰は木の板」。
        for z in range(12, 46, 4):
            v[fx, fy, z:z + 3] = C['oak'] if ((z // 4) % 2) else C['oak_l']
            v[fx, fy, z + 3] = C['timber_d']
        v[fx, fy, 46:50] = C['timber']                   # 長押
        v[fx, fy, HAK_WALL_H - 6:HAK_WALL_H] = C['timber_d']  # 軒下
        #! 上の帯（50..66）は変種が塗り替える。既定は生成りの漆喰。
        v[fx, fy, 50:HAK_WALL_H - 6] = C['cream']
        #! 柱（素木。**面の両端だけ**——タイルするとマス境に 1 本になる）。
        span = fx if not vert else fy
        lo, hi = span.start, span.stop
        for p in (lo, hi - 3):
            if vert:
                v[fx, p:p + 3, 8:HAK_WALL_H] = C['oak']
            else:
                v[p:p + 3, fy, 8:HAK_WALL_H] = C['oak']
        #! 縁側の濡縁（外へ 8 vox。z 10..15 だけ＝接地しない張り出し）。
        if side == 'n':
            dx, dy = slice(c0 - 2, c1 + 2), slice(0, c0 + 2)
        elif side == 's':
            dx, dy = slice(c0 - 2, c1 + 2), slice(c1 - 2, W)
        elif side == 'w':
            dx, dy = slice(0, c0 + 2), slice(c0 - 2, c1 + 2)
        else:
            dx, dy = slice(c1 - 2, W), slice(c0 - 2, c1 + 2)
        v[dx, dy, 10:15] = C['oak_l']
        v[dx, dy, 14] = C['oak_l']
        #! 板目（縁と平行の筋）と、床下の束（**マスの中**の面の際。接地はマスの内側だけ）。
        if vert:
            for p in range(dy.start + 1, dy.stop, 5):
                v[dx, p, 14] = C['board_d']
        else:
            for p in range(dx.start + 1, dx.stop, 5):
                v[p, dy, 14] = C['board_d']
        for p in range(lo + 4, hi - 3, 10):
            if vert:
                v[fx, p:p + 3, 1:10] = C['timber_d']
            else:
                v[p:p + 3, fy, 1:10] = C['timber_d']
    #! 開口（変種で振る）。**上の帯（長押と軒下の間）だけ**に置く——腰は板のまま。
    #! 北面にも置く（一人称は北面を正面から見る。デザイン6 その3 で方針転換）。
    #! 置く側（terrain_view の切妻モード）はマスの列で変種を選ぶので、
    #! _01 板壁＋漆喰 / _02 蔀戸の帯 / _03 連子の小窓 が**ベイの律動**として並ぶ。
    for side in outward:
        if side == 'n':
            fx2, fy2 = slice(c0 + 4, c1 - 4), slice(c0, c0 + 2)
            axis_lo, axis_hi, vert2 = c0 + 4, c1 - 4, False
        elif side == 's':
            fx2, fy2 = slice(c0 + 4, c1 - 4), slice(c1 - 2, c1)
            axis_lo, axis_hi, vert2 = c0 + 4, c1 - 4, False
        elif side == 'w':
            fx2, fy2 = slice(c0, c0 + 2), slice(c0 + 4, c1 - 4)
            axis_lo, axis_hi, vert2 = c0 + 4, c1 - 4, True
        else:
            fx2, fy2 = slice(c1 - 2, c1), slice(c0 + 4, c1 - 4)
            axis_lo, axis_hi, vert2 = c0 + 4, c1 - 4, True
        if variant == 2:
            #! 蔀戸の帯（白い紙＋粗い桟。桟は 8 vox ピッチ——細かくすると元の木阿弥）。
            v[fx2, fy2, 50:66] = C['shoji']
            for p in range(axis_lo + 3, axis_hi, 8):
                if vert2:
                    v[fx2, p:p + 2, 50:66] = C['timber']
                else:
                    v[p:p + 2, fy2, 50:66] = C['timber']
            v[fx2, fy2, 57:59] = C['timber']
        elif variant == 3:
            #! 連子の小窓（中央だけ。まわりは漆喰のまま）。
            mid = (axis_lo + axis_hi) // 2
            if vert2:
                v[fx2, mid - 6:mid + 6, 52:64] = C['glass']
                for p in range(mid - 6, mid + 6, 3):
                    v[fx2, p, 52:64] = C['timber_d']
                v[fx2, mid - 7:mid + 7, 50:52] = C['timber_d']
                v[fx2, mid - 7:mid + 7, 64:66] = C['timber_d']
            else:
                v[mid - 6:mid + 6, fy2, 52:64] = C['glass']
                for p in range(mid - 6, mid + 6, 3):
                    v[p, fy2, 52:64] = C['timber_d']
                v[mid - 7:mid + 7, fy2, 50:52] = C['timber_d']
                v[mid - 7:mid + 7, fy2, 64:66] = C['timber_d']
    return [('main', v, (-8, -8, 0))]


def manor_roofslope_hak(name):
    """拝殿の切妻屋根の斜面 1 マス（茅葺き）。`_n` = 軒が北（南へ上がる）・`_s` = その逆。

    1 マスで **HAK_RISE（14 vox）**上がる。置く側（terrain_view の切妻モード）が
    「棟までの段数 × top_z」で積むので、**型の総高＝HAK_RISE がそのまま勾配**になる。
    下まで詰めた中実で焼く——妻（東西端）では断面がそのまま**刈り込んだ茅の切り口**になる。
    `manor_roofeave_*` は軒のマス（段 0）用で、北／南へ 8 vox の軒先が付く。
    """
    base = _split_style(name)[1]  # manor_roofslope_<n|s> / manor_roofeave_<n|s>
    side = base.rsplit('_', 1)[-1]
    eave = 'roofeave' in base
    rng = rng_for(name)
    ext = 8 if eave else 0
    W = V + ext
    v = np.zeros((V, W, HAK_RISE), np.uint8)
    bundle = rng.choice([C['kaya'], C['kaya_l'], C['kaya_d'], C['kaya_g']],
                        size=(V // 2 + 1, W // 2 + 1), p=[0.44, 0.22, 0.22, 0.12])
    #! 軒は低い側に付く——`_n` は北（型の y 0..7・origin −8）、`_s` は南（y 32..39・origin 0）。
    for y in range(W):
        yy = y - ext if side == 'n' else y
        if (yy < 0) or (yy >= V):
            #! 軒先の厚い切り口。**z=0 に置かない**——軒はマスの外（負のマス）に張り出すので、
            #! 接地すると footprint 照合が floor 除算の食い違いで落ちる（時計塔の罠）。
            z0, surf = 1, 4
        else:
            t = yy if side == 'n' else (V - 1 - yy)
            z0, surf = 0, 1 + (t * (HAK_RISE - 1)) // (V - 1)
        for x in range(V):
            v[x, y, z0:surf] = C['kaya_d']
            v[x, y, max(z0, surf - 2):surf] = bundle[x // 2, y // 2]
    #! 苔と煤（天面にだけ、塊で）。
    for _ in range(int(rng.integers(2, 5))):
        cx, cy = int(rng.integers(0, V - 4)), int(rng.integers(0, W - 4))
        w_, d_ = int(rng.integers(3, 7)), int(rng.integers(3, 7))
        for x in range(cx, min(cx + w_, V)):
            for y in range(cy, min(cy + d_, W)):
                zz = 0
                for z in range(HAK_RISE - 1, -1, -1):
                    if v[x, y, z]:
                        zz = z
                        break
                v[x, y, zz] = C['moss_d'] if rng.random() < 0.5 else C['kaya_g']
    return [('main', v, (0, -ext if side == 'n' else 0, 0))]


def manor_ridge_hak(name):
    """拝殿の棟（箱棟）。切妻の頂で北と南の斜面が出会う線に**またがって**載る
    （型 32×12・origin (0,-6)。置く側が棟の南側のマスの北縁に置く）。
    博麗は千木・鰹木を持たない——**簡素であることが博麗の記号**（千木は守矢に取ってある）。
    """
    v = np.zeros((V, 12, 13), np.uint8)
    #! 茅を束ねて丸めた棟。断面は蒲鉾形。**z=0 は空ける**（origin y=-6 で棟の北半分が
    #! 負のマスに掛かる——接地すると footprint 照合の罠を踏む。軒先と同じ判断）。
    for y in range(12):
        half = abs(y - 5.5)
        h = 1 + int(10 - (half * half) // 4)
        v[:, y, 1:h] = C['kaya_d']
        v[:, y, max(1, h - 2):h] = C['kaya']
    #! 竹の押さえ（棟と平行の筋）と、要所の縄。
    for z in (4, 8):
        v[:, 1, z] = C['mune']
        v[:, 10, z] = C['mune']
    for x in range(2, V, 9):
        v[x:x + 1, 0:12, 9:11] = C['mune']
    return [('main', v, (0, -6, 0))]


def manor_gable_hak(name):
    """拝殿の妻壁 1 辺（東西端の、屋根の斜面の下を塞ぐ板）。高さ 1 マスの型を
    置く側が **sz で段の高さへ伸縮**する（cave_mound の z 伸縮と同じ流儀）。
    生成りの壁＋中央の束柱、上端は破風板の濃い見切り。
    """
    side = _split_style(name)[1].rsplit('_', 1)[-1]
    th = 4
    v = np.zeros((V, V, V), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, C['cream'])
    put(14, 17, 0, V, C['oak'])       # 中央の束柱
    put(0, 2, 0, V, C['oak'])         # 端の柱
    put(V - 2, V, 0, V, C['oak'])
    put(0, V, V - 3, V, C['timber_d'])  # 破風板
    return [('main', v, (0, 0, 0))]


def manor_innerwall_hak(name):
    """拝殿の内壁 1 辺（板張りの腰＋生成りの上壁）。紅魔館の赤白と同じ枠で材だけ和風。"""
    side = _split_style(name)[1].rsplit('_', 1)[-1]
    rng = rng_for(name)
    th, height = 3, 64
    v = np.zeros((V, V, height), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, 22, C['oak'])
    for p in range(0, V, 5):
        put(p, p + 1, 1, 22, C['timber_d'])
    put(0, V, 22, 26, C['timber'])
    put(0, V, 26, height, C['cream_l'])
    for _ in range(3):
        a = int(rng.integers(0, V - 5))
        z = int(rng.integers(30, height - 6))
        put(a, a + 5, z, z + 5, C['cream'])
    return [('main', v, (0, 0, 0))]


def torii_great(name):
    """**博麗神社の大鳥居**（朱の明神鳥居・半身）。Q2 の決定「二次創作でメジャーに
    なっているものは採用する——朱塗りの鳥居」の本体である。

    参道の両脇の 2×2 マスの柱の塊（地図の実測 (94..95,12..13) と (103..104,12..13)）に
    片脚ずつ立て、**笠木は参道の中心（4.5 マス先）まで張り出して**左右で出会う。
    全幅 10 マス ＝ 320 vox は一枚型の上限 256 を超えるので半身 2 枚に割る——
    「一棟を設計して型に切って並べる」（§5.8）のいちばん小さい例。
    接地（z<8）は**自分の柱の 2 マスの中だけ**（張り出しの規約。負のマスの footprint は
    floor 除算の食い違いで照合落ちする＝時計塔の罠）。柱の内側の足元に**狛犬**を彫る
    （§4.2 ⑥。置き場のマスを増やさずに済む）。
    """
    right = name.endswith('_r')
    #! 高さは決めたこと（デザイン6 その4「参道入り口にある鳥居の高さをあと
    #! 3 ブロック高くして」）で **+96 vox（3 マス）**——総高 約 6.8 マス の大鳥居。
    H = 224
    W = 184  # 柱のマスの西端 → 参道の中心（5.5 マス ＋ 笠木の端の遊び）
    v = np.zeros((W, 64, H), np.uint8)
    #! 台石（亀腹）と黒い根巻き。
    v[18:47, 18:47, 0:4] = C['wall_d']
    v[20:45, 20:45, 3] = C['wall']
    cx, cy = 32, 32
    for x in range(W):
        for y in range(64):
            d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
            if d2 <= 74:  # r ≈ 8.6 の柱（高くしたぶん一回り太く）
                v[x, y, 3:200] = C['shu']
                if y >= cy + 4:
                    v[x, y, 3:200] = C['shu_l']  # 南面は日を受けて明るい
                if y <= cy - 5:
                    v[x, y, 3:200] = C['shu_d']
            if d2 <= 92:  # 根巻き（黒）
                v[x, y, 3:18] = C['obs']
    #! 貫（柱を貫いて参道側へ。西端は柱の外へ少し出る）。
    v[10:176, 27:37, 158:170] = C['shu']
    v[10:16, 26:38, 158:170] = C['shu_d']  # 木口
    v[10:176, 27:37, 169] = C['shu_l']
    #! 額束（中心で左右の半身が出会う。白い額に墨の帯——この縮尺で字は潰れる）。
    v[166:176, 26:38, 170:192] = C['shu_d']
    v[168:176, 36:38, 174:190] = C['nuki']
    v[170:176, 36:38, 180:184] = C['ink']
    #! 島木と笠木（**反り**——外端 40 vox で 5 vox 持ち上がる。明神鳥居の記号）。
    for x in range(2, 176):
        lift = ((40 - x) * 5) // 40 if x < 40 else 0
        v[x, 26:38, 192 + lift:202 + lift] = C['shu_d']
        v[x, 24:40, 202 + lift:216 + lift] = C['shu']
        v[x, 24:40, 215 + lift] = C['shu_l']
    #! 狛犬（柱の内側の足元。台座＋胴＋頭＋鬣。石なので kPlain の灰）。
    v[44:60, 42:58, 0:5] = C['wall_d']
    v[46:58, 44:56, 5:8] = C['wall']
    v[47:57, 45:55, 8:18] = C['rock_l']       # 胴（うずくまり）
    v[48:56, 44:50, 15:24] = C['rock_l']      # 頭（南向き）
    v[48:56, 44:46, 20:23] = C['rock_d']      # 鬣
    v[50:54, 44:45, 17:19] = C['rock_dd']     # 口（阿形）
    v[47:49, 52:55, 5:12] = C['rock']         # 後脚
    v[55:57, 52:55, 5:12] = C['rock']
    if right:
        v = v[::-1, :, :].copy()
        return [('main', v, (-(W - 64), 0, 0))]
    return [('main', v, (0, 0, 0))]


def sakura_hak(name):
    """**桜の木**（§4.2 ④「桜が付くのは博麗だけ＝識別子」）。参道沿い（街路樹の口）と
    神社の裏（BUILDING_7 の目印）に立つ。花の塊は珊瑚の桃色＋白の 3 段。
    接地は幹の 1 マスだけ（張り出しの規約）。"""
    rng = rng_for(name)
    W = 64
    H = 78
    v = np.zeros((W, W, H), np.uint8)
    #! 幹（すこし傾ぐ）と太い枝。
    lean = int(rng.integers(-4, 5))
    for z in range(0, 40):
        ox = 30 + (lean * z) // 40
        v[ox:ox + 5, 30:35, z] = C['bark']
        v[ox + 1:ox + 3, 31:33, z] = C['bark_l']
    for bx, by in ((-12, -6), (10, 4), (-4, 10)):
        for t in range(14):
            x = 32 + (bx * t) // 14
            y = 32 + (by * t) // 14
            v[x:x + 3, y:y + 3, 34 + (t * 10) // 14] = C['bark']
    #! 花の雲（塊ごとに 1 色＝罠 38）。
    blobs = []
    for _ in range(7):
        bx = 32 + int(rng.integers(-16, 17))
        by = 32 + int(rng.integers(-14, 15))
        bz = int(rng.integers(44, 64))
        r = int(rng.integers(8, 13))
        shade = rng.choice([C['hana'], C['hana'], C['hana_d'], C['hana_w']])
        blobs.append((bx, by, bz, r, shade))
    for x in range(W):
        for y in range(W):
            for (bx, by, bz, r, shade) in blobs:
                d2 = ((x - bx) ** 2) + ((y - by) ** 2)
                if d2 <= r * r:
                    dz = int((r * r - d2) ** 0.5 * 0.55)
                    z0 = max(0, bz - dz)
                    z1 = min(H, bz + dz + 1)
                    if z1 > z0:
                        v[x, y, z0:z1] = shade
    _ground_center_only(v, W)
    return [('main', v, (-16, -16, 0))]


def bunsha_hak(name):
    """**守矢神社分社**（町 5 の BUILDING_1。マミゾウが座る東の小社）。
    原作どおり「巣箱サイズの分社」（§4.2 ⑥）——2×2 マスの小さな社に、守矢の記号の
    **太い注連縄**とミニ御柱 4 本を持たせる。敷地（3×3 の塊）の目印としてまるごと建つ。"""
    W = 64
    H = 88
    v = np.zeros((W, W, H), np.uint8)
    #! 基壇と正面（南）の階段。
    v[6:58, 8:52, 0:10] = C['wall_d']
    v[8:56, 10:50, 9] = C['wall']
    v[24:40, 52:58, 0:4] = C['wall_d']
    v[24:40, 52:56, 4:7] = C['wall']
    #! 躯体（素木の板壁・南面に扉と紙垂）。
    v[16:48, 16:42, 10:40] = C['oak']
    for x in range(16, 48, 4):
        v[x, 16:42, 10:40] = C['oak_l']
    v[26:38, 40:42, 12:36] = C['timber_d']   # 扉
    v[31:33, 40:42, 12:36] = C['oak_l']      # 引手の割り
    #! 屋根（切妻。棟は東西）。
    for y in range(10, 52):
        h = 16 - (abs(y - 30) * 16) // 22
        if h < 2:
            h = 2
        surf = 40 + h
        v[8:56, y, 40:surf] = C['kaya_d']
        v[8:56, y, surf - 2:surf] = C['kaya'] if (y % 4) else C['kaya_g']
    v[8:56, 28:33, 54:58] = C['kaya_d']      # 箱棟
    #! 千木（東西の棟端に立つ 2 対の角）と鰹木 3 本——守矢の「大社」の記号のミニチュア。
    for x0 in (9, 51):
        v[x0:x0 + 2, 24:30, 52:70] = C['oak_l']
        v[x0 + 2:x0 + 4, 31:37, 52:70] = C['oak_l']
    for x0 in (20, 30, 40):
        v[x0:x0 + 5, 27:34, 56:61] = C['bark']
    #! 注連縄（正面の軒下に太く一本＋紙垂 3 枚。§4.2「極太の注連縄」のミニ版）。
    v[12:52, 42:47, 32:38] = C['hay']
    for x0 in range(14, 50, 7):
        v[x0:x0 + 2, 42:46, 30:34] = C['hay_d']
    for x0 in (18, 30, 42):
        v[x0:x0 + 3, 44:46, 24:32] = C['nuki']
    #! ミニ御柱（四隅）。
    for (x0, y0) in ((1, 12), (59, 12), (1, 48), (59, 48)):
        v[x0:x0 + 4, y0:y0 + 4, 0:26] = C['oak_l']
        v[x0:x0 + 4, y0:y0 + 4, 25] = C['oak']
    return [('main', v, (0, 0, 0))]


def haiden_hak(name):
    """**拝殿の顔**（BUILDING_0 のマス＝北面の彫り込みに立つ賽銭箱と鈴）。
    参道を上りきった所。箱の面は北（参道側）へ向ける——カメラは南からだが、
    このマスは屋根外し（層 2）の穴の中でしか見えないので、絵の向きは参拝者に合わせる。"""
    v = np.zeros((V, V, 46), np.uint8)
    #! 階段（北から 2 段）。
    v[6:26, 2:6, 0:3] = C['oak']
    v[6:26, 5:10, 0:6] = C['oak']
    v[6:26, 5, 5] = C['oak_l']
    #! 賽銭箱（格子の天板・銭口の桟）。
    v[8:24, 12:26, 6:20] = C['timber']
    v[8:24, 12:26, 19] = C['timber_d']
    for x in range(9, 23, 3):
        v[x, 12:26, 19] = C['oak_l']
    v[8:24, 12:14, 6:20] = C['timber_d']
    #! 鈴緒（縄）と鈴。
    v[14:17, 17:20, 20:36] = C['hay']
    v[14:17, 17:20, 26:28] = C['crimson']
    v[12:20, 15:22, 36:43] = C['gold_d']
    v[13:19, 16:21, 42] = C['gold']
    return [('main', v, (0, 0, 0))]


def haiden_front_hak(name):
    """**拝殿の顔・一式**（デザイン6 その2。「本殿の正面が簡素過ぎる」という気づき＋
    参考画像＝入母屋の拝殿・唐破風の向拝・千鳥破風・太い注連縄と紙垂・台座の狛犬・石段）。

    カメラは南上空から北を向くので**北向きの壁面は 1 画素も映らない**。効くのは
    上から見える物だけ——①**向拝の庇**（唐破風の反りを北の軒先に付けた杉皮の屋根）
    ②庇の軒先の**外**に掛かる**太い注連縄＋紙垂 4＋房 2**（軒の下に吊るすと庇に隠れる。
    実測 dz/dy < tan(俯角)）③屋根の斜面に載る**千鳥破風**（妻面でなく翼の面と棟が読める）
    ④**台座の狛犬 1 対** ⑤中央の石段と賽銭箱・鈴。

    型は 7 マス × 5 マス × 150。anchor は拝殿の彫り込み（BUILDING_0 のマス）で、
    origin (-96,-74,0) ＝ x は扉の中心線に対称・y は北へ 2.3 マス 張り出す。
    **z=0 の接地は anchor のマスの中だけ**（負のマスの footprint の罠）——狛犬の台座も柱も
    z=1 から立てる（1 層の浮きは見えない＝龍神像の亀腹と同じ扱い）。
    朱は使わない（Q2——社殿は素木のまま）。
    """
    rng = rng_for(name)
    W, D, H = 224, 160, 150
    v = np.zeros((W, D, H), np.uint8)
    cx = 112  # 扉の中心線

    #! 接地の座布団（anchor のマス x 96..128 / y 74..106 だけ z=0 を持つ）。
    v[98:126, 76:104, 0:1] = C['wall_d']

    #! --- 狛犬（背の高い台座・北向きに座る。西=阿・東=吽）---
    #! 台座は参考画像に合わせて高く（1.2 マス）。低いと軒の面に食われる（俯角の罠）。
    for west in (True, False):
        def X(a, b):
            return (slice(a, b) if west else slice(W - b, W - a))
        v[X(8, 36), 16:42, 1:34] = C['wall_d']       # 台座（切石）
        v[X(10, 34), 18:40, 32:34] = C['wall']
        v[X(12, 32), 20:38, 34:40] = C['rock']       # 座
        v[X(13, 31), 23:39, 40:58] = C['rock_l']     # 胴（うずくまり）
        v[X(15, 29), 17:27, 52:70] = C['rock_l']     # 頭（北の参道を向く）
        v[X(15, 29), 25:29, 60:66] = C['rock_d']     # 鬣
        v[X(14, 30), 36:40, 40:52] = C['rock_d']     # 尾
        if west:
            v[X(18, 26), 17:18, 57:60] = C['rock_dd']  # 阿形（口を開く）
        v[X(13, 17), 23:27, 36:52] = C['rock']       # 前脚
        v[X(27, 31), 23:27, 36:52] = C['rock']

    #! --- 向拝の柱 4 本と冠木（素木）---
    #! 本屋根の軒（頂 86）より**上に出ないものは、この俯角では軒の面に食われて
    #! 1 画素も見えない**（初版で実測——庇 64..82 は丸ごと消えた）。柱・冠木・庇・縄は
    #! 北へ張り出し、庇の面は軒の頂を 20 vox 超えるまで持ち上げる。
    #! 柱は庇の裏まで届かせ、**冠木は持たない**——冠木の黒い横棒は北にあるほど画面で
    #! 上に描かれ、細くしても注連縄と紙垂の帯を分断した（v5/v6 で実測）。
    #! 参考画像でも水平の主役は縄で、梁は縄の陰にほぼ隠れている。
    for px in (44, 84, 140, 180):
        v[px:px + 8, 8:16, 1:70] = C['oak']
        v[px + 2:px + 6, 8:16, 1:70] = C['oak_l']
        v[px - 1:px + 9, 7:17, 1:6] = C['wall_d']    # 沓石（z=1 から＝接地しない）

    #! --- 石敷きの前庭（参考画像の敷石。2 vox の薄さなので sprite と喧嘩しない）---
    for x in range(72, 152):
        for y in range(16, 74):
            shade = C['flag'] if (((x // 8) + (y // 8)) % 2) else C['flag_l']
            if ((x % 8) == 0) or ((y % 8) == 0):
                shade = C['flag_d']
            v[x, y, 1:3] = shade

    #! --- 唐破風の庇（杉皮葺き。北の軒先の中央が反り上がる）---
    edge_top = [0] * W  # 軒先の稜の高さ（注連縄を乗せる位置）
    for y in range(4, 62):
        zs = 76 + ((y - 4) * 36) // 57  # 南へ上がる屋根勾配（76→112。本屋根の軒 86 を超える）
        for x in range(30, 194):
            lift = 0
            if y < 20:  # 軒先の帯だけ唐破風の反り
                dx_ = abs(x - cx)
                lift = max(0, 12 - (dx_ * dx_) // 240)
            z1 = zs + lift
            v[x, y, z1 - 6:z1] = C['sugi']
            v[x, y, z1 - 1] = C['sugi_l'] if ((y // 5) % 2) else C['sugi']
            if y < 10:
                v[x, y, z1 - 6:z1 - 4] = C['hiwada_d']  # 軒裏の影
            if y == 5:
                edge_top[x] = z1
    v[30:194, 58:62, 108:116] = C['timber_d']        # 棟押さえ（庇の南縁）
    #! 拝みの金具（懸魚の代わりの一点。金はここだけ）。
    v[cx - 3:cx + 3, 4:7, 96:104] = C['gold_d']

    #! --- 注連縄（**庇の軒先の稜の上に乗せる**。北向きの縦面はこの俯角では
    #!     背面＝1 画素も映らないので、吊るさず稜の上へ——上面が丸ごと見える）---
    for x in range(34, 190):
        dx_ = abs(x - cx)
        r = 9 - (dx_ // 30)                          # 中央 9 → 端 6（参考画像の「極太」）
        zc = edge_top[x] if edge_top[x] else 88
        shade = C['hay'] if (((x + zc) // 4) % 2) else C['hay_d']
        v[x, 2:2 + r + 3, zc - 3:zc + r - 2] = shade
        v[x, 2:5, zc - 3:zc + r - 5] = C['straw_d']  # 北縁の影で縄の丸みを言う
    #! 紙垂 4 枚——**縄から北へ流れ落ちる大きな段々**（各段の上面が白く見える。
    #! 垂直の紙は北向きの面＝背面で 1 画素も映らない。冠木より北なので全段が
    #! 手前に描かれる）。房 2 つも同じく北へ。
    for sx in (54, 88, 132, 166):
        zc = edge_top[sx] if edge_top[sx] else 88
        for i in range(5):
            yy = 14 - (i * 3)
            off = 3 if (i % 2) else -3
            v[sx - 4 + off:sx + 8 + off, yy:yy + 5, zc - 8 - (i * 7):zc - 1 - (i * 7)] = C['nuki']
    for tx in (72, 148):
        zc = edge_top[tx] if edge_top[tx] else 88
        v[tx:tx + 8, 8:16, zc - 12:zc + 2] = C['straw_d']
        v[tx + 1:tx + 7, 4:11, zc - 22:zc - 10] = C['hay_d']
        v[tx + 2:tx + 6, 2:7, zc - 30:zc - 20] = C['straw_d']

    #! --- 中央の石段と縁（sprite が跨ぐので低く 2 段だけ）---
    v[96:128, 66:76, 1:4] = C['wall_d']
    v[97:127, 66:70, 4:8] = C['wall_d']
    v[97:127, 66:67, 3] = C['wall']

    #! --- 賽銭箱と鈴（彫り込みのマスの中。屋根外しの穴から見える）---
    v[98:126, 84:104, 8:26] = C['timber']
    for x in range(100, 124, 4):
        v[x, 84:104, 25] = C['oak_l']                # 天板の桟
    v[98:126, 84:86, 8:26] = C['timber_d']
    v[108:116, 90:96, 42:52] = C['gold_d']           # 鈴
    v[110:114, 91:95, 51] = C['gold']
    v[110:113, 92:95, 26:42] = C['hay']              # 鈴緒

    #! --- 千鳥破風（屋根の斜面の上。翼の面と棟で読ませる）---
    for y in range(92, 148):
        srow_off = y - 74                            # 74 = 屋根の北縁（row 31.0）
        base = 72 + (srow_off * 14) // 32 + 2        # 斜面の 2 vox 上に浮く
        apex = 126
        if base + 6 >= apex:
            break
        t = (y - 92) / 56.0
        half = int(52 * (1.0 - t * 0.55))
        for x in range(cx - half, cx + half + 1):
            dx_ = abs(x - cx)
            zt = apex - (dx_ * (apex - base)) // max(1, half)
            if zt <= base:
                continue
            v[x, y, base:zt] = C['kaya_d']
            band = C['kaya'] if (((zt // 4) + (x // 16)) % 2) else C['kaya_l']
            v[x, y, zt - 2:zt] = band
            if dx_ >= half - 3:
                v[x, y, zt - 3:zt] = C['timber_d']   # 破風板（上から見える縁）
    v[cx - 3:cx + 3, 92:140, 122:127] = C['mune']    # 箱棟
    v[cx - 4:cx + 4, 92:96, 108:118] = C['cream']    # 妻の顔（前縁の白）
    v[cx - 2:cx + 2, 92:95, 100:110] = C['gold_d']   # 懸魚の金具

    return [('main', v, (-96, -74, 0))]


def ladder_hak(name):
    """**屋根への梯子**（BUILDING_6「神社の屋根の上」のマス）。ドレミーの昼寝場所への
    道しるべ。南の壁に立て掛けた素木の梯子。"""
    H = 72
    v = np.zeros((V, V, H), np.uint8)
    for z in range(H):
        y = 8 + (z * 20) // H
        for x0 in (10, 20):
            v[x0:x0 + 2, y:y + 2, z] = C['oak']
        if (z % 9) == 4:
            v[10:22, y:y + 2, z:z + 2] = C['oak_l']
    return [('main', v, (0, 0, 0))]


def engawa_hak(name):
    """**神社縁側**（BUILDING_3 のマス。霊夢が茶を啜る東の縁）。館の東面の外に置く
    踏み段と沓脱石。縁側そのものは拝殿の壁（manor_wall_hak）が持っている。"""
    v = np.zeros((V, V, 20), np.uint8)
    #! 濡縁の張り出しへ上がる踏み板。
    v[0:12, 6:26, 8:14] = C['oak_l']
    for y in range(7, 26, 5):
        v[0:12, y, 13] = C['board_d']
    v[4:8, 8:11, 1:8] = C['timber_d']
    v[4:8, 21:24, 1:8] = C['timber_d']
    v[12:20, 10:22, 0:6] = C['oak']
    v[12:20, 10:22, 5] = C['oak_l']
    #! 沓脱石。
    v[20:28, 12:20, 0:4] = C['rock']
    v[21:27, 13:19, 3] = C['rock_l']
    return [('main', v, (0, 0, 0))]


# ---- 河童のバザーの意匠（2026-08-19 デザイン7。町 6）----
#
# 基準は 「河童のバザー」と §5.9 の続き。
# **外せない 1 点は「錆びた波トタンの片流れ＋崖の六角柱の縦縞」**（§4.4）。
#
# 地図の壁の塊は**中庭を囲む 3 マス幅の帯が 6 件**（203 / 125 / 119 / 89 / 71 / 47 マス）で、
# これを屋敷として読むと「**市庭を囲む工房の長屋**」になる。屋根は片流れ——マスごとに
# 「外側の面までの距離」を段にして、軒を外へ・高い面を中庭へ向ける
# （`TownStyle::manor_roof_shed`）。中庭は屋外のまま（`manor_open_court`）。
KAP_WALL_H = 54   # 工房の壁 1 層（1.7 マス。低い長屋——高いと沢の崖に負ける）
KAP_RISE = 14     # 片流れが 1 マスで上がる高さ（3 マス幅の帯なら中庭側で +42 vox）


def _kap_corrugate(v, z_of, along_x, plate):
    """波トタンの畝を天面へ 1 vox 立てる。**畝は流れ（勾配）の向きに走る**。

    `z_of[x, y]` がその柱の天面の次の z（＝葺き終わりの高さ）。`along_x` が真なら
    畝は x 方向に走る（＝勾配が x）ので、畝の山と谷は y で切り替わる。
    **±1 vox しか動かさない**——波は構造であって荒れではない（設計書 §6）。
    """
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            top = int(z_of[x, y])
            if top <= 0:
                continue
            crest = ((y if along_x else x) % 4) < 2
            colour = plate[x // KAP_PLATE, y // KAP_PLATE]
            v[x, y, max(0, top - 2):top] = colour
            if crest and (top < v.shape[2]):
                v[x, y, top] = colour


#: トタン 1 枚の大きさ（vox）。**8 では小さすぎた**——マスに 4 枚並ぶと錆と生地が
#: 市松に見えて「波トタン」ではなく「タイル」に読めた（合成フレームで実測）。
KAP_PLATE = 16


def _kap_tin_plate(rng, shape):
    """トタン 1 枚ぶんの色（**塊ごとに 1 色**＝罠 38）。**地は生トタンだけ**。

    錆をこの表に混ぜてはならない。1 枚 16 vox ＝ マスに 2×2 枚なので、錆を混ぜると
    マスの格子に乗った**赤白の市松**になる（2 度踏んだ。合成フレームで実測）。
    錆は下の「錆の広がり」で**格子に乗らない塊**として置く。
    """
    #! **明るい段は少なく。**トタンは白ではなく亜鉛の灰なので、`tin_l`（鋼の白）を
    #! 主にすると屋根が紙のように白く飛ぶ（合成フレームで実測）。
    return rng.choice([C['tin'], C['tin_l'], C['tin_g']],
                      size=shape, p=[0.40, 0.12, 0.48]).astype(np.uint8)


def manor_wall_kap(name):
    """**河童の工房の壁 1 マス**（板とブリキの継ぎ足し・高さ 1.7 マス・**緑青の配管つき**）。

    §4.4 ③「壁は板とブリキの継ぎ足し」④「配管を壁から抜ける太い管 1 本＝遠目で
    『河童』の印」。配管は**外に面した辺の外へ 5 vox 張り出す**（型 44×44・origin (-6,-6)。
    張り出しは z≥8 だけ——接地がマスの外に出ると footprint 照合で落ちる罠を避ける）。

    変種で面を振る（_01 板が主 / _02 トタンの大きな継ぎ足し＋小窓 / _03 横桟の
    シャッター＋裸電球）。**乱数ではなく変種で振る**のは、面じゅうが同じ顔になるのを
    避けるため（デザイン6 その3 のベイの律動と同じ話）。
    """
    base = _split_style(name)[1]  # manor_wall_<slice>_<nn>
    parts = base.split('_')
    key = parts[2]
    variant = int(parts[3]) if ((len(parts) > 3) and parts[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    ext = 6
    W = V + (ext * 2)
    v = np.zeros((W, W, KAP_WALL_H), np.uint8)
    c0, c1 = ext, ext + V
    #! 基礎（コンクリの土間。マスいっぱい＝罠 5）。
    v[c0:c1, c0:c1, 0:6] = C['wall_d']
    v[c0:c1, c0:c1, 5] = C['wall']
    #! 躯体は**板とブリキの縦の継ぎ足し**（板 3 vox・トタン 6 vox の帯で交互に）。
    #! 板だけの初版は焦茶に沈み、中庭に向いた面が影の中で真っ黒に見えた（合成フレーム実測）。
    #! §4.4 ③「壁は板とブリキの継ぎ足し」は**素の面**で言うのが正しい。
    for x in range(c0, c1):
        band = ((x - c0) // 6) % 3
        if band == 2:
            colour = [C['tin_g'], C['tin'], C['tin_l']][((x - c0) // 3) % 3]
        else:
            colour = [C['board_l'], C['board'], C['oak'], C['board_d']][((x - c0) // 3) % 4]
        v[x, c0:c1, 6:KAP_WALL_H] = colour

    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        if side == 'n':
            face = (slice(c0, c1), slice(c0, c0 + 2))
            out_face = (slice(c0, c1), slice(c0 - ext, c0))
        elif side == 's':
            face = (slice(c0, c1), slice(c1 - 2, c1))
            out_face = (slice(c0, c1), slice(c1, c1 + ext))
        elif side == 'w':
            face = (slice(c0, c0 + 2), slice(c0, c1))
            out_face = (slice(c0 - ext, c0), slice(c0, c1))
        else:
            face = (slice(c1 - 2, c1), slice(c0, c1))
            out_face = (slice(c1, c1 + ext), slice(c0, c1))
        vert = side in ('w', 'e')
        #! ブリキの継ぎ足し。**矩形で貼る**（板の上に後から当てたもの）。
        patches = 2 if variant == 1 else 4
        for _ in range(patches):
            a0 = int(rng.integers(0, V - 8))
            z0 = int(rng.integers(8, KAP_WALL_H - 12))
            aw = int(rng.integers(7, 15))
            zh = int(rng.integers(9, 18))
            colour = C['tin'] if rng.random() < 0.6 else C['tin_g']
            if vert:
                v[face[0], c0 + a0:c0 + min(V, a0 + aw), z0:z0 + zh] = colour
            else:
                v[c0 + a0:c0 + min(V, a0 + aw), face[1], z0:z0 + zh] = colour
        #! 継ぎ目の錆だれ（板の上を垂れる筋）。
        for _ in range(3):
            a0 = c0 + int(rng.integers(0, V - 2))
            z0 = int(rng.integers(10, KAP_WALL_H - 16))
            if vert:
                v[face[0], a0:a0 + 2, z0:z0 + 14] = C['rust_d']
            else:
                v[a0:a0 + 2, face[1], z0:z0 + 14] = C['rust_d']
        #! **緑青の太い配管**（外へ 5 vox 張り出す横引き 1 本）。継ぎ手（フランジ）を 2 つ。
        pz = 30 if (variant != 3) else 24
        if vert:
            v[out_face[0], c0:c1, pz:pz + 6] = C['pipe']
            v[out_face[0], c0:c1, pz + 4:pz + 6] = C['pipe_d']
            for a0 in (c0 + 6, c1 - 10):
                v[out_face[0], a0:a0 + 3, pz - 1:pz + 7] = C['pipe_d']
        else:
            v[c0:c1, out_face[1], pz:pz + 6] = C['pipe']
            v[c0:c1, out_face[1], pz + 4:pz + 6] = C['pipe_d']
            for a0 in (c0 + 6, c1 - 10):
                v[a0:a0 + 3, out_face[1], pz - 1:pz + 7] = C['pipe_d']
        if variant == 2:
            #! 小窓（トタンを切り抜いた窓。硝子は明るい青）。
            a0 = c0 + 12
            if vert:
                v[face[0], a0:a0 + 9, 34:44] = C['glass_l']
                v[face[0], a0:a0 + 9, 33:34] = C['iron']
                v[face[0], a0:a0 + 9, 44:45] = C['iron']
            else:
                v[a0:a0 + 9, face[1], 34:44] = C['glass_l']
                v[a0:a0 + 9, face[1], 33:34] = C['iron']
                v[a0:a0 + 9, face[1], 44:45] = C['iron']
        if variant == 3:
            #! 横桟のシャッター（工房の間口）と、軒下の裸電球。
            for z0 in range(10, 44, 5):
                if vert:
                    v[face[0], c0 + 6:c1 - 6, z0:z0 + 3] = C['tin_d']
                else:
                    v[c0 + 6:c1 - 6, face[1], z0:z0 + 3] = C['tin_d']
            bz = KAP_WALL_H - 8
            if vert:
                v[out_face[0], c0 + 14:c0 + 18, bz:bz + 4] = C['bulb']
                v[face[0], c0 + 15:c0 + 17, bz + 3:bz + 8] = C['iron']
            else:
                v[c0 + 14:c0 + 18, out_face[1], bz:bz + 4] = C['bulb']
                v[c0 + 15:c0 + 17, face[1], bz + 3:bz + 8] = C['iron']
    #! 天端の押さえ（母屋。屋根の型がここから積み上がる）。
    v[c0:c1, c0:c1, KAP_WALL_H - 2:KAP_WALL_H] = C['timber_d']
    #! 張り出しは z≥8 だけ（接地はマスの中）。念のため掃除する。
    v[0:c0, :, 0:8] = 0
    v[c1:, :, 0:8] = 0
    v[:, 0:c0, 0:8] = 0
    v[:, c1:, 0:8] = 0
    return [('main', v, (-ext, -ext, 0))]


def manor_roofshed_kap(name):
    """**波トタンの片流れ屋根 1 マス**。`_n` = 軒が北（南へ上がる）… 4 姿勢。

    1 マスで **KAP_RISE（14 vox）**上がる。置く側（terrain_view の片流れモード）が
    「外側の面までの距離 × top_z」で積むので、**型の総高＝KAP_RISE がそのまま勾配**になる。
    `manor_roofeave_*` は軒のマス（段 0）用で、軒側へ 8 vox の**波打った軒先**が付く。

    畝（波）は**流れの向きに走る**——雨が流れる向きに畝が走るのが波トタンである。
    """
    base = _split_style(name)[1]  # manor_roofslope_<n|s|w|e>[_<nn>]
    parts = base.split('_')
    side = parts[2]
    eave = 'roofeave' in base
    rng = rng_for(name)
    ext = 8 if eave else 0
    along_x = side in ('w', 'e')  # 勾配が x 方向 ＝ 畝も x 方向
    if along_x:
        v = np.zeros((V + ext, V, KAP_RISE + 1), np.uint8)
    else:
        v = np.zeros((V, V + ext, KAP_RISE + 1), np.uint8)
    plate = _kap_tin_plate(rng, ((v.shape[0] // KAP_PLATE) + 1, (v.shape[1] // KAP_PLATE) + 1))
    low_first = side in ('n', 'w')  # 軒が型の手前側（origin を負へずらす）
    z_of = np.zeros((v.shape[0], v.shape[1]), np.int32)
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            a = x if along_x else y
            aa = a - ext if low_first else a
            if (aa < 0) or (aa >= V):
                #! 軒先。**z=0 に置かない**（マスの外に張り出すので、接地すると
                #! footprint 照合が floor 除算の食い違いで落ちる＝時計塔の罠）。
                v[x, y, 1:4] = C['tin_d']
                z_of[x, y] = 4
                continue
            t = aa if low_first else (V - 1 - aa)
            surf = 2 + ((t * (KAP_RISE - 2)) // (V - 1))
            v[x, y, 0:surf] = C['tin_d']
            z_of[x, y] = surf
    _kap_corrugate(v, z_of, along_x, plate)
    #! 錆の広がり（天面に塊で。**波の上だけ**にすると縞に見えるので面で置く）。
    #! **マスより小さく・数を絞る**——大きな錆は板の格子に乗って市松に読める。
    for _ in range(int(rng.integers(1, 4))):
        cx = int(rng.integers(0, max(1, v.shape[0] - 5)))
        cy = int(rng.integers(0, max(1, v.shape[1] - 5)))
        for x in range(cx, min(cx + int(rng.integers(3, 8)), v.shape[0])):
            for y in range(cy, min(cy + int(rng.integers(3, 8)), v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['rust'] if rng.random() < 0.6 else C['rust_d']
                        break
    if along_x:
        origin = (-ext if low_first else 0, 0, 0)
    else:
        origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_gable_kap(name):
    """**工房の妻壁 1 辺**（片流れの段の差で開いた縦の面を塞ぐトタンの板）。
    高さ 1 マスの型を置く側が **sz で段の高さへ伸縮**する（cave_mound の z 伸縮と同じ流儀）。
    畝は**縦**に走る（伸縮しても畝の本数が変わらない＝縦なら破綻しない）。
    """
    side = _split_style(name)[1].rsplit('_', 1)[-1]
    rng = rng_for(name)
    th = 4
    v = np.zeros((V, V, V), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    plate = _kap_tin_plate(rng, (V // 6 + 1,))
    for a in range(V):
        put(a, a + 1, 0, V, C['tin_d'] if (a % 4) < 2 else plate[a // 6])
    #! 上端の鼻隠しと、下端の水切り。
    put(0, V, V - 2, V, C['iron'])
    put(0, V, 0, 1, C['rust_d'])
    return [('main', v, (0, 0, 0))]


def crag_kap(name):
    """**玄武岩の柱状節理**（河童のバザーの崖。§4.4 ①「崖は六角柱の縦縞」）。

    「妖怪の山が活火山だった頃、溶岩が冷え固まってできた。底は六角形のひび（亀の甲羅の
    よう）、周りの壁は垂直に切り立った六角柱」（儚月抄）——**六角の格子で柱に割り、
    柱ごとに天面の高さと明暗を振る**。見下ろすカメラでは天面が絵の大半なので、
    そこが六角のモザイクになることが「玄武の沢だ」と言う唯一の手である。

    段（麓〜峰）は基の岩山と同じ 4 段。**接地層は削らない**（罠 5）。
    日当たりが悪い沢なので、根方に**発光苔**を点す（§4.4「多数の洞穴・発光苔」）。
    """
    tier = _split_style(name)[1].split('_')[1]
    h = CRAG_HEIGHT[tier]
    rng = rng_for(name)
    #! 六角格子の中心（pitch 11 vox ＝ 1 マスに 3 本ほど。型をまたいでも柱が繋がる位相）。
    pitch = 11.0
    centres = []
    row = -2
    while row <= 5:
        cy = row * pitch * 0.87
        col = -2
        while col <= 5:
            cx = (col * pitch) + (pitch * 0.5 if (row % 2) else 0.0)
            centres.append((cx, cy, len(centres)))
            col += 1
        row += 1
    #! 柱ごとの天面と色（**柱単位**。ボクセルごとに散らすと greedy が効かない＝罠 38）。
    col_top = {}
    col_shade = {}
    for (_cx, _cy, cid) in centres:
        col_top[cid] = h - int(rng.integers(0, 9))
        #! **明るい段を主にする。**初版は暗い段が 3 割で、日の下でも真っ黒な塔に見えた
        #! （プレハブの絵で実測）。玄武岩は暗い石だが、暗さは影が付けてくれる。
        col_shade[cid] = int(rng.choice([C['genbu'], C['genbu_l'], C['genbu_d']],
                                        p=[0.40, 0.42, 0.18]))
    v = np.zeros((V, V, h), np.uint8)
    for x in range(V):
        for y in range(V):
            d1 = d2 = 1e9
            best = 0
            for (cx, cy, cid) in centres:
                d = ((x - cx) ** 2) + ((y - cy) ** 2)
                if d < d1:
                    d2 = d1
                    d1 = d
                    best = cid
                elif d < d2:
                    d2 = d
            #! 柱の継ぎ目（2 番目に近い中心との差が小さい所）＝**縦に走る溝**。
            joint = (math.sqrt(d2) - math.sqrt(d1)) < 1.4
            top = col_top[best] - (1 if joint else 0)
            top = max(8, min(h, top))
            v[x, y, 0:top] = C['genbu_j'] if joint else col_shade[best]
            if not joint:
                #! 層理（下ほど暗い）。柱の中だけに入れる——溝は溝のままにする。
                v[x, y, 0:top // 5] = C['genbu_d']
            #! 天面は**柱の色より 1 段明るく**（日の当たる面。溝だけは暗いまま）。
            v[x, y, top - 1] = C['genbu_j'] if joint else C['genbu_l']
    #! 発光苔。**根方に塊で**（日の差さない沢の岩肌）。
    for _ in range(int(rng.integers(2, 6))):
        cx = int(rng.integers(0, V - 4))
        cy = int(rng.integers(0, V - 4))
        z0 = int(rng.integers(2, max(3, h // 3)))
        v[cx:cx + int(rng.integers(3, 6)), cy:cy + int(rng.integers(3, 6)), z0:z0 + 3] = (
            C['koke'] if rng.random() < 0.5 else C['koke_d'])
    return [('main', v, (0, 0, 0))]


def _ground_path_kap(name):
    """**河童のバザーの通り道** — 踏み固めた土に**鉄板を渡した**道（沢はぬかるむ）。
    油染みとボルト。§4.4 の工房の町の足元。"""
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['dirt_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack'], C['dirt'], C['pack_d'], C['dirt_l']], [0.36, 0.26, 0.24, 0.14])
    #! 敷き鉄板（多くて 1 枚。角の丸くない矩形＝人が当てたもの）。
    #! **全マスに撒かない**——初版は道じゅうが敷石の斑に見えた（合成フレーム実測）。
    if rng.random() < 0.4:
        x0 = int(rng.integers(0, V - 10))
        y0 = int(rng.integers(0, V - 10))
        w_ = int(rng.integers(9, 18))
        d_ = int(rng.integers(9, 18))
        colour = C['tin_d'] if rng.random() < 0.5 else C['tin_g']
        layer[x0:min(V, x0 + w_), y0:min(V, y0 + d_)] = colour
        #! 縁の錆とボルト。
        layer[x0:min(V, x0 + w_), y0:y0 + 1] = C['rust_d']
        for bx in range(x0 + 2, min(V, x0 + w_) - 1, 5):
            layer[bx, min(V - 1, y0 + 2)] = C['iron_l']
    #! 油染み（暗い斑。塊で）。
    _grain(rng, layer, layer > 0, [C['char_l'], C['soot']], [0.05, 0.04], block=3)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_turf_kap(name):
    """**河童のバザーの開けた地面** — 沢の砂利と苔、ところどころ水溜まり。"""
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['gravel_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['gravel'], C['pebble'], C['gravel_d'], C['turf_d']],
            [0.34, 0.24, 0.24, 0.18])
    #! 水溜まり（沢の湿地。**縁を苔で締める**——ただの暗い斑にすると穴に見える）。
    #! **1 マスに多くて 1 つ・大きめ**（小さいのを撒くと青い紙吹雪に見えた＝合成フレーム実測）。
    if rng.random() < 0.34:
        x0 = int(rng.integers(1, V - 13))
        y0 = int(rng.integers(1, V - 13))
        w_ = int(rng.integers(8, 13))
        d_ = int(rng.integers(8, 13))
        #! **ぬかるみ**（湿った土）を先に敷き、その中にだけ水面を置く。青一色の矩形は
        #! 見下ろすと「青い紙吹雪」に見えた（合成フレーム実測）。
        layer[x0:min(V, x0 + w_), y0:min(V, y0 + d_)] = C['damp']
        layer[x0 + 2:min(V, x0 + w_ - 2), y0 + 2:min(V, y0 + d_ - 2)] = C['wa_d']
        layer[max(0, x0 - 1):min(V, x0 + w_ + 1), max(0, y0 - 1):y0] = C['moss_d']
    _grain(rng, layer, layer > 0, [C['moss'], C['moss_d']], [0.06, 0.05], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _rampart_kap(name):
    """**河童のバザーの塀** — 波トタンの目隠し（工事現場の仮囲い）。石の土台に立てる。"""
    rng = rng_for(name)
    height = 58
    v = np.zeros((V, V, height), np.uint8)
    v[:, :, 0:8] = C['wall_d']
    v[:, :, 7] = C['rock_d']
    plate = _kap_tin_plate(rng, (V // 6 + 1,))
    for x in range(V):
        colour = C['tin_d'] if (x % 4) < 2 else plate[x // 6]
        v[x, 10:22, 8:height] = colour
    #! 支柱（丸太）と、上端の鼻隠し。
    for x0 in (2, V - 6):
        v[x0:x0 + 4, 8:24, 8:height - 2] = C['log']
    v[:, 10:22, height - 2:height] = C['iron']
    return [('main', v, (0, 0, 0))]


def _house_wall_kap(name):
    """**沢の小屋の壁 1 層**（工房の長屋と同じ材を 1 マスの家へ。板＋トタンの継ぎ）。"""
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    v = np.zeros((V, V, V), np.uint8)
    v[:, :, 0:HOUSE_PLINTH] = C['wall_d']
    inset = HOUSE_INSET
    x0 = inset if west else 0
    x1 = V - inset if east else V
    y0 = inset if north else 0
    y1 = V - inset if south else V
    for x in range(x0, x1):
        colour = ([C['tin_g'], C['tin'], C['tin_l']][(x // 3) % 3] if (((x // 6) % 3) == 2)
                  else [C['board_l'], C['board'], C['oak'], C['board_d']][(x // 3) % 4])
        v[x, y0:y1, HOUSE_PLINTH:V] = colour
    for side, on in (('n', north), ('s', south), ('w', west), ('e', east)):
        if not on:
            continue
        for _ in range(2):
            a0 = int(rng.integers(0, V - 8))
            z0 = int(rng.integers(7, V - 10))
            colour = C['tin'] if rng.random() < 0.5 else C['tin_g']
            if side == 'n':
                v[a0:a0 + 9, y0:y0 + 2, z0:z0 + 9] = colour
            elif side == 's':
                v[a0:a0 + 9, y1 - 2:y1, z0:z0 + 9] = colour
            elif side == 'w':
                v[x0:x0 + 2, a0:a0 + 9, z0:z0 + 9] = colour
            else:
                v[x1 - 2:x1, a0:a0 + 9, z0:z0 + 9] = colour
    #! 南面の小窓（見下ろすカメラの正面）。
    if south:
        v[12:20, y1 - 2:y1, 14:22] = C['glass_l']
    return [('main', v, (0, 0, 0))]


def _house_roof_tin(name):
    """**沢の小屋の寄棟屋根 1 スライス**（波トタン）。骨は基の板張りと同じ高さの式。"""
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    top = HOUSE_ROOF_H
    v = np.zeros((V, V, top), np.uint8)
    plate = _kap_tin_plate(rng, (V // KAP_PLATE + 1, V // KAP_PLATE + 1))
    for x in range(V):
        for y in range(V):
            reach = []
            if north:
                reach.append((y + 0.5) / V)
            if south:
                reach.append((V - 0.5 - y) / V)
            if west:
                reach.append((x + 0.5) / V)
            if east:
                reach.append((V - 0.5 - x) / V)
            t = min(reach) if reach else 1.0
            h = max(1, min(top, int(round(HOUSE_EAVE + ((top - HOUSE_EAVE) * min(1.0, t))))))
            v[x, y, 0:h] = C['tin_d']
            #! 畝は南北に走らせる（軒と直交＝雨の流れる向き）。
            v[x, y, max(0, h - 2):h] = plate[x // KAP_PLATE, y // KAP_PLATE]
            if (x % 4) < 2 and (h < top):
                v[x, y, h] = plate[x // KAP_PLATE, y // KAP_PLATE]
            if h >= top:
                v[x, y, h - 1] = C['iron']  # 棟包み
    return [('main', v, (0, 0, 0))]


def stall_kap(name):
    """**河童の露店**（§4.4 ⑤「露店の幕を水色〜藍の横長板 1 枚＋胡瓜の緑」）。

    街路樹の口（`street_tree`）で道沿いに立てる——「バザーは場所ではなく**商売の形**」
    （§4.4 の訂正）なので、市庭にも参道にも屋台が散る姿が正しい。
    鉄パイプの 4 本柱に藍の天幕、台の上に胡瓜と木箱、南面に前垂れ（見下ろすカメラの正面）。
    """
    rng = rng_for(name)
    ext = 4
    W = V + (ext * 2)
    v = np.zeros((W, W, 62), np.uint8)
    c0, c1 = ext, ext + V
    #! 4 本柱（鉄パイプ）。
    for (px, py) in ((c0 + 3, c0 + 3), (c1 - 6, c0 + 3), (c0 + 3, c1 - 6), (c1 - 6, c1 - 6)):
        v[px:px + 3, py:py + 3, 0:52] = C['iron']
        v[px + 1:px + 2, py + 1:py + 2, 0:52] = C['iron_l']
    #! 台（板）と、その上の胡瓜と木箱。
    v[c0 + 2:c1 - 2, c0 + 6:c1 - 2, 18:22] = C['board']
    v[c0 + 2:c1 - 2, c0 + 6:c1 - 2, 21] = C['board_l']
    for _ in range(6):
        gx = c0 + 3 + int(rng.integers(0, V - 8))
        gy = c0 + 8 + int(rng.integers(0, V - 14))
        v[gx:gx + 5, gy:gy + 2, 22:24] = C['kyuri']
        v[gx + 1:gx + 4, gy:gy + 2, 23] = C['kyuri_l']
    v[c0 + 2:c0 + 12, c0 + 2:c0 + 10, 0:14] = C['board_d']
    v[c0 + 3:c0 + 11, c0 + 3:c0 + 9, 13] = C['board']
    #! 天幕（**藍と白の縞**。マスの外へ 4 vox 張り出す＝屋台の庇）。
    #! 見下ろすカメラで見えるのは**天面だけ**なので、屋台の顔はここが担う——
    #! 初版は天面を一様に白抜きで塗り潰して、卓に見えた（合成フレームで実測）。
    #! 北へ 4 vox 上がる片流れにして、天面に段（＝布の張り）を出す。
    for y in range(W):
        colour = C['ai'] if ((y // 6) % 2) == 0 else C['nuki']
        z0 = 52 + ((W - 1 - y) * 4) // (W - 1)
        v[:, y, z0:z0 + 4] = colour
    #! 縁の紐（南の垂れ縁だけ濃い藍で締める）。
    v[:, W - 2:W, 52:54] = C['ai_d']
    #! 前垂れ（南面に垂らす布。見下ろすカメラから見えるのはここだけ）。
    v[c0:c1, c1 - 1:c1 + ext, 40:52] = C['ai_d']
    v[c0 + 4:c1 - 4, c1 - 1:c1 + ext, 44:48] = C['nuki']
    #! 張り出しは z≥8 だけ（接地はマスの中）。
    v[0:c0, :, 0:8] = 0
    v[c1:, :, 0:8] = 0
    v[:, 0:c0, 0:8] = 0
    v[:, c1:, 0:8] = 0
    return [('main', v, (-ext, -ext, 0))]


def lamp_post_kap(name):
    """**河童のバザーの街灯** — 鉄パイプの竿に**裸電球**とトタンの笠（§4.4 の二次創作の
    定番「配管・トタン・歯車・裸電球」）。灯は `lamp_flame_kap`（自発光は別体＝罠 39）。"""
    v = np.zeros((V, V, 52), np.uint8)
    v[12:20, 12:20, 0:3] = C['wall_d']          # コンクリの根巻き
    v[14:18, 14:18, 3:44] = C['iron']
    v[15:17, 15:17, 3:44] = C['iron_l']
    v[14:18, 14:24, 42:44] = C['iron']          # 腕（南へ）
    v[11:21, 17:27, 44:46] = C['tin_g']         # トタンの笠
    v[12:20, 18:26, 43:44] = C['tin_d']
    v[15:17, 20:24, 40:43] = C['bulb']          # 裸電球
    v[15:17, 21:23, 39:40] = C['iron_l']        # ソケットの下端
    #! 引き込みの電線（柱から東へ 1 本。町じゅうに配線が回っている印）。
    v[18:V, 15:17, 46:47] = C['iron']
    return [('main', v, (0, 0, 0))]


def lamp_flame_kap(name):
    """**裸電球の灯** — 電球の 1 ボクセル外に貼る光る殻。揺れない（電気の灯である）。"""
    a = np.zeros((4, 6, 5), np.uint8)
    a[:, :, :] = C['bulb']
    a[1:3, 1:5, 1:4] = 0
    return [('flame_a', a, (14, 19, 39))]


#: 工房の歯車（回るパーツ）。(原点 x, 原点 y, 原点 z, 一辺) と支点（プレハブ原点から）。
#: 壁の歯車 = 南面（y は D-4..D）の縦の円板／屋根の弾み車 = 寝た円板。
KOUBOU_WGEAR = (0, 60, 22, 41)      # 原点 (x, y, z) と一辺（x と z）
KOUBOU_WHUB = (20.0, 62.0, 42.0)    # 支点
KOUBOU_RGEAR = (25, 1, 0, 47)       # 原点 (x, y, -) と一辺（x と y）
KOUBOU_RHUB = (48.0, 24.0, 99.5)    # 支点（z は body + 21.5）


def koubou_kap(name):
    """**エンジニアギルド**（町 6 の BUILDING_2。河城にとりの工房）。

    市庭の真ん中の 3×2 マスの敷地へまるごと建つ。§4.4 ⑥「**歯車か水車の円板 1 枚**
    （円形は遠目の図形識別が最も強い）」——**南面に大歯車**を掛け、屋根から煙突と
    配管を出す。入口（南辺の中央）は暖簾のぶんを空けてある。
    """
    rng = rng_for(name)
    W, D, H = 96, 64, 104
    v = np.zeros((W, D, H), np.uint8)
    #! 土間（マスいっぱい＝罠 5）。
    v[:, :, 0:6] = C['wall_d']
    v[2:W - 2, 2:D - 2, 5] = C['wall']
    #! 躯体（縦板＋トタンの継ぎ）。高さ 2.4 マス。
    body = 78
    for x in range(2, W - 2):
        colour = ([C['tin_g'], C['tin'], C['tin_l']][(x // 3) % 3] if (((x // 6) % 3) == 2)
                  else [C['board_l'], C['board'], C['oak'], C['board_d']][(x // 3) % 4])
        v[x, 2:D - 2, 6:body] = colour
    #! **中は刳り抜く**（閉じた小屋の内側は 1 画素も見えない。三角形だけが増える）。
    v[6:W - 6, 6:D - 6, 6:body] = 0
    for _ in range(10):
        x0 = int(rng.integers(2, W - 14))
        z0 = int(rng.integers(10, body - 16))
        v[x0:x0 + 12, D - 4:D - 2, z0:z0 + 14] = C['tin'] if rng.random() < 0.5 else C['tin_g']
    #! 片流れの屋根（北へ落ちる波トタン。長屋と同じ材で「同じ町の建物」に見せる）。
    plate = _kap_tin_plate(rng, ((W // KAP_PLATE) + 1, (D // KAP_PLATE) + 1))
    for y in range(D):
        surf = body + 2 + ((D - 1 - y) * 16) // (D - 1)
        for x in range(W):
            v[x, y, body:surf] = C['tin_d']
            v[x, y, surf - 2:surf] = plate[x // KAP_PLATE, y // KAP_PLATE]
            if (x % 4) < 2:
                v[x, y, surf] = plate[x // KAP_PLATE, y // KAP_PLATE]
    #! **歯車 2 枚**（§4.4 ⑥「歯車か水車の円板 1 枚。円形は遠目の図形識別が最も強い」）。
    #! **y=0 は北**——見下ろすカメラに映るのは南面なので、壁の歯車は南（y=D-4..D）へ掛ける
    #! （初版は北面に掛けて 1 画素も出なかった。デザイン6 その2 の可視の三法則と同じ穴）。
    #! 見下ろしでいちばん効くのは**屋根に寝かせた弾み車**なので、そちらも 1 枚載せる。
    def gear(centre, radius, teeth, put):
        """歯車 1 枚を `put(u, w, rim)` で描く（u, w は円の座標系）。"""
        cu, cw = centre
        span = int(radius) + 5
        for u in range(int(cu) - span, int(cu) + span + 1):
            for w in range(int(cw) - span, int(cw) + span + 1):
                du = u - cu
                dw = w - cw
                d = math.sqrt((du * du) + (dw * dw))
                ang = math.atan2(dw, du)
                edge = radius + (3.0 if (int((ang + math.pi) / (math.pi / teeth)) % 2 == 0) else -1.0)
                if d > edge:
                    continue
                spoke = abs(math.sin(ang * 3.0)) < 0.30
                if (d > radius * 0.36) and (d < radius - 4.0) and not spoke:
                    continue
                put(u, w, d >= radius - 3.0)

    #! **歯車は別のパーツにして回す**（2026-08-19 に決めた:「工房の歯車は変愚の辺境に
    #! ある水車のように回転させられないか？」）。剛体の回転は描くときの行列なので、
    #! **配列は掃く軌跡ぶん要らない**——「描くボクセル」と「支点」が入っていればよい
    #! （`mill` の水車と同じ流儀。支点が配列の外に出ると `load_prefab` の照合で落ちる）。
    wall_v = np.zeros((KOUBOU_WGEAR[3], 4, KOUBOU_WGEAR[3]), np.uint8)
    roof_v = np.zeros((KOUBOU_RGEAR[3], KOUBOU_RGEAR[3], 3), np.uint8)

    def wall_gear(x, z, rim):
        lx = x - KOUBOU_WGEAR[0]
        lz = z - KOUBOU_WGEAR[2]
        if (0 <= lx < wall_v.shape[0]) and (0 <= lz < wall_v.shape[2]):
            #! **壁より明るく**（板とトタンの前で灰の歯車は沈む）。歯は錆、身は磨いた鋼。
            wall_v[lx, 0:3, lz] = C['rust'] if rim else C['steel']
            wall_v[lx, 3:4, lz] = C['steel'] if rim else C['qz_l']

    def roof_gear(x, y, rim):
        lx = x - KOUBOU_RGEAR[0]
        ly = y - KOUBOU_RGEAR[1]
        if (0 <= lx < roof_v.shape[0]) and (0 <= ly < roof_v.shape[1]):
            roof_v[lx, ly, 0:3] = C['rust'] if rim else C['steel_d']
            roof_v[lx, ly, 2:3] = C['steel']

    gear((KOUBOU_WHUB[0], KOUBOU_WHUB[2]), 15.0, 12, wall_gear)
    v[17:23, D - 5:D, 39:45] = C['rust_d']  # 軸（本体側。回さない）
    gear((KOUBOU_RHUB[0], KOUBOU_RHUB[1]), 18.0, 14, roof_gear)
    for (px, py) in ((44, 20), (52, 20), (44, 28), (52, 28)):
        v[px:px + 3, py:py + 3, body:body + 21] = C['iron']  # 弾み車の架台
    #! 煙突（屋根から 1 マス突き出す）と、屋根を跨ぐ配管。
    v[70:78, 12:20, body:H - 2] = C['iron']
    v[71:77, 13:19, H - 6:H - 2] = C['rust']
    v[40:44, 2:D - 2, body + 14:body + 20] = C['pipe']
    v[40:44, 2:6, body + 12:body + 22] = C['pipe_d']
    #! 入口（南辺の中央。暖簾の掛かるマスを空ける）。
    v[38:58, D - 6:D, 6:38] = 0
    v[38:58, D - 6:D - 4, 38:42] = C['timber_d']
    #! 軒下の裸電球 2 つ。
    for x0 in (30, 62):
        v[x0:x0 + 4, D - 5:D - 1, body - 8:body - 4] = C['bulb']
    #! ドラム缶と工具箱（東の脇）。
    v[82:92, D - 16:D - 6, 6:24] = C['rust']
    v[83:91, D - 15:D - 7, 23] = C['rust_d']
    v[82:92, D - 30:D - 20, 6:16] = C['tin_g']
    return [('main', v, (0, 0, 0)),
            ('gear_wall', wall_v, (KOUBOU_WGEAR[0], D - 4, KOUBOU_WGEAR[2])),
            ('gear_roof', roof_v, (KOUBOU_RGEAR[0], KOUBOU_RGEAR[1], body + 20))]


def koubou_parts():
    """工房のパーツ（本体＋回る歯車 2 枚）。**支点はプレハブ原点からのボクセル座標**。

    壁の歯車は南面の縦の円板なので **y 軸**まわり、屋根の弾み車は寝た円板なので
    **z 軸**まわりに回す。速さは回転/秒——`mill` の水車（0.55）は水で回る速さで、
    重い歯車には速すぎる（見下ろしでちらつく）。
    """
    return [
        {'name': 'main', 'voxels': 'main', 'grounded': True,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
        {'name': 'gear_wall', 'voxels': 'gear_wall', 'parent': 'main', 'grounded': False,
         'pivot': [float(KOUBOU_WHUB[0]), float(KOUBOU_WHUB[1]), float(KOUBOU_WHUB[2])],
         'motion': {'kind': 'rotate', 'axis': 'y', 'speed': 0.10, 'phase': 0.0},
         'wind_k': 0.0},
        {'name': 'gear_roof', 'voxels': 'gear_roof', 'parent': 'main', 'grounded': False,
         'pivot': [float(KOUBOU_RHUB[0]), float(KOUBOU_RHUB[1]), float(KOUBOU_RHUB[2])],
         'motion': {'kind': 'rotate', 'axis': 'z', 'speed': 0.16, 'phase': 0.37},
         'wind_k': 0.0},
    ]


def sakaba_kap(name):
    """**河童の酒場**（町 6 の BUILDING_0。「河童の水呑さん」が主）。

    入口は工房の帯に穿たれた 1 マスの窪みで、東だけが市庭へ開く。見下ろすカメラに
    映るのは**天面だけ**（デザイン6 その2 の可視の三法則）なので、店の顔は
    **藍と白の縞の日除け**が担う——その下に樽の卓・徳利・裸電球の連なりを置く。
    初版は細い竿に看板を掲げた形で、見下ろしでは棒 1 本にしか見えなかった。
    """
    ext = 6
    W = V + (ext * 2)
    v = np.zeros((W, W, 96), np.uint8)
    c0, c1 = ext, ext + V
    #! 土間（マスの中だけ）。
    v[c0:c1, c0:c1, 0:4] = C['wall_d']
    #! **日除け**（マスいっぱい＋東へ 6 vox。南へ 4 vox 下がる片流れ）。
    for y in range(W):
        colour = C['ai'] if ((y // 7) % 2) == 0 else C['nuki']
        z0 = 68 + ((W - 1 - y) * 4) // (W - 1)
        v[c0 - 2:W, y, z0:z0 + 4] = colour
    v[c0 - 2:W, W - 2:W, 68:70] = C['ai_d']  # 南の垂れ縁
    #! 受け柱（鉄パイプ 4 本）と、トタンの小さな返し（東の口の上）。
    for (px, py) in ((c0 + 1, c0 + 1), (W - 5, c0 + 1), (c0 + 1, c1 - 3), (W - 5, c1 - 3)):
        v[px:px + 3, py:py + 3, 4:70] = C['iron']
        v[px + 1:px + 2, py + 1:py + 2, 4:70] = C['iron_l']
    for y in range(c0, c1):
        v[W - 3:W, y, 60:64] = C['tin_g'] if ((y // 5) % 2) == 0 else C['rust']
    #! 樽の卓（3 つ）と徳利・杯。**天面が見えるので見下ろしでも読める。**
    for (bx, by) in ((c0 + 2, c0 + 3), (c0 + 2, c0 + 18), (c0 + 15, c0 + 3)):
        v[bx:bx + 11, by:by + 11, 4:22] = C['oak']
        v[bx + 1:bx + 10, by + 1:by + 10, 21] = C['oak_l']
        v[bx:bx + 11, by:by + 11, 10:12] = C['iron']
    v[c0 + 18:c0 + 24, c0 + 20:c0 + 26, 4:18] = C['qz']
    v[c0 + 25:c0 + 29, c0 + 21:c0 + 25, 4:10] = C['qz_l']
    #! 胡瓜の籠（河童の肴。§4.4 ⑤の緑をここでも 1 点）。
    v[c0 + 24:c0 + 30, c0 + 4:c0 + 12, 4:10] = C['board_d']
    v[c0 + 25:c0 + 29, c0 + 5:c0 + 11, 9:12] = C['kyuri']
    #! 裸電球の連なり（日除けの下に 3 つ。夜の市の顔）。
    v[c0 + 2:W - 2, c0 + 14:c0 + 16, 66:67] = C['iron']
    for x0 in (c0 + 4, c0 + 16, c0 + 28):
        v[x0:x0 + 4, c0 + 13:c0 + 17, 62:66] = C['bulb']
    v[0:c0, :, 0:8] = 0
    v[c1:, :, 0:8] = 0
    v[:, 0:c0, 0:8] = 0
    v[:, c1:, 0:8] = 0
    return [('main', v, (-ext, -ext, 0))]


# ---- 河童の配管（2026-08-19 デザイン7 その2）----
#
# 決めたこと:「工房と市の地面と壁にやけくそって程に配管を置こう。**焼き込みではなく、
# ボクセルでパイプをそこかしこに**。そしてあちこちのパイプの継ぎ目から蒸気
# （半透明のボクセルで吹きだす蒸気を表現）が噴出して揺れている感じに」
#
# **壁に焼き込んだ配管（manor_wall_kap の 1 本）とは別物**である。あれは面の飾りで、
# こちらは**マスに立つ物**——地面を横切る本管・壁に添う立ち上がり・継ぎ手の弁。
# 置き場は `terrain_view.cpp` の配管の網（行と列のハッシュで走る本管＋屋敷に接したマスの
# 立ち上がり）。**蒸気はプレハブではない**——半透明はプレハブの経路に無いので、
# `CloudLayer::draw_steam`（雲と同じシェーダ）が噴き出しを描く。
PIPE_R = 5        # 本管の半径（vox）。10 vox 径 ＝ 遠目で「管」と読める最小
PIPE_Z = 9        # 本管の芯の高さ。低いと地面に埋まって見え、高いと跨げなく見える
PIPE_WALL_Z = 38  # 壁に添う管の芯（工房の壁 54 vox の胸あたり）


def _pipe_tube(v, axis, centre, z0, radius, colour, dark, span=None):
    """丸パイプを 1 本通す。`axis` は 'x' か 'y'（管の走る向き）。`centre` は横の芯。

    **断面は円**（角パイプにすると桁に見える）。下半分を暗い段で締めると、
    見下ろすカメラでも管の丸みが読める（`crag` の層理と同じ理屈）。
    """
    n = v.shape[0] if axis == 'x' else v.shape[1]
    lo, hi = (0, n) if span is None else span
    for a in range(lo, hi):
        for b in range(centre - radius, centre + radius + 1):
            for z in range(z0 - radius, z0 + radius + 1):
                if (z < 0) or (z >= v.shape[2]):
                    continue
                db = b - centre
                dz = z - z0
                if ((db * db) + (dz * dz)) > (radius * radius):
                    continue
                shade = colour if (dz >= -1) else dark
                if axis == 'x':
                    if (0 <= b < v.shape[1]):
                        v[a, b, z] = shade
                else:
                    if (0 <= b < v.shape[0]):
                        v[b, a, z] = shade


def _pipe_flange(v, axis, centre, z0, at, radius, colour):
    """継ぎ手の輪（フランジ）。管より 2 vox 太い輪を 3 vox 幅で巻く。"""
    r = radius + 2
    for a in range(at, at + 3):
        if (a < 0) or (a >= (v.shape[0] if axis == 'x' else v.shape[1])):
            continue
        for b in range(centre - r, centre + r + 1):
            for z in range(z0 - r, z0 + r + 1):
                if (z < 0) or (z >= v.shape[2]):
                    continue
                db = b - centre
                dz = z - z0
                if ((db * db) + (dz * dz)) > (r * r):
                    continue
                if axis == 'x':
                    if (0 <= b < v.shape[1]):
                        v[a, b, z] = colour
                else:
                    if (0 <= b < v.shape[0]):
                        v[b, a, z] = colour


def _pipe_saddle(v, axis, centre, at, colour):
    """管を受けるコンクリの台（マスの中に 1 つ）。**接地はここだけ**。"""
    if axis == 'x':
        v[at:at + 5, centre - 4:centre + 5, 0:PIPE_Z - 2] = colour
    else:
        v[centre - 4:centre + 5, at:at + 5, 0:PIPE_Z - 2] = colour


def _pipe_rust(v, rng, count=6):
    """錆の斑（管の天面に塊で）。**格子に乗せない**（トタンの罠と同じ）。"""
    for _ in range(count):
        x0 = int(rng.integers(0, v.shape[0] - 3))
        y0 = int(rng.integers(0, v.shape[1] - 3))
        w_ = int(rng.integers(2, 5))
        d_ = int(rng.integers(2, 5))
        for x in range(x0, min(x0 + w_, v.shape[0])):
            for y in range(y0, min(y0 + d_, v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['rust'] if rng.random() < 0.6 else C['rust_d']
                        break


def pipe_run_kap(name):
    """**地面を横切る本管 1 マス**（`_ns` = 南北 / `_ew` = 東西）。

    マスいっぱいに通すので、隣のマスの同じ型と**繋がって長い管の列**になる。
    コンクリの受け台・継ぎ手の輪・錆。変種で弁と細管の有無を振る。
    """
    base = _split_style(name)[1]  # pipe_run_<ns|ew>[_<nn>]
    parts = base.split('_')
    axis = 'y' if parts[2] == 'ns' else 'x'
    variant = int(parts[3]) if ((len(parts) > 3) and parts[3].isdigit()) else 1
    rng = rng_for(name)
    v = np.zeros((V, V, 26), np.uint8)
    _pipe_saddle(v, axis, 16, 4, C['wall_d'])
    _pipe_saddle(v, axis, 16, 23, C['wall_d'])
    _pipe_tube(v, axis, 16, PIPE_Z, PIPE_R, C['pipe'], C['pipe_d'])
    _pipe_flange(v, axis, 16, PIPE_Z, 14, PIPE_R, C['pipe_d'])
    if variant == 2:
        #! 添え管（細い枝管が本管の脇を走る。工場の配管は 1 本では終わらない）。
        _pipe_tube(v, axis, 26, PIPE_Z - 2, 3, C['iron'], C['iron_l'])
    if variant == 3:
        #! 弁（ハンドル車）。**天面に出す**——見下ろしで読めるのは上面だけである。
        if axis == 'x':
            v[14:18, 12:21, PIPE_Z + PIPE_R:PIPE_Z + PIPE_R + 4] = C['iron']
            v[15:17, 14:19, PIPE_Z + PIPE_R + 4:PIPE_Z + PIPE_R + 9] = C['rust']
            v[13:19, 11:22, PIPE_Z + PIPE_R + 8:PIPE_Z + PIPE_R + 10] = C['rust']
            v[15:17, 15:18, PIPE_Z + PIPE_R + 8:PIPE_Z + PIPE_R + 10] = C['iron_l']
        else:
            v[12:21, 14:18, PIPE_Z + PIPE_R:PIPE_Z + PIPE_R + 4] = C['iron']
            v[14:19, 15:17, PIPE_Z + PIPE_R + 4:PIPE_Z + PIPE_R + 9] = C['rust']
            v[11:22, 13:19, PIPE_Z + PIPE_R + 8:PIPE_Z + PIPE_R + 10] = C['rust']
            v[15:18, 15:17, PIPE_Z + PIPE_R + 8:PIPE_Z + PIPE_R + 10] = C['iron_l']
    _pipe_rust(v, rng)
    return [('main', v, (0, 0, 0))]


def pipe_cross_kap(name):
    """**継ぎ手 1 マス**（南北と東西の本管が出会う所）。立ち上がりの噴気管つき。

    ここが**蒸気の噴き出し口**である（`terrain_view` がマスを集め、`CloudLayer::draw_steam`
    が半透明の噴き出しを描く）。噴気管の口は **z ≒ 1.5 マス**——蒸気はそこから上がる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 56), np.uint8)
    _pipe_saddle(v, 'x', 16, 3, C['wall_d'])
    _pipe_saddle(v, 'y', 16, 3, C['wall_d'])
    _pipe_tube(v, 'x', 16, PIPE_Z, PIPE_R, C['pipe'], C['pipe_d'])
    _pipe_tube(v, 'y', 16, PIPE_Z, PIPE_R, C['pipe'], C['pipe_d'])
    #! 出会いの塊（角の丸い箱。ここで 2 本が繋がっているように見せる）。
    v[9:24, 9:24, PIPE_Z - PIPE_R:PIPE_Z + PIPE_R + 1] = C['pipe_d']
    v[10:23, 10:23, PIPE_Z - PIPE_R + 1:PIPE_Z + PIPE_R] = C['pipe']
    _pipe_flange(v, 'x', 16, PIPE_Z, 6, PIPE_R, C['iron'])
    _pipe_flange(v, 'x', 16, PIPE_Z, 24, PIPE_R, C['iron'])
    #! 噴気管（立ち上がり 1.5 マス）。口は少し細くして、笠を被せる。
    v[13:20, 13:20, PIPE_Z:44] = C['iron']
    v[14:19, 14:19, PIPE_Z:44] = C['iron_l']
    v[12:21, 12:21, 34:37] = C['rust']       # 中ほどの継ぎ手
    v[14:19, 14:19, 44:48] = C['rust_d']     # 口金
    v[11:22, 11:22, 47:49] = C['iron']       # 笠
    #! 圧力計（南を向く小さな円盤。見下ろしでも縁が見える）。
    v[13:20, 22:24, 24:31] = C['iron']
    v[14:19, 24:25, 25:30] = C['qz_l']
    _pipe_rust(v, rng, 8)
    return [('main', v, (0, 0, 0))]


def pipe_wall_kap(name):
    """**壁に添う管 1 マス**（`_n`/`_s`/`_w`/`_e` ＝ 屋敷の壁がある側）。

    **屋敷に接したマスに必ず置く**ので、隣のマスと繋がって**建物を 1 周する管の線**になる。
    立ち上がりのある版（`pipe_riser_*`）と横引きの寸法を揃えてあるので、
    どちらが並んでも線は切れない。
    """
    base = _split_style(name)[1]  # pipe_wall_<n|s|w|e>[_<nn>]
    side = base.split('_')[2]
    rng = rng_for(name)
    v = np.zeros((V, V, 52), np.uint8)
    #! 壁の面から 7 vox 内側に芯を置く（壁は隣のマスなので、こちらの端に寄せる）。
    if side == 'n':
        axis, centre = 'x', 7
    elif side == 's':
        axis, centre = 'x', V - 8
    elif side == 'w':
        axis, centre = 'y', 7
    else:
        axis, centre = 'y', V - 8
    _pipe_tube(v, axis, centre, PIPE_WALL_Z, 4, C['pipe'], C['pipe_d'])
    _pipe_flange(v, axis, centre, PIPE_WALL_Z, 15, 4, C['pipe_d'])
    #! 受け金物（管を壁へ留める腕。2 本）。
    for at in (4, 24):
        if axis == 'x':
            v[at:at + 3, centre - 1:centre + 2, PIPE_WALL_Z - 9:PIPE_WALL_Z] = C['iron']
        else:
            v[centre - 1:centre + 2, at:at + 3, PIPE_WALL_Z - 9:PIPE_WALL_Z] = C['iron']
    _pipe_rust(v, rng, 4)
    return [('main', v, (0, 0, 0))]


def pipe_riser_kap(name):
    """**壁の立ち上がり 1 マス**（`_n`/`_s`/`_w`/`_e`）。横引き＋地面から上がる縦管＋弁。

    横引きは `pipe_wall_*` と同じ寸法（線が切れない）。縦管は地面から横引きへ繋がり、
    途中に弁と**噴気の口**を持つ——ここも蒸気の噴き出し口である。
    """
    base = _split_style(name)[1]  # pipe_riser_<n|s|w|e>[_<nn>]
    side = base.split('_')[2]
    rng = rng_for(name)
    v = np.zeros((V, V, 52), np.uint8)
    if side == 'n':
        axis, centre = 'x', 7
    elif side == 's':
        axis, centre = 'x', V - 8
    elif side == 'w':
        axis, centre = 'y', 7
    else:
        axis, centre = 'y', V - 8
    _pipe_tube(v, axis, centre, PIPE_WALL_Z, 4, C['pipe'], C['pipe_d'])
    #! 縦管（地面 → 横引き）。マスの中ほどに立てる。
    up = 13
    if axis == 'x':
        v[up:up + 7, centre - 3:centre + 4, 0:PIPE_WALL_Z + 4] = C['pipe']
        v[up + 1:up + 6, centre - 2:centre + 3, 0:PIPE_WALL_Z + 4] = C['pipe_d']
        v[up - 2:up + 9, centre - 5:centre + 6, 0:4] = C['wall_d']       # 根巻き
        v[up - 1:up + 8, centre - 4:centre + 5, 20:24] = C['rust']       # 継ぎ手
        #! 弁のハンドル車（**天面に出す**）と噴気の口金。
        v[up:up + 7, centre + 4:centre + 12, 26:30] = C['iron']
        v[up + 1:up + 6, centre + 10:centre + 13, 24:32] = C['rust']
        v[up - 1:up + 8, centre + 9:centre + 14, 30:32] = C['iron_l']
        v[up + 1:up + 6, centre - 9:centre - 4, 40:44] = C['rust_d']     # 噴気の口
        v[up + 2:up + 5, centre - 12:centre - 8, 41:43] = C['iron']
    else:
        v[centre - 3:centre + 4, up:up + 7, 0:PIPE_WALL_Z + 4] = C['pipe']
        v[centre - 2:centre + 3, up + 1:up + 6, 0:PIPE_WALL_Z + 4] = C['pipe_d']
        v[centre - 5:centre + 6, up - 2:up + 9, 0:4] = C['wall_d']
        v[centre - 4:centre + 5, up - 1:up + 8, 20:24] = C['rust']
        v[centre + 4:centre + 12, up:up + 7, 26:30] = C['iron']
        v[centre + 10:centre + 13, up + 1:up + 6, 24:32] = C['rust']
        v[centre + 9:centre + 14, up - 1:up + 8, 30:32] = C['iron_l']
        v[centre - 9:centre - 4, up + 1:up + 6, 40:44] = C['rust_d']
        v[centre - 12:centre - 8, up + 2:up + 5, 41:43] = C['iron']
    _pipe_rust(v, rng, 6)
    return [('main', v, (0, 0, 0))]


def _ground_path_jin(name):
    """**人里の通り道** — 踏み固めた土。**石は敷かない**（半舗装はテルモラの格）。"""
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['pack_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack'], C['pack_l'], C['dirt'], C['dirt_l']], [0.38, 0.26, 0.22, 0.14])
    _grain(rng, layer, layer > 0, [C['pack_d'], C['soil']], [0.07, 0.05], block=3)
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def _ground_turf_jin(name):
    """**人里の開けた地面** — 短い草に土が透ける。里の中なので野原より薄い。"""
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['pack']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['turf'], C['turf_d'], C['pack'], C['pack_l']], [0.34, 0.26, 0.22, 0.18])
    _grain(rng, layer, layer > 0, [C['turf_l'], C['soil']], [0.08, 0.05], block=3)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _yard_ground_jin(name):
    """**人里の前庭** — 土間の叩き。**街路より暗い**（意匠が変わっても守る約束＝基の註記）。"""
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['pack_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack_d'], C['soil'], C['dirt_d'], C['gravel_d']], [0.36, 0.28, 0.22, 0.14])
    _grain(rng, layer, layer > 0, [C['moss_d'], C['pebble']], [0.06, 0.05], block=3)
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def _ground_path_ten(name):
    """**天狗の里の通り道** — 山上の石畳。細かい切石に地衣が差す。

    人里（土）との差は材そのもの、モリバント（16 ボクセルの大判）との差は**石の細かさ**
    ——山へ担ぎ上げた石なので小さい。目地は色ではなく 1 段彫る（罠 44）。
    """
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['joint']
    face = np.zeros((V, V), np.uint8)
    step = 8
    for by in range(0, V, step):
        off = (by // step) % 2 * (step // 2)   # 半枚ずらす（芋目地を避ける）
        for bx in range(-step, V + step, step):
            x0, y0 = bx + off, by
            shade = rng.choice([C['flag'], C['flag_l'], C['flag_d']], p=[0.5, 0.26, 0.24])
            xa, xb = max(x0, 0), min(x0 + step - 1, V)
            ya, yb = max(y0, 0), min(y0 + step - 1, V)
            if xa < xb and ya < yb:
                face[xa:xb, ya:yb] = shade
    _grain(rng, face, face > 0, [C['lichen'], C['crag_b']], [0.06, 0.05], block=2)
    v[:, :, 1] = face
    return [('main', v, (0, 0, -2))]


def _ground_turf_ten(name):
    """**天狗の里の開けた地面** — 高山の草地。寒色の草に砂礫、白い高山植物を点で。

    人里の里の草（暖色の `turf`）と分かれるのは**草の色温度**——山の上は `alp` の寒色。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['crag_d']
    v[:, :, 1] = C['crag']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['alp'], C['alp_d'], C['crag'], C['crag_b']], [0.36, 0.26, 0.22, 0.16])
    _grain(rng, layer, layer > 0, [C['alp_l'], C['alp_fw'], C['lichen']], [0.07, 0.03, 0.05], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _yard_ground_ten(name):
    """**天狗の里の前庭** — 暗い割石敷き。**街路より暗い**約束は意匠が替わっても守る。"""
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['crag_dd']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['flag_d'], C['crag_d'], C['cob_d'], C['joint']], [0.36, 0.26, 0.22, 0.16])
    _grain(rng, layer, layer > 0, [C['lichen'], C['moss_d']], [0.06, 0.05], block=3)
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def _kyu_flag_face(rng, shades, p):
    """旧地獄街道の岩畳の面。8 ボクセルの石を半枚ずらしで敷く（天狗の石畳と同じ文法）。

    目地は塗らずに空けておき、下の層（`dark`）へ落とす——彫った溝が影になる（罠 44）。
    """
    face = np.zeros((V, V), np.uint8)
    step = 8
    for by in range(0, V, step):
        off = (by // step) % 2 * (step // 2)
        for bx in range(-step, V + step, step):
            x0, y0 = bx + off, by
            shade = rng.choice(shades, p=p)
            xa, xb = max(x0, 0), min(x0 + step - 1, V)
            ya, yb = max(y0, 0), min(y0 + step - 1, V)
            if xa < xb and ya < yb:
                face[xa:xb, ya:yb] = shade
    return face


def _cave_mound_kyu(name):
    """**旧地獄街道の山塊**（2026-08-18 その3 に決めた「上が平らなのはもったいない。
    複数ブロックを組み合わせたゴツゴツとした凹凸のある大きな岩山を表現しよう」）。

    岩天井（`cave_roof_kyu`）の上へ積む。段（裾 1.2 → 峰 3.2 マス）を選ぶのは置く側
    ——8 マス格子の値ノイズが高い所ほど高い段になり、**複数のマスにまたがる山塊**が立つ。
    「1 マス 1 個のまま段で山に見せる」文法も、斜めの削ぎと塊の欠きも岩山 `crag` と同じで、
    材だけ黒い岩（岩肌 `_rock_face_kyu` と同じ黒と灼熱の名残の赤褐）にする。
    足元はマスいっぱい（罠 5——削ると隣との継ぎ目から天井の背が抜けて見える）。
    """
    tier = next(t for t in ('base', 'low', 'mid', 'high', 'peak') if ('_%s_' % t) in name)
    #! base は**岩屑の最低段**（気づいたこと その3「この平らに表現されている部分も
    #! ゴツゴツさせられないか？」）——ノイズの低い所を含めて全マスに敷き、平らを消す。
    #! peak は**そびえる頂**（同「もっとダイナミックに。思い切りがたらないぞ」）——
    #! 5.5 マス。伸縮 1.4 倍まで掛かると蓋の上 7.7 マス（世界の高さ約 14 マス）に届く。
    h = {'base': 26, 'low': 38, 'mid': 70, 'high': 102, 'peak': 176}[tier]
    rng = rng_for(name)
    base = min(h - 8, 14 if tier in ('base', 'low') else 22)
    xs = np.arange(V, dtype=np.float32)[:, None]
    ys = np.arange(V, dtype=np.float32)[None, :]
    #! ゆるい斜めの削ぎ 1 枚＋塊の欠き（crag の註記のとおり。強く削ぐと岩柱の林になる）。
    ang = float(rng.uniform(0.0, 2.0 * math.pi))
    d = ((xs - 15.5) * math.cos(ang)) + ((ys - 15.5) * math.sin(ang))
    depth = float(rng.uniform(0.10, 0.26)) * h
    top = h - (np.clip((d - float(rng.uniform(-16.0, -2.0))) / 30.0, 0.0, 1.0) * depth)
    chip = rng.integers(0, 7, size=((V + 3) // 4, (V + 3) // 4)).astype(np.float32)
    top -= np.repeat(np.repeat(chip, 4, 0), 4, 1)[:V, :V]
    tops = np.clip(np.rint(top), base, h).astype(np.int32)
    #! 層理。下ほど闇に沈む（黒い山なので crag より 2 段暗い側から始める）。
    bands = [C['obs_d'], C['char'], C['sco_d'], C['char_l'], C['sco']]
    palette = np.array(bands, np.uint8)
    zgrid = np.arange(h)[None, None, :]
    solid = zgrid < tops[:, :, None]
    band_at = np.minimum((zgrid * len(bands)) // h, len(bands) - 1)
    shape = ((V + 3) // 4, (V + 3) // 4, (h + 3) // 4)
    lump = rng.choice(bands + [C['emb_d']], size=shape,
                      p=[0.12, 0.24, 0.18, 0.20, 0.12, 0.14]).astype(np.uint8)
    use_lump = rng.random(shape) < 0.45
    grow = (lambda a: np.repeat(np.repeat(np.repeat(a, 4, 0), 4, 1), 4, 2)[:V, :V, :h])
    v = np.where(solid, np.where(grow(use_lump), grow(lump), palette[band_at]), 0).astype(np.uint8)
    #! 天面は明るくしない（crag と同じ理由）。地衣は使わない——山の背は日に灼けた岩と
    #! 灼熱の名残だけで言う（緑を置くと地上の山と同じ顔になる）。
    face = rng.choice([C['char'], C['char_l'], C['emb_d']],
                      size=((V + 3) // 4, (V + 3) // 4), p=[0.58, 0.28, 0.14]).astype(np.uint8)
    face = np.repeat(np.repeat(face, 4, 0), 4, 1)[:V, :V]
    for x in range(V):
        for y in range(V):
            v[x, y, int(tops[x, y]) - 1] = face[x, y]
    return [('main', v, (0, 0, 0))]


def gaslamp_kyu(name):
    """**旧地獄街道のガス灯**（2026-08-18 その3 に決めた「街中はまだ暗いので、
    道の交差点毎にガス灯のような灯りを立てよう」）。

    地底の街は岩天井の下で常に暗い——交差点に立つ**背の高い鉄の街灯**で道筋を照らす。
    提灯掛け（軒先の趣）との違いは鉄と硝子の火屋。高さ 2 マス——交差点の目印を兼ねる。
    火屋は**四隅の桟だけ**（四方を囲うと中の火が 1 画素も見えない——鉄の街灯で踏んだ穴）。
    火は別体（`gaslamp_kyu_flame`。罠 39）。**本当の明かりは置く側が点光源で足す**
    （`TerrainViewLight`。自発光は自分しか光らせない——龍神像のライトアップと同じ判断）。
    """
    height = 64
    v = np.zeros((V, V, height), np.uint8)
    v[12:20, 12:20, 0:4] = C['wall_d']     # 石の台
    v[13:19, 13:19, 3:4] = C['wall']
    v[14:18, 14:18, 4:44] = C['iron']      # 柱
    v[15:17, 15:17, 4:44] = C['iron_l']
    v[13:19, 13:19, 20:22] = C['iron']     # 中程の飾り環
    v[12:20, 12:20, 44:46] = C['iron_l']   # 火屋の受け
    for (x0, x1) in ((12, 14), (18, 20)):  # 火屋（四隅の桟だけ）
        for (y0, y1) in ((12, 14), (18, 20)):
            v[x0:x1, y0:y1, 46:58] = C['iron']
    v[12:20, 12:20, 46:47] = C['iron']     # 下枠
    v[12:20, 12:20, 57:58] = C['iron']     # 上枠
    v[11:21, 11:21, 58:60] = C['iron']     # 笠
    v[13:19, 13:19, 60:62] = C['iron_l']
    v[15:17, 15:17, 62:64] = C['iron']     # 頂華
    return [('main', v, (0, 0, 0))]


def gaslamp_kyu_flame(name):
    """**ガス灯の火**（火屋の中の芯柱。別体＝罠 39。夜霧の度合いは置く側が乗せる）。"""
    v = np.zeros((V, V, 64), np.uint8)
    v[14:18, 14:18, 47:57] = C['lit']
    return [('main', v, (0, 0, 0))]


def _ground_path_kyu(name):
    """**旧地獄街道の通り道** — 黒い岩畳（2026-08-18 その3 に決めた
    「岩山をくり抜いた街なので地面は全て黒い岩畳で」）。

    刳り抜いた山の床に石を敷いた畳。目地を彫るのは天狗の石畳と同じ文法で、色だけ
    黒岩に振る。**道が明るく開けたマスが暗い**向き（基の註記）は守る——通りは磨かれて照る。
    """
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['dark']
    face = _kyu_flag_face(rng, [C['char_l'], C['sco'], C['sco_d']], [0.46, 0.30, 0.24])
    _grain(rng, face, face > 0, [C['sco_l'], C['gravel_d']], [0.07, 0.04], block=2)
    v[:, :, 1] = face
    return [('main', v, (0, 0, -2))]


def _ground_turf_kyu(name):
    """**旧地獄街道の開けた地面** — 同じ黒い岩畳。**目地からたまに草**（同指示
    「岩畳にはたまに草が生える」——草の茂みのプロップも tuft_chance で薄く立つ）。"""
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['dark']
    face = _kyu_flag_face(rng, [C['sco_d'], C['char'], C['char_l']], [0.44, 0.32, 0.24])
    #! 目地の草と苔。塊で少しだけ——撒きすぎると地上の野に見える。
    for _ in range(int(rng.integers(3, 7))):
        x, y = int(rng.integers(0, V - 3)), int(rng.integers(0, V - 3))
        shade = rng.choice([C['moss'], C['moss_d'], C['grass_d']], p=[0.4, 0.4, 0.2])
        face[x:x + int(rng.integers(1, 3)), y:y + int(rng.integers(1, 3))] = shade
    _grain(rng, face, face > 0, [C['moss_d']], [0.03], block=2)
    v[:, :, 1] = face
    return [('main', v, (0, 0, -2))]


def _yard_ground_kyu(name):
    """**旧地獄街道の前庭** — 持ち込んだ土の庭（同指示「敷地内の庭は土を持ち込んで
    敷いたということにして土の地面でよい」）。

    岩畳の街に**茶色の土**が置かれることで、敷地の内と外が色で割れる。
    基の「前庭は街路より暗い」は明度の序列だが、ここは**色相**（土の茶 ↔ 岩の黒）で
    区別が立つ——黒い岩畳より明るくなるのは指示に折り込み済みである。
    """
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['pack_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack_d'], C['soil'], C['dirt_d'], C['gravel_d']], [0.36, 0.28, 0.22, 0.14])
    _grain(rng, layer, layer > 0, [C['moss_d'], C['pebble']], [0.05, 0.05], block=3)
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def town_fence(name):
    """敷地の柵（§10.3「柵が二役を果たす」）。**低い**ので視線を遮らない。

    `fence_n/s/w/e` の 4 枚。1 マスに何辺でも立てられるよう、1 枚は 1 辺だけを持つ。

    意匠つきは材が違う（テルモラ＝板塀 / モリバント＝石の親柱に鉄の柵）。
    **高さは 3 つとも揃える。**柵の高さは「視線を遮らない」という約束そのもので、
    町ごとに変えると遮蔽の判定に効いてしまう。
    """
    style = _split_style(name)[0]
    if style == 'tel':
        return _fence_board(name)
    if style == 'hai':
        return _fence_hai(name)
    if style in ('mor', 'koma'):  # koma はモリバントの絵の転送（house_wall の註記）
        return _fence_iron(name)
    #! 彼岸の柵は §4.5 ⑤の**木柵**。人里の板柵をそのまま借りる（色は表の tint）。
    if style in ('jin', 'hak', 'moy', 'hig'):
        return _fence_ita(name)
    #! git（偽天棚）は**丸太の横木の牧柵**（雪で埋まる所に高い塀は建てない）。
    if style == 'git':
        return _fence_git(name)
    if style == 'ten':
        return _fence_renji(name)
    if style == 'kyu':
        return _fence_yokoita(name)
    side = _slice_of(name)
    th = 4
    height = 14
    v = np.zeros((V, V, height), np.uint8)
    lo = 0 if side in ('n', 'w') else V - th
    hi = lo + th

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 4, 6, C['oak'])       # 下段の横木
    put(0, V, 9, 11, C['oak_l'])    # 上段の横木
    for p in range(0, V, 10):       # 柱
        put(p, p + 3, 0, height, C['timber'])
        put(p, p + 3, height - 1, height, C['timber_l'])
    return [('main', v, (0, 0, 0))]


def _fence_sides(side, th):
    """柵の 1 辺を置くための添字を作る（`(lo, hi)` と、辺に沿う軸へ置く関数）。"""
    lo = 0 if side in ('n', 'w') else V - th
    return lo, lo + th


def _fence_board(name):
    """**テルモラの柵** — 縦板を隙間なく張った板塀。畑と街路を分ける低い塀。"""
    side = _slice_of(name)
    rng = rng_for(name)
    th, height = 4, 14
    v = np.zeros((V, V, height), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    #! 縦板（3 ボクセルごと）。**1 枚ずつ高さと色を変える**と「板を張った」に見える。
    for p in range(0, V, 3):
        top = height - int(rng.integers(0, 3))
        put(p, p + 3, 0, top, rng.choice([C['board'], C['board_l'], C['board_d']], p=[0.5, 0.25, 0.25]))
    put(0, V, 4, 6, C['beam'])          # 貫（横木）は板より濃い
    for p in range(0, V, 12):           # 親柱
        put(p, p + 3, 0, height, C['timber'])
        put(p, p + 3, height - 1, height, C['timber_l'])
    return [('main', v, (0, 0, 0))]


def _fence_iron(name):
    """**モリバントの柵** — 切石の親柱に鉄の縦格子。都市の街区の境。"""
    side = _slice_of(name)
    th, height = 4, 14
    v = np.zeros((V, V, height), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, 3, C['ash_d'])         # 石の腰
    put(0, V, 2, 3, C['ash'])
    for p in range(1, V, 4):            # 鉄の縦格子
        put(p, p + 1, 3, height - 2, C['iron'])
    put(0, V, height - 3, height - 1, C['iron_l'])   # 笠木
    for p in range(0, V, 14):           # 石の親柱
        put(p, p + 4, 0, height, C['ash'])
        put(p, p + 4, height - 2, height, C['ash_l'])
    return [('main', v, (0, 0, 0))]


def _fence_renji(name):
    """**天狗の里の柵** — 濃い柱の竪格子（透かし塀）。白い建物の前で黒い縦線になる。

    高さ（14）と厚み（4）は基と揃える（柵の高さは「視線を遮らない」約束そのもの）。
    人里の板塀（面）との差は**透かし**——格子の隙間から向こうが覗く。
    """
    side = _slice_of(name)
    th, height = 4, 14
    v = np.zeros((V, V, height), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, 2, C['wall_d'])                     # 土台の石
    for p in range(1, V, 4):                         # 竪格子
        put(p, p + 2, 2, height - 2, C['timber_d'])
    put(0, V, 6, 8, C['timber'])                     # 貫
    put(0, V, height - 3, height - 1, C['timber'])   # 笠木
    for p in range(0, V, 12):                        # 親柱
        put(p, p + 3, 0, height, C['timber_d'])
        put(p, p + 3, height - 1, height, C['timber_l'])
    return [('main', v, (0, 0, 0))]


def _fence_yokoita(name):
    """**旧地獄街道の柵** — 貫を通した黒い横板塀。

    高さ（14）と厚み（4）は基と揃える（柵の高さは「視線を遮らない」約束そのもの）。
    人里の板塀（縦板）とは**板の向き**で、天狗の竪格子（透かし）とは**面の詰まり**で分かれる。
    """
    side = _slice_of(name)
    rng = rng_for(name)
    th, height = 4, 14
    v = np.zeros((V, V, height), np.uint8)
    lo = 0 if side in ('n', 'w') else V - th
    ns = side in ('n', 's')

    def put(a0, a1, z0, z1, colour):
        if ns:
            v[a0:a1, lo:lo + th, z0:z1] = colour
        else:
            v[lo:lo + th, a0:a1, z0:z1] = colour

    #! 横板 3 段。**段ごとに 1 色**（罠 38）。板の間に影の線を 1 段挟む。
    for k in range(3):
        shade = rng.choice([C['shitami'], C['shitami_l'], C['shitami_d']], p=[0.5, 0.28, 0.22])
        put(0, V, k * 4, k * 4 + 3, shade)
        put(0, V, k * 4 + 3, k * 4 + 4, C['shitami_d'])
    put(0, V, height - 2, height, C['shitami_l'])    # 笠木
    for p in range(0, V, 10):                        # 柱
        put(p, p + 3, 0, height, C['char'])
        put(p, p + 3, height - 1, height, C['char_l'])
    return [('main', v, (0, 0, 0))]


def yard_ground(name):
    """前庭の地面（§10.5）。**街路と明確に違う地面**にしないと「歩けそう」に見える。

    踏み固めた土に砂利と苔を散らす。**街路より暗い**のは意図的で、明るいと柵の中の
    空き地のほうへ目が行く（1 度そうなった）。**この「街路より暗い」は意匠が変わっても
    守る**（明るさの序列が前庭と街路の役割そのものである）。
    """
    style = _split_style(name)[0]
    if style in ('jin', 'hak', 'moy'):
        return _yard_ground_jin(name)
    if style == 'hig':
        return _yard_ground_hig(name)
    if style == 'git':
        return _yard_ground_git(name)
    if style == 'hai':
        return _yard_ground_hai(name)
    if style == 'ten':
        return _yard_ground_ten(name)
    if style == 'kyu':
        return _yard_ground_kyu(name)
    if style == 'tel':
        rng = rng_for(name)
        v = _tile(2)
        v[:, :, 0] = C['pack_d']
        layer = np.zeros((V, V), np.uint8)
        _mottle(rng, layer, [C['pack_d'], C['pack'], C['soil'], C['dirt_d']], [0.38, 0.28, 0.20, 0.14])
        # 撒いた藁（畑つきの町の前庭）。**塊で**置く（1 ボクセルだと砂嵐＝罠 38）。
        _grain(rng, layer, layer > 0, [C['hay_d'], C['straw_d'], C['moss_d']], [0.09, 0.06, 0.05], block=3)
        v[:, :, 1] = layer
        return [('main', v, (0, 0, -2))]
    if style in ('mor', 'koma'):  # koma はモリバントの絵の転送（house_wall の註記）
        rng = rng_for(name)
        v = _tile(2)
        v[:, :, 0] = C['ash_d']
        layer = np.zeros((V, V), np.uint8)
        #! 暗い石畳の中庭。**街路（明るい大判の敷石）より 2 段暗い**ことで序列が付く。
        _mottle(rng, layer, [C['cob_d'], C['ash_d'], C['cob'], C['joint']], [0.36, 0.28, 0.22, 0.14])
        _grain(rng, layer, layer > 0, [C['moss_d'], C['moss'], C['cob_l']], [0.08, 0.05, 0.06], block=3)
        v[:, :, 1] = layer
        return [('main', v, (0, 0, -2))]
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['gravel_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['gravel'], C['gravel_d'], C['soil'], C['gravel_l']],
            [0.40, 0.30, 0.20, 0.10])
    # 苔（隅に寄せて散らす。一面に撒くと草地に見える）。
    _grain(rng, layer, layer > 0, [C['moss_d'], C['moss'], C['dirt_d']], [0.07, 0.05, 0.08], block=4)
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def well(name):
    """井戸。前庭の主役。**低い**（0.4 マス）ので視線を遮らない。"""
    v = np.zeros((V, V, 13), np.uint8)
    for x in range(V):
        for y in range(V):
            r2 = (x - 15.5) ** 2 + (y - 15.5) ** 2
            if 42.0 <= r2 <= 90.0:
                v[x, y, 0:11] = C['rock'] if ((x + y) // 3) % 2 else C['rock_d']
                v[x, y, 10:11] = C['rock_l']
            elif r2 < 42.0:
                v[x, y, 0:2] = C['wa_dd']  # 水面
    v[14:18, 6:26, 11:13] = C['timber']  # 桁
    return [('main', v, (0, 0, 0))]


def cart(name):
    """荷車。前庭・街路の飾り。"""
    v = np.zeros((V, V, 14), np.uint8)
    v[5:27, 9:23, 6:10] = C['oak']       # 荷台
    v[5:27, 9:23, 9:10] = C['oak_l']
    v[6:26, 10:22, 10:13] = C['hay']     # 積み荷
    for cy in (7, 25):                   # 車輪
        for x in range(V):
            for z in range(14):
                r2 = (x - 10) ** 2 + ((z - 5) * 1.0) ** 2
                if 16.0 <= r2 <= 30.0:
                    v[x, cy:cy + 2, z] = C['timber']
    v[26:31, 14:18, 7:9] = C['timber_l']  # 梶棒
    return [('main', v, (0, 0, 0))]


def flowerbed(name):
    """花壇。前庭の彩り。**いちばん低い**（0.25 マス）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.uint8)
    v[3:29, 3:29, 0:4] = C['timber_d']   # 枠
    v[5:27, 5:27, 0:5] = C['soil']
    for _ in range(26):
        x = int(rng.integers(6, 26))
        y = int(rng.integers(6, 26))
        v[x:x + 2, y:y + 2, 5:6] = C['grass_d']
        v[x:x + 2, y:y + 2, 6:7] = rng.choice([C['fl_w'], C['fl_y'], C['fl_r']])
    return [('main', v, (0, 0, 0))]


def haystack(name):
    """干し草の山。前庭・街路の飾り。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 18), np.uint8)
    for z in range(18):
        r = 13.0 * (1.0 - (z / 20.0) ** 2)
        for x in range(V):
            for y in range(V):
                if (x - 15.5) ** 2 + (y - 15.5) ** 2 <= r * r:
                    v[x, y, z] = C['hay'] if ((z // 3) % 2 == 0) else C['hay_d']
    v[15:18, 15:18, 15:18] = C['timber']  # 心棒
    if rng.random() < 0.5:
        v[10:14, 4:8, 0:3] = C['hay_d']
    return [('main', v, (0, 0, 0))]


def lamp_post(name):
    """街灯の柱。**炎は別体**（自発光はインスタンス単位＝罠 39）。"""
    v = np.zeros((V, V, 46), np.uint8)
    v[13:19, 13:19, 0:3] = C['rock_d']    # 沓石
    v[14:18, 14:18, 3:34] = C['iron']
    v[15:17, 15:17, 3:34] = C['iron_l']
    v[12:20, 12:20, 34:36] = C['iron_l']  # 受け
    #! 灯籠は**四隅の柱と上下の枠だけ**にする。四方を鉄で囲っていた版は、
    #! 中の `lamp_flame` が壁に隠れて**夜になっても 1 画素も光らなかった**
    #! （実機の夜の絵で気づいた。素材を作った当時は世界に置いていなかったので出なかった）。
    for (x0, x1) in ((12, 14), (18, 20)):
        for (y0, y1) in ((12, 14), (18, 20)):
            v[x0:x1, y0:y1, 36:44] = C['iron']
    v[12:20, 12:20, 36:37] = C['iron']    # 下枠
    v[12:20, 12:20, 43:44] = C['iron_l']  # 上枠
    v[11:21, 11:21, 44:46] = C['iron']    # 笠
    return [('main', v, (0, 0, 0))]


def lamp_flame(name):
    """街灯の火。`lamp_post` と同じマスへ置く。ゆらぎは振り子 2 枚（松明と同じ流儀）。"""
    a = np.zeros((6, 6, 9), np.uint8)
    a[1:5, 1:5, 0:7] = C['fl_mid']
    a[2:4, 2:4, 5:9] = C['fl_core']
    a[1:5, 1:5, 0:2] = C['fl_edge']
    b = np.zeros((4, 4, 7), np.uint8)
    b[1:3, 1:3, 0:7] = C['fl_core']
    return [('flame_a', a, (13, 13, 37)), ('flame_b', b, (14, 14, 38))]


def lamp_post_kyu(name):
    """**旧地獄街道の街灯** — 提灯掛け。黒木の竿の腕木から大提灯を提げる。

    基の鉄の街灯と同じマス・同じ格子（`lamp_step`）に置かれる。紙の胴は**昼から橙**
    （赤提灯は昼も赤い）。夜の灯は `lamp_flame_kyu`——紙の 1 ボクセル外へ光る殻を
    貼る別体（石灯籠の灯と同じ流儀。振り子にはしない——殻だけが揺れて紙が留まると、
    灯が提灯から抜け出して見える）。
    """
    v = np.zeros((V, V, 46), np.uint8)
    v[13:19, 13:19, 0:3] = C['rock_d']       # 沓石
    v[14:18, 14:18, 3:42] = C['char']        # 竿（黒木）
    v[15:17, 15:17, 3:42] = C['char_l']
    v[13:19, 13:19, 42:44] = C['char_l']     # 竿の頭
    v[14:18, 14:26, 40:42] = C['char']       # 腕木（南へ突き出す）
    v[15:17, 23:25, 36:40] = C['char_l']     # 吊り紐
    v[13:19, 20:26, 34:36] = C['char']       # 蓋
    v[12:20, 19:27, 24:34] = C['chochin']    # 紙の胴（8×8×10。遠目で点に潰れない大きさ）
    v[12:20, 19:27, 27:31] = C['chochin_l']  # 胴の中ほどの照り（蝋燭の高さ）
    v[13:19, 20:26, 22:24] = C['char']       # 口輪（下）
    return [('main', v, (0, 0, 0))]


def lamp_flame_kyu(name):
    """**旧地獄街道の街灯の灯** — 提灯の紙の 1 ボクセル外に貼る光る殻。

    `lamp_post_kyu` の紙（x 12..20 / y 19..27 / z 24..34）に合わせる。夜だけ置かれ、
    自発光は置く側が乗せる（罠 39）。接地しない（footprint は空）。
    """
    v = np.zeros((V, V, 46), np.uint8)
    v[13:19, 27:28, 25:33] = C['chochin_l']   # 南（カメラ側）
    v[13:19, 18:19, 25:33] = C['chochin_l']   # 北
    v[11:12, 20:26, 25:33] = C['chochin_l']   # 西
    v[20:21, 20:26, 25:33] = C['chochin_l']   # 東
    return [('main', v, (0, 0, 0))]


def ground_path(name):
    """踏み固めた土の通り道（2026-08-09 に決めた「建物と建物をつなぐ通り道は
    踏み固められていて地面がむき出しに」）。轍と小石を薄く散らす。

    意匠つきは町の格に合わせる（テルモラ＝石が疎らに埋まった半舗装 / モリバント＝
    大判の切石の街路）。**道と草の明暗の向きは 3 つとも同じ**——道が明るく草が暗い。
    逆にすると道が溝に見える。
    """
    style = _split_style(name)[0]
    if style == 'tel':
        return _ground_path_halfpaved(name)
    if style == 'mor':
        return _ground_path_flagstone(name)
    if style == 'jin':
        return _ground_path_jin(name)
    if style == 'ten':
        return _ground_path_ten(name)
    if style == 'kyu':
        return _ground_path_kyu(name)
    if style == 'koma':
        return _ground_path_brick(name)
    if style == 'hak':
        return _ground_path_hak(name)
    if style == 'moy':
        return _ground_path_moy(name)
    if style == 'hig':
        return _ground_path_hig(name)
    if style == 'git':
        return _ground_path_git(name)
    if style == 'kap':
        return _ground_path_kap(name)
    if style == 'ein':
        return _ground_path_ein(name)
    if style == 'kor':
        return _ground_path_kor(name)
    if style == 'myo':
        return _ground_path_myo(name)
    if style == 'kir':
        return _ground_path_kir(name)
    if style == 'hai':
        return _ground_path_hai(name)
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['pack_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack'], C['pack_l'], C['pack_d'], C['dirt']], [0.40, 0.26, 0.24, 0.10])
    # 轍（うっすら暗い帯を 1〜2 本）。**まっすぐにしない**（踏み跡なので蛇行する）。
    for _ in range(int(rng.integers(1, 3))):
        x = int(rng.integers(6, V - 6))
        for y in range(V):
            layer[max(0, min(V - 1, x)), y] = C['pack_d']
            layer[max(0, min(V - 1, x + 1)), y] = C['pack_d']
            x += int(rng.integers(-1, 2))
    _grain(rng, layer, layer > 0, [C['grit'], C['pebble']], [0.05, 0.04], block=2)
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def _ground_path_brick(name):
    """**紅魔館のレンガ道**（2026-08-18 に決めた「低めのランダムな岩とレンガ道」）。

    赤レンガの馬目地（半段ずらし）。レンガ 1 個は 8×4 ボクセルで、目地は上層を
    1 ボクセル貼り残して下層の暗色を覗かせる（地面は 2 層なので彫る厚みが無い）。
    """
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['joint']
    layer = np.zeros((V, V), np.uint8)
    bw, bh = 8, 4
    for row in range(V // bh):
        off = (row % 2) * (bw // 2)
        for col in range(-1, (V // bw) + 1):
            x0 = (col * bw) + off
            shade = rng.choice([C['tile'], C['roof_r'], C['cor_d'], C['drape']],
                               p=[0.44, 0.26, 0.18, 0.12])
            for x in range(max(0, x0), min(V, x0 + bw - 1)):
                for y in range(row * bh, min(V, (row * bh) + bh - 1)):
                    layer[x, y] = shade
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def _ground_path_halfpaved(name):
    """**テルモラの街路** — 踏み固めた土に、割った石が疎らに埋まった半舗装。

    城塞街だが畑つきの町なので、全面を敷石にすると格が上がりすぎてモリバントと
    見分けが付かなくなる。**石は面積の 3 割ほど**に留めて、残りは辺境と同じ土にする。
    """
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['pack_d']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack'], C['pack_l'], C['pack_d'], C['dirt']], [0.40, 0.26, 0.24, 0.10])
    #! 埋まった石。**塊で置く**（大きさをばらけさせると「敷いた」ではなく「埋まった」に見える）。
    for _ in range(int(rng.integers(5, 10))):
        x, y = int(rng.integers(0, V - 6)), int(rng.integers(0, V - 6))
        w, d = int(rng.integers(3, 7)), int(rng.integers(3, 7))
        layer[x:x + w, y:y + d] = rng.choice([C['rub'], C['rub_l'], C['rub_d']], p=[0.5, 0.28, 0.22])
    # 轍（石の上は通らないので土の所だけ）。**まっすぐにしない**。
    x = int(rng.integers(6, V - 6))
    for y in range(V):
        for k in (0, 1):
            xx = max(0, min(V - 1, x + k))
            if layer[xx, y] in (C['pack'], C['pack_l'], C['dirt']):
                layer[xx, y] = C['pack_d']
        x += int(rng.integers(-1, 2))
    _grain(rng, layer, layer > 0, [C['grit'], C['pebble']], [0.05, 0.04], block=2)
    v[:, :, 1] = layer
    return [('main', v, (0, 0, -2))]


def _ground_path_flagstone(name):
    """**モリバントの街路** — 大判の切石。目地は色ではなく**1 段彫る**（罠 44）。

    16 ボクセル（半マス）の石を段ごとに半枚ずらして敷く。都の目抜き通りなので**明るく**
    とり、脇の玉石（`ground_turf_mor_*`）との明暗で「表通りと裏」が読めるようにする。
    """
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['joint']       # 彫った目地の底
    face = np.zeros((V, V), np.uint8)
    step = 16
    for by in range(0, V, step):
        off = (by // step) % 2 * (step // 2)   # 半枚ずらす（芋目地を避ける）
        for bx in range(-step, V + step, step):
            x0, y0 = bx + off, by
            shade = rng.choice([C['flag'], C['flag_l'], C['flag_d']], p=[0.48, 0.28, 0.24])
            xa, xb = max(x0, 0), min(x0 + step - 1, V)
            ya, yb = max(y0, 0), min(y0 + step - 1, V)
            if xa < xb and ya < yb:
                face[xa:xb, ya:yb] = shade
    _grain(rng, face, face > 0, [C['pav_g1'], C['ash'], C['ash_l']], [0.12, 0.10, 0.08])
    # 欠けた角（1 段落として目地の底を見せる）。
    for _ in range(int(rng.integers(1, 4))):
        x, y = int(rng.integers(0, V - 3)), int(rng.integers(0, V - 3))
        face[x:x + int(rng.integers(2, 5)), y:y + int(rng.integers(2, 5))] = 0
    v[:, :, 1] = face
    return [('main', v, (0, 0, -2))]


def ground_turf(name):
    """短めの草（同上「それ以外は短めの草が生えているように」）。

    `ground_grass_*`（野原の草地）より**低く・まばら**にして、土が透けて見えるようにする。
    町の中で野原と同じ絵にすると、柵の中と外の区別が消える。

    意匠つきは「道でない開けたマス」の性格が町ごとに違う（テルモラ＝麦わらの混じる草地 /
    モリバント＝玉石を敷いた裏路地）。
    """
    style = _split_style(name)[0]
    if style == 'tel':
        return _ground_turf_stubble(name)
    if style == 'hai':
        return _ground_turf_hai(name)
    if style == 'mor':
        return _ground_turf_cobble(name)
    if style == 'moy':
        return _ground_turf_moy(name)
    if style == 'hig':
        return _ground_turf_hig(name)
    if style == 'git':
        return _ground_turf_git(name)
    if style in ('jin', 'hak'):
        return _ground_turf_jin(name)
    if style == 'ten':
        return _ground_turf_ten(name)
    if style == 'kyu':
        return _ground_turf_kyu(name)
    if style == 'kap':
        return _ground_turf_kap(name)
    if style == 'ein':
        return _ground_turf_ein(name)
    if style == 'kor':
        return _ground_turf_kor(name)
    if style == 'myo':
        return _ground_turf_myo(name)
    if style == 'kir':
        return _ground_turf_kir(name)
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['pack']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['turf'], C['turf_l'], C['turf_d'], C['pack']], [0.38, 0.24, 0.24, 0.14])
    # 土が覗く場所（草を抜く）。**塊で抜く**（1 ボクセルずつだと砂嵐になる＝罠 38）。
    for _ in range(int(rng.integers(2, 6))):
        x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        w, d = int(rng.integers(3, 7)), int(rng.integers(3, 7))
        layer[x:x + w, y:y + d] = 0
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_turf_stubble(name):
    """**テルモラの草地** — 刈った後の短い草に麦わらが混じる（畑つきの町）。"""
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['pack']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['turf'], C['turf_d'], C['turf_l'], C['pack']], [0.34, 0.26, 0.22, 0.18])
    #! 麦わらの筋。刈り跡なので**平行に並べる**（散らすと草地に紛れる）。
    for _ in range(int(rng.integers(2, 5))):
        y = int(rng.integers(0, V - 2))
        layer[:, y:y + 2] = C['hay_d'] if rng.random() < 0.5 else C['straw_d']
    for _ in range(int(rng.integers(2, 6))):   # 土が覗く所（塊で抜く＝罠 38）
        x, y = int(rng.integers(0, V - 5)), int(rng.integers(0, V - 5))
        layer[x:x + int(rng.integers(3, 7)), y:y + int(rng.integers(3, 7))] = 0
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_turf_cobble(name):
    """**モリバントの裏路地** — 玉石敷き。目地に苔が入る。

    4 ボクセル（1/8 マス）の玉石を段ごとに半枚ずらす。**マスの幅で割り切れる**ので、
    隣のマスと繋がって 1 枚の石畳に見える（マスごとに閉じた模様にすると格子になる＝罠 71）。
    表通り（`ground_path_mor_*` の大判の切石）より暗いので、明暗で表と裏が読める。
    """
    rng = rng_for(name)
    v = _tile(2)
    v[:, :, 0] = C['joint']
    face = np.zeros((V, V), np.uint8)
    step = 4
    for by in range(0, V, step):
        off = (by // step) % 2 * (step // 2)
        for bx in range(-step, V + step, step):
            x0 = bx + off
            shade = rng.choice([C['cob'], C['cob_l'], C['cob_d'], C['ash_d']], p=[0.40, 0.22, 0.24, 0.14])
            xa, xb = max(x0, 0), min(x0 + step - 1, V)
            ya, yb = by, min(by + step - 1, V)
            if xa < xb and ya < yb:
                face[xa:xb, ya:yb] = shade
    # 目地の苔（彫った所へ生える）。**塊で**（罠 38）。
    _grain(rng, face, face == 0, [C['moss_d'], C['moss']], [0.16, 0.10], block=2)
    v[:, :, 1] = face
    return [('main', v, (0, 0, -2))]


def palisade(name):
    """丸太を組み合わせた塀（2026-08-09 に決めた「町を囲む塀は丸太を組み合わせた塀に」）。

    **マスの中に丸太を 4×4 で立てる。**向きを持たせないので、厚み 1 マスでも 3 マスでも
    そのまま並べられる（石の城壁と違って狭間を載せる必要も無い）。
    見下ろすカメラでは木口（切り口）が絵の大半を占めるので、そこだけ明るい色にする。

    **意匠つきは石積みになる**（テルモラ＝乱石積みの低い塀 / モリバント＝切石の城壁）。
    茎の `palisade` は**枠の名前**（＝町を囲む塀）であって材ではない。
    """
    style = _split_style(name)[0]
    if style == 'tel':
        return _rampart_rubble(name)
    if style == 'mor':
        return _rampart_ashlar(name)
    if style == 'moy':
        return _rampart_moy(name)
    if style == 'hig':
        return _rampart_hig(name)
    #! git（偽天棚）の塀は**空積みの石垣**。地図に塀は 1 マスも無い（岩山と敷地だけ）が、
    #! 実機の読みは既知のマスから立つので、部分的にしか見ていない段で丸太の塀が出ないよう
    #! 用意しておく（廃洋館・永遠亭と同じ保険）。
    if style == 'git':
        return _rampart_git(name)
    if style in ('jin', 'hak'):
        return _rampart_dobei(name)
    if style == 'ten':
        return _rampart_neribei(name)
    if style == 'kyu':
        return _rock_face_kyu(name)
    if style == 'koma':
        return _rampart_iron_koma(name)
    if style == 'kap':
        return _rampart_kap(name)
    if style == 'ein':
        return _rampart_take_ein(name)
    if style == 'kor':
        return _rampart_tama_kor(name)
    if style == 'myo':
        return _rampart_tsuiji_myo(name)
    if style == 'kir':
        return _rampart_kuchi_kir(name)
    if style == 'hai':
        return _rampart_hai(name)
    rng = rng_for(name)
    height = 62
    v = np.zeros((V, V, height), np.uint8)
    step = 16          # 丸太 1 本 ＝ 半マス。**太いほうが「丸太」に見える**（細いと柵に見える）
    #! 半径はマスの半分より**大きく**とる。ちょうど 8 だと丸太の間の斜めに隙間が残り、
    #! 厚み 1 マスの所で塀の向こうが透けて見える。はみ出しはマスで切られるので、
    #! 胴は塞がったまま**天面だけ丸く**なる（見下ろすカメラに効くのは天面）。
    r = 8.6
    for bx in range(0, V, step):
        for by in range(0, V, step):
            cx, cy = bx + r, by + r
            top = int(rng.integers(height - 9, height))
            shade = rng.choice([C['log'], C['log_l'], C['log_d']], p=[0.5, 0.25, 0.25])
            #! 断面は円。**太い丸太は本数が少ない**ので、円でも四角形が膨れない（罠 48 の裏）。
            for x in range(bx, min(bx + step, V)):
                for y in range(by, min(by + step, V)):
                    d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
                    if d2 > r * r:
                        continue
                    # 先を尖らせる（上ほど細く）。d2 が大きいほど早く終わる
                    taper = min(10, int(round(6.0 * (d2 / (r * r)))))
                    v[x, y, 0:top - taper] = shade
                    v[x, y, top - taper - 1] = C['log_end']  # 木口
    # 縄で結わえた横木（2 段）。丸太の列を 1 本の塀にまとめて見せる。
    for z0 in (18, 42):
        band = v[:, :, z0:z0 + 3]
        band[band != 0] = C['lash']
    return [('main', v, (0, 0, 0))]


def _rampart_shell(v, height, course, body, light, dark, joint, rng):
    """石積みの塀の側面を彫る（テルモラとモリバントで共用）。

    **段は高さで切る。**そうすると厚み 1 マスでも 3 マスでも、隣とちゃんと段が通る。
    マスごとに四方の飾りを持たせると格子に見えるので（罠 71）、載せるのは
    **どの向きでも同じに見えるもの**（水平の段と縦の継ぎ目）だけにする。

    目地は `masonry()` と同じ流儀で**貼り残して彫る**。中を目地の色で満たしてから外皮に
    石を貼り、貼り残った所を 0 にすると 1 ボクセルの溝になって底の色が覗く。
    **色だけで目地を描かない**——溝は AO と影が勝手に暗くするので、素材の側でも暗く
    すると二重に効いて黒い線になる（罠 44）。
    """
    v[:, :, :] = joint
    stone = V // 4          # 石 1 個の幅（8 ボクセル＝1/4 マス）
    shell = np.zeros((V, V, height), bool)
    shell[0, :, :] = shell[V - 1, :, :] = shell[:, 0, :] = shell[:, V - 1, :] = True
    faces = (
        (lambda a0, a1, z0, z1, c: v.__setitem__((0, slice(a0, a1), slice(z0, z1)), c)),
        (lambda a0, a1, z0, z1, c: v.__setitem__((V - 1, slice(a0, a1), slice(z0, z1)), c)),
        (lambda a0, a1, z0, z1, c: v.__setitem__((slice(a0, a1), 0, slice(z0, z1)), c)),
        (lambda a0, a1, z0, z1, c: v.__setitem__((slice(a0, a1), V - 1, slice(z0, z1)), c)),
    )
    for z in range(course - 1, height, course):
        z0 = max(0, z - course + 1)
        off = ((z // course) % 2) * (stone // 2)
        for put in faces:
            #! 石ごとの明暗（塊単位＝罠 38）。段を石の幅で割って振り、**上端 1 列と
            #! 縦の継ぎ目 1 列は貼り残す**（そこが目地になる）。
            for p in range(off, V + stone, stone):
                a0, a1 = max(p, 0), min(p + stone - 1, V)
                if a0 < a1:
                    put(a0, a1, z0, z, rng.choice([body, light, dark], p=[0.5, 0.26, 0.24]))
    #! 貼り残した所を彫る。**接地層と天面は彫らない**（罠 5。隣との間から背景が抜ける）。
    carve = shell & (v == joint)
    carve[:, :, 0] = False
    carve[:, :, height - 1] = False
    v[carve] = 0


def _rampart_rubble(name):
    """**テルモラの塀** — 乱石積みの低い城壁。天面は土の歩廊で草が生えている。

    高さ 1.4 マス。辺境の丸太（1.94 マス）より**低い**のは、テルモラの塀が防柵ではなく
    「畑と街区を分ける囲い」だからで、代わりに厚みと石で格を出す。
    """
    rng = rng_for(name)
    height, course = 46, 7
    v = np.zeros((V, V, height), np.uint8)
    _rampart_shell(v, height, course, C['rub'], C['rub_l'], C['rub_d'], C['joint'], rng)
    #! 天面は**土と草の歩廊**。見下ろすカメラでは天面が絵の大半なので、ここで塀の性格が決まる
    #! （罠 41・76）。石の天端にすると町の中まで石に見えてモリバントと紛れる。
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack'], C['pack_d'], C['turf_d'], C['turf']], [0.36, 0.28, 0.20, 0.16])
    v[:, :, height - 1] = layer
    v[:, :, height - 2] = C['rub_d']
    return [('main', v, (0, 0, 0))]


def _rampart_ashlar(name):
    """**モリバントの城壁** — 切石を積んだ高い城壁。天面は敷石の歩廊。

    高さ 2.2 マス。**狭間は載せない**——マスごとに四方の凹凸を持たせると、厚みのある壁の上が
    小さな窪みの並びになって格子に見える（罠 71 でいちど踏んだ）。狭間は角の円塔だけが持つ。
    """
    rng = rng_for(name)
    height, course = 70, 6
    v = np.zeros((V, V, height), np.uint8)
    _rampart_shell(v, height, course, C['ash'], C['ash_l'], C['ash_d'], C['joint'], rng)
    # 上端の胴蛇腹（1 段の張り出しの代わりに明るい帯）。**外周だけ**なので格子にならない。
    for face in (0, V - 1):
        v[face, :, height - 4:height - 2] = C['ash_l']
        v[:, face, height - 4:height - 2] = C['ash_l']
    #! 天面は敷石の歩廊（都の城壁は人が歩く）。
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['flag'], C['flag_d'], C['flag_l'], C['moss_d']], [0.40, 0.28, 0.22, 0.10])
    v[:, :, height - 1] = layer
    v[:, :, height - 2] = C['ash_d']
    return [('main', v, (0, 0, 0))]


def _rampart_iron_koma(name):
    """**紅魔館の塀** — 石の土台（1 マス）に鉄のとげとげした柵（2 マス）。計 3 マス。

    2026-08-18 に決めた:「塀はベースは今までの塀が地面から1ブロック土台として。
    土台のうえに２ブロックの高さの塀の鉄のとげとげした柵が乗っている形で。合計３ブロック」。

    **粗な柵にする**（2026-08-18 デザイン4 に気づいた:「柵が柵になっていない。
    柵は土台ブロックの上面の１辺のうえに鉄棒が３本立っている程度の租な状態でよい」
    ——初版のピッチ 8 の格子 16 本は鉄棒の林になり、館の正面まで隠した）。
    土台の上面の**中央の 1 列に鉄棒 3 本**だけ。向きは持たない（中央列なので
    どちらから見ても同じまばらさ）。
    """
    rng = rng_for(name)
    height = 96
    base = 32
    v = np.zeros((V, V, height), np.uint8)
    # 石の土台 1 マス。切石＋目地（鉄柵を受ける洋館の基礎）。天端は笠石で 1 段明るく。
    _rampart_shell(v[:, :, 0:base], base, 8, C['wall'], C['wall_l'], C['wall_d'], C['joint'], rng)
    v[:, :, base - 2] = C['wall_d']
    v[:, :, base - 1] = C['wall_l']
    # 鉄棒 3 本（中央の 1 列・太さ 2）。先は槍の穂。
    tips = height - 8
    for bx in (5, 15, 25):
        shade = C['iron'] if rng.random() < 0.6 else C['iron_l']
        v[bx:bx + 2, 15:17, base:tips] = shade
        v[bx, 15, tips:height - 2] = C['steel_d']  # 穂先
    return [('main', v, (0, 0, 0))]


def palisade_base_koma(name):
    """紅魔館の塀の**内側のマス**——石の土台だけ（柵なし・高さ 1 マス）。

    2026-08-19 デザイン5 に決めた:「建物を囲む柵は外周1マスだけ土台の上に
    柵内側は土台だけに」。地図の塀は 2〜4 マス幅の帯で、全マスに鉄柵を立てると棒の列が
    重なって館を隠す。柵（`palisade_koma`）は帯の外周 1 列だけにし、内側のマスは
    この土台で石のテラスにする（選び分けは `terrain_view.cpp` の Rampart 置き）。
    """
    rng = rng_for(name)
    base = 32
    v = np.zeros((V, V, base), np.uint8)
    _rampart_shell(v, base, 8, C['wall'], C['wall_l'], C['wall_d'], C['joint'], rng)
    v[:, :, base - 2] = C['wall_d']
    v[:, :, base - 1] = C['wall_l']
    return [('main', v, (0, 0, 0))]


def watchtower(name):
    """木造のやぐら（同上「四隅には木造のやぐらを」）。塀の出隅に立てる。

    4 本の柱＋筋交い→床→手すり→切妻の屋根。高さ 3.1 マス。**塀より頭ひとつ高い**
    ことが「見張り台」の読みを作るので、丸太の塀（1.75 マス）とは差をつける。

    意匠つきは塀に合わせる（テルモラ＝石の胴に木の切妻 / モリバント＝円塔に狭間と
    円錐の瓦屋根）。**どれも塀より頭ひとつ高い**という約束は変えない。
    """
    style = _split_style(name)[0]
    if style == 'tel':
        return _tower_stone_gable(name)
    if style == 'hai':
        return _watchtower_hai(name)
    if style == 'mor':
        return _tower_round(name)
    if style in ('jin', 'hak', 'moy'):
        return _tower_hinomi(name)
    #! 彼岸（デザイン14）は**役所の隅櫓**（白漆喰＋黒瓦の宝形）。丸太の見張り台では
    #! 是非曲直庁の外郭に木の櫓が 4 基立つ。
    if style == 'hig':
        return _tower_sumi_hig(name)
    #! git（偽天棚）は**ケルン**（登山の道標の石積み）。塀の隅に木の見張り台は立たない。
    if style == 'git':
        return _tower_cairn_git(name)
    if style == 'ten':
        return _tower_takadono(name)
    if style == 'kyu':
        return _tower_yagura(name)
    if style == 'koma':
        return _tower_brick_koma(name)
    if style == 'myo':
        return _watchtower_myo(name)
    height = 100
    v = np.zeros((V, V, height), np.uint8)
    posts = ((2, 8), (22, 28))
    for (x0, x1) in posts:
        for (y0, y1) in posts:
            v[x0:x1, y0:y1, 0:72] = C['log']
            v[x0 + 1:x1 - 1, y0 + 1:y1 - 1, 0:72] = C['log_d']
    # 筋交い（段ごとの水平材）。
    for z in (18, 40, 60):
        v[2:30, 2:8, z:z + 3] = C['log_l']
        v[2:30, 22:28, z:z + 3] = C['log_l']
        v[2:8, 2:30, z:z + 3] = C['log_l']
        v[22:28, 2:30, z:z + 3] = C['log_l']
    v[0:32, 0:32, 72:76] = C['timber']       # 床（張り出す）
    v[1:31, 1:31, 75:76] = C['timber_l']
    for (a0, a1) in ((0, 3), (29, 32)):      # 手すり
        v[a0:a1, 0:32, 76:86] = C['log']
        v[0:32, a0:a1, 76:86] = C['log']
    v[0:32, 0:32, 84:86][v[0:32, 0:32, 84:86] != 0] = C['log_l']
    for z in range(86, height):              # 切妻の屋根（東西に棟）
        drop = (z - 86) * 2
        lo, hi = drop, 32 - drop
        if lo >= hi:
            break
        v[0:32, lo:hi, z] = C['timber_d'] if ((z // 3) % 2) else C['timber']
    return [('main', v, (0, 0, 0))]


def _tower_stone_gable(name):
    """**テルモラの櫓** — 乱石積みの胴に木の見張り台と切妻屋根。高さ 2.9 マス。

    塀（1.4 マス）より頭 1.5 つぶん高い。石の胴をマスいっぱいに立てるので、丸太のやぐらより
    どっしり見える——「木で組んだ物見」ではなく「石の塔に物見を載せた」形である。
    """
    rng = rng_for(name)
    height = 94
    body = 60           # 石の胴
    v = np.zeros((V, V, height), np.uint8)
    _rampart_shell(v[:, :, 0:body], body, 7, C['rub'], C['rub_l'], C['rub_d'], C['joint'], rng)
    # 木の見張り台。**マスからはみ出せない**ので、張り出しではなく材の違いで段を作る。
    v[:, :, body:body + 4] = C['timber']
    v[1:V - 1, 1:V - 1, body + 3:body + 4] = C['timber_l']
    for (a0, a1) in ((0, 3), (V - 3, V)):       # 手すり
        v[a0:a1, :, body + 4:body + 14] = C['oak']
        v[:, a0:a1, body + 4:body + 14] = C['oak']
    v[:, :, body + 12:body + 14][v[:, :, body + 12:body + 14] != 0] = C['oak_l']
    for z in range(body + 14, height):          # 切妻の屋根（東西に棟）
        drop = (z - (body + 14)) * 2
        lo, hi = drop, V - drop
        if lo >= hi:
            break
        v[:, lo:hi, z] = C['board_d'] if ((z // 3) % 2) else C['board']
    return [('main', v, (0, 0, 0))]


def _tower_round(name):
    """**モリバントの角塔** — 切石の円塔。狭間と円錐の瓦屋根。高さ 3.4 マス。

    城壁（2.2 マス）より頭ひとつ高い。**狭間はここだけが持つ**——塀のマスぜんぶに載せると
    厚みのある壁の上が窪みの並びになって格子に見える（罠 71）。塔は成分ごとに 4 つ
    しかないので、そこへ寄せれば「城壁に角塔がある」と読める。
    """
    rng = rng_for(name)
    height = 108
    body = 76           # 石の胴（狭間の下端まで）
    merlon = 12         # 狭間の高さ
    cx = cy = (V - 1) / 2.0
    r = 15.6
    v = np.zeros((V, V, height), np.uint8)
    for x in range(V):
        for y in range(V):
            if (((x - cx) ** 2) + ((y - cy) ** 2)) > (r * r):
                continue
            for z in range(body):
                v[x, y, z] = C['ash']
    # 段の目地と石の明暗（外周だけ。中は greedy が消す）。
    for z in range(5, body, 6):
        for x in range(V):
            for y in range(V):
                if v[x, y, z] == 0:
                    continue
                d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
                if d2 > ((r - 1.2) ** 2):
                    v[x, y, z] = C['joint']
                    v[x, y, max(0, z - 5):z] = rng.choice([C['ash'], C['ash_l'], C['ash_d']],
                                                          p=[0.5, 0.26, 0.24])
    #! 狭間（メルロン）。円周を 8 つに割って 1 つおきに立てる。
    for x in range(V):
        for y in range(V):
            d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
            if (d2 > (r * r)) or (d2 < ((r - 4.5) ** 2)):
                continue
            ang = math.atan2(y - cy, x - cx)
            if int((ang + math.pi) / (math.pi / 4)) % 2 == 0:
                v[x, y, body:body + merlon] = C['ash']
                v[x, y, body + merlon - 1] = C['ash_l']
    #! 円錐の瓦屋根。**塔の径いっぱいから立ち上げる**（細いと物見台に見える）。
    cone0 = body + merlon
    for z in range(cone0, height):
        t = (z - cone0) / float(height - cone0)
        rr = r * (1.0 - t)
        for x in range(V):
            for y in range(V):
                if (((x - cx) ** 2) + ((y - cy) ** 2)) <= (rr * rr):
                    v[x, y, z] = C['tile_d'] if ((z // 3) % 2) else C['tile']
    return [('main', v, (0, 0, 0))]


def _tower_brick_koma(name):
    """**紅魔館の監視塔** — 赤レンガの円塔・臙脂の尖り屋根。高さ 4 マス。

    2026-08-18 に決めた:「塀の角にはレンガ作りの監視塔たかさは4ブロック」。
    形はモリバントの角塔（円塔＋狭間＋円錐屋根）の流儀で、材を赤レンガに替え、
    鉄柵の塀（3 マス）より頭ひとつ高くする。足元は塀の土台と同じ切石の基部。
    """
    rng = rng_for(name)
    height = 128
    body = 92           # レンガの胴
    merlon = 10
    stone_base = 20     # 切石の基部（塀の土台と同じ材で受ける）
    cx = cy = (V - 1) / 2.0
    r = 15.6
    v = np.zeros((V, V, height), np.uint8)
    for x in range(V):
        for y in range(V):
            if (((x - cx) ** 2) + ((y - cy) ** 2)) > (r * r):
                continue
            for z in range(body):
                v[x, y, z] = C['wall'] if z < stone_base else C['tile']
    # レンガの段（4 ボクセル＝レンガ 1 段）と塊の明暗。外周だけ彫る（中は greedy が消す）。
    for z in range(stone_base + 3, body, 4):
        for x in range(V):
            for y in range(V):
                if v[x, y, z] == 0:
                    continue
                d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
                if d2 > ((r - 1.2) ** 2):
                    v[x, y, z] = C['joint']
                    v[x, y, max(stone_base, z - 3):z] = rng.choice(
                        [C['tile'], C['roof_r'], C['drape']], p=[0.5, 0.28, 0.22])
    # 縦のスリット窓（南面の外皮に黒い銃眼 2 本。監視塔の読み）。
    for sx in (int(cx) - 5, int(cx) + 4):
        for x in range(sx, sx + 2):
            for y in range(V):
                d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
                if (d2 <= (r * r)) and (d2 > ((r - 2.2) ** 2)) and (y < cy - r * 0.45):
                    v[x, y, 48:72] = C['obs']
    #! 狭間（メルロン）。円周を 8 つに割って 1 つおきに立てる。
    for x in range(V):
        for y in range(V):
            d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
            if (d2 > (r * r)) or (d2 < ((r - 4.5) ** 2)):
                continue
            ang = math.atan2(y - cy, x - cx)
            if int((ang + math.pi) / (math.pi / 4)) % 2 == 0:
                v[x, y, body:body + merlon] = C['tile']
                v[x, y, body + merlon - 1] = C['roof_r']
    #! 臙脂の尖り屋根（紅魔館の「暗い臙脂」）。径いっぱいから先端 1 点へ。
    cone0 = body + merlon
    for z in range(cone0, height):
        t = (z - cone0) / float(height - cone0)
        rr = (r * (1.0 - t)) + 0.8
        for x in range(V):
            for y in range(V):
                if (((x - cx) ** 2) + ((y - cy) ** 2)) <= (rr * rr):
                    v[x, y, z] = C['obs'] if ((z // 3) % 2) else C['obs_l']
    return [('main', v, (0, 0, 0))]


def parapet(name):
    """**城壁の胸壁**（2026-08-09 に決めた:「中世の城壁のように上を人が歩けるような
    形で石の柵を城壁の上にたてよう」）。

    柵と同じ**「1 枚 1 辺」**（`fence_*` の流儀）。塀のマスは四方どちらが外かを持っていないので、
    マスごとに四方へ狭間を載せると**厚みのある壁の上が窪みの並び**になって格子に見える
    （罠 71 でいちど踏んだ）。置く側（`town_plan.cpp` の `fences`）が
    「その辺の隣が塀でない」マスだけにビットを立て、ここは 1 辺ぶんだけを作る。

    狭間の周期は **8 ボクセル**（メルロン 5 ＋ 空き 3）。マスの幅 32 で割り切れるので、
    隣のマスと繋がって 1 本の狭間の列になる。
    """
    side = _slice_of(name)
    th = 5              # 厚み（歩廊を狭めすぎない）
    height = 17         # 0.53 マス。**人の腰**の高さに見せる
    v = np.zeros((V, V, height), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, 7, C['ash'])              # 腰壁（連続。ここが「歩ける縁」を作る）
    put(0, V, 6, 7, C['ash_l'])            # 天端の水切り
    for p in range(0, V, 8):               # 狭間（メルロン）
        put(p, p + 5, 7, height, C['ash'])
        put(p, p + 5, height - 2, height, C['ash_l'])
        put(p + 4, p + 5, 0, height, C['joint'])   # 縦の目地
    put(0, V, 3, 4, C['joint'])            # 段の目地
    return [('main', v, (0, 0, 0))]


def fountain_pillar(name):
    """噴水の柱（2026-08-09 に決めた:「水しぶきが 4 本の柱にたれ落ちる感じで」）。

    モリバントの噴水は、実データでは**中央の水マスを 4 つの独立した石マスが囲む**形をしている
    （`03_Morivant.txt` の 31〜35 行）。その 4 マスがこれで、真ん中に `fountain_jet` が立つ。
    """
    rng = rng_for(name)
    height = 46
    cx = cy = (V - 1) / 2.0
    v = np.zeros((V, V, height), np.uint8)
    for x in range(V):
        for y in range(V):
            d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
            if d2 <= (13.5 ** 2):
                v[x, y, 0:6] = C['ash_d']          # 台座
            if d2 <= (9.5 ** 2):
                v[x, y, 6:height - 8] = C['ash']   # 柱
            if d2 <= (12.5 ** 2):
                v[x, y, height - 8:height - 2] = C['ash_l']  # 受け皿の縁
            if d2 <= (9.0 ** 2):
                v[x, y, height - 4:height - 2] = C['jetwa']  # 溜まった水
    # 段の目地（外周だけ）。
    for z in (11, 17, 23, 29):
        for x in range(V):
            for y in range(V):
                d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
                if ((9.5 ** 2) - 22) <= d2 <= (9.5 ** 2):
                    v[x, y, z] = C['joint']
    #! 受け皿から溢れて柱を伝う水。**塊で**置く（1 ボクセルずつだと砂嵐＝罠 38）。
    for _ in range(int(rng.integers(3, 6))):
        ang = float(rng.random()) * 2.0 * math.pi
        px = int(round(cx + (9.0 * math.cos(ang))))
        py = int(round(cy + (9.0 * math.sin(ang))))
        z1 = height - 8
        z0 = int(rng.integers(8, 20))
        for x in range(max(0, px - 1), min(V, px + 2)):
            for y in range(max(0, py - 1), min(V, py + 2)):
                if v[x, y, z0:z1].any():
                    v[x, y, z0:z1] = C['spray']
    return [('main', v, (0, 0, 0))]


FOUNTAIN_SPAN = 3               #!< 噴水は 3×3 マス（中央の噴き上げ＋四方への飛沫）
FOUNTAIN_V = V * FOUNTAIN_SPAN
FOUNTAIN_TOP = 92               #!< 2.9 マス。**柱（1.44 マス）の倍**は上げないと「噴き上げ」に見えない


def _blob(v, cx, cy, cz, r, colour):
    """球の塊を置く（飛沫 1 粒）。**塊で置く**ので greedy が効く（罠 38・48）。"""
    ri = int(math.ceil(r))
    for x in range(max(0, cx - ri), min(v.shape[0], cx + ri + 1)):
        for y in range(max(0, cy - ri), min(v.shape[1], cy + ri + 1)):
            for z in range(max(0, cz - ri), min(v.shape[2], cz + ri + 1)):
                if (((x - cx) ** 2) + ((y - cy) ** 2) + ((z - cz) ** 2)) <= (r * r):
                    v[x, y, z] = colour


def fountain_jet(name):
    """**噴水の噴き上げ**（2026-08-09 に決めた:「動的な水しぶきを高く噴き上げる噴水を
    中央に。水しぶきが 4 本の柱にたれ落ちる感じで」）。

    3×3 マス。真ん中のマスから水柱が上がり、頂点から**四方の柱へ 4 本の弧**が落ちる。
    動きは剛体しか無い（`MotionKind` は静止・回転・振り子・風）ので、
    **弧を振り子にして位相をずらす**ことで「脈打って噴き出す」ように見せる。
    水柱そのものは風（`wind`）で穂先だけ揺らす。

    @note **接地しない**（origin_z を 0 より上にする）ので footprint は空。噴水のマスは
    水であって、当たり判定は地形が持っている。
    """
    rng = rng_for(name)
    mid = FOUNTAIN_V // 2
    parts = []

    #! (1) 水柱。根元は太く、上ほど細く砕ける。
    column = np.zeros((FOUNTAIN_V, FOUNTAIN_V, FOUNTAIN_TOP), np.uint8)
    for z in range(FOUNTAIN_TOP):
        t = z / float(FOUNTAIN_TOP)
        r = 7.0 - (4.2 * t)
        shade = C['jetwa'] if t < 0.45 else (C['spray'] if t < 0.78 else C['foam'])
        ri = int(math.ceil(r))
        for x in range(mid - ri, mid + ri + 1):
            for y in range(mid - ri, mid + ri + 1):
                if (((x - mid) ** 2) + ((y - mid) ** 2)) <= (r * r):
                    column[x, y, z] = shade
    parts.append(('column', column, (0, 0, 2)))

    #! (2) 頂の飛沫の冠。振り子で**速く小さく**振れる（水が砕けて散る所）。
    crown = np.zeros((FOUNTAIN_V, FOUNTAIN_V, FOUNTAIN_TOP + 18), np.uint8)
    for k in range(22):
        ang = (k / 22.0) * 2.0 * math.pi
        rad = 5.0 + (float(rng.random()) * 7.0)
        _blob(crown, int(round(mid + (rad * math.cos(ang)))),
              int(round(mid + (rad * math.sin(ang)))),
              FOUNTAIN_TOP + int(rng.integers(-4, 12)),
              1.6 + (float(rng.random()) * 1.4),
              C['foam'] if (k % 3) else C['spray'])
    parts.append(('crown', crown, (0, 0, 2)))

    #! (3) 四方の柱へ落ちる弧。**1 本ずつ別のパーツ**にして位相をずらす（同じ位相だと
    #! 4 本が一斉に上下して「呼吸する十字」に見える）。
    for index, (dx, dy) in enumerate(((0, -1), (0, 1), (-1, 0), (1, 0))):
        arc = np.zeros((FOUNTAIN_V, FOUNTAIN_V, FOUNTAIN_TOP + 18), np.uint8)
        steps = 26
        for s in range(steps + 1):
            t = s / float(steps)
            reach = t * (V * 0.98)                       # 隣のマス（柱）の真上まで
            z = FOUNTAIN_TOP + int(round((16.0 * t) - (60.0 * t * t)))
            _blob(arc, int(round(mid + (dx * reach))), int(round(mid + (dy * reach))), z,
                  2.6 - (1.0 * t), C['foam'] if (s % 4) else C['spray'])
        parts.append(('arc_%d' % index, arc, (0, 0, 2)))
    return parts


def fountain_parts():
    """噴水の動き。**水柱は風・冠と弧は振り子**（剛体しか無いので、位相で「脈」を作る）。

    振り子の支点は**必ずその部品のボクセルの中**に置く（`load_prefab` の照合＝§7.2-2 が
    見ている。松明と街灯で 1 度踏んだ＝罠 73）。ここでは水柱の頂上が支点で、
    冠も弧もそこから始まっている。
    """
    mid = float(FOUNTAIN_V // 2)
    top = float(FOUNTAIN_TOP)
    decl = [
        {'name': 'column', 'voxels': 'column', 'grounded': False,
         'motion': {'kind': 'wind'}, 'wind_k': 0.45},
        {'name': 'crown', 'voxels': 'crown', 'grounded': False,
         'pivot': [mid, mid, top],
         'motion': {'kind': 'pendulum', 'axis': 'x', 'amplitude': 5.0,
                    'period': 0.83, 'phase': 0.0, 'damping': 0.0},
         'wind_k': 0.0},
    ]
    #! 弧は 4 本。**周期も位相もずらす**（そろえると噴水が呼吸しているように見える）。
    for index, (axis, period, phase) in enumerate((('x', 1.30, 0.0), ('x', 1.30, 3.14),
                                                   ('y', 1.55, 1.57), ('y', 1.55, 4.71))):
        decl.append({'name': 'arc_%d' % index, 'voxels': 'arc_%d' % index, 'grounded': False,
                     'pivot': [mid, mid, top],
                     'motion': {'kind': 'pendulum', 'axis': axis, 'amplitude': 4.0,
                                'period': period, 'phase': phase, 'damping': 0.0},
                     'wind_k': 0.0})
    return decl


# ------------------------------------------- 岩山（P10 第 3 期。ズル＝山の中の町）
#
# 2026-08-10 に決めた:
#   「ズル 山が丸太の塀になっているのを**複数のマスにわたって表現された岩山**にして。
#     岩山には**ちらほらと高山植物**が生えているように」
#
#: 岩塊の段と高さ（ボクセル）。**段は「山の外からの深さ」**で、置く側が `slices` から引く。
#: 麓 1.4 マス → 峰 4.9 マスを 4 段で上がるので、3〜4 マスかけて山になる。
#: 1 マスで 1.4 マスぶん立ち上がるのは**塀**であって山ではない、というのがこの表の要点。
CRAG_TIERS = ('low', 'mid', 'high', 'peak')
CRAG_HEIGHT = {'low': 44, 'mid': 78, 'high': 118, 'peak': 158}


def crag(name, h_override=None, bands=None, face_mix=None):
    """岩山の岩塊。**1 マス 1 個のまま「複数のマスにまたがる山」に見せる。**

    マスごとに同じ高さの岩を置くと、材が石でも**塀にしか見えない**（丸太の塀がそうだった）。
    山に見せるのは**段**である。麓 1.4 マス → 峰 4.9 マスを 4 段で上がるので、谷から見ると
    3〜4 マスかけて壁がせり上がる。段を選ぶのは置く側（山の外からの深さ）。

    形はそのうえで 2 つだけ足す。**どちらも「隣とちょうど揃わない」ことが仕事**である。

    ======================  ==================================================
    ゆるい斜めの削ぎ 1 枚    段の天面が一枚板にならない。強く削ぐと**マスごとの尖塔**に
                             なって山ではなく岩柱の林になる（1 度そうした）
    粗い凹凸（4 ボクセル）   天端を 0〜6 ボクセル欠く。**塊単位**で欠くので、
                             隣との継ぎ目が格子ではなく岩の割れに見える
    ======================  ==================================================

    **接地層は削らない**（罠 5。隣との間から背景が抜ける）。削ぐのは腰から上だけで、
    足元はマスいっぱいの岩のままにする——「入れない所」の読みは足元で決まる。

    天面を明るくしないのは岩盤（`bedrock`）と同じ理由である。見下ろすカメラでは天面が
    絵の大半を占めるので、明るいと地面より明るくなって「登れる所」に見える。
    **色も塊ごと**（4×4）に置く。1 ボクセルずつ振ると天面が砂粒の斑になった（罠 38）。
    """
    #! 高さと色は差し替えられる（2026-08-18。紅魔館の氷塊と低い岩場）。
    #! `h_override=None` の経路は従来と 1 ビットも変えない（rng の消費順も同じ）。
    if h_override is None:
        tier = name.split('_')[1]
        h = CRAG_HEIGHT[tier]
        low_tier = (tier == 'low')
    else:
        h = int(h_override)
        low_tier = (h <= 30)
    rng = rng_for(name)
    #! ここまではマスいっぱい（足元は削らない）。低い段ほど削れる余地が少ない。
    base = min(h - 8, 14 if low_tier else 22)

    # --- 天面の高さの場 ---
    xs = np.arange(V, dtype=np.float32)[:, None]
    ys = np.arange(V, dtype=np.float32)[None, :]
    #! (a) ゆるい斜めの削ぎ 1 枚。落とすのは**いちばん深い角で高さの 1/4 まで**。
    ang = float(rng.uniform(0.0, 2.0 * math.pi))
    d = ((xs - 15.5) * math.cos(ang)) + ((ys - 15.5) * math.sin(ang))
    depth = float(rng.uniform(0.10, 0.26)) * h
    top = h - (np.clip((d - float(rng.uniform(-16.0, -2.0))) / 30.0, 0.0, 1.0) * depth)
    #! (b) 粗い凹凸。**4 ボクセルの塊**で欠く（1 ボクセルずつ欠くと天面が毛羽立つ）。
    chip = rng.integers(0, 7, size=((V + 3) // 4, (V + 3) // 4)).astype(np.float32)
    top -= np.repeat(np.repeat(chip, 4, 0), 4, 1)[:V, :V]
    tops = np.clip(np.rint(top), base, h).astype(np.int32)

    # --- 層理（z の帯）。岩盤と同じ流儀で、下ほど暗い ---
    if bands is None:
        bands = [C['crag_dd'], C['crag_d'], C['crag_b'], C['crag'], C['crag_l']]
    palette = np.array(bands, np.uint8)
    zgrid = np.arange(h)[None, None, :]
    solid = zgrid < tops[:, :, None]
    band_at = np.minimum((zgrid * len(bands)) // h, len(bands) - 1)
    #! 塊ごとの明暗（4×4×4。罠 38。ボクセルごとに散らすと greedy が効かない）。
    shape = ((V + 3) // 4, (V + 3) // 4, (h + 3) // 4)
    lump = rng.choice(bands, size=shape, p=[0.14, 0.26, 0.10, 0.34, 0.16]).astype(np.uint8)
    use_lump = rng.random(shape) < 0.45
    grow = (lambda a: np.repeat(np.repeat(np.repeat(a, 4, 0), 4, 1), 4, 2)[:V, :V, :h])
    v = np.where(solid, np.where(grow(use_lump), grow(lump), palette[band_at]), 0).astype(np.uint8)

    # --- 天面。**明るくしない。**塊ごとに、まばらに地衣（苔より灰がかった緑）を乗せる ---
    if face_mix is None:
        face_mix = ([C['crag_d'], C['crag'], C['lichen']], [0.54, 0.30, 0.16])
    face = rng.choice(face_mix[0],
                      size=((V + 3) // 4, (V + 3) // 4), p=face_mix[1]).astype(np.uint8)
    face = np.repeat(np.repeat(face, 4, 0), 4, 1)[:V, :V]
    for x in range(V):
        for y in range(V):
            v[x, y, int(tops[x, y]) - 1] = face[x, y]
    return [('main', v, (0, 0, 0))]


# ----------------------------------- 溶岩の泡（P10 第 3 期。2026-08-10 に決めた）
#
# 「むき出しの溶岩の地面は**タイル幅の 1/3 くらいのサイズの泡がゆっくりと浮かび上がって
#   はじけて、ガスが漂う**アニメーションをさせよう」
#
# **動きは剛体しか無い**（`MotionKind` は静止・回転・振り子・風）。上下の平行移動が無いので、
# 泡は**溶岩の下に沈めた車輪の縁**に付けて回す——輪が回ると泡が面を突き破って盛り上がり、
# 頂を過ぎるとまた沈む。沈んでいる間は溶岩のタイル（不透明）が隠すので、
# 見えるのは「膨らんで、はじけて、消える」ところだけになる。
#
# はじけるのは**同じ輪にもう 1 枚、位相を少し進めた飛沫の輪**を付けて出す。泡が頂を
# 過ぎた所で飛沫が顔を出すので、順番が「盛り上がる → 散る」に読める。
#
#: 溶岩の面（プレハブ原点から。置く側が根元を `kFootingDepth` 沈めるぶんを見込んである）
LAVA_SURFACE_Z = 1.5
LAVA_PIVOT_Z = -8 #: 車輪の中心。**面より下**（ここが浅いと泡が出ずっぱりになる）
LAVA_WHEEL_R = 13 #: 車輪の半径
#: (泡の中心 x, y, 回る軸, 速さ〈回転/秒〉, 位相, 泡の半径)
#: **軸を x と y で振り分ける**のは、隣り合ったマスで泡の流れる向きが揃わないようにするため。
LAVA_BUBBLES = (
    (11, 16, 'x', 0.11, 0.00, 5.5),
    (16, 12, 'y', 0.14, 0.35, 5.0),
    (20, 16, 'x', 0.09, 0.62, 6.0),
    (16, 21, 'y', 0.13, 0.18, 5.5),
    (13, 18, 'x', 0.16, 0.80, 5.0),
    (18, 15, 'y', 0.10, 0.47, 6.0),
)
LAVA_POP_LEAD = 0.055 #: 飛沫の位相の進み（1 周に対する割合）


def _lava_wheel_box(cz_bottom, span):
    """車輪の下端に置く部品の配列と原点。**支点が配列の中に入っている**こと（罠 73）。

    回転は描くときの行列なので、**掃く軌跡ぶんの配列は要らない**（配列は剛体の入れ物で、
    はみ出して回ってよい）。要るのは「描くボクセル」と「支点」が入ることだけである。
    """
    z0 = int(cz_bottom - span)
    z1 = int(LAVA_PIVOT_Z + 1)
    return np.zeros((V, V, z1 - z0), np.uint8), (0, 0, z0)


def lava_bubble(name):
    """溶岩の泡とガス。1 マス 1 個で、**変種ごとに泡の位置・速さ・位相が違う**。

    | 部品 | 何 | 動き |
    |---|---|---|
    | `bubble` | 熔けた泡（直径 ＝ **マス幅の 1/3**） | 回転（沈めた車輪の縁） |
    | `pop` | はじけた飛沫の輪 | 同じ車輪・**位相を少し進める** |
    | `gas_a` / `gas_b` | 漂うガス | 風（`wind_k` は控えめ。噴き上がらせない） |

    **ガスの素の色を明るくしない。**置く側が地形の自発光（溶岩は 2.10, 0.72, 0.22）を
    インスタンスに乗せるので、明るい灰にすると白く飛んで湯気に見える。
    """
    index = (int(name[-2:]) - 1) if name[-2:].isdigit() else 0
    px, py, _axis, _speed, _phase, radius = LAVA_BUBBLES[index % len(LAVA_BUBBLES)]
    rng = rng_for(name)
    parts = []

    #! (1) 泡。車輪のいちばん下に置く（回ると面を突き破って上がってくる）。
    cz = LAVA_PIVOT_Z - LAVA_WHEEL_R
    bubble, origin = _lava_wheel_box(cz, radius + 1)
    bz = int(cz - origin[2])
    for x in range(V):
        for y in range(V):
            dx = x - px
            dy = y - py
            if ((dx * dx) + (dy * dy)) > (radius * radius):
                continue
            h = math.sqrt(max(0.0, (radius * radius) - (dx * dx) - (dy * dy)))
            for dz in range(-int(h), int(h) + 1):
                z = bz + dz
                if (z < 0) or (z >= bubble.shape[2]):
                    continue
                #! 上ほど明るい（熱い薄皮が張っている所）。てっぺんに冷えた斑を少しだけ。
                t = (dz + h) / max(1.0, 2.0 * h)
                shade = C['bub_d'] if t < 0.34 else (C['bub'] if t < 0.72 else C['bub_l'])
                bubble[x, y, z] = shade
    for _ in range(4):
        ang = float(rng.uniform(0.0, 2.0 * math.pi))
        rr = float(rng.uniform(0.0, radius * 0.6))
        sx = int(round(px + (rr * math.cos(ang))))
        sy = int(round(py + (rr * math.sin(ang))))
        sz = bz + int(round(radius * 0.72))
        if (0 <= sx < V) and (0 <= sy < V) and (0 <= sz < bubble.shape[2]):
            bubble[sx:sx + 2, sy:sy + 2, sz:sz + 2] = C['crust_l']
    parts.append(('bubble', bubble, origin))

    #! (2) はじけた飛沫。泡より一回り広い輪＋少し上。**位相を進めて**後から顔を出す。
    pop, pop_origin = _lava_wheel_box(cz, radius + 6)
    pz = int(cz - pop_origin[2])
    for k in range(11):
        ang = ((k / 11.0) * 2.0 * math.pi) + float(rng.uniform(-0.2, 0.2))
        rr = radius + 1.5 + (float(rng.random()) * 3.0)
        sx = int(round(px + (rr * math.cos(ang))))
        sy = int(round(py + (rr * math.sin(ang))))
        sz = pz + int(round(radius * 0.5)) + int(rng.integers(0, 5))
        if (sx < 1) or (sy < 1) or (sx >= V - 1) or (sy >= V - 1):
            continue
        if (sz < 0) or (sz + 2 > pop.shape[2]):
            continue
        pop[sx:sx + 2, sy:sy + 2, sz:sz + 2] = C['bub_l'] if (k % 3) else C['bub']
    parts.append(('pop', pop, pop_origin))

    #! (3) 漂うガス。**低く保つ**（0.44 マスまで）。高くすると溶岩が焚き火に見える。
    #! 芯は少しずつ流し、**上ほど太く淡く**（湧いて広がる煙の形）。真下は細く。
    for tag, gx0, gy0, tall in (('gas_a', px, py, 14),
                                ('gas_b', (px + 13) % 20 + 6, (py + 9) % 20 + 6, 9)):
        gas = np.zeros((V, V, tall), np.uint8)
        cx = float(gx0)
        cy = float(gy0)
        for z in range(1, tall):
            cx += float(rng.uniform(-0.9, 0.9))
            cy += float(rng.uniform(-0.9, 0.9))
            t = (z - 1) / float(tall - 2)
            rr = 1.0 + (1.9 * t)
            shade = C['gas_d'] if t < 0.28 else (C['gas'] if t < 0.66 else C['gas_y'])
            for x in range(max(0, int(cx - rr)), min(V, int(cx + rr) + 1)):
                for y in range(max(0, int(cy - rr)), min(V, int(cy + rr) + 1)):
                    if (((x - cx) ** 2) + ((y - cy) ** 2)) > (rr * rr):
                        continue
                    #! **上のほうは穴あきにする**（詰まった塊だと煙ではなく岩に見える）。
                    if (t > 0.45) and (rng.random() < 0.42):
                        continue
                    gas[x, y, z] = shade
        parts.append((tag, gas, (0, 0, 0)))
    return parts


def lava_bubble_parts(name):
    """溶岩の泡の動き。**泡と飛沫は同じ車輪**（支点も速さも同じ・位相だけずらす）。"""
    index = (int(name[-2:]) - 1) if name[-2:].isdigit() else 0
    px, py, axis, speed, phase, _r = LAVA_BUBBLES[index % len(LAVA_BUBBLES)]
    pivot = [float(px), float(py), float(LAVA_PIVOT_Z)]
    wheel = (lambda part, ph: {
        'name': part, 'voxels': part, 'grounded': False, 'pivot': list(pivot),
        'motion': {'kind': 'rotate', 'axis': axis, 'speed': speed, 'phase': ph},
        'wind_k': 0.0,
    })
    return [
        wheel('bubble', phase),
        wheel('pop', phase + LAVA_POP_LEAD),
        #! ガスは風。**係数は草より小さく**（0.55）——大きいと煙が寝てしまう。
        {'name': 'gas_a', 'voxels': 'gas_a', 'grounded': False,
         'motion': {'kind': 'wind'}, 'wind_k': 0.55},
        {'name': 'gas_b', 'voxels': 'gas_b', 'grounded': False,
         'motion': {'kind': 'wind'}, 'wind_k': 0.7},
    ]


def alpine(name):
    """高山植物（同じ指示の後半「岩山にはちらほらと高山植物が生えているように」）。

    **岩の天面へ載せる**ので、根元は土ではなく**割れ目に溜まった砂利**にする。
    高さは 0.2〜0.4 マス。**背は伸ばさない**——高山の植物が低いからでもあるが、絵の理屈は
    「ここで背を伸ばすと稜線が草で毛羽立って、岩山が丘に見える」ほうである。

    ======  ==========================================================
    01      クッション状の株（白い小花）。岩に張り付く高山植物の典型
    02      硬い葉の叢に黄色い花。株立ちで背がいちばん高い（0.4 マス）
    03      低い灌木（濃い緑に赤い実）。岩の割れ目から横へ這う
    ======  ==========================================================
    """
    kind = int(name[-2:]) if name[-2:].isdigit() else 1
    rng = rng_for(name)
    height = {1: 8, 2: 13, 3: 10}[kind]
    v = np.zeros((V, V, height), np.uint8)
    #! 根元の砂利。**マスいっぱいには敷かない**（岩の天面が見えていてこその「ちらほら」）。
    for _ in range(int(rng.integers(5, 9))):
        x = int(rng.integers(8, 22))
        y = int(rng.integers(8, 22))
        v[x:x + 3, y:y + 3, 0:1] = C['grit']

    if kind == 1:
        cx, cy = 15.5, 15.5
        for x in range(V):
            for y in range(V):
                d = math.hypot(x - cx, y - cy)
                if d > 8.5:
                    continue
                cap = int(round(5.0 * (1.0 - ((d / 8.5) ** 2))))
                if cap <= 0:
                    continue
                v[x, y, 0:cap] = C['alp'] if ((x + y) % 3) else C['alp_d']
        for _ in range(14):
            x = int(rng.integers(9, 23))
            y = int(rng.integers(9, 23))
            z = int(np.max(np.nonzero(np.append(v[x, y, :], 1))[0]))
            if (z > 0) and (z < height - 1):
                v[x, y, z] = C['alp_fw']
    elif kind == 2:
        for _ in range(int(rng.integers(7, 12))):
            bx = int(rng.integers(9, 23))
            by = int(rng.integers(9, 23))
            tall = int(rng.integers(6, height - 1))
            lean_x = int(rng.integers(-2, 3))
            lean_y = int(rng.integers(-2, 3))
            blade = C['alp'] if rng.random() < 0.6 else C['alp_d']
            for z in range(tall):
                t = z / float(max(1, tall))
                x = min(V - 1, max(0, bx + int(round(lean_x * t))))
                y = min(V - 1, max(0, by + int(round(lean_y * t))))
                v[x, y, z] = blade
            if rng.random() < 0.45:
                x = min(V - 1, max(0, bx + lean_x))
                y = min(V - 1, max(0, by + lean_y))
                v[x, y, tall:min(height, tall + 2)] = C['alp_fy']
    else:
        for _ in range(int(rng.integers(4, 7))):
            bx = int(rng.integers(10, 22))
            by = int(rng.integers(10, 22))
            v[bx:bx + 2, by:by + 2, 0:5] = C['alp_d']
            for _ in range(6):
                x = min(V - 2, max(0, bx + int(rng.integers(-4, 5))))
                y = min(V - 2, max(0, by + int(rng.integers(-4, 5))))
                z = int(rng.integers(3, height - 2))
                v[x:x + 2, y:y + 2, z:z + 2] = C['alp_l'] if rng.random() < 0.7 else C['alp']
        for _ in range(6):
            x = int(rng.integers(9, 23))
            y = int(rng.integers(9, 23))
            z = int(rng.integers(4, height - 1))
            if v[x, y, z] != 0:
                v[x, y, z] = C['alp_fr']
    return [('main', v, (0, 0, 0))]


def susuki(name):
    """**ススキ**（2026-08-09 に決めた:「テルモラの道以外の平地には背の高めの
    ススキのような草が風の波に揺らされている感じに」）。

    町の草地の `grass`（0.69 マス）と差し替わる。**穂を付ける**のが読みの決め手で、
    ただ背を伸ばしただけだと「伸びた雑草」にしかならない。穂は葉より明るく灰がかった色。

    高さは **1.28 マス**（41 ボクセル）。これ以上伸ばすと、見下ろすカメラで前庭や街路の
    小物を隠してしまう（草は「地面の質感」であって主役ではない）。
    """
    rng = rng_for(name)
    height = 41
    v = np.zeros((V, V, height), np.uint8)
    for _ in range(int(rng.integers(9, 15))):
        bx = int(rng.integers(3, V - 3))
        by = int(rng.integers(3, V - 3))
        tall = int(rng.integers(int(height * 0.55), height - 3))
        #! 茎は**根元から穂先へ 1 ボクセルずつ寄せる**（まっすぐだと針山に見える）。
        lean_x = int(rng.integers(-3, 4))
        lean_y = int(rng.integers(-3, 4))
        blade = C['stalk'] if rng.random() < 0.6 else C['stalk_d']
        for z in range(tall):
            t = z / float(max(1, tall))
            x = min(V - 1, max(0, bx + int(round(lean_x * t))))
            y = min(V - 1, max(0, by + int(round(lean_y * t))))
            v[x, y, z] = blade
        #! 穂（10 本に 6 本くらい）。**茎の先に 5〜7 ボクセル**の房を付ける。
        if rng.random() < 0.6:
            x = min(V - 1, max(0, bx + lean_x))
            y = min(V - 1, max(0, by + lean_y))
            shade = C['plume'] if rng.random() < 0.6 else C['plume_d']
            for z in range(tall, min(height, tall + int(rng.integers(5, 8)))):
                v[x, y, z] = shade
                if (z % 2) == 0:
                    for ox, oy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        xx, yy = min(V - 1, max(0, x + ox)), min(V - 1, max(0, y + oy))
                        v[xx, yy, z] = shade
    return [('main', v, (0, 0, 0))]


# ---------------------------------------------- 城と塔（P10 第 2 期レビュー 6）
#
# 2026-08-09 に決めた:
#   「テルモラの城は**石組みで巨大な城**を組んで。入り口は**一つの大きな門**で組もう」
#   「城の入り口だけは看板を取りやめて**城門**に」
#   「賢者の塔とトランプの塔を、**敷地の中に高い石組みの塔**で」
#   高さは指定した値で **天守 6 マス・城壁 3 マス**。
#
# 骨組みは家と同じ（敷地 → 建物の矩形 ＋ 前庭 ＋ 門）。**材と高さだけ**を差し替える。
#   建物の矩形 → `castle_keep_*`（9 スライス。6 マス）
#   前庭の外を向いた辺 → `castle_wall_*`（1 枚 1 辺。3 マス）
#   門 → 並びの両端に `gate_pier`、間に `gate_lintel`

CASTLE_KEEP_H = 192   #!< 6 マス
CASTLE_WALL_H = 96    #!< 3 マス
GATE_PIER_H = 128     #!< 4 マス。城壁より頭ひとつ高い


def _stone_courses(v, x0, x1, y0, y1, z0, z1, course, body, light, dark, joint, rng, faces):
    """外皮に石を貼って目地を彫る（`masonry` と同じ流儀）。`faces` は 'n','s','w','e' の並び。"""
    for side in faces:
        if side == 'n':
            fx, fy = slice(x0, x1), slice(y0, y0 + 1)
            bx, by = fx, slice(y0 + 1, y0 + 2)
            lo, hi, horiz = x0, x1, True
        elif side == 's':
            fx, fy = slice(x0, x1), slice(y1 - 1, y1)
            bx, by = fx, slice(y1 - 2, y1 - 1)
            lo, hi, horiz = x0, x1, True
        elif side == 'w':
            fx, fy = slice(x0, x0 + 1), slice(y0, y1)
            bx, by = slice(x0 + 1, x0 + 2), fy
            lo, hi, horiz = y0, y1, False
        else:
            fx, fy = slice(x1 - 1, x1), slice(y0, y1)
            bx, by = slice(x1 - 2, x1 - 1), fy
            lo, hi, horiz = y0, y1, False
        for z in range(z0 + course - 1, z1, course):
            zz0 = max(z0, z - course + 1)
            off = ((z // course) % 2) * 5
            #! 石ごとの明暗（塊単位＝罠 38）。
            for p in range(lo, hi, 10):
                shade = rng.choice([body, light, dark], p=[0.52, 0.26, 0.22])
                if horiz:
                    v[p:p + 10, fy, zz0:z] = shade
                else:
                    v[fx, p:p + 10, zz0:z] = shade
            #! 段の目地と縦の継ぎ目は**彫る**（面を 0 にし、底を目地の色に）＝罠 44。
            v[fx, fy, z] = 0
            v[bx, by, z] = joint
            for p in range(lo + off, hi, 10):
                if horiz:
                    v[p:p + 1, fy, zz0:z] = 0
                    v[p:p + 1, by, zz0:z] = joint
                else:
                    v[fx, p:p + 1, zz0:z] = 0
                    v[bx, p:p + 1, zz0:z] = joint


def castle_keep(name):
    """**天守の 1 スライス**（6 マス）。外に面した辺に狭間、天面は歩廊。

    家の 9 スライスと同じ枠なので、`town_plan` が決めた建物の矩形へそのまま並ぶ。
    屋根を載せない（城は屋上が歩廊）ので、**壁 1 枚で 6 マス**ぶんを持つ。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    top = CASTLE_KEEP_H
    v = np.zeros((V, V, top), np.uint8)
    v[:, :, :] = C['ash']
    v[:, :, 0:5] = C['ash_d']        # 根石

    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    _stone_courses(v, 0, V, 0, V, 5, top - 10, 8, C['ash'], C['ash_l'], C['ash_d'], C['joint'],
                   rng, faces)
    for side in faces:               # 胴蛇腹（上端の帯）
        if side in ('n', 's'):
            fy = slice(0, 1) if side == 'n' else slice(V - 1, V)
            v[:, fy, top - 10:top - 8] = C['ash_l']
        else:
            fx = slice(0, 1) if side == 'w' else slice(V - 1, V)
            v[fx, :, top - 10:top - 8] = C['ash_l']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['flag'], C['flag_d'], C['flag_l'], C['moss_d']], [0.42, 0.28, 0.22, 0.08])
    v[:, :, top - 1] = layer         # 屋上の歩廊
    #! 狭間は**外に面した辺だけ**（マスごとに四方へ載せると格子に見える＝罠 71）。
    for side in faces:
        for p in range(0, V, 8):
            if side in ('n', 's'):
                y0 = 0 if side == 'n' else V - 4
                v[p:p + 5, y0:y0 + 4, top - 8:top] = C['ash']
                v[p:p + 5, y0:y0 + 4, top - 1] = C['ash_l']
            else:
                x0 = 0 if side == 'w' else V - 4
                v[x0:x0 + 4, p:p + 5, top - 8:top] = C['ash']
                v[x0:x0 + 4, p:p + 5, top - 1] = C['ash_l']
    #! 矢狭間（南面だけ。見下ろすカメラの正面）。
    if south:
        for wz in (52, 108):
            for wx in (8, 20):
                v[wx:wx + 3, V - 2:V, wz:wz + 14] = C['dark']
    return [('main', v, (0, 0, 0))]


def castle_wall(name):
    """**城壁の 1 辺**（3 マス）。前庭の外を向いた辺へ、柵の代わりに立てる。

    柵（`fence_*`）と同じ「1 枚 1 辺」なので、置く側は同じビットを見るだけでよい。
    """
    side = _slice_of(name)
    rng = rng_for(name)
    th = 8              # 厚み。歩廊が乗る幅
    top = CASTLE_WALL_H
    v = np.zeros((V, V, top), np.uint8)
    lo, hi = _fence_sides(side, th)
    if side in ('n', 's'):
        v[:, lo:hi, :] = C['ash']
        _stone_courses(v, 0, V, lo, hi, 4, top - 12, 8, C['ash'], C['ash_l'], C['ash_d'],
                       C['joint'], rng, ['n', 's'])
        v[:, lo:hi, top - 1] = C['flag']
        for p in range(0, V, 8):     # 狭間
            v[p:p + 5, lo:hi, top - 12:top] = C['ash']
            v[p:p + 5, lo:hi, top - 1] = C['ash_l']
    else:
        v[lo:hi, :, :] = C['ash']
        _stone_courses(v, lo, hi, 0, V, 4, top - 12, 8, C['ash'], C['ash_l'], C['ash_d'],
                       C['joint'], rng, ['w', 'e'])
        v[lo:hi, :, top - 1] = C['flag']
        for p in range(0, V, 8):
            v[lo:hi, p:p + 5, top - 12:top] = C['ash']
            v[lo:hi, p:p + 5, top - 1] = C['ash_l']
    v[:, :, 0:4][v[:, :, 0:4] != 0] = C['ash_d']   # 根石
    return [('main', v, (0, 0, 0))]


def gate_pier(name):
    """**城門の脇柱**（4 マス）。門の並びの**両端**に立てる。

    門をマスごとに 1 基ずつ立てると入口の数だけアーチが並ぶ（レビュー 6 の指摘）。
    「一つの大きな門」は**両端の塔と、その間の梁**で作る。
    """
    rng = rng_for(name)
    top = GATE_PIER_H
    v = np.zeros((V, V, top), np.uint8)
    v[:, :, :] = C['ash']
    v[:, :, 0:5] = C['ash_d']
    _stone_courses(v, 0, V, 0, V, 5, top - 14, 8, C['ash'], C['ash_l'], C['ash_d'], C['joint'],
                   rng, ['n', 's', 'w', 'e'])
    #! 上は狭間つきの物見。**四方に載せてよい**（塔は門の両端の 2 基だけなので格子にならない）。
    v[:, :, top - 14:top] = C['ash_d']
    for p in range(0, V, 8):
        v[p:p + 5, 0:4, top - 14:top] = C['ash']
        v[p:p + 5, V - 4:V, top - 14:top] = C['ash']
        v[0:4, p:p + 5, top - 14:top] = C['ash']
        v[V - 4:V, p:p + 5, top - 14:top] = C['ash']
    v[4:V - 4, 4:V - 4, top - 14:top - 12] = C['flag']   # 物見の床
    return [('main', v, (0, 0, 0))]


def gate_lintel(name):
    """**城門の梁**（門の並びの内側のマス）。くぐれるよう**下を空ける**。

    基は「南北にくぐる」形（梁が東西に張る）。東西にくぐる所は `rotated()` で回す。
    """
    rng = rng_for(name)
    top = GATE_PIER_H
    v = np.zeros((V, V, top), np.uint8)
    beam0 = 64          #!< 梁の下端は 2.0 マス。人も馬も抜けられる高さに見せる
    v[:, 6:V - 6, beam0:top - 14] = C['ash']
    _stone_courses(v, 0, V, 6, V - 6, beam0, top - 14, 8, C['ash'], C['ash_l'], C['ash_d'],
                   C['joint'], rng, ['n', 's'])
    for k in range(6):  # アーチの起こし（梁の下を丸く落とす）
        v[k, 6:V - 6, beam0:beam0 + 6 - k] = 0
        v[V - 1 - k, 6:V - 6, beam0:beam0 + 6 - k] = 0
    #! 上は狭間つきの歩廊（両端の塔と繋がって見える）。
    v[:, 6:V - 6, top - 14:top] = C['ash_d']
    for p in range(0, V, 8):
        v[p:p + 5, 6:10, top - 14:top] = C['ash']
        v[p:p + 5, V - 10:V - 6, top - 14:top] = C['ash']
    v[:, 10:V - 10, top - 14:top - 12] = C['flag']
    return [('main', v, (0, 0, 0))]


TOWER_SPAN = 2                 #!< 塔は 2×2 マス
TOWER_V = V * TOWER_SPAN
TOWER_H = 160                  #!< 5 マス。家（3.1 マス）と城の天守（6 マス）の間


def tower_wizard(name):
    """**高い石組みの塔**（2026-08-09 に決めた「賢者の塔とトランプの塔」）。

    2×2 マス・5 マス。円塔にして上に狭間と円錐の屋根を載せる——町の中で
    **家並みから頭ひとつ抜ける**ことがこの素材の役目なので、高さと丸さで区別を付ける。
    """
    rng = rng_for(name)
    v = np.zeros((TOWER_V, TOWER_V, TOWER_H), np.uint8)
    cx = cy = (TOWER_V - 1) / 2.0
    body = TOWER_H - 34
    r = 26.0
    for x in range(TOWER_V):
        for y in range(TOWER_V):
            d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
            if d2 <= ((r + 3.0) ** 2):
                v[x, y, 0:8] = C['ash_d']          # 基壇
            if d2 <= (r * r):
                v[x, y, 8:body] = C['ash']
    #! 段の目地（外周だけ）。中は greedy が消すので触らない。
    for z in range(15, body, 8):
        for x in range(TOWER_V):
            for y in range(TOWER_V):
                d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
                if (v[x, y, z] != 0) and (d2 > ((r - 1.4) ** 2)):
                    v[x, y, z] = C['joint']
                    v[x, y, max(8, z - 7):z] = rng.choice([C['ash'], C['ash_l'], C['ash_d']],
                                                          p=[0.5, 0.27, 0.23])
    #! 狭間（円周を 8 つに割って 1 つおき）。
    for x in range(TOWER_V):
        for y in range(TOWER_V):
            d2 = ((x - cx) ** 2) + ((y - cy) ** 2)
            if (d2 > ((r + 2.0) ** 2)) or (d2 < ((r - 4.0) ** 2)):
                continue
            ang = math.atan2(y - cy, x - cx)
            if int((ang + math.pi) / (math.pi / 4)) % 2 == 0:
                v[x, y, body:body + 14] = C['ash']
                v[x, y, body + 13] = C['ash_l']
    #! 円錐の屋根（瓦。街の屋根と揃える）。
    cone0 = body + 14
    for z in range(cone0, TOWER_H):
        t = (z - cone0) / float(TOWER_H - cone0)
        rr = (r - 2.0) * (1.0 - t)
        for x in range(TOWER_V):
            for y in range(TOWER_V):
                if (((x - cx) ** 2) + ((y - cy) ** 2)) <= (rr * rr):
                    v[x, y, z] = C['tile_d'] if ((z // 3) % 2) else C['tile']
    #! 窓（南面。塔の中ほどに 3 つ）。
    for wz in (40, 78, 116):
        v[int(cx) - 2:int(cx) + 2, TOWER_V - int(r) - 2:TOWER_V - int(r) + 1, wz:wz + 12] = C['dark']
    return [('main', v, (0, 0, 0))]


# -------------------------------------------------- 看板（2 マス幅・店の中身を絵で言う）
#
# 2026-08-09 に決めた:「建物の横に揺れる看板は 2 タイルの幅で大きくし、
# 建物の内容がわかる絵を組もう。宿屋であればベッド、武器屋であれば剣、防具屋は盾」。
#
# 絵は 16×14 の文字絵を 2 倍に引き伸ばして板の**南面**へ彫る。文字絵にしてあるのは、
# 増やすときに人が読める形で足せるようにするため（座標の羅列だと直せない）。
#! **1 マス幅**（2026-08-09 に決めた「少し大きすぎたので 1 マスサイズに縮小してみてくれ」）。
#! 絵は 16×14 を 2 倍（32×28）で、**マスの幅いっぱい**に置く。柱は板より**奥**（y の小さい側）
#! へ寄せて、板の下から脚が、上から桁が覗く形にする——画像の姿勢を 1 マスで保つための組み方。
SIGN_W = V           # 1 マス
SIGN_H = 54          # 1.69 マス（2 マス版は 2.4 マスだった）
#! 板は**マスの 2/3**（2026-08-09 に決めた「看板を 2/3 のサイズにして足に被らないように」）。
#! 右足（x 24..30）に掛からないよう左へ寄せる。絵は等倍（16×14）で余白 2〜3 ボクセル。
SIGN_BOARD_X = (1, 22)
SIGN_BOARD_Z = (23, 44)
ICON_SCALE = 1

