# ---- 幻想蛮怒の店の看板（2026-08-17。こう決めた——「店の看板は変愚のものではなく幻想独自で。
#      店の種類により漢字 1 文字で作ってみよう。武器屋：武 のように」）----
#
# **名前は「基の看板名 ＋ _gb」**にしてある。町の意匠の接尾辞と同じ流儀なので、引く側を
# styled() に変えれば**表を書き換えずに**幻想蛮怒だけ差し替わる（変愚は基の名前へ落ちる）。
#
# 字は MS ゴシック 16px を焼いてドット絵へ落とし、**ソースに焼き込んだ**（再現性のため。
# 字体が入れ替わっても絵が変わらない）。手で直してよい。
#
# **画数が命である。**既存のアイコンは 2 ボクセル厚の 16x14 だが、漢字は 1 ボクセル厚で細い。
