def signboard(name):
    """1 マス幅の吊り看板。`frame`（柱と腕木・静止）＋ `board`（吊った板・振り子）。

    **足は片足で、右（＝東）だけ**（2026-08-09 に決めた:「看板は片足にして右側にだけ
    足をつけて、上の梁からつるされているように」）。柱の頭から腕木が左へ張り出し、
    そこから板を 2 本の金具で吊る——酒場の看板の作り。

    **板は必ず南を向く**（同 2026-08-09:「建物の看板は常に南向に」）。姿勢の対は要らない。
    柱と腕木は板より**奥**（y の小さい側）に置くので、南から見ると板の下に足が、
    上に腕木が覗く。
    """
    icon_key = name[len('sign_'):]
    colours, rows = ICONS[icon_key]
    frame = np.zeros((SIGN_W, V, SIGN_H), np.uint8)
    board = np.zeros((SIGN_W, V, SIGN_H), np.uint8)

    beam_z = SIGN_H - 8
    # 柱（右＝東の 1 本だけ。沓石つき）。
    frame[24:30, 11:17, 0:SIGN_H] = C['timber']
    frame[25:29, 12:16, 0:SIGN_H] = C['timber_d']
    frame[23:31, 10:18, 0:3] = C['log_d']
    # 腕木（柱の頭から左へ張り出す）。
    frame[0:30, 10:18, beam_z:beam_z + 6] = C['timber']
    frame[0:30, 11:17, beam_z + 4:beam_z + 6] = C['timber_l']
    # 方杖（柱と腕木を支える斜材）。無いと腕木が宙に浮いて見える。
    for k in range(4):
        frame[24 - (k * 2) - 2:24 - (k * 2), 12:16, beam_z - (k * 2) - 2:beam_z - (k * 2)] = C['timber_d']

    # 板（縁を立てた枠＋中の平面）。**柱より手前**（y の大きい側）・**足には掛からない**。
    x0, x1 = SIGN_BOARD_X
    z0, z1 = SIGN_BOARD_Z
    board[x0:x1, 17:21, z0:z1] = C['board_l']
    board[x0 + 1:x1 - 1, 18:20, z0 + 1:z1 - 1] = C['board']

    # 絵（板の南面と北面へ 2 ボクセルの厚みで置く）。16×14 の文字絵を等倍で中央へ。
    #
    # **裏面にも描く**（2026-08-11 に決めた:「FPS モードにした際に分かったのだが、
    # 看板は裏面もアイコンを描画して」）。見下ろしの絵では板を南からしか見なかったので
    # 気づかなかったが、一人称では裏へ回れてしまい、無地の板が見えていた。
    #
    # **裏面は左右を反転させる。**世界は x = 東・y = 南で、南から見ると東は画面の右、
    # 北から見ると東は画面の**左**になる。同じ並びで置くと、裏から見た絵が鏡像になる
    # （両面に同じ絵を描いた実物の看板は、どちらの面からも正しく読める）。
    ox = x0 + ((x1 - x0) - (len(rows[0]) * ICON_SCALE)) // 2
    oz = z0 + ((z1 - z0) - (len(rows) * ICON_SCALE)) // 2
    for r, line in enumerate(rows):
        for c, ch in enumerate(line):
            if ch == '.':
                continue
            colour = C[colours[ch]]
            z = oz + ((len(rows) - 1 - r) * ICON_SCALE)
            # 南面（板の +y 側の 2 ボクセル）。
            board[ox + (c * ICON_SCALE):ox + (c * ICON_SCALE) + ICON_SCALE, 19:21, z:z + ICON_SCALE] = colour
            # 北面（板の -y 側の 2 ボクセル）。列を反転して置く。
            back_c = len(line) - 1 - c
            board[ox + (back_c * ICON_SCALE):ox + (back_c * ICON_SCALE) + ICON_SCALE, 17:19, z:z + ICON_SCALE] = colour
    # 吊り金具（腕木から板へ）。**絵より後**に置く（金具は絵の手前に見える）。
    for hook in (x0 + 4, x1 - 7):
        board[hook:hook + 3, 18:20, z1:beam_z + 2] = C['iron']
    return [('frame', frame, (0, 0, 0)), ('board', board, (0, 0, 0))]


def sign_parts():
    """吊り板は振り子。**揺れ幅は `sign.jsonc`（確認済み）と同じ値**に揃える。

    @note 姿勢の対（`_ew`）は**要らない**。2026-08-09 に決めたので
    「建物の看板は常に南向に」と決まったので、置く側はマスをずらすだけでよい。
    """
    return [
        {'name': 'frame', 'voxels': 'frame', 'grounded': True,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
        {'name': 'board', 'voxels': 'board', 'parent': 'frame', 'grounded': False,
         'pivot': [float(sum(SIGN_BOARD_X)) * 0.5, 19.0, float(SIGN_H - 8)],
         'motion': {'kind': 'pendulum', 'axis': 'x', 'amplitude': 11.0,
                    'period': 2.3, 'phase': 0.0, 'damping': 0.0},
         'wind_k': 0.0},
    ]



# ---------------------------------------- 永遠亭の意匠（デザイン8・2026-08-19）
#
# §4.3 の「外せない 1 点」＝**垂直要素が皆無。屋根が高さの半分以上を占め、
# 白い障子の横帯と竹の縦線が交差する。**——だから作るものは 3 つに絞れる:
#
#   1. **低い壁**（1.5 マス）と、その軒下を走る**白い障子の帯**
#   2. **大きな入母屋の屋根**（1 段 14 vox。3 段で壁より高くなる）
#   3. **竹**（4.1〜7.0 マス。屋根より高い縦線）
#
# 屋根材は**檜皮葺き**にした。「大昔の日本の屋敷の造りなのに少しも古びていない」
# （求聞史紀）＝平安の貴族の屋敷の格で、蓬莱山輝夜は竹取物語の姫である。
# §4.3 の表は「茅 `#6B5A44` か瓦 `#5A6068`」と書いたが、**茅は人里・瓦は旧地獄街道**が
# 既に使っている——3 つめの町に同じ材を配ると町の描き分けが 1 つ減る。
# 色は天狗の里の杉皮（`hiwada`＝`sugi` 72,58,46）を借りる（§4.3 の茅の色に近い）。
EIN_WALL_H = 48   #!< 屋敷の壁の高さ（1.5 マス）。**低く**（§4.3 ①「垂直要素をゼロに」）
EIN_RISE = 14     #!< 屋根 1 段の上がり。3 段＝1.31 マスで壁（1.5）とほぼ同じ高さになる
EIN_BAMBOO_H = (132, 152, 172, 192, 208, 224)  #!< 竹の高さ（4.1〜7.0 マス）


def manor_wall_ein(name):
    """**永遠亭の壁 1 マス**（石の基壇＋濡縁＋腰板＋**白い障子の帯**・高さ 1.5 マス）。

    §4.3 ①「垂直要素をゼロにする——横長・低平の大屋根 1 枚が全部」に従って、
    博麗の拝殿（2.25 マス）よりさらに**低く**作る。屋根が高さの半分以上を占めるのは
    ここが低いからで、屋根を高くして得るものではない。

    変種は**間（ベイ）の律動**で選ばれる（置く側が 4 マス周期で `_01 _02 _01 _03`）。
    どれも上帯は白いままにする——「窓を四角い点でなく**白い横帯**にすると洋館と
    一瞬で分かれる」（§4.3 ③）ので、帯を切ってはならない:

      - `_01` 障子（白一色に細い桟）……主
      - `_02` 腰付障子（下 6 vox が板）……変化
      - `_03` 舞良戸（横桟の板戸。雨戸を閉てた間）……差し色

    縁側の濡縁は外に面した辺の**外へ 8 vox** 張り出す（型 48×48・origin (-8,-8)。
    張り出しは z≥10 だけ——接地がマスの外に出ると footprint 照合で落ちる＝時計塔の罠）。
    """
    base = _split_style(name)[1]  # manor_wall_<slice>_<nn>
    parts = base.split('_')
    key = parts[2]
    variant = int(parts[3]) if ((len(parts) > 3) and parts[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    W = V + 16
    v = np.zeros((W, W, EIN_WALL_H), np.uint8)
    c0, c1 = 8, 8 + V  # マスの中身（local 8..40）
    #! 基壇（切石。マスいっぱい＝罠 5）。
    v[c0:c1, c0:c1, 0:6] = C['wall_d']
    v[c0:c1, c0:c1, 5] = C['wall']
    #! 躯体は**暗い板**で詰める（「内部は最低限の採光しかせず薄暗く」＝求聞史紀。
    #! 切れ目から覗く色が明るいと、屋敷の中が広間に見える）。
    v[c0:c1, c0:c1, 6:EIN_WALL_H] = C['timber_d']

    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        if side == 'n':
            fx, fy, vert = slice(c0, c1), c0, False
        elif side == 's':
            fx, fy, vert = slice(c0, c1), c1 - 1, False
        elif side == 'w':
            fx, fy, vert = c0, slice(c0, c1), True
        else:
            fx, fy, vert = c1 - 1, slice(c0, c1), True
        #! 面の割り。**横の線を通す**のが和風の要（縦の線は柱 2 本だけ）。
        v[fx, fy, 6:10] = C['beam']            # 地覆（床下の見切り）
        #! 腰板（竪羽目。4 vox ごとに 1 枚。板の継ぎ目だけ暗く）。
        v[fx, fy, 10:19] = C['board']
        span = fx if not vert else fy
        lo, hi = span.start, span.stop
        for p in range(lo, hi, 4):
            if vert:
                v[fx, p:p + 1, 10:19] = C['board_d']
            else:
                v[p:p + 1, fy, 10:19] = C['board_d']
        v[fx, fy, 19:23] = C['beam_l']         # 敷居（腰長押）
        #! 上帯（23..40）＝**白い障子の帯**。
        v[fx, fy, 23:40] = C['shoji']
        #! **白い帯（28..40）はどの変種でも切らない。**初版は変種ごとに帯の高さを変えて
        #! いて、合成フレームで「白い横帯」ではなく**四角い窓の点線**に見えた（§4.3 ③の
        #! 外せない 1 点はここで、洋館 3 件との差がこの帯だけで付く）。振るのは腰（23..28）。
        if variant == 2:
            v[fx, fy, 23:28] = C['board']      # 腰付障子（下は板）
            v[fx, fy, 27:28] = C['beam']
        elif variant == 3:
            #! 舞良戸（横桟の板戸）を腰にだけ。
            v[fx, fy, 23:28] = C['board_l']
            for z in range(23, 28, 2):
                v[fx, fy, z:z + 1] = C['board_d']
        #! 障子の桟（**粗く**。8 vox ピッチ。細かくすると遠目で灰色に潰れる＝デザイン6 その3）。
        for p in range(lo + 3, hi, 8):
            if vert:
                v[fx, p:p + 2, 28:40] = C['beam']
            else:
                v[p:p + 2, fy, 28:40] = C['beam']
        v[fx, fy, 33:34] = C['beam']           # 中桟（横 1 本）
        v[fx, fy, 40:44] = C['beam_l']         # 上長押（§4.3 ⑥「濃茶の水平線を 1 本」）
        v[fx, fy, 44:EIN_WALL_H] = C['timber_d']  # 軒下（垂木の影）
        #! 柱（濃茶。**面の両端だけ**——タイルするとマス境に 1 本になる）。
        for p in (lo, hi - 3):
            if vert:
                v[fx, p:p + 3, 6:EIN_WALL_H] = C['beam_l']
            else:
                v[p:p + 3, fy, 6:EIN_WALL_H] = C['beam_l']
        #! 濡縁（外へ 8 vox。z 10..15 だけ＝接地しない張り出し）。
        if side == 'n':
            dx, dy = slice(c0 - 2, c1 + 2), slice(0, c0 + 2)
        elif side == 's':
            dx, dy = slice(c0 - 2, c1 + 2), slice(c1 - 2, W)
        elif side == 'w':
            dx, dy = slice(0, c0 + 2), slice(c0 - 2, c1 + 2)
        else:
            dx, dy = slice(c1 - 2, W), slice(c0 - 2, c1 + 2)
        v[dx, dy, 10:15] = C['oak_l']
        #! 板目（縁と平行の筋）と、床下の束（**マスの中**の面の際。接地はマスの内側だけ）。
        if vert:
            for p in range(dy.start + 1, dy.stop, 5):
                v[dx, p, 14] = C['board_d']
        else:
            for p in range(dx.start + 1, dx.stop, 5):
                v[p, dy, 14] = C['board_d']
        for p in range(lo + 4, hi - 3, 10):
            if vert:
                v[fx, p:p + 3, 1:10] = C['timber_d']
            else:
                v[p:p + 3, fy, 1:10] = C['timber_d']
    #! 苔（基壇の際にだけ。「少しも古びていない」ので**壁には回さない**）。
    for _ in range(int(rng.integers(1, 4))):
        p = int(rng.integers(c0, c1 - 5))
        if rng.random() < 0.5:
            v[p:p + 5, c0:c0 + 1, 0:2] = C['moss_d']
        else:
            v[c0:c0 + 1, p:p + 5, 0:2] = C['moss_d']
    return [('main', v, (-8, -8, 0))]


def manor_roofslope_ein(name):
    """**檜皮葺きの斜面 1 マス**。`_n` = 軒が北（南へ上がる）… 4 姿勢。

    1 マスで **EIN_RISE（14 vox）**上がる。置く側（terrain_view の入母屋モード）が
    「マスごとの距離 × top_z」で積むので、**型の総高＝EIN_RISE がそのまま勾配**になる。
    `manor_roofeave_*` は軒のマス（段 0）用で、軒側へ **10 vox の深い軒**が出る
    （§4.3 ②「屋根が板の高さの半分以上」は軒の深さでも確保できる）。

    檜皮は**流れに直交する細い段**で葺く（4 vox ごとに 1 枚）。波トタン（河童）が
    流れに沿う畝だったのと**逆向き**で、そこが材の見分けになる。
    """
    base = _split_style(name)[1]  # manor_roofslope_<n|s|w|e>[_<nn>]
    parts = base.split('_')
    side = parts[2]
    eave = 'roofeave' in base
    rng = rng_for(name)
    ext = 10 if eave else 0
    along_x = side in ('w', 'e')
    if along_x:
        v = np.zeros((V + ext, V, EIN_RISE + 1), np.uint8)
    else:
        v = np.zeros((V, V + ext, EIN_RISE + 1), np.uint8)
    low_first = side in ('n', 'w')  # 軒が型の手前側（origin を負へずらす）
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            a = x if along_x else y
            aa = a - ext if low_first else a
            if (aa < 0) or (aa >= V):
                #! 軒先。**z=0 に置かない**（マスの外に張り出すので、接地すると
                #! footprint 照合が floor 除算の食い違いで落ちる＝時計塔の罠）。
                v[x, y, 1:4] = C['hiwada']
                v[x, y, 3] = C['hiwada_l']
                continue
            t = aa if low_first else (V - 1 - aa)
            surf = 2 + ((t * (EIN_RISE - 2)) // (V - 1))
            v[x, y, 0:surf] = C['hiwada_d']
            #! 檜皮の重ね（4 vox ごとの段）。**天面は明るい側で塗る**——初版は
            #! `hiwada_d`（58,52,48）を地にしていて、合成フレームで**青灰の板**に見えた。
            #! 檜皮は赤みのある茶なので、明るい 2 色（98,82,64 と 112,78,50）を交互に置き、
            #! 1 枚ごとの見切りだけを暗い線にする。
            v[x, y, surf - 1] = C['hiwada_l'] if ((t // 4) % 2 == 0) else C['hiwada_r']
            if (t % 4) == 0:
                v[x, y, surf - 1] = C['hiwada']  # 1 枚ごとの見切り（影の線）
    #! 苔（天面に塊で少しだけ。「少しも古びていない」ので**控えめに**）。
    for _ in range(int(rng.integers(0, 3))):
        cx = int(rng.integers(0, max(1, v.shape[0] - 5)))
        cy = int(rng.integers(0, max(1, v.shape[1] - 5)))
        for x in range(cx, min(cx + int(rng.integers(3, 7)), v.shape[0])):
            for y in range(cy, min(cy + int(rng.integers(3, 7)), v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['hiwada_g']
                        break
    if along_x:
        origin = (-ext if low_first else 0, 0, 0)
    else:
        origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_rooftop_ein(name):
    """**平らな大棟 1 マス**（入母屋の段が上限に達したマス）。

    距離変換で組む屋根は「平面の厚い所ほど高い」ので、棟と棟が出会う所（永遠亭では
    北棟と渡り廊下の交わり）で段が際限なく伸びる。上限（`TownStyle::manor_roof_max`）で
    頭打ちにすると翼ごとの棟の高さが揃うが、**そこへ斜面の型を並べると鋸歯になる**
    ——1 マスで 1 段上がる型だからである。だからこの平らな型で受ける。

    総高は `EIN_RISE`（斜面の型と同じ）。隣の斜面の高いほうの端とちょうど揃う。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, EIN_RISE), np.uint8)
    v[:, :, 0:EIN_RISE] = C['hiwada_d']
    #! 天面の檜皮（4 vox ごとの段。斜面と同じ割り付けにして、境で層が続いて見えるように）。
    for y in range(V):
        v[:, y, EIN_RISE - 1] = C['hiwada_l'] if ((y // 4) % 2 == 0) else C['hiwada_r']
        if (y % 4) == 0:
            v[:, y, EIN_RISE - 1] = C['hiwada']
    #! 苔（控えめに）。
    for _ in range(int(rng.integers(0, 3))):
        cx = int(rng.integers(0, V - 5))
        cy = int(rng.integers(0, V - 5))
        v[cx:cx + int(rng.integers(3, 7)), cy:cy + int(rng.integers(3, 7)), EIN_RISE - 1]             = C['hiwada_g']
    return [('main', v, (0, 0, 0))]


def manor_ridge_ein(name):
    """**檜皮の箱棟**。`manor_ridge_ein` は東西へ通る棟・`manor_ridge_ns_ein` は南北。

    入母屋は平面の形で棟の向きが変わる（長い棟には東西、渡り廊下には南北）ので、
    切妻（博麗＝東西だけ）と違って**2 本要る**。断面は蒲鉾形の箱棟で、
    上に熨斗のような段を 2 つ重ねる。**千木も鰹木も載せない**（社殿ではなく屋敷である）。
    """
    ns = _split_style(name)[1].endswith('_ns')
    long_, thick, h = V, 12, 13
    v = np.zeros((thick, long_, h) if ns else (long_, thick, h), np.uint8)

    def put(a0, a1, z0, z1, colour):
        if ns:
            v[a0:a1, :, z0:z1] = colour
        else:
            v[:, a0:a1, z0:z1] = colour

    for a in range(thick):
        half = abs(a - 5.5)
        top = 1 + int(10 - (half * half) // 4)
        put(a, a + 1, 1, top, C['hiwada'])
        put(a, a + 1, max(1, top - 2), top, C['hiwada_l'])
    #! 棟の段（熨斗の代わりの押さえ。**竹ではなく木の棟木**）。
    put(2, 10, 9, 11, C['hiwada_l'])
    put(4, 8, 11, 13, C['beam'])
    return [('main', v, (-6, 0, 0) if ns else (0, -6, 0))]


def manor_gable_ein(name):
    """**入母屋の破風 1 辺**（隅棟が抜けた上の、垂直の三角の面）。

    高さ 1 マスの型を置く側が **sz で段の高さへ伸縮**する（cave_mound の z 伸縮と
    同じ流儀）ので、**縦の要素だけで作る**——横の桟を入れると段の高さで太さが変わる。
    白い壁に**木連格子**（細い縦の桟）、上端に厚い破風板。
    """
    side = _split_style(name)[1].rsplit('_', 1)[-1]
    th = 4
    v = np.zeros((V, V, V), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, C['cream'])
    #! 木連格子（4 vox ピッチの細い縦桟）。伸縮しても本数も太さも変わらない。
    for a in range(1, V, 4):
        put(a, a + 2, 0, V, C['beam'])
    put(0, 3, 0, V, C['beam_l'])       # 端の柱
    put(V - 3, V, 0, V, C['beam_l'])
    put(0, V, V - 4, V, C['timber_d'])  # 破風板（厚い見切り）
    put(0, V, V - 5, V - 4, C['hiwada_d'])
    return [('main', v, (0, 0, 0))]


def bamboo_ein(name):
    """**竹**（迷いの竹林。§4.3 ④「竹を建物の前後に立て、建物より高くする」）。

    永遠亭の地図は**木が 9,773 マス**——町の絵の 8 割がこれである。だから作りは
    「安いこと」が第一の条件になる: 幹は**角柱**（丸くすると greedy が効かない＝
    設計書 §6.1 の木の教訓）、葉は**薄い板の塊**で、どちらも塊ごとに 1 色。

    高さは変種で振る（01 = 4.1 マス 〜 06 = 7.0 マス）。**低い変種ほど本数を増やす**
    ——竹林は 1 本ずつではなく株で生えるもので、根方が混むほど「藪」に見える。
    屋敷の屋根（壁 1.5 ＋ 屋根 3 段 1.31 ＝ 2.8 マス）より**どの変種も高い**。
    """
    step = int(name[-2:]) if name[-2:].isdigit() else 1
    h = EIN_BAMBOO_H[max(0, min(step, len(EIN_BAMBOO_H)) - 1)]
    rng = rng_for(name)
    v = np.zeros((V, V, h), np.uint8)
    culms = 1 if step >= 5 else int(rng.integers(2, 4))
    for _ in range(culms):
        cx = int(rng.integers(8, V - 8))
        cy = int(rng.integers(8, V - 8))
        top = int(h * rng.uniform(0.84, 1.0))
        r = 3 if h >= 170 else 2
        #! しなり（上ほど流れる）。**根元は動かさない**（生えているものである）。
        lean_x = rng.uniform(-2.5, 2.5)
        lean_y = rng.uniform(-2.5, 2.5)
        node = int(rng.integers(20, 27))
        for z in range(top):
            t = z / float(top)
            px = int(round(cx + (lean_x * t * t)))
            py = int(round(cy + (lean_y * t * t)))
            rr = r if t < 0.72 else max(1, r - 1)
            x0, x1 = max(0, px - rr), min(V, px + rr + 1)
            y0, y1 = max(0, py - rr), min(V, py + rr + 1)
            if (x0 >= x1) or (y0 >= y1):
                continue
            ring = ((z % node) < 2) and (z > 6)
            v[x0:x1, y0:y1, z] = C['stalk'] if ring else C['slime_l']
            #! 陰の面（北と西）。**1 色ずつ**なので greedy が縦にまとめる。
            if not ring:
                v[x0, y0:y1, z] = C['slime']
                v[x0:x1, y0, z] = C['slime']
        #! 葉（上の 3 割）。**見下ろすカメラに映るのは葉の天蓋**で、幹はほとんど
        #! 見えない（合成フレームで実測——初版は葉が疎らで、竹林が「灰緑の筋」に
        #! しか見えなかった）。細長い板を重ねて、上から見て緑が繋がるようにする。
        leaves = 12 + step
        for _ in range(leaves):
            t = rng.uniform(0.66, 1.02)
            bz = int(top * t)
            bx = int(round(cx + (lean_x * t * t) + rng.integers(-10, 11)))
            by = int(round(cy + (lean_y * t * t) + rng.integers(-10, 11)))
            if rng.random() < 0.5:
                bw, bd = int(rng.integers(6, 12)), int(rng.integers(2, 4))
            else:
                bw, bd = int(rng.integers(2, 4)), int(rng.integers(6, 12))
            x0, x1 = max(0, bx), min(V, bx + bw)
            y0, y1 = max(0, by), min(V, by + bd)
            z0, z1 = max(0, bz), min(h, bz + int(rng.integers(3, 7)))
            if (x0 >= x1) or (y0 >= y1) or (z0 >= z1):
                continue
            block = v[x0:x1, y0:y1, z0:z1]
            block[block == 0] = rng.choice([C['leaf_l'], C['leaf_h'], C['slime_l']],
                                           p=[0.34, 0.40, 0.26])
    #! 落ち葉と筍（根方に少し。地面のタイルは別物なので、ここでは 1 段だけ）。
    for _ in range(int(rng.integers(0, 3))):
        bx = int(rng.integers(2, V - 5))
        by = int(rng.integers(2, V - 5))
        v[bx:bx + 4, by:by + 4, 0:2] = C['stalk_d']
    return [('main', v, (0, 0, 0))]


def _ground_turf_ein(name):
    """**竹林と庭の地面** — 苔に竹の落ち葉。

    竹林（9,773 マス）と屋敷まわりの草地（1,762 マス）を**同じ材で受ける**。
    町の地面で塗り潰すと森が禿げる（河童のバザーの判断）——それを避けるために
    地を**苔（緑）**にしてある。落ち葉は細長い矩形で、笹の葉の形をそのまま言う。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['soil']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['moss'], C['moss_d'], C['turf_d'], C['soil']], [0.34, 0.28, 0.22, 0.16])
    #! 竹の落ち葉（**塊で置く**＝罠 38。1 ボクセルずつ散らすと砂嵐になる）。
    for _ in range(int(rng.integers(5, 10))):
        shade = C['wilt'] if rng.random() < 0.6 else C['wilt_d']
        if rng.random() < 0.5:
            x = int(rng.integers(0, V - 3))
            y = int(rng.integers(0, V - 7))
            layer[x:x + 2, y:y + 6] = shade
        else:
            x = int(rng.integers(0, V - 7))
            y = int(rng.integers(0, V - 3))
            layer[x:x + 6, y:y + 2] = shade
    _grain(rng, layer, layer > 0, [C['moss_d'], C['turf']], [0.06, 0.05], block=3)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_path_ein(name):
    """**竹林の踏み分け道と飛び石** — 踏み固めた土に、苔の目地の飛び石が 1 つ。

    永遠亭は「人目を避けるようひっそり建つ」（求聞史紀）ので、**敷石は敷かない**
    ——博麗の参道（きちんと整備された自然石）との差はここに出す。マスに 1 つだけ
    大きめの飛び石を散らす（小さい石を撒くと点描になる＝デザイン7 の水溜まりの罠）。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['soil']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack'], C['pack_d'], C['soil'], C['moss_d']], [0.36, 0.28, 0.22, 0.14])
    if rng.random() < 0.62:
        w = int(rng.integers(11, 16))
        d = int(rng.integers(10, 15))
        x = int(rng.integers(2, max(3, V - w - 2)))
        y = int(rng.integers(2, max(3, V - d - 2)))
        layer[x:x + w, y:y + d] = C['flag']
        layer[x + 1:x + w - 1, y + 1:y + d - 1] = C['flag_l']
    #! 縁へ寄った落ち葉（道の真ん中は踏まれて残らない）。
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 5))
        y = 0 if rng.random() < 0.5 else V - 3
        layer[x:x + 4, y:y + 3] = C['wilt_d']
    _grain(rng, layer, layer > 0, [C['grit'], C['pebble']], [0.05, 0.04], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _rampart_take_ein(name):
    """**竹垣**（建仁寺垣）。永遠亭の塀。屋敷の塊は屋敷として立つので出番は少ないが、
    地図に 1〜2 マスの壁の欠片が出たときにここへ落ちる。丸竹を隙間なく立て、
    横に押縁を 3 本、黒い縄で結ぶ。
    """
    rng = rng_for(name)
    height = 46
    v = np.zeros((V, V, height), np.uint8)
    for bx in range(0, V, 4):
        top = int(rng.integers(height - 5, height))
        shade = C['slime_l'] if (rng.random() < 0.6) else C['slime']
        v[bx:bx + 4, :, 0:top] = shade
        v[bx:bx + 1, :, 0:top] = C['stalk_d']  # 竹と竹の間の影
        for z in range(int(rng.integers(12, 20)), top, 22):
            v[bx:bx + 4, :, z:z + 2] = C['stalk']  # 節
    #! 押縁（横に渡した丸竹）と縄。
    for z in (10, 26, 40):
        v[:, 0:4, z:z + 4] = C['stalk']
        v[:, V - 4:V, z:z + 4] = C['stalk']
        for x in range(2, V, 8):
            v[x:x + 2, 0:4, z - 1:z + 5] = C['lash']
            v[x:x + 2, V - 4:V, z - 1:z + 5] = C['lash']
    return [('main', v, (0, 0, 0))]


def genkan_ein(name):
    """**永遠亭の大玄関**（`BUILDING_1`＝蓬莱山輝夜。北面の彫り込みのマス）。

    **このマスは壁ではなく「屋敷に穿たれた 1 マスの凹み」である。**奥（南隣）は屋敷の
    壁なので、障子も濡縁も**隣のマスがもう持っている**（`manor_wall_ein` の南面が
    北へ 8 vox 張り出す）。ここが足すのは、その手前に立つ**車寄せ**だけでよい。

    口は**北へ開く**（地図の (137,31)。北隣の (137,30) が床）。北向きの縦面は
    見下ろすカメラの背面なので、**顔になるのは天面**である（デザイン6 その2 の
    可視の三法則・デザイン7 の露店の罠「縦面に賭けるな」）。だから主役は:

      - **唐破風の庇**（マスの外へ 10 vox。屋根の中で唯一の曲線＝ここが正面だと言う）
      - 沓脱石と飛び石（真上から見えるのは石の天面）
      - 門柱の**灯**（夜の目印。自発光は乗せないので塗りだけ）
    """
    ext = 10
    v = np.zeros((V, V + ext, 70), np.uint8)
    c0 = ext  # マスの北端（local y）
    #! 沓脱石（マスの真ん中。**天面が顔**なので大きく 1 つ＝小石を撒くと点描になる）。
    v[9:24, c0 + 13:c0 + 26, 0:6] = C['flag']
    v[10:23, c0 + 14:c0 + 25, 5:6] = C['flag_l']
    #! 飛び石（口の手前に 2 つ）。
    v[7:16, c0 + 2:c0 + 10, 0:4] = C['flag']
    v[18:27, c0 + 4:c0 + 11, 0:4] = C['flag_l']
    #! 車寄せの柱（マスの北の隅に 2 本。**接地はマスの中**＝footprint の規約）。
    for x0 in (3, 25):
        v[x0:x0 + 4, c0 + 1:c0 + 5, 0:54] = C['beam_l']
        v[x0:x0 + 4, c0 + 1:c0 + 5, 0:3] = C['wall_d']  # 礎石
    #! 頭貫（2 本の柱を結ぶ横木）。
    v[3:29, c0 + 1:c0 + 5, 46:52] = C['beam']
    #! 唐破風（起りと反りのある庇）。**この曲線が「正面」の合図**。
    for y in range(0, c0 + 14):
        t = y / float(c0 + 13)
        z0 = 54 + int(round(5.0 * (1.0 - (((t - 0.62) ** 2) * 5.0))))
        z0 = max(52, min(60, z0))
        v[0:V, y:y + 1, z0:z0 + 4] = C['hiwada_d']
        v[0:V, y:y + 1, z0 + 3:z0 + 4] = C['hiwada']
    #! 棟（庇の付け根）と、破風の懸魚（軒先の中央に垂れる飾り）。
    v[0:V, c0 + 12:c0 + 16, 60:66] = C['hiwada_l']
    v[14:18, 0:3, 48:58] = C['beam']
    #! 灯（門柱の上。夜も形が読める明るさで塗るだけ）。
    for x0 in (3, 25):
        v[x0 - 1:x0 + 5, c0:c0 + 6, 40:46] = C['lit']
    return [('main', v, (0, -ext, 0))]


def shinryo_ein(name):
    """**永遠亭の診療所**（`BUILDING_0`＝八意永琳。南面の彫り込みのマス）。

    大玄関と同じく**1 マスの凹み**で、奥（北隣）の壁は隣のマスが持っている。
    こちらは**南へ開く**（地図の (83,37)。南隣の (83,38) が床）——見下ろすカメラの
    正面なので、**縦の面がそのまま顔になる**。永琳は「月の頭脳」で医者であり、
    ここは屋敷で唯一**人を迎える**口である:

      - **白い暖簾**（薬袋の白。藍の帯 2 本。屋号の字は掛けない——建物の看板は
        無地が既定という約束＝町ごとの表に書くまで黙る）
      - 薬箱と乳鉢の並ぶ土間、軒の吊り灯
      - 檜皮の小庇（マスの外へ 8 vox）
    """
    ext = 8
    v = np.zeros((V, V + ext, 60), np.uint8)
    #! 土間（三和土。**明るい面**にして「口が開いている」ことを言う）。
    v[2:30, 6:V, 0:5] = C['pack_l']
    v[3:29, 8:V - 1, 4:5] = C['pack']
    #! 戸口の柱 2 本と鴨居（マスの南の際。暖簾を吊る枠）。
    for x0 in (1, 27):
        v[x0:x0 + 4, V - 5:V - 1, 0:48] = C['beam_l']
        v[x0:x0 + 4, V - 5:V - 1, 0:3] = C['wall_d']
    v[1:31, V - 5:V - 1, 42:48] = C['beam']
    #! 白い暖簾（3 枚に割れた布。藍の帯 2 本。**南面**なのでここが顔）。
    for x0 in (3, 13, 23):
        v[x0:x0 + 9, V - 3:V - 1, 26:42] = C['nuki']
        v[x0:x0 + 9, V - 3:V - 1, 30:32] = C['ai']
        v[x0:x0 + 9, V - 3:V - 1, 37:39] = C['ai_l']
    #! 薬箱（小引き出しの重ね）と乳鉢・薬研（土間の隅。小さいので塊で言う）。
    v[4:12, 9:17, 5:20] = C['oak']
    for z in range(6, 20, 4):
        v[4:12, 9:10, z:z + 1] = C['timber_d']
    v[5:11, 9:10, 5:20] = C['oak_l']
    v[20:26, 10:16, 5:9] = C['rock_l']
    v[22:28, 18:22, 5:8] = C['iron_l']
    #! 檜皮の小庇（マスの外へ。天面の顔）。
    for y in range(V - 6, V + ext):
        t = (y - (V - 6)) / float(ext + 5)
        z0 = 52 - int(round(t * 6))
        v[0:V, y:y + 1, z0:z0 + 4] = C['hiwada_d']
        v[0:V, y:y + 1, z0 + 3:z0 + 4] = C['hiwada']
    v[0:V, V - 8:V - 4, 52:56] = C['hiwada_l']
    #! 軒の吊り灯（暗い軒下に 1 つ。塗りだけ）。
    v[14:18, V:V + 3, 44:48] = C['lit']
    return [('main', v, (0, 0, 0))]


# ---- 香霖堂の意匠（デザイン9・2026-08-19）----
#
# §4.1 の外せない 1 点は「**入母屋の店舗＋白い土蔵が渡り廊下でつながった 2 棟の
# シルエット**」で、単棟にすると里の商家と混ざる。地図の壁の塊は 241 マスの 1 枚岩
# （34×10）なので、置く側が**南から食い込む切れ込みで 3 つに割って**からここへ来る
# （`TownPlan::wings`。0=店舗 / 1=土蔵 / 2=渡り廊下）。材の名前は棟ごとの札で:
#
#   `_kor` … 瓦の店舗（焼杉の腰板・障子・連子窓。壁 1.7 マス）
#   `_kra` … 白い土蔵（なまこ壁の腰・白漆喰・鉄格子の小窓。壁 2.4 マス＝**いちばん高い**）
#   `_wat` … 渡り廊下（板の腰と連子だけ。壁 1.2 マス＝**いちばん低い**）
#
# **高さは型が持つ**（置く側は `top_of(wall)` に屋根を積むだけ）。2 棟の間が低く
# 落ちるのは、この 3 つの数の差だけで出来ている。
KOR_WALL_H = {'kor': 54, 'kra': 78, 'wat': 38}  #!< 棟ごとの壁の高さ（vox）
KOR_RISE = 13  #!< 屋根 1 段の上がり。3 段＝1.22 マス


def _kor_wing(name):
    """名前から棟の札を読む（無ければ店舗）。**`_split_style` を使わない**——
    `kra` と `wat` は町の意匠ではなく**棟**で、`TOWN_STYLES` に入れると
    家並み一式 37 個がもう 2 組焼かれてしまう。"""
    for tok in ('kra', 'wat'):
        if ('_%s_' % tok) in name or name.endswith('_' + tok):
            return tok
    return 'kor'


def _kor_words(name):
    """棟と意匠の札を落とした語の並び（`manor_wall_nw_kra_01` → `[manor, wall, nw, 01]`）。"""
    return [p for p in name.split('_') if p not in ('kor', 'kra', 'wat')]


def manor_wall_kor(name):
    """**香霖堂の壁 1 マス**。棟の札で材が変わる（上の表）。

    どれも**横の線で読ませる**（腰・敷居・長押・軒下）のは和風の要だが、
    棟ごとに線の高さが違うので、並べると 3 つの建物として読める:

      - 店舗（`_kor`）… 焼杉の腰板 → 敷居 → 障子か連子の帯 → 長押。変種は帯だけ振る
        （`_01` 羽目板 / `_02` 障子 / `_03` 連子窓）。ベイの律動は置く側が 4 マス周期で選ぶ
      - 土蔵（`_kra`）… **なまこ壁**（黒瓦を菱に貼り、白漆喰の目地が斜めに交差）を
        腰へ、その上は塗り込めの白漆喰。**窓は小さく高い**（`_02` にだけ鉄格子）。
        §4.1 ③「土蔵の白を面積で効かせる」はここと軒（白い鉢巻）で確保する
      - 渡り廊下（`_wat`）… 板の腰と連子。低いので屋根も低く、2 棟の間が沈む
    """
    wing = _kor_wing(name)
    words = _kor_words(name)  # manor wall <slice> [nn]
    key = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    height = KOR_WALL_H[wing]
    v = np.zeros((V, V, height), np.uint8)
    #! 基礎（切石）と躯体。躯体の色は**切れ目から覗く色**なので暗く詰める。
    v[:, :, 0:4] = C['wall_d']
    v[:, :, 4:height] = C['timber_d'] if (wing != 'kra') else C['kura_wd']
    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in faces:
        vert = side in ('w', 'e')
        if side == 'n':
            fx, fy = slice(0, V), slice(0, 3)
        elif side == 's':
            fx, fy = slice(0, V), slice(V - 3, V)
        elif side == 'w':
            fx, fy = slice(0, 3), slice(0, V)
        else:
            fx, fy = slice(V - 3, V), slice(0, V)

        def band(z0, z1, colour):
            v[fx, fy, z0:z1] = colour

        def stripe(p0, p1, z0, z1, colour):
            if vert:
                v[fx, p0:p1, z0:z1] = colour
            else:
                v[p0:p1, fy, z0:z1] = colour

        if wing == 'kra':
            #! ---- 土蔵 ----
            band(4, 10, C['wall'])            # 石の腰石
            band(10, 34, C['namako'])         # なまこ壁の地（黒瓦）
            #! 白漆喰の目地を**斜めに 2 方向**。交差した菱がなまこ壁の記号である。
            for p in range(-34, V + 34, 9):
                for z in range(10, 34):
                    a0 = p + (z - 10)
                    a1 = p - (z - 10)
                    for a in (a0, a1):
                        if 0 <= a < V - 1:
                            stripe(a, a + 2, z, z + 1, C['kura_wl'])
            band(34, 37, C['kura_wl'])        # 水切りの白い帯
            band(37, height - 9, C['kura_w'])
            #! 塗り込めの面は**均さない**。刷毛の斑を塊で 2〜3 か所だけ（点描にしない）。
            for _ in range(int(rng.integers(2, 4))):
                a = int(rng.integers(2, V - 8))
                z = int(rng.integers(40, max(41, height - 18)))
                stripe(a, a + 6, z, z + 8, C['kura_wl'])
            if variant == 2:
                #! 鉄格子の小窓（**高い所に小さく**。ライブラリは採光を嫌う）。
                z0 = height - 26
                stripe(11, 21, z0, z0 + 12, C['char'])
                for a in range(12, 21, 3):
                    stripe(a, a + 1, z0 + 1, z0 + 11, C['iron_l'])
                stripe(10, 22, z0 + 12, z0 + 14, C['kura_wl'])  # 窓庇の白
            band(height - 9, height - 4, C['kura_wl'])  # 軒の鉢巻（塗り込め）
            band(height - 4, height, C['beam'])         # 化粧軒（木の見切り）
            continue
        #! ---- 店舗と渡り廊下（木の造り）----
        low = (wing == 'wat')
        sill = 18 if low else 22
        top_band = 32 if low else 44
        band(4, 8, C['beam'])                 # 土台
        band(8, sill, C['shitami'])           # 腰板（下見板）
        for p in range(0, V, 4):
            stripe(p, p + 1, 8, sill, C['shitami_d'])
        band(sill, sill + 3, C['beam_l'])     # 敷居
        if low:
            #! 渡り廊下は**連子だけ**（板で塞ぐと通路に見えない）。
            band(sill + 3, top_band, C['board_d'])
            for p in range(1, V, 4):
                stripe(p, p + 2, sill + 3, top_band, C['beam'])
        elif variant == 2:
            band(sill + 3, top_band, C['shoji'])   # 障子
            for p in range(3, V, 8):
                stripe(p, p + 2, sill + 3, top_band, C['beam'])
            stripe(0, V, (sill + top_band) // 2, (sill + top_band) // 2 + 1, C['beam'])
        elif variant == 3:
            band(sill + 3, top_band, C['board_d'])  # 連子窓
            for p in range(1, V, 4):
                stripe(p, p + 2, sill + 3, top_band, C['beam'])
        else:
            band(sill + 3, top_band, C['board'])    # 竪羽目の板壁
            for p in range(0, V, 6):
                stripe(p, p + 1, sill + 3, top_band, C['board_d'])
            for p in range(3, V, 6):
                stripe(p, p + 1, sill + 3, top_band, C['board_l'])
        band(top_band, top_band + 4, C['beam_l'])   # 長押（濃茶の水平線 1 本）
        band(top_band + 4, height, C['timber_d'])   # 軒下（垂木の影）
        #! 柱は**面の両端だけ**（タイルするとマス境で 1 本になる）。
        for p in (0, V - 3):
            stripe(p, p + 3, 4, height, C['beam_l'])
    return [('main', v, (0, 0, 0))]


def manor_roofslope_kor(name):
    """**瓦葺きの斜面 1 マス**（`_kor` 桟瓦のいぶし銀 / `_kra` 土蔵の本瓦）。

    畝は**流れに沿う**（丸瓦が軒へ向かって走る）。檜皮（永遠亭）が流れに直交する
    細い段だったのと**逆向き**で、そこが材の見分けになる。1 マスで `KOR_RISE` 上がり、
    置く側が「マスごとの距離 × top_z」で積む。

    土蔵の軒は**塗り込め**（白漆喰が軒先まで回る）。§4.1 ③「白を面積で効かせる」は
    見下ろしのカメラでは壁より軒で効く——屋根の縁に白い線が回ると、上から見ても
    2 棟が別の材だと分かる。
    """
    wing = _kor_wing(name)
    words = _kor_words(name)  # manor roofslope|roofeave <side> [nn]
    side = words[2]
    eave = (words[1] == 'roofeave')
    kura = (wing == 'kra')
    rng = rng_for(name)
    ext = (6 if kura else 10) if eave else 0
    along_x = side in ('w', 'e')
    #! **型の高さは KOR_RISE ちょうど。**置く側は「段 × top_z」で積むので、型が
    #! 天面より高いと**マスごとに 2 vox の返し**が出来る——それが北向きの小さな壁に
    #! なって、低い日ざしで**屋根じゅうが自分の影に沈む**（合成フレームで実測。
    #! 初版は丸瓦を持ち上げるつもりで +2 していた）。
    if along_x:
        v = np.zeros((V + ext, V, KOR_RISE), np.uint8)
    else:
        v = np.zeros((V, V + ext, KOR_RISE), np.uint8)
    low_first = side in ('n', 'w')
    pitch = 8 if kura else 6  # 丸瓦の間隔（本瓦は太く、桟瓦は細かい）
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            a = x if along_x else y
            aa = a - ext if low_first else a
            cross = y if along_x else x
            ridge_line = (cross % pitch) < 2
            if (aa < 0) or (aa >= V):
                #! 軒先。**z=0 に置かない**（マスの外へ出るので、接地すると footprint の
                #! 照合が floor 除算の食い違いで落ちる＝時計塔の罠）。
                if kura:
                    v[x, y, 1:5] = C['kura_w']   # 塗り込めの軒（白い縁）
                    v[x, y, 4] = C['kura_wl']
                else:
                    v[x, y, 1:4] = C['sanga_d']
                    v[x, y, 3] = C['sanga_l'] if ridge_line else C['sanga']
                continue
            t = aa if low_first else (V - 1 - aa)
            surf = 2 + ((t * (KOR_RISE - 2)) // (V - 1))
            #! **段の立ち上がり（蹴込み）は地の色**。初版はここを `sanga_d`（42,41,47）に
            #! していて、勾配 1 マスで 11 段も上がるので、見下ろすと**画の 4 割が蹴込み**に
            #! なり、屋根が真っ黒に見えた（合成フレームで実測）。暗くするのは目地だけ。
            v[x, y, 0:surf] = C['sanga']
            #! 丸瓦は**色の縞だけ**で言う。初版は 1 vox 持ち上げて畝にしていたが、
            #! 斜面は 1 vox ずつ段になって下りるので、持ち上げた列が**俵の山**に見えた
            #! （合成フレームで実測）。曲面に載る細い凹凸は、この縮尺では読めない。
            v[x, y, surf - 1] = C['sanga_l'] if ridge_line else C['sanga']
            if (cross % pitch) == 2:
                v[x, y, surf - 1] = C['sanga_d']  # 瓦と瓦の合わせ目（影の線）
    #! 苔と煤の斑（塊で 0〜2 か所だけ）。
    for _ in range(int(rng.integers(0, 3))):
        cx = int(rng.integers(0, max(1, v.shape[0] - 5)))
        cy = int(rng.integers(0, max(1, v.shape[1] - 5)))
        for x in range(cx, min(cx + int(rng.integers(3, 7)), v.shape[0])):
            for y in range(cy, min(cy + int(rng.integers(3, 7)), v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['sanga_g']
                        break
    if along_x:
        origin = (-ext if low_first else 0, 0, 0)
    else:
        origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_rooftop_kor(name):
    """**平らな大棟 1 マス**（段の上限に達したマス）。斜面の型を同じ段で並べると鋸歯に
    なるので、頭打ちのマスはこれで受ける（デザイン8 の罠）。畝の割り付けは斜面と同じ。"""
    kura = (_kor_wing(name) == 'kra')
    rng = rng_for(name)
    v = np.zeros((V, V, KOR_RISE), np.uint8)
    v[:, :, 0:KOR_RISE] = C['sanga']
    pitch = 8 if kura else 6
    for x in range(V):
        v[x, :, KOR_RISE - 1] = C['sanga_l'] if ((x % pitch) < 2) else C['sanga']
        if (x % pitch) == 2:
            v[x, :, KOR_RISE - 1] = C['sanga_d']
    for _ in range(int(rng.integers(0, 3))):
        cx = int(rng.integers(0, V - 5))
        cy = int(rng.integers(0, V - 5))
        v[cx:cx + int(rng.integers(3, 7)), cy:cy + int(rng.integers(3, 7)), KOR_RISE - 1] \
            = C['sanga_g']
    return [('main', v, (0, 0, 0))]


def manor_ridge_kor(name):
    """**熨斗瓦を重ねた棟**（`manor_ridge_kor` 東西 / `manor_ridge_ns_kor` 南北）。

    入母屋は平面の形で棟の向きが変わるので 2 本要る。段を 3 つ重ねて上に丸瓦を伏せる
    ——**鬼瓦は載せない**（社寺ではなく店である）。土蔵の棟は白漆喰で塗り込める。
    """
    words = _kor_words(name)
    ns = ('ns' in words)
    kura = (_kor_wing(name) == 'kra')
    long_, thick, h = V, 12, 14
    v = np.zeros((thick, long_, h) if ns else (long_, thick, h), np.uint8)

    def put(a0, a1, z0, z1, colour):
        if ns:
            v[a0:a1, :, z0:z1] = colour
        else:
            v[:, a0:a1, z0:z1] = colour

    put(0, thick, 1, 5, C['sanga_d'])       # 熨斗 1 段目
    put(1, thick - 1, 5, 9, C['sanga'])     # 2 段目
    put(2, thick - 2, 9, 11, C['sanga_l'])  # 3 段目
    #! 冠瓦（伏せた丸瓦）。断面を蒲鉾に。
    for a in range(3, thick - 3):
        half = abs(a - 5.5)
        top = 11 + int(3 - (half * half) // 3)
        put(a, a + 1, 11, max(12, top), C['sanga_l'] if kura else C['sanga'])
    if kura:
        #! 土蔵の棟は塗り込め（白い線が屋根の頂を走る）。
        put(0, thick, 3, 5, C['kura_w'])
        put(2, thick - 2, 9, 11, C['kura_wl'])
    return [('main', v, (-6, 0, 0) if ns else (0, -6, 0))]


def manor_gable_kor(name):
    """**入母屋の破風 1 辺**（隅棟が抜けた上の、垂直の三角の面）。

    高さ 1 マスの型を置く側が **sz で段の高さへ伸縮**するので、**縦の要素だけ**で
    作る（横の桟は段の高さで太さが変わる）。店舗は白漆喰に木の破風板、
    土蔵は**塗り込めの白一色**（木を見せないのが土蔵の造りである）。
    """
    wing = _kor_wing(name)
    side = _kor_words(name)[-1]
    th = 4
    v = np.zeros((V, V, V), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    if wing == 'kra':
        put(0, V, 0, V, C['kura_w'])
        put(0, 3, 0, V, C['kura_wl'])
        put(V - 3, V, 0, V, C['kura_wl'])
        put(0, V, V - 4, V, C['sanga_d'])   # 瓦の見切りだけ
        return [('main', v, (0, 0, 0))]
    put(0, V, 0, V, C['cream'])
    for a in range(1, V, 5):                # 木連格子（細い縦桟）
        put(a, a + 2, 0, V, C['beam'])
    put(0, 3, 0, V, C['beam_l'])
    put(V - 3, V, 0, V, C['beam_l'])
    put(0, V, V - 4, V, C['timber_d'])      # 破風板
    put(0, V, V - 5, V - 4, C['sanga_d'])
    return [('main', v, (0, 0, 0))]


def mise_kor(name):
    """**香霖堂の店の口**（`BUILDING_0`＝森近霖之助。南面の彫り込みのマス）。

    §4.1 ④「**入口だけ洋風**（濃茶の開き戸＋真鍮のノブ）——これが阿求の言う
    『ごちゃごちゃとして落ち着きのない**異国風**の建物』の正体」。和風の店構えに
    **開き戸が 1 枚**あるだけで異国風に転ぶ、というのが原作の読みなので、
    ここは引き戸にしてはならない。

    口は**南へ開く**（地図の (115,14)。南隣が前庭）ので、見下ろすカメラの正面＝
    **縦の面がそのまま顔**になる。だから戸そのものに賭ける:

      - 濃茶の開き戸（**片側だけ内へ開いている**。閉じた板より「店」に見える）
      - 真鍮のノブと蝶番、上半分にガラス
      - 軒の瓦の小庇と、吊り看板 1 枚
      - 戸口の外に**ガラクタ**（拾い集めた道具屋の記号。§4.1 ⑥）
    """
    ext = 8
    v = np.zeros((V, V + ext, 62), np.uint8)
    #! 土間（踏み石。天面が見えるので明るく）。
    v[3:29, 8:V, 0:5] = C['pack_l']
    v[6:26, 12:V - 2, 4:5] = C['flag']
    #! 戸口の枠（洋風なので**太い方立**）。縁に**生成りの見切り**を 1 本入れて、
    #! 影に沈んでも口の輪郭が残るようにする。
    for x0 in (2, 26):
        v[x0:x0 + 4, V - 6:V - 1, 0:50] = C['door_wd']
        v[x0 + 1:x0 + 3, V - 2:V - 1, 4:48] = C['cream']
    v[2:30, V - 6:V - 1, 44:50] = C['door_wd']
    v[2:30, V - 2:V - 1, 46:48] = C['cream']
    #! 扉 2 枚。西側は閉じ、東側は**内へ 6 vox 開いている**。
    #!
    #! **硝子は明るく**（`lit`）。濃茶の扉を濃茶の壁に付けると、庇の影に入った縦面では
    #! **輪郭が 1 画素も出ない**（合成フレームで実測）。店の中の灯りが硝子越しに見える
    #! ——「明るい店」は原作の香霖堂の姿でもあるので、ここは光らせるのが正しい。
    v[6:16, V - 3:V - 1, 4:44] = C['door_w']
    v[6:16, V - 3:V - 1, 26:41] = C['lit']
    v[10:12, V - 3:V - 1, 26:41] = C['door_wd']   # 硝子の桟（縦）
    v[6:16, V - 3:V - 1, 33:34] = C['door_wd']    # 同（横）
    v[17:27, V - 9:V - 7, 4:44] = C['door_w']
    v[17:27, V - 9:V - 7, 26:41] = C['lit']
    v[21:23, V - 9:V - 7, 26:41] = C['door_wd']
    #! 真鍮のノブ（左右の戸の内側）と蝶番。
    v[15:17, V - 4:V - 1, 22:25] = C['brass']
    v[16:18, V - 10:V - 7, 22:25] = C['brass']
    for z in (10, 38):
        v[6:8, V - 4:V - 1, z:z + 3] = C['brass_d']
    #! 瓦の小庇（マスの外へ 8 vox。天面の顔）。
    for y in range(V - 4, V + ext):
        t = (y - (V - 4)) / float(ext + 3)
        z0 = 54 - int(round(t * 5))
        v[0:V, y:y + 1, z0:z0 + 4] = C['sanga_d']
        v[0:V, y:y + 1, z0 + 3:z0 + 4] = C['sanga']
    v[0:V, V - 7:V - 3, 54:58] = C['sanga_l']
    #! 吊り看板（**無地の板ではなく**、白抜きの帯を 1 本入れて屋号に見せる）。
    v[8:24, V + 2:V + 4, 40:52] = C['board']
    v[9:23, V + 2:V + 4, 43:49] = C['nuki']
    v[8:24, V + 2:V + 4, 51:52] = C['beam_l']
    #! 戸口の外のガラクタ（拾い物の山。§4.1 ⑥）。**マスの外は z=1 から**——接地が
    #! マスの外へ出ると footprint の照合で落ちる（時計塔の罠。デザイン8 でも踏んだ）。
    v[1:9, V + 1:V + 7, 1:7] = C['rust']
    v[2:7, V + 2:V + 5, 6:11] = C['iron_l']
    v[24:30, V + 2:V + 8, 1:5] = C['oak']
    v[25:29, V + 3:V + 7, 4:9] = C['steel_d']
    return [('main', v, (0, 0, 0))]


def kura_kor(name):
    """**香霖堂の工房の口**（`BUILDING_8`。北面の彫り込みのマス）。

    口は**北へ開く**（地図の (100,14)。北隣が床）ので、縦の面はカメラの背面になる
    ——**顔になるのは天面**である（デザイン6 その2 の可視の三法則）。だから主役は
    庇と地面の物にする:

      - **蔵の戸前**（土蔵の分厚い観音扉。黒漆喰の縁と鉄の閂）
      - マスの外へ 10 vox 出る瓦の庇（真上から見えるのはこれ）
      - 沓脱石と、直しかけの道具（車輪・鉄の桶）
    """
    ext = 10
    v = np.zeros((V, V + ext, 64), np.uint8)
    c0 = ext  # マスの北端（local y）
    #! 三和土（土間）と沓脱石。
    v[3:29, c0:c0 + 24, 0:5] = C['pack']
    v[10:23, c0 + 2:c0 + 12, 4:8] = C['flag']
    #! 戸前の枠（**塗り込めの白**。土蔵の口は壁と同じ材で縁取る）。
    for x0 in (1, 27):
        v[x0:x0 + 4, c0 + 1:c0 + 6, 0:52] = C['kura_w']
    v[1:31, c0 + 1:c0 + 6, 46:52] = C['kura_w']
    v[1:31, c0 + 1:c0 + 6, 44:46] = C['namako']
    #! 観音扉 2 枚（黒漆喰。**閂と鉄の把手**を横に通す）。
    for x0 in (5, 17):
        v[x0:x0 + 10, c0 + 2:c0 + 4, 5:44] = C['namako']
        v[x0 + 1:x0 + 9, c0 + 2:c0 + 4, 7:42] = C['namako_l']
    v[5:27, c0 + 1:c0 + 3, 22:26] = C['iron_l']
    v[14:18, c0:c0 + 3, 20:28] = C['iron']
    #! 瓦の庇（マスの外へ。**天面の顔**）。
    for y in range(0, c0 + 6):
        t = 1.0 - (y / float(c0 + 5))
        z0 = 52 - int(round(t * 6))
        v[0:V, y:y + 1, z0:z0 + 4] = C['sanga_d']
        v[0:V, y:y + 1, z0 + 3:z0 + 4] = C['sanga']
    v[0:V, c0 + 4:c0 + 8, 52:56] = C['sanga_l']
    #! 直しかけの道具（車輪と鉄の桶。**天面で読ませる**ので大きく 2 つ）。
    #! **マスの外は z=1 から**（接地がマスの外へ出ると footprint の照合で落ちる）。
    for z in range(1, 12):
        v[4:6, 1:9, z] = C['iron_l']
        v[12:14, 1:9, z] = C['iron_l']
    v[4:14, 1:3, 1:12] = C['iron']
    v[4:14, 7:9, 1:12] = C['iron']
    v[20:28, 2:10, 1:7] = C['steel_d']
    v[21:27, 3:9, 6:7] = C['rust']
    return [('main', v, (0, -ext, 0))]


def byou_kor(name):
    """**神霊廟出張所**（`BUILDING_3`。南の塊の北面の彫り込み）。

    神霊廟は道士（豊聡耳神子）の廟なので、和の店構えとは**別の系統**で作る——
    朱の柱に緑青の梁、扉は円い環の把手。ここも**北へ開く**（地図の (116,51)）ので、
    顔は天面＝反りの強い庇と、参道の香炉が受け持つ。
    """
    ext = 8
    v = np.zeros((V, V + ext, 58), np.uint8)
    c0 = ext
    v[4:28, c0:c0 + 22, 0:5] = C['flag']
    v[6:26, c0 + 2:c0 + 18, 4:5] = C['flag_l']
    #! 朱の柱 2 本と緑青の梁（道教の色。**朱は柱だけ**＝§4.2 の朱の使い方）。
    for x0 in (2, 26):
        v[x0:x0 + 4, c0 + 2:c0 + 6, 0:46] = C['shu']
        v[x0:x0 + 4, c0 + 2:c0 + 6, 0:3] = C['wall_d']
    v[2:30, c0 + 2:c0 + 6, 40:46] = C['pipe']
    #! 扉（濃い板に環の把手）。
    v[7:25, c0 + 3:c0 + 5, 4:40] = C['timber_d']
    v[8:15, c0 + 3:c0 + 5, 6:38] = C['timber']
    v[17:24, c0 + 3:c0 + 5, 6:38] = C['timber']
    for x0 in (13, 18):
        v[x0:x0 + 2, c0 + 2:c0 + 4, 20:24] = C['brass']
    #! 反りの強い庇（**曲線が「別の系統」だと言う**）。
    for y in range(0, c0 + 7):
        t = y / float(c0 + 6)
        z0 = 46 + int(round(4.0 * (t * t)))
        v[0:V, y:y + 1, z0:z0 + 4] = C['sanga_d']
        v[0:V, y:y + 1, z0 + 3:z0 + 4] = C['sanga']
    v[0:V, c0 + 5:c0 + 9, 46:50] = C['shu_d']
    #! 香炉（参道の真ん中。三本足の鼎）。**マスの外は z=1 から**（footprint の照合）。
    v[13:19, 1:7, 1:9] = C['pipe_d']
    v[12:20, 0:8, 8:11] = C['pipe']
    for x0 in (13, 18):
        v[x0:x0 + 1, 2:3, 1:4] = C['iron']
    return [('main', v, (0, -ext, 0))]


def junk_kor(name):
    """**ガラクタの山**（§4.1 ⑥「戸口の外にガラクタを積む」）。

    霖之助は**外の世界から流れ着いた道具**を拾い集めて売る道具屋なので、
    山の中身は**和の物ではない**（鉄の輪・硝子瓶・鋼の板・木箱）。
    塊ごとに 1 色（罠 38）で、4 変種は積み方だけ違う。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 22), np.uint8)
    shades = [C['rust'], C['iron_l'], C['steel_d'], C['oak'], C['glass_l'], C['board_d']]
    for _ in range(int(rng.integers(4, 8))):
        w = int(rng.integers(6, 13))
        d = int(rng.integers(6, 13))
        x = int(rng.integers(1, max(2, V - w - 1)))
        y = int(rng.integers(1, max(2, V - d - 1)))
        z0 = int(rng.integers(0, 8))
        h = int(rng.integers(4, 10))
        v[x:x + w, y:y + d, z0:z0 + h] = shades[int(rng.integers(0, len(shades)))]
    #! いちばん上に 1 つだけ**丸いもの**（車輪か桶の口）。四角ばかりだと瓦礫に見える。
    cx = int(rng.integers(10, 20))
    cy = int(rng.integers(10, 20))
    for x in range(max(0, cx - 7), min(V, cx + 8)):
        for y in range(max(0, cy - 7), min(V, cy + 8)):
            r = ((x - cx) ** 2) + ((y - cy) ** 2)
            if 20 <= r <= 46:
                top = int(v[x, y].nonzero()[0].max()) + 1 if v[x, y].any() else 0
                v[x, y, top:top + 3] = C['iron_l']
    return [('main', v, (0, 0, 0))]


def lamp_post_kor(name):
    """**角行灯の街灯**（森の入り口の道。木の柱に四角い紙の火袋）。

    石灯籠（永遠亭）でも裸電球（河童）でもない**第 3 の灯**にする——同じ画面には
    並ばないが、町の記号は 1 つずつ違えておくのが 14 町を描き分ける唯一の道である。
    火は別体（`lamp_flame_kor`）。
    """
    v = np.zeros((V, V, 66), np.uint8)
    v[13:19, 13:19, 0:4] = C['wall_d']      # 礎石
    v[14:18, 14:18, 4:44] = C['beam_l']     # 柱
    #! 火袋（四角い紙。**枠は細く**——太いと灯が見えない＝鉄の街灯の穴）。
    v[10:22, 10:22, 44:60] = C['nuki']
    for x0, y0 in ((10, 10), (10, 20), (20, 10), (20, 20)):
        v[x0:x0 + 2, y0:y0 + 2, 44:60] = C['beam']
    v[9:23, 9:23, 60:63] = C['board']       # 笠
    v[10:22, 10:22, 62:65] = C['board_l']
    return [('main', v, (0, 0, 0))]


def lamp_flame_kor(name):
    """角行灯の灯（紙の面の内側。自発光は置く側がインスタンスで足す）。"""
    v = np.zeros((V, V, 66), np.uint8)
    v[11:21, 11:21, 45:59] = C['lit']
    return [('main', v, (0, 0, 0))]


def _ground_turf_kor(name):
    """**森の入り口の下草** — 短い草に落ち葉と小枝。

    香霖堂は「人里から魔法の森へ向かう**森の入り口**」（§4.1）なので、
    地は**緑のまま**にする（河童のバザーで避けた「森が禿げる」と同じ判断）。
    差は落ち葉の量で出す——広葉樹の葉なので、笹（永遠亭）より**丸く大きい**。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['soil']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['turf'], C['turf_d'], C['moss'], C['soil']], [0.34, 0.28, 0.22, 0.16])
    for _ in range(int(rng.integers(4, 9))):
        shade = C['wilt'] if rng.random() < 0.55 else C['wilt_d']
        x = int(rng.integers(0, V - 5))
        y = int(rng.integers(0, V - 5))
        layer[x:x + 4, y:y + 3] = shade
        layer[x + 1:x + 3, y + 3:y + 4] = shade
    #! 小枝（1 本だけ。落ち葉と同じ色だと見えないので暗く）。
    if rng.random() < 0.5:
        x = int(rng.integers(2, V - 12))
        y = int(rng.integers(2, V - 3))
        layer[x:x + 10, y:y + 1] = C['bark']
    _grain(rng, layer, layer > 0, [C['moss_d'], C['turf_l']], [0.06, 0.05], block=3)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_path_kor(name):
    """**森の小道** — 踏み固めた土に轍と落ち葉。

    博麗の参道（整備された自然石）とも永遠亭の飛び石とも違い、**石を 1 つも敷かない**
    ——ここは店へ通う荷車の道である。轍を 2 本、縁に落ち葉を寄せる。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['soil']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['pack'], C['pack_d'], C['dirt'], C['soil']], [0.36, 0.28, 0.22, 0.14])
    for _ in range(2):
        x = int(rng.integers(5, V - 5))
        for y in range(V):
            layer[max(0, min(V - 1, x)), y] = C['pack_d']
            layer[max(0, min(V - 1, x + 1)), y] = C['pack_d']
            x += int(rng.integers(-1, 2))
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 5))
        y = 0 if rng.random() < 0.5 else V - 4
        layer[x:x + 4, y:y + 3] = C['wilt_d']
    _grain(rng, layer, layer > 0, [C['grit'], C['pebble']], [0.05, 0.04], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _rampart_tama_kor(name):
    """**玉垣の石柱**（香霖堂の塀）。

    この町の壁の欠片は**神霊廟出張所を囲む 1 マスの点が 6 つ**（実測）で、線の塀では
    ない。土塀の板を立てると廟の前に壁が生えるので、**1 本の石柱**として立てる
    ——角柱に笠石、正面に浅い彫り。塊で立つ塀（この町には無い）でも柱の列になる。
    """
    rng = rng_for(name)
    height = int(rng.integers(38, 46))
    v = np.zeros((V, V, height), np.uint8)
    v[8:24, 8:24, 0:3] = C['wall_d']            # 根石
    v[10:22, 10:22, 3:height - 4] = C['flag']
    v[11:21, 11:21, 3:height - 4] = C['flag_l']
    #! 浅い彫り（1 vox。底を暗く＝設計書 §6）。
    for z in range(10, height - 8, 6):
        v[11:21, 10:11, z:z + 2] = C['flag_d']
        v[10:11, 11:21, z:z + 2] = C['flag_d']
    v[9:23, 9:23, height - 4:height - 1] = C['flag']   # 笠石
    v[10:22, 10:22, height - 1:height] = C['flag_l']
    #! 苔（根元だけ）。
    if rng.random() < 0.6:
        v[10:22, 10:12, 3:6] = C['moss_d']
    return [('main', v, (0, 0, 0))]


# ---- 命蓮寺の意匠（デザイン10・2026-08-19）----
#
# §4.2 の外せない 1 点は「**灰の瓦屋根と赤い幟の列、そして鳥居を置かないこと**。
# 幟を外すと『白壁の大きな和風建築』になり、鳥居を足すと神社 2 件と区別が付かない」。
# **塔（五重塔・多宝塔）は原作の描写に無い**ので建てない（実在モデルの朝護孫子寺の
# 特徴で、二次創作でも一部）。道教の意匠も混ぜない（あれは神霊廟のもの）。
#
# 地図は**本堂 756 マス（39×21・充填 0.92）**の大伽藍と、東の宿坊 119 マス、そして
# **孤立した 1 マスの壁が 138 個**（北東の囲いに 135・西の参道の脇に 3）——これが
# §4.2 の挙げる**千体地蔵**である。塀として立てると境内じゅうに土塀の欠片が生える。
MYO_WALL_H = 84   #!< 本堂の壁の高さ（2.6 マス）。3 件でいちばん高い建物
MYO_RISE = 16     #!< 屋根 1 段の上がり。**10 段＝5 マス**の大屋根になる
#! 11（0.34 マス＝17°）で試したら、39×21 の平面では**平たい板**に見えた（合成フレームで
#! 実測）。寺の屋根は勾配が命なので 16（0.5 マス＝26°）まで起こす——壁 2.6 と合わせて
#! 総高 7.6 マス、幻想蛮怒でいちばん高い建物になる（大伽藍なので、それでよい）。


def _myo_words(name):
    return [p for p in name.split('_') if p != 'myo']


def manor_wall_myo(name):
    """**命蓮寺の本堂の壁 1 マス**（石の基壇＋腰板＋長押＋**白壁**・高さ 2.6 マス）。

    §4.2 ②「白壁 `#EDE8DE`〜`#F2EFE6`（3 件で最も明るい建物に）」。神社 2 件を
    茅と檜皮の暖色にしてあるので、**白壁と灰瓦の冷たさだけで「寺」と読める**。

    変種は**間（ベイ）の律動**で選ばれる（置く側が 4 マス周期で `_01 _02 _01 _03`）:

      - `_01` 白壁（漆喰の平）……主
      - `_02` 連子窓（縦の細い格子）……変化
      - `_03` 板扉（横桟の板戸）……差し色

    **朱は垂木の鼻に細く 1 本**だけ入れる（実測で命蓮寺の朱は 2.2%＝3 件でいちばん
    多いが、面で塗ると神社に寄る。幟が朱の主役である）。
    """
    words = _myo_words(name)  # manor wall <slice> [nn]
    key = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    height = MYO_WALL_H
    v = np.zeros((V, V, height), np.uint8)
    #! 石の基壇と、暗い躯体（切れ目から覗く色）。
    v[:, :, 0:6] = C['wall_d']
    v[:, :, 5:6] = C['wall']
    v[:, :, 6:height] = C['timber_d']
    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in faces:
        vert = side in ('w', 'e')
        if side == 'n':
            fx, fy = slice(0, V), slice(0, 3)
        elif side == 's':
            fx, fy = slice(0, V), slice(V - 3, V)
        elif side == 'w':
            fx, fy = slice(0, 3), slice(0, V)
        else:
            fx, fy = slice(V - 3, V), slice(0, V)

        def band(z0, z1, colour):
            v[fx, fy, z0:z1] = colour

        def stripe(p0, p1, z0, z1, colour):
            if vert:
                v[fx, p0:p1, z0:z1] = colour
            else:
                v[p0:p1, fy, z0:z1] = colour

        band(6, 10, C['beam'])                 # 地覆
        band(10, 28, C['board'])               # 腰板（竪羽目）
        for p in range(0, V, 5):
            stripe(p, p + 1, 10, 28, C['board_d'])
        band(28, 32, C['beam_l'])              # 腰長押
        band(32, height - 12, C['myo_w'])      # 白壁
        #! 塗りの斑（塊で 2〜3 か所だけ。点描にしない＝罠 38）。
        for _ in range(int(rng.integers(2, 4))):
            a = int(rng.integers(2, V - 8))
            z = int(rng.integers(36, max(37, height - 24)))
            stripe(a, a + 6, z, z + 7, C['myo_wl'])
        if variant == 2:
            #! 連子窓（縦の細い格子。寺の壁で唯一の「線の面」）。
            #! **帯を細く**——広く取ると白壁の面積が減って、遠目で「白い建物」に
            #! 見えなくなる（§4.2 ②「3 件で最も明るい建物に」）。
            band(46, height - 26, C['timber_d'])
            for p in range(1, V, 4):
                stripe(p, p + 2, 46, height - 26, C['beam'])
            band(height - 28, height - 26, C['beam_l'])
            band(44, 46, C['beam_l'])
        elif variant == 3:
            #! 板扉（横桟の板戸）。
            band(36, height - 18, C['board'])
            for z in range(36, height - 18, 6):
                stripe(0, V, z, z + 2, C['board_d'])
            for p in (2, V - 4):
                stripe(p, p + 2, 36, height - 18, C['beam_l'])
        band(height - 12, height - 8, C['beam_l'])   # 上長押
        band(height - 8, height - 5, C['timber_d'])  # 軒下（垂木の影）
        #! 垂木の鼻（**朱を細く 1 本**。§4.2 の朱はここと幟だけ）。
        for p in range(1, V, 4):
            stripe(p, p + 2, height - 5, height - 2, C['shu'])
        band(height - 2, height, C['timber_d'])
        #! 柱は面の両端だけ（タイルするとマス境で 1 本になる）。
        for p in (0, V - 3):
            stripe(p, p + 3, 6, height, C['beam_l'])
    return [('main', v, (0, 0, 0))]


def manor_roofslope_myo(name):
    """**本瓦葺きの斜面 1 マス**（灰の瓦。`_n` = 軒が北 … 4 姿勢）。

    香霖堂の桟瓦（畝 6 vox）より**畝を太く**（8 vox）して、同じ灰でも
    「大伽藍の本瓦」に読ませる。1 マスで `MYO_RISE` 上がり、置く側が
    「マスごとの距離 × top_z」で積む。**型の総高は段の上がりぴったり**
    （高いとマスごとに返しが出来て屋根が自分の影に沈む＝デザイン9 の穴）。
    """
    words = _myo_words(name)  # manor roofslope|roofeave <side> [nn]
    side = words[2]
    eave = (words[1] == 'roofeave')
    rng = rng_for(name)
    ext = 12 if eave else 0        # 深い軒（大伽藍は軒の出が深い）
    along_x = side in ('w', 'e')
    if along_x:
        v = np.zeros((V + ext, V, MYO_RISE), np.uint8)
    else:
        v = np.zeros((V, V + ext, MYO_RISE), np.uint8)
    low_first = side in ('n', 'w')
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            a = x if along_x else y
            aa = a - ext if low_first else a
            cross = y if along_x else x
            ridge_line = (cross % 8) < 3
            if (aa < 0) or (aa >= V):
                #! 軒先。**z=0 に置かない**（マスの外なので接地すると footprint 照合が落ちる）。
                v[x, y, 1:4] = C['sanga_d']
                v[x, y, 3] = C['sanga_l'] if ridge_line else C['sanga']
                continue
            t = aa if low_first else (V - 1 - aa)
            surf = 2 + ((t * (MYO_RISE - 2)) // (V - 1))
            v[x, y, 0:surf] = C['sanga']
            v[x, y, surf - 1] = C['sanga_l'] if ridge_line else C['sanga']
            if (cross % 8) == 3:
                v[x, y, surf - 1] = C['sanga_d']   # 丸瓦の脇の影
    #! 苔（塊で 0〜2 か所。古刹なので香霖堂より少しだけ多く）。
    for _ in range(int(rng.integers(0, 4))):
        cx = int(rng.integers(0, max(1, v.shape[0] - 5)))
        cy = int(rng.integers(0, max(1, v.shape[1] - 5)))
        for x in range(cx, min(cx + int(rng.integers(3, 8)), v.shape[0])):
            for y in range(cy, min(cy + int(rng.integers(3, 8)), v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['sanga_g']
                        break
    if along_x:
        origin = (-ext if low_first else 0, 0, 0)
    else:
        origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_rooftop_myo(name):
    """平らな大棟 1 マス（段の上限に達したマス。斜面を並べると鋸歯になる）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, MYO_RISE), np.uint8)
    v[:, :, 0:MYO_RISE] = C['sanga']
    for x in range(V):
        v[x, :, MYO_RISE - 1] = C['sanga_l'] if ((x % 8) < 3) else C['sanga']
        if (x % 8) == 3:
            v[x, :, MYO_RISE - 1] = C['sanga_d']
    for _ in range(int(rng.integers(0, 3))):
        cx = int(rng.integers(0, V - 5))
        cy = int(rng.integers(0, V - 5))
        v[cx:cx + int(rng.integers(3, 7)), cy:cy + int(rng.integers(3, 7)), MYO_RISE - 1] \
            = C['sanga_g']
    return [('main', v, (0, 0, 0))]


def manor_ridge_myo(name):
    """**大棟**（`manor_ridge_myo` は東西へ通る棟・`_ns` は南北）。

    大伽藍の棟は太い。熨斗瓦を 4 段重ねて冠瓦を伏せ、**両端に鬼瓦は置かない**
    （型はマスごとに置かれるので、端だけの飾りは作れない）。高さは香霖堂の棟の 1.4 倍。
    """
    ns = ('ns' in _myo_words(name))
    long_, thick, h = V, 16, 20
    v = np.zeros((thick, long_, h) if ns else (long_, thick, h), np.uint8)

    def put(a0, a1, z0, z1, colour):
        if ns:
            v[a0:a1, :, z0:z1] = colour
        else:
            v[:, a0:a1, z0:z1] = colour

    put(0, thick, 1, 6, C['sanga_d'])        # 熨斗 1
    put(1, thick - 1, 6, 10, C['sanga'])     # 熨斗 2
    put(2, thick - 2, 10, 13, C['sanga_l'])  # 熨斗 3
    put(3, thick - 3, 13, 15, C['sanga'])    # 熨斗 4
    for a in range(4, thick - 4):
        half = abs(a - 7.5)
        top = 15 + int(5 - (half * half) // 3)
        put(a, a + 1, 15, max(16, top), C['sanga_l'])
    return [('main', v, (-8, 0, 0) if ns else (0, -8, 0))]


def manor_gable_myo(name):
    """**入母屋の破風 1 辺**（白漆喰の三角面＋木の破風板）。

    高さ 1 マスの型を置く側が sz で段の高さへ伸ばすので、**縦の要素だけ**で作る。
    寺の破風は白漆喰で塗り込め、縁だけ濃い木で締める。
    """
    side = _myo_words(name)[-1]
    th = 4
    v = np.zeros((V, V, V), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, C['myo_w'])
    put(0, 4, 0, V, C['beam_l'])          # 端の破風板
    put(V - 4, V, 0, V, C['beam_l'])
    for a in range(6, V - 6, 7):          # 縦の格子（木連格子は寺でも使う）
        put(a, a + 2, 0, V, C['beam'])
    put(0, V, V - 5, V, C['timber_d'])    # 上端の見切り
    put(0, V, V - 6, V - 5, C['sanga_d'])
    return [('main', v, (0, 0, 0))]


def nobori_myo(name):
    """**赤い幟**（§4.2 ③「奉納 毘沙門天王」の白字の赤旗が階段の両側に多数）。

    64px では字が潰れるので、**白い横線 2 本**で字の代わりにする（§4.2 の指示）。
    竿は 2.5 マス、布は竿の片側だけに垂れる。**風で揺れる**（`wind_k`。
    幟は境内でいちばん動くものなので、静止させると書き割りに見える）。
    """
    rng = rng_for(name)
    height = 80
    v = np.zeros((V, V, height), np.uint8)
    #! 竿と足元の石（マスの中央より少し寄せる。変種で左右に振る）。
    px = 10 + int(rng.integers(0, 8))
    v[px:px + 3, 14:17, 0:height] = C['beam_l']
    v[px - 2:px + 5, 12:19, 0:4] = C['flag_d']
    v[px - 1:px + 4, 13:18, 3:5] = C['flag']
    #! 布（竿の東側へ。幅 14・上から 8 vox 下がった所から）。
    top = height - 6
    v[px + 3:px + 17, 15:16, 20:top] = C['nobori']
    v[px + 3:px + 17, 15:16, top - 3:top] = C['nobori_d']
    #! 白い横線 2 本（字の代わり）。
    for z in (int(top * 0.62), int(top * 0.44)):
        v[px + 5:px + 15, 15:16, z:z + 4] = C['nuki']
    #! 横木（竿の頭）。
    v[px:px + 18, 14:17, top:top + 3] = C['beam']
    return [('main', v, (0, 0, 0))]


def jizou_myo(name):
    """**千体地蔵の 1 体**（§4.2「千体地蔵」。地図の孤立した 1 マスの壁 138 個がこれ）。

    丸い頭・肩の落ちた胴・蓮の台座の 3 段で読ませる（顔は彫らない——この縮尺では
    点が 2 つ並ぶだけで「目」に見えず、汚れに落ちる）。**赤い前掛け**を掛けた個体を
    混ぜる（変種 2 と 4）——境内に赤が点々と散るのが千体地蔵の記号である。
    """
    rng = rng_for(name)
    height = int(rng.integers(30, 40))
    v = np.zeros((V, V, height), np.uint8)
    cx = 16
    #! 台座（蓮弁の代わりに段を 2 つ）。
    v[cx - 7:cx + 7, cx - 7:cx + 7, 0:4] = C['ishi_d']
    v[cx - 6:cx + 6, cx - 6:cx + 6, 3:7] = C['ishi']
    #! 胴（上へすぼまる）。
    body = height - 9
    for z in range(6, body):
        t = (z - 6) / float(max(1, body - 6))
        r = int(round(5.5 - (t * 1.5)))
        v[cx - r:cx + r, cx - r:cx + r, z] = C['ishi']
        v[cx - r + 1:cx + r - 1, cx - r:cx - r + 1, z] = C['ishi_l']
    #! 頭（丸く。**肩より広く**——同じ太さで続けると、ただの石柱に見える）。
    hz = body + 3
    for z in range(body, min(height, hz + 5)):
        dz = abs(z - hz)
        r = max(1, int(round(5.0 - (dz * 0.7))))
        v[cx - r:cx + r, cx - r:cx + r, z] = C['ishi_l']
    #! 首（頭と胴の間を 1 段細く。これで頭が「載っている」に見える）。
    v[cx - 3:cx + 3, cx - 3:cx + 3, body - 1:body] = C['ishi_d']
    #! 赤い前掛け（変種 2・4 だけ。境内に散る赤の点）。
    #! **南面に掛ける**——北面は見下ろすカメラの背面で、1 画素も出ない（デザイン6 その2）。
    if int(name[-2:]) % 2 == 0:
        v[cx - 4:cx + 4, cx + 3:cx + 5, body - 9:body] = C['nobori']
        v[cx - 4:cx + 4, cx + 3:cx + 5, body - 3:body - 1] = C['nobori_d']
    #! 苔（根元だけ。古刹）。
    if rng.random() < 0.7:
        v[cx - 6:cx + 6, cx - 7:cx - 5, 0:3] = C['moss_d']
    return [('main', v, (0, 0, 0))]


def shourou_myo(name):
    """**鐘楼**（§4.2 ⑤「梵鐘は鳥居に次いで強い識別子」）。

    四本柱＋袴腰＋宝形の小屋根、中に黒い梵鐘。**屋敷の南西の外角に 1 つだけ**立つ
    （`TownStyle::corner_prop`）。マスの外へは出さない——1 マスに収める代わりに
    背を高く（3.4 マス）して、境内のどこからでも頭が見えるようにする。
    """
    height = 110
    v = np.zeros((V, V, height), np.uint8)
    #! 基壇（袴腰。石を積んで少し広げる）。
    v[2:30, 2:30, 0:8] = C['ishi_d']
    v[3:29, 3:29, 7:12] = C['ishi']
    v[4:28, 4:28, 11:13] = C['ishi_l']
    #! 四本柱（内へ傾ける代わりに太く）。
    for x0 in (6, 22):
        for y0 in (6, 22):
            v[x0:x0 + 4, y0:y0 + 4, 12:78] = C['beam_l']
    #! 頭貫と長押（柱を結ぶ横木。2 段）。
    for z in (44, 70):
        v[6:26, 6:10, z:z + 4] = C['beam']
        v[6:26, 22:26, z:z + 4] = C['beam']
        v[6:10, 6:26, z:z + 4] = C['beam']
        v[22:26, 6:26, z:z + 4] = C['beam']
    #! 梵鐘（黒い釣り鐘。肩は丸く、口は広い）。
    for z in range(30, 66):
        t = (z - 30) / 36.0
        r = int(round(9.0 - (t * t * 3.0)))
        v[16 - r:16 + r, 16 - r:16 + r, z] = C['kane']
    v[14:18, 14:18, 64:72] = C['kane_l']   # 竜頭（吊り手）
    v[8:24, 8:24, 30:32] = C['kane_l']     # 口の縁
    #! 宝形の小屋根（四方へ落ちる。頂に露盤）。
    for z in range(78, 104):
        r = int(round(16 - ((z - 78) * 0.52)))
        r = max(2, r)
        v[16 - r:16 + r, 16 - r:16 + r, z] = C['sanga']
        v[16 - r:16 + r, 16 - r:16 + r + 1, z] = C['sanga_l'] if ((z % 4) == 0) else C['sanga']
    v[13:19, 13:19, 103:108] = C['sanga_d']
    v[15:17, 15:17, 107:height] = C['gold']  # 宝珠
    return [('main', v, (0, 0, 0))]


def sanmon_myo(name):
    """**山門の柱 1 本**（§4.2 ④「瓦葺の山門を手前に一枚。**仁王像は入れない・鳥居も
    置かない**」）。南の塀の切れ目の**両脇**に 1 本ずつ立つ（`great_gate` ＋ `flank`）。

    2 本で 1 つの門に見えるよう、**屋根は切れ目の側へ長く張り出す**（マスの外へ 10 vox。
    接地しない高さなので footprint は 1 マスのまま）。`_ew` は東西にくぐる姿勢。
    """
    ew = name.endswith('_ew')
    ext = 10
    if ew:
        v = np.zeros((V + ext, V, 96), np.uint8)
        ox, oy = -ext, 0
    else:
        v = np.zeros((V, V + ext, 96), np.uint8)
        ox, oy = 0, -ext
    c0 = ext  # マスの始まり（張り出しの側）
    #! 礎石と柱（太い。門の柱は 1 マスの半分を占める）。
    if ew:
        v[c0 + 8:c0 + 24, 8:24, 0:6] = C['ishi_d']
        v[c0 + 10:c0 + 22, 10:22, 5:70] = C['beam_l']
        v[c0 + 12:c0 + 20, 12:20, 5:70] = C['beam']
    else:
        v[8:24, c0 + 8:c0 + 24, 0:6] = C['ishi_d']
        v[10:22, c0 + 10:c0 + 22, 5:70] = C['beam_l']
        v[12:20, c0 + 12:c0 + 20, 5:70] = C['beam']
    #! 冠木（門の横木。切れ目の側へ伸ばす）と、その上の瓦屋根。
    if ew:
        v[0:V + ext, 9:23, 62:70] = C['beam']
        for z in range(70, 88):
            r = int(round(14 - ((z - 70) * 0.6)))
            v[0:V + ext, 16 - r:16 + r, z] = C['sanga'] if (z % 3) else C['sanga_l']
        v[0:V + ext, 14:18, 87:92] = C['sanga_d']
    else:
        v[9:23, 0:V + ext, 62:70] = C['beam']
        for z in range(70, 88):
            r = int(round(14 - ((z - 70) * 0.6)))
            v[16 - r:16 + r, 0:V + ext, z] = C['sanga'] if (z % 3) else C['sanga_l']
        v[14:18, 0:V + ext, 87:92] = C['sanga_d']
    return [('main', v, (ox, oy, 0))]


def honden_myo(name):
    """**本堂の口**（`BUILDING_1`＝聖白蓮。本堂の**西面**のマス）。

    §4.2 の境内の構成から、口に置くのは**ゆるやかな石階段・向拝の柱・本坪鈴と綱**。
    **鳥居も注連縄も置かない**（神社と混ざる）。口は西へ開くので、見下ろすカメラでは
    縦の面が斜めに見える——だから**階段の天面**と**庇の天面**で読ませ、鈴だけを
    縦の面に吊る。
    """
    ext = 10
    v = np.zeros((V + ext, V, 78), np.uint8)
    c0 = ext  # マスの西端（local x）
    #! ゆるやかな石階段（西へ 3 段下りる。天面が顔）。
    for i, z in enumerate((10, 6, 2)):
        x0 = c0 - ((i + 1) * 3)
        v[max(0, x0):c0 + 2, 6:26, 0:z + 2] = C['ishi']
        v[max(0, x0):c0 + 2, 7:25, z:z + 2] = C['ishi_l']
    #! 土間（口の中）。
    v[c0:V + ext, 6:26, 0:5] = C['ishi_d']
    #! 向拝の柱 2 本（マスの西の際）。
    for y0 in (5, 24):
        v[c0 + 1:c0 + 5, y0:y0 + 4, 0:56] = C['beam_l']
        v[c0 + 1:c0 + 5, y0:y0 + 4, 0:4] = C['ishi_d']
    #! 頭貫と、深い庇（マスの外へ 10 vox。**天面が顔**）。
    v[c0 + 1:c0 + 5, 4:28, 50:56] = C['beam']
    for x in range(0, c0 + 8):
        t = 1.0 - (x / float(c0 + 7))
        z0 = 62 - int(round(t * 7))
        v[x:x + 1, 2:30, z0:z0 + 5] = C['sanga']
        v[x:x + 1, 2:30, z0 + 4:z0 + 5] = C['sanga_l']
    v[c0 + 6:c0 + 10, 2:30, 62:68] = C['sanga_d']   # 庇の付け根
    #! 本坪鈴と綱（縦の面の主役。鈴は真鍮・綱は白）。
    v[c0 - 1:c0 + 2, 14:18, 40:48] = C['gold']
    v[c0:c0 + 1, 15:17, 20:40] = C['nuki']
    #! 賽銭箱（階段の下。板の箱に格子の口）。
    v[c0 - 8:c0 - 1, 12:20, 0:9] = C['board']
    v[c0 - 8:c0 - 1, 12:20, 8:9] = C['timber_d']
    for y in range(13, 20, 2):
        v[c0 - 7:c0 - 2, y:y + 1, 8:10] = C['board_d']
    #! **マスの外は z=1 から**（接地がマスの外に出ると footprint の照合で落ちる＝時計塔の罠。
    #! 石段も賽銭箱も西へ張り出すので、いちばん下の層だけ剥がす）。
    v[0:c0, :, 0] = 0
    return [('main', v, (-ext, 0, 0))]


def shukubo_myo(name):
    """**宿坊の口**（`BUILDING_0`＝雲居一輪＆雲山。東の建物の**北面**）。

    北向きなので見下ろすカメラでは縦の面が背面になる——**顔は瓦の庇と沓脱石**。
    引き違いの障子戸と、軒に提灯を 1 つ（寺の宿なので朱ではなく生成りの紙）。
    """
    ext = 8
    v = np.zeros((V, V + ext, 62), np.uint8)
    c0 = ext  # マスの北端（local y）
    #! 三和土と沓脱石（天面が顔）。
    v[3:29, c0:c0 + 22, 0:5] = C['pack']
    v[11:22, c0 + 2:c0 + 12, 4:8] = C['ishi']
    #! 戸口の柱と鴨居。
    for x0 in (1, 27):
        v[x0:x0 + 4, c0 + 1:c0 + 5, 0:46] = C['beam_l']
    v[1:31, c0 + 1:c0 + 5, 40:46] = C['beam']
    #! 引き違いの障子（白い面 2 枚。桟は粗く）。
    for x0 in (5, 17):
        v[x0:x0 + 10, c0 + 2:c0 + 4, 6:40] = C['shoji']
        for z in range(8, 40, 8):
            v[x0:x0 + 10, c0 + 2:c0 + 4, z:z + 2] = C['beam']
        v[x0 + 4:x0 + 6, c0 + 2:c0 + 4, 6:40] = C['beam']
    #! 瓦の庇（マスの外へ。天面の顔）。
    for y in range(0, c0 + 6):
        t = 1.0 - (y / float(c0 + 5))
        z0 = 50 - int(round(t * 6))
        v[0:V, y:y + 1, z0:z0 + 4] = C['sanga']
        v[0:V, y:y + 1, z0 + 3:z0 + 4] = C['sanga_l']
    v[0:V, c0 + 4:c0 + 8, 50:54] = C['sanga_d']
    #! 軒の提灯（生成りの紙。夜の灯は置く側が乗せないので塗りだけ）。
    v[14:19, c0 - 3:c0 + 1, 34:44] = C['nuki']
    v[14:19, c0 - 3:c0 + 1, 38:40] = C['ink']
    return [('main', v, (0, -ext, 0))]


def _ground_path_myo(name):
    """**石畳の参道**（§4.2 ⑥「石畳の参道＋等間隔の石灯篭」。響子が掃除担当で
    綺麗に整備されている）。**切石を通し目地で敷く**——博麗の自然石（乱張り）とも
    香霖堂の轍の土とも違い、**目地がまっすぐ通る**ことが「整備されている」の記号。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['ishi_d']
    layer = np.zeros((V, V), np.uint8)
    #! 切石（8×16 の短冊を通し目地で）。
    for gy in range(0, V, 8):
        off = 0 if ((gy // 8) % 2 == 0) else 8
        for gx in range(-off, V, 16):
            x0 = max(0, gx)
            layer[x0:gx + 15, gy:gy + 7] = C['ishi'] if rng.random() < 0.7 else C['ishi_l']
    #! 目地（暗い線を通す）。
    for gy in range(0, V, 8):
        layer[:, gy:gy + 1] = C['ishi_d']
    _grain(rng, layer, layer > 0, [C['ishi_l'], C['moss_d']], [0.05, 0.04], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_turf_myo(name):
    """**境内の地面** — 掃き清めた砂利に苔。

    §4.2 の命蓮寺は「響子が掃除担当で綺麗に整備」されているので、**草を生やさない**
    （`tuft_chance` も低く取る）。白っぽい砂利を地にして、際にだけ苔を置く。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['grit']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['grit'], C['gravel_l'], C['gravel'], C['ishi_l']],
            [0.40, 0.24, 0.22, 0.14])
    #! 苔（塊で 1〜3 か所。掃き清めた砂利の際に残る）。
    for _ in range(int(rng.integers(1, 4))):
        x = int(rng.integers(0, V - 6))
        y = int(rng.integers(0, V - 6))
        layer[x:x + int(rng.integers(3, 6)), y:y + int(rng.integers(3, 6))] = C['moss_d']
    _grain(rng, layer, layer > 0, [C['pebble'], C['ishi']], [0.05, 0.04], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _rampart_tsuiji_myo(name):
    """**築地塀**（寺の塀。白漆喰の土塀に瓦の笠木）。

    §4.2 の境内は塀で囲われている。人里の土塀（`_jin`）と同じ構えだが、
    **白漆喰＋灰瓦**にして寺の色にする。塀の腹に**横の筋を 3 本**通すのは
    定規筋（格式のある寺の塀の印）で、これがあると土塀と見分けが付く。
    """
    rng = rng_for(name)
    height = 52
    v = np.zeros((V, V, height), np.uint8)
    v[:, :, 0:6] = C['ishi_d']          # 石の腰
    v[:, :, 5:6] = C['ishi']
    v[:, :, 6:height - 8] = C['myo_w']  # 白漆喰
    #! 定規筋（横の白い筋 3 本。地より 1 段明るく）。
    for z in (int(height * 0.42), int(height * 0.52), int(height * 0.62)):
        v[:, :, z:z + 2] = C['myo_wl']
    #! 塗りの斑（塊で）。
    for _ in range(int(rng.integers(1, 3))):
        x = int(rng.integers(0, V - 8))
        z = int(rng.integers(10, height - 18))
        v[x:x + 7, :, z:z + 6] = C['myo_wd']
    #! 瓦の笠木（両側へ落ちる小さな屋根）。
    v[:, :, height - 8:height - 5] = C['sanga_d']
    for i in range(3):
        v[:, i:V - i, height - 5 + i:height - 4 + i] = C['sanga'] if (i % 2 == 0) else C['sanga_l']
    return [('main', v, (0, 0, 0))]


def _watchtower_myo(name):
    """**塀の隅**（寺の塀に櫓は立たない）。控え柱を付けて少しだけ高くした築地塀の隅。"""
    v = np.zeros((V, V, 64), np.uint8)
    v[:, :, 0:7] = C['ishi_d']
    v[:, :, 6:56] = C['myo_w']
    for z in (26, 32, 38):
        v[:, :, z:z + 2] = C['myo_wl']
    #! 控え柱（南面へ 1 本）。
    v[12:20, V - 6:V, 0:50] = C['beam_l']
    v[:, :, 56:59] = C['sanga_d']
    for i in range(3):
        v[:, i:V - i, 59 + i:60 + i] = C['sanga'] if (i % 2 == 0) else C['sanga_l']
    return [('main', v, (0, 0, 0))]


def _house_roof_myo(name):
    """宿坊の屋根 — **灰の瓦**（旧地獄街道の黒瓦と同じ文法で、色だけ灰に振る）。"""
    return _house_roof_kawara(name, shades=(C['sanga'], C['sanga_l'], C['sanga_d'], C['sanga_g']))


# ---- 霧雨魔法店の意匠（デザイン11・2026-08-19）----
#
# §4.1 の外せない 1 点は「**急勾配の尖った洋風屋根**。瓦や入母屋を持ち込むと香霖堂と、
# 低い寄棟にすると里の民家と即座に混ざる」。9 スライスの寄棟では作れない（§3.5）ので、
# **屋敷の切妻**（デザイン6 で博麗の拝殿に作った距離段の切妻）で組み、1 段の上がりを
# **0.8 マス**まで起こす——同じ仕掛けで、値だけで「和の低い屋根」と「洋の尖った屋根」が
# 分かれる。屋根は**赤錆の板葺き**（§4.1 ②「暗色。**瓦のいぶし銀は使わない**」）。
KIR_WALL_H = 48   #!< 壁の高さ（1.5 マス）。**平屋＋屋根裏**（§4.1 の資料の食い違いの解）
KIR_RISE = 26     #!< 屋根 1 段の上がり（0.81 マス＝39°）。2 段で棟まで上がる


def _kir_words(name):
    return [p for p in name.split('_') if p != 'kir']


def manor_wall_kir(name):
    """**霧雨魔法店の壁 1 マス**（褪せた横板張り・高さ 1.5 マス）。

    §4.1 ③「壁は褪せた板張りの**横目**（`#8C7355` に褪色白を数段）」——人里の
    焼杉（竪羽目）とも土蔵の漆喰とも、**板の向きで**分かれる。

      - `_01` 板だけ……主
      - `_02` 窓（硝子に**山吹の灯**。§4.1 ⑤「明るい」を担保する）
      - `_03` **蔓の絡む面**（§4.1 ④。1 面だけ。古びの記号）
    """
    words = _kir_words(name)  # manor wall <slice> [nn]
    key = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    height = KIR_WALL_H
    v = np.zeros((V, V, height), np.uint8)
    #! 石の基礎（低く）と、暗い躯体。
    v[:, :, 0:4] = C['rub_d']
    v[:, :, 4:height] = C['timber_d']
    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in faces:
        vert = side in ('w', 'e')
        if side == 'n':
            fx, fy = slice(0, V), slice(0, 3)
        elif side == 's':
            fx, fy = slice(0, V), slice(V - 3, V)
        elif side == 'w':
            fx, fy = slice(0, 3), slice(0, V)
        else:
            fx, fy = slice(V - 3, V), slice(0, V)

        def band(z0, z1, colour):
            v[fx, fy, z0:z1] = colour

        def stripe(p0, p1, z0, z1, colour):
            if vert:
                v[fx, p0:p1, z0:z1] = colour
            else:
                v[p0:p1, fy, z0:z1] = colour

        #! 横板張り（4 vox ごとに 1 枚。**継ぎ目の影が横に走る**のがこの町の壁の記号）。
        band(4, height, C['kir_b'])
        for z in range(4, height, 4):
            band(z, z + 1, C['kir_bd'])
            band(z + 1, z + 2, C['kir_bl'] if ((z // 4) % 3 == 0) else C['kir_b'])
        #! 褪色（塊で 2〜3 か所。板 1 枚ぶんの幅で抜く）。
        for _ in range(int(rng.integers(2, 4))):
            a = int(rng.integers(0, V - 7))
            z = int(rng.integers(6, height - 10))
            stripe(a, a + 6, z, z + 4, C['kir_bl'])
        if variant == 2:
            #! 窓（硝子＋山吹の灯。枠は白く塗った木）。
            stripe(8, 24, 18, 36, C['cream'])
            stripe(10, 22, 20, 34, C['glass'])
            stripe(11, 21, 21, 33, C['lit'])
            stripe(15, 17, 20, 34, C['cream'])   # 桟（縦）
            stripe(10, 22, 26, 28, C['cream'])   # 桟（横）
        elif variant == 3:
            #! 蔓（§4.1 ④。下から絡んで上へ細る。**塊で置く**＝罠 38）。
            for _ in range(int(rng.integers(3, 6))):
                a = int(rng.integers(0, V - 4))
                top = int(rng.integers(20, height - 4))
                stripe(a, a + 3, 4, top, C['vine'])
                stripe(a + 1, a + 2, 4, top + 4, C['vine_d'])
            for _ in range(int(rng.integers(4, 8))):
                a = int(rng.integers(0, V - 5))
                z = int(rng.integers(6, height - 6))
                stripe(a, a + 4, z, z + 3, C['vine_d'])
        #! 隅柱（面の両端。白く塗った木＝洋風の羽目板の押さえ）。
        for p in (0, V - 3):
            stripe(p, p + 3, 4, height, C['cream_d'])
    return [('main', v, (0, 0, 0))]


def manor_roofslope_kir(name):
    """**急勾配の板葺き 1 マス**（`_n` = 軒が北 / `_s` = 軒が南）。

    1 マスで **KIR_RISE（26 vox＝0.81 マス）**上がる——和の屋根（永遠亭 14・命蓮寺 16）の
    倍近い。これが §4.1 の「**急勾配の尖った洋風屋根**」で、値だけで和洋が分かれる。

    葺きは**細長い板**（こけら板）。赤錆の色で、縁を 1 枚ずつ暗く落とす。
    `_02` の南面には**屋根裏の窓**（ドーマー）が付く——§4.1 の資料の食い違い
    （一階建て／上下 2 階）を「平屋＋屋根裏」で畳む道具である。
    """
    words = _kir_words(name)  # manor roofslope|roofeave <side> [nn]
    side = words[2]
    eave = (words[1] == 'roofeave')
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    rng = rng_for(name)
    ext = 8 if eave else 0
    v = np.zeros((V, V + ext, KIR_RISE), np.uint8)
    low_first = (side == 'n')
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            aa = (y - ext) if low_first else y
            if (aa < 0) or (aa >= V):
                v[x, y, 1:5] = C['kir_rd']
                v[x, y, 4] = C['kir_r']
                continue
            t = aa if low_first else (V - 1 - aa)
            surf = 2 + ((t * (KIR_RISE - 2)) // (V - 1))
            v[x, y, 0:surf] = C['kir_r']
            #! こけら板（流れに直交する細い段。4 vox ごと）。
            v[x, y, surf - 1] = C['kir_rl'] if ((t // 4) % 2 == 0) else C['kir_r']
            if (t % 4) == 0:
                v[x, y, surf - 1] = C['kir_rd']
            if (x % 7) == 0:
                v[x, y, surf - 1] = C['kir_rd']   # 板の継ぎ目（縦の線）
    #! 苔（北の面ほど多い。魔法の森は湿っている）。
    for _ in range(int(rng.integers(1, 4 if side == 'n' else 3))):
        cx = int(rng.integers(0, V - 5))
        cy = int(rng.integers(0, max(1, v.shape[1] - 5)))
        for x in range(cx, min(cx + int(rng.integers(3, 7)), V)):
            for y in range(cy, min(cy + int(rng.integers(3, 7)), v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['vine_d']
                        break
    #! **屋根裏の窓は軒のマスだけ**（デザイン11 その2 で改めた。上の `manor_roofslope_you`
    #! と同じ理由——斜面にも出すと出窓が段に積み重なる）。破風つきの小さな出窓。
    if eave and (variant == 2) and (side == 's'):
        #! **窓は南面に開ける**（デザイン11 その2 で直した）。初版は北の面に貼って
        #! いて、見下ろすカメラから 1 画素も見えず灰の箱にしか読めなかった。
        y0, y1 = V - 16, V - 4
        v[10:22, y0:y1, 0:KIR_RISE] = C['kir_r']
        v[11:21, y1 - 2:y1, 6:18] = C['cream']
        v[12:20, y1 - 2:y1, 7:17] = C['lit']
        v[9:23, y1 - 2:y1 + 2, 17:21] = C['kir_rd']
        v[10:22, y1:y1 + 2, 20:22] = C['kir_rl']
    origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_gable_kir(name):
    """**切妻の妻壁 1 辺**（板張りの三角面＋**丸い屋根裏窓**）。

    高さ 1 マスの型を置く側が sz で段の高さへ伸ばすので、**縦の要素だけ**で作る
    ——丸窓は伸縮で楕円になるが、この縮尺では「屋根裏に穴が 1 つ」で読める。
    """
    side = _kir_words(name)[-1]
    th = 4
    v = np.zeros((V, V, V), np.uint8)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, C['kir_b'])
    #! 竪羽目（妻だけ縦板にする。壁の横目との差で「妻」が読める）。
    for a in range(0, V, 5):
        put(a, a + 1, 0, V, C['kir_bd'])
    put(0, 3, 0, V, C['cream_d'])
    put(V - 3, V, 0, V, C['cream_d'])
    #! 丸い屋根裏窓（中央。硝子と山吹）。
    for a in range(11, 21):
        d = abs(a - 15.5)
        r = int(round(4.6 - (d * 0.55)))
        put(a, a + 1, 16 - r, 16 + r, C['glass'])
    for a in range(13, 19):
        put(a, a + 1, 14, 18, C['lit'])
    put(10, 22, 15, 17, C['cream'])
    put(0, V, V - 4, V, C['kir_rd'])   # 破風板
    return [('main', v, (0, 0, 0))]


def manor_ridge_kir(name):
    """**棟包み**（板葺きの頂を木で押さえる）。瓦の熨斗は使わない（§4.1 ②）。"""
    long_, thick, h = V, 10, 12
    v = np.zeros((long_, thick, h), np.uint8)
    v[:, 1:9, 1:7] = C['kir_rd']
    v[:, 2:8, 6:10] = C['timber_d']
    v[:, 3:7, 9:12] = C['kir_bl']
    for x in range(0, V, 6):
        v[x:x + 1, 2:8, 6:11] = C['timber']
    return [('main', v, (0, -5, 0))]


def mise_kir(name):
    """**霧雨魔法店の口**（`BUILDING_0`＝霧雨魔理沙。南面の彫り込みのマス）。

    口は**南へ開く**（地図の (74,40)。南隣が床）ので、見下ろすカメラの正面＝
    **縦の面がそのまま顔**になる。§4.1 の記号を全部ここへ:

      - 板の扉（洋風の開き戸。取っ手は鉄）と踏み段
      - **手書きの看板を傾けて 1 枚**（「なんかします」。64px で字にならないので
        白い板に黒い線 2 本。**傾いている**ことがこの看板の記号である）
      - 軒の吊り灯（山吹）と、戸口の外の道具の山
    """
    ext = 8
    v = np.zeros((V, V + ext, 62), np.uint8)
    #! 踏み段（板を 2 段。天面が見える）。
    v[8:24, V - 2:V + 4, 0:5] = C['kir_b']
    v[9:23, V + 1:V + 6, 0:3] = C['kir_bd']
    #! 戸口の枠（白く塗った木）。
    for x0 in (4, 24):
        v[x0:x0 + 4, V - 5:V - 1, 0:44] = C['cream_d']
    v[4:28, V - 5:V - 1, 40:46] = C['cream_d']
    #! 扉（板を縦に張った開き戸。取っ手は鉄）。
    v[8:24, V - 3:V - 1, 3:41] = C['kir_b']
    for x in range(9, 24, 3):
        v[x:x + 1, V - 3:V - 1, 3:41] = C['kir_bd']
    v[8:24, V - 3:V - 1, 20:22] = C['timber_d']
    v[21:23, V - 4:V - 1, 18:21] = C['iron_l']
    #! 板の庇（マスの外へ。天面の顔）。
    for y in range(V - 4, V + ext):
        t = (y - (V - 4)) / float(ext + 3)
        z0 = 52 - int(round(t * 8))
        v[0:V, y:y + 1, z0:z0 + 4] = C['kir_rd']
        v[0:V, y:y + 1, z0 + 3:z0 + 4] = C['kir_r']
    #! **傾いた手書き看板**（マスの外の柱に吊る。段ごとに 1 vox ずらして傾ける）。
    for i in range(12):
        z = 26 + i
        x0 = 3 + (i // 3)
        v[x0:x0 + 14, V + 4:V + 6, z:z + 1] = C['cream']
        if i in (4, 8):
            v[x0 + 2:x0 + 11, V + 4:V + 6, z:z + 1] = C['ink']
    v[2:4, V + 3:V + 6, 26:44] = C['timber_d']
    #! 軒の吊り灯（山吹。§4.1 ⑤「明るい」）。
    v[14:19, V + 1:V + 5, 44:50] = C['lit']
    v[15:18, V + 2:V + 4, 49:52] = C['iron']
    return [('main', v, (0, 0, 0))]


def odou_kir(name):
    """**寂れた小堂**（`BUILDING_2`＝矢田寺成美。地図の 5 マスの塊の口）。

    成美は**地蔵菩薩**なので、中に石仏を 1 体だけ据えた道端の小さな堂にする。
    「寂れた」ので屋根は苔だらけ、扉は外れて傾いている。北へ開く（地図の (56,16) の
    北隣が壁で、南の (56,17) が床）——**顔になるのは天面**なので、庇と屋根で読ませる。
    """
    ext = 6
    v = np.zeros((V, V + ext, 56), np.uint8)
    #! 石の基壇。
    v[4:28, V - 8:V + ext, 0:6] = C['rub']
    v[5:27, V - 7:V + ext - 1, 5:7] = C['rub_l']
    #! 堂の身（板張りの小さな箱。南面だけ開く）。
    v[6:26, V - 10:V - 2, 6:34] = C['kir_b']
    for z in range(6, 34, 4):
        v[6:26, V - 10:V - 2, z:z + 1] = C['kir_bd']
    v[9:23, V - 3:V - 2, 8:30] = C['dark']      # 開いた口（暗がり）
    #! 石仏（中に 1 体。頭を丸く）。
    v[13:19, V - 7:V - 3, 6:20] = C['ishi']
    for z in range(20, 26):
        r = max(1, int(round(3.6 - (abs(z - 22) * 0.7))))
        v[16 - r:16 + r, V - 6:V - 4, z] = C['ishi_l']
    v[12:20, V - 4:V - 3, 12:18] = C['nobori']  # 赤い前掛け
    #! 苔だらけの板の屋根（**寂れ**の記号）。棟は南北。
    for i in range(10):
        z = 34 + i
        w = 14 - i
        v[16 - w:16 + w, V - 12 + i // 2:V + ext - i // 2, z:z + 1] = C['kir_rd']
        if (i % 3) == 0:
            v[16 - w:16 + w, V - 12 + i // 2:V + ext - i // 2, z:z + 1] = C['vine_d']
    v[14:18, V - 8:V + 2, 44:47] = C['timber_d']
    #! 傾いて外れた扉（脇に立てかける）。
    for i in range(10):
        v[26:29, V - 6 + (i // 4):V - 4 + (i // 4), 6 + (i * 2):8 + (i * 2)] = C['kir_bd']
    return [('main', v, (0, -0, 0))]


def junk_kir(name):
    """**魔法の材料の山**（§4.1 ⑥「屋外に道具のガラクタが積まれている」）。

    香霖堂のガラクタ（外の世界の鉄と硝子）とは**中身を変える**——こちらは
    **瓶・茸・本・箒**で、拾い物ではなく**魔法の材料**である。箒は 1 山に 1 本だけ
    立てかける（魔理沙の記号）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 26), np.uint8)
    shades = [C['kir_b'], C['glass_l'], C['rub'], C['vine_d'], C['board_d']]
    for _ in range(int(rng.integers(4, 7))):
        w = int(rng.integers(6, 12))
        d = int(rng.integers(6, 12))
        x = int(rng.integers(1, max(2, V - w - 1)))
        y = int(rng.integers(1, max(2, V - d - 1)))
        z0 = int(rng.integers(0, 6))
        h = int(rng.integers(4, 9))
        v[x:x + w, y:y + d, z0:z0 + h] = shades[int(rng.integers(0, len(shades)))]
    #! 硝子の瓶を 2 つ（山吹の中身。夜でも点にならない程度に小さく）。
    for _ in range(2):
        x = int(rng.integers(3, V - 7))
        y = int(rng.integers(3, V - 7))
        top = int(v[x, y].nonzero()[0].max()) + 1 if v[x, y].any() else 0
        v[x:x + 4, y:y + 4, top:top + 6] = C['glass_l']
        v[x + 1:x + 3, y + 1:y + 3, top + 1:top + 4] = C['lit']
    #! 茸（魔法の森の材料）。
    for _ in range(int(rng.integers(1, 4))):
        x = int(rng.integers(2, V - 5))
        y = int(rng.integers(2, V - 5))
        v[x:x + 2, y:y + 2, 0:5] = C['bone']
        v[x - 1:x + 3, y - 1:y + 3, 4:7] = C['nobori_d']
    #! **箒**（1 本だけ立てかける。魔理沙の記号）。
    if int(name[-2:]) % 2 == 1:
        for i in range(18):
            v[6 + (i // 3):8 + (i // 3), 6:8, 2 + i] = C['timber']
        v[10:15, 5:10, 18:24] = C['hay']
    return [('main', v, (0, 0, 0))]


# ---- 魔法の森の 2 軒（デザイン11 その2・2026-08-20）----
#
# 町 10 の森には、中にクエストの口を 1 マスだけ抱えた solid な塊が 2 つある。初版は
# 「先方データの建物は 3 件だけだから家 2 軒は誤り」と見て岩の露頭にしようとしたが、
# **クエストの本文を当たると、どちらも名前のある家だった**:
#
#   北西 54 マス `u`(11,3)  … Quest20「鏡の国の怪物」＝**アリス・マーガトロイドの家**
#   北東 51 マス `s`(180,11) … Quest5「**森の幽霊洋館**」＝空き家（実は河童の倉庫）
#
# **どちらも洋館で、違うのは手入れの有無だけ**——同じ型を 2 つの材で作り、
# `_ari`（住んでいる）と `_yur`（朽ちている）で撃ち分ける。魔法店（`_kir`）の
# 褪せた板張り＋赤錆とは、**下見板と青灰のスレート**で分かれる。
YOU_WALL_H = KIR_WALL_H   #!< 壁の高さは魔法店と揃える（同じ森の同じ時代の建物）
YOU_RISE = KIR_RISE       #!< 屋根 1 段の上がりも同じ 39°（洋の急勾配）


def _you_words(name):
    """`manor_wall_ne_ari_02` → `('ari', 'ne', 2)`。`manor_gable_w_yur` → `('yur', 'w', 1)`。"""
    parts = name.split('_')
    kind = 'yur' if 'yur' in parts else 'ari'
    variant = int(parts[-1]) if parts[-1].isdigit() else 1
    skip = ('manor', 'wall', 'roofslope', 'roofeave', 'gable', 'ridge', 'ari', 'yur')
    body = [p for p in parts if (p not in skip) and (not p.isdigit())]
    return kind, (body[0] if body else 'mid'), variant


def _you_hues(kind):
    """材の 3 色ずつ（板・スレート）。**明度差ではなく彩度と緑で「朽ち」を出す**。"""
    if kind == 'ari':
        return dict(b=C['ari_b'], bl=C['ari_bl'], bd=C['ari_bd'],
                    r=C['ari_r'], rl=C['ari_rl'], rd=C['ari_rd'])
    return dict(b=C['yur_b'], bl=C['yur_bl'], bd=C['yur_bd'],
                r=C['yur_r'], rl=C['yur_rl'], rd=C['yur_rd'])


def manor_wall_you(name):
    """**森の洋館の壁 1 マス**（下見板・高さ 1.5 マス）。`_ari` は白、`_yur` は灰。

    魔法店の壁（`manor_wall_kir`）と**板の張り方で分かれる**——あちらは 4 vox ごとの
    横板張りで継ぎ目の影が横に走る。こちらは **3 vox ごとの下見板**（板を少しずつ
    重ねて張る洋の張り方）で、影の間隔が狭く、隅に**白く塗った太い隅柱**が立つ。

      - `_01` 板だけ……主
      - `_02` 窓。`ari` は**青い鎧戸の両開き**＋山吹の灯／`yur` は**板を斜めに打ちつけた窓**

    `yur` はさらに**板の抜け**（下地の躯体が覗く）と**蔦**が全面に入る。
    """
    kind, key, variant = _you_words(name)
    hue = _you_hues(kind)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    height = YOU_WALL_H
    #! **`np.int16`**（`reg_local` の索引は 1000 番台。uint8 には入らない）
    v = np.zeros((V, V, height), np.int16)
    #! 石の基礎と、暗い躯体（板が抜けたときに覗く色）。
    v[:, :, 0:4] = C['rub_d']
    v[:, :, 4:height] = C['timber_d']
    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in faces:
        vert = side in ('w', 'e')
        if side == 'n':
            fx, fy = slice(0, V), slice(0, 3)
        elif side == 's':
            fx, fy = slice(0, V), slice(V - 3, V)
        elif side == 'w':
            fx, fy = slice(0, 3), slice(0, V)
        else:
            fx, fy = slice(V - 3, V), slice(0, V)

        def band(z0, z1, colour):
            v[fx, fy, z0:z1] = colour

        def stripe(p0, p1, z0, z1, colour):
            if vert:
                v[fx, p0:p1, z0:z1] = colour
            else:
                v[p0:p1, fy, z0:z1] = colour

        #! **下見板**（3 vox ごとに 1 枚。板の下端に影が 1 本ずつ入る）。
        band(4, height, hue['b'])
        for z in range(4, height, 3):
            band(z, z + 1, hue['bd'])
        if kind == 'yur':
            #! 板の抜け（躯体が覗く）と、下から絡む蔦。**塊で置く**（罠 38）。
            for _ in range(int(rng.integers(2, 5))):
                a = int(rng.integers(0, V - 9))
                z = int(rng.integers(8, height - 10))
                stripe(a, a + 8, z, z + 3, C['timber_d'])
            for _ in range(int(rng.integers(3, 6))):
                a = int(rng.integers(0, V - 4))
                top = int(rng.integers(18, height - 6))
                stripe(a, a + 3, 4, top, C['vine'])
                stripe(a + 1, a + 2, 4, min(top + 5, height), C['vine_d'])
        else:
            #! 塗り直しの跡（板 2〜3 枚ぶんだけ白が明るい）。
            for _ in range(int(rng.integers(2, 4))):
                a = int(rng.integers(0, V - 7))
                z = int(rng.integers(6, height - 10))
                stripe(a, a + 6, z, z + 3, hue['bl'])
        if variant == 2:
            if kind == 'ari':
                #! 窓（白枠＋硝子＋山吹の灯）と、**青い鎧戸の両開き**。
                stripe(9, 23, 17, 35, C['cream'])
                stripe(11, 21, 19, 33, C['glass'])
                stripe(12, 20, 20, 32, C['lit'])
                stripe(15, 17, 19, 33, C['cream'])   # 桟（縦）
                stripe(11, 21, 25, 27, C['cream'])   # 桟（横）
                for a in (4, 23):
                    stripe(a, a + 5, 17, 35, C['ari_s'])
                    for z in range(18, 35, 4):
                        stripe(a, a + 5, z, z + 1, C['ari_sd'])
                stripe(9, 23, 35, 37, C['ari_sl'])   # 窓の上の水切り
            else:
                #! 割れた窓と、**斜めに打ちつけた板 2 枚**（空き家の記号）。
                stripe(9, 23, 17, 35, hue['bd'])
                stripe(11, 21, 19, 33, C['dark'])
                stripe(12, 15, 21, 27, C['glass'])   # 残った硝子の欠片
                stripe(17, 20, 26, 32, C['glass'])
                for k, z0 in ((0, 18), (1, 27)):
                    for i in range(18):
                        a = 7 + i
                        z = z0 + (i // 2 if k == 0 else -(i // 2)) + 4
                        if 4 <= z < (height - 2):
                            stripe(a, a + 1, z, z + 4, hue['b'])
        #! 隅柱（面の両端。**白く塗った太い柱**＝洋の羽目板の押さえ）。
        for p in (0, V - 4):
            stripe(p, p + 4, 4, height, C['cream_d'] if kind == 'ari' else C['rub_d'])
    return [('main', v, (0, 0, 0))]


def manor_roofslope_you(name):
    """**急勾配のスレート 1 マス**（`_n` = 軒が北 / `_s` = 軒が南）。

    上がりは魔法店と同じ **YOU_RISE（0.81 マス＝39°）**。葺きは**石板**（スレート）で、
    赤錆の板葺き（`_kir`）とは**色と目の細かさ**で分かれる——板は 4 vox の段、
    スレートは **3 vox の段＋縦の目地**である。

      - `ari` … 青灰の石板。`_02` の南面に**ドーマー**（屋根裏の窓。青い枠）
      - `yur` … 苔むした暗いスレート。`_02` の南面は**穴**が開き、垂木が覗く
    """
    kind, side, variant = _you_words(name)
    hue = _you_hues(kind)
    eave = ('roofeave' in name.split('_'))
    rng = rng_for(name)
    ext = 8 if eave else 0
    v = np.zeros((V, V + ext, YOU_RISE), np.int16)
    low_first = (side == 'n')
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            aa = (y - ext) if low_first else y
            if (aa < 0) or (aa >= V):
                v[x, y, 1:5] = hue['rd']
                v[x, y, 4] = hue['r']
                continue
            t = aa if low_first else (V - 1 - aa)
            surf = 2 + ((t * (YOU_RISE - 2)) // (V - 1))
            v[x, y, 0:surf] = hue['r']
            #! 石板の段（8 vox ごとに 1 本＝1 マスに 4 本）と、縦の目地（16 vox ごと）。
            #! **段と目地を細かく入れすぎると屋根が波板に見える**（デザイン6 その3 の
            #! 再演）——初版は 3 vox の段＋5 vox の目地＋明るい段で、引きの絵では
            #! 屋根一面が方眼紙になった（合成フレームで実測）。**目は粗いほうが石に見える。**
            if (t % 8) == 0:
                v[x, y, surf - 1] = hue['rd']
            if (x % 16) == 0:
                v[x, y, surf - 1] = hue['rd']
    #! 苔（北の面ほど多い。魔法の森は湿っている）。**`ari` はほとんど生やさない**
    #! ——住んでいる家の屋根に苔が点々と乗ると「手入れの有無」の対が壊れる。
    if kind == 'yur':
        tufts = int(rng.integers(1, 4 if side == 'n' else 3))
    else:
        tufts = int(rng.integers(0, 2 if side == 'n' else 1))
    for _ in range(tufts):
        cx = int(rng.integers(0, V - 5))
        cy = int(rng.integers(0, max(1, v.shape[1] - 5)))
        for x in range(cx, min(cx + int(rng.integers(3, 7)), V)):
            for y in range(cy, min(cy + int(rng.integers(3, 7)), v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['vine_d']
                        break
    #! **ドーマーと穴は軒のマスだけ**（デザイン11 その2）。斜面のマスにも出していたら
    #! 5 マス奥行きの家で**同じ出窓が 3 段に積み重なった**（合成フレームで実測）。
    #! 出窓は軒に載るものなので、これで数も位置も落ち着く。
    if eave and (variant == 2) and (side == 's'):
        #! **窓は南面に開ける。**初版は出窓の北の面に硝子を貼っていて、見下ろす
        #! カメラから 1 画素も見えず**灰の箱＝煙突**にしか読めなかった（実測）。
        #! デザイン6 その2 の可視の三法則の再演——南の軒の出窓は南を向く。
        y0, y1 = V - 16, V - 4
        if kind == 'ari':
            #! **ドーマー**（屋根裏の窓）。破風つきの小さな出窓を斜面から起こす。
            v[10:22, y0:y1, 0:YOU_RISE] = hue['r']
            v[11:21, y1 - 2:y1, 6:18] = C['cream']
            v[12:20, y1 - 2:y1, 7:17] = C['lit']
            v[9:23, y1 - 2:y1 + 2, 17:21] = C['ari_s']    # 破風（南へ 2 vox 出す）
            v[10:22, y1:y1 + 2, 20:22] = C['ari_sl']
        else:
            #! **屋根の穴**（垂木が覗く。空き家の記号。上から見て黒く抜ける）。
            #! **本当に抜く。**初版は天面から 3 vox だけ削っていて、下に葺きが残るので
            #! 「少し窪んだ明るい面」にしか見えなかった（実測）。柱を丸ごと落として
            #! 底に闇を置くと、上から見て**黒い穴**になる。
            for x in range(11, 23):
                for y in range(y0, y1):
                    if (abs(x - 16) + abs(y - ((y0 + y1) // 2))) > 7:
                        continue
                    v[x, y, :] = 0
                    v[x, y, 0:2] = C['dark']
            for x in range(12, 23, 4):
                v[x:x + 2, y0:y1, 0:3] = C['timber_d']   # 垂木
    origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_gable_you(name):
    """**切妻の妻壁 1 辺**（竪羽目の三角面＋丸い屋根裏窓）。

    高さ 1 マスの型を置く側が sz で伸ばすので、**縦の要素だけ**で作る。
    `ari` は白に青枠の丸窓、`yur` は板が 2 枚抜けて丸窓が割れている。
    """
    kind, side, _ = _you_words(name)
    hue = _you_hues(kind)
    rng = rng_for(name)
    th = 4
    v = np.zeros((V, V, V), np.int16)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, hue['b'])
    #! 竪羽目（妻だけ縦板。壁の下見板との差で「妻」が読める）。
    for a in range(0, V, 4):
        put(a, a + 1, 0, V, hue['bd'])
    put(0, 3, 0, V, C['cream_d'] if kind == 'ari' else C['rub_d'])
    put(V - 3, V, 0, V, C['cream_d'] if kind == 'ari' else C['rub_d'])
    if kind == 'yur':
        #! 板が抜けて躯体が覗く（2 枚ぶん）。
        for _ in range(2):
            a = int(rng.integers(2, V - 8))
            z = int(rng.integers(2, V - 8))
            put(a, a + 6, z, z + 4, C['timber_d'])
    #! 丸い屋根裏窓（中央）。
    for a in range(11, 21):
        d = abs(a - 15.5)
        r = int(round(4.6 - (d * 0.55)))
        put(a, a + 1, 16 - r, 16 + r, C['glass'] if kind == 'ari' else C['dark'])
    if kind == 'ari':
        for a in range(13, 19):
            put(a, a + 1, 14, 18, C['lit'])
        put(10, 22, 15, 17, C['ari_s'])          # 青い窓枠
    else:
        put(13, 16, 14, 17, C['glass'])          # 割れ残った硝子
    put(0, V, V - 4, V, hue['rd'])               # 破風板
    return [('main', v, (0, 0, 0))]


def manor_ridge_you(name):
    """**棟包み**。`ari` は鉛の板で押さえた棟、`yur` は苔むしてたわんだ棟。"""
    kind, _, _ = _you_words(name)
    hue = _you_hues(kind)
    long_, thick, h = V, 10, 12
    v = np.zeros((long_, thick, h), np.int16)
    v[:, 1:9, 1:7] = hue['rd']
    v[:, 2:8, 6:10] = C['steel_d'] if kind == 'ari' else C['vine_d']
    v[:, 3:7, 9:12] = hue['rl'] if kind == 'ari' else C['vine_d']
    for x in range(0, V, 5):
        v[x:x + 1, 2:8, 6:11] = hue['rd']
    if kind == 'yur':
        #! たわみ（真ん中が 2 vox 落ちる）と苔の塊。
        for x in range(10, 22):
            v[x, 1:9, 9:12] = 0
            v[x, 2:8, 7:9] = C['vine_d']
    return [('main', v, (0, -5, 0))]


def mon_ari(name):
    """**アリスの家の戸口**（Quest20「鏡の国の怪物」の口。`u`(11,3)）。

    彫り込みは**北面**——見下ろすカメラ（南から）には**縦の面が背中を向ける**ので、
    デザイン6 その2 の可視の三法則どおり**天面で読ませる**。白い切妻のポーチと
    青いスレート、その北へ降りる石段が顔になる。扉そのものはマスの南の縁に立てる
    （一人称で北から入るときにだけ正面に来る）。
    """
    ext = 8
    v = np.zeros((V, V + ext, 58), np.int16)
    south = ext + V   #!< マスの南の縁（＝家の壁）
    #! 扉（白い開き戸に青い枠。真鍮の握り）。
    v[6:26, south - 4:south - 1, 0:34] = C['cream_d']
    v[9:23, south - 3:south - 1, 0:30] = C['cream_l']
    for x in range(10, 23, 3):
        v[x:x + 1, south - 3:south - 1, 0:30] = C['cream']
    v[9:23, south - 4:south - 1, 30:34] = C['ari_s']
    v[20:22, south - 5:south - 2, 14:17] = C['gold']
    #! 扉の上の欄間（硝子。灯りが漏れる＝「住んでいる」の記号）。
    v[11:21, south - 3:south - 1, 34:39] = C['glass']
    v[12:20, south - 3:south - 1, 35:38] = C['lit']
    #! **ポーチの切妻屋根**（天面の顔）。マスの外へ 6 vox 出て、北へ向かって下がる。
    for y in range(2, south - 1):
        t = (south - 1 - y) / float(south - 3)
        z0 = 38 + int(round(t * 6))
        v[4:28, y:y + 1, z0:z0 + 3] = C['ari_r']
        v[4:28, y:y + 1, z0 + 2:z0 + 3] = C['ari_rl'] if ((y % 3) == 0) else C['ari_r']
    v[4:28, 2:4, 44:48] = C['cream']            # 破風（軒先の白い板）
    #! ポーチの柱 2 本（白）。
    for x0 in (5, 24):
        v[x0:x0 + 3, 3:6, 0:40] = C['cream_d']
    #! 石段 3 段（マスの外の北へ降りる。天面が見える）。
    for i in range(3):
        v[9 + i:23 - i, 2 + (i * 2):5 + (i * 2), 0:3 - i] = C['rub_l']
        v[9 + i:23 - i, 2 + (i * 2):3 + (i * 2), 0:3 - i] = C['rub']
    #! 青い玄関マット（段とポーチの間。上から見える 1 枚）。
    v[11:21, 9:15, 0:1] = C['ari_s']
    #! 鉢植えを 2 つ（青い花。アリスの家の手入れの記号）。
    for x0 in (2, 27):
        v[x0:x0 + 4, 6:10, 0:5] = C['mbr']
        v[x0:x0 + 4, 6:10, 5:8] = C['ari_sl']
        v[x0 + 1:x0 + 3, 7:9, 8:10] = C['fl_w']
    #! 吊りランプ（ポーチの下。山吹）。
    v[14:18, 6:10, 33:38] = C['lit']
    v[15:17, 7:9, 38:41] = C['iron']
    #! **マスの外へ北に出す部分は z=0 を空ける。**footprint の照合が、書き出す側
    #! （Python の `//`＝床除算）と読む側（C++ の `/`＝0 方向への切り捨て）で
    #! **負の原点のときだけ食い違う**——-8 // 32 = -1 に対し -8 / 32 = 0 である。
    #! 軒の型（`manor_roofeave_*`）が z=1 から始めているのはこのためで、同じ手を使う。
    v[:, 0:ext, 0] = 0
    return [('main', v, (0, -ext, 0))]


def mon_yur(name):
    """**森の幽霊洋館の戸口**（Quest5 の口。`s`(180,11)）。

    彫り込みは**南面**なので、見下ろすカメラに**正面から向く**——ここは縦の面が
    そのまま顔になる数少ない入口である。空き家の記号を全部立てる:
    板を斜めに打ちつけた扉・外れかけた庇・苔むした石段・割れたランプ。
    """
    ext = 8
    v = np.zeros((V, V + ext, 56), np.int16)
    #! 扉の枠（灰に朽ちた木）と、開いた暗がり。**壁より高くしない**——1.5 マスの
    #! 壁（`YOU_WALL_H`）より上へ出すと、軒の上に小屋が乗っているように見える（実測）。
    v[5:27, V - 5:V - 1, 0:38] = C['rub_d']
    v[8:24, V - 3:V - 1, 0:34] = C['dark']
    v[8:24, V - 4:V - 2, 0:34] = C['yur_bd']
    for x in range(9, 24, 3):
        v[x:x + 1, V - 4:V - 2, 0:34] = C['yur_b']
    #! **斜めに打ちつけた板 2 枚**（×に交差。空き家の記号）。
    for i in range(18):
        z = 6 + i
        v[6 + i:8 + i, V - 5:V - 2, z:z + 3] = C['yur_bl']
        v[25 - i:27 - i, V - 5:V - 2, z:z + 3] = C['yur_b']
    #! 蜘蛛の巣（枠の隅に 2 つ。細い線だけ）。
    for x0, z0 in ((6, 30), (24, 30)):
        for k in range(5):
            v[x0 - k if x0 > 16 else x0 + k, V - 4:V - 3, z0 - k] = C['cloth']
    #! 外れかけた庇（マスの外へ。片側が落ちている＝**傾き**が朽ちの記号）。
    for y in range(V - 4, V + ext):
        t = (y - (V - 4)) / float(ext + 3)
        z0 = 42 - int(round(t * 10))
        v[0:V, y:y + 1, z0:z0 + 3] = C['yur_rd']
        v[0:26, y:y + 1, z0 + 2:z0 + 3] = C['yur_r']
        v[26:V, y:y + 1, max(0, z0 - 6):z0 - 3] = C['yur_rd']   # 落ちた側
    for x in range(2, 26, 6):
        v[x:x + 2, V + 2:V + 4, 24:38] = C['vine_d']            # 庇に垂れる蔦
    #! 苔むした石段（2 段。天面に苔）。
    for i in range(2):
        v[8 + i:24 - i, V + (i * 2):V + 3 + (i * 2), 0:3 - i] = C['rub']
        v[8 + i:24 - i, V + (i * 2):V + 3 + (i * 2), 2 - i:3 - i] = C['vine_d']
    #! 割れたランプ（枠の脇。灯は入らない）。
    v[3:6, V - 4:V - 1, 28:34] = C['iron']
    v[3:6, V - 4:V - 1, 30:33] = C['glass']
    return [('main', v, (0, 0, 0))]


def doll_ari(name):
    """**上海人形**（アリスの家の戸口の脇に並ぶ。§ Quest20「家で人形を作ってたら」）。

    高さ 22 vox（0.7 マス）。**顔は彫らない**——この縮尺では点が 2 つ並ぶだけで
    汚れに落ちる（千体地蔵と同じ判断。デザイン10）。読ませるのは
    **金の髪・青と白の服・小さすぎる体**の 3 つである。
    """
    rng = rng_for(name)
    variant = int(name[-2:])
    v = np.zeros((V, V, 26), np.int16)
    cx = int(rng.integers(12, 20))
    cy = int(rng.integers(12, 20))
    base = 3 if variant == 3 else 0
    if variant == 3:
        #! 変種 3 は切株に腰かける（森の中の 1 体）。
        v[cx - 5:cx + 5, cy - 5:cy + 5, 0:3] = C['bark']
        v[cx - 4:cx + 4, cy - 4:cy + 4, 2:3] = C['log_end']
    #! ドレス（裾が広い。青と白）。
    for z in range(base, base + 10):
        r = 5 - ((z - base) // 3)
        v[cx - r:cx + r, cy - r:cy + r, z] = C['ari_s']
        if ((z - base) % 3) == 0:
            v[cx - r:cx + r, cy - r:cy + r, z] = C['cream_l']
    #! 胴と腕。
    v[cx - 2:cx + 2, cy - 2:cy + 2, base + 10:base + 15] = C['cream_l']
    v[cx - 4:cx - 2, cy - 1:cy + 1, base + 10:base + 14] = C['ari_sl']
    v[cx + 2:cx + 4, cy - 1:cy + 1, base + 10:base + 14] = C['ari_sl']
    #! 頭と金の髪（**髪がいちばん効く**——上から見て金の点になる）。
    v[cx - 3:cx + 3, cy - 3:cy + 3, base + 15:base + 20] = C['bone']
    v[cx - 3:cx + 3, cy - 3:cy + 3, base + 19:base + 22] = C['gold']
    v[cx - 4:cx + 4, cy - 4:cy + 4, base + 17:base + 20] = C['gold']
    if variant == 2:
        #! 変種 2 は青い帽子（つばを 1 段広く）。
        v[cx - 5:cx + 5, cy - 5:cy + 5, base + 21:base + 23] = C['ari_s']
        v[cx - 2:cx + 2, cy - 2:cy + 2, base + 22:base + 25] = C['ari_sd']
    return [('main', v, (0, 0, 0))]


def crate_yur(name):
    """**河童の木箱**（幽霊洋館の戸口の脇。Quest5 の決着「ここは河童たちの倉庫だった」）。

    アリスの家の人形と**同じ枠**（戸口の脇の 2 マス）に置くが、中身で家の性格が分かれる
    ——あちらは作りかけの人形、こちらは**運び込まれた荷**である。縄で縛った板の箱を
    2〜3 個、苔と割れた壺を添える。
    """
    rng = rng_for(name)
    variant = int(name[-2:])
    v = np.zeros((V, V, 26), np.uint8)
    boxes = 3 if variant == 1 else 2
    for i in range(boxes):
        w = int(rng.integers(9, 13))
        d = int(rng.integers(9, 13))
        x = int(rng.integers(1, max(2, V - w - 1)))
        y = int(rng.integers(1, max(2, V - d - 1)))
        z0 = 0 if i == 0 else int(rng.integers(6, 10))
        h = int(rng.integers(7, 10))
        v[x:x + w, y:y + d, z0:z0 + h] = C['board']
        #! 板の縁（木口を明るく）と、縄（十字に 1 本ずつ）。
        v[x:x + 1, y:y + d, z0:z0 + h] = C['board_d']
        v[x + w - 1:x + w, y:y + d, z0:z0 + h] = C['board_d']
        v[x:x + w, y:y + d, z0 + h - 1:z0 + h] = C['log_end']
        v[x + (w // 2):x + (w // 2) + 1, y:y + d, z0:z0 + h] = C['lash']
        v[x:x + w, y + (d // 2):y + (d // 2) + 1, z0 + h - 1:z0 + h] = C['lash']
        #! 苔（天面の隅に 1 か所）。
        v[x:x + 4, y:y + 4, z0 + h - 1:z0 + h] = C['vine_d']
    if variant == 2:
        #! 変種 2 は箱が 1 つ崩れ、割れた壺が転がる。
        v[2:9, 22:29, 0:4] = C['board_d']
        v[3:8, 23:28, 3:7] = C['rub']
        v[4:7, 24:27, 6:8] = C['dark']
    return [('main', v, (0, 0, 0))]


def _ground_turf_kir(name):
    """**魔法の森の下草** — 湿った苔に落ち葉と切株。

    §4.1 ⑦「建物の周りを 1〜2 マス伐開する（切株・明るい地面）」。地図が既に
    建物のまわりを草にしてあるので、**その草を「伐り開いた跡」に見せる**
    ——苔の地に切株の年輪を 1 つ置くマスを混ぜる。
    """
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['soil']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['moss'], C['moss_d'], C['turf_d'], C['soil']], [0.32, 0.30, 0.22, 0.16])
    #! 切株（5 マスに 1 つ。年輪を 2 本）。
    if rng.random() < 0.22:
        cx = int(rng.integers(6, V - 10))
        cy = int(rng.integers(6, V - 10))
        for x in range(cx - 5, cx + 6):
            for y in range(cy - 5, cy + 6):
                if ((x - cx) ** 2 + (y - cy) ** 2) <= 26:
                    layer[x, y] = C['kir_b']
                if 8 <= ((x - cx) ** 2 + (y - cy) ** 2) <= 14:
                    layer[x, y] = C['kir_bd']
    for _ in range(int(rng.integers(3, 7))):
        shade = C['wilt'] if rng.random() < 0.5 else C['wilt_d']
        x = int(rng.integers(0, V - 5))
        y = int(rng.integers(0, V - 5))
        layer[x:x + 4, y:y + 3] = shade
    _grain(rng, layer, layer > 0, [C['moss_d'], C['turf']], [0.06, 0.05], block=3)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_path_kir(name):
    """**踏み分け道** — 湿った土に轍と落ち葉。石は 1 つも敷かない（森の中の小道）。"""
    rng = rng_for(name)
    v = _tile(3)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['soil']
    layer = np.zeros((V, V), np.uint8)
    _mottle(rng, layer, [C['soil'], C['pack_d'], C['dirt_d'], C['moss_d']], [0.34, 0.28, 0.22, 0.16])
    for _ in range(2):
        x = int(rng.integers(5, V - 5))
        for y in range(V):
            layer[max(0, min(V - 1, x)), y] = C['dirt_d']
            layer[max(0, min(V - 1, x + 1)), y] = C['dirt_d']
            x += int(rng.integers(-1, 2))
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 5))
        y = 0 if rng.random() < 0.5 else V - 4
        layer[x:x + 4, y:y + 3] = C['wilt_d']
    _grain(rng, layer, layer > 0, [C['grit'], C['moss_d']], [0.05, 0.04], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _rampart_kuchi_kir(name):
    """**朽ちた板塀**（この町の塀の欠片）。板が抜け、蔓が絡んでいる。"""
    rng = rng_for(name)
    height = 40
    v = np.zeros((V, V, height), np.uint8)
    v[:, :, 0:4] = C['rub_d']
    for x0 in range(0, V, 6):
        top = int(rng.integers(height - 10, height))
        if rng.random() < 0.18:
            continue   # 板が 1 枚抜けている
        v[x0:x0 + 5, 12:20, 3:top] = C['kir_b']
        v[x0:x0 + 1, 12:20, 3:top] = C['kir_bd']
        v[x0:x0 + 5, 12:20, top - 2:top] = C['kir_bl']
    for z in (14, 30):
        v[:, 13:19, z:z + 3] = C['kir_bd']
    if rng.random() < 0.7:
        x = int(rng.integers(0, V - 6))
        v[x:x + 5, 11:21, 3:int(rng.integers(16, 34))] = C['vine_d']
    return [('main', v, (0, 0, 0))]


# ---- 廃洋館の意匠（デザイン12・2026-08-20）----
#
# 町 11 は **森の廃洋館（プリズムリバー邸）**。§4.3 の外せない 1 点は
# 「**上辺が欠けた非対称シルエット＋黒く抜けた窓。彩度が最も低い**」で、
# 紅魔館（唯一の赤・時計塔）の**正反対**へ振ることで洋館 2 件が分かれる。
#
# 壁の塊は **793 マス・49×20・充填 0.81** の 1 枚岩なので、屋敷として読み
# **距離変換の屋根**（`manor_roof_irimoya`）で組む——四方の軒から 4 段上がり、
# 頂は**平らな鉛の陸屋根**（マンサール）になる。その陸屋根を 2×2 マスの塊で抜くのが
# 「上辺の欠け」である（`manor_roof_scar`）。
HAI_WALL_H = 128  #!< 壁の高さ（4 マス＝2 階建て）。紅魔館の 6 マスより**低く長く**
HAI_RISE = 22     #!< 屋根 1 段の上がり（0.69 マス＝35°）。4 段＝2.75 マスで陸屋根へ抜ける
#! **壁 4 マスより屋根を低く**保つ（初版は 1.125 マス／段＝屋根だけで 4.5 マスあり、
#! 見下ろしのカメラでは**屋根が壁を隠して**「黒く抜けた窓」が 1 つも見えなかった＝実測）。


def _hai_words(name):
    """`manor_wall_ne_hai_02` → `['manor', 'wall', 'ne', '02']`。"""
    return _split_style(name)[1].split('_')


def _hai_ashlar(v, fx, fy, vertical, z0, z1, rng, course=16):
    """**切石積みの面**（8 vox の段＋目地の線）。廃墟なので石ごとの色差を大きく取る。"""
    for z in range(z0, z1, course):
        for p in range(0, V, 10):
            a0, a1 = p, min(p + 9, V)
            shade = rng.choice([C['hai_w'], C['hai_wl'], C['hai_wd']], p=[0.74, 0.13, 0.13])
            if vertical:
                v[fx, a0:a1, z:min(z + course - 1, z1)] = shade
            else:
                v[a0:a1, fy, z:min(z + course - 1, z1)] = shade
        if (z + course - 1) < z1:
            if vertical:
                v[fx, :, z + course - 1] = C['hai_wd']
            else:
                v[:, fy, z + course - 1] = C['hai_wd']


def manor_wall_hai(name):
    """**廃洋館の壁 1 マス**（退色した灰白の切石・高さ 4 マス＝2 階）。

    §4.3 の ②③④ をそのまま置く:
      - 壁は**退色した灰白**（`#A8A49B`）。紅魔館の紅の真逆で、**彩度は全町で最低**
      - **窓は黒く抜く**（`#1C1E22`）。**灯を入れない**——「人が住んでいない」が
        遠目で読める唯一の手なので、山吹の灯（`_kir` / `_ari`）は 1 つも置かない
      - **蔓を壁の下半分に**（`#4A6B3C`）

    変種は置く側が**列で**選ぶ（ベイの律動 `{0,1,0,2}`＝無地・窓・無地・板打ち）。
      - `_01` 無地＋蔓……主
      - `_02` **黒い縦長窓 2 段**（1 階・2 階。石の枠だけが明るい）
      - `_03` **板を打ちつけた窓**と、石の抜けた崩れ
    """
    words = _hai_words(name)  # manor wall <slice> [nn]
    key = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    h = HAI_WALL_H
    #! **`np.int16`**（`reg_local` の索引は 1000 番台。uint8 には入らない）
    v = np.zeros((V, V, h), np.int16)
    #! 地覆の石と、内側の躯体（屋根の下は暗い）。
    v[:, :, 0:10] = C['hai_wd']
    v[:, :, 10:h] = C['rub_d']
    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in faces:
        vertical = side in ('w', 'e')
        if side == 'n':
            fx, fy = slice(0, V), slice(0, 4)
        elif side == 's':
            fx, fy = slice(0, V), slice(V - 4, V)
        elif side == 'w':
            fx, fy = slice(0, 4), slice(0, V)
        else:
            fx, fy = slice(V - 4, V), slice(0, V)

        def stripe(p0, p1, z0, z1, colour, _fx=fx, _fy=fy, _vert=vertical):
            if _vert:
                v[_fx, p0:p1, z0:z1] = colour
            else:
                v[p0:p1, _fy, z0:z1] = colour

        _hai_ashlar(v, fx, fy, vertical, 0, h, rng)
        #! 基礎の粗石・階を分ける帯石・頂のコーニス。
        stripe(0, V, 0, 10, C['hai_wd'])
        stripe(0, V, 60, 64, C['hai_wl'])
        stripe(0, V, h - 8, h - 4, C['hai_wl'])
        stripe(0, V, h - 4, h, C['hai_wd'])
        if variant in (2, 3):
            #! **柱間（ベイ）を 2 vox 彫り込む。**置く側は列で変種を選ぶ（`{0,1,0,2}`）ので、
            #! 窓のマスだけ面を後退させると**無地のマスが付け柱として立つ**——初版は面が
            #! 平らなまま横目地だけが通り、49 マスの正面が**兵舎の縞**に見えた（実測）。
            stripe(5, 27, 10, h - 10, 0)
            #! **縦長の窓を 2 段**（1 階 z20..50・2 階 z76..106）。中は真っ黒・方立は入れない
            #! （1 マス幅のマスでは細い桟が潰れて「稲妻」に見えた＝実測）。
            for z0, z1 in ((20, 50), (76, 106)):
                stripe(8, 24, z0 - 3, z1 + 4, C['hai_wd'])   # 石の見込み（枠の奥）
                stripe(10, 22, z0, z1, C['hai_k'])           # 黒い開口
                stripe(9, 23, z1 + 3, z1 + 6, C['hai_wl'])   # 楣
                stripe(9, 23, z0 - 4, z0 - 1, C['hai_wl'])   # 台輪
            if variant == 3:
                #! **板を打ちつけた窓**（1 階だけ。斜めに 2 枚）と、石の抜けた崩れ。
                for i in range(14):
                    z = 22 + (i * 2)
                    stripe(9 + i, 11 + i, z, z + 5, C['timber_d'])
                    stripe(23 - i, 25 - i, z, z + 5, C['rub_d'])
                a = int(rng.integers(2, V - 10))
                z = int(rng.integers(88, h - 22))
                stripe(a, a + 8, z, z + 12, C['hai_k'])
                stripe(a + 1, a + 7, z + 1, z + 6, C['rub_d'])
        #! **蔓**（壁の下半分。§4.3 ④）。**塊で・数を絞って**這わせる——4 vox の細い筋を
        #! 5 本入れた初版は、一人称で**緑の縦縞が全ベイに並んで柱のように**見えた（実測）。
        #! 幅を 5〜9 vox に太らせ、本数を 0〜3 に落として、蔓の無いマスを作る。
        for _ in range(int(rng.integers(0, 3 if variant == 2 else 4))):
            wide = int(rng.integers(5, 10))
            a = int(rng.integers(0, V - wide - 1))
            top = int(rng.integers(20, 72))
            stripe(a, a + wide, 4, top, C['hai_v'])
            stripe(a + 1, a + wide - 1, 4, min(top + 10, h), C['hai_vd'])
        #! 雨垂れの汚れ（コーニスから下へ 2 本）。
        for _ in range(2):
            a = int(rng.integers(0, V - 3))
            stripe(a, a + 2, int(rng.integers(60, 100)), h - 8, C['hai_wd'])
    return [('main', v, (0, 0, 0))]


def manor_roofslope_hai(name):
    """**青灰のスレートの斜面 1 マス**（`_n` / `_s` / `_w` / `_e` の 4 姿勢）。

    1 マスで **HAI_RISE（36 vox ＝ 1.125 マス）**上がる急勾配。葺きは石板で、
    段は **8 vox**・縦の目地は **16 vox**——デザイン11 その2 の教訓
    （細かく入れると屋根が方眼紙になる）をそのまま守る。

    `manor_roofeave_*` は軒のマス（段 0）用で、軒側へ 10 vox 出て**鉛の樋**が付く。
      - `_01` 素……主
      - `_02` **スレートが剥げて野地板が覗く**（穴は開けない——本当の抜けは
        陸屋根の崩落〔`manor_roofscar_hai`〕が受け持つ）
      - `_03` 苔の乗った段（軒だけ）
    """
    words = _hai_words(name)  # manor roofslope|roofeave <side> [nn]
    side = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    eave = (words[1] == 'roofeave')
    rng = rng_for(name)
    ext = 10 if eave else 0
    along_x = side in ('w', 'e')
    if along_x:
        v = np.zeros((V + ext, V, HAI_RISE + 2), np.int16)
    else:
        v = np.zeros((V, V + ext, HAI_RISE + 2), np.int16)
    low_first = side in ('n', 'w')
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            a = x if along_x else y
            aa = (a - ext) if low_first else a
            if (aa < 0) or (aa >= V):
                #! 軒先と**鉛の樋**。z=0 には置かない（マスの外へ張り出す型の約束）。
                v[x, y, 1:5] = C['hai_ld']
                v[x, y, 4] = C['hai_l']
                if (aa < -4) or (aa >= V + 4):
                    v[x, y, 5:8] = C['hai_l']
                continue
            t = aa if low_first else (V - 1 - aa)
            surf = 3 + ((t * (HAI_RISE - 3)) // (V - 1))
            v[x, y, 0:surf] = C['hai_r']
            #! 石板の段（**16 vox ごと＝1 マスに 2 本**）と縦の目地（16 vox ごと）。
            #! **目は粗いほうが石に見える**——初版は 8 vox ごとで、引きの絵では
            #! 屋根一面が**波トタンの横縞**に見えた（合成フレームで実測）。
            b = y if along_x else x
            if (t % 16) == 0:
                v[x, y, surf - 1] = C['hai_rd']
            if (b % 16) == 0:
                v[x, y, surf - 1] = C['hai_rd']
    #! **剥げ**（変種 3 だけ）。野地板が覗く帯を 1 枚。天面の 1 段だけ差し替える。
    #! **変種の半分を剥げにしてはならない**——初版は 2 変種のうち 1 枚がこれで、
    #! 屋根一面に茶色の斑が水玉に散った（実測）。3 枚に 1 枚・1 か所に薄める。
    if variant == 3:
        for _ in range(1):
            cx = int(rng.integers(0, max(1, v.shape[0] - 7)))
            cy = int(rng.integers(0, max(1, v.shape[1] - 7)))
            for x in range(cx, min(cx + 6, v.shape[0])):
                for y in range(cy, min(cy + 6, v.shape[1])):
                    for z in range(v.shape[2] - 1, -1, -1):
                        if v[x, y, z]:
                            v[x, y, z] = C['timber_d']
                            break
    #! 苔（北の面ほど多い。**廃墟なので `_yur` より濃い**）。
    #! **マスごとに 1〜2 個も生やさない**（初版は全マスに緑の点が乗って屋根が斑になった）。
    tufts = int(rng.integers(0, 3)) if (side == 'n') else int(rng.integers(0, 2))
    for _ in range(tufts):
        cx = int(rng.integers(0, max(1, v.shape[0] - 6)))
        cy = int(rng.integers(0, max(1, v.shape[1] - 6)))
        for x in range(cx, min(cx + int(rng.integers(3, 7)), v.shape[0])):
            for y in range(cy, min(cy + int(rng.integers(3, 7)), v.shape[1])):
                for z in range(v.shape[2] - 1, -1, -1):
                    if v[x, y, z]:
                        v[x, y, z] = C['hai_vd']
                        break
    if along_x:
        origin = (-ext if low_first else 0, 0, 0)
    else:
        origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_rooftop_hai(name):
    """**平らな鉛の陸屋根 1 マス**（マンサールの頂）。総高は `HAI_RISE`。

    鉛板は継ぎ目を巻く（ロール葺き）ので、16 vox ごとに 1 本の高い筋が走る。
    廃墟なので苔と落ち葉が溜まる。崩落（`manor_roofscar_hai`）はこの面を
    2×2 マスの塊で抜く。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, HAI_RISE), np.int16)
    v[:, :, 0:HAI_RISE] = C['hai_ld']
    v[:, :, HAI_RISE - 2:HAI_RISE] = C['hai_l']
    #! 鉛のロール（南北に走る。16 vox ごとに高い筋）。
    for x in range(0, V, 16):
        v[x:x + 3, :, HAI_RISE - 1:HAI_RISE] = C['hai_ll']
        v[x + 1:x + 2, :, HAI_RISE - 1:HAI_RISE] = C['hai_l']
    #! 苔と落ち葉（塊で 2〜4 か所）。
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 7))
        y = int(rng.integers(0, V - 7))
        shade = C['hai_vd'] if rng.random() < 0.6 else C['hai_lf']
        v[x:x + int(rng.integers(4, 8)), y:y + int(rng.integers(4, 8)), HAI_RISE - 1] = shade
    #! 落ちたスレートの欠片。
    for _ in range(int(rng.integers(0, 3))):
        x = int(rng.integers(0, V - 6))
        y = int(rng.integers(0, V - 6))
        v[x:x + 5, y:y + 3, HAI_RISE - 1] = C['hai_rd']
    return [('main', v, (0, 0, 0))]


def manor_roofscar_hai(name):
    """**陸屋根の崩落 1 マス**（デザイン12 の外せない 1 点）。

    §4.3「**上辺が欠けた非対称シルエット**」。置く側は **2×2 マスの塊**の種で
    ここを選ぶので、4 マスまとまって抜ける——マスごとに散らすと方眼に穴が開く（罠 38）。

    **本当に抜く**（デザイン11 その2 の教訓）。天面を少し削るだけでは
    「窪んだ明るい面」にしか見えないので、柱を丸ごと落として**底に闇を置く**。
    残るのは縁のわずかな鉛と、**折れた小屋組の梁**である。
    """
    variant = int(name.rsplit('_', 1)[1])
    rng = rng_for(name)
    v = np.zeros((V, V, HAI_RISE), np.int16)
    #! 底の闇（これが「黒い穴」の実体）。
    v[:, :, 0:2] = C['dark']
    #! 縁に残った鉛（辺を 1〜2 つだけ。変種ごとに残る辺が違う）。
    edges = [('n', 0), ('s', V - 5), ('w', 0), ('e', V - 5)]
    rng.shuffle(edges)
    for side, a0 in edges[:int(rng.integers(1, 3))]:
        lip = int(rng.integers(3, 6))
        if side in ('n', 's'):
            v[:, a0:a0 + lip, 0:HAI_RISE] = C['hai_ld']
            v[:, a0:a0 + lip, HAI_RISE - 2:HAI_RISE] = C['hai_l']
        else:
            v[a0:a0 + lip, :, 0:HAI_RISE] = C['hai_ld']
            v[a0:a0 + lip, :, HAI_RISE - 2:HAI_RISE] = C['hai_l']
    #! 折れた小屋組の梁（2〜3 本。穴の上に架かって残る）。
    for i in range(2 + (variant % 2)):
        z = 8 + (i * 7)
        a = int(rng.integers(2, V - 8))
        if rng.random() < 0.5:
            v[a:a + 5, 0:V, z:z + 4] = C['timber_d']
            if rng.random() < 0.5:
                v[a:a + 5, int(rng.integers(6, V - 10)):V, z:z + 4] = 0
        else:
            v[0:V, a:a + 5, z:z + 4] = C['timber_d']
            if rng.random() < 0.5:
                v[0:int(rng.integers(8, V - 6)), a:a + 5, z:z + 4] = 0
    #! 落ちたスレートと石屑（底に少し。真っ黒だけだと穴が板に見える）。
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 6))
        y = int(rng.integers(0, V - 6))
        v[x:x + 5, y:y + 4, 1:3] = C['hai_rd'] if rng.random() < 0.6 else C['rub_d']
    return [('main', v, (0, 0, 0))]


def manor_gable_hai(name):
    """**段差を塞ぐ石の面 1 辺**（破風にあたる）。高さ 1 マスを置く側が sz で伸ばす。

    伸縮するので**横の段は入れない**（伸ばすと段が間延びする）——縦の目地と
    隅石（quoin）だけで石に見せる。中央に**塞がれた明り取り**（黒）を 1 つ。
    """
    words = _hai_words(name)  # manor gable <side>
    side = words[2]
    rng = rng_for(name)
    th = 4
    v = np.zeros((V, V, V), np.int16)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, C['hai_w'])
    for a in range(0, V, 8):
        if rng.random() < 0.4:
            put(a + 1, a + 8, 0, V, C['hai_wl'] if rng.random() < 0.5 else C['hai_wd'])
        put(a, a + 1, 0, V, C['hai_wd'])
    put(0, 4, 0, V, C['hai_wl'])
    put(V - 4, V, 0, V, C['hai_wl'])
    #! 塞がれた明り取り（黒。灯は入れない）。
    put(12, 20, 10, 24, C['hai_wd'])
    put(13, 19, 12, 22, C['hai_k'])
    #! 蔓（1 本）。
    a = int(rng.integers(5, V - 8))
    put(a, a + 3, 0, int(rng.integers(10, 26)), C['hai_vd'])
    return [('main', v, (0, 0, 0))]


def manor_ridge_hai(name):
    """**鉛の棟包みと鉄の飾り**（`manor_ridge_hai` は東西・`_ns` は南北）。

    洋館の棟には**鉄の棟飾り**（クレスティング）が載る。廃墟なので**歯が抜けている**
    ——ここも「上辺が欠けた」の一部である。
    """
    ns = _split_style(name)[1].endswith('_ns')
    rng = rng_for(name)
    long_, thick, h = V, 12, 22
    v = np.zeros((thick, long_, h) if ns else (long_, thick, h), np.int16)

    def put(a0, a1, t0, t1, z0, z1, colour):
        if ns:
            v[t0:t1, a0:a1, z0:z1] = colour
        else:
            v[a0:a1, t0:t1, z0:z1] = colour

    put(0, V, 1, 11, 1, 8, C['hai_rd'])
    put(0, V, 2, 10, 7, 11, C['hai_l'])
    put(0, V, 3, 9, 10, 12, C['hai_ll'])
    #! 鉄の棟飾り（3 vox ピッチの槍先。3 本に 1 本ほど欠ける）。
    for a in range(1, V - 1, 3):
        if rng.random() < 0.34:
            continue
        top = 12 + int(rng.integers(5, 9))
        put(a, a + 2, 5, 7, 11, top, C['hai_ru'])
        put(a, a + 2, 5, 7, top, top + 2, C['hai_rud'])
    return [('main', v, (-5, 0, 0) if ns else (0, -5, 0))]


def mon_hai(name):
    """**廃洋館の玄関**（`BUILDING_0`＝「洋館に入る」。`a`(72,29) の彫り込み）。

    彫り込みは**西面**——見下ろすカメラ（南から）には斜めにしか見えないので、
    **天面（ポーチの屋根）と西へ降りる石段**の 2 つで読ませる。扉は**半開き**で、
    中は真っ黒に抜く（灯を入れない＝「無人」の記号）。
    """
    ext = 8
    rng = rng_for(name)
    v = np.zeros((V + ext, V, 104), np.int16)
    east = ext + V   #!< マスの東の縁（＝館の壁）
    #! 扉の枠（石の縁取り）と、開いた暗がり。**壁より高くしない。**
    v[east - 6:east - 1, 4:28, 0:76] = C['hai_wl']
    v[east - 5:east - 1, 7:25, 0:70] = C['hai_k']
    #! 両開きの扉——片方は蝶番が外れて**傾いて**いる（廃墟の記号）。
    for y0, tilt in ((7, 0), (16, 3)):
        for i in range(9):
            z0 = (tilt * i) // 3
            shade = C['hai_wd'] if ((i % 3) == 0) else C['timber_d']
            v[east - 4:east - 2, y0 + i:y0 + i + 1, z0:z0 + 62] = shade
    v[east - 4:east - 2, 15:17, 0:70] = C['hai_ru']
    #! 扉の上の欄間（**黒。硝子は残っていない**）。
    v[east - 5:east - 1, 9:23, 70:80] = C['hai_k']
    v[east - 6:east - 1, 8:24, 79:83] = C['hai_wl']
    #! **ポーチ（車寄せ）の屋根**——天面の顔。マスの外（西）へ出て、西へ下がる。
    for x in range(2, east - 1):
        t = (east - 1 - x) / float(east - 3)
        z0 = 84 + int(round(t * 8))
        v[x:x + 1, 2:30, z0:z0 + 3] = C['hai_r']
        if (x % 8) == 0:
            v[x:x + 1, 2:30, z0 + 2:z0 + 3] = C['hai_rd']
    v[2:6, 2:30, 88:94] = C['hai_wl']
    #! ポーチの石柱 2 本（西の両端）。**片方は上が欠けている。**
    for y0, top in ((3, 86), (25, 78)):
        v[3:9, y0:y0 + 5, 0:top] = C['hai_w']
        v[4:8, y0 + 1:y0 + 4, 0:top] = C['hai_wl']
        if top < 84:
            v[3:9, y0:y0 + 5, top:top + 3] = C['rub_d']
    #! 石段 3 段（マスの外の西へ降りる。**縁が欠けている**）。
    for i in range(3):
        x0 = 2 + (i * 2)
        v[x0:x0 + 3, 8 + i:26 - i, 1:4 - i] = C['hai_wd']
        v[x0:x0 + 3, 8 + i:26 - i, 3 - i:4 - i] = C['hai_w']
        if rng.random() < 0.7:
            a = int(rng.integers(9, 22))
            v[x0:x0 + 3, a:a + 4, 1:4 - i] = 0
    #! 蔦が枠へ這い上がる（2 本）。
    for _ in range(2):
        y = int(rng.integers(4, 26))
        v[east - 6:east - 4, y:y + 3, 0:int(rng.integers(30, 70))] = C['hai_vd']
    #! **マスの外へ出す部分は z=0 を空ける**（footprint 照合の床除算の食い違い）。
    v[0:ext, :, 0] = 0
    return [('main', v, (-ext, 0, 0))]


def chika_hai(name):
    """**地下室の口**（Quest52「廃洋館の地下室」。`s`(72,21) の彫り込み）。

    四方を壁に囲まれた 1 マスの彫り込みなので、**天面でしか見えない**——石の枠に
    **両開きの鉄扉が開いたまま**、下へ石段が沈む。受注していない間はそのマスが
    永久壁なので、この絵はクエスト中だけ出る。
    """
    v = np.zeros((V, V, 12), np.int16)
    #! 石の縁（枠）。
    v[:, :, 0:6] = C['hai_wd']
    v[3:29, 3:29, 0:6] = C['hai_w']
    #! 下り階段（黒へ沈む 4 段）。
    for i in range(4):
        v[6:26, 8 + (i * 4):12 + (i * 4), 0:max(5 - i, 1)] = C['hai_wl']
    v[6:26, 24:29, 0:1] = C['dark']
    v[8:24, 6:8, 0:5] = C['dark']
    #! 開いた両開きの鉄扉（左右へ倒れている＝開けっ放し）。
    for x0 in (2, 24):
        v[x0:x0 + 6, 6:26, 5:9] = C['hai_ru']
        v[x0 + 1:x0 + 5, 8:24, 8:10] = C['hai_rud']
    #! 落ち葉が吹き溜まる。
    v[10:22, 6:10, 6:7] = C['hai_lf']
    return [('main', v, (0, 0, 0))]


def _rampart_hai(name):
    """**屋敷を囲う崩れた石塀**（`Rampart`）。腰は切石、上は**錆びた鉄柵**。

    変種で崩れ方を振る（`_01` 素・`_02` 笠石が落ちた・`_03` 柵が曲がって抜けた）。
    """
    variant = int(name.rsplit('_', 1)[1])
    rng = rng_for(name)
    h = 56
    v = np.zeros((V, V, h), np.int16)
    #! 切石の腰（8 vox の段。目地は暗い線）。
    for z in range(0, 30, 8):
        for p in range(0, V, 10):
            v[p:p + 9, 10:22, z:z + 7] = rng.choice(
                [C['hai_w'], C['hai_wl'], C['hai_wd']], p=[0.54, 0.24, 0.22])
        v[:, 10:22, z + 7:z + 8] = C['hai_wd']
    #! 笠石。変種 2 は一部が落ちている。
    v[:, 9:23, 30:34] = C['hai_wl']
    if variant == 2:
        a = int(rng.integers(0, V - 12))
        v[a:a + 11, 9:23, 30:34] = 0
        v[a:a + 11, 10:22, 26:30] = C['rub_d']
    #! 錆びた鉄柵（3 vox ピッチ。変種 3 は数本が抜けている）。
    for x in range(1, V - 1, 3):
        if (variant == 3) and (rng.random() < 0.4):
            continue
        top = h - int(rng.integers(0, 5))
        v[x:x + 2, 15:17, 33:top] = C['hai_ru']
        v[x:x + 2, 15:17, top - 2:top] = C['hai_rud']
    v[:, 14:18, 40:43] = C['hai_ru']
    #! 蔦（塀の腹に。塊で）。
    for _ in range(int(rng.integers(1, 3))):
        a = int(rng.integers(0, V - 6))
        v[a:a + 5, 9:23, 0:int(rng.integers(14, 32))] = C['hai_vd']
    return [('main', v, (0, 0, 0))]


def _watchtower_hai(name):
    """**塀の隅の門柱**（櫓は立たない）。切石の柱に**割れた飾り壺**を載せる。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 88), np.int16)
    for z in range(0, 70, 8):
        v[6:26, 6:26, z:z + 7] = C['hai_wl'] if (rng.random() < 0.4) else C['hai_w']
        v[6:26, 6:26, z + 7:z + 8] = C['hai_wd']
    v[4:28, 4:28, 70:76] = C['hai_wl']      # 笠石
    #! 飾り壺（縦に割れて上が落ちている）。
    v[11:21, 11:21, 76:84] = C['hai_w']
    v[13:19, 13:19, 84:88] = C['hai_wd']
    v[16:21, 11:21, 80:88] = 0
    #! 足元の瓦礫と蔦。
    v[2:10, 20:30, 0:5] = C['rub_d']
    v[6:12, 6:26, 0:int(rng.integers(20, 46))] = C['hai_vd']
    return [('main', v, (0, 0, 0))]


def _fence_hai(name):
    """**低い錆びた鉄柵の 1 辺**（前庭と塀の外向きの辺に立つ）。"""
    side = _slice_of(name)
    rng = rng_for(name)
    th, h = 4, 22
    v = np.zeros((V, V, h), np.int16)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, 4, C['hai_wd'])
    for a in range(1, V - 1, 4):
        if rng.random() < 0.18:
            continue
        top = h - int(rng.integers(0, 4))
        put(a, a + 2, 3, top, C['hai_ru'])
        put(a, a + 2, top - 2, top, C['hai_rud'])
    put(0, V, 12, 14, C['hai_ru'])
    return [('main', v, (0, 0, 0))]


def gate_great_hai(name):
    """**閉じた鉄の大門**（南の塀の切れ目に組み込む）。

    切石の門柱 2 本＋**錆びた鉄の格子扉**。中央の弧に**トランペットの紋章**を据える
    ——§4.3 ⑤「（任意）楽器のシルエット 1 つ」を、住人（プリズムリバー三姉妹＝
    騒霊楽団）の印として**ここに 1 度だけ**置く。館そのものには楽器を貼らない。
    """
    rng = rng_for(name)
    h = 112
    v = np.zeros((V, V, h), np.int16)
    v[:, :, 0:3] = C['hai_wd']
    v[:, :, 2] = C['hai_w']
    #! 切石の門柱 2 本。
    for x0, x1 in ((0, 9), (23, 32)):
        for z in range(3, 88, 8):
            v[x0:x1, 10:22, z:z + 7] = rng.choice(
                [C['hai_w'], C['hai_wl'], C['hai_wd']], p=[0.52, 0.26, 0.22])
            v[x0:x1, 10:22, z + 7:z + 8] = C['hai_wd']
        v[x0:x1, 9:23, 88:93] = C['hai_wl']
        cx = (x0 + x1) // 2
        v[cx - 3:cx + 3, 13:19, 93:99] = C['hai_w']
        v[cx - 2:cx + 2, 14:18, 99:102] = C['hai_wd']
    #! 錆びた鉄の格子扉（閉）。縦棒はピッチ 3・太さ 2。
    for x in range(9, 23):
        arch = int(round(6.0 * math.sin(math.pi * (x - 9) / 13.0)))
        top = 60 + arch
        if (x % 3) == 0:
            v[x:x + 2, 15:17, 3:top] = C['hai_ru']
            v[x:x + 2, 15, top:top + 3] = C['hai_rud']
    for z0 in (16, 42):
        v[9:23, 15:17, z0:z0 + 2] = C['hai_ru']
    v[15:17, 14:18, 3:66] = C['hai_rud']
    #! 柱間の鉄の弧。
    v[6:26, 15:17, 84:87] = C['hai_ru']
    for x in range(9, 23):
        rise = int(round(7.0 * math.sin(math.pi * (x - 9) / 13.0)))
        if rise > 0:
            v[x, 15:17, 86:86 + rise] = C['hai_ru']
    #! **トランペットの紋章**（朝顔＝丸い口・管・ボタン 3 つ）。
    v[10:14, 14:18, 70:80] = C['hai_ru']
    v[11:13, 15:17, 72:78] = C['hai_rud']
    v[14:22, 15:17, 73:76] = C['hai_ru']
    v[20:23, 15:17, 70:79] = C['hai_ru']
    for x in (15, 17, 19):
        v[x:x + 1, 14:18, 76:78] = C['hai_rud']
    return [('main', v, (0, 0, 0))]


def bust_hai(name):
    """**苔むした胸像**（西の並木道の脇。`entrance_flanks` が入口の前へ並べる）。

    `_03` は**倒れて台だけ**が残り、頭が足元へ転がる——並べたときに 1 体だけ
    崩れていると「手入れされていない庭」に読める。
    """
    variant = int(name.rsplit('_', 1)[1])
    rng = rng_for(name)
    v = np.zeros((V, V, 56), np.int16)
    #! 台座（切石。3 段）。
    v[8:24, 8:24, 0:6] = C['hai_wd']
    v[9:23, 9:23, 6:26] = C['hai_w']
    v[8:24, 8:24, 26:30] = C['hai_wl']
    for z in range(8, 26, 6):
        v[9:23, 9:23, z:z + 1] = C['hai_wd']
    if variant == 3:
        #! 倒れている——台の上は割れ口だけ、頭は足元に転がる。
        v[9:23, 9:23, 26:30] = C['rub_d']
        v[24:31, 12:20, 0:7] = C['hai_w']
        v[25:30, 13:19, 6:9] = C['hai_wl']
        v[6:12, 20:28, 0:4] = C['rub_d']
    else:
        #! 胸像（胸と肩は箱、頭は丸め）。**顔は彫らない**（千体地蔵と同じ判断）。
        v[12:20, 12:20, 30:42] = C['hai_w']
        v[11:21, 13:19, 32:38] = C['hai_w']
        v[13:19, 13:19, 42:52] = C['hai_wl']
        v[14:18, 12:20, 44:50] = C['hai_wl']
        if variant == 2:
            v[13:19, 13:19, 48:52] = 0
            v[13:19, 13:19, 47:48] = C['rub_d']
    #! 苔（北面と足元）。
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(8, 22))
        z = int(rng.integers(0, 26))
        v[x:x + 4, 8:11, z:z + 6] = C['hai_vd']
    v[6:26, 6:26, 0:1] = C['hai_vd']
    return [('main', v, (0, 0, 0))]


def _ground_turf_hai(name):
    """**荒れた庭の下草** — 伸びきった草に落ち葉と茨。掃く者はいない。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['soil']
    layer = np.zeros((V, V), np.int16)
    _mottle(rng, layer, [C['turf_d'], C['moss_d'], C['hai_v'], C['soil']], [0.34, 0.28, 0.22, 0.16])
    #! 落ち葉の吹き溜まり（塊で 2〜4 か所）。
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 6))
        y = int(rng.integers(0, V - 6))
        layer[x:x + int(rng.integers(4, 8)), y:y + int(rng.integers(3, 7))] = C['hai_lf']
    #! 茨（暗い緑の筋。2 本）。
    for _ in range(2):
        x = int(rng.integers(2, V - 4))
        for y in range(V):
            layer[max(0, min(V - 1, x)), y] = C['hai_vd']
            x += int(rng.integers(-1, 2))
    _grain(rng, layer, layer > 0, [C['moss_d'], C['turf']], [0.06, 0.05], block=3)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_path_hai(name):
    """**苔むした砂利道** — かつての馬車道。目地から草が突き上げている。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['grit']
    layer = np.zeros((V, V), np.int16)
    _mottle(rng, layer, [C['grit'], C['gravel'], C['gravel_l'], C['moss_d']],
            [0.34, 0.26, 0.22, 0.18])
    #! 轍（2 本）と、割れ目から出た草。
    for _ in range(2):
        x = int(rng.integers(5, V - 5))
        for y in range(V):
            layer[max(0, min(V - 1, x)), y] = C['pack_d']
            layer[max(0, min(V - 1, x + 1)), y] = C['pack_d']
            x += int(rng.integers(-1, 2))
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 5))
        y = int(rng.integers(0, V - 5))
        layer[x:x + 4, y:y + 3] = C['hai_v'] if (rng.random() < 0.5) else C['hai_vd']
    _grain(rng, layer, layer > 0, [C['pebble'], C['ishi']], [0.05, 0.04], block=2)
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _yard_ground_hai(name):
    """**前庭の敷石** — 苔の目地に割れた石板。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0] = C['pack_d']
    v[:, :, 1] = C['ishi_d']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['ishi']
    for x in range(0, V, 11):
        for y in range(0, V, 9):
            layer[x:x + 10, y:y + 8] = rng.choice(
                [C['ishi'], C['ishi_l'], C['ishi_d']], p=[0.5, 0.26, 0.24])
    for x in range(0, V, 11):
        layer[x:x + 1, :] = C['moss_d']
    for y in range(0, V, 9):
        layer[:, y:y + 1] = C['moss_d']
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(0, V - 5))
        y = int(rng.integers(0, V - 5))
        layer[x:x + 4, y:y + 4] = C['hai_vd']
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]



# ---- 守矢神社の意匠（デザイン13・2026-08-20）----
#
# §4.2 の外せない 1 点は「**注連縄の「太さ」と御柱の垂直 4 本**。注連縄を博麗と同じ
# 細さにすると『ただの大きい博麗神社』になる」。**朱は 1 ボクセルも使わない**
# （公式の昼景の実測で 0.1%＝実質ゼロ。朱を使ってよいのは命蓮寺の幟だけ）。
#
# 地図の実測（`t0000012.txt`）:
#   社殿  **263 マス・x80..118 y17..25（39×9）**・充填 0.75。南面の中央に 3 マスの彫り込み、
#         その奥の `a`(99,23) が `BUILDING_0`＝本殿（八坂神奈子）
#   御柱  **4 マスの 2×2 の塊がちょうど 16 個**（x81..82/90..91/107..108/116..117 ×
#         y27..28/31..32/35..36/39..40）。4 本ずつ 4 組——**諏訪大社の四宮の四隅**
#   参道  x96..102（**7 マス幅**）が y25..42 を貫き、y43..49 の広場へ出て、南は 3 マス幅で山を下る
#   神の湖 北の縁の**深水 1,065 マス**（＋浅水 192）。町の 62.7% が木＝**山上の針葉樹林**
#
# 博麗神社（`hak`）との描き分けは 3 つ。
#   ① 注連縄の太さ  博麗 18 vox 径 → 守矢 **44 vox 径**（2.4 倍）
#   ② 屋根材        博麗は茅（`_house_roof_kaya`）→ 守矢は**檜皮の厚葺き**
#   ③ 前に立つ物    博麗は**朱の大鳥居**（`torii_great`）→ 守矢は**御柱 16 本**
# **この町に大鳥居の口（`torii`）を書いてはならない**——16 個の塊は東西の対を
# 8 組つくるので、御柱がまるごと鳥居 8 基に化ける（`quad_wall_prop` の註記）。
reg_local('moy_hi', (122, 92, 66))        # 檜皮 #7A5C42
reg_local('moy_hi_l', (140, 107, 78))     # 檜皮（明。葺き替えた面）#8C6B4E
reg_local('moy_hi_d', (107, 79, 58))      # 檜皮（暗）#6B4F3A
reg_local('moy_hi_dd', (82, 61, 45))      # 軒先の断面（**厚葺きはここで読ませる**）
reg_local('moy_w', (136, 119, 85))        # 素木 #887755
reg_local('moy_w_l', (162, 144, 108))     # 素木（日の当たる面）
reg_local('moy_w_d', (104, 90, 64))       # 素木（陰・木口）
reg_local('moy_e', (102, 102, 68))        # 土色の小壁 #666644
reg_local('moy_e_l', (124, 124, 88))
reg_local('moy_shime', (200, 180, 126))   # 藁の注連縄 #C8B47E
reg_local('moy_shime_l', (222, 203, 152))
reg_local('moy_shime_d', (164, 144, 92))
reg_local('moy_shide', (242, 240, 232))   # 紙垂（白）
reg_local('moy_log', (194, 169, 134))     # 皮を剥いだ樅の丸太 #C2A986
reg_local('moy_log_l', (214, 192, 160))
reg_local('moy_log_d', (138, 114, 80))    # #8A7250
reg_local('moy_ao_d', (46, 68, 42))       # 樅の葉（濃）
reg_local('moy_ao', (64, 94, 52))
reg_local('moy_ao_l', (92, 124, 66))
reg_local('moy_niji_a', (126, 172, 210))  # 月虹の布（淡い青）
reg_local('moy_niji_b', (170, 146, 202))  # 同（淡い菫）
reg_local('moy_niji_c', (214, 196, 132))  # 同（淡い金）
reg_local('moy_grit', (96, 88, 74))       # 山の土
reg_local('moy_grit_l', (124, 116, 98))
reg_local('moy_sasa', (86, 110, 66))      # 笹の下草

MOY_WALL_H = 90   #!< 社殿の壁の高さ（2.8 マス）。命蓮寺（2.6）より高く、屋根は低い
MOY_RISE = 22     #!< 屋根 1 段の上がり（0.69 マス＝35°）。**4 段＝2.75 マス**
#! §4.2 は「社殿は 3 件で一番大きく」と書いているが、**先方データはそう書いていない**
#! ——命蓮寺の本堂は 756 マス、守矢の社殿は 263 マスで、**守矢のほうが小さい**。
#! 地図が正なので、大きさでは分けない。分けるのは注連縄の太さと御柱である。
#! 段の上限は置かない（この平面では走りが最大 4 なので、自然に 4 段で棟が通る）。


def _moy_words(name):
    """`manor_wall_ne_moy_02` → `['manor', 'wall', 'ne', '02']`。"""
    return _split_style(name)[1].split('_')


def manor_wall_moy(name):
    """**守矢神社の社殿の壁 1 マス**（石の基壇＋素木の丸柱＋竪板壁・高さ 2.8 マス）。

    §4.2「壁・柱の基調は**オリーブ／土色** `#666644`〜`#887755`。**朱は使わない**」。
    命蓮寺の白壁と博麗の淡いクリームの間へ、**くすんだ黄土**で入る。

    **柱を 1 マスに 1 本立てる。**39 マスの正面をのっぺり張ると横目地の縞にしか見えない
    （廃洋館の穴 3 番）——和風の建物は**柱間（間）が構造そのもの**なので、マスの西の縁に
    素木の角柱を 2 vox 出して立てると、39 マスに 39 本の律動が通る。

    変種は置く側がマスの種で選ぶ:
      - `_01` 竪板壁（素木の縦板）……主
      - `_02` **連子窓**（縦の細い格子。奥は暗い）
      - `_03` **蔀戸**（上を跳ね上げた横板の戸。上半分が影になる）
    """
    words = _moy_words(name)  # manor wall <slice> [nn]
    key = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    h = MOY_WALL_H
    #! **`np.int16`**（`reg_local` の索引は 1000 番台。uint8 には入らない）
    v = np.zeros((V, V, h), np.int16)
    #! 石の基壇（乱石積み）と、内側の躯体（軒の下は暗い）。
    v[:, :, 0:10] = C['rock_d']
    v[:, :, 8:10] = C['rock']
    v[:, :, 10:h] = C['timber_d']
    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in faces:
        vertical = side in ('w', 'e')
        if side == 'n':
            fx, fy = slice(0, V), slice(0, 5)
        elif side == 's':
            fx, fy = slice(0, V), slice(V - 5, V)
        elif side == 'w':
            fx, fy = slice(0, 5), slice(0, V)
        else:
            fx, fy = slice(V - 5, V), slice(0, V)

        def band(p0, p1, z0, z1, colour, _fx=fx, _fy=fy, _vert=vertical):
            if _vert:
                v[_fx, p0:p1, z0:z1] = colour
            else:
                v[p0:p1, _fy, z0:z1] = colour

        #! 竪板壁（8 vox の板・目地 1 vox）。塊ごとに 1 色（罠 38）。
        for p in range(0, V, 8):
            shade = rng.choice([C['moy_w'], C['moy_w_l'], C['moy_w_d']], p=[0.62, 0.2, 0.18])
            band(p, p + 7, 10, h, shade)
            band(p + 7, p + 8, 10, h, C['moy_w_d'])
        #! 腰の長押（横に 1 本）と、頂の桁。
        band(0, V, 34, 39, C['moy_w_d'])
        band(0, V, 36, 38, C['moy_w_l'])
        band(0, V, h - 8, h, C['moy_w_d'])
        band(0, V, h - 6, h - 4, C['moy_w'])
        if variant == 2:
            #! **連子窓**（縦の細い格子。奥は暗い＝吹き放しの社殿の内）。
            band(4, 28, 44, 76, C['dark'])
            for p in range(5, 27, 4):
                band(p, p + 2, 44, 76, C['moy_w_l'])
            band(3, 29, 40, 44, C['moy_w_d'])
            band(3, 29, 76, 80, C['moy_w_d'])
        elif variant == 3:
            #! **蔀戸**（横板の戸。上半分を跳ね上げてあるので影が落ちる）。
            band(4, 28, 40, 80, C['moy_w'])
            for z in range(42, 80, 6):
                band(4, 28, z, z + 1, C['moy_w_d'])
            band(4, 28, 62, 80, C['dark'])
            band(4, 28, 80, 84, C['moy_w_d'])
        #! **雨落ちの小石**（基壇の外の 1 段）。
        band(0, V, 6, 8, C['rock'])
    #! **柱を 1 本**（マスの西の縁。2 vox 出して立てる＝間の律動）。
    v[0:6, 0:V, 8:h] = C['moy_w_d']
    v[1:5, 0:V, 8:h] = C['moy_w']
    v[0:6, 0:V, 8:12] = C['rock_l']   # 礎石
    return [('main', v, (0, 0, 0))]


def manor_roofslope_moy(name):
    """**檜皮の厚葺きの斜面 1 マス**（`_n` / `_s` / `_w` / `_e` の 4 姿勢）。

    1 マスで **MOY_RISE（22 vox ＝ 0.69 マス・35°）**。檜皮葺きの見どころは
    **軒先の厚み**（本物は 20〜30 cm ある）なので、`manor_roofeave_*` の軒先は
    **14 vox の断面**を出し、そこにだけ 3 vox ごとの層の筋を刻む。
    斜面の面は **16 vox の粗い層**（8 vox で刻むと波トタンに見える＝廃洋館の穴 2 番）。

      - `_01` 素……主
      - `_02` 苔の帯（北面ほど濃い）
      - `_03` 葺き替えたばかりの明るい面（**3 枚に 1 枚まで**＝廃洋館の穴 7 番）
    """
    words = _moy_words(name)  # manor roofslope|roofeave <side> [nn]
    side = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    eave = (words[1] == 'roofeave')
    rng = rng_for(name)
    ext = 12 if eave else 0
    along_x = side in ('w', 'e')
    if along_x:
        v = np.zeros((V + ext, V, MOY_RISE + 16), np.int16)
    else:
        v = np.zeros((V, V + ext, MOY_RISE + 16), np.int16)
    low_first = side in ('n', 'w')
    base = C['moy_hi_l'] if variant == 3 else C['moy_hi']
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            a = x if along_x else y
            aa = (a - ext) if low_first else a
            if (aa < 0) or (aa >= V):
                #! **軒先の断面**（厚葺きの顔）。z=0 には置かない（マスの外へ張り出す型の約束）。
                v[x, y, 1:15] = C['moy_hi_dd']
                for z in range(2, 15, 3):
                    v[x, y, z] = C['moy_hi_d']
                v[x, y, 14] = base
                continue
            t = aa if low_first else (V - 1 - aa)
            #! **むくり**（檜皮は軒際で寝て棟際で立つ）。t^1.25 で軽く反らせる。
            f = (t / float(V - 1)) ** 1.25
            surf = 14 + int(round(f * MOY_RISE))
            v[x, y, 0:surf] = C['moy_hi_dd']
            shade = base if (((t // 16) + (0 if along_x else 0)) % 2) == 0 else C['moy_hi_d']
            v[x, y, max(0, surf - 14):surf] = shade
            #! 層の段（**16 vox ＝ 1 マスに 2 本**）。
            if (t % 16) == 0:
                v[x, y, surf - 1] = C['moy_hi_d']
    #! 苔（変種 2 だけ。塊で 1〜2 か所）。
    if variant == 2:
        for _ in range(int(rng.integers(1, 3))):
            cx = int(rng.integers(0, max(1, v.shape[0] - 8)))
            cy = int(rng.integers(0, max(1, v.shape[1] - 8)))
            for x in range(cx, min(cx + int(rng.integers(4, 9)), v.shape[0])):
                for y in range(cy, min(cy + int(rng.integers(4, 9)), v.shape[1])):
                    for z in range(v.shape[2] - 1, -1, -1):
                        if v[x, y, z]:
                            v[x, y, z] = C['moss_d']
                            break
    if along_x:
        origin = (-ext if low_first else 0, 0, 0)
    else:
        origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_rooftop_moy(name):
    """**大棟の平ら 1 マス**（段の上限に達したマス。この平面ではほとんど出ない）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, MOY_RISE + 16), np.int16)
    v[:, :, 0:MOY_RISE + 14] = C['moy_hi_dd']
    v[:, :, MOY_RISE + 2:MOY_RISE + 16] = C['moy_hi']
    for x in range(0, V, 16):
        v[x:x + 1, :, MOY_RISE + 15] = C['moy_hi_d']
    for _ in range(int(rng.integers(1, 3))):
        x = int(rng.integers(0, V - 6))
        y = int(rng.integers(0, V - 6))
        v[x:x + 5, y:y + 5, MOY_RISE + 15] = C['moss_d']
    return [('main', v, (0, 0, 0))]


def manor_gable_moy(name):
    """**入母屋の破風 1 辺**（高さ 1 マスを置く側が sz で伸ばす）。

    伸縮するので**横の段は入れない**（伸ばすと段が間延びする）——**素木の破風板**を
    2 vox 出して縁取り、中は**土色の小壁に竪の小舞**、中央に**懸魚**を 1 つ下げる。
    朱は使わない。
    """
    words = _moy_words(name)  # manor gable <side>
    side = words[2]
    rng = rng_for(name)
    th = 5
    v = np.zeros((V, V, V), np.int16)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, C['moy_e'])
    #! 竪の小舞（塊ごとに 1 色。10 vox ピッチ）。
    for a in range(0, V, 10):
        if rng.random() < 0.5:
            put(a + 1, a + 9, 0, V, C['moy_e_l'])
        put(a, a + 1, 0, V, C['moy_w_d'])
    #! 破風板（両端の縁取り）と、中央の懸魚。
    put(0, 5, 0, V, C['moy_w'])
    put(V - 5, V, 0, V, C['moy_w'])
    put(1, 4, 0, V, C['moy_w_l'])
    put(V - 4, V - 1, 0, V, C['moy_w_l'])
    put(13, 19, 6, 20, C['moy_w_d'])
    put(14, 18, 8, 18, C['moy_w'])
    return [('main', v, (0, 0, 0))]


def manor_ridge_moy(name):
    """**箱棟**（`manor_ridge_moy` は東西・`_ns` は南北）。

    諏訪大社の社殿は**千木も鰹木も持たない**（あれは伊勢・出雲の意匠）ので、
    檜皮を重ねた**四角い箱棟**に銅板の覆いを掛けるだけにする。
    """
    ns = _split_style(name)[1].endswith('_ns')
    rng = rng_for(name)
    long_, thick, h = V, 14, 26
    v = np.zeros((thick, long_, h) if ns else (long_, thick, h), np.int16)

    def put(a0, a1, t0, t1, z0, z1, colour):
        if ns:
            v[t0:t1, a0:a1, z0:z1] = colour
        else:
            v[a0:a1, t0:t1, z0:z1] = colour

    put(0, V, 0, 14, 1, 18, C['moy_hi_dd'])
    for z in range(2, 18, 3):
        put(0, V, 0, 14, z, z + 1, C['moy_hi_d'])
    put(0, V, 1, 13, 17, 22, C['moy_hi'])
    put(0, V, 2, 12, 21, 24, C['band'])       # 銅板の覆い（青錆びた帯）
    put(0, V, 4, 10, 23, 25, C['moy_w_d'])
    for _ in range(int(rng.integers(0, 3))):
        a = int(rng.integers(0, V - 5))
        put(a, a + 4, 3, 11, 23, 25, C['moss_d'])
    return [('main', v, (-7, 0, 0) if ns else (0, -7, 0))]


def haiden_moy(name):
    """**社殿の顔・一式**（`BUILDING_0`＝本殿・八坂神奈子。`a`(99,23) の彫り込み）。
    **§4.2 の外せない 1 点の半分がここにある。**

    姿は**参考にした画像**（2026-08-20）に合わせてある。読み取った要素は 7 つ:
      ① **向拝の庇**（本屋根より前へ 2 マス出る檜皮の深い軒）
      ② その正面に**千鳥破風**（金の懸魚つき）
      ③ 庇の軒先に掛かる**極太の注連縄**——**中央が太く両端へ紡錘に細る**型で、
         端は藁で締める。**紙垂 5 枚**を南へ垂らし、腹から**藁の円錐を 3 つ**下げる
      ④ **格子の板戸**（中央だけ暗い戸口）
      ⑤ **石の基壇と石段**（正面中央。両脇に高欄）
      ⑥ **玉垣**（基壇の縁を横に走る石の低い柵）
      ⑦ **狛犬 1 対**（高い切石の台座の上。南を向く）

    博麗の拝殿（`haiden_front_hak`）は**北を向いていた**ので屋根の上へ物を載せるほか
    なかったが、守矢の彫り込みは**南面**でカメラの正面に来る。それでも**軒の下に吊る
    ものは見下ろすカメラでは 1 画素も見えない**（廃洋館の穴 1 番）ので、縄は
    **庇の軒先より南へ・軒の稜より上へ**置く（博麗で効いた手をそのまま太らせた）。

    型は **7 マス × 5 マス × 7 マス**（224×160×224）。anchor は彫り込みのマス `a`(99,23)、
    origin (-96, 0, 0)。参道は x96..102 の **7 マス幅**なので型の幅とちょうど揃う。
    **z=0 の接地は anchor のマスの中だけ**（負のマスの footprint の罠）。

    地図の都合で**使える奥行きが場所によって違う**（守るべき約束）:
      - 局所 y 0..32（世界 y23）… `x 96..128` だけが空き（両隣は社殿の壁）
      - 局所 y 32..64（世界 y24）… `x 64..160` だけが空き（3 マスの彫り込み）
      - 局所 y 64..160（世界 y25..27）… 全幅が参道
    高さ 130 を超える所は本屋根（壁 90 ＋ 軒 36）の上なので、庇は自由に張り出せる。
    """
    rng = rng_for(name)
    W, D, H = 224, 160, 224
    v = np.zeros((W, D, H), np.int16)
    cx = 112  # 扉の中心線

    #! 接地の座布団（anchor のマス x 96..128 / y 0..32 だけ z=0 を持つ）。
    v[98:126, 2:30, 0:1] = C['rock_d']

    # ---- ⑤ 石の基壇（社殿の床。彫り込みの中と、その南 1 マス）----
    v[64:160, 32:76, 1:18] = C['rock']
    v[66:158, 34:74, 16:18] = C['rock_l']
    v[96:128, 1:32, 1:18] = C['rock']
    v[98:126, 2:30, 16:18] = C['rock_l']
    #! 石段 4 段（正面中央。南へ降りる）。
    for i, (y0, y1) in enumerate(((76, 88), (88, 100), (100, 112), (112, 126))):
        top = 15 - (i * 4)
        v[84:140, y0:y1, 1:top] = C['rock']
        v[86:138, y0:y1, top - 2:top] = C['rock_l']
    #! 石段の両脇の袖石。
    v[76:86, 76:126, 1:22] = C['rock_d']
    v[138:148, 76:126, 1:22] = C['rock_d']

    # ---- ⑥ 玉垣（基壇の縁を横に走る低い石の柵。石段の口だけ空ける）----
    for x0, x1 in ((0, 76), (148, 224)):
        v[x0:x1, 68:76, 1:30] = C['rock']
        v[x0:x1, 69:75, 28:30] = C['rock_l']
        for px in range(x0, x1, 26):
            v[px:px + 8, 66:78, 1:36] = C['rock_l']
            v[px + 1:px + 7, 67:77, 34:36] = C['rock']

    # ---- ④ 格子の板戸（戸口のマス。中央だけ暗く抜く）----
    v[96:128, 4:10, 18:96] = C['moy_w_d']
    v[100:124, 4:8, 22:92] = C['dark']
    for px in range(101, 123, 4):
        v[px:px + 2, 3:6, 22:92] = C['moy_w']
    v[96:128, 2:6, 92:100] = C['moy_w_l']   # 楣

    # ---- ① 向拝の庇（檜皮の深い軒。本屋根の上から南へ 2 マス張り出す）----
    #! 稜（軒先の高さ）を控えておく——注連縄はこの上へ乗せる。
    eave_top = 0
    for y in range(20, 108):
        t = (y - 20) / 88.0
        zs = 182 - int(round(34 * (t ** 0.85)))
        for x in range(2, 222):
            v[x, y, zs - 12:zs] = C['moy_hi_dd']
            shade = C['moy_hi'] if (((y // 16) % 2) == 0) else C['moy_hi_d']
            v[x, y, zs - 6:zs] = shade
            if (y % 16) == 0:
                v[x, y, zs - 1] = C['moy_hi_d']
        if y >= 100:
            #! **軒先の断面**（檜皮の厚葺きはここで読ませる。3 vox ごとの層）。
            for x in range(2, 222):
                v[x, y, zs - 20:zs] = C['moy_hi_dd']
                for z in range(zs - 19, zs, 3):
                    v[x, y, z] = C['moy_hi_d']
                v[x, y, zs - 1] = C['moy_hi']
            eave_top = zs
    #! 軒裏の垂木（南から見上げると見える面。等間隔の暗い筋）。
    for x in range(6, 218, 12):
        v[x:x + 5, 96:108, 146:150] = C['moy_w_d']

    # ---- ② 千鳥破風（庇の正面中央。金の懸魚）----
    for y in range(24, 76):
        t = (76 - y) / 52.0
        apex = 178 + int(round(30 * t))
        hw = 8 + int(round(30 * t))
        for dx in range(-hw, hw + 1):
            top = apex - int(round((abs(dx) / float(max(1, hw))) * 26))
            v[cx + dx, y, top - 10:top] = C['moy_hi_dd']
            v[cx + dx, y, top - 5:top] = C['moy_hi']
    #! 破風板（南の面の縁取り。素木）と、拝みの懸魚（金はここ 1 か所だけ）。
    for dx in range(-38, 39):
        top = 208 - int(round((abs(dx) / 38.0) * 26))
        v[cx + dx, 70:76, top - 34:top] = C['moy_e']
        v[cx + dx, 68:74, top - 8:top] = C['moy_w_l']
        v[cx + dx, 68:74, top - 12:top - 8] = C['moy_w']
    v[cx - 7:cx + 7, 66:72, 172:190] = C['gold_d']
    v[cx - 5:cx + 5, 65:70, 174:188] = C['gold']

    # ---- 向拝の柱 4 本（素木。石段の口をまたがない位置に立てる）----
    for px in (10, 56, 156, 202):
        v[px:px + 14, 104:124, 1:150] = C['moy_w_d']
        v[px + 2:px + 12, 106:122, 1:150] = C['moy_w']
        v[px + 4:px + 10, 108:120, 1:150] = C['moy_w_l']
        v[px - 3:px + 17, 101:127, 1:10] = C['rock_l']   # 沓石

    # ---- ③ **極太の注連縄**（外せない 1 点）----
    #! 参考画像の型＝**中央が太く両端へ紡錘に細る**。中央の半径 24 vox（径 48 vox ＝
    #! **1.5 マス**）で、博麗の 18 vox に対して **2.7 倍**である。§4.2 の
    #! 「注連縄を博麗と同じ細さにすると『ただの大きい博麗神社』になる」がここ。
    #! **軒の稜より上へ・軒先より南へ**置く（見下ろすカメラで縄の上面が丸ごと見える）。
    yc = 118
    #! **稜の 6 vox 下**へ芯を置く（＝太さの半分だけが稜の上に出る）。初版は稜の 10 vox
    #! 上に置いていて、見下ろすカメラでは**縄が庇と千鳥破風を丸ごと覆い隠した**
    #! （合成フレームで実測）——縄は主役だが、社殿を消してよいわけではない。
    zc = eave_top - 6
    for x in range(2, W - 2):
        t = abs(x - cx) / float(cx)
        r = int(round(24 - (15 * (t ** 1.5))))
        sag = int(round(14 * (1.0 - (t * t))))
        for dy in range(-r - 8, r + 9):
            for dz in range(-r, r + 1):
                #! 断面は**縦に潰した楕円**（縄は自重で潰れる）。奥行きを 1.3 倍に取る。
                if (((dy / 1.3) ** 2) + (dz * dz)) > (r * r):
                    continue
                #! 藁の撚り（14 vox ピッチの斜めの筋）。
                twist = ((x + (dz * 2)) // 14) % 3
                shade = (C['moy_shime_l'] if twist == 0
                         else (C['moy_shime'] if twist == 1 else C['moy_shime_d']))
                v[x, yc + dy, zc - sag + dz] = shade
    #! 縄尻の締め（両端を藁で巻く）。
    for x0 in (2, W - 20):
        v[x0:x0 + 18, yc - 16:yc + 16, zc - 16:zc + 16] = C['moy_shime_d']
        v[x0 + 3:x0 + 15, yc - 13:yc + 13, zc - 13:zc + 13] = C['moy_shime']

    # ---- 紙垂 5 枚（2026-08-20 に決めた:「白連なったオブジェクトは 1/3 の
    #      細さにして長さも半分に」）----
    #! 幅 16 → **6 vox**（1/3）・段 4 → **2 段**（丈は半分）。太らせると白い幟に見えて
    #! 主役の縄を隠す（デザイン13 の穴 7 番）——細いほうが紙に見える。
    for i in range(5):
        sx = 24 + (i * 44)
        t = abs(sx - cx) / float(cx)
        r = int(round(24 - (15 * (t ** 1.5))))
        sag = int(round(14 * (1.0 - (t * t))))
        z = zc - sag - r
        y = yc + 10
        for _ in range(2):
            v[sx:sx + 6, y:y + 8, z - 3:z] = C['moy_shide']   # 段の上面（見える面）
            v[sx:sx + 6, y + 6:y + 8, z - 12:z] = C['moy_shide']
            z -= 12
            y += 4

    # ---- **房 3 つ**（2026-08-20 に決めた:「注連縄から直接円錐形がぶら下がる形に。
    #      ぶら下げる紐は要らない。参考画像のとおり、円錐は 3 つ」）----
    #! 参考画像の大注連縄は**藁を束ねた円錐**を 3 つ下げる（中央と左右）。初版は角柱の
    #! 房を 2 つで、しかも中央には**紐で吊った本坪鈴**が下がっていた——**紐と鈴は外し、
    #! 縄の腹から円錐が直に生える**形にする（縄と 4 vox 重ねて継ぎ目を消す）。
    for sx in (cx - 74, cx, cx + 74):
        t = abs(sx - cx) / float(cx)
        r = int(round(24 - (15 * (t ** 1.5))))
        sag = int(round(14 * (1.0 - (t * t))))
        z_top = zc - sag - r + 6        #!< 縄の腹（6 vox 食い込ませる）
        #! **円錐は上下逆**（2026-08-20 に決めた その2:「円錐は上下逆かつ半分の長さに」）
        #! ——縄に接する所が細く、**下へ向かって広がる**。丈も 54 → **27 vox**（半分）。
        length = 27
        for k in range(length):
            z = z_top - k
            if z < 1:
                break
            #! 下ほど太い円錐（半径 3 → 15）。
            rr = int(round(3 + (12.0 * ((k / float(length - 1)) ** 0.7))))
            if rr < 1:
                rr = 1
            for dx in range(-rr, rr + 1):
                for dy in range(-rr, rr + 1):
                    if ((dx * dx) + (dy * dy)) > (rr * rr):
                        continue
                    #! 藁の撚り（縦の束。塊ごとに 1 色＝罠 38）。
                    twist = ((dx + 32) // 5 + (k // 9)) % 3
                    shade = (C['moy_shime'] if twist == 0
                             else (C['moy_shime_d'] if twist == 1 else C['moy_shime_l']))
                    v[sx + dx, yc + dy, z] = shade

    # ---- ⑦ 狛犬 1 対（高い切石の台座。南を向く。西＝阿・東＝吽）----
    for west in (True, False):
        def X(a, b):
            return (slice(a, b) if west else slice(W - b, W - a))
        v[X(2, 40), 128:158, 1:46] = C['rock_d']        # 台座（高い切石）
        v[X(4, 38), 130:156, 42:46] = C['rock']
        v[X(6, 36), 132:154, 46:52] = C['rock_l']       # 座布団石
        #! **見下ろすカメラに効くのは天面の輪郭**なので、胴・鬣・頭・尾を
        #! **高さで段に分けて**置く（同じ高さで並べると 1 つの灰色の箱になる＝実測）。
        v[X(9, 33), 134:154, 52:74] = C['rock_l']       # 胴（うずくまり）
        v[X(11, 31), 146:156, 70:86] = C['rock_d']      # 鬣（首の後ろ。暗く）
        v[X(13, 29), 130:146, 74:96] = C['rock_l']      # 頭（南の参道を向く）
        v[X(12, 16), 132:140, 92:102] = C['rock_d']     # 耳（左右に 1 対）
        v[X(26, 30), 132:140, 92:102] = C['rock_d']
        v[X(16, 26), 128:132, 80:88] = C['rock']        # 鼻面
        if west:
            v[X(18, 24), 127:130, 82:86] = C['rock_dd']  # 阿形（口を開く）
        #! 尾（背へ巻き上げる。天面で「獣」と読ませる唯一の手）。
        v[X(15, 27), 152:158, 66:100] = C['rock_d']
        v[X(13, 29), 150:157, 96:104] = C['rock_l']
        v[X(9, 14), 132:140, 48:70] = C['rock']         # 前脚
        v[X(28, 33), 132:140, 48:70] = C['rock']

    # ---- 玉砂利の敷き（石段の南。参道の色より一段明るい）----
    for x in range(0, W, 7):
        for y in range(126, D, 7):
            if rng.random() < 0.55:
                continue
            v[x:x + 6, y:y + 6, 1:2] = rng.choice(
                [C['rock'], C['rock_l'], C['moy_grit_l']], p=[0.5, 0.28, 0.22])
    return [('main', v, (-96, 0, 0))]


def onbashira_moy(name):
    """**御柱**（`quad_wall_prop`。2×2 マスちょうどの塊 16 個に 1 本ずつ）。

    §4.2 ②「皮を剥いだ樅の丸太 `#C2A986` / `#8A7250`。**屋根から突き出す垂直の棒は
    遠目で一発**」。**総高 7 マス**（224 vox）——社殿（壁 2.8 ＋ 屋根 2.75 ＝ 5.6 マス）
    より高いので、引きの絵でも 16 本が林立して見える。

    上端は**冠落とし**（斜めに削いだ切り口）。根元に**注連縄を 1 巻き**して紙垂を 4 枚。
    型は **2×2 マス**（64×64）で、置く側は塊の**北西のマスに 1 枚**だけ立てる。
    接地は 4 マスぶんの盛り土で受ける（footprint がそのまま 4 マスになる）。

      - `_01` 素……主
      - `_02` 苔と地衣の乗った古い柱
      - `_03` 冠落としの向きが逆・縄が高い
    """
    step = int(name[-2:]) if name[-2:].isdigit() else 1
    rng = rng_for(name)
    S, H = 64, 224
    v = np.zeros((S, S, H), np.int16)
    cx = cy = 32
    #! 根元の盛り土（4 マスぶん。ここが footprint になる）。
    #! **玉石の囲いを回してはならない**——初版は 4 辺に石を並べていて、引きの絵では
    #! 柱が**石の壇に載った円柱**（西洋の柱廊）に見えた（合成フレームで実測）。
    v[:, :, 0:3] = C['moy_grit']
    v[:, :, 2:3] = C['moy_grit_l']
    for _ in range(int(rng.integers(3, 7))):
        a = int(rng.integers(2, S - 10))
        b = int(rng.integers(2, S - 10))
        v[a:a + int(rng.integers(4, 9)), b:b + int(rng.integers(4, 9)), 2:4] = C['rock_d']
    v[20:44, 20:44, 3:6] = C['moy_grit_l']

    #! 丸太（径 34 vox ＝ 1.06 マス）。
    #! **半径を z で変えてはならない。**初版は上へ 3 vox 細らせていて、縁の判定
    #! （外周を暗くする）が z の途中で入れ替わり、引きの絵で**溝彫りの円柱（西洋の
    #! 柱廊）**に見えた（合成フレームで実測）。丸太は 7 マスで 3 vox しか細らないので、
    #! **一定にして縁を 1 本に固定する**ほうが「1 本の木」に見える。
    top = H - 22
    R = 17
    #! 断面は**八角**（円にしない）。丸い柱は面が 1 vox ずつ段になり、焼き込み AO が
    #! **縦の縞**を全面に引いて「溝彫りの円柱（西洋の柱廊）」に見えた（合成フレームで
    #! 実測）——設計書 §6.1 の「幹は角柱。丸くすると greedy が効かない」と同じ話である。
    #! 八角は**手斧で削った丸太**そのものの形でもあるので、意匠としても正しい。
    #! 面取りは**浅く**（|dx|+|dy| <= 28）。深く落として正八角にすると、45°の面が
    #! 1 vox ずつの段になって AO が縞を引く——**平らな面を大きく取る**ほうが丸太に見える。
    for z in range(4, top):
        for dx in range(-R, R + 1):
            for dy in range(-R, R + 1):
                if (abs(dx) + abs(dy)) > 28:
                    continue
                edge = (abs(dx) >= (R - 1)) or (abs(dy) >= (R - 1))                     or ((abs(dx) + abs(dy)) > 26)
                v[cx + dx, cy + dy, z] = C['moy_log_d'] if edge else C['moy_log']
    #! 節（枝を落とした跡。**塊で 3〜5 個**だけ＝まだらであって筋ではない）。
    for _ in range(int(rng.integers(3, 6))):
        z = int(rng.integers(20, top - 30))
        ang = rng.uniform(0.0, 2.0 * math.pi)
        kx = cx + int(round(math.cos(ang) * (R - 4)))
        ky = cy + int(round(math.sin(ang) * (R - 4)))
        w = int(rng.integers(4, 8))
        v[kx - w:kx + w, ky - w:ky + w, z:z + w] = C['moy_log_d']
        v[kx - w + 1:kx + w - 1, ky - w + 1:ky + w - 1, z + 1:z + w - 1] = C['bark']
    #! **冠落とし**（上端を斜めに削ぐ）。向きは変種で振る。
    flip = (step == 3)
    for z in range(top - 24, top):
        cut = (z - (top - 24))
        for dx in range(-R, R + 1):
            for dy in range(-R, R + 1):
                a = dx if not flip else -dx
                if a > (cut - 12):
                    v[cx + dx, cy + dy, z] = 0
    for dx in range(-R, R + 1):
        for dy in range(-R, R + 1):
            for z in range(top - 1, 4, -1):
                if v[cx + dx, cy + dy, z]:
                    v[cx + dx, cy + dy, z] = C['moy_log_l']  # 切り口の白木
                    break

    #! 鉄の輪（2 本。丸太を締める。3 本入れると樽に見えた＝合成フレームで実測）。
    for z in (52, 148):
        for dx in range(-18, 19):
            for dy in range(-18, 19):
                d = (dx * dx) + (dy * dy)
                if (d <= (18 * 18)) and (d >= (14 * 14)):
                    v[cx + dx, cy + dy, z:z + 3] = C['iron']

    #! **注連縄を 1 巻き**（根元。変種 3 は高い位置）と、紙垂 4 枚。
    zc = 84 if step == 3 else 58
    for dx in range(-21, 22):
        for dy in range(-21, 22):
            d = (dx * dx) + (dy * dy)
            if (d > (21 * 21)) or (d < (15 * 15)):
                continue
            twist = ((dx + dy) // 5) % 3
            shade = (C['moy_shime_l'] if twist == 0
                     else (C['moy_shime'] if twist == 1 else C['moy_shime_d']))
            v[cx + dx, cy + dy, zc:zc + 14] = shade
    #! 紙垂 4 枚。**横へ張り出させない**——初版は段ごとに外へずらしていて、
    #! 引きの絵で**白い棚が柱から突き出て**見えた（合成フレームで実測）。まっすぐ垂らす。
    for ax, ay in ((0, -19), (0, 19), (-19, 0), (19, 0)):
        px = cx + ax - 3
        py = cy + ay - 3
        v[px:px + 7, py:py + 7, zc - 26:zc] = C['moy_shide']
        v[px + 1:px + 6, py + 1:py + 6, zc - 26:zc - 24] = C['moy_shime_d']

    #! 苔と地衣（変種 2 だけ。北面の下半分へ塊で）。
    if step == 2:
        for _ in range(int(rng.integers(3, 6))):
            z = int(rng.integers(6, 110))
            a = int(rng.integers(-16, 8))
            v[cx + a:cx + a + 9, cy - 18:cy - 10, z:z + int(rng.integers(6, 16))] = C['moss_d']
    return [('main', v, (0, 0, 0))]


def goshinboku_moy(name):
    """**御神木**（`corner_prop`。社殿の脇に 1 本だけ）。

    §4.2 ⑤「御神木を社殿の脇に 1 本」——獣王園の早苗の台詞にある。**注連縄を巻いて
    紙垂を下げる**ことで「ただの大きな木」と分かれる（御柱と同じ縄の色を使う）。

    型は **3×3 マス × 8 マス**（96×96×256）で、origin (-32,-32,0) ＝ マスの中央に立つ。
    **z=0 の接地は anchor のマスの中だけ**（負のマスの footprint の罠）。
    """
    rng = rng_for(name)
    S, H = 96, 256
    v = np.zeros((S, S, H), np.int16)
    cx = cy = 48
    #! 接地の座布団（anchor のマス x32..64 / y32..64 だけ）。
    v[34:62, 34:62, 0:1] = C['moy_grit']
    #! 根張り（8 方向へ這う。z=1 から）。
    for k in range(8):
        ang = (math.pi / 4.0) * k
        for s in range(6, 30):
            px = int(round(cx + (math.cos(ang) * s)))
            py = int(round(cy + (math.sin(ang) * s)))
            r = max(1, 6 - (s // 6))
            v[px - r:px + r, py - r:py + r, 1:1 + max(2, 10 - (s // 3))] = C['bark']
    #! 幹（径 40 vox。上へ細る。こぶを 2 つ）。**断面は八角**（御柱と同じ理由——
    #! 丸い幹は焼き込み AO が縦の縞を引く。設計書 §6.1）。
    for z in range(1, 168):
        t = z / 168.0
        r = 20 - int(round(7 * t))
        if 40 < z < 58:
            r += 3
        lim = int(round(r * 1.42))
        for dx in range(-r, r + 1):
            for dy in range(-r, r + 1):
                if (abs(dx) + abs(dy)) > lim:
                    continue
                edge = (abs(dx) >= (r - 1)) or (abs(dy) >= (r - 1)) or ((abs(dx) + abs(dy)) > (lim - 2))
                v[cx + dx, cy + dy, z] = C['bark'] if edge else C['bark_l']
    #! 枝（4 本。斜めに上がる）。
    for k in range(4):
        ang = (math.pi / 2.0) * k + 0.5
        for s in range(10, 40):
            px = int(round(cx + (math.cos(ang) * s)))
            py = int(round(cy + (math.sin(ang) * s)))
            pz = 120 + (s * 2)
            r = max(1, 5 - (s // 10))
            v[px - r:px + r, py - r:py + r, pz:pz + (r * 2)] = C['bark']
    #! 樹冠（薄い板の塊。塊ごとに 1 色＝greedy が効く）。
    for _ in range(26):
        r = int(rng.integers(9, 20))
        px = int(rng.integers(r, S - r))
        py = int(rng.integers(r, S - r))
        pz = int(rng.integers(150, H - 26))
        shade = rng.choice([C['moy_ao_d'], C['moy_ao'], C['moy_ao_l']], p=[0.42, 0.36, 0.22])
        v[px - r:px + r, py - r:py + r, pz:pz + int(rng.integers(8, 18))] = shade
    #! **注連縄**（幹に 1 巻き。紙垂 4 枚）。
    for dx in range(-24, 25):
        for dy in range(-24, 25):
            d = (dx * dx) + (dy * dy)
            if (d > (24 * 24)) or (d < (18 * 18)):
                continue
            twist = ((dx + dy) // 5) % 3
            shade = (C['moy_shime_l'] if twist == 0
                     else (C['moy_shime'] if twist == 1 else C['moy_shime_d']))
            v[cx + dx, cy + dy, 62:78] = shade
    for ax, ay in ((0, -23), (0, 23), (-23, 0), (23, 0)):
        z = 60
        px = cx + ax - 4
        py = cy + ay - 4
        for _ in range(3):
            v[px:px + 9, py:py + 9, z - 3:z] = C['moy_shide']
            z -= 8
    return [('main', v, (-32, -32, 0))]


def eki_moy(name):
    """**索道乗り場**（`plots` の戸口の印。`b`(156,55)＝眼鏡の河童娘）。

    §4.2 の「先方データとの符合」でいちばん強いのがここである——**2017 年春に
    ロープウェイが開通して山麓と直結した**（茨歌仙 39 話）という原作の設定を、
    先方は町 12 の `B:1` と人里の `B:11` の**両側に索道乗り場を置く**ことで実装している。

    読ませるのは 3 つ。**大きな索輪**（径 2 マスの鉄の車輪）・**東へ延びる 2 本の綱**
    （山を下って人里へ向かう）・**吊り下がったゴンドラ**。戸口は西向き（参道の道へ開く）
    なので、型は anchor から**東へ 6 マス**伸ばして駅そのものに被せる——綱と索輪は
    駅の屋根（壁 2.8 ＋ 屋根 2 段 ＝ 4.2 マス）より**上**を通す。
    """
    rng = rng_for(name)
    W, D, H = 192, 96, 224
    v = np.zeros((W, D, H), np.int16)
    #! 接地の座布団（anchor のマス x0..32 / y32..64 だけ）。
    v[2:30, 34:62, 0:1] = C['rock_d']
    #! 板のプラットホーム（z=1 から）。
    v[0:80, 12:84, 1:8] = C['moy_w_d']
    for x in range(0, 80, 9):
        v[x:x + 8, 12:84, 6:8] = C['moy_w']
    #! 櫓（鉄と素木の柱 4 本）。
    for px, py in ((6, 16), (6, 72), (62, 16), (62, 72)):
        v[px:px + 12, py:py + 12, 1:150] = C['iron']
        v[px + 3:px + 9, py + 3:py + 9, 1:150] = C['iron_l']
    #! 筋交い（2 段）。
    for z in (56, 108):
        v[6:74, 16:22, z:z + 6] = C['iron']
        v[6:74, 72:78, z:z + 6] = C['iron']
    #! 小屋根（板葺きの片流れ。索輪より低く抑える）。
    for i in range(10):
        v[0:84, 6:90, 116 + i:117 + i] = C['moy_w_d'] if (i % 3) else C['moy_w']
    v[0:84, 6:12, 110:126] = C['moy_w_d']
    #! **索輪**（軸は南北。径 60 vox ＝ 1.9 マス。屋根の上）。
    wx, wy, wz, R = 40, 48, 180, 30
    for dx in range(-R, R + 1):
        for dz in range(-R, R + 1):
            d = (dx * dx) + (dz * dz)
            if (d <= (R * R)) and (d >= ((R - 7) * (R - 7))):
                v[wx + dx, wy - 9:wy + 9, wz + dz] = C['iron']
                v[wx + dx, wy - 4:wy + 4, wz + dz] = C['iron_l']
    for k in range(8):
        ang = (math.pi / 4.0) * k
        for s in range(4, R - 6):
            px = wx + int(round(math.cos(ang) * s))
            pz = wz + int(round(math.sin(ang) * s))
            v[px - 1:px + 2, wy - 3:wy + 3, pz - 1:pz + 2] = C['iron_l']
    v[wx - 8:wx + 8, wy - 12:wy + 12, wz - 8:wz + 8] = C['iron']
    v[wx - 4:wx + 4, wy - 16:wy + 16, wz - 4:wz + 4] = C['band']   # 軸受け
    #! **2 本の綱**（索輪から東へ。山を下って人里へ向かう＝画面の外へ抜ける）。
    for cy_ in (wy - 22, wy + 22):
        v[wx:W, cy_ - 2:cy_ + 2, wz + 24:wz + 27] = C['iron']
        v[wx:W, cy_ - 2:cy_ + 2, wz - 26:wz - 23] = C['iron']
    #! **ゴンドラ**（綱から吊り下がる木の函）。
    gx = 108
    v[gx - 4:gx + 4, wy - 24:wy + 24, wz - 24:wz + 26] = C['iron']    # 吊り腕
    v[gx - 26:gx + 26, wy - 22:wy + 22, 96:150] = C['moy_w_d']
    v[gx - 23:gx + 23, wy - 19:wy + 19, 100:146] = C['moy_w']
    v[gx - 20:gx + 20, wy - 20:wy - 18, 116:140] = C['dark']         # 窓
    v[gx - 20:gx + 20, wy + 18:wy + 20, 116:140] = C['dark']
    for i in range(6):
        v[gx - 28 + i:gx + 28 - i, wy - 24 + i:wy + 24 - i, 150 + i:151 + i] = C['band']
    #! 河童の道具（戸口の脇。鉄の箱と巻いた綱）。
    v[4:24, 66:84, 8:24] = C['iron']
    v[6:22, 68:82, 22:24] = C['iron_l']
    for r in range(6, 16, 3):
        for k in range(20):
            ang = (math.pi / 10.0) * k
            px = 44 + int(round(math.cos(ang) * r))
            py = 74 + int(round(math.sin(ang) * r))
            v[px - 1:px + 2, py - 1:py + 2, 8:12] = C['moy_shime_d']
    if rng.random() < 0.5:
        v[30:44, 14:28, 8:20] = C['moy_w_d']
    return [('main', v, (0, -32, 0))]


def ura_moy(name):
    """**神社の裏**（`BUILDING_2`＝ドレミー・スイート。`c`(99,17)）。

    社殿の**北**の口——カメラは南から見下ろすので、社殿（総高 5.6 マス）の陰になって
    正面はほとんど映らない。だから**天面で読ませる**: 素木の小さな棟門の屋根と、
    石畳、手水鉢の水面。夢の話（Quest60）は絵に混ぜない——**原作の裏付けの薄いものを
    形にしない**（§4.0 の約束）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 96), np.int16)
    v[:, :, 0:2] = C['moy_grit']
    #! 石畳（天面の主役）。
    for x in range(0, V, 8):
        for y in range(0, V, 8):
            v[x:x + 7, y:y + 7, 2:3] = rng.choice(
                [C['rock'], C['rock_l'], C['rock_d']], p=[0.5, 0.3, 0.2])
    #! 棟門（柱 2 本＋檜皮の小さな切妻。棟は東西）。
    for px in (3, 24):
        v[px:px + 5, 12:18, 2:56] = C['moy_w_d']
        v[px + 1:px + 4, 13:17, 2:56] = C['moy_w']
    v[0:V, 11:19, 56:62] = C['moy_w_d']
    for i in range(8):
        w = 14 - i
        v[0:V, 15 - w:15 + w, 62 + (i * 2):64 + (i * 2)] = (
            C['moy_hi'] if (i % 2) else C['moy_hi_d'])
    v[0:V, 13:17, 78:82] = C['moy_hi_dd']
    #! 手水鉢（東の隅。水面を 1 段下げる）。
    v[22:31, 22:31, 2:16] = C['rock_d']
    v[24:29, 24:29, 14:15] = C['water'] if 'water' in C else C['band']
    return [('main', v, (0, 0, 0))]


def ichi_moy(name):
    """**月虹市場（出張所）**（`BUILDING_3`＝天弓千亦。`d`(115,47)）。

    虹龍洞（第 18 弾）の要素。**月虹**＝月の光でできる虹なので、日除けの布は
    **淡い青・菫・金**の 3 色に振る——**朱は使わない**（朱は命蓮寺の幟の記号で、
    ここへ持ち込むと山の上に寺の色が出る）。C 字の塀（17 マス）の中の露店である。
    """
    rng = rng_for(name)
    S = 96
    v = np.zeros((S, S, 112), np.int16)
    #! 接地の座布団（anchor のマスだけ）。
    v[34:62, 34:62, 0:1] = C['moy_grit']
    #! 竹の骨組み（4 本）。
    for px, py in ((14, 14), (14, 78), (78, 14), (78, 78)):
        v[px:px + 5, py:py + 5, 1:88] = C['moy_w_d']
        v[px + 1:px + 4, py + 1:py + 4, 1:88] = C['moy_w']
    v[12:86, 12:18, 84:90] = C['moy_w_d']
    v[12:86, 78:84, 84:90] = C['moy_w_d']
    #! 日除けの布（**月虹**。3 色の帯を張る。中央がわずかに垂れる）。
    for i, x in enumerate(range(12, 86, 8)):
        shade = (C['moy_niji_a'], C['moy_niji_b'], C['moy_niji_c'])[i % 3]
        for y in range(12, 84):
            t = abs(y - 48) / 36.0
            z = 90 - int(round(7 * (1.0 - (t * t))))
            v[x:x + 8, y, z:z + 3] = shade
    #! 台（板の上にカードの束と行灯）。
    v[22:74, 30:66, 1:26] = C['moy_w_d']
    v[24:72, 32:64, 24:26] = C['moy_w']
    for _ in range(7):
        px = int(rng.integers(26, 64))
        py = int(rng.integers(34, 58))
        shade = rng.choice([C['moy_niji_a'], C['moy_niji_b'], C['moy_niji_c']])
        v[px:px + 8, py:py + 6, 26:29] = shade
        v[px + 1:px + 7, py + 1:py + 5, 28:29] = C['moy_shide']
    #! 行灯（1 つ。夜の灯りは町の街灯が受け持つので、ここは白い面だけ）。
    v[64:74, 60:70, 26:48] = C['moy_w_d']
    v[66:72, 62:68, 30:46] = C['moy_shide']
    return [('main', v, (-32, -32, 0))]


def fuda_moy(name):
    """**カード販売所**（`BUILDING_4`＝菅牧典。`e`(162,55)）。

    索道乗り場の東の 3×3 の広場に立つ小さな屋台。月虹市場（`ichi_moy`）と**同じ系統**
    （どちらも虹龍洞のアビリティカード）だが、**こちらは屋根が板葺きの箱**で、
    暖簾は**藍 1 色**——並べたときに市場のほうが華やかに見える向きへ差を付ける。
    """
    rng = rng_for(name)
    S = 96
    v = np.zeros((S, S, 104), np.int16)
    v[34:62, 34:62, 0:1] = C['moy_grit']
    #! 箱の身（板張り。北へ寄せて南面を開ける）。
    v[20:76, 16:60, 1:58] = C['moy_w_d']
    for x in range(20, 76, 7):
        v[x:x + 6, 16:60, 1:58] = C['moy_w']
    v[26:70, 56:60, 22:44] = C['dark']       # 開いた口（売り台の奥）
    #! 売り台（南へ張り出す板）。
    v[24:72, 58:76, 20:26] = C['moy_w_d']
    v[26:70, 60:74, 24:26] = C['moy_w_l']
    for _ in range(5):
        px = int(rng.integers(28, 62))
        v[px:px + 8, 62:70, 26:28] = rng.choice(
            [C['moy_niji_a'], C['moy_niji_b'], C['moy_niji_c']])
    #! 板葺きの片流れ（南へ落ちる）。
    for i in range(9):
        v[16:80, 12 + (i * 7):19 + (i * 7), 76 - (i * 2):80 - (i * 2)] = (
            C['moy_w'] if (i % 2) else C['moy_w_d'])
    #! 藍の暖簾（軒から下げる。字は入れない＝遠目で潰れる）。
    for x in range(22, 74, 13):
        v[x:x + 11, 74:76, 44:62] = C['indigo'] if 'indigo' in C else C['moy_niji_b']
    return [('main', v, (-32, -32, 0))]


MOY_MOMI_H = (108, 132, 156, 180)  #!< 樅の高さ（3.4 / 4.1 / 4.9 / 5.6 マス）
#! 初版は 4.7〜7.0 マスで、**社殿（5.6）も御柱（7.0）も林に埋もれた**（合成フレームで
#! 実測）。§4.2 ②「屋根から突き出す垂直の棒 4 本は遠目で一発」が成り立つのは、
#! **林の梢が社殿の軒より低い**ときだけである。


def momi_moy(name):
    """**樅（もみ）**（`grove`。町の 62.7%＝8,200 マスがこれになる）。

    妖怪の山の上の針葉樹林で、**御柱はこの木から採る**（諏訪の御柱は樅である）。
    円錐の層を重ねた濃緑の木にすると、16 本の白い丸太（皮を剥いだ樅）との
    **同じ木の生と死**が読める。

    作りは「安いこと」が第一（永遠亭の竹と同じ理屈——町の絵の 6 割がこれである）:
    幹は角柱、葉は**薄い板の層**で、どちらも塊ごとに 1 色。
    """
    step = int(name[-2:]) if name[-2:].isdigit() else 1
    h = MOY_MOMI_H[max(0, min(step, len(MOY_MOMI_H)) - 1)]
    rng = rng_for(name)
    v = np.zeros((V, V, h), np.int16)
    cx = int(rng.integers(13, 20))
    cy = int(rng.integers(13, 20))
    #! 幹（角柱。**葉の下だけ**。上まで通すと段の隙間から黒い柱が覗いて塔に見える）。
    for z in range(int(h * 0.26)):
        r = 3 if z < (h // 4) else 2
        v[cx - r:cx + r, cy - r:cy + r, z] = C['bark'] if ((z // 7) % 2) else C['bark_l']
    #! 葉は**塊ごとに 1 色の直方体**を円錐状に散らす（既定の木と同じ流儀＝設計書 R8。
    #! 「球で置くと表面が階段状になり三角形が膨れる」）。同心の円盤を積んだ初版は、
    #! 引きの絵で**緑のジッグラト**に見えた（合成フレームで実測）——針葉樹の輪郭は
    #! 段ではなく**折れた枝先の刻み**である。
    base = int(h * 0.16)
    span = h - base - 6
    levels = 7
    for i in range(levels):
        t = i / float(levels - 1)
        z0 = base + int(round(span * t))
        r = 13 - int(round(10.0 * t))
        if r < 2:
            r = 2
        thick = max(5, 13 - int(round(7 * t)))
        shade = rng.choice([C['moy_ao_d'], C['moy_ao'], C['moy_ao_l']], p=[0.44, 0.36, 0.20])

        def box(px, py, w, d, z_lo, z_hi, colour):
            x0 = max(0, px - w)
            x1 = min(V, px + w)
            y0 = max(0, py - d)
            y1 = min(V, py + d)
            if (x1 > x0) and (y1 > y0):
                v[x0:x1, y0:y1, max(0, z_lo):min(h, z_hi)] = colour

        box(cx, cy, max(2, r - 3), max(2, r - 3), z0, z0 + thick, shade)
        #! 裾の張り出し（枝先。**1〜2 vox 下げて**段の縁を崩す）。
        for k in range(4 if r > 6 else 2):
            ang = (math.pi / 2.0) * k + rng.uniform(-0.5, 0.5)
            px = cx + int(round(math.cos(ang) * (r - 2)))
            py = cy + int(round(math.sin(ang) * (r - 2)))
            w = int(rng.integers(2, max(3, r - 2)))
            shade2 = rng.choice([C['moy_ao_d'], C['moy_ao'], C['moy_ao_l']], p=[0.5, 0.32, 0.18])
            box(px, py, w, w, z0 - int(rng.integers(1, 4)), z0 + thick - 3, shade2)
    #! 梢（尖り）。
    v[cx - 1:cx + 1, cy - 1:cy + 1, h - 14:h] = C['moy_ao_d']
    return [('main', v, (0, 0, 0))]


def lamp_post_moy(name):
    """**木の常夜灯**（`lamp_step`。素木の角柱に杉皮の小屋根と障子の火袋）。

    命蓮寺と永遠亭は**石灯籠**（`stone_lantern`）なので、守矢は**素木**にする
    ——§4.2 の「素木・茅・土の社」を灯りまで通す。総高 2.3 マス。
    """
    v = np.zeros((V, V, 74), np.int16)
    v[13:19, 13:19, 0:44] = C['moy_w_d']
    v[14:18, 14:18, 0:44] = C['moy_w']
    v[11:21, 11:21, 0:5] = C['rock_d']        # 沓石
    #! 火袋（障子の箱）。面は `lamp_flame_moy` が別体で光る（罠 39）。
    v[9:23, 9:23, 44:62] = C['moy_w_d']
    v[10:22, 10:22, 46:60] = C['moy_shide']
    for a in (10, 15, 21):
        v[a:a + 1, 9:23, 44:62] = C['moy_w_d']
        v[9:23, a:a + 1, 44:62] = C['moy_w_d']
    #! 杉皮の小屋根（宝形）。
    for i in range(6):
        w = 9 - i
        v[16 - w:16 + w, 16 - w:16 + w, 62 + (i * 2):64 + (i * 2)] = (
            C['moy_hi'] if (i % 2) else C['moy_hi_d'])
    v[15:17, 15:17, 72:74] = C['moy_w_d']
    return [('main', v, (0, 0, 0))]


def lamp_flame_moy(name):
    """**常夜灯の灯**（障子の面。自発光はインスタンス単位＝罠 39 なので別体に割る）。"""
    v = np.zeros((V, V, 74), np.int16)
    v[10:22, 8:9, 46:60] = C['moy_shide']
    v[10:22, 23:24, 46:60] = C['moy_shide']
    v[8:9, 10:22, 46:60] = C['moy_shide']
    v[23:24, 10:22, 46:60] = C['moy_shide']
    return [('main', v, (0, 0, 0))]


def _rampart_moy(name):
    """**玉垣**（月虹市場を囲う C 字の塀 17 マス。素木の柱に貫を 2 本通す）。

    土塀にすると山の上に町の壁が生えて見えるので、神社の垣にする。高さ 1.4 マス。
    """
    rng = rng_for(name)
    step = int(name[-2:]) if name[-2:].isdigit() else 1
    h = 46
    v = np.zeros((V, V, h), np.int16)
    v[:, :, 0:4] = C['moy_grit']
    #! 地覆（横に通る土台の石）。
    v[:, 12:20, 3:9] = C['rock_d']
    v[:, 13:19, 7:9] = C['rock']
    #! 柱（マスに 1 本。変種で位置を振る）。
    px = (2, 12, 22)[max(0, min(step, 3) - 1)]
    v[px:px + 8, 11:21, 3:h] = C['moy_w_d']
    v[px + 1:px + 7, 12:20, 3:h] = C['moy_w']
    v[px:px + 8, 11:21, h - 4:h] = C['moy_w_l']   # 柱頭の面取り
    #! 貫（2 本。柱を貫いて横に走る）。
    for z in (18, 32):
        v[:, 13:19, z:z + 6] = C['moy_w']
        v[:, 14:18, z + 4:z + 6] = C['moy_w_l']
    if rng.random() < 0.4:
        v[:, 13:15, 3:12] = C['moss_d']
    return [('main', v, (0, 0, 0))]


def _ground_path_moy(name):
    """**参道**（山の黒土に平石を伏せ、縁に苔）。

    命蓮寺の**掃き清めた白砂利**とも、博麗の**自然石**とも分ける——ここは山の上で、
    参道は踏み固めた土に大きめの平石を点々と伏せたものである。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0] = C['moy_grit']
    v[:, :, 1] = C['moy_grit']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['moy_grit']
    for _ in range(int(rng.integers(4, 8))):
        w = int(rng.integers(6, 13))
        d = int(rng.integers(5, 11))
        x = int(rng.integers(0, V - w))
        y = int(rng.integers(0, V - d))
        layer[x:x + w, y:y + d] = rng.choice(
            [C['rock'], C['rock_l'], C['rock_d']], p=[0.5, 0.28, 0.22])
    for _ in range(int(rng.integers(1, 4))):
        x = int(rng.integers(0, V - 4))
        y = int(rng.integers(0, V - 4))
        layer[x:x + 3, y:y + 3] = C['moss_d']
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_turf_moy(name):
    """**山の下草**（笹と苔に露岩が覗く。山上の神社の境内）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0] = C['moy_grit']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['moy_sasa']
    for x in range(0, V, 6):
        for y in range(0, V, 6):
            layer[x:x + 5, y:y + 5] = rng.choice(
                [C['moy_sasa'], C['moss'], C['moss_d']], p=[0.5, 0.28, 0.22])
    #! 露岩（**8 マスに 1 つほど**。0.3 で試したら開けたマスじゅうに灰の四角が散って
    #! 市松に見えた＝合成フレームで実測）。
    if rng.random() < 0.12:
        w = int(rng.integers(7, 13))
        x = int(rng.integers(0, V - w))
        y = int(rng.integers(0, V - w))
        layer[x:x + w, y:y + w] = C['rock']
        v[x:x + w, y:y + w, 1:3] = C['rock_d']
    v[:, :, 2] = layer
    v[:, :, 1] = np.where(v[:, :, 1] == 0, C['moy_grit'], v[:, :, 1])
    return [('main', v, (0, 0, -3))]


# ---- 彼岸（デザイン14・2026-08-20）------------------------------------------
# §4.5 の外せない 1 点は「**足元一面の彼岸花の赤**」——鬼形獣 3 面の背景素材に実在する、
# 彼岸に固有の唯一の絵である。地図はそれを**作者註記「Dirt→Flower」**でそのまま持って
# いて、8,986 マス（68.8%）が花になっている。**木も水も 1 マスも無い**のは 14 町でここだけ。
#
# 是非曲直庁の外観は**原作に無い**（§4.5「創作枠」）ので、役所らしさ——左右対称・幅広・
# 入母屋の大屋根・白漆喰＋朱の柱＋黒瓦・軒に紺の幕——で組む。地図の平面（1,002 マス・
# 80×17・上下左右とも対称で四隅が落ちた八角）がその読みを裏づけている。
reg_local('hig_beni', (195, 32, 43))      # 彼岸花 #C3202B
reg_local('hig_beni_l', (215, 38, 61))    # 同（日の当たる花弁）#D7263D
reg_local('hig_beni_d', (148, 22, 32))    # 同（陰）
reg_local('hig_shibe', (238, 106, 72))    # 蕊の先（橙に振る。淡いと蕾に見える）
reg_local('hig_kuki', (78, 92, 58))       # 花茎。**葉は 1 枚も付けない**（彼岸花の顔）
reg_local('hig_shiro', (236, 232, 222))   # 白漆喰（是非曲直庁と築地塀）
reg_local('hig_shiro_l', (250, 248, 242))
reg_local('hig_shiro_d', (198, 192, 180))
reg_local('hig_tsuchi', (74, 66, 58))     # 彼岸の土（灰褐。赤を沈ませる下地）
reg_local('hig_tsuchi_l', (98, 89, 78))
reg_local('hig_tsuchi_d', (56, 50, 44))
reg_local('hig_suna', (154, 146, 132))    # 賽の河原の白砂（参道）
reg_local('hig_suna_d', (122, 115, 104))
reg_local('hig_ki', (200, 185, 156))      # 白木の卒塔婆 #C8B99C
reg_local('hig_ki_d', (140, 128, 113))    # 風化した木 #8C8071
reg_local('hig_kon', (34, 44, 82))        # 紺の幕（§4.5 ⑥「軒に紺の幕」）
reg_local('hig_kon_l', (56, 72, 116))
reg_local('hig_yami', (10, 10, 12))       # 奈落の闇
reg_local('hig_okibi', (104, 30, 18))     # 奈落の底の残り火（明るいとごみに見える）
reg_local('hig_yaki', (74, 58, 46))       # 焼杉の黒褐 #4A3A2E（渡し舟の外板）
reg_local('hig_yaki_l', (98, 78, 62))     # 同（日の当たる面・板の木口）
reg_local('hig_yaki_d', (52, 41, 33))     # 同（陰・継ぎ目）
reg_local('hig_koro', (152, 128, 92))     # コロの丸太（皮を剥いだ生木）
reg_local('hig_koro_d', (112, 92, 64))
reg_local('hig_kaza_a', (196, 46, 46))    # 風車の羽（赤）
reg_local('hig_kaza_b', (46, 82, 168))    # 同（青）

HIG_WALL_H = 100  #!< 是非曲直庁の壁の高さ（3.1 マス）。14 町でいちばん高い壁
#! 屋根 1 段の上がり（20 vox ＝ 0.625 マス・32°）。**6 段＝4.4 マス**の大屋根。
#! **この値が型の総高でもある。**置く側は段ごとに `top_of(slope)`（＝型の総高）だけ
#! 持ち上げるので、**型の中の上がりが総高と違うと、その差がそのまま段差になる**
#! ——初版は総高 30 vox に対して中の上がりが 16 vox で、屋根が**黒い段丘**に見えた
#! （合成フレームで実測）。
HIG_RISE = 20


def _hig_words(name):
    """`manor_wall_ne_hig_02` → `['manor', 'wall', 'ne', '02']`。"""
    return _split_style(name)[1].split('_')


def higanbana(name):
    """**彼岸花**（`grass_hig`。町の開けたマスぜんぶ＝約 9,900 マスに 3 株ずつ立つ）。

    **これが §4.5 の外せない 1 点である。**赤は緋 #C3202B〜#D7263D。

    形の決め手は 2 つ。
      1. **葉が 1 枚も無い。**彼岸花は花期に葉を持たない（葉と花が同時に出ない）ので、
         茎だけがすっと立って先に赤が乗る。葉を付けると「赤い花の咲いた草」になる
      2. **花は輪に開く。**6 枚の花弁が反り返り、そこから**蕊が長く突き出す**。
         見下ろすカメラに映るのはこの輪なので、輪の直径で赤の面積が決まる

    高さは **0.66 マス**（21 vox）まで。ススキ（1.28 マス）の半分——町ぜんぶを覆うので、
    高くすると参道の小物も卒塔婆も赤い霞に沈む。

    **株は 1 個に 12〜18**（2026-08-20 その2 に決めた「もっと増やそう。今の三倍の
    密度で」）。**濃くするのは型の中で行う**——置く側の `tuft_tries` を 3 → 9 にすると
    インスタンスが 3 万から 9 万へ増えるうえ、追加の株は**マスの四隅にしか置かれない**
    （`emit_prop_at` の隅は 4 通り）ので、増やすほど隅に固まる。型の中の株はマスの
    6..26 vox に散るので、**同じ 3 倍でも撒け方が均される**。
    """
    rng = rng_for(name)
    height = 21
    v = np.zeros((V, V, height), np.int16)
    for _ in range(int(rng.integers(12, 19))):
        #! **マスいっぱいに散らす**（0..31）。6..25 に絞っていた初版は、株を 3 倍にすると
        #! マスの真ん中だけが濃くなって**マスの縁に赤の切れ目が方眼で走った**（合成フレームで
        #! 実測）。花はマスの外へはみ出す（描く側で切られる）が、隣のマスの花が埋める。
        bx = int(rng.integers(1, V - 1))
        by = int(rng.integers(1, V - 1))
        tall = int(rng.integers(13, height - 2))
        lean_x = int(rng.integers(-2, 3))
        lean_y = int(rng.integers(-2, 3))
        #! 茎（1 vox。**葉は付けない**）。
        for z in range(tall):
            t = z / float(max(1, tall))
            x = min(V - 1, max(0, bx + int(round(lean_x * t))))
            y = min(V - 1, max(0, by + int(round(lean_y * t))))
            v[x, y, z] = C['hig_kuki']
        hx = min(V - 1, max(0, bx + lean_x))
        hy = min(V - 1, max(0, by + lean_y))
        #! 花の輪（6 枚の花弁。反り返るので**先が 1 vox 持ち上がる**）。
        petals = 6
        r0 = int(rng.integers(4, 7))
        base = rng.choice([C['hig_beni'], C['hig_beni_l'], C['hig_beni_d']], p=[0.5, 0.3, 0.2])
        for k in range(petals):
            ang = (2.0 * math.pi * k / petals) + (rng.random() * 0.3)
            for reach in range(1, r0 + 1):
                px = hx + int(round(math.cos(ang) * reach))
                py = hy + int(round(math.sin(ang) * reach))
                pz = tall - 1 + (1 if reach > (r0 - 2) else 0)
                if (0 <= px < V) and (0 <= py < V) and (0 <= pz < height):
                    v[px, py, pz] = base
                    #! 花弁は 2 vox 幅（1 vox だと引きの絵で赤が消える）。
                    qx = px + (1 if math.cos(ang) >= 0 else -1)
                    if 0 <= qx < V:
                        v[qx, py, pz] = base
            #! 蕊（花弁より 3 vox 長く、1 vox 高く跳ねる）。
            sx = hx + int(round(math.cos(ang) * (r0 + 3)))
            sy = hy + int(round(math.sin(ang) * (r0 + 3)))
            sz = min(height - 1, tall + 1)
            if (0 <= sx < V) and (0 <= sy < V):
                v[sx, sy, sz] = C['hig_shibe']
        v[hx, hy, min(height - 1, tall)] = C['hig_beni_d']
    return [('main', v, (0, 0, 0))]


def _ground_turf_hig(name):
    """**彼岸の土**（灰褐の乾いた地面に白砂が吹き溜まる）。

    赤を主役にするので**地面は徹底して沈める**——命蓮寺の掃き清めた白砂利や守矢の
    笹の下草と違って、ここは色を持たない。ニコニコ大百科の要約「とくに見所は何も無く、
    また、何をすることも出来ない」寂しい場所の側へ倒す。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0] = C['hig_tsuchi_d']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['hig_tsuchi']
    for x in range(0, V, 6):
        for y in range(0, V, 6):
            layer[x:x + 5, y:y + 5] = rng.choice(
                [C['hig_tsuchi'], C['hig_tsuchi_l'], C['hig_tsuchi_d']], p=[0.5, 0.28, 0.22])
    #! **白砂の斑は入れない。**初版は 0.14 で撒いていて、引きの絵で開けたマスじゅうに
    #! 明るい四角が散り**市松の床**に見えた（合成フレームで実測。デザイン13 の穴 8 番の再演）。
    #! 0.07 まで落としても直らない——**変種は 5 枚しかない**ので、当たった 1 枚が
    #! 町の 2 割のマスに同じ斑を出す（確率は 0/20/40% にしか丸まらない）。
    #! 地面の変化は**マスの中の 6 vox の塊**だけで付ける。砂は参道（`ground_path_hig`）の色である。
    v[:, :, 2] = layer
    v[:, :, 1] = C['hig_tsuchi_d']
    return [('main', v, (0, 0, -3))]


def _ground_path_hig(name):
    """**参道**（賽の河原の白砂を敷き、踏み跡が黒い土を出す）。

    南の関所から庁舎の階（きざはし）まで 8 マス幅で 6 マス、北は谷まで 2 マス幅で 8 マス。
    **赤の中を白が貫く**のが町の骨格なので、土の道（守矢）ではなく砂にする。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0] = C['hig_tsuchi_d']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['hig_suna']
    for x in range(0, V, 5):
        for y in range(0, V, 5):
            layer[x:x + 4, y:y + 4] = rng.choice(
                [C['hig_suna'], C['hig_suna_d'], C['hig_tsuchi_l']], p=[0.52, 0.32, 0.16])
    #! 踏み跡（黒い土が出た所。1〜3 か所）。
    for _ in range(int(rng.integers(1, 4))):
        w = int(rng.integers(5, 12))
        d = int(rng.integers(4, 10))
        x = int(rng.integers(0, V - w))
        y = int(rng.integers(0, V - d))
        layer[x:x + w, y:y + d] = C['hig_tsuchi']
    v[:, :, 2] = layer
    v[:, :, 1] = C['hig_tsuchi_d']
    return [('main', v, (0, 0, -3))]


NARAKU_DEPTH = 40  #!< 奈落の底の深さ（vox。1.25 マス）。**縁は隣の地面の 3 vox 下**


def naraku_hig(name):
    """**奈落のマス**（`terrain_props` の `DARK_PIT`。x85..112 y1..4 の 96 マス）。

    地図の北の崖に切れ込んだ谷で、その南の縁に**地獄への入口が 2 つ**（`>`(98,4)(99,4)）
    開いている。地形は `DARK_PIT`（f_info 87「暗い穴」）で、共通の対応表には行が無い
    ——**変愚の絵を動かさない**ために、町ごとの表（`terrain_props`）で差し替える。

    **深く掘ってよい**（2026-08-20 その2 に決めた「行動不能マスというだけなら
    深く掘って底を黒くしておこう」）。`DARK_PIT` は `MOVE` を持たない＝**歩けないマス**
    なので、底を下げても行き先が消えない。

    初版は「天面を 3 vox 沈めた黒い面」だった——**隣を知らない型で縁を持ち上げると
    96 マスぜんぶに縁が立って蜂の巣になる**（罠 38）ことを避けた形だが、裂け目に見えても
    深さが無かった。**縁を 1 vox に絞れば蜂の巣にならない**: 隣り合うマスの縁が重なっても
    幅 2 vox（0.06 マス）で、1.25 マス下の底から見上げる黒い畝は読めない。しかも
    この 1 vox の壁が**穴の外との境をきちんと塞ぐ**——花野の地面（厚み 3 vox）の
    下が抜けて空が覗く、という失敗をここで防いでいる。

    **底は黒一色**（同じ指示）。残り火は地獄の門（`jigokumon_hig`）だけが持つ。
    """
    rng = rng_for(name)
    #! **底だけ**（縁は `naraku_wall_*_hig` が「隣が違う地形の辺」にだけ立てる）。
    #! 型の中に縁を彫った版は、96 マスぜんぶに縁が立って**黒い格子**に見えた
    #! （合成フレームで実測。1 vox まで細めても、天面が光を拾うので方眼が読める）。
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0:3] = C['hig_yami']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['hig_yami']
    for x in range(0, V, 7):
        for y in range(0, V, 7):
            if rng.random() < 0.30:
                layer[x:x + 6, y:y + 6] = C['obs']
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -NARAKU_DEPTH))]


def naraku_wall_hig(name):
    """**奈落の縁 1 辺**（`terrain_props` の `wall`。`_n` / `_s` / `_w` / `_e`）。

    掘り下げた穴と**その外**との境にだけ立つ黒い岩の壁。置く側がマスごとに四方の
    地形 id を見て、違う辺にだけ 1 枚置くので、**穴の内側には 1 枚も立たない**。

    厚みは 6 vox。上端は隣の地面の 3 vox 下（＝穴の口）、下端は底まで。
    真っ平らな面は「穴」ではなく「箱」に見えるので、**岩の段を 2 つ**張り出させる。
    """
    side = _split_style(name)[1].rsplit('_', 1)[-1]
    rng = rng_for(name)
    h = NARAKU_DEPTH - 3   # z = -40 .. -3
    th = 6
    v = np.zeros((V, V, h), np.int16)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, t0, t1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo + t0:lo + t1, z0:z1] = colour
        else:
            v[lo + t0:lo + t1, a0:a1, z0:z1] = colour

    put(0, V, 0, th, 0, h, C['hig_yami'])
    #! 岩の層（横に走る筋。黒の中の僅かな明暗が「深さ」を作る）。
    for z in range(2, h - 2, 7):
        if rng.random() < 0.55:
            put(0, V, 0, th, z, z + 2, C['obs'])
    #! 張り出した段を 2 つ（穴の壁が箱に見えないように）。
    for _ in range(2):
        a0 = int(rng.integers(2, V - 12))
        z0 = int(rng.integers(3, max(4, h - 16)))
        put(a0, a0 + int(rng.integers(6, 12)), 0, th + 3, z0, z0 + int(rng.integers(4, 8)),
            C['obs'])
    return [('main', v, (0, 0, -NARAKU_DEPTH))]


def narakufuchi_hig(name):
    """**奈落の縁の踏み段**（`terrain_props` の `ENTRANCE`。`>`(98,4)(99,4) の 2 マス）。

    地獄への入口は**歩けるマス**（`ENTRANCE`）なので、奈落を深く掘ったあとも
    **地表の高さに残さなければならない**——ここだけ底へ落とすと、南の広場から
    門へ渡る足場が消える。谷の南の縁に張り出した**黒い岩の踊り場**にする。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0:3] = C['obs']
    for x in range(0, V, 8):
        for y in range(0, V, 8):
            v[x:x + 7, y:y + 7, 2:3] = rng.choice(
                [C['obs'], C['obs_l'], C['hig_yami']], p=[0.5, 0.28, 0.22])
    return [('main', v, (0, 0, -3))]


def jigokumon_hig(name):
    """**地獄への入口**（`terrain_props` の `ENTRANCE`。`>`(98,4)(99,4) の 2 マス）。

    谷の南の縁に開く 2 マスの口である。**奈落を敷いたら階段が見えなくなった**
    ——対応表の `dungeon_entrance` は暗い彫り込みの絵で、黒い裂け目の底に置くと
    1 画素も読めない（合成フレームで実測）。地面を替えたマスは絵も替える。

    形は**マスの西の縁に黒い石の門柱 1 本＋冠木**。2 マスに並べると 2 間の門になる
    （社殿の柱の律動と同じ分担）。柱の間の床は 3 段下りていて、段の間から
    **残り火が覗く**——下は地獄である。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 60), np.int16)
    #! 下りる 3 段（南から北へ落ちる。段の間に残り火）。
    for i, z in enumerate((6, 3, 0)):
        y0 = 4 + (i * 9)
        v[:, y0:y0 + 9, 0:z + 2] = C['obs']
        v[:, y0:y0 + 9, z:z + 2] = C['obs_l'] if (i % 2) else C['obs']
        v[:, y0:y0 + 1, max(0, z - 1):z + 1] = C['hig_okibi']
    #! 黒い石の門柱（マスの西の縁。総高 1.9 マス）。
    v[0:7, 10:20, 0:60] = C['obs']
    v[1:6, 11:19, 0:58] = C['obs_l']
    v[0:7, 10:20, 0:4] = C['rock_dd'] if 'rock_dd' in C else C['obs']
    #! 冠木（マスをまたいで横に通る。2 マスに並べると 2 間の門になる）。
    v[0:V, 11:19, 52:60] = C['obs']
    v[0:V, 12:18, 56:60] = C['obs_l']
    #! 鉄の環（柱に 1 つ。黒一色の中の唯一の光り）。
    v[2:5, 9:11, 34:42] = C['iron_l']
    if rng.random() < 0.5:
        v[2:5, 19:21, 34:42] = C['iron_l']
    return [('main', v, (0, 0, 0))]


def _rampart_hig(name):
    """**築地塀**（外郭の 7 マス厚の帯。白漆喰に黒瓦の甍を載せる）。

    地図の外郭は西 x34..40・東 x157..163 の**7 マス厚**で、南北も 3〜4 マスで閉じている
    ——これは柵ではなく**役所の大垣**である。外を向いた 1 列だけがこの絵で、
    内側のマスは `palisade_base_hig`（漆喰の胴だけ）に落ちる。高さ 2.1 マス。
    """
    rng = rng_for(name)
    step = int(name[-2:]) if name[-2:].isdigit() else 1
    h = 68
    v = np.zeros((V, V, h), np.int16)
    #! 切石の腰（乱石ではなく整った布積み＝役所の垣）。
    v[:, :, 0:16] = C['rock_d']
    for x in range(0, V, 8):
        v[x:x + 7, :, 12:16] = rng.choice([C['rock'], C['rock_l']], p=[0.7, 0.3])
    #! 漆喰の胴（塊ごとに 1 色。目地は入れない＝塗り壁）。
    v[:, :, 16:h - 12] = C['hig_shiro']
    for x in range(0, V, 11):
        if rng.random() < 0.45:
            v[x:x + 10, :, 16:h - 12] = C['hig_shiro_d']
    #! **定規筋**（築地塀の白い横線。格式の印）。
    for z in (h - 26, h - 22, h - 18):
        v[:, :, z:z + 1] = C['hig_shiro_l']
    #! 黒瓦の甍（両流れ）。
    for i in range(6):
        w = 16 - (i * 2)
        v[:, 16 - w:16 + w, h - 12 + (i * 2):h - 10 + (i * 2)] = (
            C['kawara'] if (i % 2) else C['kawara_d'])
    v[:, 13:19, h - 2:h] = C['kawara_g']
    if (step % 3) == 0:
        #! 3 枚に 1 枚は漆喰が剥げて小舞が覗く（寂れた場所である）。
        x = int(rng.integers(2, V - 12))
        v[x:x + 10, :, 22:40] = C['hig_ki_d']
    return [('main', v, (0, 0, 0))]


def palisade_base_hig(name):
    """**築地塀の胴**（7 マス厚の内側のマス。甍を持たない漆喰の塊）。

    外を向いた 1 列だけが `palisade_hig`（甍つき）になり、ここはその内側——
    甍を全マスに載せると**7 本の屋根が並んだ縞**になる（紅魔館の塀の分担と同じ理屈）。
    高さは甍の分だけ低い 1.75 マス。
    """
    rng = rng_for(name)
    h = 56
    v = np.zeros((V, V, h), np.int16)
    v[:, :, 0:16] = C['rock_d']
    v[:, :, 16:h] = C['hig_shiro']
    for x in range(0, V, 11):
        if rng.random() < 0.4:
            v[x:x + 10, :, 16:h] = C['hig_shiro_d']
    v[:, :, h - 3:h] = C['hig_shiro_l']
    return [('main', v, (0, 0, 0))]


def _tower_sumi_hig(name):
    """**隅櫓**（外郭の四隅。白漆喰の胴に黒瓦の宝形屋根）。

    やぐらは**塀より頭ひとつ高い**という約束（`watchtower` の註記）を守りつつ、
    丸太の見張り台ではなく**役所の隅櫓**にする。総高 3.6 マス。
    """
    h = 116
    v = np.zeros((V, V, h), np.int16)
    v[2:30, 2:30, 0:20] = C['rock_d']
    for x in range(2, 30, 8):
        v[x:x + 7, 2:30, 16:20] = C['rock']
    v[4:28, 4:28, 20:84] = C['hig_shiro']
    #! 朱の柱（四隅。是非曲直庁と同じ記号）。
    for (x0, y0) in ((4, 4), (24, 4), (4, 24), (24, 24)):
        v[x0:x0 + 4, y0:y0 + 4, 20:88] = C['shu']
    #! 格子窓（**狭間ではない**。ここは城ではなく役所である）。
    for y0 in (10, 18):
        v[6:26, y0:y0 + 4, 52:70] = C['dark']
        for x in range(7, 26, 4):
            v[x:x + 2, y0:y0 + 4, 52:70] = C['hig_ki']
    v[3:29, 3:29, 84:90] = C['kawara_d']
    #! 宝形の黒瓦。
    for i in range(9):
        w = 14 - i
        v[16 - w:16 + w, 16 - w:16 + w, 90 + (i * 2):92 + (i * 2)] = (
            C['kawara'] if (i % 2) else C['kawara_d'])
    v[14:18, 14:18, 108:h] = C['kawara_g']
    return [('main', v, (0, 0, 0))]


def _yard_ground_hig(name):
    """**前庭の地面**（雑貨屋の前。踏み固めた黒い土に砂が吹き寄せる）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0:2] = C['hig_tsuchi_d']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['hig_tsuchi_d']
    for _ in range(int(rng.integers(5, 10))):
        w = int(rng.integers(4, 11))
        d = int(rng.integers(4, 11))
        x = int(rng.integers(0, V - w))
        y = int(rng.integers(0, V - d))
        layer[x:x + w, y:y + d] = rng.choice(
            [C['hig_tsuchi'], C['hig_tsuchi_d'], C['hig_suna_d']], p=[0.45, 0.35, 0.20])
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def manor_wall_hig(name):
    """**是非曲直庁の壁 1 マス**（白漆喰＋朱の柱＋腰の下見板・高さ 3.1 マス）。

    §4.5 ⑥「是非曲直庁は創作枠（原作に外観が無い）。役所らしさ＝左右対称・幅広・
    入母屋の大屋根・**白漆喰＋朱の柱＋黒瓦**・正面に階段と大扉・**軒に紺の幕**」。

    守矢の社殿と同じく**柱を 1 マスに 1 本**立てる（和風の建物は柱間が構造そのもの）が、
    こちらは**朱**である——素木の社殿（守矢）・土壁の里（人里）と、色で分かれる。
    幕は全マスの軒下に回す。80 マスの正面を紺が一本に通るのが「式のある役所」の顔である。

    変種は置く側がマスの種で選ぶ:
      - `_01` 素の白漆喰……主
      - `_02` **連子窓**（朱の格子。奥は暗い）
      - `_03` **板扉**（黒い板戸に朱の框。閉じている）
    """
    words = _hig_words(name)  # manor wall <slice> [nn]
    key = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    h = HIG_WALL_H
    v = np.zeros((V, V, h), np.int16)
    #! 切石の基壇（役所なので乱石ではなく布積み）と、内側の躯体。
    v[:, :, 0:14] = C['rock_d']
    v[:, :, 12:14] = C['rock']
    v[:, :, 14:h] = C['timber_d']
    faces = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in faces:
        vertical = side in ('w', 'e')
        if side == 'n':
            fx, fy = slice(0, V), slice(0, 5)
        elif side == 's':
            fx, fy = slice(0, V), slice(V - 5, V)
        elif side == 'w':
            fx, fy = slice(0, 5), slice(0, V)
        else:
            fx, fy = slice(V - 5, V), slice(0, V)

        def band(p0, p1, z0, z1, colour, _fx=fx, _fy=fy, _vert=vertical):
            if _vert:
                v[_fx, p0:p1, z0:z1] = colour
            else:
                v[p0:p1, _fy, z0:z1] = colour

        #! 腰の下見板（黒。漆喰の白との境が建物の水平線になる）。
        band(0, V, 14, 34, C['shitami'])
        band(0, V, 32, 34, C['char_l'])
        #! 白漆喰（塊ごとに 1 色。目地は入れない＝塗り壁）。
        for p in range(0, V, 11):
            shade = rng.choice([C['hig_shiro'], C['hig_shiro_l'], C['hig_shiro_d']],
                               p=[0.62, 0.2, 0.18])
            band(p, p + 11, 34, h - 14, shade)
        if variant == 2:
            #! **連子窓**（朱の縦格子。奥は暗い）。
            band(4, 28, 46, 76, C['dark'])
            for p in range(5, 27, 4):
                band(p, p + 2, 46, 76, C['shu'])
            band(3, 29, 42, 46, C['char'])
            band(3, 29, 76, 80, C['char'])
        elif variant == 3:
            #! **板扉**（黒い板戸に朱の框。閉じている＝役所は勝手に入れない）。
            band(3, 29, 34, 80, C['shu_d'])
            band(5, 27, 34, 78, C['shitami'])
            for p in range(6, 27, 5):
                band(p, p + 1, 34, 78, C['char_l'])
            band(14, 18, 52, 60, C['kawara_g'])   # 環（かん）
        #! **紺の幕**（§4.5 ⑥「軒に紺の幕」）。軒下に 14 vox・白い縦縞を 1 マスに 2 本。
        band(0, V, h - 14, h, C['hig_kon'])
        band(0, V, h - 4, h - 2, C['hig_kon_l'])
        for p in (6, 22):
            band(p, p + 3, h - 14, h - 2, C['hig_shiro_l'])
    #! **朱の柱を 1 本**（マスの西の縁。2 vox 出して立てる＝間の律動）。
    v[0:6, 0:V, 12:h - 14] = C['shu_d']
    v[1:5, 0:V, 12:h - 14] = C['shu']
    v[0:6, 0:V, 12:16] = C['rock_l']   # 礎石
    return [('main', v, (0, 0, 0))]


def manor_roofslope_hig(name):
    """**黒瓦の本瓦葺きの斜面 1 マス**（`_n` / `_s` / `_w` / `_e` の 4 姿勢）。

    1 マスで **HIG_RISE（16 vox ＝ 0.5 マス・27°）**。役所の大屋根は勾配が緩い。
    本瓦葺きの顔は**丸瓦の畝**（平瓦の継ぎ目を丸瓦が覆う）なので、
    **勾配の向きに 8 vox ごとの畝**を通す——軒と平行な段（旧地獄街道の桟瓦）とは
    別の文法で、遠目に縦の縞が出る。

      - `_01` 素……主
      - `_02` 苔の帯
      - `_03` 葺き替えた明るい面（**3 枚に 1 枚まで**＝廃洋館の穴 7 番）
    """
    words = _hig_words(name)  # manor roofslope|roofeave <side> [nn]
    side = words[2]
    variant = int(words[3]) if ((len(words) > 3) and words[3].isdigit()) else 1
    eave = (words[1] == 'roofeave')
    rng = rng_for(name)
    ext = 12 if eave else 0
    along_x = side in ('w', 'e')
    if along_x:
        v = np.zeros((V + ext, V, HIG_RISE), np.int16)
    else:
        v = np.zeros((V, V + ext, HIG_RISE), np.int16)
    low_first = side in ('n', 'w')
    base = C['kawara_l'] if variant == 3 else C['kawara']
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            a = x if along_x else y
            aa = (a - ext) if low_first else a
            #! 畝は**勾配に直交する軸**へ 8 vox ごと（＝勾配の向きに走る丸瓦）。
            #! **上へ足さない**（総高が変わると段差が戻る）——平瓦のほうを 2 vox 彫る。
            across = y if along_x else x
            ridge = ((across % 8) < 3)
            if (aa < 0) or (aa >= V):
                #! **軒先**（巴瓦の列。z=0 には置かない＝マスの外へ張り出す型の約束）。
                v[x, y, 1:6] = C['kawara_d']
                v[x, y, 5] = base
                if ridge:
                    v[x, y, 6:8] = C['kawara_g']
                continue
            t = aa if low_first else (V - 1 - aa)
            f = t / float(V - 1)
            #! **軒先で 1 vox・棟際で総高**——隣の段とちょうど繋がる（段差 1 vox）。
            surf = 1 + int(round(f * (HIG_RISE - 1)))
            if not ridge:
                surf = max(1, surf - 2)
            v[x, y, 0:surf] = C['kawara_d']
            v[x, y, max(0, surf - 6):surf] = base
    if variant == 2:
        #! 苔（変種 2 だけ。**小さく 1〜2 か所**——初版は 4〜8 vox 角で、引きの絵では
        #! 黒瓦に**緑の飛沫**が散って見えた＝合成フレームで実測）。
        for _ in range(int(rng.integers(1, 3))):
            cx = int(rng.integers(0, max(1, v.shape[0] - 4)))
            cy = int(rng.integers(0, max(1, v.shape[1] - 4)))
            for x in range(cx, min(cx + 3, v.shape[0])):
                for y in range(cy, min(cy + 3, v.shape[1])):
                    for z in range(v.shape[2] - 1, -1, -1):
                        if v[x, y, z]:
                            v[x, y, z] = C['moss_d']
                            break
    if along_x:
        origin = (-ext if low_first else 0, 0, 0)
    else:
        origin = (0, -ext if low_first else 0, 0)
    return [('main', v, origin)]


def manor_rooftop_hig(name):
    """**大棟の平ら 1 マス**（段の上限に達したマス。80×17 の平面では棟の行に出る）。"""
    rng = rng_for(name)
    v = np.zeros((V, V, HIG_RISE), np.int16)
    v[:, :, 0:HIG_RISE] = C['kawara_d']
    v[:, :, HIG_RISE - 6:HIG_RISE] = C['kawara']
    for x in range(0, V, 8):
        v[x:x + 3, :, HIG_RISE - 2:HIG_RISE] = C['kawara_l']
    if rng.random() < 0.5:
        x = int(rng.integers(0, V - 4))
        y = int(rng.integers(0, V - 4))
        v[x:x + 3, y:y + 3, HIG_RISE - 1] = C['moss_d']
    return [('main', v, (0, 0, 0))]


def manor_gable_hig(name):
    """**入母屋の破風 1 辺**（高さ 1 マスを置く側が sz で伸ばす）。

    伸縮するので**横の段は入れない**（伸ばすと段が間延びする）——**黒い破風板**で
    縁取り、中は**白漆喰**、中央に**朱の懸魚**を 1 つ下げる。白と黒と朱の 3 色で、
    80 マスの建物の両端に大きな三角が出る。
    """
    words = _hig_words(name)  # manor gable <side>
    side = words[2]
    th = 5
    v = np.zeros((V, V, V), np.int16)
    lo, hi = _fence_sides(side, th)

    def put(a0, a1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo:hi, z0:z1] = colour
        else:
            v[lo:hi, a0:a1, z0:z1] = colour

    put(0, V, 0, V, C['hig_shiro'])
    put(2, V - 2, 0, V, C['hig_shiro_l'])
    #! 破風板（両端の縁取り。黒）。
    put(0, 5, 0, V, C['char'])
    put(V - 5, V, 0, V, C['char'])
    put(1, 4, 0, V, C['char_l'])
    put(V - 4, V - 1, 0, V, C['char_l'])
    #! 懸魚（朱。中央に 1 つ）。
    put(13, 19, 4, 20, C['shu_d'])
    put(14, 18, 6, 18, C['shu'])
    return [('main', v, (0, 0, 0))]


def manor_ridge_hig(name):
    """**箱棟**（`manor_ridge_hig` は東西・`_ns` は南北）。

    熨斗瓦を重ねて冠瓦を載せた役所の棟。**鬼瓦は置かない**——棟はマスごとに並ぶので、
    端の飾りを全マスに付けると 80 マスに鬼が 80 匹並ぶ（罠 38 と同じ形）。
    """
    ns = _split_style(name)[1].endswith('_ns')
    rng = rng_for(name)
    long_, thick, h = V, 14, 24
    v = np.zeros((thick, long_, h) if ns else (long_, thick, h), np.int16)

    def put(a0, a1, t0, t1, z0, z1, colour):
        if ns:
            v[t0:t1, a0:a1, z0:z1] = colour
        else:
            v[a0:a1, t0:t1, z0:z1] = colour

    #! 熨斗瓦（横に寝かせた瓦を 5 段。段ごとに 1 vox 内へ寄せる）。
    for i in range(5):
        put(0, V, i, 14 - i, 1 + (i * 3), 4 + (i * 3), C['kawara'] if (i % 2) else C['kawara_d'])
    #! 冠瓦（丸い覆い）。
    put(0, V, 3, 11, 16, 21, C['kawara'])
    put(0, V, 4, 10, 20, 23, C['kawara_l'])
    put(0, V, 6, 8, 22, 24, C['kawara_g'])
    for _ in range(int(rng.integers(0, 2))):
        a = int(rng.integers(0, V - 5))
        put(a, a + 4, 4, 10, 21, 23, C['moss_d'])
    return [('main', v, (-7, 0, 0) if ns else (0, -7, 0))]


def kizahashi_hig(name):
    """**階（きざはし）と列柱**（`manor_marks` の `FLOOR`。庁舎の南北の彫り込み 18 マス）。

    §4.5 ⑥「**正面に階段と大扉**」。是非曲直庁には `B:` 行の入口が 1 つも無い
    ——地図が持っているのは**南北の面に彫り込まれた向拝**（南 x97..100 y24 ＋
    x95..102 y25・北 x97..100 y13 ＋ x98..99 y14）だけである。

    **向きを持たせない。**南の向拝は北を向き、北の向拝は南を向くので、片側だけの絵に
    すると片方が裏返る。**マスに 1 本の朱の丸柱**（壁と同じ律動）と**左右対称の 2 段の
    石段**にすると、4 マスに並んで**列柱の向拝**として読める。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 88), np.int16)
    #! 石敷き（天面は隣の地面より 5 vox 高い＝壇の上）。
    v[:, :, 0:5] = C['rock_d']
    for x in range(0, V, 8):
        for y in range(0, V, 8):
            v[x:x + 7, y:y + 7, 3:5] = rng.choice(
                [C['rock'], C['rock_l'], C['rock_d']], p=[0.5, 0.3, 0.2])
    #! 2 段の石段（東西に通る。南北どちらから上っても同じ形）。
    v[:, 4:28, 5:8] = C['rock']
    v[:, 9:23, 8:11] = C['rock_l']
    #! **朱の丸柱**（マスの西の縁。庁舎の壁と同じ間隔で立つ）。
    v[1:9, 12:20, 5:76] = C['shu_d']
    v[2:8, 13:19, 5:76] = C['shu']
    v[0:10, 11:21, 5:9] = C['rock_l']       # 礎石
    v[0:10, 11:21, 70:76] = C['char']       # 頭貫
    #! 頭貫の上の黒瓦の小庇（列柱に軒が通る）。
    for i in range(4):
        w = 16 - (i * 3)
        v[:, 16 - w:16 + w, 76 + (i * 3):79 + (i * 3)] = (
            C['kawara'] if (i % 2) else C['kawara_d'])
    return [('main', v, (0, 0, 0))]


def sekisho_hig(name):
    """**地獄の関所**（`BUILDING_0`＝庭渡 久侘歌。`a`(107,32)）。

    §4.5 ⑤「関所は**木柵＋切妻の番所小屋＋障子明かり**、朱の柱 #B4432F ＋黒瓦」。
    地図では南の外郭（y31..33）の切れ目（x91..106）の**東の肩**に立つ 1 マスで、
    ここをくぐって庁舎の前庭へ入る。

    見下ろすカメラに映るのは天面なので、**切妻の黒瓦を東西の棟で通し**、その下に
    障子の白い面と朱の柱を出す。木柵は東西の袖として左右へ 1 マスぶん伸ばす。
    """
    rng = rng_for(name)
    S = 96
    v = np.zeros((S, S, 96), np.int16)
    #! 石敷きの敷居（anchor のマスだけ）。
    v[32:64, 32:64, 0:3] = C['rock_d']
    v[34:62, 34:62, 2:3] = C['rock']
    #! 木柵（東西の袖。角柱に横木 2 本）。
    #! **z=0 には置かない。**接地のマスは anchor の 1 マスだけという約束（`ichi_moy` の座布団と
    #! 同じ）で、外のマスに z=0 のボクセルがあると footprint の照合で落ちる。
    for x in range(2, S - 2, 12):
        if 26 <= x <= 66:
            continue
        v[x:x + 6, 44:50, 1:38] = C['hig_ki_d']
        v[x + 1:x + 5, 45:49, 1:38] = C['hig_ki']
    for z in (14, 28):
        v[0:28, 45:49, z:z + 5] = C['hig_ki_d']
        v[68:S, 45:49, z:z + 5] = C['hig_ki_d']
    #! 番所小屋（朱の柱 4 本）。
    for (px, py) in ((28, 30), (60, 30), (28, 58), (60, 58)):
        v[px:px + 8, py:py + 8, 3:62] = C['shu_d']
        v[px + 1:px + 7, py + 1:py + 7, 3:62] = C['shu']
    #! 障子（北面と東面だけ。南は開いていて、そこをくぐる）。
    v[30:66, 30:34, 20:58] = C['hig_shiro_l']
    v[62:68, 30:66, 20:58] = C['hig_shiro_l']
    for a in range(32, 66, 8):
        v[a:a + 2, 29:35, 20:58] = C['hig_ki_d']
        v[61:69, a:a + 2, 20:58] = C['hig_ki_d']
    v[28:68, 28:68, 58:64] = C['char']       # 桁
    #! 切妻の黒瓦（棟は東西。両流れ）。
    for i in range(7):
        w = 22 - (i * 3)
        v[24:72, 48 - w:48 + w, 64 + (i * 2):66 + (i * 2)] = (
            C['kawara'] if (i % 2) else C['kawara_d'])
    v[24:72, 44:52, 78:82] = C['kawara_g']
    #! 「関」の木札（南面。1 枚だけ）。
    v[40:56, 26:28, 34:52] = C['hig_ki']
    v[42:54, 25:27, 36:50] = C['char']
    if rng.random() < 0.5:
        v[36:40, 26:28, 34:52] = C['hig_ki_d']
    return [('main', v, (-32, -32, 0))]


def uraguchi_hig(name):
    """**道具屋裏口**（`BUILDING_1`＝埴安神 袿姫。`b`(45,39)）。

    雑貨屋（9×4）の**北面**の戸口で、南面の `1`(45,42) が表の店口である。
    袿姫は**埴輪の造形神**（鬼形獣の EX ボス）なので、裏口の脇に**埴輪を 2 体**置く
    ——焼き上がりを待つ品として、荷の木箱と一緒に並べる。
    北向きの口なので、見下ろすカメラには**天面と埴輪の頭**が映る。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 72), np.int16)
    v[:, :, 0:3] = C['hig_tsuchi_d']
    v[4:28, 2:6, 2:3] = C['rock_d']
    #! 板戸（引き違い。片方が開いている）。
    v[2:30, 24:28, 3:52] = C['char']
    v[4:16, 24:28, 5:50] = C['hig_ki_d']
    v[16:28, 24:28, 5:50] = C['dark']
    v[2:30, 22:30, 52:58] = C['char_l']
    #! 黒瓦の小庇（北へ出す）。
    for i in range(4):
        v[0:V, max(0, 20 - (i * 3)):24 - (i * 3), 58 + (i * 2):60 + (i * 2)] = (
            C['kawara'] if (i % 2) else C['kawara_d'])
    #! **埴輪 2 体**（円筒の胴に丸い頭、目と口の穴）。
    for (hx, hy, hh) in ((4, 10, 30), (22, 14, 26)):
        v[hx:hx + 8, hy:hy + 8, 3:3 + hh] = C['mbr']
        v[hx + 1:hx + 7, hy + 1:hy + 7, 3:3 + hh] = C['mbr_d']
        v[hx:hx + 8, hy:hy + 8, 3 + hh:6 + hh] = C['mbr']
        v[hx + 1:hx + 7, hy + 1:hy + 7, 6 + hh:14 + hh] = C['mbr']
        v[hx + 2:hx + 3, hy:hy + 1, 9 + hh:11 + hh] = C['dark']   # 目
        v[hx + 5:hx + 6, hy:hy + 1, 9 + hh:11 + hh] = C['dark']
        v[hx + 3:hx + 5, hy:hy + 1, 6 + hh:8 + hh] = C['dark']    # 口
    #! 荷の木箱（焼き上がりを運ぶ）。
    if rng.random() < 0.7:
        v[12:24, 6:16, 3:16] = C['oak']
        v[13:23, 7:15, 14:16] = C['oak_l']
    return [('main', v, (0, 0, 0))]


def kuguri_hig(name):
    """**潜り戸**（`terrain_props` の `QUEST_ENTER`。`A`(41,4)＝Quest63「破滅のクエスト3」）。

    ここは**外郭（築地塀）の北西に開いた 1 マスの穴**である。地図は
    `?:[EQU $QUEST63 1]` の枝でだけ `A` を `QUEST_ENTER` に変えるので、
    **クエストを受けている間だけ通れる**——ところが絵の側は塀の 1 マスのままだったので、
    **穴が開いていることが絵で分からなかった**（§5.18 の残り 4 番）。

    地形で引くので**座標を 1 つも持たない**。受注中だけ `QUEST_ENTER` になるマスに、
    受注中だけこの絵が立つ——地図が持っている条件をそのまま絵にしている。

    形は築地塀と同じ材（白漆喰＋黒瓦）で、**塀より頭ひとつ高い門**にする:
    切石の沓石 → 白漆喰の袖壁 → 黒い冠木 → 黒瓦の小屋根、その下に**開いた板戸**と
    奥の闇。塀（2.1 マス）に対して総高 2.6 マスなので、引きの絵でも切れ目が読める。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 84), np.int16)
    #! 敷居（切石。塀の腰と同じ材）。
    v[:, 10:22, 0:5] = C['rock_d']
    v[2:30, 12:20, 3:5] = C['rock']
    #! 袖壁（東西の両脇。白漆喰＋切石の腰）。
    for x0 in (0, 24):
        v[x0:x0 + 8, 10:22, 0:16] = C['rock_d']
        v[x0:x0 + 8, 10:22, 16:60] = C['hig_shiro']
        v[x0 + 1:x0 + 7, 11:21, 16:60] = C['hig_shiro_l']
    #! 冠木（黒。門の顔）。
    v[0:V, 9:23, 60:68] = C['char']
    v[0:V, 10:22, 64:68] = C['char_l']
    #! 黒瓦の小屋根（両流れ。塀の甍と同じ文法）。
    for i in range(5):
        w = 9 - (i * 2)
        v[0:V, 16 - w:16 + w, 68 + (i * 3):71 + (i * 3)] = (
            C['kawara'] if (i % 2) else C['kawara_d'])
    v[0:V, 14:18, 82:84] = C['kawara_g']
    #! 通り抜ける口（奥は闇）。
    v[8:24, 12:20, 5:60] = C['dark']
    #! **開いた板戸**（西の袖へ寄せて畳んである。閉じていると「通れない」に読める）。
    v[8:11, 4:20, 5:56] = C['hig_yaki']
    for z in range(8, 56, 7):
        v[8:11, 4:20, z:z + 1] = C['hig_yaki_d']
    v[8:11, 4:6, 5:56] = C['hig_yaki_l']
    v[7:12, 6:9, 28:32] = C['iron']          # 引き手
    #! 苔（寂れた場所。3 枚に 1 枚ほど）。
    if rng.random() < 0.4:
        v[0:8, 21:22, 16:26] = C['moss_d']
    return [('main', v, (0, 0, 0))]


def watashibune_hig(name):
    """**渡し舟**（`corner_prop`。是非曲直庁の南西の外角 (57,27) に 1 艘だけ）。

    §4.5 ④「渡し舟は**ボロいのが正**（焼杉の黒褐 `#4A3A2E`、板の継ぎ目を露出、
    舳先が反った平底の和舟）。**新しく綺麗に作ると設定違反**」——地獄の支給品で
    財政難のため新調できず、小町が『三途のタイタニック』と自称する舟である。

    **陸に上げて修繕中の姿**にする（2026-08-20 その2 に決めた「下にコロの丸太を
    置き、その上に傾いて置いておこう。地上に上げてメンテナンスのために置いてある感じで。
    周りに大工道具や、木桶、バケツなどを小物として何個も置いておこう」）。
    §4.5 は町 13 に水を 1 マスも置いていないので、**浮かべる場所が無い**——
    陸に上げるという指示は、地図と原作の両方に無理なく収まる。

    小町は是非曲直庁の死神で、映姫の下で働いている。**庁舎の裏庭に舟が上がっている**
    のは、彼女が仕事を放り出して昼寝をしている設定とも噛み合う。

    型は 3×3 マス（96×96）。**接地するのは anchor のマスだけ**（footprint の照合。
    デザイン14 の穴 3 番）なので、舟も小物も z=1 から上に置く。
    """
    rng = rng_for(name)
    S = 96
    H = 72
    v = np.zeros((S, S, H), np.int16)
    #! 作業場の敷板（anchor のマスだけ z=0 に置く）。
    v[32:64, 32:64, 0:1] = C['hig_tsuchi_d']

    #! ---- コロの丸太 3 本（**東西に転がす**。舟はこの上に載る）----
    #! **舟の外へ両側 8 vox 突き出す**（初版は舟の下に隠れて、真上からは 1 本も見えず
    #! 「コロに載っている」が読めなかった＝合成フレームで実測）。丸太の木口が舷側の
    #! 外に並ぶことが、そのまま「陸に上げてある」の印になる。
    for cx in (22, 48, 74):
        for dy in range(-7, 8):
            for dz in range(-7, 8):
                if (dy * dy + dz * dz) > 49:
                    continue
                z = 8 + dz
                if z < 1:
                    continue
                shade = C['hig_koro'] if ((dy + dz) % 5) else C['hig_koro_d']
                v[cx - 6:cx + 7, 26:70, z] = shade
        #! 木口（両端の切り口。舷側の外に出る所）。
        v[cx - 6:cx + 7, 26:28, 2:15] = C['hig_koro_d']
        v[cx - 6:cx + 7, 68:70, 2:15] = C['hig_koro_d']

    #! ---- 船体（東西に長い平底の和舟。**南へ傾いで**コロに載る）----
    #! 傾きは「船底の片側がコロに載り、反対側が地に着く」形——y が大きいほど下がる。
    def tilt(y):
        #! 傾き（南＝y が大きいほど下がる）。**0.34 では真上から傾きが読めなかった**。
        return int(round((48 - y) * 0.48))

    for x in range(8, 88):
        t = (x - 8) / 79.0
        #! 舳先（両端）で幅が絞られ、床が反り上がる。
        narrow = min(1.0, (min(t, 1.0 - t) * 3.4))
        hb = int(round(4 + (10 * narrow)))       # 半幅 4..14
        rise = int(round(11 * (1.0 - narrow) ** 2))  # 舳先の反り
        base = 15 + rise
        for y in range(48 - hb, 48 + hb + 1):
            z0 = base + tilt(y)
            if z0 < 1:
                continue
            #! 底板（3 vox）。板は 9 vox ごとの継ぎ目を露出させる（ボロい舟の顔）。
            shade = C['hig_yaki'] if (((x // 9) % 2) == 0) else C['hig_yaki_d']
            v[x, y, z0:z0 + 3] = shade
            v[x, y, z0 + 2:z0 + 3] = C['hig_yaki_d'] if ((x % 9) == 0) else shade
        #! 舷側（両縁を 13 vox 立ち上げる）。
        for y in (48 - hb, 48 + hb):
            z0 = base + tilt(y)
            if z0 < 1:
                continue
            top = z0 + 13 - int(round(6 * (1.0 - narrow)))
            v[x, y - 1:y + 2, z0:top] = C['hig_yaki']
            v[x, y - 1:y + 2, top - 2:top] = C['hig_yaki_l']   # 上縁（摺り板）
            #! **板を 1 枚剥がしておく**（修繕中。骨が覗く）。
            if 46 <= x <= 54:
                v[x, y - 1:y + 2, z0 + 4:top - 2] = 0

    #! 剥がした所に覗く肋材（3 本）。
    for x in (47, 50, 53):
        v[x, 34:62, 16:26] = C['hig_koro_d']

    #! 舳先の反りの先端（東西の端に立ち上がる板）。
    for x0 in (8, 84):
        v[x0:x0 + 4, 44:52, 22:38] = C['hig_yaki']
        v[x0:x0 + 4, 45:51, 34:38] = C['hig_yaki_l']

    #! ---- 小物（大工道具・木桶・バケット・材木。**何個も**散らす）----
    def keg(cx, cy, r, ht, colour, hoop):
        """木桶（樽）。たがを 2 本。"""
        for dx in range(-r, r + 1):
            for dy in range(-r, r + 1):
                if (dx * dx + dy * dy) > (r * r):
                    continue
                v[cx + dx, cy + dy, 1:1 + ht] = colour
        for z in (1 + (ht // 4), 1 + ((ht * 3) // 4)):
            for dx in range(-r, r + 1):
                for dy in range(-r, r + 1):
                    d2 = dx * dx + dy * dy
                    if ((r - 1) * (r - 1)) < d2 <= (r * r):
                        v[cx + dx, cy + dy, z:z + 2] = hoop
        #! 口を彫って「桶」にする（塊のままだと丸太の切り株に見える）。
        for dx in range(-r + 2, r - 1):
            for dy in range(-r + 2, r - 1):
                if (dx * dx + dy * dy) <= ((r - 2) * (r - 2)):
                    v[cx + dx, cy + dy, ht - 2:1 + ht] = C['dark']

    #! 木桶 3 つとバケット 2 つ。
    keg(16, 68, 7, 16, C['oak'], C['iron_l'])
    keg(30, 74, 6, 13, C['hig_koro'], C['iron'])
    keg(60, 70, 8, 18, C['oak'], C['iron_l'])
    for (bx, by) in ((44, 76), (76, 66)):
        keg(bx, by, 5, 10, C['iron'], C['iron_l'])
        #! 提げ手（鉄の弓）。
        for dx in range(-5, 6):
            dz = int(round((25 - (dx * dx)) ** 0.5)) if (dx * dx) <= 25 else 0
            v[bx + dx, by, 11 + dz] = C['iron_l']

    #! 大工道具の台（作業台）と、その上の道具。
    v[12:36, 18:30, 1:11] = C['oak']
    v[12:36, 18:30, 9:11] = C['oak_l']
    v[13:15, 19:29, 1:9] = C['timber_d']
    v[33:35, 19:29, 1:9] = C['timber_d']
    #! 鋸（刃を台にもたせ掛ける）。
    for i in range(20):
        v[16 + i, 22, 11 + i] = C['iron_l']
        v[16 + i, 23, 11 + i] = C['iron']
    v[34:40, 21:25, 29:33] = C['oak']          # 鋸の柄
    #! 手斧（ちょうな）と木槌を台に置く。
    v[18:22, 25:28, 11:14] = C['iron']
    v[22:32, 26:27, 11:13] = C['oak_l']
    v[26:33, 19:22, 11:15] = C['oak']
    v[24:27, 20:21, 11:14] = C['oak_l']
    #! 鑿（のみ）を 3 本、台の縁に並べる。
    for i, bx in enumerate((15, 19, 23)):
        v[bx:bx + 2, 28:29, 11:13] = C['iron_l']
        v[bx:bx + 2, 29:31, 11:13] = C['oak']

    #! 材木の束（新しい板を積む。傷んだ舷側の替えである）。
    for i in range(4):
        v[54:86, 14 + (i % 2), 1 + (i * 4):4 + (i * 4)] = (
            C['hig_koro'] if (i % 2) else C['hig_koro_d'])
        v[54:86, 16 + (i % 2), 1 + (i * 4):4 + (i * 4)] = C['hig_koro_d']
    v[52:54, 12:20, 1:18] = C['timber']        # 積み木の枕
    v[86:88, 12:20, 1:18] = C['timber']

    #! 木屑（削りかす）を撒く。
    for _ in range(int(rng.integers(10, 18))):
        px = int(rng.integers(6, S - 8))
        py = int(rng.integers(6, S - 8))
        if 30 <= py <= 66 and 8 <= px <= 88:
            continue   # 舟の下は避ける
        v[px:px + 3, py:py + 2, 1:2] = C['hig_koro']

    #! 竿（舟の脇に立てかける。小町の得物ではなく、渡し舟を突く竿）。
    for z in range(1, 60):
        v[90 - (z // 12), 58 + (z // 20), z] = C['hig_koro']
        v[91 - (z // 12), 58 + (z // 20), z] = C['hig_koro_d']
    return [('main', v, (-32, -32, 0))]


def sotoba_hig(name):
    """**卒塔婆**（`street_tree`。道に面したマスへ 3 割で立つ）。

    §4.5 ②「卒塔婆を**不等間隔に立てる**（白木 #C8B99C / 風化 #8C8071。頭が階段状に
    切り欠かれた細長い縦板）」——東方鬼形獣 1 面の背景素材に実在する。

    街路樹の口を借りているので道沿いに次々と立つが、割合が 0.3 なので間隔は不揃いに
    なる（「不等間隔」の要件はこれで満たす）。高さは 1.4〜1.9 マス。
    """
    step = int(name[-2:]) if name[-2:].isdigit() else 1
    rng = rng_for(name)
    h = (48, 56, 62, 44)[(step - 1) % 4]
    v = np.zeros((V, V, h + 4), np.int16)
    weather = (step % 2) == 0
    body = C['hig_ki_d'] if weather else C['hig_ki']
    edge = C['hig_ki'] if weather else C['hig_ki_d']
    bx = int(rng.integers(10, 18))
    by = int(rng.integers(12, 20))
    lean = int(rng.integers(-2, 3))
    #! 板（幅 12 vox・厚み 4 vox）。根元から先へ lean だけ傾ぐ。
    for z in range(h):
        t = z / float(h)
        x = max(0, bx + int(round(lean * t)))
        v[x:x + 12, by:by + 4, z] = body
        v[x:x + 1, by:by + 4, z] = edge
        v[x + 11:x + 12, by:by + 4, z] = edge
    #! **頭の刻み**（五輪を象った階段状の切り欠き。卒塔婆の顔はここ）。
    tx = max(0, bx + lean)
    for i, w in enumerate((5, 3, 1)):
        z0 = h - 2 - (i * 3)
        v[tx:tx + w, by:by + 4, z0:z0 + 3] = 0
        v[tx + 12 - w:tx + 12, by:by + 4, z0:z0 + 3] = 0
    #! 墨の字（1 本の縦線。読ませない＝遠目で潰れる）。
    v[tx + 5:tx + 7, by:by + 1, 8:h - 12] = C['dark']
    if step == 4:
        #! 4 枚に 1 枚は根元に土が盛られている（寂れた場所である）。
        v[:, by + 4:by + 8, 0:6] = C['hig_tsuchi_d']
    return [('main', v, (0, 0, 0))]


HIG_KAZA_HUB = (23.0, 15.0, 25.0)  #!< 風車の軸（変種で動かさない。parts を共有するため）


def saino_hig(name):
    """**石積みと風車**（`entrance_flanks`。関所の門の前に列で並ぶ）。

    §4.5 ③「石積み＋風車（丸石の灰を円錐に、脇に**赤と青の小さな十字**）」——
    東方鬼形獣 1 面（賽の河原）の背景素材に実在する。彼岸そのものの絵ではないが、
    §4.5 のボクセル案が挙げている（三途の河を渡って着く先の入口だからである）。

    **風車は回る**（`rotate`。軸は変種で動かさないので 1 つの parts で足りる）。
    赤い花野に灰の円錐が並び、その脇で赤と青の羽が回る。
    """
    step = int(name[-2:]) if name[-2:].isdigit() else 1
    rng = rng_for(name)
    base = np.zeros((V, V, 56), np.int16)
    wheel = np.zeros((V, V, 56), np.int16)
    base[:, :, 0:2] = C['hig_tsuchi_d']
    #! 丸石の円錐（塊ごとに 1 色。段は 5〜7。**主役はこちら**——初版は風車の竿が
    #! 1.3 マスあって、引きの絵では**灰の柱が並んだ柵**に見えた＝合成フレームで実測）。
    tiers = (6, 5, 7)[(step - 1) % 3]
    cx, cy = 12, 16
    for i in range(tiers):
        r = 9 - int(round((7.0 * i) / max(1, tiers - 1)))
        z0 = 2 + (i * 4)
        for x in range(cx - r, cx + r + 1):
            for y in range(cy - r, cy + r + 1):
                if ((x - cx) ** 2 + (y - cy) ** 2) > (r * r):
                    continue
                if (0 <= x < V) and (0 <= y < V):
                    base[x, y, z0:z0 + 4] = rng.choice(
                        [C['rock'], C['rock_l'], C['rock_d']], p=[0.44, 0.28, 0.28])
    #! 風車の軸（**細い竹の棒**。2 vox 角・総高 0.8 マス）。**灰白の木は石に見える**ので
    #! 竹の色（bark）で立てる——初版の `hig_ki_d` は石積みと同じ灰に沈んだ。
    base[22:24, 15:17, 2:26] = C['bark']
    #! **羽は面で作る**（4 象限を三角に埋める。赤・青・赤・青）。1 vox の腕を 4 本
    #! 伸ばした初版は、引きの絵では**赤い横棒に青い塊が乗った十字**にしか見えなかった
    #! （合成フレームで実測）——風車は「回る円盤」として読ませないと風車にならない。
    R = 6
    for dx in range(-R, R + 1):
        for dz in range(-R, R + 1):
            if (dx * dx + dz * dz) > (R * R):
                continue
            #! 象限で色を替え、**各象限の片側だけ**を埋めると羽根の反りが出る。
            quad = (0 if dx >= 0 else 2) + (0 if dz >= 0 else 1)
            if (abs(dx) > abs(dz)) == (quad in (0, 3)):
                continue
            colour = C['hig_kaza_a'] if (quad % 2) == 0 else C['hig_kaza_b']
            wx = 23 + dx
            wz = 25 + dz
            if (0 <= wx < V) and (0 <= wz < 56):
                wheel[wx, 14:16, wz] = colour
    wheel[22:25, 13:17, 24:27] = C['iron']
    return [('base', base, (0, 0, 0)), ('wheel', wheel, (0, 0, 0))]


def saino_hig_parts():
    return [
        {'name': 'base', 'voxels': 'base', 'grounded': True,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
        {'name': 'wheel', 'voxels': 'wheel', 'parent': 'base', 'grounded': False,
         'pivot': list(HIG_KAZA_HUB),
         'motion': {'kind': 'rotate', 'axis': 'y', 'speed': 0.30, 'phase': 0.0},
         'wind_k': 0.0},
    ]


# --------------------------------------------------- 偽天棚（デザイン15・2026-08-20）
#
# 町 14。**東方虹龍洞 3 面**「尊き高原に穿つ洞」／英名 Mine of High Land（§4.5）。
# 外せない 1 点は「**木の無い高原に空いた木枠の坑口と、そこから立ちのぼる煙**」。
#
# 先方データがそれをそのまま持っている——地図の **46% が山**（6,021 マス。14 町で最多）で、
# 囲まれた盆地に**草 2,952 ／ 花 2,917**（作者註記の「Dirt→Flower」は彼岸と同じ手）、
# 北の崖に `>`(90,3)＝**虹龍洞への入口**が 1 マスだけ開いている。
#
# **§4.5 ① の「木を生やさない」は先方データと食い違う**（木が 249 マスある）。データが正で、
# 木は**ハイマツ**（0.6 マスの這松）にした——高山帯の木はこれなので、木を置いても
# 「森でない高原」は保てる。§6.1 の 4 件と同じ形の訂正である。
reg_local('git_kusa', (106, 132, 92))     # 高原の草（寒色寄りの緑 #6E8B5A を灰へ寄せた）
reg_local('git_kusa_l', (126, 150, 110))
reg_local('git_kusa_d', (84, 108, 78))
#! **礫の混じった灰緑。**砂礫を別の色の斑で撒くと 5 枚の変種が町じゅうで同じ位置に
#! 出て**市松の水玉**になる（デザイン14 の穴 2 番の再演。合成フレームで実測）。
#! 「礫が透ける」は**隣り合う色**でしか描けない。
reg_local('git_kusa_g', (132, 142, 116))
reg_local('git_reki', (185, 180, 168))    # 砂礫の灰白 #B9B4A8
reg_local('git_reki_l', (208, 204, 194))
reg_local('git_reki_d', (150, 146, 136))
reg_local('git_reki_dd', (112, 108, 100))
reg_local('git_yuki', (237, 241, 244))    # 残雪 #EDF1F4
reg_local('git_yuki_d', (206, 214, 222))
reg_local('git_koma', (217, 139, 176))    # 駒草の淡紅紫 #D98BB0
reg_local('git_koma_l', (238, 176, 204))
reg_local('git_koma_d', (176, 104, 142))
reg_local('git_koha', (146, 166, 140))    # 駒草の葉（粉を吹いた白緑。細かく裂ける）
reg_local('git_koha_d', (112, 132, 110))
reg_local('git_ki', (90, 69, 53))         # 坑口の木枠 #5A4535
reg_local('git_ki_l', (122, 96, 74))
reg_local('git_ki_d', (62, 47, 36))
reg_local('git_ana', (20, 22, 26))        # 坑道の闇 #14161A
reg_local('git_hi', (186, 48, 46))        # 緋の幕（駒草山如の緋色の衣）
reg_local('git_hi_d', (140, 34, 34))
reg_local('git_kin', (208, 170, 72))      # 金の房
reg_local('git_kin_l', (238, 208, 124))
reg_local('git_shoji', (240, 232, 206))   # 障子明かり
reg_local('git_ita', (132, 118, 100))     # 風化した板壁（高原の小屋）
reg_local('git_ita_l', (158, 144, 124))
reg_local('git_ita_d', (104, 92, 78))
reg_local('git_maru', (150, 122, 86))     # 丸太
reg_local('git_maru_d', (112, 90, 62))
reg_local('git_oshi', (140, 138, 132))    # 屋根の押さえ石（石置き板葺きの顔）
reg_local('git_oshi_d', (108, 106, 102))
reg_local('git_matsu', (58, 86, 58))      # ハイマツの葉
reg_local('git_matsu_l', (80, 110, 72))
