def _ground_turf_git(name):
    """**高原の草地**（`ground_turf_git`。開けたマスの地面）。

    §4.5 ①「草は寒色寄りの緑 `#6E8B5A`、砂礫の灰白 `#B9B4A8`」。高山草原は**土が見えず
    礫が見える**ので、緑の下地に**砂礫の塊**を透かせる。斑は撒かない——変種は 5 枚
    しかないので、当たった 1 枚が町の 2 割のマスに同じ斑を出して市松になる
    （デザイン14 の穴 2 番）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0:2] = C['git_reki_dd']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['git_kusa']
    #! **4 色の近い緑を 5 vox の塊で撒くだけ**（礫の灰緑を含む）。明度の離れた色を
    #! 斑で置くと、変種 5 枚が町の 2 割ずつに同じ水玉を出す（デザイン14 の穴 2 番）。
    for x in range(0, V, 5):
        for y in range(0, V, 5):
            layer[x:x + 4, y:y + 4] = rng.choice(
                [C['git_kusa'], C['git_kusa_l'], C['git_kusa_d'], C['git_kusa_g']],
                p=[0.40, 0.24, 0.22, 0.14])
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _ground_path_git(name):
    """**踏み分け道**（`ground_path_git`）。高原の道は土ではなく**礫**である。

    草の緑に対して**明るい灰白**で通る。土の道（守矢）にすると周りの草より暗くなり、
    見下ろすと「窪み」に読める——高原では道のほうが明るい。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0:2] = C['git_reki_dd']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['git_reki']
    #! **礫の 4 色を 4 vox の塊で**。緑の草を斑で残すと、道じゅうに同じ緑の水玉が
    #! 並んで**敷石**に見える（デザイン14 の穴 2 番。合成フレームで実測）。
    for x in range(0, V, 4):
        for y in range(0, V, 4):
            layer[x:x + 3, y:y + 3] = rng.choice(
                [C['git_reki'], C['git_reki_l'], C['git_reki_d'], C['git_reki_dd']],
                p=[0.42, 0.24, 0.24, 0.10])
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def _yard_ground_git(name):
    """**前庭**（`yard_ground_git`）。踏み固めた礫に**木屑と炭**が落ちる小屋の前。

    街路より暗い（前庭と街路の明度の序列は意匠が変わっても守る＝`yard_ground` の註記）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0:2] = C['git_reki_dd']
    layer = np.zeros((V, V), np.int16)
    layer[:, :] = C['git_reki_d']
    #! **明度差を詰めた 3 色を 4 vox で**。6 vox × 3 色で振ると、前庭のマスが
    #! **敷石を並べた床**に見えた（合成フレームで実測。地面の斑は町ぜんぶで同じ話）。
    for x in range(0, V, 4):
        for y in range(0, V, 4):
            layer[x:x + 3, y:y + 3] = rng.choice(
                [C['git_reki_d'], C['git_reki_dd'], C['git_reki']], p=[0.52, 0.30, 0.18])
    #! 木屑（挽いた板の削り屑）と炭。**2 vox の塊**まで（大きいと汚れに見える＝穴 7 番）。
    for _ in range(int(rng.integers(3, 7))):
        x = int(rng.integers(0, V - 2))
        y = int(rng.integers(0, V - 2))
        layer[x:x + 2, y:y + 2] = C['git_ita_l'] if rng.random() < 0.6 else C['git_kuro']
    v[:, :, 2] = layer
    return [('main', v, (0, 0, -3))]


def shibakusa_git(name):
    """**高原の芝草**（`grass_git`。意匠の草。**駒草を 1〜2 株混ぜる**）。

    高山帯の草は**短い**（風で伸びられない）。ススキ 1.28 マス・彼岸花 0.66 マスに対して
    **0.44 マス**まで。

    ただし**短い草は上から見ると消える**。初版は 1 vox の葉を 9〜15 本立てただけで、
    見下ろすカメラでは**黒い点**にしかならなかった（合成フレームで実測）。読ませるのは
    高さではなく**天面の面積**なので、
      1. 葉は **2 vox 幅**で、根元から先へ**傾いで広がる**（株が座布団になる）
      2. 1 株を 3〜5 本の葉の束にして、束を 4〜6 か所に置く（点在ではなく叢）
      3. 穂は葉より**明るい灰白**（乾いた高原の色）で、天面に置く
    """
    rng = rng_for(name)
    height = 14
    v = np.zeros((V, V, height), np.int16)
    for _ in range(int(rng.integers(4, 7))):
        cx = int(rng.integers(3, V - 3))
        cy = int(rng.integers(3, V - 3))
        for _b in range(int(rng.integers(3, 6))):
            tall = int(rng.integers(6, height - 1))
            ang = float(rng.uniform(0.0, 2.0 * math.pi))
            reach = float(rng.uniform(2.0, 5.0))
            blade = rng.choice([C['git_kusa'], C['git_kusa_l'], C['git_kusa_d']],
                               p=[0.40, 0.32, 0.28])
            for z in range(tall):
                t = z / float(max(1, tall))
                #! 先ほど大きく傾ぐ（t の 2 乗）。**天面に葉の面が出る**のがここの狙い。
                x = cx + int(round(math.cos(ang) * reach * (t * t)))
                y = cy + int(round(math.sin(ang) * reach * (t * t)))
                if not ((0 <= x < V - 1) and (0 <= y < V)):
                    break
                v[x:x + 2, y, z] = blade
            #! 穂（3 本に 1 本）。
            if rng.random() < 0.34:
                x = min(V - 2, max(0, cx + int(round(math.cos(ang) * reach))))
                y = min(V - 1, max(0, cy + int(round(math.sin(ang) * reach))))
                v[x:x + 2, y, min(height - 1, tall)] = C['git_reki_l']
    #! **駒草を 1〜2 株混ぜる**（§4.5 ② の「点で散らす」）。意匠の草は変種を持たない
    #! 1 個なので、株の数と位置は種で振れても**必ず 1 株は入る**——この町の開けたマス
    #! 5,224 に 0.85 × 2 で撒かれるので、マスあたり 1〜2 点の淡紅紫が散る。
    #! **`FLOWER` のマスに分けない**理由は §5.19 の穴 1 番（道が破線になる）。
    for _k in range(int(rng.integers(1, 3))):
        _koma_clump(v, rng, int(rng.integers(5, V - 5)), int(rng.integers(5, V - 5)))
    return [('main', v, (0, 0, 0))]


def _koma_clump(v, rng, cx, cy, base_z=0):
    """**駒草の株を 1 つ**（`grass_git` と `alpine_git` が共有する）。

    §4.5 ②「駒草のピンクを砂礫に点で散らす（`#D98BB0`。数ドットで『高山』が出る）」。

    **見下ろすカメラに映るのは天面だけ**なので、形はそこで決める。
      1. **葉は白緑の座布団**（半径 4〜5・高さ 2〜3 の裂け葉）。緑の草とは別の色に見える
      2. **花は座布団の上に浮く 2×2 の塊**を 3〜5 つ。細い茎に 1 vox の花を付けた初版は
         引きの絵で**1 画素も残らなかった**（合成フレームで実測）
      3. 花は**うつむく**ので、塊の下を 1 段濃い紅にする
    """
    height = v.shape[2]
    r = int(rng.integers(4, 6))
    for x in range(max(0, cx - r), min(V, cx + r + 1)):
        for y in range(max(0, cy - r), min(V, cy + r + 1)):
            d = math.hypot(x - cx, y - cy)
            if (d > r) or ((d > (r - 1)) and (((x + y) % 2) == 0)):
                continue
            cap = 3 if d < (r * 0.5) else 2
            v[x, y, base_z:base_z + cap] = C['git_koha'] if ((x + y) % 3) else C['git_koha_d']
    for _k in range(int(rng.integers(3, 6))):
        sx = min(V - 2, max(0, cx + int(rng.integers(-r, r + 1))))
        sy = min(V - 2, max(0, cy + int(rng.integers(-r, r + 1))))
        stem = int(rng.integers(3, 6))
        #! 茎（1 vox。花を浮かせるだけの高さ）。
        for z in range(base_z + 2, min(height, base_z + 2 + stem)):
            v[sx, sy, z] = C['git_koha_d']
        z0 = min(height - 2, base_z + 2 + stem)
        tint = rng.choice([C['git_koma'], C['git_koma_l']], p=[0.58, 0.42])
        #! 花（2×2×2 の塊。**下の段を濃く**するとうつむいた花に見える）。
        v[sx:sx + 2, sy:sy + 2, z0:z0 + 2] = tint
        v[sx:sx + 2, sy:sy + 2, z0:z0 + 1] = C['git_koma_d']


#: 段ごとの高さ 3 つ（vox）。素の岩山（44/78/118/158）より上を高く・下は据え置き。
_GIT_CRAG_H = {'low': (44, 40, 50), 'mid': (78, 68, 92),
               'high': (118, 138, 102), 'peak': (158, 208, 178)}

#: 岩山の層（高山の花崗岩。**彩度を落として明度で刻む**——ここに色を置くと駒草が沈む）
_GIT_CRAG_BANDS = [C['rock_dd'], C['rock_d'], C['rock'], C['rock_l'], C['qz']]


def _crag_git(name):
    """**高山の岩山**（`crag_{low,mid,high,peak}_git`。町の 46%）。

    素の岩山（茶がかった岩）に対して**灰白の花崗岩**へ振り、**上の 2 段だけ天面に残雪**を
    置く（§4.5 ①「残雪の白 `#EDF1F4`」）。段は置く側が「山の外からの深さ」で選ぶので、
    **谷から見ると麓が灰・稜線が白**になる——高原を囲む外輪山の絵はこれで立つ。

    麓（1.4 マス）に雪を置かないのは高さの読みのためである。全段に置くと
    「雪の積もった平地」になって、山がせり上がって見えない。
    """
    tier = name.split('_')[1]
    if tier in ('high', 'peak'):
        face = ([C['snow'], C['qz'], C['rock_l'], C['grit']], [0.34, 0.28, 0.24, 0.14])
    else:
        face = ([C['rock'], C['rock_l'], C['grit'], C['lichen']], [0.40, 0.26, 0.22, 0.12])
    #! **段ごとに 3 つの高さ**（デザイン15）。素の岩山は段の中では高さが揃うので、
    #! 山が深いこの町では**上の 2 段が平らな台地**になって石垣に見えた（合成フレームで
    #! 実測）。変種ごとに 1〜1.5 マス振ると、稜線がマスごとに欠けて尾根になる。
    parts = crag(name, h_override=_GIT_CRAG_H[tier][(int(name[-2:]) - 1) % 3],
                 bands=_GIT_CRAG_BANDS, face_mix=face)
    #! **残雪**（§4.5 ①「残雪の白 `#EDF1F4`」）。天面だけに置いても**麓から見上げる絵に
    #! 1 画素も出ない**——見えているのは斜面だからである。雪線（z=96 vox ＝ 3.0 マス。
    #! 麓 1.4・中腹 2.4 の段には届かない高さ）から上の**斜面に斑で貼る**。
    #! 4 vox の塊で 55% ——全面を白くすると岩が消えて「雪山」になる。高原は夏である。
    rng = rng_for(name + ':snow')
    v = parts[0][1]
    h = v.shape[2]
    for z0 in range(96, h, 4):
        for x0 in range(0, V, 4):
            for y0 in range(0, V, 4):
                if rng.random() >= 0.55:
                    continue
                block = v[x0:x0 + 4, y0:y0 + 4, z0:z0 + 4]
                block[block > 0] = C['snow'] if (rng.random() < 0.7) else C['snow_d']
    return parts


def alpine_git(name):
    """**岩山の天面の駒草**（`alpine_git`。置く側が 8 マスに 1 株ほど載せる）。

    素の高山植物（クッション・叢・灌木の 3 種）を**駒草だけ**に差し替える。
    §4.5 ② の「高山植物の女王」は稜線の砂礫地に咲くので、**岩の天面こそが本来の
    生え場所**である（草原のマスより、こちらのほうが自生地に近い）。

    ======  ==========================================================
    01      株 2 つ。いちばん目立つ
    02      株 1 つ（疎らな稜線）
    03      岩の割れ目に沿って並んだ 3 株
    ======  ==========================================================
    """
    kind = int(name[-2:]) if name[-2:].isdigit() else 1
    rng = rng_for(name)
    v = np.zeros((V, V, 12), np.int16)
    #! 根元の砂利。**マスいっぱいには敷かない**（岩の天面が見えていてこその「ちらほら」）。
    for _ in range(int(rng.integers(4, 8))):
        x = int(rng.integers(8, 22))
        y = int(rng.integers(8, 22))
        v[x:x + 3, y:y + 3, 0:1] = C['git_reki_d']
    if kind == 3:
        spots = [(11 + (i * 5), 14 + int(rng.integers(-3, 4))) for i in range(3)]
    else:
        spots = [(15 + int(rng.integers(-5, 6)), 15 + int(rng.integers(-5, 6)))
                 for _ in range(2 if kind == 1 else 1)]
    for (cx, cy) in spots:
        _koma_clump(v, rng, cx, cy, base_z=1)
    return [('main', v, (0, 0, 0))]


def haimatsu_git(name):
    """**ハイマツ**（`grove` の素材。木のマス 249 に立てる）。

    §4.5 ① は「木を生やさない高原にする（これが識別点）」と書いているが、
    **先方データは木を 249 マス持っている**（§5.19 の実測）。データが正なので木は立てる
    ——ただし**高山帯の木はハイマツ（這松）だけ**である。幹が地を這い、葉が
    **0.5〜0.7 マスの塊**で広がるので、木を置いても森にならない。§4.5 の狙い
    （2 面＝老松の森／3 面＝木の無い高地）は、この形で保てる。

    竹（永遠亭・4.4 マス）とも杉（霧雨）とも**高さで別物**に読める。
    """
    rng = rng_for(name)
    height = int(rng.integers(17, 23))
    v = np.zeros((V, V, height), np.int16)
    #! 這う幹（中心から 2〜3 本。**立ち上がらない**のがハイマツの顔）。
    for _ in range(int(rng.integers(2, 4))):
        ang = float(rng.uniform(0.0, 2.0 * math.pi))
        x, y = 15.5, 15.5
        for step in range(int(rng.integers(8, 14))):
            x += math.cos(ang) * 1.4
            y += math.sin(ang) * 1.4
            ang += float(rng.uniform(-0.5, 0.5))
            ix, iy = int(round(x)), int(round(y))
            if not ((1 <= ix < (V - 1)) and (1 <= iy < (V - 1))):
                break
            z = 1 + (step // 5)
            v[ix - 1:ix + 1, iy - 1:iy + 1, 0:z + 2] = C['git_miki']
    #! 葉の塊（**天面が絵の大半**なので、丸い山ではなく凹凸のある塊にする）。
    for _ in range(int(rng.integers(4, 7))):
        cx = int(rng.integers(8, 24))
        cy = int(rng.integers(8, 24))
        r = int(rng.integers(5, 9))
        top = int(rng.integers(height - 7, height))
        shade = rng.choice([C['git_matsu'], C['git_matsu_l'], C['git_matsu_d']],
                           p=[0.46, 0.24, 0.30])
        for x in range(max(0, cx - r), min(V, cx + r + 1)):
            for y in range(max(0, cy - r), min(V, cy + r + 1)):
                d = math.hypot(x - cx, y - cy)
                if d > r:
                    continue
                cap = int(round(top * (1.0 - ((d / r) ** 2)))) + 3
                cap = min(height, max(3, cap))
                v[x, y, 2:cap] = shade
    #! 天面の明るい葉（日の当たる面。塊で置く）。
    for _ in range(int(rng.integers(3, 6))):
        cx = int(rng.integers(6, 26))
        cy = int(rng.integers(6, 26))
        for x in range(cx, min(V, cx + 4)):
            for y in range(cy, min(V, cy + 4)):
                col = np.nonzero(v[x, y, :])[0]
                if col.size:
                    v[x, y, int(col[-1])] = C['git_matsu_l']
    return [('main', v, (0, 0, 0))]


def _house_wall_git(name):
    """**高原の小屋の壁**（`house_wall_*_git`）。

    高山の建物は**石場建ての板壁**である——礎石を高く積み（雪と融水を切る）、
    その上に縦板を張り、隅に丸太の柱を通す。障子は南面だけ。
    人里の土壁（塗り壁）とも旧地獄街道の下見板（横板）とも、**縦の板目**で分かれる。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    v = np.zeros((V, V, HOUSE_WALL_H), np.int16)
    plinth = 8  #!< 雪国の高い石場（辺境 5・テルモラ 9 の間）
    v[:, :, 0:plinth] = C['git_reki_dd']
    #! 野面石の目（**塊ごとに 1 色**。目地は引かない＝積んだ石そのもの）。
    for x in range(0, V, 7):
        for y in range(0, V, 7):
            v[x:x + 6, y:y + 6, plinth - 3:plinth] = rng.choice(
                [C['git_reki_d'], C['git_reki'], C['git_reki_dd']], p=[0.44, 0.28, 0.28])
    x0 = HOUSE_INSET if west else 0
    x1 = V - HOUSE_INSET if east else V
    y0 = HOUSE_INSET if north else 0
    y1 = V - HOUSE_INSET if south else V
    v[x0:x1, y0:y1, plinth:] = C['git_ita']
    #! 板のむら（塊単位。罠 38）。
    for _ in range(7):
        bx = int(rng.integers(x0, max(x0 + 1, x1 - 5)))
        bz = int(rng.integers(plinth, HOUSE_WALL_H - 6))
        shade = C['git_ita_l'] if rng.random() < 0.5 else C['git_ita_d']
        block = v[bx:bx + 5, y0:y1, bz:bz + 6]
        block[block == C['git_ita']] = shade

    outward = [s for s, on in (('n', north), ('s', south), ('w', west), ('e', east)) if on]
    for side in outward:
        fx, fy = _house_face(x0, x1, y0, y1, side)
        #! 軒下の桁と足元の水切り（丸太）。
        v[fx, fy, HOUSE_WALL_H - 4:HOUSE_WALL_H] = C['git_maru']
        v[fx, fy, plinth:plinth + 2] = C['git_maru_d']
        span = fx if side in ('n', 's') else fy
        #! **縦板の合わせ目**（3 vox おきの暗い筋。これが「縦板」の読みそのもの）。
        for p in range(span.start + 1, span.stop - 1, 3):
            if side in ('n', 's'):
                v[p:p + 1, fy, plinth:HOUSE_WALL_H - 4] = C['git_ita_d']
            else:
                v[fx, p:p + 1, plinth:HOUSE_WALL_H - 4] = C['git_ita_d']
        #! 隅の丸太柱（面の端に 1 本ずつ）。
        for p in (span.start, span.stop - 3):
            if side in ('n', 's'):
                v[p:p + 3, fy, plinth:HOUSE_WALL_H] = C['git_maru']
            else:
                v[fx, p:p + 3, plinth:HOUSE_WALL_H] = C['git_maru']
    #! 障子窓（南面だけ。**格子は 2 本**——高山の小屋なので開口は小さい）。
    if south:
        wx = ((x0 + x1) // 2) - 5
        wz = plinth + 9
        v[wx - 1:wx + 11, y1 - 2:y1, wz - 1:wz + 12] = C['git_maru_d']
        v[wx:wx + 10, y1 - 2:y1, wz:wz + 11] = C['git_shoji']
        v[wx + 3:wx + 4, y1 - 2:y1, wz:wz + 11] = C['git_maru_d']
        v[wx + 6:wx + 7, y1 - 2:y1, wz:wz + 11] = C['git_maru_d']
    return [('main', v, (0, 0, 0))]


def _house_roof_git(name):
    """**石置き板葺きの屋根**（`house_roof_*_git`）。

    **押さえ石が屋根の顔である。**板を並べただけでは高山の風に飛ぶので、山の小屋は
    屋根石を並べて押さえる（飛騨・木曽の板倉と同じ造り）。見下ろすカメラでは天面が
    絵の大半なので、**この石の粒が町の輪郭を決める**——茅（人里）・瓦（旧地獄街道）・
    檜皮（守矢）と遠目でも 1 発で分かれる。

    勾配は**浅い**（総高 24 vox）。石を載せる屋根は勾配を取れない。
    """
    key = _slice_of(name)
    north, south, west, east = SLICE_OUT[key]
    rng = rng_for(name)
    eave, top = 4, 24
    v = np.zeros((V, V, top), np.int16)
    height, hip = _roof_field(north, south, west, east, eave, top, curve=1.0)
    plank = rng.choice([C['git_ita'], C['git_ita_l'], C['git_ita_d']],
                       size=((V // 3) + 1, (V // 3) + 1), p=[0.44, 0.26, 0.30])
    for x in range(V):
        for y in range(V):
            h = int(height[x, y])
            v[x, y, 0:h] = C['git_ita_d']       # 軒先の断面
            if h > eave:
                v[x, y, eave:h] = plank[x // 3, y // 3]
            #! 板の合わせ目（軒と平行な暗い筋。3 段ごと）。
            if (h % 3) == 0:
                v[x, y, h - 1] = C['git_ita_d']
            if hip[x, y] or (h >= top):
                v[x, y, h - 1] = C['git_maru_d']   # 隅棟と棟の押さえ丸太
    #! **押さえ石**（3〜4 vox 角を 5〜9 個。天面へ 1 vox 載せる）。
    for _ in range(int(rng.integers(5, 10))):
        sx = int(rng.integers(1, V - 4))
        sy = int(rng.integers(1, V - 4))
        w = int(rng.integers(3, 5))
        shade = C['git_oshi'] if rng.random() < 0.6 else C['git_oshi_d']
        for x in range(sx, min(V, sx + w)):
            for y in range(sy, min(V, sy + w)):
                h = int(height[x, y])
                v[x, y, h - 1:min(top, h + 1)] = shade
    return [('main', v, (0, 0, 0))]


def koshiyane_git(name):
    """**越屋根**（`roof_vent`。敷地の建物の**真ん中のマスの屋根の上に 1 つだけ**立つ）。

    §4.5 ④「煙を立てる——屋根に越屋根（煙出し）を付け、白灰の煙の渦。**煙が偽天棚の
    署名**」。囲炉裏の煙を抜くために屋根へ載せる小さな屋根で、**火棚（＝天棚）の真上**に
    来る——「偽天棚」の語源解釈（§4.5「下に火があることの暗示」）がそのまま形になる所である。

    煙そのものは**ボクセルでは描かない**（プレハブに半透明の道が無い＝デザイン7 その2）。
    置く側がこの型の天面へ**蒸気の口**を 1 つ積み、雲の描き手が渦を出す。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 16), np.int16)
    #! 台（屋根に載る束。1 マスの真ん中 18 vox 角）。
    v[7:25, 7:25, 0:3] = C['git_maru_d']
    #! 胴（**簀の子**。煙が抜けるので板を透かす）。
    v[8:24, 8:24, 3:11] = C['git_ita_d']
    for p in range(9, 23, 3):
        v[p:p + 2, 8:24, 3:11] = C['git_ita']
        v[8:24, p:p + 2, 3:11] = C['git_ita']
    v[10:22, 10:22, 3:11] = C['git_ana']   # 中は煙で燻れた闇
    #! 小屋根（宝形。押さえ石を 1 つだけ載せる）。
    for i in range(4):
        w = 12 - (i * 2)
        v[16 - w:16 + w, 16 - w:16 + w, 11 + i:12 + i] = (
            C['git_ita'] if (i % 2) else C['git_ita_l'])
    v[14:19, 14:19, 15:16] = C['git_oshi'] if rng.random() < 0.7 else C['git_oshi_d']
    return [('main', v, (0, 0, 0))]


def _fence_git(name):
    """**丸太の横木の柵**（`fence_*_git`。前庭の外を向いた辺）。

    高原の囲いは板塀ではなく**横木 2 本の牧柵**である。雪で埋まる所に高い塀は建てない。
    """
    side = _slice_of(name)
    rng = rng_for(name)
    h = 26
    v = np.zeros((V, V, h), np.int16)
    lo, hi = _fence_sides(side, 5)

    def put(a0, a1, t0, t1, z0, z1, colour):
        if side in ('n', 's'):
            v[a0:a1, lo + t0:lo + t1, z0:z1] = colour
        else:
            v[lo + t0:lo + t1, a0:a1, z0:z1] = colour

    #! 杭（2 本）。
    for a0 in (2, 24):
        put(a0, a0 + 5, 1, 4, 0, h, C['git_maru'])
        put(a0 + 1, a0 + 4, 1, 4, h - 3, h, C['git_maru_d'])
    #! 横木（2 段）。
    for z0 in (9, 19):
        put(0, V, 1, 4, z0, z0 + 4, C['git_maru'])
        put(0, V, 1, 2, z0 + 3, z0 + 4, C['git_maru_d'])
    #! 3 枚に 1 枚は横木の間に枯れ枝を差してある（人の手の跡）。
    if rng.random() < 0.34:
        put(12, 14, 0, 5, 4, 20, C['git_miki'])
    return [('main', v, (0, 0, 0))]


def kokou_git(name):
    """**虹龍洞の坑口**（`terrain_props` の `ENTRANCE`。`>`(90,3) の 1 マス）。

    **これが §4.5 の外せない 1 点である**——「木の無い高原に空いた木枠の坑口と、
    そこから立ちのぼる煙。副題『尊き高原に穿つ洞』がそのまま絵になる」。

    形は §4.5 ③ のとおり: **横木＋二本柱の鳥居型の枠**（`#5A4535`）と**真っ黒な穴**
    （`#14161A`）。枠は坑道の支保工そのもので、**山肌へ 3 重に入れて奥へ続かせる**
    ——1 枚だけだと「額縁」に見えて奥行きが出ない。

    **材は太く採る。**初版は柱 4 vox・冠木 6 vox で、麓から見ると**岩肌に開いた
    ただの黒い四角**だった（合成フレームで実測）。1 マスの物が引きの絵で読めるかは
    **輪郭の太さ**で決まるので、柱 7 vox・冠木 14 vox・控えの斜材つきまで太らせる。

    冠木には**九曜紋**を焼く（§4.5 ⑦「板の側面に和文様を 1 つ焼く（青海波・網代・
    **九曜**）」）。九曜は**虹龍洞 4 面の文様**で、この穴の先がその 4 面である。

    **トロッコとレールは置かない**（§4.5 ⑧「原作に確認できない。置くなら創作と明記」）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 84), np.int16)
    #! ズリ（掘り出した捨石）を敷いた足元。
    v[:, :, 0:3] = C['git_kuro']
    v[4:28, 0:16, 2:3] = C['git_kuro_l']
    #! **穴**（マスの北半分。奥は闇）。
    v[6:26, 10:V, 3:58] = C['git_ana']
    #! 支保工 3 重（手前ほど明るい＝奥行き）。**手前の 1 枚だけ太い。**
    for i, (y0, th, tone) in enumerate(((10, 7, C['git_ki_l']), (19, 5, C['git_ki']),
                                        (27, 4, C['git_ki_d']))):
        y1 = y0 + th
        post = 7 - i
        v[6 - post:6, y0:y1, 3:58] = tone           # 西の柱
        v[26:26 + post, y0:y1, 3:58] = tone         # 東の柱
        v[6 - post:26 + post, y0:y1, 58:58 + (14 - (i * 3))] = tone   # 冠木
        if i == 0:
            #! 木口の陰（柱の中を 1 段暗くすると丸太の太さが出る）。
            v[0:2, y0:y1, 3:58] = C['git_ki_d']
            v[30:32, y0:y1, 3:58] = C['git_ki_d']
            v[0:V, y0:y1, 58:62] = C['git_ki_d']
    #! **控えの斜材**（柱の足元から外へ張る。坑口が「支えてある」ことの印）。
    for step in range(6):
        z0 = 6 + (step * 6)
        w = 6 - step
        v[0:w, 10:17, z0:z0 + 6] = C['git_ki']
        v[V - w:V, 10:17, z0:z0 + 6] = C['git_ki']
    #! **九曜紋**（手前の冠木の南面に焼く。中央 1 つ＋周り 8 つ）。
    cx, cz = 16, 65
    v[cx - 1:cx + 2, 9:10, cz - 1:cz + 2] = C['git_ki_d']
    for k in range(8):
        ang = 2.0 * math.pi * k / 8.0
        px = cx + int(round(math.cos(ang) * 8))
        pz = cz + int(round(math.sin(ang) * 4))
        if (0 <= px < V - 1) and (58 <= pz < 71):
            v[px:px + 2, 9:10, pz:pz + 2] = C['git_ki_d']
    #! 破風の板（枠の上に渡す 1 枚。雪と落石を切る）。押さえ石は小屋と同じ文法。
    v[0:V, 6:18, 72:77] = C['git_ita']
    v[0:V, 6:8, 72:77] = C['git_ita_d']
    v[4:28, 8:14, 77:79] = C['git_oshi']
    #! 枠の脇に積んだズリの山（掘った量がそのまま山になる。**柱を隠さない高さ**まで）。
    for x0 in (0, 28):
        hgt = int(rng.integers(5, 9))
        v[x0:x0 + 4, 0:9, 3:3 + hgt] = C['git_kuro']
        v[x0:x0 + 4, 2:7, (3 + hgt) - 1:3 + hgt] = C['git_kuro_l']
    #! **南向きへ反転**（`_face_south` の註記。奥が北・手前が南）。
    return _face_south([('main', v, (0, 0, 0))])


def zuri_git(name):
    """**坑口の足元**（`terrain_props` の `ENTRANCE` の地面）。掘り出した**ズリ**（捨石）。

    高原の草の中で**ここだけ黒い**——山を穿った証拠である。地面を替えないと坑口の
    周りが草のままになって、「穴を掘った」形跡が絵から消える。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    v[:, :, 0:3] = C['git_kuro']
    for x in range(0, V, 5):
        for y in range(0, V, 5):
            v[x:x + 4, y:y + 4, 2:3] = rng.choice(
                [C['git_kuro'], C['git_kuro_l'], C['git_reki_dd']], p=[0.5, 0.32, 0.18])
    return [('main', v, (0, 0, -3))]


def _face_south(parts):
    """**y を反転して南向きにする**（デザイン15。§5.19 の穴 3 番）。

    プレハブの **+y は南＝カメラ側**である（`house_wall` の「窓は南面だけ」が
    `y1-2:y1` ＝ y の大きいほうへ彫っているのがその証拠）。ところが門の 4 個は
    「奥（北）から手前（南）へ」書いてあったので、**入口の奥の闇が幕の手前に立って
    町の色を丸ごと隠していた**（合成フレームでは「赤い帯のついた黒い戸口」に見え、
    型の中を読むまで気づかなかった。`--prefab=` で 1 枚だけ描かせて分かった）。

    書き方を変えると読み合わせが崩れるので、**書くのは北向きのまま・最後に反転する**。
    """
    return [(name, vol[:, ::-1, :].copy(), off) for (name, vol, off) in parts]


def toba_git(name):
    """**虹龍洞の近くの賭場**（`BUILDING_0`＝駒草 山如。`a`(44,15)）。

    §4.5 ⑤「賭場は**緋の幕**＋**金の房**＋障子明かり」。山如は**緋色の衣・金のリボン・
    扇子・ドラゴンキセル**（賭場の胴元。煙草の煙で精神操作）で、緋と金は人物の色でもある。

    高原の小屋が板と石と草の色しか持たない町なので、**ここだけが色を持つ**
    ——15×5 マスの建物の南面に開いたこの 1 マスが、町でいちばん目立つ点になる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 80), np.int16)
    v[:, :, 0:3] = C['git_reki_d']
    v[6:26, 2:8, 2:3] = C['git_ita_d']       # 踏み板
    #! 素木の柱（両脇）。
    for x0 in (2, 25):
        v[x0:x0 + 5, 10:16, 3:64] = C['git_maru']
        v[x0 + 1:x0 + 4, 11:15, 3:64] = C['git_maru_d']
    #! 冠木と杉皮の庇（**手前＝南へ出す**。反転後にそう出る）。
    v[0:V, 9:17, 64:70] = C['git_maru_d']
    for i in range(4):
        v[0:V, max(0, 8 - (i * 2)):16 - (i * 2), 70 + (i * 2):72 + (i * 2)] = (
            C['git_ita'] if (i % 2) else C['git_ita_d'])
    #! **口の奥は闇**。初版は口いっぱいに障子を立てていて、麓から見ると
    #! **白い板の戸**にしか見えなかった（合成フレームで実測）——幕の下に白い面があると、
    #! 幕ではなく「白い扉の上の赤い庇」に読める。
    v[7:25, 16:V, 3:52] = C['git_ana']
    #! **障子明かり**は口の両脇の 4 vox だけ（部屋の灯りが漏れている所）。
    for x0 in (7, 21):
        v[x0:x0 + 4, 15:18, 6:44] = C['git_shoji']
        v[x0:x0 + 4, 15:18, 24:26] = C['git_maru_d']   # 中桟
    #! **緋の幕**（§4.5 ⑤）。**柱の外側へ、間口いっぱいに張る。**
    #!
    #! 初版は柱の間（`y12:15`）に垂らしていて、麓から見ると**上の一筋しか赤くなかった**
    #! ——焼き込みの陰影は**その型の中の囲まれ具合**で決まるので、両脇を柱に・上を庇に
    #! 挟まれた面は下へ行くほど暗くなり、赤が黒に沈む（合成フレームで実測）。
    #! **見せたい色は囲いの外へ出す。**裾も地面から 14 vox 上げて、床の陰から離す。
    v[2:30, 8:11, 14:62] = C['git_hi']
    for p in range(3, 30, 6):
        v[p:p + 2, 8:11, 14:62] = C['git_hi_d']    # 縫い目
    v[2:30, 8:11, 56:62] = C['git_kin']            # 上端の金の帯
    #! **金の房**（幕の下端に 3 本。垂らすと「賭場」の格になる）。
    for p in (5, 15, 25):
        v[p:p + 2, 7:11, 6:16] = C['git_kin']
        v[p:p + 2, 7:11, 4:8] = C['git_kin_l']
    #! 幕の裾が風で捲れている（3 枚に 1 枚。奥の闇と障子が覗く）。
    if rng.random() < 0.4:
        v[16:22, 8:11, 14:22] = 0
    #! **南向きへ反転**（`_face_south` の註記。奥が北・手前が南）。
    return _face_south([('main', v, (0, 0, 0))])


def chochin_git(name):
    """**賭場の前の提灯**（`entrance_flanks`。門の手前 3 マスへ並べる）。

    緋の幕と同じ緋と金で、**竿に 1 つずつ**吊るす。賭場は夜の商いなので、町でここだけ
    灯りが並ぶ——`lamp_step` を 0 にして街灯を立てないのは、**明かりの粗密で
    「人の集まる所」を作る**ためである。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 56), np.int16)
    v[13:19, 13:19, 0:3] = C['git_reki_dd']   # 根石
    v[14:18, 14:18, 3:48] = C['git_maru']     # 竿
    v[14:18, 14:18, 44:48] = C['git_maru_d']
    v[10:22, 14:18, 46:48] = C['git_maru_d']  # 腕木
    #! 提灯（緋の胴に金の輪。骨の筋を暗く）。
    cx, cy, cz = 11, 16, 34
    for z in range(cz, cz + 11):
        t = abs((z - (cz + 5)) / 6.0)
        r = int(round(5.0 * math.sqrt(max(0.0, 1.0 - (t * t)))))
        for x in range(cx - r, cx + r + 1):
            for y in range(cy - r, cy + r + 1):
                if (math.hypot(x - cx, y - cy) <= r) and (0 <= x < V) and (0 <= y < V):
                    v[x, y, z] = C['git_hi'] if ((z % 3) != 0) else C['git_hi_d']
    v[cx - 2:cx + 3, cy - 2:cy + 3, cz + 11:cz + 13] = C['git_kin']
    v[cx - 2:cx + 3, cy - 2:cy + 3, cz - 2:cz] = C['git_kin']
    v[cx - 1:cx + 2, cy - 1:cy + 2, cz + 4:cz + 7] = C['git_shoji']  # 火の芯
    if rng.random() < 0.5:
        v[cx - 1:cx + 2, cy - 1:cy + 2, cz - 5:cz - 2] = C['git_kin_l']  # 房
    return [('main', v, (0, 0, 0))]


def ajito_git(name):
    """**山童のアジト**（`BUILDING_1`＝山城 たかね。`b`(177,53)）。

    山の東の窪地に、**塀に囲まれた小屋**として置かれている（x168..187 y48..56。
    周りはハイマツ 69 マスで、山に囲まれて**歩いては行けない**——飛べる者の家である）。

    たかねは**迷彩柄・前髪が葉**で、**河童と技術提携**している（§4.5）。だから口は
    「隠す」ものと「機械」の 2 つで作る: **迷彩の垂れ布**と葉のついた蔓で入口を覆い、
    柱に**河童の歯車と銅管**を 1 つずつ噛ませる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 68), np.int16)
    v[:, :, 0:3] = C['git_reki_dd']
    #! 丸太を組んだだけの粗い枠。
    for x0 in (1, 26):
        v[x0:x0 + 5, 11:17, 3:52] = C['git_maru']
        v[x0 + 1:x0 + 4, 12:16, 3:52] = C['git_maru_d']
    v[0:V, 10:18, 52:58] = C['git_maru']
    v[0:V, 11:17, 55:58] = C['git_maru_d']
    #! 奥は闇（洞のような住処）。
    v[6:26, 13:V, 3:50] = C['git_ana']
    #! **迷彩の垂れ布**（継ぎ接ぎの布。塊ごとに色を振る）。
    for p in range(6, 26, 4):
        for z in range(20, 52, 6):
            v[p:p + 4, 12:15, z:z + 6] = rng.choice(
                [C['git_meisai'], C['git_meisai_d'], C['git_kusa_d']], p=[0.4, 0.36, 0.24])
    #! 葉のついた蔓（枠の上から垂らす。前髪の葉と同じ緑）。
    for _ in range(int(rng.integers(4, 8))):
        x = int(rng.integers(2, V - 2))
        drop = int(rng.integers(6, 18))
        v[x:x + 1, 10:12, 52 - drop:52] = C['git_ha']
        v[x - 1:x + 2, 9:12, 52 - drop:54 - drop] = C['git_ha']
    #! **河童の歯車と銅管**（技術提携の印。西の柱に噛ませる）。
    for k in range(8):
        ang = 2.0 * math.pi * k / 8.0
        px = 3 + int(round(math.cos(ang) * 4))
        pz = 30 + int(round(math.sin(ang) * 4))
        v[max(0, px):px + 2, 9:11, pz:pz + 2] = C['iron']
    v[1:6, 9:11, 28:33] = C['iron_l']
    v[27:30, 8:12, 12:40] = C['iron']
    v[27:30, 8:12, 24:27] = C['iron_l']
    #! **南向きへ反転**（`_face_south` の註記。奥が北・手前が南）。
    return _face_south([('main', v, (0, 0, 0))])


def sakaba_git(name):
    """**酒場**（`BUILDING_2`＝妖怪の酔客達。`c`(15,29)）。

    盆地の西にある 6×5 マスの小屋の**東面**の口である（＝`_ew` の姿勢で立つ）。
    賭場の緋と金に対して、こちらは**縄のれんと赤提灯**——同じ「人の集まる所」でも、
    幕を垂らす店（賭場）と縄を垂らす店（酒場）で格が分かれる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 72), np.int16)
    v[:, :, 0:3] = C['git_reki_d']
    for x0 in (2, 25):
        v[x0:x0 + 5, 11:16, 3:56] = C['git_maru']
        v[x0 + 1:x0 + 4, 12:15, 3:56] = C['git_maru_d']
    v[0:V, 10:17, 56:62] = C['git_maru_d']
    #! 杉皮の庇（手前＝南へ出す）。
    for i in range(4):
        v[0:V, max(0, 9 - (i * 2)):16 - (i * 2), 62 + (i * 2):64 + (i * 2)] = (
            C['git_ita'] if (i % 2) else C['git_ita_d'])
    #! 口の奥は闇。障子は両脇の 4 vox だけ（賭場と同じ直し。§5.19 の穴 3 番）。
    v[7:25, 16:V, 3:50] = C['git_ana']
    for x0 in (7, 21):
        v[x0:x0 + 4, 15:18, 6:42] = C['git_shoji']
        v[x0:x0 + 4, 15:18, 22:24] = C['git_maru_d']
    #! **縄のれん**（1 本ずつ長さを違える。揃えると簾に見える）。
    #! 幕と同じく**柱の外側**へ吊る（囲いの中に置くと陰に沈む＝§5.19 の穴 3 番）。
    for p in range(4, 29, 2):
        drop = int(rng.integers(16, 26))
        v[p:p + 1, 9:12, 54 - drop:54] = C['git_nawa']
    v[0:V, 9:12, 54:57] = C['git_maru_d']          # 縄を吊る竿
    #! 赤提灯 2 つ（軒の両側）。
    for cx in (6, 25):
        for z in range(38, 48):
            t = abs((z - 43) / 5.5)
            r = int(round(4.0 * math.sqrt(max(0.0, 1.0 - (t * t)))))
            for x in range(cx - r, cx + r + 1):
                for y in range(11 - r, 11 + r + 1):
                    if (0 <= x < V) and (0 <= y < V) and (math.hypot(x - cx, y - 11) <= r):
                        v[x, y, z] = C['git_aka'] if ((z % 3) != 0) else C['git_hi_d']
        v[cx - 1:cx + 2, 10:13, 48:56] = C['git_nawa']
        v[cx - 2:cx + 3, 9:14, 36:38] = C['git_maru_d']
    #! 空の徳利を並べた台（酔客の店）。
    if rng.random() < 0.7:
        v[9:23, 4:9, 3:8] = C['git_ita_d']
        for p in range(10, 22, 4):
            v[p:p + 3, 5:8, 8:14] = C['git_shoji']
            v[p + 1:p + 2, 6:7, 14:16] = C['git_shoji']
    #! **南向きへ反転**（`_face_south` の註記。奥が北・手前が南）。
    return _face_south([('main', v, (0, 0, 0))])


def _rampart_git(name):
    """**空積みの石垣**（`palisade_git`）。積んだだけの石の壁。

    地図に塀は 1 マスも無い（あるのは岩山と 6 つの敷地だけ）が、**実機の読みは既知のマスから
    立つ**ので、敷地の壁を部分的にしか見ていない段で丸太の塀が出ることがある
    （廃洋館・永遠亭と同じ保険）。高原に丸太は運べないので、そこは石で受ける。
    """
    rng = rng_for(name)
    h = 54
    v = np.zeros((V, V, h), np.int16)
    #! 石を 1 個ずつ積む（**段ごとに継ぎ目をずらす**＝空積みの顔）。
    z = 0
    row = 0
    while z < h:
        step = int(rng.integers(6, 10))
        off = (row % 2) * 4
        for x in range(-8, V + 8, 9):
            x0 = max(0, x + off)
            x1 = min(V, x + off + 8)
            if x0 >= x1:
                continue
            v[x0:x1, :, z:min(h, z + step)] = rng.choice(
                [C['git_reki_d'], C['git_reki'], C['git_reki_dd'], C['git_reki_l']],
                p=[0.36, 0.28, 0.24, 0.12])
        z += step
        row += 1
    #! 天端は平らに均す（積み石の最上段だけ揃えると「積んだ」に見える）。
    v[:, :, h - 2:h] = C['git_reki']
    for x in range(0, V, 6):
        if rng.random() < 0.4:
            v[x:x + 5, :, h - 2:h] = C['git_reki_d']
    return [('main', v, (0, 0, 0))]


def _tower_cairn_git(name):
    """**ケルン**（`watchtower_git`。塀の四隅に立つもの）。

    高原に木の見張り台は立たない。稜線に積むのは**道標のケルン**である
    ——登る人が石を 1 つずつ足していく塔で、高山の絵として塀の隅に立つ。
    高さ 2.4 マス（塀 1.7 マスより頭ひとつ高い＝やぐらの約束は守る）。
    """
    rng = rng_for(name)
    h = 76
    v = np.zeros((V, V, h), np.int16)
    for z in range(0, h, 4):
        t = z / float(h)
        r = int(round(13.0 * (1.0 - (t * 0.72))))
        cx = 16 + int(rng.integers(-1, 2))
        cy = 16 + int(rng.integers(-1, 2))
        shade = rng.choice([C['git_reki_d'], C['git_reki'], C['git_reki_dd'], C['git_reki_l']],
                           p=[0.34, 0.30, 0.24, 0.12])
        for x in range(max(0, cx - r), min(V, cx + r + 1)):
            for y in range(max(0, cy - r), min(V, cy + r + 1)):
                if math.hypot(x - cx, y - cy) <= r:
                    v[x, y, z:min(h, z + 4)] = shade
    #! 天辺の 1 石（いちばん上は必ず 1 個）。
    v[14:19, 14:19, h - 5:h] = C['git_reki_l']
    #! 目印の棒（半分に立つ。雪でも見えるように）。
    if rng.random() < 0.5:
        v[15:18, 15:18, h - 5:h + 0] = C['git_miki']
    return [('main', v, (0, 0, 0))]


# ------------------------------------------------------------------- 目録
def static_part(motion=None, wind_k=0.0):
    return [{'name': 'main', 'voxels': 'main', 'grounded': True,
             'motion': motion or {'kind': 'static'}, 'wind_k': wind_k}]


def door_parts():
    return [
        {'name': 'frame', 'voxels': 'frame', 'grounded': True,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
        {'name': 'panel', 'voxels': 'panel', 'parent': 'frame', 'grounded': True,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
    ]


def flame_parts():
    # 炎は 2 枚を別の周期・位相の振り子で（合成でちらつきに見える）。
    # 風に頼らない（地下は無風。hd2d_app.cpp の「洞窟の草が揺れると嘘くさい」）。
    return [
        {'name': 'flame_a', 'voxels': 'flame_a', 'grounded': False,
         'pivot': [16.0, 16.0, 30.0],
         'motion': {'kind': 'pendulum', 'axis': 'x', 'amplitude': 7.0,
                    'period': 0.9, 'phase': 0.0, 'damping': 0.0},
         'wind_k': 0.0},
        {'name': 'flame_b', 'voxels': 'flame_b', 'grounded': False,
         'pivot': [16.0, 16.0, 31.0],
         'motion': {'kind': 'pendulum', 'axis': 'y', 'amplitude': 9.0,
                    'period': 0.63, 'phase': 1.7, 'damping': 0.0},
         'wind_k': 0.0},
    ]


# name → (builder, jsonc の parts, 注記)
CATALOG = {}


def add_variants(prefix, count, builder, note, parts_decl=None):
    """**基本デザインは 1 つ、乱数の種だけ違う変種を `count` 枚**（2026-08-09 に決めた
    「各ブロック色調と基本デザインは統一したうえで 10 種類くらいのランダム性が欲しい」）。

    種は名前から決まる（`rng_for`）ので、`wall_stone_07` は誰が何度作っても同じ形になる。
    置く側は対応表の集合からマスの種で 1 枚選ぶ（`terrain_view.cpp`）。
    """
    for i in range(1, count + 1):
        name = '%s_%02d' % (prefix, i)
        CATALOG[name] = (builder, parts_decl if parts_decl is not None else static_part(),
                         '%s（変種 %d/%d）' % (note, i, count))


