#: 下から見ると漏斗が垂れて見える。ここに名前を書いたプレハブには `.jsonc` へ
#: `hide_unseen_from_above` を立て、画面側が**空から届かない面を作らない**ようにする
#: （規則は `hd2d/voxel/greedy_mesher.h` の `mesh_model()`）。
