# ---- 町（P10 第 2 期・設計書 §10）----
# 建物は**壁と屋根を分けた 9 スライス**。階数は壁を積む枚数で決まるので、
# 2 階建てのための素材は要らない（置く側が 2 枚重ねる）。
for _slice in HOUSE_SLICES:
    CATALOG['house_wall_' + _slice] = (
        house_wall, static_part(), '建物の壁 1 層（寄棟 9 スライスの %s）' % _slice)
    CATALOG['house_roof_' + _slice] = (
        house_roof, static_part(), '寄棟屋根（9 スライスの %s）' % _slice)
for _side in ('n', 's', 'w', 'e'):
    CATALOG['fence_' + _side] = (
        town_fence, static_part(), '敷地の柵（%s 側の 1 辺）' % _side)
add_variants('ground_path', 5, ground_path, '踏み固めた土の通り道')
add_variants('ground_turf', 5, ground_turf, '短めの草（土が透ける）')
add_variants('palisade', 3, palisade, '丸太を組み合わせた塀')
for _icon_key in sorted(ICONS.keys()):
    CATALOG['sign_' + _icon_key] = (
        signboard, sign_parts(), '1 マス幅の吊り看板（絵: %s。片足・常に南を向く）' % _icon_key)

# ---- 町ごとの意匠（2026-08-09 に決めた「街ごとの雰囲気の変化」）----
#
# **同じ枠に別の材を入れるだけ**なので、素材の枚数も置き方も辺境の地と揃っている
# （壁 9・屋根 9・地面 5+5・柵 4・塀 3・やぐら 1・前庭 1 ＝ 1 意匠あたり 37 個）。
# 看板と門は**統一**（決めたこと。町が変わっても店の読み方は変わらないほうがよい）。
_STYLE_NOTE = {'jin': '人里（焼杉の腰板と土壁・茅葺き・障子）',
    'tel': 'テルモラ（木骨漆喰・藁葺き・半舗装・乱石積み）',
               'mor': 'モリバント（切石と漆喰・瓦・敷石・切石の城壁）',
               'ten': '天狗の里（白漆喰の真壁・杉皮葺き・石畳・練塀）',
               'kyu': '旧地獄街道（黒い下見板の町屋・黒瓦・提灯）',
               'koma': '紅魔館（家はモリバントの絵・鉄柵の塀・レンガの監視塔・レンガ道）',
               'hak': '博麗神社（脇の小屋は人里の造り・参道は自然石・境内は草地）',
               'kap': '河童のバザー（板とトタンの継ぎ足し・波トタンの片流れ・鉄板の道）',
               'ein': '永遠亭（苔と竹の落ち葉・飛び石の道・竹垣）',
               'kor': '香霖堂（森の下草と落ち葉・轍の小道・玉垣の石柱）',
               'myo': '命蓮寺（掃き清めた砂利・石畳の参道・白漆喰の築地塀）',
               'kir': '霧雨魔法店（湿った苔と切株・踏み分け道・朽ちた板塀）',
               'hai': '廃洋館（荒れた庭の下草・苔むした砂利道・崩れた石塀と鉄柵）',
               'moy': '守矢神社（山の下草と平石の参道・素木の玉垣・檜皮葺き）',
               'hig': '彼岸（灰褐の土に彼岸花・白砂の参道・白漆喰の築地塀・黒瓦）',
               'git': '偽天棚（高原の草と砂礫・駒草・石場建ての板壁・石置き板葺き）'}
for _style in TOWN_STYLES:
    _note = _STYLE_NOTE[_style]
    for _slice in HOUSE_SLICES:
        CATALOG['house_wall_%s_%s' % (_slice, _style)] = (
            house_wall, static_part(), '%s の建物の壁 1 層（%s）' % (_note, _slice))
        CATALOG['house_roof_%s_%s' % (_slice, _style)] = (
            house_roof, static_part(), '%s の寄棟屋根（%s）' % (_note, _slice))
    for _side in ('n', 's', 'w', 'e'):
        CATALOG['fence_%s_%s' % (_side, _style)] = (
            town_fence, static_part(), '%s の敷地の柵（%s 側の 1 辺）' % (_note, _side))
    add_variants('ground_path_' + _style, 5, ground_path, '%s の通り道' % _note)
    add_variants('ground_turf_' + _style, 5, ground_turf, '%s の開けた地面' % _note)
    add_variants('palisade_' + _style, 3, palisade, '%s の町を囲む塀' % _note)
    CATALOG['watchtower_' + _style] = (
        watchtower, static_part(), '%s の塀の四隅に立つ塔' % _note)
    CATALOG['yard_ground_' + _style] = (
        yard_ground, static_part(), '%s の前庭の地面' % _note)

CATALOG['house_light_jin'] = (
    house_light, static_part(), '人里の灯り（障子の白い面が光る）')
CATALOG['house_entrance_jin'] = (
    house_entrance, static_part(), '人里の玄関（見た目だけ。入口を持たない敷地の南面に立てる）')
CATALOG['gate_great_jin'] = (
    gate_great_jin, static_part(), '人里の大門（南の土塀に組み込む、扉を閉めた棟門）')
CATALOG['statue_dragon_jin'] = (
    statue_dragon_jin, static_part(), '人里の龍神の石像（目が青い。BUILDING_4）')
CATALOG['nobori_ten'] = (
    nobori_ten, static_part(), '天狗の里の幟（白地に赤黒。街路樹の口で道沿いに立つ）')
# 天狗の里の建物を人里の造りの色違いへ（2026-08-18 その3）。灯りと玄関も人里と同じ形で
# 名前だけ分ける——引く側は styled() なので、名前が無いとその物じたいが出ない。
CATALOG['house_light_ten'] = (
    house_light, static_part(), '天狗の里の灯り（障子の白い面が光る。人里と同じ割り付け）')
CATALOG['house_entrance_ten'] = (
    house_entrance, static_part(), '天狗の里の玄関（人里と同じ引き違い戸）')
CATALOG['stone_lantern'] = (
    stone_lantern, static_part(), '石灯籠（春日形・高さ 2 マス。祠の四隅や参道に）')
CATALOG['stone_lantern_flame'] = (
    stone_lantern_flame, static_part(), '石灯籠の灯（火袋の外に貼る発光板。夜だけ置く）')
CATALOG['torii'] = (
    torii, static_part(), '素木の鳥居（神明鳥居・反りなし。人里の龍神の祠の入口）')
CATALOG['house_light_kyu'] = (
    house_light, static_part(), '旧地獄街道の灯り（軒下の提灯と格子窓が光る）')
#! 玄関は人里のものと同じ形（黒木の引き違い戸は町屋にもそのまま合う）。名前だけ分ける
#! ——引く側は styled("house_entrance") なので、名前が無いと玄関そのものが出ない。
CATALOG['house_entrance_kyu'] = (
    house_entrance, static_part(), '旧地獄街道の玄関（人里と同じ黒木の引き違い戸）')
CATALOG['lamp_post_kyu'] = (
    lamp_post_kyu, static_part(), '旧地獄街道の街灯（提灯掛け。黒木の竿から朱提灯を提げる）')
CATALOG['lamp_flame_kyu'] = (
    lamp_flame_kyu, static_part(), '旧地獄街道の街灯の灯（紙の外に貼る発光殻。夜だけ置く）')
# 岩肌と岩天井（2026-08-18 その3「街全体を巨大な黒い岩山で覆い、屋根としてしまいたい」）。
# 岩山の全段（crag_*_kyu）を**同じ岩肌 6 マス**で置く——刳り抜いた山の内壁は、外から
# 見上げる山と違って段の裾を持たない（通りに面した壁は垂直に 6 マス立つ）。
for _tier in CRAG_TIERS:
    add_variants('crag_%s_kyu' % _tier, 2, _rock_face_kyu,
                 '旧地獄街道の岩肌（刳り抜いた山の内壁 6 マス。%s 段も同じ材）' % _tier)
add_variants('cave_roof_kyu', 3, cave_roof_kyu,
             '旧地獄街道の岩天井（町の全マスの z=6 マスに敷く蓋。黒い山の背）')
# 山塊とガス灯（2026-08-18 その3「ゴツゴツとした凹凸のある大きな岩山」「交差点毎にガス灯」）。
# base は岩屑の最低段——ノイズの低い所も含めて全マスに敷き、平らな天面を消す（同 その3 の指摘）。
# peak はそびえる頂（同「思い切りがたらないぞ」）。
for _tier in ('base', 'low', 'mid', 'high', 'peak'):
    add_variants('cave_mound_kyu_%s' % _tier, 2, _cave_mound_kyu,
                 '旧地獄街道の山塊（岩天井の上の %s 段。値ノイズで複数マスの山になる）' % _tier)
CATALOG['gaslamp_kyu'] = (
    gaslamp_kyu, static_part(), '旧地獄街道のガス灯（交差点の鉄の街灯・2 マス。点光源つき）')
CATALOG['gaslamp_kyu_flame'] = (
    gaslamp_kyu_flame, static_part(), 'ガス灯の火（火屋の中の芯柱。別体。昼も点く）')

# ---- 博麗神社（デザイン6・2026-08-19）----
# 社殿（277 マスの塊）は屋敷の読みで建てる。壁は 9 スライス × 変種 3（開口を振る）、
# 屋根は**切妻**——斜面 2 姿勢＋軒先 2 姿勢＋棟＋妻壁 4 面を、置く側（terrain_view の
# 切妻モード）が「棟までの段数」で積む。朱の大鳥居は参道の柱の塊に半身ずつ。
for _slice in HOUSE_SLICES:
    add_variants('manor_wall_%s_hak' % _slice, 3, manor_wall_hak,
                 '博麗神社の拝殿の壁（%s。素木の柱＋生成りの土壁・縁側の濡縁つき）' % _slice)
