# ---- 河童のバザー（デザイン7・2026-08-19）----
# 中庭を囲む 3 マス幅の帯 6 件を屋敷として読み、**波トタンの片流れ**を載せる。
# 斜面は 4 姿勢（軒の向き）＋軒のマス 4 姿勢、段の差で開いた縦面は妻壁（sz で伸縮）。
# 崖（岩山の 4 段）は**玄武岩の柱状節理**——六角の格子で柱に割り、天面をモザイクにする。
for _slice in HOUSE_SLICES:
    add_variants('manor_wall_%s_kap' % _slice, 3, manor_wall_kap,
                 '河童の工房の壁（%s。板とブリキの継ぎ足し・緑青の配管つき）' % _slice)
for _side in ('n', 's', 'w', 'e'):
    # **姿勢ごとに変種 3 枚**。1 個だと錆の斑がマスの格子に揃って、20 マス続く長屋が
    # 同じ模様の連鎖に見えた（合成フレームで実測）。置く側はマスの種で 1 枚選ぶ。
    add_variants('manor_roofslope_%s_kap' % _side, 3, manor_roofshed_kap,
                 '工房の片流れの斜面（軒は %s）' % _side)
    add_variants('manor_roofeave_%s_kap' % _side, 3, manor_roofshed_kap,
                 '工房の片流れの軒のマス（%s。軒先 8 vox つき）' % _side)
    CATALOG['manor_gable_%s_kap' % _side] = (
        manor_gable_kap, static_part(), '工房の妻壁（%s 面。段の差を塞ぐトタン。sz で伸縮）' % _side)
for _tier in CRAG_TIERS:
    add_variants('crag_%s_kap' % _tier, 2, crag_kap,
                 '玄武の沢の柱状節理（%s 段。六角柱の縦縞と発光苔）' % _tier)
# ---- 配管（デザイン7 その2。こう決めた——「やけくそって程に配管を」）----
# 地面の本管は行と列に走らせるので**マスいっぱい**に通してある（隣と繋がって列になる）。
# 壁の管は屋敷に接したマスに必ず置く横引き（`pipe_wall_*`）と、そこへ弁と噴気の口を足した
# 立ち上がり（`pipe_riser_*`）の 2 種——**横引きの寸法は同じ**なので線が切れない。
for _dir in ('ns', 'ew'):
    add_variants('pipe_run_%s_kap' % _dir, 3, pipe_run_kap,
                 '地面を横切る本管（%s。受け台・継ぎ手・錆）' % _dir)
add_variants('pipe_cross_kap', 2, pipe_cross_kap,
             '配管の継ぎ手（南北と東西が出会うマス。噴気管つき＝蒸気の口）')
for _side in ('n', 's', 'w', 'e'):
    add_variants('pipe_wall_%s_kap' % _side, 2, pipe_wall_kap,
                 '壁に添う横引きの管（屋敷が %s 側のマス）' % _side)
    add_variants('pipe_riser_%s_kap' % _side, 2, pipe_riser_kap,
                 '壁の立ち上がり（%s 側。弁と噴気の口つき）' % _side)
CATALOG.update({
    'stall_kap': (stall_kap, static_part(), '河童の露店（藍の天幕・胡瓜・前垂れ。道沿いに立つ）'),
    'lamp_post_kap': (lamp_post_kap, static_part(), '河童のバザーの街灯（鉄パイプの竿と裸電球）'),
    'lamp_flame_kap': (lamp_flame_kap, [
        {'name': 'flame_a', 'voxels': 'flame_a', 'grounded': False,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
    ], '裸電球の灯（電気なので揺れない。自発光は置く側が乗せる）'),
    'koubou_kap': (koubou_kap, koubou_parts(),
                   'エンジニアギルド（BUILDING_2。にとりの工房。3×2 マス・**回る歯車 2 枚**）'),
    'sakaba_kap': (sakaba_kap, static_part(),
                   '河童の酒場（BUILDING_0。トタンの庇・藍の暖簾・樽・裸電球の連なり）'),
    'house_light_kap': (house_light, static_part(), '沢の小屋の灯り（人里と同じ割り付け）'),
    'house_entrance_kap': (house_entrance, static_part(), '沢の小屋の玄関（人里と同じ引き違い戸）'),
})

# ---- 永遠亭（デザイン8・2026-08-19）----
# 壁の塊は**1 成分 960 マス・外接 95×21・充填 0.48**の大屋敷。切妻（外接矩形で測る）でも
# 片流れ（棟を持たない）でも組めないので、**マスごとの距離変換で入母屋**を積む
# （`TownStyle::manor_roof_irimoya`）。斜面と軒は片流れと同じ 4 姿勢の名前を使い、
# 棟は**東西と南北の 2 本**、段の差で開いた縦面は破風（`manor_gable_*` を sz で伸縮）。
for _slice in HOUSE_SLICES:
    add_variants('manor_wall_%s_ein' % _slice, 3, manor_wall_ein,
                 '永遠亭の壁（%s。石の基壇＋濡縁＋腰板＋白い障子の帯・1.5 マス）' % _slice)
for _side in ('n', 's', 'w', 'e'):
    # **姿勢ごとに変種 2 枚**。大屋根は 50 マスを超えて続くので、1 個だと苔の斑が
    # マスの格子に揃う（河童の長屋で踏んだ罠。置く側はマスの種で 1 枚選ぶ）。
    add_variants('manor_roofslope_%s_ein' % _side, 2, manor_roofslope_ein,
                 '永遠亭の檜皮葺きの斜面（軒は %s）' % _side)
    add_variants('manor_roofeave_%s_ein' % _side, 2, manor_roofslope_ein,
                 '永遠亭の檜皮葺きの軒のマス（%s。深い軒 10 vox つき）' % _side)
    CATALOG['manor_gable_%s_ein' % _side] = (
        manor_gable_ein, static_part(),
        '永遠亭の破風（%s 面。木連格子と破風板。sz で段の高さへ伸縮）' % _side)
# 竹は**風で揺れる**（`wind_k` は幹の高さで自動的にしなる＝設計書 §8.2-3）。
# 木（`tree_*`）は静止のままにしてある——揺らすのは竹だけの記号にする。
add_variants('bamboo_ein', 6, bamboo_ein,
             '迷いの竹林の竹（01=4.1 マス 〜 06=7.0 マス。低いほど株が太る）',
             parts_decl=static_part(motion={'kind': 'wind'}, wind_k=0.35))
CATALOG.update({
    'manor_rooftop_ein': (manor_rooftop_ein, static_part(),
                          '永遠亭の平らな大棟（段の上限に達したマス。斜面を並べると鋸歯になる）'),
    'manor_ridge_ein': (manor_ridge_ein, static_part(), '永遠亭の箱棟（東西へ通る棟）'),
    'manor_ridge_ns_ein': (manor_ridge_ein, static_part(), '永遠亭の箱棟（南北へ通る棟）'),
    # 街灯は**石灯籠**（人里の祠で作ったものをそのまま使う。竹林の道に置く）。
    'lamp_post_ein': (stone_lantern, static_part(), '永遠亭の石灯籠（春日形。2 マス）'),
    # 灯は**接地しない**（火袋は 2 マス目の高さにある）。石灯籠の火は揺れない
    # ——`stone_lantern_flame` は窓の外に貼る板 4 枚で、振り子に割っていない。
    'lamp_flame_ein': (stone_lantern_flame, [
        {'name': 'main', 'voxels': 'main', 'grounded': False,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
    ], '石灯籠の灯（火袋の窓の外に貼る板。自発光は置く側が乗せる）'),
    'genkan_ein': (genkan_ein, static_part(),
                   '永遠亭の大玄関（BUILDING_1＝輝夜。唐破風の車寄せと沓脱石）'),
    'shinryo_ein': (shinryo_ein, static_part(),
                    '永遠亭の診療所（BUILDING_0＝永琳。白い暖簾と薬箱の土間）'),
})

# ---- 香霖堂（デザイン9・2026-08-19）----
# 壁の塊は 241 マス 34×10 の 1 枚岩で、置く側が**南から食い込む切れ込み**（実測 x112..114）
# で 3 つに割ってから引く（`TownStyle::manor_court_split`）。材はその棟の札で分かれる:
# **主＝瓦の店舗（`_kor`）／別棟＝白い土蔵（`_kra`）／渡り廊下（`_wat`）**。
# 屋根の型（斜面・軒・棟・大棟）は店舗と土蔵の 2 組だけ焼き、渡り廊下は**店舗の瓦へ落ちる**
# ——3 マス幅の廊下に専用の瓦を焼いても、見下ろしで違いが出ない。
for _slice in HOUSE_SLICES:
    add_variants('manor_wall_%s_kor' % _slice, 3, manor_wall_kor,
                 '香霖堂の店舗の壁（%s。焼杉の腰板＋障子と連子の帯・1.7 マス）' % _slice)
    add_variants('manor_wall_%s_kra' % _slice, 2, manor_wall_kor,
                 '香霖堂の土蔵の壁（%s。なまこ壁の腰＋塗り込めの白漆喰・2.4 マス）' % _slice)
    CATALOG['manor_wall_%s_wat_01' % _slice] = (
        manor_wall_kor, static_part(),
        '香霖堂の渡り廊下の壁（%s。板の腰と連子だけ・1.2 マス）' % _slice)
for _side in ('n', 's', 'w', 'e'):
    for _wing, _what in (('kor', '店舗の桟瓦'), ('kra', '土蔵の本瓦')):
        add_variants('manor_roofslope_%s_%s' % (_side, _wing), 2, manor_roofslope_kor,
                     '香霖堂の%sの斜面（軒は %s）' % (_what, _side))
        add_variants('manor_roofeave_%s_%s' % (_side, _wing), 2, manor_roofslope_kor,
                     '香霖堂の%sの軒のマス（%s。土蔵は塗り込めの白い軒）' % (_what, _side))
        CATALOG['manor_gable_%s_%s' % (_side, _wing)] = (
            manor_gable_kor, static_part(),
            '香霖堂の破風（%s 面・%s。sz で段の高さへ伸縮）' % (_side, _wing))
CATALOG.update({
    'manor_rooftop_kor': (manor_rooftop_kor, static_part(), '香霖堂の平らな大棟（店舗）'),
    'manor_rooftop_kra': (manor_rooftop_kor, static_part(), '香霖堂の平らな大棟（土蔵）'),
    'manor_ridge_kor': (manor_ridge_kor, static_part(), '香霖堂の熨斗瓦の棟（東西へ通る棟）'),
    'manor_ridge_ns_kor': (manor_ridge_kor, static_part(), '香霖堂の熨斗瓦の棟（南北へ通る棟）'),
    'manor_ridge_kra': (manor_ridge_kor, static_part(), '土蔵の棟（東西。塗り込めの白い線）'),
    'manor_ridge_ns_kra': (manor_ridge_kor, static_part(), '土蔵の棟（南北。塗り込めの白い線）'),
    'mise_kor': (mise_kor, static_part(),
                 '香霖堂の店の口（BUILDING_0＝霖之助。洋風の開き戸＋真鍮のノブ＝異国風の正体）'),
    'kura_kor': (kura_kor, static_part(),
                 '香霖堂の工房の口（BUILDING_8。土蔵の観音扉と瓦の庇。北向きなので天面が顔）'),
    'byou_kor': (byou_kor, static_part(),
                 '神霊廟出張所の口（BUILDING_3。朱の柱と緑青の梁・反りの強い庇・香炉）'),
    'lamp_post_kor': (lamp_post_kor, static_part(), '香霖堂の街灯（木の柱に角行灯）'),
    'lamp_flame_kor': (lamp_flame_kor, [
        {'name': 'main', 'voxels': 'main', 'grounded': False,
         'motion': {'kind': 'static'}, 'wind_k': 0.0},
    ], '角行灯の灯（紙の面の内側。自発光は置く側が乗せる）'),
})
add_variants('junk_kor', 4, junk_kor,
             '戸口の外のガラクタ（外の世界から流れ着いた道具の山。§4.1 ⑥）')

# ---- 命蓮寺（デザイン10・2026-08-19）----
# 本堂は **756 マス 39×21・充填 0.92** の大伽藍で、屋敷として読む（`manor_min_cells: 200`）。
# 宿坊 119 マスと店の 5 マスは**敷地の条件に収まる**ので従来の家並みの口（`house_*_myo`）で建つ。
# 孤立した 1 マスの壁 138 個は**千体地蔵**（`lone_wall_prop`）、南の塀の切れ目の両脇は
# **山門**（`great_gate` ＋ flank）、本堂の口の前には**赤い幟の列**（`entrance_flanks`）。
