# ---- 魔法の森の 2 軒（デザイン11 その2・2026-08-20）----
# 町 10 の森の塊 2 つは、クエストの本文では**名前のある家**だった（`town_styles.jsonc`
# の町 10 の節に出典）。同じ洋館の型を 2 つの材で撃ち分ける——`_ari` は住んでいる家、
# `_yur` は朽ちた空き家である。どちらも**マスで名指して**屋敷として読ませる（`plots`）。
for _kind in ('ari', 'yur'):
    _who = 'アリスの家' if _kind == 'ari' else '森の幽霊洋館'
    for _slice in HOUSE_SLICES:
        add_variants('manor_wall_%s_%s' % (_slice, _kind), 2, manor_wall_you,
                     '%sの壁（%s。下見板・1.5 マス。_02 は窓）' % (_who, _slice))
    for _side in ('n', 's'):
        add_variants('manor_roofslope_%s_%s' % (_side, _kind), 2, manor_roofslope_you,
                     '%sの急勾配のスレート（軒は %s）' % (_who, _side))
        add_variants('manor_roofeave_%s_%s' % (_side, _kind), 3, manor_roofslope_you,
                     '同（%s の軒のマス。軒先 8 vox。_02 だけ出窓／穴）' % _side)
    for _side in ('n', 's', 'w', 'e'):
        CATALOG['manor_gable_%s_%s' % (_side, _kind)] = (
            manor_gable_you, static_part(),
            '%sの妻壁（%s 面。竪羽目＋丸い屋根裏窓。sz で伸縮）' % (_who, _side))
    CATALOG['manor_ridge_%s' % _kind] = (
        manor_ridge_you, static_part(), '%sの棟包み' % _who)
add_variants('doll_ari', 3, doll_ari,
             '上海人形（アリスの家の戸口の脇。金の髪と青白の服で読ませる）')
add_variants('crate_yur', 2, crate_yur,
             '河童の木箱（幽霊洋館の戸口の脇。Quest5 の決着の伏線）')
CATALOG.update({
    'mon_ari': (mon_ari, static_part(),
                'アリスの家の戸口（北面。白い切妻のポーチと石段＝天面で読ませる）'),
    'mon_yur': (mon_yur, static_part(),
                '森の幽霊洋館の戸口（南面。板を打ちつけた扉・外れかけた庇・苔の石段）'),
})

# ---- 廃洋館（デザイン12・2026-08-20）----
# 壁の塊は **793 マス・49×20・充填 0.81** の 1 枚岩。屋敷として読み（`manor_min_cells: 600`）、
# **距離変換の屋根**（`manor_roof_irimoya`）で四方の軒から 4 段上げ、頂を
# **平らな鉛の陸屋根**で受ける＝マンサール。切妻（博麗・霧雨）でも入母屋（永遠亭・命蓮寺）
# でもない 3 つめの組み方だが、**コードは 1 行も足していない**——段の上限
# （`manor_roof_max`）と隅棟の折れ（`manor_hip_break`）の値だけで洋館の屋根になる。
# 新しいのは崩落（`manor_roof_scar`）1 つで、これが §4.3 の外せない 1 点である。
