# ---- 岩山（P10 第 3 期。2026-08-10 に決めた「複数のマスにわたって表現された岩山」）----
# **意匠を持たない。**山は町の意匠ではなく地形なので、町が変わっても山は山である。
# どの段を置くかは `town_plan.cpp` がマスごとに決める（山の外からの深さ）。
_CRAG_NOTE = {'low': '麓（1.4 マス）', 'mid': '中腹（2.4 マス）',
              'high': '上部（3.7 マス）', 'peak': '峰（4.9 マス）'}
for _tier in CRAG_TIERS:
    add_variants('crag_' + _tier, 4, crag, '岩山の岩塊 — %s' % _CRAG_NOTE[_tier])


# ---- 入口の手前の低い岩棚（2026-08-27 に決めた）----
# 「鉄獄の入り口が丸太の山に囲まれて見えないので**手前の丸太は背の低い踏破不可の
#   オブジェクト**で置き換えて」。
#
# 麓（`crag_low`。1.4 マス）でも**ダンジョンの口の絵（`dungeon_entrance` は 1.31 マス）と
# ほぼ同じ高さ**なので、口の手前へ置くと結局ふさぐ。ここは**口より確実に低い**
# 0.56〜0.69 マスに採る。歩けないことは**足元がマスいっぱいの岩**であることで読ませる
# （`crag()` の註記「入れない所の読みは足元で決まる」）。
def crag_ledge(name):
    """入口の手前に置く低い岩棚。高さは変種ごとに 18〜22 ボクセル（0.56〜0.69 マス）。"""
    return crag(name, h_override=int(rng_for(name + ':h').integers(18, 23)))


add_variants('crag_ledge', 3, crag_ledge, '入口の手前の低い岩棚（0.6 マス）')


# ---- 紅魔館の岩と氷（2026-08-18「マップ南の通路と山は低めのランダムな岩とレンガ道」
#      「氷塊は巨大な岩山の色違い（白と水色で氷を表現）」）----
def _crag_rubble_koma(name):
    """紅魔館の岩。山の 4 段を**どれも低いランダムな岩**にする——霧の湖の畔は低い岩場で、
    そびえるのは氷塊（iceberg）と館だけにする。高さは変種ごとに種で振れる。"""
    tier = name.split('_')[1]
    lo, hi = {'low': (16, 24), 'mid': (20, 30), 'high': (24, 36), 'peak': (28, 42)}[tier]
    h = int(rng_for(name + ':h').integers(lo, hi))
    return crag(name, h_override=h)


def iceberg(name):
    """氷壁の氷塊——岩山の色違い（白と水色）。変種ごとに高さを変えて氷山の凸凹を出す。"""
    idx = int(name.rsplit('_', 1)[1])
    h = (52, 72, 92)[(idx - 1) % 3]
    return crag(name, h_override=h,
                bands=[C['pane_d'], C['pane'], C['spray'], C['snow_d'], C['snow']],
                face_mix=([C['snow'], C['snow_d'], C['pane_l']], [0.50, 0.30, 0.20]))


