VWL_SPINES = ['vwl_b1', 'vwl_b2', 'vwl_b3', 'vwl_b4', 'vwl_b5', 'vwl_b6', 'vwl_b7']


def floor_carpet_gb(name):
    """**赤絨毯の床** — 紅魔館深部（設計 §5.2。調査 §3.5 ②「紅魔館の唯一の赤を床で言う」）。

    部屋にも通路にも同じ材を敷く（表が両方へ同じ名前を指す）。館の中なので
    **石畳の目地は引かない**——絨毯は継ぎ目なく続き、代わりに

    | 何 | どう |
    |---|---|
    | 織り | 2×2 の塊で赤 3 色を薄く散らす（`_grain` と同じ考え。1 ボクセル単位にしない） |
    | 紋 | マスの中央に**金糸の菱**。**全部のマスに置く**ので、並ぶと規則的な紋様になる |
    | 擦り切れ | 1 段彫って下の石を出す。**変種の半分だけ**（毎マスに穴があると床が虫食いに見える） |

    彫りは 1 段。厚みは他の床と同じ `FLOOR_H` で、天面がちょうど z=0 に来る。
    """
    rng = rng_for(name)
    idx = int(name.rsplit('_', 1)[1])
    v = np.zeros((V, V, FLOOR_H), np.int16)
    top = FLOOR_H - 1
    #! 絨毯の下は館の石（擦り切れた所から覗く）。
    for z in range(FLOOR_H):
        v[:, :, z] = C['pav_dd'] if z < top - 1 else C['pav_d']
    v[:, :, 0] = C['pav_dd']

    face = np.zeros((V, V), np.int16)
    face[:, :] = C['vwl_carp']
    #! 織り目（塊単位のむら）。**基調から離さない**——離すと「汚れ」に見える。
    for x in range(0, V, 2):
        for y in range(0, V, 2):
            r = rng.random()
            if r < 0.17:
                face[x:x + 2, y:y + 2] = C['vwl_carp_l']
            elif r < 0.34:
                face[x:x + 2, y:y + 2] = C['vwl_carp_d']
    #! 金糸の菱（マスの中央）。**マスごとに同じ形**なので、敷き詰まると紋様として読める。
    #! **輪郭だけ**にする（2026-08-20 の 2 版。初版は塗り潰しと二重で、引きの絵で
    #! 「絨毯に落ちた金色の染み」に見えた。織りの紋は線であって面ではない）。
    for k in range(9):
        w = k if k < 5 else 8 - k
        for dz, colour in ((0, 'vwl_carp_g'),):
            face[16 - w - 1:16 - w + 1, 11 + k + dz] = C[colour]
            face[16 + w - 1:16 + w + 1, 11 + k + dz] = C[colour]
            face[16 - w - 1:16 - w + 1, 20 - k - dz] = C[colour]
            face[16 + w - 1:16 + w + 1, 20 - k - dz] = C[colour]
    v[:, :, top] = face

    #! 擦り切れ（偶数の変種だけ）。**彫って下の石を出してはいけない**
    #! （2026-08-20 の 2 版。初版は 1 段彫っていて、引きの絵で**赤い絨毯に散った
    #! 茶色い穴**に見えた。絨毯の擦り切れは穴ではなく毛が寝て色が褪せることである）。
    #! 色だけを落とす——四角形も 1 つ増えない。
    if idx % 2 == 0:
        for _ in range(int(rng.integers(1, 3))):
            w, d = int(rng.integers(5, 11)), int(rng.integers(5, 11))
            x = int(rng.integers(2, V - 2 - w))
            y = int(rng.integers(2, V - 2 - d))
            patch = v[x:x + w, y:y + d, top]
            patch[patch == C['vwl_carp']] = C['vwl_carp_d']
            patch[patch == C['vwl_carp_l']] = C['vwl_carp']
    return [('main', v, (0, 0, -FLOOR_H))]


def _vwl_shelf_face(v, rng, face, packed):
    """書架の 1 面を描く。`face` は 0=−y / 1=+y / 2=−x / 3=+x。

    面の座標は `(u, z)`——`u` が面に沿った横、`z` が高さ。触るのは**外皮の 4 ボクセル**で、
    深さ 0 が棚枠の小口、深さ 1 が本の背、深さ 2 が本の上の闇である。

    ## 彫らないと「絵を描いた箱」になる（2026-08-20 に実測して直した）
    初版は全部を深さ 0 に塗っていた。**メッシャは色ではなく幾何で四角形を割る**
    （色は焼き込みの地図へ回る）ので、外皮が平らなままだと**壁 1 枚が 6〜82 四角形**の
    ただの箱になり、書架の段も本の凹凸も 1 つも立たなかった。棚は**枠を残して中を彫る**:

    | 深さ | 何 |
    |---:|---|
    | 0 | 棚板・側板・中仕切り（**残す**＝ 1 ボクセル手前へ出る） |
    | 1 | 本の背（彫った底に立つ。高さは 1 冊ずつ違う） |
    | 2 | 本の上の闇（棚の奥。**ここが在るから書架が空洞に見える**） |
    | 3 | 抜けた本の奥（さらに深い穴） |

    `packed` が真なら**抜けを作らない**（岩盤＝奥へ続く書架の塊）。
    """
    def put(u0, u1, z0, z1, depth, colour):
        """面の (u, z) 矩形を深さ `depth` の層へ塗る（`colour=0` は彫る）。"""
        u0, u1 = max(0, u0), min(V, u1)
        z0, z1 = max(0, z0), min(WALL_H, z1)
        if (u0 >= u1) or (z0 >= z1):
            return
        if face == 0:
            v[u0:u1, depth, z0:z1] = colour
        elif face == 1:
            v[u0:u1, V - 1 - depth, z0:z1] = colour
        elif face == 2:
            v[depth, u0:u1, z0:z1] = colour
        else:
            v[V - 1 - depth, u0:u1, z0:z1] = colour

    #! 棚は 4 段（段の高さ 8＝本がちょうど収まる）。棚板は 2 ボクセルで**深さ 0 に残す**。
    for base in (0, 8, 16, 24):
        put(0, V, base, base + 2, 0, C['vwl_wood'])
        put(0, V, base, base + 2, 1, C['vwl_wood_d'])
    #! 天の笠板と両端の側板（**枠が無いと本の縞だけが浮いて棚に見えない**）。
    put(0, V, WALL_H - 2, WALL_H, 0, C['vwl_wood_l'])
    put(0, 2, 0, WALL_H, 0, C['vwl_wood_d'])
    put(V - 2, V, 0, WALL_H, 0, C['vwl_wood_d'])
    #! 中仕切り（1 面に 2 本）。**これが無いと 1 面が 1 枚の板に見える**。
    dividers = (10, 21)
    for u in dividers:
        put(u, u + 1, 0, WALL_H, 0, C['vwl_wood_d'])

    #! 本。**縦縞を 1 塊ずつ**（1 冊ごとに色を散らすと greedy が効かない＝罠 38）。
    for base in (0, 8, 16, 24):
        u = 2
        while u < V - 2:
            wdt = int(rng.integers(2, 5))
            if u + wdt > V - 2:
                break
            if any(u <= d < u + wdt for d in dividers):
                u += wdt      # 中仕切りをまたがない
                continue
            top = base + 8 if base < 24 else WALL_H - 2
            #! まず棚の中を**彫る**（深さ 0 と 1 を抜き、深さ 2 に奥の闇を敷く）。
            put(u, u + wdt, base + 2, top, 0, 0)
            put(u, u + wdt, base + 2, top, 1, 0)
            put(u, u + wdt, base + 2, top, 2, C['vwl_gap'])
            if (not packed) and (rng.random() < 0.13):
                #! 抜けた本。**さらに 1 段深く**——これが 1 つ在るだけで書架が箱でなくなる。
                put(u, u + wdt, base + 2, top, 2, 0)
                put(u, u + wdt, base + 2, top, 3, C['vwl_gap'])
                u += wdt
                continue
            hgt = 6 if packed else int(rng.integers(5, 8))
            hgt = min(hgt, top - base - 2)
            spine = C[VWL_SPINES[int(rng.integers(0, len(VWL_SPINES)))]]
            #! 背表紙は彫った底（深さ 1）に立つ。**上に隙間が残る**のが棚の読み。
            put(u, u + wdt, base + 2, base + 2 + hgt, 1, spine)
            if (not packed) and (rng.random() < 0.10):
                #! 傾いた 1 冊（隣の隙間へ倒れ込む。埃をかぶった書架の生気）。
                put(u + wdt - 1, u + wdt + 1, base + 2 + hgt, base + 4 + hgt, 1, spine)
            u += wdt


def _vwl_top_books(v, rng, count):
    """書架の**天面**（2026-08-20。引きの絵で気づいて作り直した）。

    見下ろすカメラでは、壁と岩盤の**天面がいちばん広く映る**。笠板 1 枚だけだと
    合成フレームの引きで**茶色の寄木の床**が一面に広がって見えた（`--camera=34,55,110`
    で実測）。

    ## 高さは 32 のまま（**上へ積んではならない**）
    最初は天面へ本を積んだ——**壁ブロックの高さは全種で 1.0 マスに統一**という決まりを
    破っていた（2026-08-09 に決めた「壁ブロックの高さが異なるのも地形判別が
    つきづらくなるので統一しよう」）。積むのをやめ、**天面を彫って中へ収める**:

    - 板目（マスごとに向きが違う 5〜7 幅の板と、1 ボクセル彫った継ぎ目）
    - **窪みへ寝かせた本**（3 彫って 2 段。天面より上へは 1 ボクセルも出ない）
    """
    top = WALL_H - 1
    #! 板目。**向きをマスごとに変える**——揃うと寄木の床に戻る。
    along_x = rng.random() < 0.5
    u = int(rng.integers(0, 6))
    while u < V:
        wdt = int(rng.integers(5, 8))
        shade = rng.choice([C['vwl_wood'], C['vwl_wood_l'], C['vwl_wood_d']], p=[0.5, 0.3, 0.2])
        if along_x:
            v[u:u + wdt - 1, :, top] = shade
            v[max(0, u + wdt - 1):u + wdt, 1:V - 1, top] = 0      # 継ぎ目（彫る）
        else:
            v[:, u:u + wdt - 1, top] = shade
            v[1:V - 1, max(0, u + wdt - 1):u + wdt, top] = 0
        u += wdt
    #! 窪みへ寝かせた本（**天面より上へ出さない**）。
    for _ in range(int(rng.integers(max(1, count - 1), count + 2))):
        w = int(rng.integers(7, 12))
        d = int(rng.integers(5, 9))
        x = int(rng.integers(1, V - 1 - w))
        y = int(rng.integers(1, V - 1 - d))
        v[x:x + w, y:y + d, WALL_H - 3:WALL_H] = 0
        for k in range(2):
            z = WALL_H - 3 + k
            spine = C[VWL_SPINES[int(rng.integers(0, len(VWL_SPINES)))]]
            v[x:x + w, y:y + d, z:z + 1] = spine
            v[x:x + w, y:y + 1, z:z + 1] = C['vwl_b6']     # 小口（紙の側）
            x = max(0, min(V - w, x + int(rng.integers(-1, 2))))
            y = max(0, min(V - d, y + int(rng.integers(-1, 2))))


def wall_bookshelf_gb(name):
    """**壁が書架** — 紅魔館深部（調査 §3.5「外せない 1 点」）。

    `NO_CAVE` ＋ 通路率 100 で**洞窟が 1 マスも出ない**純粋な回廊なので、壁の 100% が
    役割の既定で描かれる。つまり材がそのまま全面へ効く——**1 手で最も効く**。

    4 面すべてを棚にする（部屋の形しだいでどの面も見える。`glyph_slab` が片面に
    賭けて失敗したのと同じ轍を踏まない）。中身は木の塊で、外皮 3 ボクセルだけが棚である。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['vwl_wood_d']
    for face in range(4):
        _vwl_shelf_face(v, rng, face, packed=False)
    #! 天面は埃をかぶった笠板（**平らに保つ**＝高さの揃いが地形の判別を作る）。
    v[:, :, WALL_H - 1] = C['vwl_wood_l']
    v[2:V - 2, 2:V - 2, WALL_H - 1] = C['vwl_wood']
    _vwl_top_books(v, rng, 2)
    return [('main', v, (0, 0, 0))]


def bedrock_bookshelf_gb(name):
    """**書架の塊**（岩盤の位置）— 紅魔館深部。

    岩盤は「厚い壁の中身」なので、**抜けも傾きも無い、隙間なく詰まった書架**にする。
    咲夜が空間を操るので館内は実際より広い（調査 §4.3）——**本の壁が奥へ続いている**
    という読みが、この 1 枚の役目である。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['vwl_wood_d']
    for face in range(4):
        _vwl_shelf_face(v, rng, face, packed=True)
    v[:, :, WALL_H - 1] = C['vwl_wood']
    _vwl_top_books(v, rng, 4)
    return [('main', v, (0, 0, 0))]


def book_pile_gb(name):
    """**本の塔** — 紅魔館深部の行き止まり（調査 §3.5 ③「床に積まれた本の塔」）。

    横に寝かせた本を**少しずつずらして**積む（真っ直ぐだと箱に見える）。
    高さ 0.7 マス。傍らに 2〜3 冊の低い山と、開いたまま伏せた 1 冊。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 24), np.int16)
    cx, cy = 15, 15
    z = 0
    while z < 22:
        th = int(rng.integers(2, 4))
        w = int(rng.integers(9, 13))
        d = int(rng.integers(7, 11))
        ox = cx - w // 2 + int(rng.integers(-2, 3))
        oy = cy - d // 2 + int(rng.integers(-2, 3))
        spine = C[VWL_SPINES[int(rng.integers(0, len(VWL_SPINES)))]]
        v[ox:ox + w, oy:oy + d, z:z + th] = spine
        #! 小口（紙の側）は白く。**背表紙と 2 色**あるだけで「本」に見える。
        v[ox:ox + w, oy:oy + 1, z:z + th - 1] = C['vwl_b6']
        v[ox:ox + w, oy + d - 1:oy + d, z:z + th - 1] = C['vwl_b6']
        z += th
    #! 脇の低い山。
    for sx, sy in ((3, 20), (22, 6)):
        for k in range(int(rng.integers(2, 4))):
            spine = C[VWL_SPINES[int(rng.integers(0, len(VWL_SPINES)))]]
            v[sx:sx + 8, sy:sy + 6, k * 2:k * 2 + 2] = spine
            v[sx:sx + 8, sy:sy + 1, k * 2:k * 2 + 1] = C['vwl_b6']
    #! 伏せて開いたままの 1 冊（**読みかけ**。この 1 つが図書館の生気になる）。
    v[20:29, 19:24, 0:2] = C['vwl_b6']
    v[24:25, 19:24, 0:3] = C['vwl_b2']
    return [('main', v, (0, 0, 0))]


def glyph_circle_gb(name):
    """**床に彫った魔法陣** — 紅魔館深部の部屋の中（調査 §3.5 ⑤）。

    宙に浮かぶ魔法陣 5 種は**敵**なので小物にしない。代わりに床の刻みを置く。

    **厚みは 1 ボクセルだけ**（2026-08-20。初版は 2 で、引きの絵で紫の輪が床から
    盛り上がって玩具に見えた）。床のプレハブは別の個なので**こちらから彫ることはできない**
    ——彫れないなら、**限界まで薄く敷いて「床に描いた線」に見せる**のが次善である。
    線は 2 本の環と、それを繋ぐ放射 8 本、中心の四芒。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 1), np.int16)
    cx = cy = 15.5
    for x in range(V):
        for y in range(V):
            r = math.hypot(x - cx, y - cy)
            ang = math.atan2(y - cy, x - cx)
            outer = 11.4 <= r <= 12.8
            inner = 6.4 <= r <= 7.4
            spoke = (7.4 < r < 11.4) and (abs(math.sin(ang * 4.0)) < 0.13)
            if outer or inner:
                v[x, y, 0] = C['vwl_gl_l']
            elif spoke:
                v[x, y, 0] = C['vwl_gl']
    #! 中心の四芒（腕の長さ 5）。
    for k in range(-5, 6):
        v[15 + k, 15, 0] = C['vwl_gl_l']
        v[16 + k, 16, 0] = C['vwl_gl_l']
        v[15, 15 + k, 0] = C['vwl_gl_l']
        v[16, 16 + k, 0] = C['vwl_gl_l']
    #! 擦れて途切れた所（1〜3 か所）。**完全な円は「刷り物」に見える**。
    for _ in range(int(rng.integers(1, 4))):
        x = int(rng.integers(2, V - 8))
        y = int(rng.integers(2, V - 8))
        v[x:x + 6, y:y + 5, :] = 0
    return [('main', v, (0, 0, 0))]


def candle_stand_gb(name):
    """**燭台** — 紅魔館深部の火（調査 §3.5 ④「火は蝋燭に」）。

    立ち松明（`torch_stand`）と**同じ原点・同じ高さ**で作る——炎は既存の
    `torch_flame` をそのまま重ねるので、芯の位置（z≈30・中央 3×3）を合わせないと
    炎が宙に浮く。真鍮の燭台に蝋燭 3 本（中央が高く、左右は低い）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 34), np.int16)
    #! 台座（三脚の輪）。
    v[11:21, 11:21, 0:2] = C['vwl_brass']
    v[12:20, 12:20, 1:3] = C['vwl_brass_l']
    v[15:17, 15:17, 2:20] = C['vwl_brass']     # 幹
    v[14:18, 14:18, 9:11] = C['vwl_brass_l']   # 節
    #! 腕（東西へ 1 本ずつ張り出し、先で上へ折れる）。
    for dx, x0 in ((-1, 9), (1, 20)):
        v[min(x0, 16):max(x0 + 3, 16), 15:17, 18:20] = C['vwl_brass']
        v[x0:x0 + 3, 15:17, 18:24] = C['vwl_brass']
        v[x0 - 1:x0 + 4, 14:18, 23:25] = C['vwl_brass_l']   # 受け皿
        #! 脇の蝋燭（**溶けて短い**。長さを揃えると工場製に見える）
        ch = int(rng.integers(4, 8))
        v[x0:x0 + 3, 15:17, 25:25 + ch] = C['vwl_wax']
        v[x0:x0 + 3, 15:16, 25:25 + ch - 1] = C['vwl_wax_d']  # 垂れた蝋
    #! 中央の受け皿と蝋燭（芯が z=30 に来る＝`torch_flame` の位置）。
    v[13:19, 13:19, 20:22] = C['vwl_brass_l']
    v[14:18, 14:18, 22:30] = C['vwl_wax']
    v[14:15, 14:18, 22:28] = C['vwl_wax_d']
    v[15:17, 15:17, 29:31] = C['vwl_wax_d']    # 芯のまわりの窪み
    return [('main', v, (0, 0, 0))]


def pillar_shelf_gb(name):
    """**書架の間柱** — 紅魔館深部の部屋の縁（2026-08-20 に決めた）。

    設計書 §5.2 は `pillar_stone`（切石の柱）を指していたが、実機の絵で
    **マホガニーと赤絨毯の中に灰色の切石が浮いた**。調査 §3.5 ③ は元々
    「部屋の縁の柱を**書架の間柱**」と書いていたので、そちらへ差し替える。

    形は `pillar_stone` と揃える——**高さ 54（1.7 マス）**・台座・柱身・柱頭の 3 段。
    違うのは材だけで、柱身の 4 面が細い書架になっている。壁の書架
    （`wall_bookshelf_gb`）と同じ作りで、**彫って**段と本を出す
    （平らに塗ると箱になる＝設計 V7）。

    幅は 16 ボクセル（0.5 マス）。壁の書架より狭いので**中仕切りは入れない**
    ——1 面に本が 4〜5 冊しか並ばないところに仕切りを入れると格子に見える。
    """
    rng = rng_for(name)
    A, B = 8, 24            # 柱身の範囲（0.5 マス角）
    h = 58                  # 54（`pillar_stone` の丈）＋ 天面に積む本の 4
    v = np.zeros((V, V, h), np.int16)

    def put(face, u0, u1, z0, z1, depth, colour):
        """柱身の 1 面の (u, z) 矩形を、外面から `depth` の層へ塗る。"""
        u0, u1 = max(A, u0), min(B, u1)
        z0, z1 = max(0, z0), min(h, z1)
        if (u0 >= u1) or (z0 >= z1):
            return
        if face == 0:
            v[u0:u1, A + depth, z0:z1] = colour
        elif face == 1:
            v[u0:u1, B - 1 - depth, z0:z1] = colour
        elif face == 2:
            v[A + depth, u0:u1, z0:z1] = colour
        else:
            v[B - 1 - depth, u0:u1, z0:z1] = colour

    #! 台座（`pillar_stone` と同じ 2 段の広がり）。
    v[A - 3:B + 3, A - 3:B + 3, 0:2] = C['vwl_wood_d']
    v[A - 2:B + 2, A - 2:B + 2, 2:4] = C['vwl_wood']
    #! 柱身（中身は木の塊。外皮 3 ボクセルだけが棚になる）。
    v[A:B, A:B, 4:46] = C['vwl_wood_d']
    for face in range(4):
        #! 棚板（5 段）と側桟。**深さ 0 に残す**＝ 1 ボクセル手前へ出る。
        for base in (4, 12, 20, 28, 36):
            put(face, A, B, base, base + 2, 0, C['vwl_wood'])
            put(face, A, B, base, base + 2, 1, C['vwl_wood_d'])
        put(face, A, B, 44, 46, 0, C['vwl_wood_l'])
        put(face, A, A + 2, 4, 46, 0, C['vwl_wood_d'])
        put(face, B - 2, B, 4, 46, 0, C['vwl_wood_d'])
        #! 本（1 段に 4〜5 冊）。棚の中を彫ってから背表紙を立てる。
        for base in (4, 12, 20, 28, 36):
            u = A + 2
            while u < B - 2:
                wdt = int(rng.integers(2, 5))
                if u + wdt > B - 2:
                    break
                top = base + 8 if base < 36 else 44
                put(face, u, u + wdt, base + 2, top, 0, 0)
                put(face, u, u + wdt, base + 2, top, 1, 0)
                put(face, u, u + wdt, base + 2, top, 2, C['vwl_gap'])
                if rng.random() < 0.12:
                    u += wdt          # 抜けた本（奥の闇がそのまま残る）
                    continue
                hgt = min(int(rng.integers(5, 8)), top - base - 2)
                spine = C[VWL_SPINES[int(rng.integers(0, len(VWL_SPINES)))]]
                put(face, u, u + wdt, base + 2, base + 2 + hgt, 1, spine)
                u += wdt
    #! 柱頭（迫り出した繰形。`pillar_stone` と同じ高さで終わる）。
    #! **薄く小さく**——初版は 22 幅 ×7 高で、柱の上に机の天板が載って見えた。
    v[A - 1:B + 1, A - 1:B + 1, 46:48] = C['vwl_wood']
    v[A - 2:B + 2, A - 2:B + 2, 48:50] = C['vwl_wood_l']
    v[A:B, A:B, 50:52] = C['vwl_wood_d']
    #! 天面に本を 1 山（**柱の上は本の置き場**。書架の天面と同じ扱い）。
    if rng.random() < 0.6:
        for k in range(int(rng.integers(1, 3))):
            spine = C[VWL_SPINES[int(rng.integers(0, len(VWL_SPINES)))]]
            ox = A + int(rng.integers(0, 3))
            oy = A + int(rng.integers(0, 3))
            v[ox:ox + 11, oy:oy + 8, 52 + k * 2:54 + k * 2] = spine
            v[ox:ox + 11, oy:oy + 1, 52 + k * 2:53 + k * 2] = C['vwl_b6']
    return [('main', v, (0, 0, 0))]


NEEDLE_H = 12  #!< 針が床から立つ高さ（vox。0.37 マス）。**高くしない**——歩く床である


def floor_needle_gb(name):
    """**針の原** — 地獄の床（調査 §3.12「外せない 1 点」）。

    地獄は**壁の 70% が『針のむしろ』で、しかもそれは通れる床**である（調査 §1.3）。
    つまり針山地獄がフロア全体に敷かれている。**この 1 枚で地獄の 7 割が決まる。**

    焼けた砂の面に**灰鉄の針を格子状に立てる**。針は 6×6 の 36 本で、太さ 3、
    高さは 5〜8 を種で振る（揃えると剣山の工業製品に見える）。
    **先端だけ明るく**するのが「針」の読み——一様な灰色の突起は瓦礫に見える。

    ## なぜ 36 本なのか（三角形の予算）
    針 1 本が 1 つの箱なので、本数がそのまま四角形の数になる。床タイルは**歩けるマス
    すべてに出る**ので、`floor_room`（150 quads）の 2 倍あたりが上限である。
    64 本にすると 500 を超え、`wall_lair`（536）と並ぶ——壁より重い床は割に合わない。
    """
    rng = rng_for(name)
    h = FLOOR_H + NEEDLE_H
    v = np.zeros((V, V, h), np.int16)
    ground = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['hel_grit'] if z < ground else C['hel_grit_l']
    v[:, :, 0] = C['hel_grit']
    #! 地の面（焼けた砂。塊単位のむら）。
    for x in range(0, V, 4):
        for y in range(0, V, 4):
            v[x:x + 4, y:y + 4, ground] = rng.choice(
                [C['hel_grit_l'], C['hel_grit'], C['crust_l']], p=[0.5, 0.32, 0.18])
    #! 針（6×6）。位置は 1 ボクセルだけ揺らす（格子が読めると剣山になる）。
    #!
    #! **細く高く、先を尖らせる**（2026-08-20 の 2 版）。初版は 3×3 で高さ 5〜8 の
    #! 角柱だったので、引きの絵で**杭を打った原っぱ**に見えた。針に見せる条件は
    #! 「太さより丈が勝っていること」と「先が細っていること」の 2 つで、
    #! 軸を 2×2・丈を 7〜11 にし、天へ 1×1 の穂先を 2 段載せる。
    #! **色の段は四角形を増やさない**（色は焼き込みの地図へ回るので、
    #! 明るい先端はただで付く）——増えるのは穂先の箱 1 つぶんだけである。
    for gx in range(6):
        for gy in range(6):
            x = 2 + gx * 5 + int(rng.integers(0, 2))
            y = 2 + gy * 5 + int(rng.integers(0, 2))
            if rng.random() < 0.08:
                continue                      # 折れて抜けた針
            hh = int(rng.integers(7, NEEDLE_H + 1))
            v[x:x + 2, y:y + 2, FLOOR_H:FLOOR_H + hh - 3] = C['hel_ndl']
            v[x:x + 2, y:y + 2, FLOOR_H + hh - 3:FLOOR_H + hh - 2] = C['hel_ndl_l']
            v[x:x + 1, y:y + 1, FLOOR_H + hh - 2:FLOOR_H + hh] = C['hel_ndl_l']   # 穂先
            #! 根元の影（1 段だけ暗く）。針が面から生えて見える。
            v[x:x + 2, y:y + 2, ground] = C['hel_ndl_d']
    return [('main', v, (0, 0, -FLOOR_H))]


def haniwa_soldier_gb(name):
    """**埴輪の兵**（杖刀偶磨弓）— 地獄の部屋の縁と壁際（調査 §3.12 ②）。

    住人に埴輪が 6 種居るので、**小物ではなくマスを持つ像**にする。素焼きの赤褐。

    ## 埴輪に見せる 3 点（2026-08-20。2 度作り直した）
    1. **断面は円。**角柱にすると土管か煙突になる（初版）
    2. **顔の穴を大きく、深く。**2 版は目を 4×3 で彫ったが、冑の鍔の影に入って
       引きの絵で 1 画素も読めなかった。埴輪の顔は**穴が顔の面積の 1/4 を占める**
       ——目は 5×5・口は 6×4 で、**深さ 8 まで貫いて中を闇にする**
    3. **頭を大きく、首を細く。**人の比ではなく埴輪の比（頭が胴とほぼ同径）にする。
       この 2 つの径の差だけで「人が立っている」に読める

    高さ 44（1.4 マス）。柱（`pillar_stone` は 32＋）の代わりに立つので、
    背が足りないとただの置物になる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 46), np.int16)
    cx = cy = 15.5

    def disc(z0, z1, r, colour):
        for x in range(V):
            for y in range(V):
                if math.hypot(x - cx, y - cy) <= r:
                    v[x, y, z0:z1] = colour

    disc(0, 4, 9.0, C['hel_hani_d'])          # 土に据わった台
    disc(4, 6, 8.2, C['hel_hani_d'])
    disc(6, 23, 7.2, C['hel_hani'])           # 胴
    for z in (10, 16):                        # 輪積みの継ぎ目
        disc(z, z + 1, 7.6, C['hel_hani_d'])
    disc(23, 25, 6.0, C['hel_hani_d'])        # 肩
    disc(25, 27, 3.4, C['hel_hani_d'])        # **細い首**
    disc(27, 40, 7.0, C['hel_hani'])          # **頭（胴とほぼ同径）**
    disc(40, 42, 9.6, C['hel_hani_d'])        # 冑の鍔（**大きく張り出す**）
    disc(42, 45, 5.2, C['hel_hani'])          # 冑の椀
    #! 南（カメラ側＝**+y**）の面に光を当てる。**向きを間違えると顔が裏を向く**
    #! （2026-08-20 に実際にやった。`gen_prefabs.py` 冒頭「+y は南＝カメラ側」）。
    for x in range(V):
        for y in range(int(cy) + 1, V):
            for z in range(6, 40):
                if v[x, y, z] == C['hel_hani']:
                    v[x, y, z] = C['hel_hani_l']
    #! 腕（筒。左右へ水平に張り出し、肘から下へ折れる）。片方に鉄の剣＝**杖刀**偶。
    for x0 in (2, 24):
        v[x0:x0 + 8, 12:18, 17:23] = C['hel_hani']
        v[x0:x0 + 8, 16:18, 17:23] = C['hel_hani_l']
        v[x0 + 1:x0 + 6, 13:17, 9:18] = C['hel_hani_d']    # 前腕（下へ）
    v[25:28, 13:17, 20:40] = C['iron']                     # 剣
    v[25:28, 13:17, 39:42] = C['iron_l']
    #! **顔は平ら**にする（2026-08-20 の 3 度目）。円筒のまま目を彫ると、頬が残らず
    #! **顔の前半分が消えて空洞の兜**に見えた（実測。z=36 の断面に鼻の稜しか残らない）。
    #! 埴輪の顔は実際に平たい面なので、頭の前を **y=11 で切り落として面を作り**、
    #! そこへ穴を彫る。これで頬と顎が残り、穴が「顔の穴」として読める。
    FACE_Y = 20                                            # **+y ＝南＝カメラ側**
    head = v[:, FACE_Y + 1:V, 27:40]
    head[(head == C['hel_hani']) | (head == C['hel_hani_l'])] = 0
    v[9:23, FACE_Y:FACE_Y + 1, 27:40] = C['hel_hani_l']    # 面（頬と顎）
    #! **顔の穴**（面から奥へ 5 彫り、底を闇にする。ここが埴輪の顔）。
    for x0 in (11, 18):                                    # 目 4×4
        v[x0:x0 + 4, FACE_Y - 4:FACE_Y + 1, 33:37] = 0
        v[x0:x0 + 4, FACE_Y - 4:FACE_Y - 3, 33:37] = C['hel_hole']
    v[13:19, FACE_Y - 4:FACE_Y + 1, 28:31] = 0             # 口 6×3
    v[13:19, FACE_Y - 4:FACE_Y - 3, 28:31] = C['hel_hole']
    #! 欠け（地獄の年月。1〜3 か所を落とす）。**北面（裏）だけ**——顔を崩さない。
    for _ in range(int(rng.integers(1, 4))):
        x = int(rng.integers(9, 20))
        z = int(rng.integers(7, 22))
        v[x:x + 3, 8:13, z:z + 3] = 0
    return [('main', v, (0, 0, 0))]


def skull_pile_gb(name):
    """**髑髏の塚** — 地獄の行き止まりと部屋の中（調査 §3.12 ③。特産品が頭蓋骨）。

    既存の `bones`（散った骨）とは**量で差を付ける**——あちらは 1 個の頭蓋と 4 本の骨、
    こちらは**積み上がった 20 個以上**である。地獄の湧きは 30（16 本で最も濃い）なので、
    「ここで大勢死んだ」を言う小物が要る。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 22), np.int16)
    #! 下敷きの砕けた骨（塚の裾）。
    for _ in range(14):
        x, y = int(rng.integers(2, 26)), int(rng.integers(2, 26))
        v[x:x + int(rng.integers(3, 7)), y:y + 2, 0:2] = C['bone_d']
    #! 頭蓋を円錐状に積む。**上ほど少なく**（3 段）。
    layers = ((0, 5, 7.5), (6, 3, 5.0), (11, 2, 2.6))
    for z0, n, rad in layers:
        for k in range(n * 3 if z0 == 0 else n * 2):
            ang = k / float(n * 3 if z0 == 0 else n * 2) * 2.0 * math.pi
            x = int(15 + math.cos(ang) * rad) - 3
            y = int(15 + math.sin(ang) * rad) - 3
            x = max(0, min(V - 8, x))
            y = max(0, min(V - 7, y))
            v[x:x + 7, y:y + 6, z0:z0 + 5] = C['bone']
            v[x + 1:x + 6, y + 1:y + 5, z0 + 5:z0 + 6] = C['bone']   # 丸めた頭頂
            v[x + 1:x + 6, y + 4:y + 6, z0:z0 + 2] = C['bone_d']     # 顎（**+y ＝手前**）
            #! 眼窩（南面＝ +y）。**間を 1 ボクセル空ける**——詰めると
            #! 2 つが 1 本の黒い帯に融けて「口」に見える（2026-08-20 に実測）。
            v[x + 1:x + 3, y + 5, z0 + 2:z0 + 4] = C['dark']
            v[x + 4:x + 6, y + 5, z0 + 2:z0 + 4] = C['dark']
            v[x + 3:x + 4, y + 5, z0 + 1:z0 + 3] = C['bone_d']       # 鼻梁
    #! 頂の 1 個（角のある鬼の頭蓋）。
    v[12:20, 12:19, 16:21] = C['bone']
    v[13:19, 16:19, 16:18] = C['bone_d']
    v[13:15, 18, 18:20] = C['dark']
    v[17:19, 18, 18:20] = C['dark']
    for x0, dx in ((10, -1), (19, 1)):
        for k in range(3):
            v[x0 + dx * k:x0 + dx * k + 2, 14:17, 20 + k:22 + k] = C['bone_d']
    return [('main', v, (0, 0, 0))]


def fuda_seal_gb(name):
    """**剥がれた封の札** — 夢殿大祀廟の洞窟の壁際（調査 §3.2 ③）。

    1,400 年の眠りから神子と布都が**もう出ていった**ことを、剥がれかけた札で言う。

    ## 札は「1 枚の平らな面」である（2026-08-20。2 度作り直した）
    初版は 2 ボクセルずつ段を下げながら手前へずらした——**紙が折れた階段**に見えた。
    2 版は 1 ボクセルずつ傾けた——**梯子の横桟**に見えた。紙は**平面**なので、
    傾けずに垂らし、**下端だけを手前へ 2 段めくる**。ここでようやく紙に見える。

    **手前（+y）が南＝カメラ側。**朱の梵字は面の両側から見えるので厚みは 1 でよい。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.int16)
    SHEET_Y = 9        # 垂れた面の位置
    #! 岩に貼り付いたままの上端（壁の側＝ y が小さい）と、そこから面へ渡る折れ。
    v[10:22, 5:10, 25:28] = C['yum_fu_d']
    #! 垂れた本体（**厚み 1 の平面**）。
    v[10:22, SHEET_Y:SHEET_Y + 1, 7:26] = C['yum_fu']
    v[10:11, SHEET_Y:SHEET_Y + 1, 7:26] = C['yum_fu_d']    # 縁の焼け
    v[21:22, SHEET_Y:SHEET_Y + 1, 7:26] = C['yum_fu_d']
    #! 下端のめくれ（2 段だけ手前へ。**これが「垂れている」の唯一の手がかり**）。
    v[10:22, SHEET_Y + 1:SHEET_Y + 2, 5:8] = C['yum_fu']
    v[10:22, SHEET_Y + 2:SHEET_Y + 3, 4:6] = C['yum_fu_d']
    #! 破れた下端（左右で高さが違う）。真っ直ぐだと看板になる。
    for x in range(10, 22):
        cut = int(rng.integers(0, 4))
        if cut:
            v[x, SHEET_Y:SHEET_Y + 3, 4:4 + cut] = 0
    #! 朱の梵字（**3 画だけ**——読めなくてよい、朱が在ればよい）。
    v[13:19, SHEET_Y:SHEET_Y + 1, 20:21] = C['yum_shu']
    v[15:17, SHEET_Y:SHEET_Y + 1, 11:21] = C['yum_shu']
    v[12:20, SHEET_Y:SHEET_Y + 1, 15:16] = C['yum_shu']
    v[14:18, SHEET_Y:SHEET_Y + 1, 9:10] = C['yum_sumi']
    #! 落ちた札 2 枚（1 枚は裏返って字が見えない）。
    v[2:12, 20:25, 0:1] = C['yum_fu']
    v[5:9, 21:24, 1:2] = C['yum_shu']
    v[20:29, 23:27, 0:1] = C['yum_fu_d']
    #! 千切れた紙片（**2〜4 片だけ**——多いと散らかった紙屑になる）。
    for _ in range(int(rng.integers(2, 5))):
        x, y0 = int(rng.integers(2, 26)), int(rng.integers(16, 28))
        v[x:x + 3, y0:y0 + 2, 0:1] = C['yum_fu_d']
    return [('main', v, (0, 0, 0))]


