# ================================================================= 幻想蛮怒のダンジョン（S3）
# **残り 9 本**（設計書の見出しは「8 本」だが、
# 表は 9 行ある——16 本 − S1／S2 で書いた 7 本 ＝ 9 本が正しい）。
# 順は設計書の発注どおり: 玄武の沢 → 仙界 → 逆さ城 → 無縁塚 → 森 → 夢の世界 →
# 地獄谷 → 混沌 → 浅間。
#
# S2 で覚えたことをそのまま守る:
#   ① **メッシャは色でなく幾何で四角形を割る**（V7）——平らな面に絵を描いても箱にしかならない
#   ② **壁と岩盤の高さは 32 のまま**（V8）——天面の飾りは彫って中へ収める
#   ③ **プレハブの +y は南＝カメラ側**（罠）
for _name, _rgb in (
    # ---- 玄武の沢（調査 §3.4）----
    # 玄武岩の**青みの暗灰**。花崗岩の黄灰（`rock` = 126,122,114）と正反対へ振る
    # ——「玄武の沢」という名がそのまま岩の種類を指しているので、色で名前を裏切らない。
    # **明るい側へ振ってある**（2026-08-21 の 2 版）。指定の下限 #3E434A で組んだ初版は
    # 地下の乏しい光でほとんど黒に落ち、六角柱が読めなかった（合成フレームで実測）。
    # 指定の上限 #5A6068 を基調に取り直す——花崗岩（126,122,114 の黄灰）とは
    # **明度ではなく色相**で割れていればよい。
    ('gen_bas', (90, 96, 104)), ('gen_bas_l', (122, 130, 140)), ('gen_bas_d', (66, 72, 80)),
    ('gen_bas_j', (40, 44, 50)),      # 柱と柱の間の節理（彫った底）
    # 光苔。**自発光の枠は火にしか無い**（`terrain_view.cpp` は `fire_flame` にだけ
    # 自発光を渡し、しかも色は橙のべた書き）ので、**明度で「光っている」を言う**。
    ('gen_moss', (127, 209, 168)), ('gen_moss_l', (186, 244, 210)),
    ('gen_moss_d', (74, 132, 106)),
    # 河童の機械（銅と真鍮）。`steel` / `iron` / `rust` は共通の表から借りる。
    ('gen_cu', (168, 104, 66)), ('gen_cu_l', (212, 148, 98)), ('gen_cu_d', (114, 68, 44)),
    ('gen_bra', (188, 156, 74)), ('gen_bra_l', (226, 200, 118)),
    # ---- 仙界（調査 §3.9）----
    # 雲上の**青みの白**（調査 ②「真珠の白 → 青みの白 #DCE6EC」）。
    ('sen_st', (220, 230, 236)), ('sen_st_l', (242, 248, 250)), ('sen_st_d', (172, 186, 196)),
    ('sen_gl', (176, 206, 214)), ('sen_gl_l', (222, 242, 246)), ('sen_gl_d', (126, 156, 168)),
    # 青銅の香炉（道教の器。西洋の白い蝋燭と取り替える）。
    ('sen_bro', (108, 124, 104)), ('sen_bro_l', (152, 170, 142)), ('sen_bro_d', (72, 84, 70)),
    ('sen_ash', (218, 214, 202)),
    ('sen_smk', (226, 230, 234)), ('sen_smk_d', (196, 202, 208)),
    ('sen_ember', (236, 146, 70)),
    # 桃（不老長寿の記号）と鶴の丹頂。
    ('sen_pea', (232, 168, 184)), ('sen_pea_l', (250, 208, 218)), ('sen_pea_d', (198, 128, 150)),
    ('sen_fru', (240, 152, 118)), ('sen_crown', (194, 54, 48)),
    ('sen_bark', (92, 74, 66)), ('sen_bark_l', (124, 104, 92)),
):
    reg_local(_name, _rgb)


# ------------------------------------------------------------ 4 玄武の沢（柱状節理）
def _hex_centres(rng, pitch):
    """六角格子の中心を並べる（マスの外まではみ出させる）。

    **ボロノイで割ると自然に六角形になる**——中心を六角格子に置いた領域分割のセルが
    正六角形そのものだからである。境界を彫れば柱状節理の断面になる。
    """
    out = []
    dy = pitch * math.sqrt(3.0) * 0.5
    row = -1
    y = -pitch
    while y < V + pitch:
        row += 1
        x = -pitch + (pitch * 0.5 if (row % 2) else 0.0)
        while x < V + pitch:
            out.append((x + float(rng.uniform(-1.2, 1.2)), y + float(rng.uniform(-1.2, 1.2))))
            x += pitch
        y += dy
    return out


def _hex_top(v, rng, pitch, shades, joint, deep=0):
    """**天面に六角柱の断面を彫る。**

    見下ろすカメラでは天面がいちばん広く映るので、ここで柱状節理を言えないと
    「青い箱」で終わる（書架の天面で 1 度踏んだのと同じ話＝ V7・V8）。

    `deep` が 0 より大きいと、セルのいくつかを**その深さぶん彫り下げる**——柱の丈が
    揃っていない「柱の束」の読みになる。**上へは 1 ボクセルも積まない**（V8）。
    """
    h = v.shape[2]
    cen = _hex_centres(rng, pitch)
    lab = np.zeros((V, V), np.int32)
    edge = np.zeros((V, V), bool)
    for x in range(V):
        for y in range(V):
            d1 = d2 = 1e9
            i1 = 0
            for i, (cx, cy) in enumerate(cen):
                d = ((x - cx) ** 2) + ((y - cy) ** 2)
                if d < d1:
                    d2, d1, i1 = d1, d, i
                elif d < d2:
                    d2 = d
            lab[x, y] = i1
            edge[x, y] = (math.sqrt(d2) - math.sqrt(d1)) < 1.5
    #! 柱ごとに 1 色（塊単位＝罠 38）。
    tone = [shades[int(rng.integers(0, len(shades)))] for _ in range(len(cen))]
    drop = [int(rng.integers(2, deep + 1)) if (deep > 0 and rng.random() < 0.28) else 0
            for _ in range(len(cen))]
    for x in range(V):
        for y in range(V):
            i = int(lab[x, y])
            if edge[x, y]:
                #! 節理（1 段彫って底に暗い色。AO と合わさって溝になる）。
                v[x, y, h - 1] = 0
                v[x, y, h - 2] = joint
                continue
            v[x, y, h - 1] = tone[i]
            if drop[i] > 0:
                v[x, y, h - drop[i]:h] = 0
                v[x, y, h - drop[i] - 1] = tone[i]


def _basalt_faces(v, rng, wide=False):
    """側面に**縦の節理**を彫る（柱状節理の唯一かつ決定的な絵）。

    64px の板なら縦の稜線を 5〜6 本引くだけで柱状節理が出る（調査 §3.4 ①）——
    立体でも**縦の溝は 1 面に 4〜5 本**（幅 6〜9）が下限で、太い柱にすると
    「板を 3 枚張った壁」に見える。
    立体では**引く**のではなく**彫る**——1 ボクセルの溝を縦に通し、底に節理の色を敷く。
    横には 10〜14 段ごとに**節**（実在の柱状節理にある横の割れ）を入れる。
    """
    h = v.shape[2]
    shades = [C['gen_bas'], C['gen_bas_l'], C['gen_bas_d'], C['gen_bas']]
    for face in range(4):
        u = int(rng.integers(0, 4))
        while u < V:
            wdt = int(rng.integers(9, 14)) if wide else int(rng.integers(6, 10))
            shade = shades[int(rng.integers(0, len(shades)))]
            recess = 1 if rng.random() < 0.34 else 0
            ua, ub = u, min(u + wdt - 1, V)   # 右 1 列は節理（彫る）
            if ua < ub:
                if recess:
                    _carve_relief(v, face, ua, ub, 1, h - 1, recess)
                _paint_face(v, face, ua, ub, 1, h - 1, recess, shade)
            #! 縦の節理（**溝を通す**。接地層と天面は触らない＝罠 5 と高さの揃い）。
            if ub < V:
                _carve_relief(v, face, ub, ub + 1, 1, h - 1, 1)
                _paint_face(v, face, ub, ub + 1, 1, h - 1, 1, C['gen_bas_j'])
            u += wdt
        #! 横の節（**1 面に 1〜2 本だけ**。実在の柱状節理にもある横の割れだが、
        #! 10 段ごとに入れた初版は縦横の格子になって**羽目板の扉**に見えた（実測）。
        #! 柱状節理は縦が主で横は従である——縦の溝より数を減らす）。
        w = int(rng.integers(11, 19))
        while w < h - 2:
            _carve_relief(v, face, 0, V, w, w + 1, 1)
            _paint_face(v, face, 0, V, w, w + 1, 1, C['gen_bas_j'])
            w += int(rng.integers(14, 22))


def wall_basalt_gb(name):
    """**六角柱の壁** — 玄武の沢（調査 §3.4「外せない 1 点」）。

    「玄武の沢」という名は**そのまま岩の種類**（玄武岩＝柱状節理）を指しているのに、
    先方データの壁は花崗岩 80% ＝変愚の既定である。**ここが意匠でいちばん効く 1 点。**

    側面は縦の節理、天面は六角柱の断面。色は花崗岩の黄灰と正反対の**青みの暗灰**。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['gen_bas_d']
    _basalt_faces(v, rng, wide=False)
    _hex_top(v, rng, 10.5, [C['gen_bas'], C['gen_bas_l'], C['gen_bas_d']], C['gen_bas_j'],
             deep=2)
    return [('main', v, (0, 0, 0))]


def bedrock_basalt_gb(name):
    """**六角柱の塊**（岩盤の位置）— 玄武の沢。

    岩盤は「厚い壁の中身」なので、柱を**太く**（11〜16）し、天面の柱の丈をもう 1 段
    ばらけさせる——**絶壁が削れているのではなく、柱が束になって立っている**が読める。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['gen_bas_d']
    _basalt_faces(v, rng, wide=True)
    _hex_top(v, rng, 13.0, [C['gen_bas_d'], C['gen_bas'], C['gen_bas_d']], C['gen_bas_j'],
             deep=3)
    return [('main', v, (0, 0, 0))]


def _hex_prism(v, cx, cy, z0, z1, rad, colour, edge=None):
    """立った六角柱（断面が正六角形の柱）。`edge` を渡すと稜を 1 色明るくする。"""
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            dx, dy = x - cx, y - cy
            #! 正六角形の内外判定（3 本の法線への射影の最大）。
            q = max(abs(dy), abs(dy * 0.5 + dx * 0.8660254),
                    abs(dy * 0.5 - dx * 0.8660254))
            if q <= rad:
                v[x, y, z0:z1] = colour if ((q < rad - 1.0) or (edge is None)) else edge


def column_hex_gb(name):
    """**折れた六角柱** — 玄武の沢の行き止まり・壁際・部屋の縁（調査 §3.4 ④）。

    渓谷の柱は崩れて谷底に転がる。**立った根元 ＋ 傍らに横たわる 1 本**の 2 つで作り、
    行き止まりの塚にも部屋の縁の柱にも同じものを使う——**折れているからどちらでも
    成り立つ**（切石の柱と違って「途中で終わっている」ことが自然な形である）。

    丈は 40（`pillar_stone` の 54 より低い）。**折れた柱が背高だと折れて見えない。**
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 42), np.int16)
    #! 立った根元（六角柱。稜を明るく＝角が立って見える）。
    hgt = int(rng.integers(30, 41))
    _hex_prism(v, 11.5, 12.5, 0, hgt, 6.4, C['gen_bas'], C['gen_bas_l'])
    #! 折れ口（**欠けさせる**。2026-08-21 の 2 版——斜めに削いだ初版は面が滑らかで、
    #! 鋸で挽いた柱に見えた。岩の折れ口は段になって崩れるので、
    #! **上から 3 段ぶん、隣り合う辺ごとに違う深さで落とす**）。
    for k in range(3):
        z0 = hgt - 1 - (k * 2)
        if z0 < 5:
            break
        for _ in range(int(rng.integers(2, 5))):
            ang = float(rng.uniform(0.0, 6.28))
            bx = int(round(11.5 + (math.cos(ang) * 4.5)))
            by = int(round(12.5 + (math.sin(ang) * 4.5)))
            v[max(0, bx - 3):bx + 3, max(0, by - 3):by + 3, max(0, z0 - 1):hgt] = 0
    #! 横の節（立った柱にも入れる）。
    for z in (9, 19, 28):
        if z < hgt - 2:
            layer = v[:, :, z]
            layer[layer > 0] = C['gen_bas_j']
    #! 横たわる 1 本（東西に。**+y ＝手前**へ置いて根元と重ならないようにする）。
    ly = 25.0
    for x in range(int(rng.integers(2, 6)), int(rng.integers(22, 28))):
        for y in range(19, 31):
            for z in range(0, 11):
                dy, dz = y - ly, z - 4.6
                q = max(abs(dz), abs(dz * 0.5 + dy * 0.8660254),
                        abs(dz * 0.5 - dy * 0.8660254))
                if q <= 4.6:
                    v[x, y, z] = C['gen_bas_d'] if q < 3.6 else C['gen_bas']
    #! 転がる欠片（2〜3 個。**多いとただの瓦礫**になる）。
    for _ in range(int(rng.integers(2, 4))):
        _hex_prism(v, int(rng.integers(18, 28)), int(rng.integers(2, 12)),
                   0, int(rng.integers(3, 6)), 3.2, C['gen_bas_d'], C['gen_bas'])
    return [('main', v, (0, 0, 0))]


def mossrock_glow_gb(name):
    """**光苔の岩** — 玄武の沢の通路の壁際（調査 §3.4 ④「洞窟に光苔が生息」）。

    原作では光苔は玄武の沢の洞窟の生き物である（先方は虹龍洞の特産品にしているが、
    **両方に置いても矛盾しない**——調査 §3.13 の見立て）。

    ## 光らせられない（実測。2026-08-21）
    自発光は**インスタンス単位**で、`terrain_view.cpp` の装飾層が渡しているのは
    **炎の枠（`fire_flame`）だけ**、しかも色は橙のべた書き（1.35/0.85/0.30）である。
    壁際の枠には 0 しか渡らないので、**苔を本当に光らせる道は無い**（枠を増やすのは
    必守制約 4 が禁じている）。だから**明度で言う**——暗い玄武岩の上に周りより
    3 段明るい青緑を置くと、見た目には光って見える。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 20), np.int16)
    #! 岩（2〜3 個。**六角柱の欠片**なので角がある）。
    #! **細く高く**（2026-08-21 の 2 版。半径 7 の塊を 3 つ並べた初版はマスいっぱいの
    #! 平たい皿になり、「苔の生えた岩」ではなく**緑の敷物**に見えた）。
    for _ in range(int(rng.integers(2, 4))):
        _hex_prism(v, int(rng.integers(10, 22)), int(rng.integers(10, 22)),
                   0, int(rng.integers(8, 18)), float(rng.uniform(3.4, 5.4)),
                   C['gen_bas'], C['gen_bas_l'])
    #! 苔（**天面**＝光の当たる側から。裏まで塗ると苔玉になる）。
    for x in range(V):
        for y in range(V):
            top = -1
            for z in range(19, -1, -1):
                if v[x, y, z] > 0:
                    top = z
                    break
            if top < 2:
                continue
            r = rng.random()
            if r < 0.42:
                v[x, y, top] = C['gen_moss']
            elif r < 0.62:
                v[x, y, top] = C['gen_moss_l']
            elif r < 0.78:
                v[x, y, top] = C['gen_moss_d']
    #! 南面（+y の側）へ垂れる苔。**外皮の 1 枚だけ**を塗る。
    for x in range(V):
        for z in range(2, 18):
            for y in range(V - 1, 0, -1):
                if v[x, y, z] == 0:
                    continue
                if rng.random() < 0.32:
                    v[x, y, z] = C['gen_moss_d']
                break
    return [('main', v, (0, 0, 0))]


def kappa_gear_gb(name):
    """**河童の機械** — 玄武の沢の部屋の中（調査 §3.4 ⑤）。

    住人が河童 ×3 ＋**河童のエンジニア**＝アジトそのものなので、部屋の中に
    「釜と歯車と管」を置く。**水車でもトロッコでもない**——`change2.txt` が
    エンジニアと書いている以上、道具は工学の側にする。

    ## 歯車は**南（+y）**に立てる（2026-08-21。2 度置き直した）
    初版は歯車を釜の西の端（−x）に付けたので**カメラからは釜の陰**になり、
    絵に出るのは銅の胴だけ——ただの樽に見えた。2 版は「前」を y の小さい側と
    取り違えて北へ付け、やはり釜に隠れた（**+y が南＝カメラ側**＝罠）。
    管も釜の天を這わせず、**上へ抜いてから東へ折る**（天に寝かせた初版は
    釜の天面と同じ高さで、平らな茶色の板に融けていた）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 28), np.int16)
    #! 台（据わりを作る。無いと機械が浮く）。
    v[4:28, 5:25, 0:2] = C['iron']
    #! 銅の釜（東西に寝た円筒。**北寄り**に置いて、南（手前）を歯車に空ける）。
    for x in range(7, 26):
        for y in range(V):
            for z in range(V):
                r = math.hypot(y - 13.0, z - 9.5)
                if r <= 6.4:
                    v[x, y, z] = C['gen_cu'] if r < 5.4 else C['gen_cu_l']
    #! 箍（真鍮の帯を 3 本）。
    for x in (10, 16, 22):
        band = v[x, :, :]
        band[(band == C['gen_cu']) | (band == C['gen_cu_l'])] = C['gen_bra']
    #! 歯車（**南＝ +y に立てる**。x–z の面に置くので、見下ろすカメラに歯が見える）。
    for x in range(V):
        for z in range(V):
            r = math.hypot(x - 17.0, z - 10.0)
            if r > 9.4:
                continue
            ang = math.atan2(z - 10.0, x - 17.0)
            if (r <= 7.8) or (math.cos(ang * 9.0) < 0.0):
                v[x, 21:24, z] = C['gen_bra'] if r > 6.6 else C['gen_bra_l']
    #! 輻（**中を彫って 4 本の腕にする**。詰まった円盤は歯車に見えない＝ V7）。
    for x in range(V):
        for z in range(V):
            r = math.hypot(x - 17.0, z - 10.0)
            if not (2.6 < r < 6.4):
                continue
            ang = math.atan2(z - 10.0, x - 17.0)
            if abs(math.cos(ang * 2.0)) < 0.86:
                v[x, 21:24, z] = 0
    v[15:19, 19:25, 8:12] = C['iron']      # 軸受け
    v[16:18, 18:27, 9:11] = C['iron_l']    # 軸（手前へ突き出す）
    #! 管（釜の天から**上へ抜けてから**東へ折れる。継ぎ手を 2 つ膨らませる）。
    v[12:16, 11:15, 15:24] = C['gen_cu_d']
    v[11:17, 10:16, 22:24] = C['gen_bra']
    v[15:29, 11:15, 22:24] = C['gen_cu_d']
    v[26:29, 10:16, 21:25] = C['gen_bra']
    #! 手回しの弁（管の途中に小さな輪。**河童の道具**であることの念押し）。
    for y in range(V):
        for z in range(V):
            r = math.hypot(y - 13.0, z - 27.0)
            if 3.0 < r <= 4.2:
                v[19:21, y, min(z, 27)] = C['iron_l']
    v[19:21, 12:15, 24:26] = C['iron']
    #! 錆と水垢（河童の道具は水の中で使う）。
    for _ in range(int(rng.integers(4, 8))):
        x = int(rng.integers(8, 25))
        y = int(rng.integers(8, 18))
        z = int(rng.integers(2, 16))
        if v[x, y, z] > 0:
            v[x:x + 3, y:y + 2, z:z + 2] = C['rust']
    return [('main', v, (0, 0, 0))]


# ------------------------------------------------------------------- 10 仙界（ガラス）
GLASS_BASE = 7  #!< 不透明な基礎の高さ（32 の 2 割強。決めたこと D4）


def _glass_block(v, rng, dense):
    """**下 2 割の不透明な基礎 ＋ 枠と格子だけの空隙ブロック**（D4）。

    ボクセルは不透明前提なので**半透明は使わない**（そう決めた）。
    「透けている」は**中身を空にする**ことで出す——枠（12 稜）と格子（縦横の桟）だけを
    残し、間は本当に何も無い。既存の `door_glass_*` と同じ流儀で、視界も通るし、
    地面を透過させる必要もない。

    `dense` が真なら格子を 1 段細かくする（岩盤＝奥へ続く厚み）。
    """
    h = v.shape[2]
    #! 基礎（磨いた白玉。**天面に 1 段の縁**を彫って基礎と枠を切る）。
    v[:, :, 0:GLASS_BASE] = C['sen_st_d']
    v[:, :, GLASS_BASE - 2:GLASS_BASE] = C['sen_st']
    v[1:V - 1, 1:V - 1, GLASS_BASE - 1] = C['sen_st_l']
    #! 12 稜の枠（角柱 4 本 ＋ 天の胴縁）。**3 ボクセル角**——細いと骨に見え、
    #! 太いと石の壁に戻る。
    for x0 in (0, V - 3):
        for y0 in (0, V - 3):
            v[x0:x0 + 3, y0:y0 + 3, GLASS_BASE:h] = C['sen_st']
            v[x0:x0 + 3, y0:y0 + 3, h - 3:h] = C['sen_st_l']
    for a, b in ((0, 3), (V - 3, V)):
        v[a:b, :, h - 3:h] = C['sen_st']
        v[:, a:b, h - 3:h] = C['sen_st']
    #! 腰の胴縁（**格子の 1 本目**）。
    mid = GLASS_BASE + (h - GLASS_BASE) // 2
    for a, b in ((0, 2), (V - 2, V)):
        v[a:b, :, mid:mid + 2] = C['sen_gl_d']
        v[:, a:b, mid:mid + 2] = C['sen_gl_d']
    #! 縦の桟（面ごとに 1〜3 本。硝子の板を割る）。**変種ごとに割り方を変える**
    #! ——初版は種を罅にしか使っておらず、**10 枚がほぼ同一**だった（実測。
    #! ボクセル数が 10 枚中 7 枚で 1 ボクセルも違わなかった）。
    plans = (((10, 21), (7, 15, 23), (12, 19)) if dense
             else ((15,), (10, 21), (13,), (9, 20)))
    for u in plans[int(rng.integers(0, len(plans)))]:
        for a, b in ((0, 2), (V - 2, V)):
            v[u:u + 2, a:b, GLASS_BASE:h - 3] = C['sen_gl_d']
            v[a:b, u:u + 2, GLASS_BASE:h - 3] = C['sen_gl_d']
    #! 稜の照り（**硝子の記号**。角が明るいと「面が在るのに向こうが見える」に読める）。
    for x0 in (0, V - 1):
        v[x0, 0, GLASS_BASE:h] = C['sen_gl_l']
        v[x0, V - 1, GLASS_BASE:h] = C['sen_gl_l']
    #! 天の格子（見下ろすカメラでは天面がいちばん広い。**ここが空だと穴に見える**ので、
    #! 桟だけを渡して「硝子の天井」にする。中は空のまま＝透けの読みは保つ）。
    step = int(rng.integers(6, 9)) if dense else int(rng.integers(9, 13))
    for u in range(step, V - 2, step):
        v[u:u + 2, 1:V - 1, h - 2:h] = C['sen_gl']
        v[1:V - 1, u:u + 2, h - 2:h] = C['sen_gl']
    #! **内側の筋交い**（X 字に渡した磨りガラスの薄板）。
    #!
    #! ## なぜ要るのか（2026-08-21 の実測。`--terrain-check --dungeon=10` が FAIL した）
    #! 中を本当に空にすると、**マスをまっすぐ突き抜けて背景が見える**。合成フレームの
    #! 「四隅の欠け」検査（`hd2d_app.cpp` の `gap_ratio < 0.0005`）はそれを
    #! 下塗り色として数えるので、カメラを寄せると 0.079% で落ちた。
    #!
    #! **半透明は使わない**（D4）ままこれを塞ぐには、**視線を必ず 1 枚横切らせる**しかない。
    #! 対角に 2 枚渡すと、マスを横切るどんな水平の線も必ずどちらかに当たる。
    #! 見た目には**枠の奥に薄い面がある**＝磨りガラスの読みになり、
    #! 「向こうが透けて見える」感じは（面がマスの真ん中に在るので）むしろ深くなる。
    for t in range(V):
        for a, b in ((t, t), (t, min(V - 1, t + 1)),
                     (t, V - 1 - t), (t, max(0, V - 2 - t))):
            v[a, b, GLASS_BASE:h - 3] = C['sen_gl']
    #! 罅（**1 枚に 1 本だけ**。全部のマスに入ると割れた城になる）。
    if rng.random() < 0.25:
        u = int(rng.integers(6, 24))
        z = int(rng.integers(GLASS_BASE + 2, h - 8))
        for k in range(6):
            v[max(0, u + k - 3):max(1, u + k - 1), 0:2, z + k] = C['sen_gl_l']


def wall_glass_gb(name):
    """**ガラスの壁** — 仙界（先方データは壁が `GLASS_WALL` 100%）。

    幻想蛮怒の 218（`GLASS_WALL`）は共通の対応表に行が無く**役割の壁へ落ちる**ので、
    意匠の材がそのまま受ける（設計 §2.4）。作りは D4——半透明は使わない。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    _glass_block(v, rng, dense=False)
    return [('main', v, (0, 0, 0))]


def bedrock_glass_gb(name):
    """**ガラスの塊**（岩盤の位置）— 仙界。格子を 1 段細かくし、中に磨りガラスの芯を通す。

    岩盤は「厚い壁の中身」なので、**奥へ続いている**ことを芯で言う
    （書架の岩盤を「隙間なく詰まった書架」にしたのと同じ考え）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    _glass_block(v, rng, dense=True)
    #! 磨りガラスの芯（**角を落とした 8 角**。角柱のままだと枠の中に柱が立って見える）。
    for x in range(V):
        for y in range(V):
            dx, dy = abs(x - 15.5), abs(y - 15.5)
            if (max(dx, dy) <= 6.0) and ((dx + dy) <= 8.6):
                edge = (max(dx, dy) > 4.6) or ((dx + dy) > 7.2)
                v[x, y, GLASS_BASE:WALL_H - 3] = C['sen_gl_d'] if edge else C['sen_gl']
    return [('main', v, (0, 0, 0))]


def floor_jade_gb(name):
    """**白玉の床** — 仙界（設計 §5.3 に無い 1 枚。2026-08-21 に足した）。

    ## なぜ足したか
    §5.3 は仙界の材を「壁と岩盤」だけにしていたが、**ガラスの壁を入れた合成フレームで
    床が変愚の茶色い敷石のまま残り、雲上の白の中に土の色が 1 面だけ居座った**
    （実測）。調査 §3.9 の「外せない 1 点」は**雲上の白を残す**ことなので、
    床が茶色いままではその 1 点が立たない。先方データの床は 100% が既定＝材が素直に効く。

    大判の白玉を敷き、**雲の紋を 1 段彫る**（道教の仙境の型。塗るだけでは V7 のとおり
    四角形が 1 つも増えないが、**彫れば溝の影が出る**）。
    """
    rng = rng_for(name)
    idx = int(name.rsplit('_', 1)[1])
    v = np.zeros((V, V, FLOOR_H), np.int16)
    top = FLOOR_H - 1
    #! 彫った底は**明るいまま**にする（2026-08-21 の 2 版。底に濃い青灰を敷いた初版は
    #! 目地も欠けも**白い床に空いた黒い穴**に見えた。溝は AO と影でどうせ暗くなるので、
    #! 素材の側で暗くすると二重に効く＝共通パレットの `crack` の註記と同じ話）。
    for z in range(FLOOR_H):
        v[:, :, z] = C['sen_gl_d'] if z < top - 1 else C['sen_st_d']
    v[:, :, 0] = C['sen_gl_d']
    #! 大判の敷石（半枚ずらして芋目地を避ける。目地は 1 列残して彫る）。
    face = np.zeros((V, V), np.int16)
    step = 16
    for by in range(0, V, step):
        off = ((by // step) % 2) * (step // 2)
        for bx in range(-step, V + step, step):
            x0 = bx + off
            shade = rng.choice([C['sen_st'], C['sen_st_l'], C['sen_st_d']], p=[0.5, 0.3, 0.2])
            xa, xb = max(x0, 0), min(x0 + step - 1, V)
            ya, yb = max(by, 0), min(by + step - 1, V)
            if (xa < xb) and (ya < yb):
                face[xa:xb, ya:yb] = shade
    v[:, :, top] = face
    #! 雲の紋（**半分の変種だけ**。全部のマスに入ると壁紙になる）。渦を 1 段彫る。
    #! **線を繋げる**（2026-08-21 の 2 版。0.42 rad 刻みで点を打った初版は、
    #! 渦の外側で点が離れ、**磨いた床に散った黒い斑**に見えた。紋は線であって点ではない
    #! ——刻みを細かくし、幅を 2 にして繋げる）。
    if (idx % 2) == 1:
        cx = float(rng.integers(11, 21))
        cy = float(rng.integers(11, 21))
        ang = float(rng.uniform(0.0, 6.28))
        rad = 2.0
        for _ in range(150):
            ang += 0.075
            rad += 0.058
            x = int(round(cx + (math.cos(ang) * rad)))
            y = int(round(cy + (math.sin(ang) * rad)))
            if (0 <= x < V - 1) and (0 <= y < V - 1):
                v[x:x + 2, y:y + 2, top] = 0
                v[x:x + 2, y:y + 2, top - 1] = C['sen_gl']
    #! 欠け（角を 1 段落とす。**磨いた玉でも縁は欠ける**。0〜1 か所だけ）。
    for _ in range(int(rng.integers(0, 2))):
        x = int(rng.integers(0, V - 3))
        y = int(rng.integers(0, V - 3))
        v[x:x + int(rng.integers(2, 5)), y:y + int(rng.integers(2, 5)), top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def crane_statue_gb(name):
    """**鶴の石像** — 仙界の部屋の縁・壁際・部屋の中（調査 §3.9 ①）。

    いま出ているのは変愚の「天界」の**翼の像**（`statue_winged`）である
    ——**道教の仙界に西洋の天使**。方向（雲上の白）は合っているので、
    差し替えるのは記号だけで済む: 翼の像 → **鶴**。丈 54（`pillar_stone` と同じ）。

    ## 鶴に見せる 3 点（2026-08-21。2 度作り直した）
    1. **横を向かせる。**カメラは真南から見下ろす（`--terrain-check` の向きの検査で
       screen-down = world +y）ので、**南を向けた 2 版は正面から見て細い棒**になった。
       鳥は**影絵で読む**もので、影絵が立つのは真横だけである——だから東を向かせる
    2. **胴は前後（東西）に長い卵。**初版は翼の段を胴の外まで塗って
       **横木の出た十字架**になった。彫りも塗りも**胴が在る所だけ**に限る
    3. **首は胴の丈と同じだけ長く、S 字に前へ。**鶴の丈のおよそ 1/3 が首である。
       嘴は頭の 1.5 倍の長さで **+x へ真っ直ぐ**。丹頂の朱は頭の天に 1 点だけ
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 56), np.int16)
    #! 台座（3 段。`pillar_stone` の据わりに合わせる）。
    v[9:23, 9:23, 0:2] = C['sen_st_d']
    v[10:22, 10:22, 2:4] = C['sen_st']
    v[11:21, 11:21, 4:5] = C['sen_st_l']
    #! 脚（2 本。**細く長く**——鶴の丈の 1/3 は脚である）。左右（南北）に並べる。
    for y0 in (13, 18):
        v[15:17, y0:y0 + 2, 5:20] = C['sen_st_d']
        v[14:20, y0 - 1:y0 + 3, 5:6] = C['sen_st_d']   # 蹴爪（+x ＝進む向きへ）
    #! 胴（**東西（x）に長い卵**）。
    for x in range(V):
        for y in range(V):
            for z in range(18, 34):
                dx, dy, dz = (x - 15.0) / 7.6, (y - 16.0) / 4.8, (z - 25.5) / 5.2
                if ((dx * dx) + (dy * dy) + (dz * dz)) <= 1.0:
                    v[x, y, z] = C['sen_st']
    #! 尾（**後ろ＝ −x へ跳ね上げる**）。
    for k in range(5):
        v[8 - k:10 - k, 13:19, 26 + k:29 + k] = C['sen_st_d']
    #! 畳んだ翼（胴の両脇に段を**彫る**。**胴が在る所だけ**——外まで塗ると横木になる）。
    for y0 in (11, 20):
        for y in range(y0, y0 + 2):
            for x in range(V):
                for z in range(24, 30):
                    if v[x, y, z] == C['sen_st']:
                        v[x, y, z] = 0 if (z >= 28) else C['sen_st_d']
    #! 首（胴の前の肩から立ち上がり、**S 字**で前へ倒れる。3 角の細さ）。
    for z, cx in ((31, 18.5), (33, 19.4), (35, 19.8), (37, 19.6), (39, 19.0),
                  (41, 18.4), (43, 18.0), (45, 17.8)):
        x0 = int(round(cx)) - 1
        v[x0:x0 + 3, 15:18, z:z + 3] = C['sen_st']
    #! 頭（小さい塊）と嘴（**+x へ真っ直ぐ**）。
    v[16:21, 14:18, 45:50] = C['sen_st']
    v[21:29, 15:17, 46:48] = C['sen_st_d']
    #! 丹頂（**朱を頭の天に 1 点だけ**。白い像に赤が 1 点あると目が行く）。
    v[17:21, 14:17, 49:51] = C['sen_crown']
    #! 欠けと汚れ（仙界は静かな場所だが、像は古い）。
    for _ in range(int(rng.integers(1, 4))):
        x = int(rng.integers(10, 22))
        z = int(rng.integers(6, 24))
        for y in range(V - 1, 0, -1):
            if v[x, y, z] > 0:
                v[x:x + 2, y - 1:y + 1, z:z + 3] = C['sen_st_d']
                break
    return [('main', v, (0, 0, 0))]


def censer_gb(name):
    """**香炉** — 仙界の火の本体（調査 §3.9 ①「白い蝋燭 → 香炉と線香の煙」）。

    青銅の三足の香炉。丈 22 と低いので、**炎の枠（`incense_smoke_gb`）が z=21 から
    立ち上がる**ように高さを合わせてある（立ち松明と炎の関係と同じ）。
    """
    del name  # 磨いた青銅の器なので変種の種を持たない（ガラスの扉と同じ扱い）
    v = np.zeros((V, V, 24), np.int16)
    #! 三足（前 1 本・後ろ 2 本。**+y ＝手前**）。
    for x0, y0 in ((14, 21), (8, 10), (20, 10)):
        v[x0:x0 + 4, y0:y0 + 3, 0:6] = C['sen_bro_d']
        v[x0:x0 + 4, y0:y0 + 3, 0:2] = C['sen_bro']
    #! 胴（丸い鉢）。
    for x in range(V):
        for y in range(V):
            for z in range(6, 17):
                rr = 9.4 - (abs(z - 12.0) * 0.42)
                r = math.hypot(x - 15.5, y - 15.5)
                if r <= rr:
                    v[x, y, z] = C['sen_bro'] if r < (rr - 1.0) else C['sen_bro_l']
    #! 帯（青銅器の輪。1 段だけ暗く）。
    band = v[:, :, 10]
    band[band > 0] = C['sen_bro_d']
    #! 耳（両側の把手。**2 つあると香炉に見える**）。
    for x0 in (4, 24):
        v[x0:x0 + 4, 14:18, 13:19] = C['sen_bro_d']
        v[x0:x0 + 4, 14:18, 17:19] = C['sen_bro']
    #! 灰（**彫って中へ収める**。上へ盛ると鉢が深く見えない）。
    for x in range(V):
        for y in range(V):
            if math.hypot(x - 15.5, y - 15.5) <= 7.0:
                v[x, y, 16:18] = 0
                v[x, y, 16] = C['sen_ash']
    #! 立てた線香 3 本（灰から出る短い軸。煙は別体）。
    for x0, y0 in ((14, 14), (17, 16), (15, 18)):
        v[x0:x0 + 1, y0:y0 + 1, 17:21] = C['sen_bro_d']
    return [('main', v, (0, 0, 0))]


def incense_smoke_gb(name):
    """**線香の煙** — 仙界の炎の枠（`fire_flame`）。

    ## 自発光の色は橙で固定である（実測。2026-08-21）
    `terrain_view.cpp` の装飾層は**炎の枠にだけ**自発光を渡し、その値は
    **(1.35, 0.85, 0.30)** のべた書きである。**枠を増やさない**（必守制約 4）以上、
    青白い光は出せない。だから**燃えている先を橙にする**——線香の火は実際に橙の点なので、
    ここは制約と原作が一致している。**煙は白**で、橙の暈が乗って温かく見える。

    炎（`torch_flame`）と同じく**振り子で 2 枚**にする（合成でゆらぎに見える）。
    """
    del name  # 煙の形は 1 つ（火は 1 種類しか出ない枠なので変種を持たない）
    a = np.zeros((V, V, 38), np.int16)
    b = np.zeros((V, V, 38), np.int16)
    #! 火の点（線香の先。**ここだけ橙**）。
    for x0, y0 in ((14, 14), (17, 16), (15, 18)):
        a[x0:x0 + 1, y0:y0 + 1, 21:22] = C['sen_ember']
    #! 煙（上へ行くほど広がって薄れる。**塊で置く**＝罠 38）。
    for part, sx, sy, phase in ((a, 14, 14, 0.0), (b, 17, 16, 1.6), (b, 15, 18, 3.1)):
        x, y = float(sx), float(sy)
        for z in range(22, 38):
            k = (z - 22) / 16.0
            x += math.sin(phase + (z * 0.42)) * 0.55
            y += math.cos(phase + (z * 0.31)) * 0.45
            wdt = 1 + int(k * 3.0)
            xi = max(0, min(V - wdt, int(round(x))))
            yi = max(0, min(V - wdt, int(round(y))))
            part[xi:xi + wdt, yi:yi + wdt, z:z + 1] = (
                C['sen_smk'] if k < 0.55 else C['sen_smk_d'])
    return [('flame_a', a, (0, 0, 0)), ('flame_b', b, (0, 0, 0))]


def incense_parts():
    """煙は**火の点を支点に**ゆらぐ（`flame_parts` の支点 z=30 は松明の芯の高さ）。

    香炉の火は z=21 にあるので、そこを支点にしないと煙の根が横へ飛ぶ。
    """
    return [
        {'name': 'flame_a', 'voxels': 'flame_a', 'grounded': False,
         'pivot': [16.0, 16.0, 21.0],
         'motion': {'kind': 'pendulum', 'axis': 'x', 'amplitude': 5.0,
                    'period': 1.7, 'phase': 0.0, 'damping': 0.0},
         'wind_k': 0.0},
        {'name': 'flame_b', 'voxels': 'flame_b', 'grounded': False,
         'pivot': [16.0, 16.0, 21.0],
         'motion': {'kind': 'pendulum', 'axis': 'y', 'amplitude': 6.0,
                    'period': 2.3, 'phase': 1.7, 'damping': 0.0},
         'wind_k': 0.0},
    ]


def peach_tree_gb(name):
    """**桃の木** — 仙界の部屋の中（調査 §3.9 ④「不老長寿の記号」）。

    仙人が食べるのは蟠桃である。**マスをまたぐ大きさにはしない**——部屋の中の枠は
    4.5% で出るので、大きすぎると部屋が林になる。丈 46・幹は細く、花と実で言う。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 48), np.int16)
    #! 幹（**まっすぐにしない**。桃は幹が曲がる）。
    x, y = 15.0, 16.0
    for z in range(0, 26):
        x += float(rng.uniform(-0.35, 0.35))
        y += float(rng.uniform(-0.30, 0.30))
        rr = max(1, int(round(3.0 - (z * 0.05))))
        xi, yi = int(round(x)), int(round(y))
        v[xi - rr:xi + rr, yi - rr:yi + rr, z:z + 1] = C['sen_bark']
        v[xi - rr:xi - rr + 1, yi - rr:yi + rr, z:z + 1] = C['sen_bark_l']
    #! 枝（4 本。**外へ広がってから上へ**）。
    tips = []
    for k in range(4):
        ang = ((k / 4.0) * 2.0 * math.pi) + float(rng.uniform(-0.4, 0.4))
        bx, by, bz = x, y, 24.0
        xi, yi, zi = int(round(bx)), int(round(by)), int(round(bz))
        for _ in range(9):
            bx += math.cos(ang) * 1.5
            by += math.sin(ang) * 1.5
            bz += 1.3
            if bz >= 44.0:
                break
            xi = max(1, min(V - 3, int(round(bx))))
            yi = max(1, min(V - 3, int(round(by))))
            zi = int(round(bz))
            v[xi:xi + 2, yi:yi + 2, zi:zi + 2] = C['sen_bark']
        tips.append((xi, yi, zi))
    #! 花（**塊で置く**。1 ボクセルずつ散らすと粒に見えて greedy が効かない＝罠 38）。
    for xi, yi, zi in tips:
        for _ in range(int(rng.integers(4, 8))):
            ox = max(0, min(V - 3, xi + int(rng.integers(-5, 6))))
            oy = max(0, min(V - 3, yi + int(rng.integers(-5, 6))))
            oz = max(0, min(45, zi + int(rng.integers(-4, 5))))
            v[ox:ox + 3, oy:oy + 3, oz:oz + 2] = (
                C['sen_pea'] if rng.random() < 0.6 else C['sen_pea_l'])
    #! 実（**2〜3 個だけ**。多いと花と混ざって色が濁る）。
    for _ in range(int(rng.integers(2, 4))):
        xi, yi, zi = tips[int(rng.integers(0, len(tips)))]
        ox = max(0, min(V - 3, xi + int(rng.integers(-4, 5))))
        oy = max(0, min(V - 3, yi + int(rng.integers(-4, 5))))
        oz = max(2, min(44, zi - int(rng.integers(1, 5))))
        v[ox:ox + 3, oy:oy + 3, oz:oz + 3] = C['sen_fru']
        v[ox:ox + 1, oy:oy + 3, oz:oz + 3] = C['sen_pea_d']
    #! 散った花びら（根元に。**地に色が落ちている**と咲いていることが遠目で分かる）。
    for _ in range(int(rng.integers(3, 7))):
        ox = int(rng.integers(1, V - 3))
        oy = int(rng.integers(1, V - 3))
        v[ox:ox + 2, oy:oy + 2, 0:1] = C['sen_pea_l']
    return [('main', v, (0, 0, 0))]


