# --------------------------------------------------------- 9 逆さ城・7 無縁塚（S3 第 2 回）
for _name, _rgb in (
    # ---- 逆さ城（調査 §3.9 の前半）----
    # 松本城に寄せた 2 色。**上下を入れ替える**——実際の城は下が黒漆の下見板・上が白漆喰で、
    # 逆さ城はその逆（調査 ②）。
    ('sak_kur', (38, 34, 30)), ('sak_kur_l', (64, 58, 50)), ('sak_kur_d', (24, 21, 18)),
    ('sak_shi', (232, 228, 216)), ('sak_shi_d', (192, 186, 172)),
    ('sak_ish', (118, 114, 108)), ('sak_ish_l', (148, 144, 136)), ('sak_ish_d', (86, 82, 78)),
    ('sak_kin', (206, 178, 96)), ('sak_kin_l', (240, 220, 152)),
    ('sak_hari', (186, 192, 202)), ('sak_hari_l', (236, 240, 248)),
    ('sak_shu', (168, 60, 52)),         # 打ち出の小槌の朱漆
    # ---- 無縁塚（調査 §3.7）----
    # **紫の桜**（#9B7CB8〜#C4A8D8）。無縁塚にしか無いものなので、これが唯一の識別点。
    # **彼岸花の赤は使わない**——町 13 彼岸が既に赤で持っていて、混ざる。
    # **明るい側へ振ってある**（2026-08-21 の 2 版）。調査の指定 `#9B7CB8`〜`#C4A8D8` で
    # 組んだ初版は、**灯りの届かないマスで黒に潰れて木だと分からなかった**（実機で実測。
    # 引きの絵に 2 本立っていたのに紫の画素は 97 しか無かった）。ダンジョンの地の明るさは
    # 掛け算で効くので、**素材の側を明るくしないと暗所では読めない**——玄武岩で 1 度
    # 踏んだのと同じ話（V11 の隣）。花は光苔と同じ扱いにして、**明度で目立たせる**。
    ('mue_sak', (206, 172, 232)), ('mue_sak_l', (240, 218, 250)), ('mue_sak_d', (162, 128, 196)),
    ('mue_bark', (74, 62, 58)), ('mue_bark_l', (106, 92, 84)),
    ('mue_ish', (140, 132, 118)), ('mue_ish_l', (174, 166, 150)), ('mue_ish_d', (104, 96, 88)),
    ('mue_ki', (200, 185, 156)),        # 白木（卒塔婆）
    ('mue_sumi', (48, 44, 42)),
    # **外の世界の物**（特産品の一覧がそのまま素材表になっている）。
    # 幻想郷に無い色＝**彩度の高い工業の色**にする。
    ('mue_gara', (168, 206, 214)), ('mue_kan', (178, 182, 190)), ('mue_kan_l', (214, 218, 226)),
    ('mue_aka', (190, 62, 58)), ('mue_ao', (56, 92, 168)),
):
    reg_local(_name, _rgb)


def _sakasa_faces(v, rng, dense):
    """逆さ城の壁の 1 面 — **石垣が天に、下見板が地に**（調査 §3.9 ②）。

    実際の城（松本城）は下から順に**石垣 → 黒漆の下見板 → 白漆喰**と積む。
    逆さ城はその**上下を丸ごとひっくり返す**——それがこの 1 枚の役目のすべてである。

    ## 見える所へ置く（2026-08-21。1 度作り直した）
    初版は「下が白漆喰・上が黒漆」とだけ入れ替えた。**絵に出なかった。**
    見下ろすカメラでは壁の面は**上の 1/3 しか見えない**（残りは床と手前のマスに隠れる）ので、
    上に来た黒漆だけが読め、**ただの黒い壁**になった（合成フレームで実測）。

    逆さの証拠は**上の 1/3 に置かねばならない**。だから順を組み直した:

    | z | 何 | なぜ |
    |---:|---|---|
    | 32〜20 | **石垣**（下へ行くほど石が小さい） | 城の礎石が天に在る＝逆さの決定的な証拠。天面の石垣とも繋がる |
    | 20〜18 | **軒の溝** | 庇が下を向いている |
    | 18〜8 | 白漆喰 | |
    | 8〜0 | 黒漆の下見板 | 実際の城では最下段が石垣なので、板が地に着くのが逆さ |
    """
    h = v.shape[2]
    stone_bottom = 20             # 石垣の下端（ここから下が漆喰と板）
    for face in range(4):
        #! 石垣（**天から下へ、石が小さくなる**＝実際の石垣の上下逆）。
        z = h - 1
        course = 6
        while z > stone_bottom:
            z0 = max(stone_bottom, z - course)
            u = int(rng.integers(0, 4))
            while u < V:
                wdt = course + int(rng.integers(2, 6))
                ua, ub = u, min(u + wdt - 1, V)
                if ua < ub:
                    _paint_face(v, face, ua, ub, z0, z, 0,
                                rng.choice([C['sak_ish'], C['sak_ish_l'], C['sak_ish_d']],
                                           p=[0.46, 0.3, 0.24]))
                #! 縦の合端（**彫る**。塗るだけでは V7 のとおり四角形が増えない）。
                if ub < V:
                    _carve_relief(v, face, ub, ub + 1, z0, z, 1)
                    _paint_face(v, face, ub, ub + 1, z0, z, 1, C['sak_ish_d'])
                u += wdt
            #! 横の合端。
            _carve_relief(v, face, 0, V, z0 - 1, z0, 1)
            _paint_face(v, face, 0, V, z0 - 1, z0, 1, C['sak_ish_d'])
            z = z0 - 1
            course = max(3, course - 1)   # **下ほど小さい**（石垣の逆さ）
        #! 軒の溝（32 の立方体から外へは出せないので、張り出しではなく**えぐりで影**）。
        _carve_relief(v, face, 0, V, stone_bottom - 2, stone_bottom, 2)
        _paint_face(v, face, 0, V, stone_bottom - 2, stone_bottom, 2, C['sak_kur_d'])
        #! 白漆喰。
        _paint_face(v, face, 0, V, 8, stone_bottom - 2, 0, C['sak_shi'])
        #! **逆さの狭間**（白漆喰の中へ彫り込む。金具を 1 つ落とし込む）。
        if dense or (rng.random() < 0.7):
            u0 = int(rng.integers(4, 20))
            _carve_relief(v, face, u0, u0 + 5, 11, 16, 2)
            _paint_face(v, face, u0, u0 + 5, 11, 16, 2, C['sak_kur_d'])
            _paint_face(v, face, u0 + 1, u0 + 4, 12, 15, 2, C['sak_kin'])
        #! 黒漆の下見板（**地に着く**。横板を 3 段ずつ、下端を彫って影を出す）。
        zz = 1
        while zz < 8:
            _paint_face(v, face, 0, V, zz, min(zz + 3, 8), 0, C['sak_kur'])
            _carve_relief(v, face, 0, V, zz, zz + 1, 1)
            _paint_face(v, face, 0, V, zz, zz + 1, 1, C['sak_kur_d'])
            zz += 4


def wall_sakasa_gb(name):
    """**逆さの城壁** — 逆さ城（調査 §3.9「外せない 1 点」）。

    先方データは**壁が暗い穴 100%**（`DARK_PIT`）で、共通の対応表にその行は在るが
    **規則が空**なので役割の壁へ落ちる（設計 V2 の実測）——**材が効く。**

    上が石垣・下が黒漆の下見板（実際の松本城の逆）。天面も**石垣の天端**
    ——上下が逆なのだから、城の礎石はいちばん上に在る。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['sak_shi_d']
    _sakasa_faces(v, rng, dense=False)
    #! 天面＝**石垣**（逆さの城の礎石は天に在る）。目地を彫る。
    top = WALL_H - 1
    v[:, :, top] = C['sak_ish']
    for _ in range(9):
        x0 = int(rng.integers(0, V - 6))
        y0 = int(rng.integers(0, V - 6))
        w = int(rng.integers(5, 11))
        d = int(rng.integers(5, 11))
        v[x0:x0 + w, y0:y0 + d, top] = rng.choice(
            [C['sak_ish'], C['sak_ish_l'], C['sak_ish_d']], p=[0.45, 0.3, 0.25])
        v[x0:x0 + w, y0:y0 + 1, top] = 0
        v[x0:x0 + 1, y0:y0 + d, top] = 0
        v[x0:x0 + w, y0:y0 + 1, top - 1] = C['sak_ish_d']
        v[x0:x0 + 1, y0:y0 + d, top - 1] = C['sak_ish_d']
    return [('main', v, (0, 0, 0))]


def bedrock_sakasa_gb(name):
    """**逆さの城の塊**（岩盤の位置）— 逆さ城。

    岩盤は「厚い壁の中身」なので、**天守の胴**として黒漆の下見板を厚く取り、
    天面には**鯱の代わりに礎石**を並べる（`wall_sakasa_gb` と同じ理屈で上下が逆）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['sak_kur_d']
    _sakasa_faces(v, rng, dense=True)
    top = WALL_H - 1
    v[:, :, top] = C['sak_ish_d']
    for _ in range(6):
        x0 = int(rng.integers(0, V - 8))
        y0 = int(rng.integers(0, V - 8))
        w = int(rng.integers(7, 13))
        d = int(rng.integers(7, 13))
        v[x0:x0 + w, y0:y0 + d, top] = rng.choice(
            [C['sak_ish'], C['sak_ish_d']], p=[0.55, 0.45])
        v[x0:x0 + w, y0:y0 + 1, top] = 0
        v[x0:x0 + 1, y0:y0 + d, top] = 0
    return [('main', v, (0, 0, 0))]


def pillar_inverted_gb(name):
    """**天井から生えた逆さ柱** — 逆さ城の部屋の縁（調査 §3.9「外せない 1 点」）。

    ## 宙に吊る（**接地しない部品**）
    この画面には天井が無いので、柱を床から立てたら逆さにならない。
    `stone_floating` が既にやっている手を借りる——**`grounded` を偽にした部品**は
    原点の高さのまま宙に留まる。柱の voxel を z=15〜56 に置くと、
    **床から 0.47 マス浮いたところで柱が終わる**＝上から生えて途中で切れている。

    形は `pillar_stone` を**上下ひっくり返した**もの: 台座が天に、柱頭が下に、
    繰形の広がりが**下向き**。丈 41（`pillar_stone` の 54 に浮きぶんを足すと同じ天）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 58), np.int16)
    #! 台座（**天に在る**）。
    v[9:23, 9:23, 54:56] = C['sak_ish_d']
    v[10:22, 10:22, 52:54] = C['sak_ish']
    v[11:21, 11:21, 51:52] = C['sak_ish_l']
    #! 柱身（下へ伸びる。角を落として 8 角に＝城の柱は面取りしてある）。
    for x in range(V):
        for y in range(V):
            dx, dy = abs(x - 15.5), abs(y - 15.5)
            if (max(dx, dy) <= 5.5) and ((dx + dy) <= 7.6):
                edge = (max(dx, dy) > 4.2)
                v[x, y, 21:52] = C['sak_kur_l'] if edge else C['sak_kur']
    #! 帯金（3 か所。**彫って**金具を落とし込む＝ V7）。
    for z in (28, 38, 47):
        layer = v[:, :, z:z + 2]
        layer[layer > 0] = C['sak_kin']
    #! 柱頭（**下向きの繰形**。逆さであることはここでいちばん強く読める）。
    v[11:21, 11:21, 19:21] = C['sak_kur']
    v[10:22, 10:22, 17:19] = C['sak_kin']
    v[12:20, 12:20, 15:17] = C['sak_kur_d']
    #! 折れ口（**下端は途中で切れている**。1〜2 か所を欠かせる）。
    for _ in range(int(rng.integers(1, 3))):
        x = int(rng.integers(10, 20))
        y = int(rng.integers(10, 20))
        v[x:x + 4, y:y + 4, 15:19] = 0
    return [('main', v, (0, 0, 0))]


def pillar_inverted_parts():
    """**接地しない**（`stone_floating` の石と同じ扱い）。宙に留まって初めて逆さになる。"""
    return [{'name': 'main', 'voxels': 'main', 'grounded': False,
             'motion': {'kind': 'static'}, 'wind_k': 0.0}]


def needle_giant_gb(name):
    """**巨大な針** — 逆さ城の行き止まりと部屋の中（調査 §3.9 ④）。

    少名針妙丸の「針小棒大」がそのまま記号になっている（二次創作では**巨大な針・
    お椀の舟・打ち出の小槌**が輝針城の三点セットである）。

    **マスをまたぐ大きさで**床へ斜めに刺す。**針の目（穴）を彫る**のが決め手
    ——穴が無いと、ただの銀の棒か槍に見える。丈 54。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 56), np.int16)
    #! 針（斜めに刺さる。**下が細く上が太い**——針は先が尖り、目の側が太い。
    #! 2026-08-21 の 2 版。均一に細い初版は、遠目で**銀の小枝**にしか見えなかった）。
    lean = float(rng.uniform(0.08, 0.16)) * (1.0 if rng.random() < 0.5 else -1.0)
    for z in range(0, 54):
        cx = 15.5 + (lean * z)
        cy = 16.5 + (lean * 0.5 * z)
        r = 1 if z < 8 else (2 if z < 26 else 3)
        x0 = int(round(cx)) - r
        y0 = int(round(cy)) - r
        v[x0:x0 + (r * 2), y0:y0 + (r * 2), z:z + 1] = C['sak_hari']
        v[x0:x0 + 1, y0:y0 + (r * 2), z:z + 1] = C['sak_hari_l']   # 稜の照り
    #! 針の目（**彫って抜く**。これが無いと銀の棒か槍にしか見えない）。
    for z in range(38, 50):
        cx = 15.5 + (lean * z)
        cy = 16.5 + (lean * 0.5 * z)
        x0 = int(round(cx))
        y0 = int(round(cy))
        w = 2 if (40 <= z <= 48) else 1
        v[x0 - w:x0 + w, y0 - 3:y0 + 3, z:z + 1] = 0
    #! 刺さり口の割れ（床石を割って立っている）。
    for _ in range(int(rng.integers(3, 6))):
        ang = float(rng.uniform(0.0, 6.28))
        for k in range(int(rng.integers(4, 9))):
            x = int(round(15.5 + (math.cos(ang) * (3.0 + k))))
            y = int(round(16.5 + (math.sin(ang) * (3.0 + k))))
            if (0 <= x < V) and (0 <= y < V):
                v[x, y, 0:1] = C['sak_ish_d']
    #! 傍らに転がる**お椀の舟**（1 つだけ。輝針城の三点セットの 2 つ目）。
    for x in range(V):
        for y in range(V):
            for z in range(0, 7):
                r = math.hypot(x - 24.0, y - 8.0)
                if (r <= 6.2) and (r >= 4.6 or z <= 1):
                    v[x, y, z] = C['sak_kin'] if z > 1 else C['sak_kin_l']
    return [('main', v, (0, 0, 0))]


def mallet_gb(name):
    """**打ち出の小槌** — 逆さ城の部屋の中（調査 §3.9 ⑤）。

    鬼人正邪と少名針妙丸が幻想郷をひっくり返そうとした道具そのもの。
    **床に転がしておく**（誰も持っていない＝異変は終わっている）。丈は 14 と低い。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 16), np.int16)
    #! 槌の頭（横倒し。**六角の胴に金の輪**）。
    for y in range(V):
        for z in range(V):
            dy, dz = y - 16.0, z - 6.5
            q = max(abs(dz), abs(dz * 0.5 + dy * 0.8660254),
                    abs(dz * 0.5 - dy * 0.8660254))
            if q <= 6.0:
                v[7:19, y, z] = C['sak_shu']
    for x in (8, 17):
        band = v[x, :, :]
        band[band > 0] = C['sak_kin']
    #! 打ち出の面（東西の小口。**金で縁を取る**）。
    for x0 in (7, 18):
        for y in range(V):
            for z in range(V):
                dy, dz = y - 16.0, z - 6.5
                if math.hypot(dy, dz) <= 5.4:
                    v[x0, y, z] = C['sak_kin_l']
    #! 柄（東へ。**握りに紐**）。
    v[19:30, 15:17, 5:7] = C['mue_bark']
    v[24:26, 14:19, 3:8] = C['sak_kin']
    v[28:30, 14:19, 3:8] = C['sak_kin_l']
    #! 落ちた小判 2〜3 枚（**打ち出の**小槌である証）。
    for _ in range(int(rng.integers(2, 4))):
        x = int(rng.integers(2, 26))
        y = int(rng.integers(2, 12))
        v[x:x + 5, y:y + 3, 0:1] = C['sak_kin']
    return [('main', v, (0, 0, 0))]


def railing_gb(name):
    """**欄干** — 逆さ城の通路の壁際（調査 §3.9 ③）。

    足元の**暗い穴 30%** はコア側から来るので、「床が抜けている」恐怖は既に地形が持つ。
    こちらは**穴の縁に欄干を回す**——それで「城の中で床が抜けている」に読める。

    ## 卓に見えないようにする（2026-08-21。1 度作り直した）
    初版は架木を上から 2 番目に置き、下にも平桁を渡して束を 5 本入れた
    ——出来上がったのは**黒い長机**だった（実測）。欄干と机を分けるのは 3 点:

    1. **架木は天のいちばん上。**下に横木を渡さない（渡すと天板と幕板になる）
    2. **束は細く多く**（1 ボクセル幅を 8 本）。太い束が 4〜5 本だと脚に見える
    3. **束は地まで下ろす。**宙で終わると机の脚になり、地に着くと柵になる
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 26), np.int16)
    Y = 20                        # **南（+y）寄り**に立てる＝手前の縁
    #! 親柱 2 本と擬宝珠（**地から立てる**）。
    for x0 in (1, 28):
        v[x0:x0 + 3, Y:Y + 3, 0:20] = C['sak_kur']
        v[x0 - 1:x0 + 4, Y - 1:Y + 4, 20:22] = C['sak_kin']
        v[x0:x0 + 3, Y:Y + 3, 22:25] = C['sak_kin_l']
    #! 架木（**天のいちばん上に 1 本だけ**）。
    v[1:31, Y:Y + 3, 17:20] = C['sak_kur_l']
    #! 地覆（見切り。**横木ではなく縁石の高さ**に留める）。
    v[1:31, Y:Y + 3, 0:2] = C['sak_kur_d']
    #! 束（**細く多く・地まで**。1 ボクセル幅を 8 本）。
    for x0 in range(5, 28, 3):
        v[x0:x0 + 1, Y + 1:Y + 3, 2:17] = C['sak_kur_l']
    #! 欠け（1〜2 本は折れている。**城は空っぽで手入れされていない**）。
    for _ in range(int(rng.integers(1, 3))):
        x0 = int(rng.integers(4, 27))
        v[x0:x0 + 3, Y:Y + 3, 8:20] = 0
    return [('main', v, (0, 0, 0))]


# ------------------------------------------------------------------- 7 無縁塚
def sakura_violet_gb(name):
    """**紫の桜** — 無縁塚の部屋の縁（調査 §3.7「外せない 1 点」）。

    **無縁塚にしか存在しない妖怪桜**で、幽玄な美しさを誇る（求聞史紀）。
    **これが無縁塚の唯一の識別点**である——彼岸花の赤を主役にすると、
    町 13「彼岸」が既に赤を持っているので区別が付かなくなる。

    丈 60・**枝がマスをまたぐ**（部屋の縁の枠は 10% でしか出ないので、大きくてよい）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 62), np.int16)
    #! 幹（**根元を太く、上で二又**。桜は根張りが目立つ）。
    x, y = 15.0, 16.0
    for z in range(0, 30):
        x += float(rng.uniform(-0.30, 0.30))
        y += float(rng.uniform(-0.25, 0.25))
        rr = max(2, int(round(4.6 - (z * 0.085))))
        xi, yi = int(round(x)), int(round(y))
        v[xi - rr:xi + rr, yi - rr:yi + rr, z:z + 1] = C['mue_bark']
        v[xi - rr:xi - rr + 1, yi - rr:yi + rr, z:z + 1] = C['mue_bark_l']
    #! 根（**+y ＝手前へ 3 本**。地面から浮き出る根が老木の証）。
    for ang in (0.9, 1.8, 2.7):
        for k in range(7):
            xi = max(0, min(V - 3, int(round(15.0 + (math.cos(ang) * (4 + k * 1.6))))))
            yi = max(0, min(V - 3, int(round(16.0 + (math.sin(ang) * (4 + k * 1.6))))))
            v[xi:xi + 3, yi:yi + 3, 0:max(1, 3 - (k // 3))] = C['mue_bark']
    #! 枝（5 本。**外へ広げてから上へ**——枝垂れではないので上向きに）。
    tips = []
    for k in range(5):
        ang = ((k / 5.0) * 2.0 * math.pi) + float(rng.uniform(-0.35, 0.35))
        bx, by, bz = x, y, 28.0
        xi, yi, zi = int(round(bx)), int(round(by)), int(round(bz))
        for _ in range(10):
            bx += math.cos(ang) * 1.7
            by += math.sin(ang) * 1.7
            bz += 1.9
            if bz >= 56.0:
                break
            xi = max(1, min(V - 3, int(round(bx))))
            yi = max(1, min(V - 3, int(round(by))))
            zi = int(round(bz))
            v[xi:xi + 2, yi:yi + 2, zi:zi + 2] = C['mue_bark']
        tips.append((xi, yi, zi))
    #! 花（**塊で置く**＝罠 38。紫を 3 段に振り、上ほど明るく＝光を受ける側）。
    for xi, yi, zi in tips:
        for _ in range(int(rng.integers(7, 12))):
            ox = max(0, min(V - 4, xi + int(rng.integers(-7, 8))))
            oy = max(0, min(V - 4, yi + int(rng.integers(-7, 8))))
            oz = max(28, min(58, zi + int(rng.integers(-6, 7))))
            tone = rng.choice([C['mue_sak'], C['mue_sak_l'], C['mue_sak_d']],
                              p=[0.45, 0.33, 0.22])
            v[ox:ox + 4, oy:oy + 4, oz:oz + 2] = tone
    #! 散った花びら（根元に。**地に紫が落ちている**と咲いていることが遠目で分かる）。
    for _ in range(int(rng.integers(5, 10))):
        ox = int(rng.integers(0, V - 3))
        oy = int(rng.integers(0, V - 3))
        v[ox:ox + 2, oy:oy + 2, 0:1] = C['mue_sak_l']
    return [('main', v, (0, 0, 0))]


def grave_nameless_gb(name):
    """**無縁仏の石** — 無縁塚の行き止まりと壁際（調査 §3.7 ②）。

    **縁者の居ない者の遺体を埋める場所**なので、墓標には**名が無い**——
    字の彫っていない自然石を**不等間隔に**寄せる。1 本だけ白木の卒塔婆を添える
    （彼岸の町の `sotoba_hig` は塔婆そのものなので、こちらは石を主役にする）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 24), np.int16)
    #! 土饅頭（低い盛り土。**塚**であることの下地）。
    for x in range(V):
        for y in range(V):
            r = math.hypot(x - 15.5, y - 16.5)
            if r <= 12.0:
                v[x, y, 0:max(1, int(3.0 - (r * 0.2)))] = C['mue_ish']
    #! 名の無い石（4〜6 個。**高さも傾きもばらばら**——揃うと霊園になる）。
    for _ in range(int(rng.integers(4, 7))):
        cx = int(rng.integers(4, 25))
        cy = int(rng.integers(6, 25))
        w = int(rng.integers(4, 8))
        d = int(rng.integers(3, 6))
        hgt = int(rng.integers(6, 17))
        tilt = int(rng.integers(-1, 2))
        #! **明るい側へ寄せる**（2026-08-21。暗い石を主にした初版は、盛り土の影と
        #! 融けて**黒い塊**にしか見えなかった。墓石は風化して白茶けるものである）。
        tone = rng.choice([C['mue_ish'], C['mue_ish_l'], C['mue_ish_d']], p=[0.42, 0.44, 0.14])
        for z in range(hgt):
            ox = max(0, min(V - w, cx + ((z * tilt) // 5)))
            v[ox:ox + w, cy:cy + d, z:z + 1] = tone
        #! 天は丸める（自然石なので角が無い）。
        ox = max(0, min(V - w, cx + (((hgt - 1) * tilt) // 5)))
        v[ox:ox + 1, cy:cy + d, hgt - 2:hgt] = 0
        v[ox + w - 1:ox + w, cy:cy + d, hgt - 2:hgt] = 0
    #! 白木の卒塔婆 1 本（**墨の字は 3 画だけ**——読めなくてよい）。
    sx = int(rng.integers(3, 22))
    v[sx:sx + 3, 8:9, 0:21] = C['mue_ki']
    v[sx:sx + 3, 8:9, 21:] = 0
    for k in range(4):            # 頭の刻み（塔婆の五輪の形。**上ほど細る**）
        z = 17 + k
        v[sx:sx + 3, 8:9, z:z + 1] = 0
        v[sx + (k // 2):sx + 3 - (k // 2), 8:9, z:z + 1] = C['mue_ki']
    v[sx + 1:sx + 2, 8:9, 8:18] = C['mue_sumi']
    return [('main', v, (0, 0, 0))]


def drift_gb(name):
    """**外の世界の漂着物** — 無縁塚の部屋の中と壁際（調査 §3.7 ③）。

    無縁塚の特産品は**宝石 12 種＋ミスリル＋…＋プリズム＋河童の腕＋
    イザナギオブジェクト**＝**外から流れ着いた物の山**である。
    **これが無縁塚の二重の性格（墓地 ＋ 漂着物）を絵にする唯一の手。**

    幻想郷に無い物を並べる: **傘・眼鏡・缶・瓶・時計**。
    見分けの要は**色**——ここだけ彩度の高い工業の色を使う（周りは草と石と紫の桜）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 14), np.int16)
    #! 傘（畳んで転がっている。**赤い布と銀の柄**。いちばん大きいので主役）。
    for x in range(4, 24):
        r = 2 if x < 19 else 1
        v[x, 20 - r:20 + r, 1:1 + (r * 2)] = C['mue_aka']
    v[22:29, 19:21, 1:3] = C['mue_kan_l']
    v[3:5, 18:22, 0:4] = C['mue_sumi']       # 石突
    #! 缶（立っている 1 つ・倒れた 1 つ）。
    for x in range(V):
        for y in range(V):
            if math.hypot(x - 25.0, y - 9.0) <= 3.2:
                v[x, y, 0:7] = C['mue_kan']
                v[x, y, 5:6] = C['mue_ao']
    v[8:16, 4:8, 0:4] = C['mue_kan_l']
    v[10:12, 4:8, 0:4] = C['mue_aka']
    #! 瓶（硝子。**倒れて口が欠けている**）。
    v[15:24, 13:17, 0:4] = C['mue_gara']
    v[23:26, 14:16, 1:3] = C['mue_gara']
    #! 眼鏡（**輪 2 つと弦**。小さいが「外の世界」がいちばん強く出る）。
    for cx in (7, 13):
        for x in range(V):
            for y in range(V):
                r = math.hypot(x - cx, y - 26.0)
                if 1.8 < r <= 2.8:
                    v[x, y, 0:1] = C['mue_sumi']
    v[9:12, 25:27, 0:1] = C['mue_sumi']
    v[3:6, 25:27, 0:1] = C['mue_sumi']
    #! 時計（文字盤。**針を 2 本**）。
    for x in range(V):
        for y in range(V):
            r = math.hypot(x - 25.0, y - 24.0)
            if r <= 4.4:
                v[x, y, 0:2] = C['mue_kan_l'] if r > 3.4 else C['mue_gara']
    v[25:26, 21:25, 2:3] = C['mue_sumi']
    v[25:28, 24:25, 2:3] = C['mue_sumi']
    #! 草に埋もれかけている（**+y の側へ土を寄せる**。落ちて久しい物である）。
    for _ in range(int(rng.integers(3, 7))):
        x = int(rng.integers(0, V - 4))
        y = int(rng.integers(0, V - 4))
        v[x:x + 4, y:y + 3, 0:1] = C['mue_ish_d']
    return [('main', v, (0, 0, 0))]


