# ------------------------------------------------------------------- 12 混沌の領域
def floor_sea_gb(name):
    """**凪の水面** — 混沌の領域（調査 §3.1 ③）。

    **静かの海**は月の裏側の正反対＝地上に最も近い所で、**水面に大きな地球の光が
    映える凪の海**である（儚月抄）。水に映る星は一種の「境界」。

    **波を立てない。**既存の `water_shallow` は細かいさざ波を持っているが、
    ここは「凪」なので**長い横の筋を 2〜3 本**だけ引く——地球の光の映り込みである。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, FLOOR_H), np.int16)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['lun_sea_d'] if z < top else C['lun_sea']
    #! 深みのむら（**大きな塊で**。細かく散らすと砂に見える）。
    for _ in range(int(rng.integers(3, 7))):
        w = int(rng.integers(8, 20))
        d = int(rng.integers(8, 20))
        x0 = int(rng.integers(0, V - w))
        y0 = int(rng.integers(0, V - d))
        v[x0:x0 + w, y0:y0 + d, top] = C['lun_sea_d'] if rng.random() < 0.5 else C['lun_sea']
    #! 地球の光の映り（**長い横の筋**。凪の海の唯一の模様）。
    for _ in range(int(rng.integers(2, 4))):
        y0 = int(rng.integers(2, V - 4))
        th = int(rng.integers(1, 3))
        x0 = int(rng.integers(0, 8))
        x1 = int(rng.integers(V - 8, V))
        v[x0:x1, y0:y0 + th, top] = C['lun_sea_l']
    return [('main', v, (0, 0, -FLOOR_H))]


def _lunar_wall(v, rng, dense):
    """月の都の壁 — **朱の腰・白い壁・瑠璃瓦の天**（調査 §3.1 ②）。

    月の都は**中華風の建物が立ち並ぶ**（儚月抄）。変愚の城の意匠（タペストリー・
    鎧立て）＝西洋の城から**離す**のがこの 1 枚の役目である。

    **天面を瑠璃瓦にする**のが決め手——見下ろすカメラでは天面がいちばん広く映るので、
    ここが青く光っていれば、それだけで「中華の甍が並ぶ都」に読める。
    """
    h = v.shape[2]
    for face in range(4):
        #! 腰（朱の下見板。地から 8 段）。
        _paint_face(v, face, 0, V, 0, 8, 0, C['lun_shu'])
        for zz in (2, 5):
            _carve_relief(v, face, 0, V, zz, zz + 1, 1)
            _paint_face(v, face, 0, V, zz, zz + 1, 1, C['lun_shu_d'])
        #! 白い壁（8〜24）。
        _paint_face(v, face, 0, V, 8, 24, 0, C['lun_hak'])
        #! 窓（**丸窓か花頭窓**。中華の壁は開口が丸い）。
        if dense or (rng.random() < 0.75):
            cu = int(rng.integers(8, 22))
            for u in range(V):
                for w in range(8, 24):
                    if math.hypot(u - cu, w - 15.0) <= 5.0:
                        _carve_relief(v, face, u, u + 1, w, w + 1, 2)
                        _paint_face(v, face, u, u + 1, w, w + 1, 2, C['lun_rur_d'])
                    elif math.hypot(u - cu, w - 15.0) <= 6.2:
                        _paint_face(v, face, u, u + 1, w, w + 1, 0, C['lun_shu_d'])
        #! 軒（白壁と瓦の境。**1 段えぐって影**）。
        _carve_relief(v, face, 0, V, 24, 26, 2)
        _paint_face(v, face, 0, V, 24, 26, 2, C['lun_shu_d'])
        #! 瑠璃瓦の side（垂木の小口が並ぶ）。
        _paint_face(v, face, 0, V, 26, h - 1, 0, C['lun_rur'])
        for u in range(0, V, 4):
            _carve_relief(v, face, u, u + 1, 26, h - 1, 1)
            _paint_face(v, face, u, u + 1, 26, h - 1, 1, C['lun_rur_d'])
    #! 天面＝**瑠璃瓦**（本瓦葺き。丸瓦の筋を彫る）。
    top = h - 1
    v[:, :, top] = C['lun_rur']
    along_x = rng.random() < 0.5
    for u in range(1, V - 1, 5):
        if along_x:
            v[u:u + 2, :, top] = C['lun_rur_l']
            v[u + 3:u + 4, 1:V - 1, top] = 0
            v[u + 3:u + 4, 1:V - 1, top - 1] = C['lun_rur_d']
        else:
            v[:, u:u + 2, top] = C['lun_rur_l']
            v[1:V - 1, u + 3:u + 4, top] = 0
            v[1:V - 1, u + 3:u + 4, top - 1] = C['lun_rur_d']


def wall_lunar_gb(name):
    """**月の都の壁** — 混沌の領域。朱の腰・白い壁・**瑠璃瓦の天**。"""
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['lun_hak_d']
    _lunar_wall(v, rng, dense=False)
    return [('main', v, (0, 0, 0))]


def bedrock_lunar_gb(name):
    """**月の都の塊**（岩盤の位置）— 混沌の領域。窓を必ず入れ、瓦の筋を細かくする。"""
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['lun_hak_d']
    _lunar_wall(v, rng, dense=True)
    return [('main', v, (0, 0, 0))]


def pillar_shu_gb(name):
    """**朱塗りの円柱** — 混沌の領域の部屋の縁（調査 §3.1 ②）。

    変愚の天界は白い円柱（`column_white`）を立てるが、**月の都は中華風**なので
    朱の円柱に瑠璃瓦の斗栱を載せる。丈 54（`pillar_stone` と同じ）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 56), np.int16)
    #! 礎盤（白石の 2 段）。
    for x in range(V):
        for y in range(V):
            r = math.hypot(x - 15.5, y - 15.5)
            if r <= 8.4:
                v[x, y, 0:3] = C['lun_hak_d']
            if r <= 7.2:
                v[x, y, 3:5] = C['lun_hak']
    #! 柱身（円柱。**南面を明るく**）。
    for x in range(V):
        for y in range(V):
            r = math.hypot(x - 15.5, y - 15.5)
            if r <= 5.4:
                v[x, y, 5:44] = C['lun_shu_l'] if y > 15.5 else C['lun_shu']
            elif r <= 6.0:
                v[x, y, 5:44] = C['lun_shu_d']
    #! 斗栱（**マス形を 2 段**。中華・和の柱頭はここで読ませる）。
    v[9:23, 9:23, 44:47] = C['lun_shu_d']
    v[7:25, 7:25, 47:50] = C['lun_shu']
    v[6:26, 6:26, 50:53] = C['lun_rur']
    v[8:24, 8:24, 53:55] = C['lun_rur_l']
    #! 金の帯（**1 本だけ**。柱に飾りが多いと廟になる）。
    for x in range(V):
        for y in range(V):
            if 5.0 <= math.hypot(x - 15.5, y - 15.5) <= 6.2:
                v[x, y, 26:29] = C['lun_kin']
    #! 剥落（朱漆は剥げる。1〜3 か所）。
    for _ in range(int(rng.integers(1, 4))):
        z = int(rng.integers(8, 40))
        x = int(rng.integers(10, 20))
        for y in range(V - 1, 0, -1):
            if v[x, y, z] > 0:
                v[x:x + 3, y - 1:y + 1, z:z + 4] = C['lun_hak_d']
                break
    return [('main', v, (0, 0, 0))]


def machine_wreck_gb(name):
    """**機械の残骸** — 混沌の領域の行き止まり（調査 §3.1 ④）。

    静かの海には**地上から打ち上げられた機械の残骸**があり、
    「**穢れた人間の夢の跡が眠っている**」（儚月抄）。**これが原作固有の 1 点。**

    着陸機の脚が折れ、皿（アンテナ）が傾き、**金の断熱材が剥がれて垂れている**。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 24), np.int16)
    #! 胴（八角の箱。傾いて沈んでいる）。
    for x in range(V):
        for y in range(V):
            dx, dy = abs(x - 15.0), abs(y - 17.0)
            if (max(dx, dy) <= 7.0) and ((dx + dy) <= 9.6):
                v[x, y, 2:11] = C['lun_met']
                v[x, y, 9:11] = C['lun_met_d']
    #! 金の断熱材（**剥がれて垂れる**。ここが機械を「人の物」に見せる）。
    for _ in range(int(rng.integers(3, 6))):
        ang = float(rng.uniform(0.0, 6.28))
        x = int(round(15.0 + (math.cos(ang) * 7.0)))
        y = int(round(17.0 + (math.sin(ang) * 7.0)))
        x = max(0, min(V - 3, x))
        y = max(0, min(V - 3, y))
        v[x:x + 3, y:y + 3, 1:int(rng.integers(5, 11))] = C['lun_foil']
    #! 脚（3 本。**1 本は折れている**）。
    for k, ang in enumerate((0.5, 2.6, 4.7)):
        bx, by = 15.0, 17.0
        for step in range(7):
            bx += math.cos(ang) * 1.7
            by += math.sin(ang) * 1.7
            z = max(0, 5 - step)
            xi = max(0, min(V - 2, int(round(bx))))
            yi = max(0, min(V - 2, int(round(by))))
            if (k == 1) and (step > 3):
                break                       # 折れた 1 本
            v[xi:xi + 2, yi:yi + 2, z:z + 2] = C['lun_met_d']
    #! 皿（傾いたアンテナ。**縁を立てて椀にする**）。
    for x in range(V):
        for y in range(V):
            r = math.hypot(x - 22.0, y - 8.0)
            if r <= 6.4:
                v[x, y, 12 + int(r * 0.5):14 + int(r * 0.5)] = (
                    C['lun_met'] if r < 5.2 else C['lun_hak_d'])
    v[21:24, 11:14, 8:15] = C['lun_met_d']     # 支柱
    #! 錆（真空の月には錆びないが、**幻想郷に落ちた物**なので朽ちている）。
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(6, 24))
        y = int(rng.integers(8, 26))
        if v[x, y, 5] > 0:
            v[x:x + 3, y:y + 3, 4:7] = C['rust']
    return [('main', v, (0, 0, 0))]


def flag_moon_gb(name):
    """**旗** — 混沌の領域の部屋の中（調査 §3.1 ④）。

    静かの海の**有人月面着陸の旗**。真空なので靡かないが、月では棒で横に張ってある
    ——だから**旗は平らな板**でよい（風で揺らさない。地下は無風という既存の規律とも合う）。
    丈 34。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 36), np.int16)
    #! 竿（**傾いて刺さっている**。誰も直しに来ない）。
    lean = float(rng.uniform(0.06, 0.14))
    for z in range(0, 34):
        x = int(round(12.0 + (lean * z)))
        v[x:x + 2, 16:18, z:z + 1] = C['lun_met']
    #! 横木（旗を張る棒）。
    tx = int(round(12.0 + (lean * 31)))
    v[tx:tx + 14, 16:18, 31:33] = C['lun_met_d']
    #! 旗（**平らな板**。朱と白＝月の都と同じ色にして、地の物であることを言う）。
    v[tx + 1:tx + 13, 17:18, 22:32] = C['lun_hak']
    v[tx + 1:tx + 6, 17:18, 27:32] = C['lun_shu']
    for k in range(5):
        v[tx + 1:tx + 13, 17:18, 23 + (k * 2):24 + (k * 2)] = C['lun_shu_d']
    #! 裾のほつれ（**下端を欠かす**。長い年月が読める）。
    for x in range(tx + 1, tx + 13):
        cut = int(rng.integers(0, 3))
        if cut:
            v[x, 17:18, 22:22 + cut] = 0
    #! 足元の踏み跡（月の砂に残る靴の跡。**2 つだけ**）。
    for _ in range(2):
        x = int(rng.integers(2, 26))
        y = int(rng.integers(4, 28))
        v[x:x + 4, y:y + 2, 0:1] = C['lun_sea_d']
    return [('main', v, (0, 0, 0))]


# ------------------------------------------------------------------- 16 浅間浄穢山
def _corbel_faces(v, rng, dark):
    """**持ち送りで狭まる石積み** — 浅間浄穢山（調査 §3.14「外せない 1 点」）。

    ピラミッドの内部通路は**上へ行くほど内へ寄る石積み**（持ち送り）で塞がれている。
    立方体の外へは出せないので、**下の段ほど深くえぐる**ことで同じ形を作る
    ——下が奥まって上が手前に来れば、通路は上ほど狭く見える。

    段は 5 つ。いちばん下が 4 ボクセル奥、いちばん上が面一。
    """
    h = v.shape[2]
    steps = ((0, 7, 4), (7, 13, 3), (13, 19, 2), (19, 26, 1), (26, h - 1, 0))
    stone = ([C['asa_edo'], C['asa_edo_l'], C['asa_root']] if dark
             else [C['asa_st'], C['asa_st_l'], C['asa_st_d']])
    for face in range(4):
        for z0, z1, back in steps:
            if back > 0:
                _carve_relief(v, face, 0, V, max(z0, 1), min(z1, h - 1), back)
            #! 石を横に割る（**縦の合端を彫る**。1 枚の板に見せない）。
            u = int(rng.integers(0, 5))
            while u < V:
                wdt = int(rng.integers(9, 16))
                ua, ub = u, min(u + wdt - 1, V)
                if ua < ub:
                    _paint_face(v, face, ua, ub, max(z0, 1), min(z1, h - 1), back,
                                stone[int(rng.integers(0, len(stone)))])
                if ub < V:
                    _paint_face(v, face, ub, ub + 1, max(z0, 1), min(z1, h - 1), back, C['asa_j'])
                u += wdt
            #! 段の天（持ち送りの見付。**明るく**して段を読ませる）。
            if back > 0:
                _paint_face(v, face, 0, V, max(z1 - 1, 1), min(z1, h - 1), back,
                            C['asa_j'] if dark else C['asa_st_l'])


def _asama_top(v, rng, dark):
    """天面 — 大判の切石（穢土の帯では黒土と石灰の脈）。"""
    top = v.shape[2] - 1
    if dark:
        v[:, :, top] = C['asa_edo']
        for _ in range(8):
            x0 = int(rng.integers(0, V - 6))
            y0 = int(rng.integers(0, V - 6))
            v[x0:x0 + int(rng.integers(4, 10)), y0:y0 + int(rng.integers(4, 10)), top] = (
                C['asa_edo_l'] if rng.random() < 0.5 else C['asa_edo'])
        #! 石灰の脈（**1 本だけ・ほぼ真っ直ぐ**。うねらせると白い虫に見える＝床で実測）。
        if rng.random() < 0.7:
            x = float(rng.integers(2, V - 2))
            drift = float(rng.uniform(-0.4, 0.4))
            y = 0.0
            while y < V:
                x += drift + float(rng.uniform(-0.25, 0.25))
                xi = max(0, min(V - 2, int(round(x))))
                v[xi:xi + 2, int(y):int(y) + 2, top] = C['asa_lim']
                y += 1.9
        return
    v[:, :, top] = C['asa_st']
    for bx in range(0, V, 15):
        for by in range(0, V, 11):
            v[bx:bx + 14, by:by + 10, top] = rng.choice(
                [C['asa_st'], C['asa_st_l'], C['asa_st_d']], p=[0.5, 0.3, 0.2])
            v[bx + 14:bx + 15, by:by + 11, top] = 0
            v[bx:bx + 15, by + 10:by + 11, top] = 0
            v[bx + 14:bx + 15, by:by + 11, top - 1] = C['asa_j']
            v[bx:bx + 15, by + 10:by + 11, top - 1] = C['asa_j']


def wall_corbel_gb(name):
    """**持ち送りの石壁** — 浅間浄穢山の全域（調査 §3.14 ①）。

    `MAZE` ＋ 通路率 0 なので**同じ幅の石の回廊が延々と続く**。
    上へ行くほど内へ寄る石積みにすれば、それだけで**ピラミッドの内部通路**になる。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['asa_st_d']
    _corbel_faces(v, rng, dark=False)
    _asama_top(v, rng, dark=False)
    return [('main', v, (0, 0, 0))]


def bedrock_corbel_gb(name):
    """**持ち送りの石の塊**（岩盤の位置）— 浅間浄穢山の全域。"""
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['asa_j']
    _corbel_faces(v, rng, dark=False)
    _asama_top(v, rng, dark=False)
    return [('main', v, (0, 0, 0))]


def wall_root_gb(name):
    """**根の層の壁** — 浅間浄穢山 51〜55 階（決定 D5。調査 §3.14 ②）。

    `d_info.txt` の註記が「**特殊処理で 51-55 階は MAZE フラグを無視する**」と書いている
    ——**最後の 5 階だけ迷宮でなくなる**。6 面の舞台名が「**錦上を支える穢土**」なので、
    そこだけ**土と根の層**にする。**幻想蛮怒で唯一「階で意匠が変わる」ダンジョン。**

    持ち送りの形は保つ（同じ山の中である）。替えるのは**材だけ**——
    乾いた白石が湿った黒土になり、目地の代わりに**根**が走る。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['asa_edo_d']
    _corbel_faces(v, rng, dark=True)
    #! 根（**面を横切る**。土の層の唯一の飾り）。
    for face in range(4):
        for _ in range(int(rng.integers(2, 5))):
            w = float(rng.integers(3, WALL_H - 4))
            u = 0.0
            while u < V:
                w += float(rng.uniform(-0.9, 0.9))
                wi = max(1, min(WALL_H - 2, int(round(w))))
                _paint_face(v, face, int(u), int(u) + 2, wi, wi + 2, 0,
                            C['asa_root'] if rng.random() < 0.6 else C['asa_root_l'])
                u += 1.6
    _asama_top(v, rng, dark=True)
    return [('main', v, (0, 0, 0))]


def bedrock_root_gb(name):
    """**根の層の塊**（岩盤の位置）— 浅間浄穢山 51〜55 階。"""
    rng = rng_for(name)
    v = np.zeros((V, V, WALL_H), np.int16)
    v[:, :, :] = C['asa_edo_d']
    _corbel_faces(v, rng, dark=True)
    for face in range(4):
        for _ in range(int(rng.integers(3, 7))):
            w = float(rng.integers(3, WALL_H - 4))
            u = 0.0
            while u < V:
                w += float(rng.uniform(-1.1, 1.1))
                wi = max(1, min(WALL_H - 2, int(round(w))))
                _paint_face(v, face, int(u), int(u) + 2, wi, wi + 3, 0,
                            C['asa_root'] if rng.random() < 0.5 else C['asa_root_l'])
                u += 1.4
    _asama_top(v, rng, dark=True)
    return [('main', v, (0, 0, 0))]


def floor_edo_gb(name):
    """**黒土の床** — 浅間浄穢山 51〜55 階（調査 §3.14 ⑤）。

    「錦上を支える穢土」——上層の乾いた白石に対して、**湿った黒土**。
    白い石灰の脈が走る（`MAZE` が解ける階なので、床が地山に戻ったことを言う）。
    """
    rng = rng_for(name)
    idx = int(name.rsplit('_', 1)[1])
    v = np.zeros((V, V, FLOOR_H), np.int16)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['asa_edo_d'] if z < top else C['asa_edo']
    #! 土のむら（**重ねた矩形**で塊にしつつ揃えない＝ `_lump_face` と同じ考え）。
    for _ in range(40):
        w = int(rng.integers(3, 11))
        d = int(rng.integers(3, 11))
        x0 = int(rng.integers(0, V - w))
        y0 = int(rng.integers(0, V - d))
        v[x0:x0 + w, y0:y0 + d, top] = rng.choice(
            [C['asa_edo'], C['asa_edo_l'], C['asa_edo_d']], p=[0.5, 0.3, 0.2])
    #! 石灰の脈（**白い筋**。マスをまたいで走る）。
    #!
    #! **本数を絞り、まっすぐに近づける**（2026-08-21 の 2 版）。1〜2 本を
    #! ±1.3 で振った初版は、敷き詰めると**黒土の上を白い虫が這っている**ように見えた
    #! （実測）——脈は地層の割れ目なので、うねらず、マスに 1 本あれば足りる。
    if (idx % 5) != 0:
        x = float(rng.integers(2, V - 2))
        drift = float(rng.uniform(-0.42, 0.42))
        y = 0.0
        while y < V:
            x += drift + float(rng.uniform(-0.28, 0.28))
            xi = max(0, min(V - 2, int(round(x))))
            v[xi:xi + 2, int(y):int(y) + 2, top] = C['asa_lim']
            y += 1.9
    #! 踏み荒らし（**彫って窪ませる**。土の床は掘れる）。
    for _ in range(int(rng.integers(1, 4))):
        x = int(rng.integers(1, V - 6))
        y = int(rng.integers(1, V - 6))
        v[x:x + int(rng.integers(3, 6)), y:y + int(rng.integers(3, 6)), top] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def _sazare(v, rng, cx, cy, rad, hgt, big):
    """さざれ石（小石が寄り集まって固まった礫岩）を 1 つ盛る。

    「**さざれ石の巌となりて**」（君が代）＋ 磐永（岩長姫）の不変が、
    そのまま特産品と最深の宝の名前になっている（調査 §3.14）。
    **小石の粒が見えること**が唯一の読みなので、粒は 2〜3 ボクセルの塊で置く。
    """
    for z in range(hgt):
        k = z / float(hgt)
        r = rad * (1.0 - (k * (0.35 if big else 0.62)))
        for x in range(V):
            for y in range(V):
                if math.hypot(x - cx, y - cy) <= r:
                    v[x, y, z] = C['asa_saz_d']
    #! 粒（**塊で置く**＝罠 38。表面だけ差せば中は見えない）。
    for _ in range(int(hgt * rad * 0.5)):
        ang = float(rng.uniform(0.0, 6.28))
        z = int(rng.uniform(0.0, hgt - 1))
        k = z / float(hgt)
        r = rad * (1.0 - (k * (0.35 if big else 0.62)))
        x = int(round(cx + (math.cos(ang) * (r - 0.8))))
        y = int(round(cy + (math.sin(ang) * (r - 0.8))))
        if not ((0 <= x < V - 2) and (0 <= y < V - 2)):
            continue
        tone = rng.choice([C['asa_saz'], C['asa_saz_l'], C['asa_saz_d'], C['asa_j']],
                          p=[0.36, 0.3, 0.2, 0.14])
        w = int(rng.integers(2, 4))
        v[x:x + w, y:y + w, z:z + w] = tone


def sazareishi_gb(name):
    """**さざれ石の塚** — 浅間浄穢山の行き止まりと部屋の中（調査 §3.14 ④）。

    特産品が「さざれ石」で最深の宝が「巌となったさざれ石」。**浅間浄穢山の唯一の固有記号**。
    上層は**小石の塚**、最深部は**巌**（`iwao_gb`）——深さに沿って替える。丈 20。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 22), np.int16)
    _sazare(v, rng, 15.5, 16.0, 9.5, 20, big=False)
    #! 脇に転がる小石（2〜4 個）。
    for _ in range(int(rng.integers(2, 5))):
        x = int(rng.integers(1, V - 4))
        y = int(rng.integers(1, V - 4))
        v[x:x + 3, y:y + 3, 0:2] = C['asa_saz']
    return [('main', v, (0, 0, 0))]


def iwao_gb(name):
    """**巌となったさざれ石** — 浅間浄穢山 51〜55 階の行き止まり（調査 §3.14 ④）。

    「さざれ石の巌となりて」——最深部では**塚ではなく一枚の巌**になる。
    塚（`sazareishi_gb`）と同じ粒を持ったまま、**丈 36・裾が広い**。
    磐永阿梨夜（岩長姫＝不変・恒久）の居る階なので、動かないものが立っている。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 38), np.int16)
    _sazare(v, rng, 15.5, 16.0, 13.0, 36, big=True)
    #! 苔（**南の根方だけ**。長く動いていない岩である）。
    for x in range(V):
        for z in range(0, 8):
            for y in range(V - 1, 0, -1):
                if v[x, y, z] == 0:
                    continue
                if rng.random() < 0.28:
                    v[x, y, z] = C['asa_root']
                break
    return [('main', v, (0, 0, 0))]


def crystal_malice_gb(name):
    """**敵意の結晶** — 浅間浄穢山の壁際と部屋の中（調査 §3.14 ③）。

    住人に**敵意の結晶が 12 種（緑赤青黄 × 小／中／巨大）**居る。
    **住人と同じ 4 色を地形の側にも置くと世界が繋がる**ので、1 個に 4 色を入れる。丈 28。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 30), np.int16)
    tones = [(C['asa_cg'], C['asa_cg_l']), (C['asa_cr'], C['asa_cr_l']),
             (C['asa_cb'], C['asa_cb_l']), (C['asa_cy'], C['asa_cy_l'])]
    rng.shuffle(tones)
    #! 母岩（結晶が生えている台）。
    for x in range(V):
        for y in range(V):
            r = math.hypot(x - 15.5, y - 16.0)
            if r <= 10.0:
                v[x, y, 0:max(1, int(4.0 - (r * 0.25)))] = C['asa_st_d']
    for k in range(4):
        ang = ((k / 4.0) * 2.0 * math.pi) + float(rng.uniform(-0.5, 0.5))
        rr = float(rng.uniform(2.5, 6.5))
        cx = 15.5 + (math.cos(ang) * rr)
        cy = 16.0 + (math.sin(ang) * rr)
        hgt = int(rng.integers(11, 28))
        lean = float(rng.uniform(-0.14, 0.14))
        base, lit = tones[k]
        for z in range(2, hgt):
            r = max(1.0, 3.8 * (1.0 - ((z - 2) / float(hgt))))
            sx = cx + (lean * z)
            for x in range(V):
                for y in range(V):
                    if math.hypot(x - sx, y - cy) <= r:
                        v[x, y, z] = lit if (y > cy) else base
    return [('main', v, (0, 0, 0))]


def serpent_carve_gb(name):
    """**蛇の彫り** — 浅間浄穢山の通路の壁際（調査 §3.14 ⑥）。

    4 面ボス『ユイマン・浅間』は**蛇に「穢れ」＝生命情報を食わせて再構成し、
    汚染を無害化する**能力を持つ（地下の国「維縵国」の姫）。
    その蛇を**石碑に彫る**——立体で蛇を作ると小物の蛇になってしまうので、
    **板を立てて彫り込む**（V7 のとおり、彫れば四角形が増え、影が出る）。丈 26。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 28), np.int16)
    #! 石碑（**南（+y）を向いた板**。厚み 5）。
    v[6:26, 18:23, 0:26] = C['asa_st']
    v[6:26, 18:23, 0:3] = C['asa_st_d']            # 根石
    v[6:8, 18:23, 0:26] = C['asa_st_d']            # 縁
    v[24:26, 18:23, 0:26] = C['asa_st_d']
    v[6:26, 18:23, 24:26] = C['asa_st_d']          # 笠
    #! 蛇（**南面を蛇行して彫る**。深さ 2）。
    y0 = 22
    x = 9.0
    for z in range(4, 23):
        x += math.sin(z * 0.42) * 1.9
        xi = max(7, min(23, int(round(15.5 + ((x - 15.5) * 0.9)))))
        v[xi:xi + 3, y0 - 2:y0 + 1, z:z + 1] = 0
        v[xi:xi + 3, y0 - 2:y0 - 1, z:z + 1] = C['asa_j']
    #! 頭（**目に朱を 1 点**——石碑に赤が 1 つあると蛇が生きて見える）。
    v[13:19, y0 - 2:y0 + 1, 20:23] = 0
    v[13:19, y0 - 2:y0 - 1, 20:23] = C['asa_j']
    v[14:15, y0 - 2:y0 - 1, 21:22] = C['asa_cr']
    v[17:18, y0 - 2:y0 - 1, 21:22] = C['asa_cr']
    #! 欠けと苔（1〜3 か所）。
    for _ in range(int(rng.integers(1, 4))):
        x0 = int(rng.integers(6, 24))
        z0 = int(rng.integers(2, 22))
        v[x0:x0 + 3, 18:23, z0:z0 + 3] = C['asa_st_d']
    return [('main', v, (0, 0, 0))]


