# ---- 陽だまり（Sil-Q の `patch of sunlight`。2026-08-22。決めたこと）----
# 「日差しがスポットのように差し込んで草花が咲いている地面」。
#
# **光の柱は作らない。**ボクセルは不透明なので（`hd2d/render/voxel_renderer.cpp` に
# 混色の引数が無い）、柱を立てると陽の筋ではなく**白い角柱**がマスを塞ぐ。差し込む光は
# 床の側で見せる——芯が白く、外へ向かって金→石の色へ落ちる輪を天面に描き、
# 対応表の `emissive` で輪ごと灯す。草花は別体（`sunlit_bloom_sq`）で立体に持たせる。
reg_local('sq_sun_c', (250, 243, 212))   # 陽の芯（白に寄せる。ここだけ石の色を残さない）
reg_local('sq_sun_m', (233, 214, 158))
reg_local('sq_sun_e', (203, 180, 130))
reg_local('sq_sun_o', (168, 148, 110))   # 輪の外縁。ここで敷石の色へ渡す
reg_local('sq_lit_g', (128, 170, 80))    # 陽を浴びた草（`grass_l` より明るい）
reg_local('sq_lit_gl', (158, 196, 100))


def ground_sunlit_sq(name):
    """陽だまりの地面。**部屋の床（`floor_room`）の続きに陽の輪が落ちている**形。

    | 段 | 何 |
    |---|---|
    | 敷石 | `floor_room` と同じ大判・同じ目地（**同じ床に見えること**が要件） |
    | 陽の輪 | 天面の色だけ。芯から 4 段で敷石へ落とす。縁は 1 ボクセル単位で散らす |
    | 草 | 輪の中だけ。日の当たる所にしか生えないので、外へは 1 株も置かない |

    **輪を真円にしない。**真円だと「床に描いた円」に見えて、上から差す光に見えない。
    楕円を傾け、縁の判定に±のゆらぎを足して輪郭を崩す。

    彫らないので `quads` は平らな床と同じ（罠: 地面のタイルはどれもそうで、
    ここに凹凸を付けると陽だまりだけ床から浮いて見える）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, FLOOR_H), np.int16)
    top = FLOOR_H - 1
    for z in range(FLOOR_H):
        v[:, :, z] = C['pav_dd'] if z < top - 1 else C['crack']
    v[:, :, 0] = C['pav_dd']

    # ---- 敷石（`floor_room` と同じ手順。目地は 1 列残して 1 段彫れる）----
    face = np.zeros((V, V), np.int16)
    step = 16
    for by in range(0, V, step):
        off = (by // step) % 2 * (step // 2)
        for bx in range(-step, V + step, step):
            x0 = bx + off
            shade = rng.choice([C['pav'], C['pav_l'], C['pav_d']], p=[0.5, 0.25, 0.25])
            x1, y1 = x0 + step - 1, by + step - 1
            xa, xb = max(x0, 0), min(x1, V)
            ya, yb = max(by, 0), min(y1, V)
            if xa < xb and ya < yb:
                face[xa:xb, ya:yb] = shade
    stone = face > 0
    _grain(rng, face, stone, [C['pav_g1'], C['pav_g2'], C['pav_g3']], [0.16, 0.13, 0.10])

    # ---- 陽の輪（傾いた楕円。縁はゆらぎで崩す）----
    cx = 15.5 + float(rng.uniform(-2.5, 2.5))
    cy = 15.5 + float(rng.uniform(-2.5, 2.5))
    rx = float(rng.uniform(10.0, 12.5))
    ry = float(rng.uniform(8.5, 11.0))
    ang = float(rng.uniform(0.0, math.pi))
    ca, sa = math.cos(ang), math.sin(ang)
    band = [(0.42, C['sq_sun_c']), (0.68, C['sq_sun_m']),
            (0.87, C['sq_sun_e']), (1.00, C['sq_sun_o'])]
    lit = np.zeros((V, V), bool)
    core = np.zeros((V, V), bool)
    for x in range(V):
        for y in range(V):
            if not stone[x, y]:
                continue  # 目地は彫れているので陽も落ちない（溝は影になる）
            dx, dy = x - cx, y - cy
            u = (dx * ca) + (dy * sa)
            w = (-dx * sa) + (dy * ca)
            t = math.sqrt(((u / rx) ** 2) + ((w / ry) ** 2))
            t += float(rng.uniform(-0.07, 0.07))  # 縁のゆらぎ（輪郭を 1 ボクセル単位で崩す）
            if t >= 1.0:
                continue
            for edge, colour in band:
                if t < edge:
                    face[x, y] = colour
                    break
            lit[x, y] = True
            core[x, y] = t < 0.75

    # ---- 草（**輪の中だけ**。塊 2×2 で撒く＝罠 38「1 ボクセル単位は砂粒に見える」）----
    # **株で撒く。**等確率でばらまくと苔の斑になり、草地に見えない。1 株ごとに
    # 2×2 の塊を数個重ねて、株の輪郭を作る。
    # **株の中心は輪の中から選ぶ**（マスのどこかを引いて外れたら諦める形だと、
    # 輪が小さい変種に草が 1 株も生えないことがある。実際に `_01` がそうなった）。
    seats = np.argwhere(lit)
    for _ in range(int(rng.integers(6, 10))):
        if len(seats) == 0:
            break
        sx, sy = (int(k) for k in seats[int(rng.integers(0, len(seats)))])
        tone = rng.choice([C['sq_lit_g'], C['sq_lit_gl'], C['grass_d']], p=[0.45, 0.30, 0.25])
        for _ in range(int(rng.integers(3, 7))):
            x = int(np.clip(sx + rng.integers(-3, 4), 0, V - 2))
            y = int(np.clip(sy + rng.integers(-3, 4), 0, V - 2))
            if lit[x:x + 2, y:y + 2].all():
                face[x:x + 2, y:y + 2] = tone
    # 花は**1 ボクセルの点**でよい（`ground_grass` と同じ流儀。塊にすると花が石ほど大きくなる）。
    hearts = np.argwhere(core)
    for _ in range(int(rng.integers(7, 12))):
        if len(hearts) == 0:
            break
        x, y = (int(k) for k in hearts[int(rng.integers(0, len(hearts)))])
        face[x, y] = rng.choice([C['fl_w'], C['fl_y'], C['fl_r']], p=[0.4, 0.35, 0.25])

    v[:, :, top] = face
    # ---- 亀裂と欠け（`floor_room` と**同じ数・同じ深さ**）----
    # ここを省くと天面が 1 枚の板になり、`--prefab-check` の quads が 150 → 36 まで落ちる
    # ＝隣の部屋の床だけ荒れていて、陽だまりのマスだけつるりとして見える。
    for _ in range(int(rng.integers(0, 3))):
        x, y = int(rng.integers(3, V - 3)), int(rng.integers(3, V - 3))
        dx, dy = (1, 1) if rng.random() < 0.5 else (1, -1)
        deep = rng.random() < 0.4
        for _ in range(int(rng.integers(7, 14))):
            if (0 <= x < V) and (0 <= y < V):
                v[x, y, top] = 0
                if deep:
                    v[x, y, top - 1] = 0
            x += dx if rng.random() < 0.8 else 0
            y += dy if rng.random() < 0.6 else 0
    for _ in range(int(rng.integers(1, 4))):
        x, y = int(rng.integers(0, V - 3)), int(rng.integers(0, V - 3))
        w, d = int(rng.integers(2, 5)), int(rng.integers(2, 5))
        v[x:x + w, y:y + d, top] = 0
        if rng.random() < 0.25:
            v[x:x + w, y:y + d, top - 1] = 0
    return [('main', v, (0, 0, -FLOOR_H))]


def sunlit_bloom_sq(name):
    """陽だまりに咲く草花。**低い**（0.22 マス）ので視線を遮らない。

    株ごとに葉を数枚と花を 1 本。葉は根元から斜めに立ち上げる（垂直に立てると
    毛の束に見える）。**風には揺らさない**——地下は無風という決めがある
    （`hd2d_app.cpp` の「洞窟の草が揺れると嘘くさい」）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 8), np.int16)
    for _ in range(int(rng.integers(6, 9))):
        cx = int(rng.integers(7, 25))
        cy = int(rng.integers(7, 25))
        for _ in range(int(rng.integers(7, 12))):  # 葉
            x = cx + int(rng.integers(-2, 3))
            y = cy + int(rng.integers(-2, 3))
            h = int(rng.integers(3, 7))
            dx = int(rng.choice([-1, 0, 1]))
            dy = int(rng.choice([-1, 0, 1]))
            for z in range(h):
                if (0 <= x < V) and (0 <= y < V):
                    v[x, y, z] = C['sq_lit_gl'] if z >= h - 1 else C['sq_lit_g']
                if (z % 2) == 1:
                    x += dx
                    y += dy
        if rng.random() < 0.7:  # 花（茎 1 本と花弁 1 段）
            h = int(rng.integers(4, 7))
            v[cx, cy, 0:h] = C['grass_d']
            petal = int(rng.choice([C['fl_w'], C['fl_y'], C['fl_r']], p=[0.4, 0.35, 0.25]))
            # 花冠は**十字**（3×3 の塊にすると角砂糖に見える。実機の絵で確かめた）。
            for (ox, oy) in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                v[cx + ox, cy + oy, h:h + 1] = petal
            v[cx, cy, h:h + 1] = C['fl_y'] if (petal != C['fl_y']) else C['fl_w']
    return [('main', v, (0, 0, 0))]


add_variants('ground_sunlit_sq', 3, ground_sunlit_sq,
             '陽だまりの地面（Sil-Q）。部屋の床に落ちた陽の輪と、その中だけの草')
CATALOG.update({
    'sunlit_bloom_sq': (sunlit_bloom_sq, static_part(), '陽だまりに咲く草花（Sil-Q）'),
})


# ---- 蜘蛛の巣・深淵・鍛冶場（Sil-Q。2026-08-22。決めたこと）----
# どれも「変愚に相当する絵が無いので床へ倒してあった」マスである（`terrain_map.csv` の註記）。
# 番号は 1300 番台の予約帯（`terrain_prefabs.jsonc` の `terrains_extra`）。
reg_local('sq_web', (212, 214, 208))     # 糸（張りたて）
reg_local('sq_web_d', (168, 170, 164))   # 糸（埃をかぶった所）
reg_local('sq_pit_r', (88, 84, 79))      # 深淵の岩肌（口の近く）
reg_local('sq_pit_d', (54, 51, 49))      # 同（中ほど）
reg_local('sq_pit_dd', (31, 30, 31))     # 同（底の手前）
reg_local('sq_soot', (46, 42, 39))       # 鍛冶場の煤
# 鍛冶の鉄は**共通の `iron`（56,54,58）では暗すぎる**。地下の明かりで見ると金床が
# ただの黒い箱になった（実機の絵で確かめた）。研がれた鉄として 1 段明るく持つ。
reg_local('sq_anv', (94, 92, 99))
reg_local('sq_anv_l', (132, 130, 139))
reg_local('sq_anv_d', (58, 56, 62))
# 鍛冶場は Sil-Q に**3 等級**ある（`terrain.txt` の色がそのまま等級である。
# 並 `0:s` 灰 / 付呪 `0:y1` 黄 / `Orodruth` `0:r` 赤・使い切ると `0:D` 暗灰）。
# **形は 1 つ、鉄の色だけ替える**（`_recolour`）——等級で道具立てが変わるわけではない。
reg_local('sq_ench', (170, 142, 74))
reg_local('sq_ench_l', (224, 188, 98))
reg_local('sq_ench_d', (112, 92, 48))
reg_local('sq_oro', (152, 74, 58))
reg_local('sq_oro_l', (216, 112, 70))
reg_local('sq_oro_d', (94, 46, 36))
reg_local('sq_cold', (64, 62, 66))
reg_local('sq_cold_l', (90, 88, 94))
reg_local('sq_cold_d', (40, 38, 42))


def web_sq(name):
    """蜘蛛の巣（Sil-Q の feat 26）。**マスの左右の端に細く低い木、その間に巣**
    （2026-08-22 に決めた）。

    巣は `y = 15` の 1 ボクセル厚の面に描く。**放射の糸を先に、枠の糸を後**から重ねる
    ——逆にすると交点が枠の色で埋まって、蜘蛛の巣ではなく網に見える。

    姿勢の対（`web_sq_ew`）は `rotated()` が 90° 回して作る。通路の通る向きに合わせて
    置く側が選ぶ（扉と同じ流儀＝設計書 §7.1-2）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 26), np.int16)

    #! 細く低い木（左右の端）。幹は 3 vox 角・上へ 1 vox 細る。枝は上寄りに 2〜3 本。
    for (bx, inward) in ((2, 1), (27, -1)):
        h = int(rng.integers(20, 25))
        v[bx:bx + 3, 14:17, 0:h] = C['bark']
        v[bx + 1:bx + 2, 14:17, 0:h] = C['bark_l']
        v[bx:bx + 3, 14:17, 0:2] = C['bark_l']          # 根張り
        #! 枝は**2 vox 厚で、外へ行くほど上がる**。1 vox の線で描いた版は
        #! 実機で消えて「ただの杭が 2 本」に見えた。
        for _ in range(int(rng.integers(2, 4))):        # 枝
            z = int(rng.integers(h - 10, h - 2))
            reach = int(rng.integers(3, 6))
            for k in range(reach):
                x = bx + 1 + (inward * (k + 1))
                zz = min(24, z + k)
                if 0 <= x < V:
                    v[x, 14:17, zz:zz + 2] = C['bark']
                    v[x, 15:16, zz + 1:zz + 2] = C['bark_l']

    #! 巣（円網）。中心をわずかに上・左右どちらかへ寄せる（真ん中に置くと的に見える）。
    cx = 15.5 + float(rng.uniform(-2.0, 2.0))
    cz = 14.0 + float(rng.uniform(-1.5, 1.5))
    rx = float(rng.uniform(10.0, 12.0))
    rz = float(rng.uniform(8.5, 10.5))
    spokes = int(rng.integers(8, 11))
    ang0 = float(rng.uniform(0.0, math.pi))

    def put(fx, fz, colour):
        x, z = int(round(fx)), int(round(fz))
        if (4 <= x < V - 4) and (2 <= z < 25):
            v[x, 15, z] = colour

    for k in range(spokes):                              # 放射の糸
        a = ang0 + ((2.0 * math.pi * k) / spokes)
        for t in range(1, 40):
            s = t / 39.0
            put(cx + (math.cos(a) * rx * s), cz + (math.sin(a) * rz * s), C['sq_web'])
    for ring in (0.30, 0.52, 0.74, 0.95):                # 枠の糸（外ほど埃）
        colour = C['sq_web'] if ring < 0.7 else C['sq_web_d']
        for t in range(160):
            a = (2.0 * math.pi * t) / 160.0
            #! **たるませる**（下側だけ半径を伸ばす）。真円だと機械で編んだ網に見える。
            sag = 1.0 + (0.10 * max(0.0, math.sin(a)))
            put(cx + (math.cos(a) * rx * ring), cz + (math.sin(a) * rz * ring * sag), colour)
    for _ in range(int(rng.integers(1, 4))):             # 破れ（マスごとに 1〜3 か所）
        a = float(rng.uniform(0.0, 2.0 * math.pi))
        s = float(rng.uniform(0.4, 1.0))
        hx, hz = int(round(cx + (math.cos(a) * rx * s))), int(round(cz + (math.sin(a) * rz * s)))
        v[max(0, hx - 2):hx + 3, 15, max(0, hz - 2):hz + 3] = 0
    return [('main', v, (0, 0, 0))]


CHASM_DEPTH = 0
#!< 深淵の深さ（vox）。**0 ＝ 床の厚みの中だけで彫る。**
#!
#! 前は 96（3 マス）だった（2026-08-22 に決めた「三ブロックほど地下に掘れる？」）。
#! **2026-08-25 に 0 へ戻した**——「地面の下にたれてしまうね」に気づいた。
#!
#! **地形は厚さ 4 vox の板が空に浮いているだけ**である（`floor_room_01` は 32x32x4）。
#! だから**床より深く彫れば、彫ったぶんは必ず板の下へはみ出す**。カメラは斜め上から
#! 見下ろすので、はみ出したものは空を背にして丸見えになる。
#!
#! 「外側の面だけ描かない」も試したが**解にならなかった**。
#! 外側を消すと、今度は**漏斗の向こう側の内壁**が下から見えるようになる——面はマスの向きを
#! 向いており、軸に沿った面は裏返らないからである。**板の下に物を置いて
#! 「下からは見えない」は成り立たない。**
#!
#! いまは**床の厚みの中に黒い口を彫る**（下 2 vox は真っ黒で塞ぐ）。深さは無いが、
#! 見下ろすと黒い穴に見え、**板の下には 1 ボクセルも出ない**。
CHASM_LIP = 18    #!< 口の下の「詰まっている」厚み。ここが薄いと床の下の空が透ける


def ground_chasm_sq(name):
    """深淵（Sil-Q の feat 2）。**地面に亀裂、大きく口を開けた形**（2026-08-22 に決めた）。

    | 段 | 何 |
    |---|---|
    | 手段 | マスの 6〜8 割。**縁を不規則にして四方の辺へ食い込ませる** |
    | 深さ | **床の厚みの中だけ**（`CHASM_DEPTH = 0`。理由はあちらの註） |
    | 底 | 下 2 vox を黒（`dark`）でマスいっぱいに塞ぐ。**板の下へは出さない** |

    **縁をマスの中に閉じ込めないこと。**深淵は 1 マス幅の裂け目が地図を蛇行する形で生まれる
    （`silq/src/generate.c` の `build_chasm`）ので、マスごとに縁を回すと**穴の数珠つなぎ**に
    見える。奈落（`naraku_hig`）で同じ罠を踏んでいる——あちらは縁を別のプレハブへ出したが、
    こちらは「縁を辺まで食い込ませて隣とつなぐ」形で解いた。

    歩けるマスとして送っている（`sq_shim` が `PASSABLE` を立てる）が、**穴の絵は嘘ではない**
    ——Sil-Q の深淵は踏み込むと落ちる（`cmd1.c:4995`）。設計 §4.2 の「歩けるので床へ倒す」は
    2D の代用タイルについての決めで、専用の絵ができたここには掛からない。
    """
    rng = rng_for(name)
    h = CHASM_DEPTH + FLOOR_H
    v = np.zeros((V, V, h), np.int16)
    floor_z0 = CHASM_DEPTH
    top = h - 1

    #! ---- 口の形 ----
    #! **十字に近い超楕円**（`|x|^p + |y|^p`、p≈1.45）にする。理由は 2 つ:
    #!   1. 辺の真ん中でマスからはみ出す ⇒ **隣の深淵とつながる**（裂け目は 1 マス幅で
    #!      蛇行して生まれるので、円にすると穴の数珠つなぎになる）
    #!   2. 四隅は残る ⇒ 岩の張り出しが口の縁を作り、**床の下が抜けない**
    ax = (np.arange(V) - 15.5).reshape(V, 1)
    ay = (np.arange(V) - 15.5).reshape(1, V)
    pw = 1.45
    shape = np.power(np.power(np.abs(ax), pw) + np.power(np.abs(ay), pw), 1.0 / pw)
    #! 縁のゆらぎ（塊 2×2。1 ボクセル単位だと縁が毛羽立って砂に見える）。
    wob = rng.normal(0.0, 1.5, ((V + 1) // 2, (V + 1) // 2))
    wob = np.repeat(np.repeat(wob, 2, axis=0), 2, axis=1)[:V, :V]
    rmax = float(rng.uniform(18.0, 20.5))
    edge = rmax + wob

    #! 窄まり（口で 1.0、底で 0.16）。**二乗で効かせる**——直線の漏斗は人工物に見える。
    zs = np.arange(h).reshape(1, 1, h) / float(h - 1)
    scale = 0.16 + (0.84 * np.power(zs, 0.6))
    open_at = shape[:, :, None] < (edge[:, :, None] * scale)

    #! ---- 岩を詰める ----
    for z in range(h):
        depth = 1.0 - (z / float(h - 1))  # 0 = 口、1 = 底
        colour = C['sq_pit_dd'] if depth > 0.78 else (C['sq_pit_d'] if depth > 0.45 else C['sq_pit_r'])
        if z < 2:
            v[:, :, z] = C['dark']       # 底はマスいっぱいに塞ぐ（下が抜けない）
            continue
        solid = ~open_at[:, :, z]
        #! **喉もマスいっぱいに詰める**（2026-08-25 に決めた）。
        #!
        #! 前は「殻だけ 3.5 vox 厚」だった（`.vox` を小さく保つため）。ところが地形は
        #! 空に浮いた板なので、**床より下は隣が空**——殻の**外側にも面が立ち**、
        #! 下から見ると漏斗が垂れて見えた。
        #!
        #! 詰めれば殻の外側という面が**そもそも無くなる**。残るのは
        #!   ・漏斗の内側（上から覗いて見える面。**残したいのはこれだけ**）
        #!   ・箱の横と底（`hide_unseen_from_above` が落とす。`greedy_mesher.h`）
        #! である。**殻を薄いまま「外側の面だけ落とす」ことはできない**——縁のゆらぎ
        #! （`wob`）で殻に針穴が開いており、外の空間が口までつながってしまう
        #! （実測: 空のボクセル 78,043 個が**全部**口から届いた）。
        #!
        #! `.vox` は 5 倍ほどになるが、**メッシュはむしろ減る**（内側の面は作られない）。
        v[solid, z] = colour
    #! 岩肌のむら（口の近くだけ。底は黒一色）。
    for z in range(max(0, floor_z0 - CHASM_LIP), h):
        layer = v[:, :, z]
        layer[(layer > 0) & (rng.random((V, V)) < 0.14)] = C['rock_dd']

    #! ---- 残った床（口の外＝四隅）----
    face = np.zeros((V, V), np.int16)
    _lump_face(rng, face, [C['pav'], C['pav_d'], C['pav_dd'], C['crack']],
               [0.34, 0.28, 0.22, 0.16], span=(3, 9), count=70)
    for z in range(floor_z0, h):
        keep = ~open_at[:, :, z]
        col = face if z == top else np.full((V, V), C['pav_dd'], np.int16)
        v[:, :, z] = np.where(keep, col, 0)
    #! 口の縁を 1 段落とす（切り立った縁は板を切り抜いたように見える）。
    lip = (~open_at[:, :, top]) & open_at[:, :, top - 1]
    v[lip, top] = 0
    return [('main', v, (0, 0, -h))]


def forge_sq(name):
    """鍛冶場（Sil-Q の feat 64〜79）。**炉・釜・机・金床・バケツ**（2026-08-22 に決めた）。

    **1 マスに収める。**vault 160 本のうち鍛冶場を持つのは 15 本で、`0` の数は 14 本が 1 個・
    残る 1 本（`the Chambers of Thu`）も離れた 2 個である（実測 2026-08-22）ので、
    **複数マスにまたがる鍛冶場は生まれない**。だから 1 マスの中で散らす。

    ## 置き方（32×32。**+y が南＝手前**）

    ```
        炉             机          y 1..11   （背の高いものを北の辺へ）
             金床                  y 13..23  （真ん中。角は東へ伸ばす）
        釜             バケツ      y 22..31
    ```

    背の高いもの（炉の背板 z=18）を**北の辺**へ置くのが要点である。カメラは南から
    見下ろすので、南に置くと手前のものが奥を隠す。

    **炉に覆い（フード）は付けない。**実物の鍛冶炉には煙を吸う覆いがあるが、
    見下ろす画では覆いが火床をそっくり隠してしまう。背板だけを立てて煙道を示す。

    変種で替えるのは**東西の入れ替えと道具の並びだけ**で、材と寸法は 3 枚とも同じ
    （§9.3 の「基本デザインを揃えたうえで種だけ違う」）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 22), np.int16)
    kind = int(name[-2:]) % 3
    flip = (kind == 1)  # 東西を入れ替える

    def fx(x0, w):
        """東西の入れ替えを吸う（`flip` なら x を鏡にする）。左端を返す。"""
        return (V - x0 - w) if flip else x0

    # ------------------------------------------------------------------- 炉
    #! 石積みの火床。**火は覆わない**（上の註記）。背板が煙道の代わり。
    hx, hy, hw = fx(1, 13), 1, 13
    v[hx:hx + hw, hy:hy + 9, 0:9] = C['wall_l']
    for z in range(2, 9, 3):                             # 積み目
        v[hx:hx + hw, hy:hy + 9, z:z + 1] = C['wall']
    #! **火床は上を開ける。**初版は掘った上に石を 1 段被せていて、熾きが 1 粒も見えず
    #! 炉が黒い箱になった（実機の絵で気づいた）。見下ろす画では**天面がすべて**である。
    v[hx + 2:hx + hw - 2, hy + 3:hy + 8, 6:9] = 0        # 火床（掘る）
    v[hx + 2:hx + hw - 2, hy + 3:hy + 8, 6:7] = C['crust']
    for _ in range(30):                                  # 熾き
        cx = int(rng.integers(hx + 2, hx + hw - 3))
        cy = int(rng.integers(hy + 3, hy + 7))
        v[cx:cx + 2, cy:cy + 2, 7:8] = rng.choice([C['fl_edge'], C['fl_mid'], C['fl_core']],
                                                  p=[0.38, 0.36, 0.26])
    #! 背板（煙道）。**低く・薄く。**z=18 まで立てた版はマスの north を黒い壁が占めて、
    #! 金床も机も背板の影に沈んだ。
    v[hx:hx + hw, hy:hy + 2, 0:14] = C['wall']
    for z in range(3, 14, 4):
        v[hx:hx + hw, hy:hy + 2, z:z + 1] = C['wall_d']
    v[hx + 3:hx + hw - 3, hy + 1:hy + 2, 9:13] = C['sq_soot']  # 煤けた所

    # ---------------------------------------------------------------- 机（道具台）
    bw = 15
    bx0, by0, by1 = fx(16, bw), 1, 9
    bx1 = bx0 + bw
    v[bx0:bx1, by0:by1, 11:13] = C['oak']                # 天板
    v[bx0:bx1, by0:by0 + 1, 11:13] = C['oak_l']
    for lx in (bx0 + 1, bx1 - 3):                        # 脚
        for ly in (by0 + 1, by1 - 3):
            v[lx:lx + 2, ly:ly + 2, 0:11] = C['timber_d']
    v[bx0:bx1, by0:by1, 10:11] = C['timber_d']           # 幕板
    #! 道具（天板の上に 1 段）。金槌・やっとこ・鑢。
    tx = bx0 + 1
    v[tx:tx + 6, by0 + 3:by0 + 4, 13:14] = C['timber']       # 金槌の柄
    v[tx + 6:tx + 9, by0 + 2:by0 + 5, 13:16] = C['sq_anv']   # 金槌の頭
    v[tx + 6:tx + 9, by0 + 2:by0 + 5, 15:16] = C['sq_anv_l']
    ty = by0 + 6
    for dy in (0, 3):                                        # やっとこ（2 本の腕）
        v[tx + 1:tx + 9, ty + dy:ty + dy + 1, 13:14] = C['sq_anv']
    v[tx + 8:tx + 11, ty:ty + 4, 13:14] = C['sq_anv_l']      # 咥え口
    if kind != 2:
        v[bx1 - 5:bx1 - 2, by0 + 5:by0 + 8, 13:17] = C['sq_anv_d']   # 釘の缶
        v[bx1 - 4:bx1 - 3, by0 + 6:by0 + 7, 16:17] = C['sq_anv']
    else:
        v[bx1 - 6:bx1 - 1, by0 + 6:by0 + 7, 13:14] = C['sq_anv_l']   # 鑢

    # ------------------------------------------------------------------- 金床
    #! 切り株の上に置く。**角（つの）を 7 vox 伸ばす**——短いと胴に埋もれて黒い箱に見える。
    ax = fx(10 + (1 if (kind == 2) else 0), 18)
    ay = 14
    horn = -1 if flip else 1                             # 角はマスの中央へ向ける
    hx0 = (ax + 7) if flip else ax                       # 切り株の左端
    v[hx0:hx0 + 11, ay:ay + 9, 0:7] = C['log']           # 切り株
    v[hx0:hx0 + 11, ay:ay + 9, 6:7] = C['log_end']       # 木口
    v[hx0 + 2:hx0 + 6, ay + 2:ay + 6, 6:7] = C['sq_soot']
    v[hx0 + 1:hx0 + 10, ay + 1:ay + 8, 7:9] = C['sq_anv_d']    # 台座
    v[hx0 + 3:hx0 + 8, ay + 3:ay + 6, 9:11] = C['sq_anv_d']    # 胴（細く絞る）
    v[hx0 + 1:hx0 + 10, ay + 1:ay + 8, 11:13] = C['sq_anv']    # 天場
    v[hx0 + 1:hx0 + 10, ay + 1:ay + 8, 12:13] = C['sq_anv_l']  # 打ち面
    for k in range(7):                                   # 角（先へ細る）
        w = max(1, 6 - k)
        x = (hx0 - 1 - k) if flip else (hx0 + 10 + k)
        if not (0 <= x < V):
            break
        y0 = ay + 4 - (w // 2)
        v[x, y0:y0 + w, 11:11 + max(1, w - 1)] = C['sq_anv']
        v[x, y0:y0 + w, 11 + max(0, w - 2):12 + max(0, w - 2)] = C['sq_anv_l']
    v[hx0 + 7:hx0 + 9, ay + 2:ay + 4, 12:13] = C['sq_soot']    # 打ち跡
    _ = horn

    # --------------------------------------------------------- 釜（金床の脇）
    #! 鉄の釜。**三脚の上に据える**（床に直に置くと寸胴の樽に見える）。
    #!
    #! **金床の南（手前）へは置かない。**カメラは南から見下ろすので、手前に丈のある
    #! ものを置くと金床がそっくり隠れる（初版がそうだった）。脇へ寄せて、
    #! **マスの手前はバケット 1 つだけ**にする。
    kx, ky = fx(1, 8), 12
    kcx, kcy = kx + 3.5, ky + 3.5
    for z in range(2, 11):
        #! 胴は**下すぼまり**（底が丸く、口へ向かって開く）。樽と見分ける形はここで決まる。
        rr = 2.5 + (1.1 * ((z - 2) / 8.0))
        for x in range(max(0, kx), min(V, kx + 8)):
            for y in range(ky, min(V, ky + 8)):
                r = math.hypot(x - kcx, y - kcy)
                if r <= rr:
                    inner = (r < (rr - 1.0)) and (z > 3)
                    v[x, y, z] = 0 if inner else C['sq_anv_d']
    for x in range(max(0, kx), min(V, kx + 8)):          # 中身と口縁
        for y in range(ky, min(V, ky + 8)):
            r = math.hypot(x - kcx, y - kcy)
            if r < 2.7:
                v[x, y, 9:10] = C['crust']               # 中身（灰。水はバケットの役目）
            if 2.7 <= r <= 3.7:
                v[x, y, 10:11] = C['sq_anv']             # 口縁（1 段明るい）
    for k in range(3):                                   # 三脚（外へ張る）
        a = (2.0 * math.pi * k / 3.0) + 0.5
        lx = int(round(kcx + (math.cos(a) * 2.4)))
        ly = int(round(kcy + (math.sin(a) * 2.4)))
        if (0 <= lx < V - 1) and (0 <= ly < V - 1):
            v[lx:lx + 2, ly:ly + 2, 0:3] = C['sq_anv_d']
    for k in range(9):                                   # 提げ手（弓なり。**釜の目印**）
        x = int(round(kcx - 3.5 + k))
        if not (0 <= x < V):
            continue
        z = 11 + int(round(4.0 * math.sin(math.pi * (k + 0.5) / 9.0)))
        v[x, int(kcy):int(kcy) + 1, z:z + 1] = C['sq_anv']

    # ----------------------------------------------------------- バケット（南東）
    wx, wy = fx(21, 8), 24
    for x in range(wx, min(V, wx + 8)):
        for y in range(wy, min(V, wy + 8)):
            r = math.hypot(x - (wx + 3.5), y - (wy + 3.5))
            if 2.6 <= r <= 3.7:
                v[x, y, 0:10] = C['timber']
                v[x, y, 2:3] = C['iron']                 # たが（下）
                v[x, y, 8:9] = C['iron']                 # たが（上）
            elif r < 2.6:
                v[x, y, 0:1] = C['timber_d']             # 底
                v[x, y, 7:8] = C['wa']                   # 水
                if (x + y) % 3 == 0:
                    v[x, y, 7:8] = C['wa_l']             # 明かりの映り
    return [('main', v, (0, 0, 0))]

#: 鍛冶場の等級 → 色。`forge_sq_<grade>_NN` の `<grade>` で引く。
#: **使い切った `Orodruth`（`cold`）だけは熾きも落とす**——先方の記号色が
#: 赤（`0:r`）から暗灰（`0:D`）へ変わるのがそれである。
FORGE_GRADES = {
    'ench': {'sq_anv': 'sq_ench', 'sq_anv_l': 'sq_ench_l', 'sq_anv_d': 'sq_ench_d'},
    'oro': {'sq_anv': 'sq_oro', 'sq_anv_l': 'sq_oro_l', 'sq_anv_d': 'sq_oro_d'},
    'cold': {'sq_anv': 'sq_cold', 'sq_anv_l': 'sq_cold_l', 'sq_anv_d': 'sq_cold_d',
             'fl_core': 'crust_l', 'fl_mid': 'crust', 'fl_edge': 'crust'},
}


def forge_sq_graded(name):
    """等級つきの鍛冶場（`forge_sq_ench_01` など）。**形は並の鍛冶場と 1 ボクセルも違わない。**

    種を並の名前から引くので、道具の並びまで対応する枚と同じになる（`rotated()` と同じ流儀）。
    """
    grade = name.split('_')[2]
    base = 'forge_sq_%s' % name[-2:]
    return [(pn, _recolour(v, FORGE_GRADES[grade]), o) for pn, v, o in forge_sq(base)]


