# ---- 護符の扉 3 色（Sil-Q の feat 6/7/8。2026-08-22。SH-21 / W2）----
# 先方は `+:G` `+:B` `+:v` の 3 段で、**封の強さ（破るのに要る意志 20 / 25 / 30）**を
# 記号の色だけで示している（`silq/lib/edit/terrain.txt` の「power 1/2/3」）。
# 当方はこれまで 3 つとも変愚の閉じた扉（`F32.png` / `door_closed`）へ倒していたので、
# **境の歌で扉を開けるかどうかを絵から決められなかった**。
#
# **形は 1 つ、印の色だけ替える**（鍛冶場の等級と同じ流儀）。扉そのものは
# `door_closed` と 1 ボクセルも違わず、板面の中央に**封印の輪**を 1 ボクセル浮き出させる。
# 色だけで分けないのは、色は暗がりで飛ぶうえ、**メッシャが幾何で四角形を割る**ためである
#
# 取っ手の鉄輪は**付けない**。封じられていて開かない扉なので、輪の代わりに印が座る。
reg_local('sq_wd_g', (74, 186, 96))     # 護符 1（緑。意志 20）
reg_local('sq_wd_gl', (150, 238, 162))
reg_local('sq_wd_b', (72, 140, 232))    # 護符 2（青。意志 25）
reg_local('sq_wd_bl', (148, 202, 255))
reg_local('sq_wd_v', (166, 104, 230))   # 護符 3（紫。意志 30）
reg_local('sq_wd_vl', (212, 168, 252))

#: 護符の等級 → （印の色, 印の明るい色）。`door_warded_sq_<grade>` の `<grade>` で引く。
WARD_GRADES = {
    'g': ('sq_wd_g', 'sq_wd_gl'),
    'b': ('sq_wd_b', 'sq_wd_bl'),
    'v': ('sq_wd_v', 'sq_wd_vl'),
}


def _ward_sigil(panel, y_face, y_proud, core, bright):
    """板面の中央に封印の印を 1 ボクセル浮き出させる。

    輪（半径 4.5）＋内側の十字。**十字は先方の記号 `+` そのもの**である。
    輪の外へ 4 本の短い光条を出して「封じてある」を出す（4 隅は鉄帯に当たるので
    上下左右に振る。帯は z=5〜8 と z=18〜21）。
    """
    cx, cz = 16, 13  # 板は x 5..27 / 帯の隙間は z 8..18。どちらも中央
    for x in range(cx - 6, cx + 7):
        for z in range(cz - 6, cz + 7):
            d = ((x - cx) ** 2 + (z - cz) ** 2) ** 0.5
            if 3.6 <= d <= 4.6:  # 輪
                panel[x, y_proud, z] = C[core]
            elif d < 3.6 and (x == cx or z == cz):  # 十字（`+`）
                panel[x, y_proud, z] = C[bright]
    # 光条（輪の外へ 2 ボクセル。上下左右）。
    for (dx, dz) in ((0, 1), (0, -1), (1, 0), (-1, 0)):
        for t in (5, 6):
            panel[cx + dx * t, y_proud, cz + dz * t] = C[core]
    # 印の座（面のほうを 1 段暗くして輪を浮かせる。彫らずに色だけだと平らに見える）。
    for x in range(cx - 5, cx + 6):
        for z in range(cz - 5, cz + 6):
            d = ((x - cx) ** 2 + (z - cz) ** 2) ** 0.5
            if d <= 5.0 and panel[x, y_proud, z] == 0:
                panel[x, y_face, z] = C['timber_d']


def door_warded_sq(name):
    """護符の扉（Sil-Q の feat 6/7/8）。閉じた扉と同じ形＋板面の封印の印。

    種は等級を外した名前から引くので、**3 色とも板の散らし方まで同じ**になる。
    """
    # `rotated()` が `_ew` を落としてから呼ぶので、ここは常に等級で終わる名前である。
    core, bright = WARD_GRADES[name.split('_')[-1]]
    rng = rng_for('door_warded_sq')  # 3 色で共通の種（形は 1 つ）
    v = np.zeros((V, V, 36), np.int16)
    _door_frame(v)
    panel = np.zeros((V, V, 36), np.int16)
    for x in range(5, 27, 4):  # 縦の樫板（`door_closed` と同じ振り方）
        shade = rng.choice([C['oak'], C['oak_l'], C['timber_l']], p=[0.45, 0.35, 0.2])
        panel[x:x + 4, 14:18, 0:26] = shade
    _door_panel_face(panel, 14, 13)  # 南面（既定のカメラが見る側）
    _door_panel_face(panel, 17, 18)  # 北面
    _ward_sigil(panel, 14, 13, core, bright)
    _ward_sigil(panel, 17, 18, core, bright)
    return [('frame', v, (0, 0, 0)), ('panel', panel, (0, 0, 0))]


CATALOG.update({
    'door_warded_sq_g': (door_warded_sq, door_parts(), '護符の扉・緑（Sil-Q feat 6。意志 20）'),
    'door_warded_sq_g_ew': (rotated(door_warded_sq), door_parts(), '同・東西の姿勢'),
    'door_warded_sq_b': (door_warded_sq, door_parts(), '護符の扉・青（Sil-Q feat 7。意志 25）'),
    'door_warded_sq_b_ew': (rotated(door_warded_sq), door_parts(), '同・東西の姿勢'),
    'door_warded_sq_v': (door_warded_sq, door_parts(), '護符の扉・紫（Sil-Q feat 8。意志 30）'),
    'door_warded_sq_v_ew': (rotated(door_warded_sq), door_parts(), '同・東西の姿勢'),
})


# ============================================ FroxComposband の地形（2026-08-24。版 2 で Frox から載せ替え）
#
# 決めたこと F5:
#   「追加タイルは一旦文字タイルで実装 後から絵のタイルを生成する」
#   「F5 の地面はボクセルを作成し実装しておこう」
# ＝**実体（R/K/P）は字の板で通すが、地形だけは先に立体を作る。**
#
# **版 2（2026-08-24）**: 対象を FrogComposband から FroxComposband へ替えたが、
# **`lib/edit/f_info.txt` が改行を無視して 1 バイトも違わない**ので、
# ここは 1 ボクセルも作り直していない。
# 接頭辞 `fc_` は Fro**x C**omposband の頭字として読み替える。
#
# FroxComposband にしか無い地形は 23 種で、**その 10 種が雪と氷**である
# （`frox/lib/edit/f_info.txt` の 222〜244。`GLYPH`(3) と `EXPLOSIVE_RUNE`(64) は
# 変愚と番号もキーも同じなので数に入らない）。変愚にも幻想蛮怒にも雪の地形は無いので、
# 代表タイルへ倒すと**雪の階が丸ごと土と石に見える**——だから作る。
#
# 番号は `terrain_prefabs.jsonc` の `terrains_extra` の予約帯（`1300 + feat`）。
# Frox の feat は 222〜244 なので **1522〜1544** に入り、Sil-Q（1302〜1377）と当たらない。
#
# **どれを地面・壁・物にするかは `F:` フラグで決めた**（勘で決めていない）:
#   MOVE があれば地面（歩ける）・WALL なら構造物・罠とルーンは地面＋物。
reg_local('fc_snow_b', (176, 190, 214))   # 雪の陰（青みを差す。灰で落とすと汚れた雪になる）
reg_local('fc_snow_g', (252, 254, 255))   # 雪のきらめき（粒。天面に数点だけ）
reg_local('fc_ice', (152, 198, 216))      # 氷の本体
reg_local('fc_ice_l', (200, 230, 240))    # 氷の明部（磨かれた所・気泡）
reg_local('fc_ice_d', (98, 142, 168))     # 氷の暗部（層の境）
reg_local('fc_ice_dd', (54, 88, 116))     # 亀裂の底・裂け目の奥
reg_local('fc_slush', (168, 172, 178))    # 雪解けの泥雪
reg_local('fc_slush_d', (126, 130, 138))
reg_local('fc_waste', (104, 146, 56))     # 有毒廃液（深）
reg_local('fc_waste_l', (146, 192, 84))
reg_local('fc_waste_d', (58, 86, 34))
reg_local('fc_acid', (168, 214, 96))      # 毒酸（浅）。廃液より黄へ振る
reg_local('fc_acid_l', (208, 240, 134))
reg_local('fc_zap', (118, 196, 240))      # 雷の影の放電
reg_local('fc_zap_l', (206, 238, 252))
reg_local('fc_rune', (198, 176, 62))      # 盗賊の罠の刻み（等級で色を替える基）
reg_local('fc_rune_l', (240, 222, 118))
reg_local('fc_peel', (226, 202, 74))      # バナナの皮
reg_local('fc_peel_d', (166, 142, 44))


def _fc_ground(h=FLOOR_H):
    """Frox の地面タイルの器。**`np.int16`**（`reg_local` の 1000 番台が入らないため）。"""
    return np.zeros((V, V, h), np.int16)


def _fc_scour(rng, v, top, count, span=(2, 6), deep=False):
    """天面を 1（`deep` なら 2）段だけ削る。

    **地面のタイルに凹凸は付けない**という決め（`ground_sunlit_sq` の註記）は
    「床から浮いて見える」ことを避けるためで、**削るぶんには浮かない**。
    ここを省くと天面が 1 枚の板になり、`--prefab-check` の quads が 2 桁まで落ちる
    ＝隣のマスだけ荒れていて、この地形のマスだけつるりとして見える。
    """
    for _ in range(count):
        x = int(rng.integers(0, V - 2))
        y = int(rng.integers(0, V - 2))
        w = int(rng.integers(*span))
        d = int(rng.integers(*span))
        v[x:x + w, y:y + d, top] = 0
        if deep and rng.random() < 0.35:
            v[x:x + w, y:y + d, top - 1] = 0


def ground_snow_fc(name):
    """雪の地面（Frox の feat 235 `snow`）。**踏み跡は付けない**——足跡を焼き込むと
    どのマスにも同じ足跡が並ぶ（変種は 3 枚しかない）。

    | 段 | 何 |
    |---|---|
    | 下 | 土（雪の下は地面である。縁から覗いたときに白い箱に見えない） |
    | 天面 | 雪の塊（`snow` / `snow_d` / `fc_snow_b`）。**大きな矩形を重ねる** |
    | 風紋 | 斜めの帯。1 段彫って陰を作る（色だけの縞は「塗った線」に見える） |
    | きらめき | `fc_snow_g` の点を数粒だけ。撒きすぎると砂糖に見える |
    """
    rng = rng_for(name)
    v = _fc_ground()
    top = FLOOR_H - 1
    v[:, :, 0] = C['dirt_d']
    #! 下地は**明るい雪**にする。ここを陰の色（`fc_snow_b`）にすると、風紋を彫った溝が
    #! 紺色の点線に見えて「雪に開いた穴」になった（実測。1 度そうなった絵を撮って気づいた）。
    v[:, :, 1:top] = C['snow_d']
    face = np.zeros((V, V), np.int16)
    _lump_face(rng, face, [C['snow'], C['snow_d'], C['fc_snow_b']], [0.58, 0.28, 0.14],
               span=(4, 13), count=46)
    v[:, :, top] = face

    #! 風紋（斜めの帯を 1 段彫る）。角度は変種ごとに振る。
    #!
    #! **2 ボクセルの塊で刻む。**1 ボクセル単位で斜めに刻むと、greedy が 1 段ごとに
    #! 四角形を切って **quads が 500 を超える**（`floor_room` の 150 に対して 3.5 倍。
    #! 地面のタイルは画面に何百枚も出るので、ここが効く）。実測で 518 → 200 台に落ちた。
    half = (V + 1) // 2
    ang = float(rng.uniform(0.0, math.pi))
    ca, sa = math.cos(ang), math.sin(ang)
    period = float(rng.uniform(3.0, 4.5))   # 塊の単位が 2 なので、周期も半分で数える
    hx = np.arange(half)[:, None] - ((half - 1) * 0.5)
    hy = np.arange(half)[None, :] - ((half - 1) * 0.5)
    ridge = np.sin(((hx * ca) + (hy * sa)) * (2.0 * math.pi / period)
                   + float(rng.uniform(0.0, 6.28)))
    #! **風紋は彫らない。色だけで置く。**
    #!
    #! 最初は谷を 1 段彫っていたが、帯が斜めに走る変種では**焼き込み AO の効いた
    #! 黒い破線**になって「雪に開いた穴の列」に見えた（撮って気づいた。軸に近い角度の
    #! 変種だけがまともだった）。雪は本来なめらかな面なので、**隣も雪である以上、
    #! ここが平らでも浮かない**——`ground_sunlit_sq` の「彫らないと床から浮く」は
    #! 隣が敷石の部屋だからで、雪原には掛からない。荒れは `_fc_scour` の窪みが受け持つ。
    trough = np.repeat(np.repeat(ridge < -0.62, 2, axis=0), 2, axis=1)[:V, :V]
    shoulder = np.repeat(np.repeat((ridge >= -0.62) & (ridge < -0.28), 2, axis=0), 2, axis=1)[:V, :V]
    lit = np.repeat(np.repeat(ridge > 0.70, 2, axis=0), 2, axis=1)[:V, :V]
    top_face = v[:, :, top]
    top_face = np.where(trough & (top_face > 0), C['fc_snow_b'], top_face)
    top_face = np.where(shoulder & (top_face > 0), C['snow_d'], top_face)
    v[:, :, top] = np.where(lit & (top_face > 0), C['snow'], top_face)

    #! 窪み（吹き溜まりの凹凸）。**風紋を色だけにしたぶん、ここで荒れを持たせる**
    #! ——彫りが 1 つも無いと `quads` が 22 まで落ち、隣の石の床と並べたとき
    #! 雪だけが磨いた板に見える（`ground_sunlit_sq` の註記と同じ理屈）。
    _fc_scour(rng, v, top, int(rng.integers(9, 14)), span=(2, 6), deep=True)
    for _ in range(int(rng.integers(5, 10))):  # きらめき
        x, y = int(rng.integers(0, V)), int(rng.integers(0, V))
        if v[x, y, top] > 0:
            v[x, y, top] = C['fc_snow_g']
    return [('main', v, (0, 0, -FLOOR_H))]


def ground_slush_fc(name):
    """雪解け（feat 234 `slush`）。**雪と土と溜まり水の 3 つが混ざる**のが読みなので、
    どれか 1 つに寄せない。溜まりは 1 段彫って水の色を底へ置く（天面を水にすると
    「水色に塗った雪」になる）。"""
    rng = rng_for(name)
    v = _fc_ground()
    top = FLOOR_H - 1
    v[:, :, 0] = C['dirt_d']
    v[:, :, 1:top] = C['pack_d']
    face = np.zeros((V, V), np.int16)
    _lump_face(rng, face, [C['fc_slush'], C['snow_d'], C['fc_slush_d'], C['pack'], C['dirt_d']],
               [0.30, 0.24, 0.20, 0.16, 0.10], span=(3, 11), count=60)
    v[:, :, top] = face
    #! 溜まり（縁を崩した楕円。深さ 1 段）。
    for _ in range(int(rng.integers(2, 5))):
        cx = float(rng.uniform(5.0, 27.0))
        cy = float(rng.uniform(5.0, 27.0))
        rx = float(rng.uniform(3.5, 7.5))
        ry = float(rng.uniform(3.0, 6.5))
        for x in range(V):
            for y in range(V):
                t = (((x - cx) / rx) ** 2) + (((y - cy) / ry) ** 2)
                t += float(rng.uniform(-0.12, 0.12))
                if t < 1.0:
                    v[x, y, top] = 0
                    v[x, y, top - 1] = C['wa_d'] if t < 0.55 else C['wa']
    _fc_scour(rng, v, top, int(rng.integers(3, 6)), span=(2, 5))
    return [('main', v, (0, 0, -FLOOR_H))]


def ground_ice_fc(name):
    """氷（feat 236 `ice slick`。滑る床）。**磨かれた面**なので塊のむらは弱く、
    代わりに**閉じ込められた気泡**と**枝分かれした亀裂**で読ませる。

    亀裂は 1 段彫って底に `fc_ice_dd` を置く（焼き込み AO と合わさって溝が影になる）。
    """
    rng = rng_for(name)
    v = _fc_ground()
    top = FLOOR_H - 1
    v[:, :, 0] = C['fc_ice_dd']
    v[:, :, 1:top] = C['fc_ice_d']
    face = np.zeros((V, V), np.int16)
    #! **明暗を強く振る。**最初は `fc_ice` 中心に寄せて作ったが、実機の絵では
    #! 「青白い板」にしか見えなかった（撮って気づいた）。氷は磨かれた面と曇った面の
    #! 差が読みなので、暗い側を増やして段を立てる。
    _lump_face(rng, face, [C['fc_ice'], C['fc_ice_d'], C['fc_ice_l'], C['fc_ice_dd']],
               [0.38, 0.30, 0.22, 0.10], span=(5, 15), count=34)
    v[:, :, top] = face
    for _ in range(int(rng.integers(10, 18))):  # 気泡（1 粒でよい。塊にすると雪に見える）
        x, y = int(rng.integers(0, V)), int(rng.integers(0, V))
        v[x, y, top] = C['fc_ice_l']
    #! 亀裂（枝分かれ）。**1 本を長く**引く——短い傷を撒くと擦り傷に見える。
    for _ in range(int(rng.integers(2, 4))):
        x, y = int(rng.integers(4, V - 4)), int(rng.integers(4, V - 4))
        dx = 1 if rng.random() < 0.5 else -1
        dy = 1 if rng.random() < 0.5 else -1
        for step in range(int(rng.integers(16, 28))):
            if (0 <= x < V) and (0 <= y < V):
                v[x, y, top] = 0
                #! **2 段彫る**（1 段だと上から見て線が消える）。底は最も暗い氷。
                v[x, y, top - 1] = 0
                v[x, y, top - 2] = C['fc_ice_dd']
            x += dx if rng.random() < 0.75 else 0
            y += dy if rng.random() < 0.55 else 0
            if rng.random() < 0.12:  # 枝
                dy = -dy
    return [('main', v, (0, 0, -FLOOR_H))]


def ground_glacier_fc(name):
    """滑る坂（feat 239 `slippery slope`）。**歩ける**（`F:` に `MOVE` / `CAN_CLIMB` があり
    `WALL` が無い）ので**地面**である。氷河（`GLACIER_STEEP`）とは別物なので混同しない。

    坂であることを**天面の段**で言う——1 方向に走る浅い階段状の稜を彫り、
    色を上手から下手へ明→暗に振る。**実際に高さは変えない**（マスの上に立つ実体が
    浮くか埋まるかしてしまう。傾きは絵で言う）。
    """
    rng = rng_for(name)
    v = _fc_ground()
    top = FLOOR_H - 1
    v[:, :, 0] = C['fc_ice_dd']
    v[:, :, 1:top] = C['fc_ice_d']
    axis = int(rng.integers(0, 2))       # 0 = 東西に下る / 1 = 南北に下る
    flip = bool(rng.integers(0, 2))
    face = np.zeros((V, V), np.int16)
    for x in range(V):
        for y in range(V):
            t = (x if axis == 0 else y) / float(V - 1)
            if flip:
                t = 1.0 - t
            t += float(rng.uniform(-0.06, 0.06))
            if t < 0.34:
                face[x, y] = C['fc_ice_l']
            elif t < 0.67:
                face[x, y] = C['fc_ice']
            else:
                face[x, y] = C['fc_ice_d']
    v[:, :, top] = face
    #! 段（坂に直交する稜を 1 段彫る）。4〜6 本。
    for k in range(int(rng.integers(4, 7))):
        pos = int(((k + 0.5) / 6.0) * V) + int(rng.integers(-2, 3))
        if not (1 <= pos < V - 1):
            continue
        if axis == 0:
            v[pos:pos + 1, :, top] = 0
        else:
            v[:, pos:pos + 1, top] = 0
    _fc_scour(rng, v, top, int(rng.integers(2, 4)), span=(2, 4))
    return [('main', v, (0, 0, -FLOOR_H))]


FC_CREVASSE_DEPTH = 96  #!< 氷の裂け目の深さ（vox = 3 マス）。`CHASM_DEPTH` と揃える


def ground_crevasse_fc(name):
    """氷の裂け目（feat 243 `icy crevasse`）。**歩けない**（`F:` に `MOVE` が無い）ので
    穴の絵は嘘ではない。

    深淵（`ground_chasm_sq`）と**形を分ける**。あちらは十字に近い超楕円で四隅を残すが、
    裂け目は**一直線の割れ目**である——長軸を 1 方向へ伸ばし、短軸を細く取ることで、
    隣のマスの裂け目とつながって**地図を横切る 1 本の線**になる。長軸の向きは変種ごとに
    東西／南北を振る（置く側はマスの種で 1 枚選ぶ）。

    壁は氷（`fc_ice_*`）で、底は黒（`dark`）。**下 2 段はマスいっぱいに塞ぐ**
    （塞がないと床の下の空が透ける。深淵で踏んだ罠と同じ）。
    """
    rng = rng_for(name)
    h = FC_CREVASSE_DEPTH + FLOOR_H
    v = np.zeros((V, V, h), np.int16)
    floor_z0 = FC_CREVASSE_DEPTH
    top = h - 1
    along_x = (int(name[-2:]) % 2) == 1   # 奇数 = 東西に走る / 偶数 = 南北

    ax = (np.arange(V) - 15.5).reshape(V, 1)
    ay = (np.arange(V) - 15.5).reshape(1, V)
    long_ax, short_ax = (ax, ay) if along_x else (ay, ax)
    #! 割れ目の芯線を蛇行させる（直線だと定規で引いた溝に見える）。
    wob = rng.normal(0.0, 1.9, ((V + 1) // 2, (V + 1) // 2))
    wob = np.repeat(np.repeat(wob, 2, axis=0), 2, axis=1)[:V, :V]
    half = float(rng.uniform(5.0, 7.5))
    dist = np.abs(np.broadcast_to(short_ax, (V, V)) + (wob * 0.55))
    #! 長軸の端でだけ僅かに窄める（マスの辺までは開いたままにする＝隣とつながる）。
    taper = 1.0 - (0.18 * np.power(np.abs(np.broadcast_to(long_ax, (V, V))) / 16.0, 3.0))

    zs = np.arange(h).reshape(1, 1, h) / float(h - 1)
    scale = 0.20 + (0.80 * np.power(zs, 0.55))
    open_at = dist[:, :, None] < ((half * taper)[:, :, None] * scale)

    for z in range(h):
        depth = 1.0 - (z / float(h - 1))
        colour = C['dark'] if depth > 0.82 else (C['fc_ice_dd'] if depth > 0.45 else C['fc_ice_d'])
        if z < 2:
            v[:, :, z] = C['dark']
            continue
        solid = ~open_at[:, :, z]
        if z >= (floor_z0 - CHASM_LIP):
            v[solid, z] = colour
        else:
            band = solid & (dist < (((half * taper) * scale[0, 0, z]) + 3.5))
            v[band, z] = colour
    #! 氷の層（口の近くだけ。深い所は闇に沈むので描いても見えない）。
    for z in range(floor_z0 - CHASM_LIP, h):
        layer = v[:, :, z]
        layer[(layer > 0) & (rng.random((V, V)) < 0.16)] = C['fc_ice']

    face = np.zeros((V, V), np.int16)
    _lump_face(rng, face, [C['snow'], C['snow_d'], C['fc_snow_b'], C['fc_ice']],
               [0.36, 0.28, 0.22, 0.14], span=(3, 9), count=60)
    for z in range(floor_z0, h):
        keep = ~open_at[:, :, z]
        col = face if z == top else np.full((V, V), C['fc_ice_d'], np.int16)
        v[:, :, z] = np.where(keep, col, 0)
    lip = (~open_at[:, :, top]) & open_at[:, :, top - 1]
    v[lip, top] = 0
    return [('main', v, (0, 0, -h))]


def _fc_liquid(name, deep):
    """毒の液（feat 229 `toxic waste` / 230 `poisonous acid`）。**水と同じ作り**で
    色だけ替える——水面の作法（天面を床より下げる・さざ波は明るい帯）はあちらが正である。

    深い側は濁って泡が浮き、浅い側は明るく黄へ振る（先方の記号色も `g` と `G` で分かれる）。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    if deep:
        base, lite, dk = C['fc_waste'], C['fc_waste_l'], C['fc_waste_d']
    else:
        base, lite, dk = C['fc_acid'], C['fc_acid_l'], C['fc_waste']
    v[:, :, 0] = dk
    v[:, :, 1] = base
    xs = np.arange(V)[:, None]
    ys = np.arange(V)[None, :]
    phase = float(rng.uniform(0, 6.28))
    wavep = np.sin((xs * 0.55) + (ys * 0.35) + phase)
    face = np.full((V, V), base, np.int16)
    face[wavep > (1.1 if deep else 0.82)] = lite
    face[wavep < -1.15] = dk
    #! 泡（深い側だけ。浅い酸は膜が張らない）。**塊 2×2** で置く（1 粒は砂に見える）。
    if deep:
        for _ in range(int(rng.integers(7, 13))):
            x, y = int(rng.integers(0, V - 2)), int(rng.integers(0, V - 2))
            face[x:x + 2, y:y + 2] = C['fc_waste_l']
    v[:, :, 2] = face
    return [('main', v, (0, 0, -5 if deep else -4))]


def wall_snow_fc(name):
    """雪の壁（feat 237 `snow wall`。`POWER_5` ＝**掘りやすい**）。

    直方体・高さ 1.0 マス・天面は平ら（2026-08-09 に決めた。壁の判別が付かなくなる）。
    雪であることは**丸みと庇**で言う——側面の上半分を塊で削って角を落とし、
    天面の縁に 1 段の庇を残す。
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.zeros((V, V, h), np.int16)
    bands = [C['fc_snow_b'], C['snow_d'], C['snow'], C['snow']]
    for z in range(h):
        v[:, :, z] = bands[min((z * len(bands)) // h, len(bands) - 1)]
    #! 塊ごとの明暗（4×4×4）。雪は色差が小さいので**振りは弱く**。
    grow = (lambda a: np.repeat(np.repeat(np.repeat(a, 4, 0), 4, 1), 4, 2)[:V, :V, :h])
    shape = ((V + 3) // 4, (V + 3) // 4, (h + 3) // 4)
    lump = rng.choice([C['snow'], C['snow_d'], C['fc_snow_b']], size=shape, p=[0.5, 0.32, 0.18])
    v = np.where(grow(rng.random(shape) < 0.45), grow(lump).astype(np.int16), v)
    #! 角を丸める（**上半分だけ**。接地層を縮めると隣との間から下が抜ける＝罠 5）。
    for z in range(h // 2, h):
        t = (z - (h // 2)) / float(h - (h // 2))
        cut = int(round(1.0 + (2.4 * t * t)))
        if cut <= 0:
            continue
        v[:cut, :, z] = 0
        v[V - cut:, :, z] = 0
        v[:, :cut, z] = 0
        v[:, V - cut:, z] = 0
    #! **塊で抉る**（`wall_rock` と同じ手）。滑らかに丸めただけだと greedy が
    #! 面をまるごと 1 枚にまとめ、**quads が 37 まで落ちる**＝雪に見えず白い箱になる
    #! （罠: 実測でそうなった。`bedrock_01` が 288・`wall_stone_01` が 202）。
    #! 吹きだまりは「積もり方が場所で違う」ものなので、**4 ボクセルの塊**で
    #! 大きさも位置もばらばらに欠く。**接地層（下 4 段）は欠かない**（罠 5）。
    for face in range(4):
        for _ in range(14):
            du = int(rng.integers(4, 13))
            dz = int(rng.integers(4, 12))
            u0 = int(rng.integers(-3, V - 2))
            z0 = int(rng.integers(4, h - 3))
            depth = int(rng.integers(1, 4))
            ua, ub = max(0, u0), min(V, u0 + du)
            za, zb = max(4, z0), min(h, z0 + dz)
            if (ua >= ub) or (za >= zb):
                continue
            if face == 0:
                v[ua:ub, 0:depth, za:zb] = 0
            elif face == 1:
                v[ua:ub, V - depth:, za:zb] = 0
            elif face == 2:
                v[0:depth, ua:ub, za:zb] = 0
            else:
                v[V - depth:, ua:ub, za:zb] = 0
    #! 天端の欠け（吹きだまりの稜。天面を塊で 1〜3 段落とす）。
    for _ in range(8):
        x0 = int(rng.integers(0, V - 3))
        y0 = int(rng.integers(0, V - 3))
        w = int(rng.integers(3, 9))
        d = int(rng.integers(3, 9))
        v[x0:x0 + w, y0:y0 + d, h - int(rng.integers(1, 4)):h] = 0

    #! 庇（吹きだまりの張り出し）。1 辺だけへ 1 段出す。
    side = int(rng.integers(0, 4))
    lip = np.zeros((V, V), np.int16)
    if side == 0:
        lip[:, 0:3] = C['snow']
    elif side == 1:
        lip[:, V - 3:] = C['snow']
    elif side == 2:
        lip[0:3, :] = C['snow']
    else:
        lip[V - 3:, :] = C['snow']
    v[:, :, h - 1] = np.where(lip > 0, lip, v[:, :, h - 1])
    return [('main', v, (0, 0, 0))]


def wall_ice_fc(name):
    """氷の壁（feat 238 `ice wall`。`POWER_35` ＝**掘りにくい**）。

    雪の壁と**同じ寸法**（判別は色でつける）。氷であることは**水平の層**と
    **閉じ込められた気泡の柱**で言う。角は落とさない（氷は割れて角が立つ）。
    """
    rng = rng_for(name)
    h = WALL_H
    v = np.zeros((V, V, h), np.int16)
    #! 層（不揃いな厚み）。等間隔にすると積層ケーキに見える。
    z = 0
    tones = [C['fc_ice'], C['fc_ice_l'], C['fc_ice_d']]
    while z < h:
        t = int(rng.integers(2, 6))
        v[:, :, z:z + t] = tones[int(rng.integers(0, len(tones)))]
        z += t
    #! 気泡の柱（縦に連なる。氷が育った向きを言う）。
    for _ in range(int(rng.integers(6, 11))):
        x, y = int(rng.integers(0, V)), int(rng.integers(0, V))
        z0 = int(rng.integers(0, h - 6))
        for k in range(int(rng.integers(3, 8))):
            if z0 + k < h:
                v[x, y, z0 + k] = C['fc_ice_l']
    #! 割れの面（側面を平らに欠く）。**氷は割れて角が立つ**ので、雪の壁のような
    #! 丸めはしない——代わりに**大きな平面で削ぎ落とす**。数を減らすと greedy が
    #! 面をまとめて `quads` が 2 桁まで落ち、水色の箱になる（雪の壁で踏んだ罠）。
    #! **接地層（下 4 段）は欠かない**（罠 5）。
    for _ in range(22):
        face = int(rng.integers(0, 4))
        u0 = int(rng.integers(-2, V - 3))
        z0 = int(rng.integers(4, h - 4))
        du = int(rng.integers(4, 13))
        dz = int(rng.integers(3, 10))
        cut = int(rng.integers(1, 5))
        ua, ub = max(0, u0), min(V, u0 + du)
        za, zb = max(4, z0), min(h, z0 + dz)
        if (ua >= ub) or (za >= zb):
            continue
        if face == 0:
            v[ua:ub, 0:cut, za:zb] = 0
        elif face == 1:
            v[ua:ub, V - cut:, za:zb] = 0
        elif face == 2:
            v[0:cut, ua:ub, za:zb] = 0
        else:
            v[V - cut:, ua:ub, za:zb] = 0
    #! 天端の割れ（氷は上から割れる。塊で 1〜3 段落とす）。
    for _ in range(7):
        x0 = int(rng.integers(0, V - 3))
        y0 = int(rng.integers(0, V - 3))
        w = int(rng.integers(3, 10))
        d = int(rng.integers(3, 10))
        v[x0:x0 + w, y0:y0 + d, h - int(rng.integers(1, 4)):h] = 0
    return [('main', v, (0, 0, 0))]


# 氷河（feat 241 `glacier`。`WALL` ＋ `MOUNTAIN` ＝登れない氷の山肌）は
# **既に在る `iceberg_01..03` を使う**（紅魔館の氷塊。`crag` の白と水色の色違い）。
# 材も形も欲しいものと同じなので、名前を 2 つ持つ理由が無い（
# 「同じものを 2 語で呼ばない」）。蜘蛛の巣（feat 225）が Sil-Q の `web_sq` を
# そのまま使うのと同じ判断である。


def tree_snow_fc(name):
    """雪をかぶった木（feat 240 `snow-covered tree`）。**立ち木の写しに雪を載せる**
    ——木の形は `tree()` が正で、ここで作り直すと同じ木が 2 種類になる。

    雪は**柱ごとの天辺**へ置く（葉の色を名前で引いて塗り替えるのではなく、
    上から見て当たる面だけを白くする）。枝の下は雪が乗らないので、これで
    「上から降り積もった」形になる。
    """
    parts = tree(name)
    rng = rng_for(name + ':snow')
    out = []
    for pn, vol, origin in parts:
        v = vol.astype(np.int16)
        sx, sy, sz = v.shape
        for x in range(sx):
            for y in range(sy):
                col = np.nonzero(v[x, y, :])[0]
                if col.size == 0:
                    continue
                zt = int(col[-1])
                if rng.random() < 0.78:
                    v[x, y, zt] = C['snow'] if rng.random() < 0.72 else C['snow_d']
                    if (zt > 0) and (rng.random() < 0.34) and (v[x, y, zt - 1] > 0):
                        v[x, y, zt - 1] = C['fc_snow_b']
        out.append((pn, v, origin))
    return out


def icicle_fc(name):
    """つらら罠（feat 242 `icicle trap`）。**天井から落ちてきた氷柱が床に突き立っている**形。

    吊り下げないのは、天井がそもそも描かれないからである（見下ろしでは天井を切り、
    一人称でも壁の高さは 1 マスしかない）。**落ちた後**の絵にすれば、見下ろしからも
    一人称からも読める。高さ 0.5 マス——これ以上高いと視線を遮る。
    """
    rng = rng_for(name)
    hz = 18
    v = np.zeros((V, V, hz), np.int16)
    for _ in range(int(rng.integers(3, 6))):
        cx = int(rng.integers(8, 24))
        cy = int(rng.integers(8, 24))
        hh = int(rng.integers(9, hz))
        lean_x = int(rng.choice([-1, 0, 0, 1]))
        lean_y = int(rng.choice([-1, 0, 0, 1]))
        x, y = cx, cy
        for z in range(hh):
            r = max(0, int(round(2.6 * (1.0 - (z / float(hh))))))
            tone = C['fc_ice_l'] if z > (hh * 0.6) else C['fc_ice']
            for dx in range(-r, r + 1):
                for dy in range(-r, r + 1):
                    if ((dx * dx) + (dy * dy)) <= (r * r):
                        px, py = x + dx, y + dy
                        if (0 <= px < V) and (0 <= py < V):
                            v[px, py, z] = tone
            if (z % 3) == 2:
                x += lean_x
                y += lean_y
    #! 砕けた欠片（床に散る 1〜2 段の粒）。罠だと分かる手掛かりになる。
    for _ in range(int(rng.integers(4, 9))):
        x, y = int(rng.integers(2, V - 3)), int(rng.integers(2, V - 3))
        v[x:x + 2, y:y + 2, 0:1] = C['fc_ice_d']
    return [('main', v, (0, 0, 0))]


def trap_bear_fc(name):
    """熊罠（feat 233 `bear trap`）。**開いた鉄の顎**（閉じていると鉄の輪にしか見えない）。

    **顎は 2 枚**である。円周に歯を回すと**檻の柵**に見えた（1 度そうした絵を撮った）
    ——熊罠の読みは「向かい合った 2 枚の弧が、内を向いた歯を並べている」ことなので、
    南北の半円だけに歯を立て、東西は発条の腕を出す。

    低い（0.125 マス）ので視線を遮らない。錆は縁だけに置く（全面を錆色にすると
    炉の熾きに見えた）。
    """
    rng = rng_for(name)
    hz = 4
    v = np.zeros((V, V, hz), np.int16)
    cx = cy = 16
    #! 踏み板（真ん中の円板）と受け皿（その外の輪）。
    for x in range(V):
        for y in range(V):
            d = math.hypot(x - cx + 0.5, y - cy + 0.5)
            if d < 5.6:
                v[x, y, 0] = C['iron'] if rng.random() < 0.85 else C['rust']
            elif d < 7.4:
                v[x, y, 0:2] = C['iron_l']
    #! 顎 2 枚（南北の弧）。弧の帯は 2 ボクセル厚。
    for side in (-1, 1):
        for k in range(-10, 11):
            t = k / 10.0
            off = 8.6 - (2.6 * t * t)
            for band in (0, 1):
                x = int(round(cx + (k * 1.0)))
                y = int(round(cy + (side * (off + band))))
                if (0 <= x < V) and (0 <= y < V):
                    v[x, y, 0:2] = C['steel']
            #! 歯（**内側へ向けて**立てる。3 本おき・高さ 2）。
            if (k % 3) == 0:
                x = int(round(cx + (k * 1.0)))
                y = int(round(cy + (side * (off - 1.4))))
                if (0 <= x < V) and (0 <= y < V):
                    v[x, y, 0:hz] = C['steel_d']
    #! 発条の腕（東西へ 1 本ずつ。顎を開いたまま保つ道具）。
    for dx in (-13, 11):
        x = cx + dx
        if 0 <= x < V:
            v[x:x + 2, cy - 3:cy + 4, 0:2] = C['iron_l']
            v[x:x + 2, cy - 1:cy + 2, 0:3] = C['rust']
    return [('main', v, (0, 0, 0))]


def trap_banana_fc(name):
    """バナナ罠（feat 244 `banana trap`）。**皮 1 枚**。極端に低い（0.09 マス）ので、
    真上から見たときの形だけが読みになる——だから**三つ又に広げる**。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 3), np.int16)
    cx = int(rng.integers(13, 20))
    cy = int(rng.integers(13, 20))
    base = float(rng.uniform(0.0, 6.28))
    for k in range(3):
        ang = base + (k * 2.094) + float(rng.uniform(-0.25, 0.25))
        for step in range(int(rng.integers(8, 12))):
            x = int(round(cx + (math.cos(ang) * step)))
            y = int(round(cy + (math.sin(ang) * step)))
            w = 2 if step < 6 else 1
            for dx in range(w):
                for dy in range(w):
                    px, py = x + dx, y + dy
                    if (0 <= px < V) and (0 <= py < V):
                        v[px, py, 0] = C['fc_peel'] if step < 8 else C['fc_peel_d']
            ang += float(rng.uniform(-0.10, 0.10))
    v[cx - 1:cx + 2, cy - 1:cy + 2, 0:2] = C['fc_peel_d']  # 蔕
    return [('main', v, (0, 0, 0))]


def _fc_disc(v, cx, cy, r0, r1, colour, z0, z1):
    """輪（内径 `r0`・外径 `r1`）を塗る。印の描き方はどれもこれで足りる。"""
    for x in range(v.shape[0]):
        for y in range(v.shape[1]):
            d = math.hypot(x - cx + 0.5, y - cy + 0.5)
            if r0 <= d < r1:
                v[x, y, z0:z1] = colour


def rune_rogue_fc(name):
    """盗賊の罠の印（feat 222/223/224）。**形は 1 つ、色だけが等級**である——
    先方も記号は `;` のままで色（`y` 黄 / `o` 橙 / `R` 赤）だけを変え、それが等級を表す
    （`frox/lib/edit/f_info.txt`）。鍛冶場（`forge_sq_graded`）で通した道と同じ。

    床に**刻んだ**印なので背は 2 ボクセル。輪と、その中の走り書きの記号で作る。
    """
    rng = rng_for('rune_rogue_fc')  # 3 等級で共通の種（形は 1 つ）
    v = np.zeros((V, V, 2), np.int16)
    _fc_disc(v, 16, 16, 10.2, 12.4, C['fc_rune'], 0, 1)
    _fc_disc(v, 16, 16, 6.4, 7.4, C['fc_rune_l'], 0, 1)
    #! 中の記号（`;` を崩した形。3 本の走り書き）。
    for _ in range(3):
        x = int(rng.integers(11, 21))
        y = int(rng.integers(11, 21))
        dx = int(rng.choice([-1, 0, 1]))
        dy = int(rng.choice([-1, 1]))
        for _ in range(int(rng.integers(5, 9))):
            if (0 <= x < V) and (0 <= y < V):
                v[x, y, 0:1] = C['fc_rune_l']
            x += dx
            y += dy
    #! 四方の留め（輪の外へ 4 つ。印が「置かれている」ことの読み）。
    for (ox, oy) in ((0, 13), (0, -13), (13, 0), (-13, 0)):
        x, y = 16 + ox, 16 + oy
        if (1 <= x < V - 1) and (1 <= y < V - 1):
            v[x - 1:x + 2, y - 1:y + 2, 0:2] = C['fc_rune']
    return [('main', v, (0, 0, 0))]


#: 盗賊の罠の等級 → 色。`rune_rogue_fc_N` の N で引く（1 = 並 / 2 = 大 / 3 = 極）。
FC_ROGUE_GRADES = {
    '1': {'fc_rune': 'fc_rune', 'fc_rune_l': 'fc_rune_l'},                 # 黄（そのまま）
    '2': {'fc_rune': 'bub', 'fc_rune_l': 'bub_l'},                          # 橙
    '3': {'fc_rune': 'crimson', 'fc_rune_l': 'fl_r'},                       # 赤
}


def rune_rogue_fc_graded(name):
    """等級つきの盗賊の罠（`rune_rogue_fc_2` など）。**形は並と 1 ボクセルも違わない。**"""
    grade = name.rsplit('_', 1)[1]
    return [(pn, _recolour(v, FC_ROGUE_GRADES[grade]), o) for pn, v, o in rune_rogue_fc(name)]


def rune_punish_fc(name):
    """懲罰の記号（feat 231 `semicolon of punishment`。`;` 青）。

    盗賊の罠と**別の形**にする（同じ形の色違いにすると、青いだけの罠に見えて
    「別の仕掛け」だと分からない）。こちらは**角の立った四芒**——刻んだ線が
    交差する形で、輪を持たない。
    """
    v = np.zeros((V, V, 2), np.int16)
    for k in range(-13, 14):
        for (x, y) in ((16 + k, 16), (16, 16 + k), (16 + k, 16 + k), (16 + k, 16 - k)):
            if (0 <= x < V) and (0 <= y < V):
                v[x, y, 0:1] = C['fc_ice'] if abs(k) > 8 else C['fc_zap']
    v[14:19, 14:19, 0:2] = C['fc_zap_l']  # 芯
    return [('main', v, (0, 0, 0))]


def zap_shadow_fc(name):
    """雷の影（feat 232 `thunder-shadow`。`:` 明青）。**床の焦げに青い放電が走る**形。

    低いが平らではない——放電を 4〜6 ボクセル立ち上げる。ここだけ背があるので、
    見下ろしでも「床の模様」ではなく「何かが起きている」と読める。
    """
    rng = rng_for(name)
    v = np.zeros((V, V, 7), np.int16)
    #! 焦げ（縁を崩した楕円）。
    for x in range(V):
        for y in range(V):
            d = math.hypot(x - 15.5, y - 15.5) + float(rng.uniform(-1.4, 1.4))
            if d < 12.0:
                v[x, y, 0] = C['soot'] if d > 6.5 else C['soot_l']
    #! 放電（芯から外へ折れながら伸びる）。
    for _ in range(int(rng.integers(4, 7))):
        ang = float(rng.uniform(0.0, 6.28))
        x, y = 16.0, 16.0
        z = 1
        for step in range(int(rng.integers(7, 13))):
            xi, yi = int(round(x)), int(round(y))
            if (0 <= xi < V) and (0 <= yi < V) and (0 <= z < 7):
                v[xi, yi, z] = C['fc_zap_l'] if (step % 2) == 0 else C['fc_zap']
            ang += float(rng.uniform(-0.8, 0.8))
            x += math.cos(ang) * 1.4
            y += math.sin(ang) * 1.4
            if rng.random() < 0.45:
                z += 1
    return [('main', v, (0, 0, 0))]


