# ---- 辺境の地の作り替え----
# 接尾辞 `_out` / `_outb` の素材を別のファイルから足す。既存の登録には触らない。
_spec_out = importlib.util.spec_from_file_location('outpost_prefabs', os.path.join(HERE, 'outpost_prefabs.py'))
_outpost = importlib.util.module_from_spec(_spec_out)
_spec_out.loader.exec_module(_outpost)
_outpost.register(globals())
# ---- モリバントの追加（別担当。`morivant_prefabs.py` があれば読む。無ければ何もしない）----
# 町ごとの追加は 1 町 1 ファイル（`<町>_prefabs.py`。あれば読む。無ければ何もしない）。
for _town_module in ('morivant_prefabs', 'telmora_prefabs', 'telmora_stone_prefabs', 'angwil_prefabs', 'zul_prefabs',
                     'frox_prefabs'):
    _town_path = os.path.join(HERE, _town_module + '.py')
    if os.path.exists(_town_path):
        _spec_town = importlib.util.spec_from_file_location(_town_module, _town_path)
        _town_mod = importlib.util.module_from_spec(_spec_town)
        try:
            _spec_town.loader.exec_module(_town_mod)
        except Exception as _town_err:  # noqa: BLE001
            #! 別の担当が書きかけのファイルでも全体を止めない（2026-09-05 に実際に止まった）。
            print('%s: 読めないので飛ばす（%s）' % (_town_module, _town_err), file=sys.stderr)
            continue
        if hasattr(_town_mod, 'register'):
            _town_mod.register(globals())
        else:
            print('%s: register が無いので飛ばす' % _town_module, file=sys.stderr)


def _palette_entries(source_index, names_of, uses=None):
    """**このプレハブだけのパレット**を組む（材質つき）。

    `source_index` … `{このファイルの索引: 登録簿の索引}`（`write_vox` が詰める）
    `names_of`     … `{登録簿の索引: [色の名前, …]}`（別名があるので複数）

    材質は**ここで焼く**。描く側は色から当てるのをやめて、この宣言を読む
    （2026-08-23 に決めた。`hd2d/render/surface_wear.h`）。
    """
    entries = []
    split = []
    for new_index in sorted(source_index):
        old_index = source_index[new_index]
        rgb = PAL[old_index]
        names = names_of.get(old_index, [])
        cls, was_split = pm.material_for_index(names)
        if was_split:
            split.append(names)
        entry = {
            'i': new_index,
            'rgb': '%02X%02X%02X' % (rgb[0], rgb[1], rgb[2]),
            'name': names[0] if names else '',
            'material': pm.material_name(cls),
        }
        #: **その物の中で何に使っているか**（2026-08-23 に決めた）。組み立ての註釈から。
        note = ''
        for candidate in names:
            found = (uses or {}).get(candidate) or []
            if found:
                note = ' / '.join(found[:2])
                break
        if not note:
            #: 用途が書いていなければ、**色そのものの註釈**で補う（「錆びた鉄（門扉・柵）」）。
            #: ここも見出しらしいものだけ——説明文を持たせると読む人が選り分ける羽目になる。
            for candidate in names:
                found = pm.first_clause(pm.read_comments().get(candidate) or '')
                if found and pm.looks_like_a_use(found):
                    note = found
                    break
        if note:
            entry['use'] = note[:60]
        entries.append(entry)
    return entries, split


def main(argv):
    names = argv[1:] if len(argv) > 1 else sorted(CATALOG.keys())
    unknown = [n for n in names if n not in CATALOG]
    if unknown:
        print('目録に無い名前: %s' % ' '.join(unknown))
        return 1
    names_of = pm.names_by_index(C)
    uses_cache = {}
    split_seen = []
    for name in names:
        builder, parts_decl, note = CATALOG[name]
        parts = builder(name)
        #: **どの色を何に使ったか**は組み立て関数ごとに同じなので 1 度だけ掘る。
        if builder.__name__ not in uses_cache:
            uses_cache[builder.__name__] = pm.mine_uses(builder)
        source_index = {}
        size = write_vox(os.path.join(OUT_DIR, name + '.vox'), parts, PAL, source_index_out=source_index)
        entries, split = _palette_entries(source_index, names_of, uses_cache[builder.__name__])
        split_seen.extend(split)
        fp = write_prefab(os.path.join(OUT_DIR, name + '.jsonc'), name, parts, parts_decl,
                          note='%s（tools/voxel/gen_prefabs.py・P10）' % note,
                          palette_entries=entries,
                          hide_unseen_from_above=(name in DIG_DOWN))
        total = sum(int((vol > 0).sum()) for _, vol, _ in parts)
        print('%-16s %-11s voxels=%-7d vox=%7d B  footprint=%d マス'
              % (name, 'x'.join(map(str, parts[0][1].shape)), total, size, len(fp)))
    if split_seen:
        #: **同じ索引に材質の違う別名が乗っている**（`C['kawara'] = C['obs']` の類）。
        #: 直すなら片方を `reg_local` で独立させること——別名のままでは分けられない。
        uniq = sorted({' / '.join(ns) for ns in split_seen})
        print('材質の割れた別名が %d 組:' % len(uniq))
        for line in uniq:
            print('  ' + line)
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
